insert into public.bible_verses (translation_id, book_id, chapter, verse, text)
values
('kam', 'JER', 43, 3, 'ĩndĩ Mbaluku mwana wa Nelia nĩwe ũnũũkũthing’ĩĩsya ĩũlũ waitũ, ũtũnengane mokonĩ ma Akalitei, matũae, na kũtũtwaa twĩ atave Mbaviloni.'),
('kam', 'JER', 43, 4, 'Kwondũ wa ũu Yoanani mwana wa Kalea, na makavuteni onthe ma asikalĩ, na andũ onthe, matyaaĩthukĩĩsya wasya wa Yeova, matũe nthĩ ya Yuta.'),
('kam', 'JER', 43, 5, 'Ĩndĩ Yoanani mwana wa Kalea, na makavuteni onthe ma asikalĩ, moosa ũtialo w’onthe wa Yuta, ala maĩ manasyoka kuma mbaĩnĩ syonthe vala malũngĩlĩĩlw’e, mekale ũeni nthĩ ya Yuta;'),
('kam', 'JER', 43, 6, 'aũme, na aka, na syana, na eĩtu ma mũsumbĩ, na kĩla mũndũ ũla Nevusalatani kavuteni wa nguthu ya asũvĩi watiĩte kwa Ngetalia mwana wa Aikamu, mwana wa Savani; na mwathani Yelemia, na Mbaluku mwana wa Nelia.'),
('kam', 'JER', 43, 7, 'Na malika nthĩ ya Misili; nũndũ matyaaĩw’a wasya wa Yeova: na mavika Tavanesi.'),
('kam', 'JER', 43, 8, 'Nĩvo ĩndĩ ndeto ya Yeova yamũkĩe Yelemia ku Tavanesi, ĩkĩmwĩa,'),
('kam', 'JER', 43, 9, 'Osa mavia manene kw’okonĩ kwaku, ũmavithe nthĩnĩ wa ndaka vala ve kyũmbĩo kya mavali, vala ve ũlikĩlo wa nyũmba ya Valao ku Tavanesi, andũ ma Yuta mene;'),
('kam', 'JER', 43, 10, 'noimea, Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Sisya, ngatũmana na kwosa Nevukatilesa mũsumbĩ wa Mbaviloni, mũthũkũmi wakwa, na kũũngamya kĩvĩla kyake kya ũsumbĩ mavianĩ asu nĩvithĩte; nake akamba ĩeema yake ya kĩũsumbĩ ĩũlũ wamo.'),
('kam', 'JER', 43, 11, 'Na akooka na kũkũna nthĩ ya Misili; ala ma kĩkw’ũ, kĩkw’ũnĩ; na ala ma kũtavwa mũtavonĩ, na ala ma ũvyũ, ũvyũnĩ.'),
('kam', 'JER', 43, 12, 'Na ngakwatya mwaki nyũmba sya ngai sya Misili; nake akaivĩvya, na akaitava mũtavo: na akeevw’ĩka nthĩ ya Misili, o tondũ mũĩthi wĩvw’ĩkaa ngũa yake; na akauma kw’o na mũuo.'),
('kam', 'JER', 43, 13, 'O na akaitũlanga ituĩ sya Mbethisemesi, ĩla yĩ nthĩ ya Misili; na nyũmba sya ngai sya Misili akavĩvya na mwaki.'),
('kam', 'JER', 44, 1, 'Ndeto ĩla yamũkĩe Yelemia ũndũ wa Ayuti onthe ala matwĩe nthĩ ya Misili, ala matwĩe Mikitoli, na Tavanesi, na Memivisi, na nthĩ ya Vathilosi, ĩkyasya,'),
('kam', 'JER', 44, 2, 'Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Inyw’ĩ nĩmwonete ũthũku w’onthe ũla naeteie Yelusaleme, na ndũa syonthe sya Yuta; na, sisya, ũmũnthi nĩ maanzo, na vai mũndũ ũtwĩe nthĩnĩ wasyo.'),
('kam', 'JER', 44, 3, 'Nũndũ wa ũthũku woo ũla meekie manthatye, ũndũ wa kũthi kũtoeesya ũvani, na kũthũkũma ngai ingĩ, ila mataamanya, mo, kana inyw’ĩ, kana aaĩthe menyu.'),
('kam', 'JER', 44, 4, 'Ĩndĩ nĩnatũmie kwenyu athũkũmi makwa onthe athani, ngyũkĩla tene na ngĩmatũma, ngyasya, Ame, mũtikeke ũndũ ũũ wa ũthatyo ũla nĩmenaa.'),
('kam', 'JER', 44, 5, 'Ĩndĩ matyaaĩthukĩĩsya, kana kũtea matũ moo methyũũe na kũtia ũthũku woo, matikatoeesye ngai ingĩ ũvani.'),
('kam', 'JER', 44, 6, 'Kwondũ wa ũu kũthilĩka kwakwa na ũthatu wakwa syoonoiw’e, na kwakana ndũanĩ sya Yuta na nzĩanĩ nene sya Yelusaleme; nasyo nĩ mbanangĩku na ikatw’ĩka maanzo, o ũndũ kũilyĩ ũmũnthĩ.'),
('kam', 'JER', 44, 7, 'Yu kwondũ wa ũu Yeova Ngai wa nguthu, Ngai wa Isilaeli, easya: Nũndũ wa kĩ mũkwĩka mathayũ menyu ũthũku ũũ mũnene, kũveta kwenyu mũndũ mũũme na mũndũ mũka, kana na kaũkenge, maumw’e katĩ wa Yuta, mũikatiwe na mũndũ o na ũmwe;'),
('kam', 'JER', 44, 8, 'kwondũ wa ũnthatya na mawĩa ma moko menyu, mũkĩtoeesya ngai ingĩ ũvani nthĩ ya Misili, vala mwaendie kwĩkala ũeni; nĩ kana mũvetwe, na mwĩthĩwe kĩumo na ma kũvũthw’a katĩ wa mbaĩ syonthe sya nthĩ?'),
('kam', 'JER', 44, 9, 'Nĩmũlĩtwe nĩ ũthũku wa aaĩthe menyu, na ũthũku wa asumbĩ ma Yuta, na ũthũku wa iveti syoo na ũthũku wenyu ene, na ũthũku wa iveti syenyu, ũla meekĩe nthĩ ya Yuta, na nzĩanĩ nene sya Yelusaleme?'),
('kam', 'JER', 44, 10, 'Matyaaĩnyivya kũvika mũnthĩ ũũ, o na matyaakĩa, kana kũendaa mĩaonĩ yakwa, kana myamũlonĩ yakwa, ĩla naiie mbee wenyu na mbee wa aaĩthe menyu.'),
('kam', 'JER', 44, 11, 'Kwondũ wa ũu Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Sisya, ngamũlutĩla ũthyu wakwa nĩmwĩke ũthũku, o kũveta Yuta onthe.'),
('kam', 'JER', 44, 12, 'Na ngoosa ũtialo wa Yuta, ala meelekelye mothyũ moo maende nthĩ ya Misili kwĩkala ũeni kw’o, na onthe makaminwa; makavalũka nthĩ ya Misili; makaminwa na ũvyũ, na yũa; makakw’a kuma ũla mũnini kũvika ũla mũnene mbee, makyũawa na ũvyũ na yũa; na makeethĩwa ma kwĩvĩkwa, na ũseng’yo, na kĩumo, na ma kũvũthw’a.'),
('kam', 'JER', 44, 13, 'Nũndũ ngakũna ala matwĩe nthĩ ya Misili, o tondũ nakũnie Yelusaleme, na ũvyũ, na yũa, na mũimũ;'),
('kam', 'JER', 44, 14, 'o na vai ũmwe wa ũtialo wa Yuta, ala maendie nthĩ ya Misili mekale ũeni kw’o, ũkavonoka kana kũtiala, asyoke nthĩ ya Yuta, ĩla me na mea ma kũmĩsyokea matũe kw’o: nũndũ vai ũmwe ũkasyoka ate o ala makavonoka.'),
('kam', 'JER', 44, 15, 'Nĩvo ĩndĩ aũme onthe ala mesĩ iveti syoo nĩsyatoeesye ngai ingĩ ũvani, na aka onthe ala maũngamie vakuvĩ, ĩkomano ĩnene, o andũ onthe ala matwĩe nthĩ ya Misili, ku Vathilosi, mamũsũngĩie Yelemia, makyasya,'),
('kam', 'JER', 44, 16, 'Ũndũ wa ndeto ĩla ũneenete naitũ syĩtwanĩ ya Yeova, tũtikakwĩthukĩĩsya.'),
('kam', 'JER', 44, 17, 'Ĩndĩ tũitĩa kwĩanĩsya kĩla ndeto ĩla yumĩte makanyw’anĩ maitũ, kũmũtoeesya mũsumbĩ mũndũ mũka wa ĩtunĩ ũvani, na kũmwĩtĩa nthembo sya kũnyuwa, o tondũ tweekie, ithyĩ na aaĩthe maitũ, asumbĩ maitũ na anene maitũ me mbee ũsumbĩnĩ, ndũanĩ sya Yuta, na nzĩanĩ nene sya Yelusaleme; nũndũ ĩvinda yĩu twaĩ na lĩu mwingĩ, na twaĩ na mĩĩ mĩseo, na tũtyaaona ũthũku.'),
('kam', 'JER', 44, 18, 'Ĩndĩ kuma twaeka kũtoeesya mũsumbĩ mũndũ mũka wa ĩtunĩ ũvani, na kũmwĩtĩa nthembo sya kũnyuwa, twaaĩwa nĩ syĩndũ syonthe, na kũminwa na ũvyũ na yũa.'),
('kam', 'JER', 44, 19, 'Na yĩla twamũtoeesye mũsumbĩ mũndũ mũka wa ĩtunĩ ũvani, na kũmwĩtĩa nthembo sya kũnyuwa, nĩtwamũseũvĩsye tũmũtũ tũmũthaithe, na kũmwĩtĩa nthembo sya kũnyuwa, tũte na aũme maitũ?'),
('kam', 'JER', 44, 20, 'Nĩvo ĩndĩ Yelemia wamatavisye andũ onthe, aũme na aka, o andũ onthe ala mamũsũngĩie ũu, akĩmakũlya,'),
('kam', 'JER', 44, 21, 'Ũvani ũla mwatoeesye ndũanĩ sya Yuta, na nzĩanĩ nene sya Yelusaleme, inyw’ĩ na aaĩthe menyu, asumbĩ menyu na anene menyu me mbee ũsumbĩnĩ, na andũ ma ĩ nthĩ, Yeova ndaolilikana, na ndwaalika kĩlilikanonĩ kyake?'),
('kam', 'JER', 44, 22, 'Ũndũ Yeova ũtatonya kũmĩangĩsya, nũndũ wa ũthũku wa meko menyu, na nũndũ wa mothatyo ala mwekĩte; kwondũ wa ũu nthĩ yenyu nĩtw’ĩkĩte nthei, na ũseng’yo, na kĩumo, ĩte mũndũ ũmĩtwĩe, o ũndũ ĩilyĩ ũmũnthĩ.'),
('kam', 'JER', 44, 23, 'Nĩkwĩthĩwa nĩmwatoeesye ũvani, na nĩkwĩthĩwa nĩmwamũvĩtanĩsye Yeova, na mũtyaaĩthukĩĩsya wasya wa Yeova, kana kũendaa mĩaonĩ yake, kana myamũlonĩ yake, kana mokũsĩnĩ make; kwondũ wa ũu ũthũku ũũ nĩmũvikĩĩte, o ũndũ kũilyĩ ũmũnthĩ.'),
('kam', 'JER', 44, 24, 'Na ĩngĩ Yelemia amea andũ onthe, na aka onthe, Ĩthukĩĩsyei ndeto ya Yeova, onthe ma Yuta mwĩ nthĩ ya Misili:'),
('kam', 'JER', 44, 25, 'Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya, akĩmwĩa, Inyw’ĩ na iveti syenyu nĩmũneenete na makanyw’a menyu, na kwĩanĩsya na moko menyu, mũkyasya, Tũitĩa kwĩanĩsya mawĩvĩto maĩtũ ala tweevĩtie, tũtoeesye mũsumbĩ mũndũ mũka wa ĩtunĩ ũvani, na kũmwĩtĩa nthembo sya kũnyuwa: lũlũmĩlyai ĩndĩ mawĩvĩto menyu, na mũyĩanĩsya mawĩvĩto menyu.'),
('kam', 'JER', 44, 26, 'Kwondũ wa ũu ĩthukĩĩsyei ndeto ya Yeova, onthe ma Yuta ala mũtwĩe nthĩ ya Misili: Sisya, nĩnĩvĩtĩte na syĩtwa yakwa ĩnene, easya Yeova, atĩ syĩtwa yakwa yitikawetwa ĩngĩ kanyw’anĩ wa mũndũ o na wĩva wa Yuta nthĩ yonthe ya Misili, akyasya, O tondũ Mwĩaĩi Yeova wĩ thayũ.'),
('kam', 'JER', 44, 27, 'Sisya, nĩngũmasyaĩĩsya nĩmeke ũthũku, na ti kũmeka ũseo; na andũ onthe ma Yuta ala me nthĩ ya Misili makaminwa na ũvyũ na yũa, kũvika mathela vyũ.'),
('kam', 'JER', 44, 28, 'Na ala mevonoka ũvyũnĩ makasyoka nthĩ ya Yuta kuma nthĩ ya Misili, me avũthũ mũno ũtalonĩ woo, na ũtialo w’onthe wa Yuta, ala maendie nthĩ ya Misili kwĩkala ũeni kw’o makamanya nĩ ndeto yaũ ĩla yĩungama, yakwa, kana yoo.'),
('kam', 'JER', 44, 29, 'Na ũũ ũkeethĩwa ũvano kwenyu, easya Yeova, kana ngamũkũnĩa vandũ vaa mũmanye kana ndeto syakwa iitĩa kũũngama ĩũlũ wenyu ũndũ wa ũthũku:'),
('kam', 'JER', 44, 30, 'Ũũ nĩw’o Yeova ũnũkwasya, Sisya, ngamũnengane Valao Ovila mũsumbĩ wa Misili mokonĩ ma amaitha make, na mokonĩ ma ala mamanthaa thayũ wake; o tondũ nanenganie Nzetekia mũsumbĩ wa Yuta kw’okonĩ kwa Nevukatilesa mũsumbĩ wa Mbaviloni, ũla waĩ mũmaitha wake, na nĩwamanthaa thayũ wake.'),
('kam', 'JER', 45, 1, 'Ndeto ĩla mwathani Yelemia watavisye Mbaluku mwana wa Nelia yĩla waandĩkie ndeto ii ĩvukunĩ kuma kanyw’anĩ wa Yelemia mwaka wa kana wa kũsumbĩka kwa Yeoiakimu mwana wa Yosia, mũsumbĩ wa Yuta, ĩkĩmwĩa,'),
('kam', 'JER', 45, 2, 'Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũũkũtavya, we Mbaluku:'),
('kam', 'JER', 45, 3, 'We nĩwaisye, Woo nĩ wakwa yu! Nũndũ Yeova nĩwongeleele kwalw’a kĩmako; nĩ na mĩnoo ũndũ wa kũluma kwakwa, na ndikwona ũthũmũo.'),
('kam', 'JER', 45, 4, 'Ũkamwĩa atĩĩ, Ũũ nĩw’o Yeova ũnũkwasya: Sisya, kĩla nakĩte ngaomboa, na kĩla nĩvandĩte ngakũa; na ta ũu nthĩ yonthe.'),
('kam', 'JER', 45, 5, 'Nũkwĩmanthĩa maũndũ manene? Ndũkamamanthe; nũndũ, sisya, ngatee mĩĩ yonthe ũthũku, easya ũu Yeova; ĩndĩ thayũ waku, ngakũnenga wĩthĩwe mũtavo kũndũ kw’onthe kũla wĩendaa.'),
('kam', 'JER', 46, 1, 'Ndeto ya Yeova ĩla yamũkĩe mwathani Yelemia ũndũ wa i mbaĩ.'),
('kam', 'JER', 46, 2, 'Ũndũ wa Misili: ũndũ wa ita sya Valao‐neko mũsumbĩ wa Misili, ila syaĩ vakuvĩ na ũsĩ wa Euvalati ndũanĩ ya Kalikemisi, ĩla Nevukatilesa mũsumbĩ wa Mbaviloni wakũnie mwaka wa kana wa kũsumbĩka kwa Yoiakimu mwana wa Yosia, mũsumbĩ wa Yuta.'),
('kam', 'JER', 46, 3, 'Seũvyai kakalo na ngao, na mũithengeea kaũnĩ.'),
('kam', 'JER', 46, 4, 'Tandĩkai mbalasi, na mũitũla, inyw’ĩ aũme ala mũtũlaa mbalasi, na mũiũngama mwĩ na ngovia syenyu; kutai matumo, ĩkĩai tũkoti twa iaa.'),
('kam', 'JER', 46, 5, 'Nĩonea ũndũ ũũ kĩ? Nĩmeũteva na kũsyoka na ĩtina; na ala moo me ũtonyi nĩmavalũkĩtw’e, nao makĩĩte mĩtũkĩ, na matiũsisya na ĩtina: ũtĩsyo wĩ ngalĩ syonthe, easya ũu Yeova.'),
('kam', 'JER', 46, 6, 'Ũla wĩ mĩtũkĩ ya kũsemba ndakasembekye, kana ngũmbaũ ndĩkavonoke; nĩmalulutĩkile na kũvalũka ngalĩ ya ĩũlũ vakuvĩ na ũsĩ wa Euvalati.'),
('kam', 'JER', 46, 7, 'Ũũ nũũ ũla wũkĩlaa ta ũsĩ wa Naelo, ũla manzĩ maw’o meyũkĩlangasya ta mbũsĩ?'),
('kam', 'JER', 46, 8, 'Misili nĩyũkĩlaa ta Naelo, na manzĩ mayo nĩmeyũkĩlangasya ta mbũsĩ: nake easya, Ngookĩla, ngavw’ĩka nthĩ; ngaananga ndũa na ala maitwĩe.'),
('kam', 'JER', 46, 9, 'Ambatai, inyw’ĩ mbalasi; na sembai ta mwĩ na ndũũka, inyw’ĩ makasya ma kaũ; na ngũmbaũ syume: Kusi na Vutu, ala makwataa ngao; na Aluti, ala makwataa na kũkoota ũta.'),
('kam', 'JER', 46, 10, 'Nũndũ mũthenya ũsu nĩ mũthenya wa Mwĩaĩi, Yeova wa nguthu, mũthenya wa kwĩĩvanĩsya, nĩ kana eĩvanĩsye ũndũ wa nthũ syake: na ũvyũ ũkaya na kũvũna, na ũkanyw’a nthakame yoo ũkole; nũndũ Mwĩaĩi, Yeova wa nguthu, e na nthembo nthĩ yĩ ngalĩ ya ĩũlũ vakuvĩ na ũsĩ wa Euvalati.'),
('kam', 'JER', 46, 11, 'Ambata ũende ku Ngileati, noyosa seli, we mwĩĩtu mũtheu wa Misili: nũkwĩtethya na mĩtĩ mingĩ mana; vati kũvow’a kwaku.'),
('kam', 'JER', 46, 12, 'Mbaĩ nĩsyĩw’ĩte ũvoo wa nthoni syaku, na nthĩ nĩyusũĩte kĩĩo kyaku; nũndũ ngũmbaũ nĩlulutĩkĩle ngũmbaũ, nivalũkĩte syelĩ vamwe.'),
('kam', 'JER', 46, 13, 'Ndeto ĩla Yeova wamũtavisye mwathani Yelemia, ũndũ Nevukatilesa mũsumbĩ wa Mbaviloni ũkoka na kũkũna nthĩ ya Misili.'),
('kam', 'JER', 46, 14, 'Tavan’yai Misili, na mũinyaĩĩkya Mikitoli, na mũinyaĩĩkya Memivisi na Tavanesi: asyai, Ũngama, noyĩyũmban’ya; nũndũ ũvyũ nũĩte ngalĩ syaku syonthe.'),
('kam', 'JER', 46, 15, 'Ala maku me vinya matwaĩtwe nĩkĩ? Matyaaũngama, nĩkwĩthĩwa Yeova nĩwamalũngilye.'),
('kam', 'JER', 46, 16, 'Nĩwamalũlũtĩkilye aingĩ, ĩĩ, nĩmavalũkile ũmwe ĩũlũ wa ũla ũngĩ: nao masya, Ũkĩlai, tũende ĩngĩ kwa andũ maitũ, na nthĩ ĩla twasyaĩwe, tũkĩe ũvyũ ũla ũtũthĩnasya.'),
('kam', 'JER', 46, 17, 'Nĩmaneenie na wasya mũnene kw’o, Valao mũsumbĩ wa Misili nĩ kĩlonzo kĩthei; nĩwaekie ĩvinda yĩtw’ĩtwe yĩvĩte.'),
('kam', 'JER', 46, 18, 'O tondũ nĩ thayũ, easya Mũsumbĩ, ũla syĩtwa yake nĩ Yeova wa nguthu, vate ndĩi o ta Tavoli katĩ wa iĩma, na ta Kalimeli ũtee wa ũkanga, now’o ũkoka.'),
('kam', 'JER', 46, 19, 'We mwĩĩtu ũla wĩkalaa Misili, ĩseũvĩsye mĩio ya kũthi nayo wĩ mũtave; nũndũ Memivisi ĩkatw’ĩka ĩanzo, ĩte mũndũ ũmĩtũa, na ĩkavĩvw’a.'),
('kam', 'JER', 46, 20, 'Misili nĩ moi nzeo mũno; ĩndĩ wanangĩko wũmĩte ngalĩ ya ĩũlũ nĩ mũku, nĩ mũku.'),
('kam', 'JER', 46, 21, 'O na andũ mayo ala matuvawa mailyĩ katĩ wayo ta tũsaũ twa kĩtũũ; nũndũ nao nĩmasyokete na ĩtina, nĩmakĩĩte vamwe, matyaaũngama: nũndũ mũthenya wa wanangĩko woo nũmavikĩe, ĩvinda ya kũsilĩlwa kwoo.'),
('kam', 'JER', 46, 22, 'Wasya wayo ũkanyoloka ta nzoka; nũndũ makaenda na ita, na kũmyũkĩa na mathoka, ta ala maunaa ngũ.'),
('kam', 'JER', 46, 23, 'Makatema mũtitũ wayo, easya Yeova, nũndũ ndũmanthĩka; nĩkwĩthĩwa nĩ aingĩ kwĩ ngie, maitalĩka.'),
('kam', 'JER', 46, 24, 'Mwĩĩtu wa Misili akasonokw’a; akanenganwe mokonĩ ma andũ ma ngalĩ ya ĩũlũ.'),
('kam', 'JER', 46, 25, 'Yeova wa nguthu, Ngai wa Isilaeli, easya: Sisya, ngakũna Amoni wa ndũa ya No, na Valao, na Misili, vamwe na ngai syayo, na asumbĩ mayo; o Valao, na ala mamwĩkwatasya:'),
('kam', 'JER', 46, 26, 'na ngamanengane mokonĩ ma ala mamanthaa mathayũ moo, na kw’okonĩ kwa Nevukatilesa mũsumbĩ wa Mbaviloni, na kw’okonĩ kwa athũkũmi make; na ĩtina wa ũu ĩkatũwa nĩ andũ, o ta mĩthenya ya tene, easya ũu Yeova.'),
('kam', 'JER', 46, 27, 'Ĩndĩ ndũkakĩe, we Yakovo mũthũkũmi wakwa, o na ndũkateve, Isilaeli: nũndũ, sisya, ngakũtangĩĩa wume kũasa, na ũsyao waku kuma nthĩ ĩla watwaiwe wĩ mũtave; na Yakovo akasyoka, na akausya na kũthũmũa, na vai ũla wĩmũtĩsya.'),
('kam', 'JER', 46, 28, 'Ndũkakĩe, we Yakovo mũthũkũmi wakwa, easya ũu Yeova; nũndũ nĩ vamwe naku: nũndũ ngaimina vyũ mbaĩ syonthe vala nakũlũngĩlĩĩlye; ĩndĩ ndikakũmina vyũ, ĩndĩ ngakũkan’ya nĩthimĩte, na ndikatĩa ũkũkũna.'),
('kam', 'JER', 47, 1, 'Ndeto ya Yeova ĩla yamũkĩe mwathani Yelemia ũndũ wa Avilisiti, Valao atanamba kũkũna Ngasa.'),
('kam', 'JER', 47, 2, 'Ũũ nĩw’o Yeova ũnũkwasya: Sisya, manzĩ nĩmekũkĩla ngalĩ ya ĩũlũ, na makatw’ĩka ũsĩ ũvingĩte ũkakĩla, na makavw’ĩka nthĩ na kyonthe kĩ nthĩ, ndũa na ala mamĩtũaa; na andũ makaĩa, na onthe ala matwĩe nthĩ makakaya.'),
('kam', 'JER', 47, 3, 'Kwondũ wa matuu ma kũkinyanga kwa mavũngũ ma ila syake syĩ vinya, kwondũ wa kũsemba kwa makasya make, na kwondũ wa kĩlonzo kya ndĩa syamo, aaĩthe matĩũsisya ĩtina kũsisya syana syoo nũndũ moko moo mati vinya;'),
('kam', 'JER', 47, 4, 'nũndũ wa mũthenya ũla wũkĩte wa kwananga Avilisiti onthe, kũveta kuma Tile na sitoni kĩla mũtethya ũtialĩtw’e: nũndũ Yeova akaananga Avilisiti, ũtialo wa kĩthama kya Kavitoli.'),
('kam', 'JER', 47, 5, 'Ũvaa nĩwũkĩte ndũanĩ ya Ngasa; Asikeloni nĩ mbanangĩku vyũ, nayo nĩ ũtialo wa mwanda woo: ũkeetemanga kũvika ĩndĩĩ?'),
('kam', 'JER', 47, 6, 'We ũvyũ wa Yeova, kũkeethĩwa ĩvinda yĩana ata kũvika yĩla wĩvindya? Ĩtũngĩe ndoonĩ yaku; thũmũa, noivindya.'),
('kam', 'JER', 47, 7, 'Ũtonya kũvindya ata, nũndũ Yeova nũkũnengete wĩaĩo? Ĩũlũ wa Asikeloni, na ĩũlũ wa ũkanga ũtee, nĩ vo waũtw’ĩĩe.'),
('kam', 'JER', 48, 1, 'Ũvoo wa Moavi. Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Woo nĩ wa Nevo! Nũndũ nĩtw’ĩkĩthĩtw’e ĩanzo; Kiliathaimu nĩkũsonokw’a, nĩ ngwate; Misikavu nĩkũsonokw’a na kũombowa.'),
('kam', 'JER', 48, 2, 'Ndaĩa ya Moavi vatiĩ, nthĩnĩ wa Esivoni nĩmasũanĩĩte kũmĩka ũthũku: Ũkai, tũmĩvete ndĩkethĩwe mbaĩ. O naku, we Matimeni, ũkavindĩthw’a; ũvyũ ũkakũatĩĩa.'),
('kam', 'JER', 48, 3, 'Wasya wa kĩĩo kuma Olonaimu, wau na wanangĩko mũnene!'),
('kam', 'JER', 48, 4, 'Moavi nĩ mbanangĩku; twana twayo tũnini nĩtwatumie kĩĩo kĩw’ĩka.'),
('kam', 'JER', 48, 5, 'Nũndũ makambata kyambatonĩ kya Luithi makĩĩa mavinda onthe; nũndũ kĩtheeonĩ kya Olonaimu nĩmew’ĩte thĩna wa kĩĩo ũndũ wa wanangĩko.'),
('kam', 'JER', 48, 6, 'Kĩai, tangĩĩai mathayũ menyu, na mũyĩthĩwa ta mũtĩ weũnĩ mwĩtĩku matũ.'),
('kam', 'JER', 48, 7, 'Ĩndĩ, nĩkwĩthĩwa nĩweekwatisye mawĩa maku na ũthwii waku mwie, we naku ũkakwatwa: na ĩla ngai Kemosi ĩkatwawa ĩ ndave, athembi mayo na anene mayo vamwe.'),
('kam', 'JER', 48, 8, 'Na mwanangi akamyũkĩa kĩla ndũa, na ndũa o na ĩmwe ndĩkavonoka; mwanda naw’o ũkaanangĩka, na ũiĩ ũkaanangwa; o tondũ Yeova ũneenete.'),
('kam', 'JER', 48, 9, 'Nenga Moavi nthwau, nĩ kana aũlũke na kũthi kũasa: na ndũa syake ikatw’ĩka maanzo, ite mũndũ wa kwitũa.'),
('kam', 'JER', 48, 10, 'Naumanĩwe ũla ũtethasya wĩa wa Yeova ate na kĩthito; na naumanĩwe ũla ũsiĩĩa ũvyũ wake ndũkethĩwe na nthakame.'),
('kam', 'JER', 48, 11, 'Moavi nũthũmũĩte kuma wana wake, nĩwĩkalĩte kĩmongoyonĩ kyake, ndaakelwa kuma kĩndũnĩ kĩmwe kwĩkĩwa kĩndũnĩ kĩngĩ, o na ndaaenda e mũtave: kwondũ wa ũu ũsamo wake nĩwĩkalĩte nthĩnĩ wake, na mũuke wake ti mũalyũku.'),
('kam', 'JER', 48, 12, 'Kwondũ wa ũu, sisya, mĩthenya nĩyũkĩte, easya Yeova, ĩla ngatũma kwake ala makelaa, na makamũkela; nao makatulũla mĩio yake, na kũaa masũva moo ilungu.'),
('kam', 'JER', 48, 13, 'Na Moavi akasonoka nũndũ wa Kemosi, o tondũ nyũmba ya Isilaeli yasonokie ũndũ wa Mbethi‐eli, wĩkwatyo woo.'),
('kam', 'JER', 48, 14, 'Mwĩasya ata, Ithyĩ twĩ andũ me ũtonyi na ngũmbaũ kwondũ wa kaũ?'),
('kam', 'JER', 48, 15, 'Moavi nĩtw’ĩkĩthĩtw’e ĩei, na nĩmambatĩte ndũanĩ syake, na anake make anyuve nĩmatheeete kũawa, easya Mũsumbĩ, ũla syĩtwa yake nĩ Yeova wa nguthu.'),
('kam', 'JER', 48, 16, 'Wanangĩko wa Moavi ũkĩlilye kũka, na ũnyamao wake nĩwĩkalaatĩte mũno.'),
('kam', 'JER', 48, 17, 'Inyw’onthe ala mũmũthyũlũlũkĩte mũmeteei, na inyw’onthe ala mwĩsĩ syĩtwa yake; asyai, Ndata yĩ vinya ko nĩyatũlĩkaa, ndata nzeo mũno!'),
('kam', 'JER', 48, 18, 'We mwĩĩtu ũla ũtwĩe Ndivoni, theea kuma ũnenenĩ waku, noiĩkala na waũni; nũndũ mwanangi wa Moavi nũkũkĩe, nĩwanangĩte ngome syaku syĩ vinya.'),
('kam', 'JER', 48, 19, 'We ũla ũtwĩe Aloeli, ũngama ũtee wa nzĩa, noisyaĩĩsya: kũlya mũndũ mũũme ũla ũnũũsemba, na mũndũ mũka ũla ũnũũvonoka; asya, Kwĩkĩkie ata?'),
('kam', 'JER', 48, 20, 'Moavi nĩkũsonoka; nũndũ nĩomboetwe: kayai na kũĩa; tavan’yai ku ũtee wa ũsĩ wa Alinoni, atĩ Moavi nĩyanangĩtwe.'),
('kam', 'JER', 48, 21, 'Na ũsilĩlo nĩ mũku ĩũlũ wa nthĩ yĩ ũiĩ, ĩũlũ wa Oloni, na Yasa, na Mevaathi,'),
('kam', 'JER', 48, 22, 'na Ndivoni, na Nevo, na Mbethindivilathaimu,'),
('kam', 'JER', 48, 23, 'na Kiliathaimu, na Mbethi‐ngamuli, na Mbethi‐meoni,'),
('kam', 'JER', 48, 24, 'na Keliothi, na Mbosila, na ndũa syonthe sya nthĩ ya Moavi, ila syĩ kũasa na ila syĩ vakuvĩ.'),
('kam', 'JER', 48, 25, 'Ũvya wa Moavi nĩ mũtile, na kw’oko kwake nĩ kũtilĩku, easya ũu Yeova.'),
('kam', 'JER', 48, 26, 'Mũtoonethyei; nũndũ nĩwenenevesye Yeova: na Moavi akeeyalalya matavĩkanĩ make, nake akathekeewa.'),
('kam', 'JER', 48, 27, 'Nũndũ Isilaeli ndaĩ ntheko kwaku? Nĩwonekie katĩ wa ing’ei? Nũndũ o yĩla ũũmũweta, nũthingithasya mũtwe.'),
('kam', 'JER', 48, 28, 'Inyw’ĩ ala mũtwĩe Moavi, umai ndũanĩ, mũtũe ĩvianĩ; ĩthĩwai ta ĩvũĩ yĩla yakaa ndala yayo ngũkanĩ ya ĩtw’ĩku.'),
('kam', 'JER', 48, 29, 'Nĩtwĩw’ĩte ũvoo wa ngathĩĩo ya Moavi, atĩ e na ngathĩĩo mũno; kwĩyũkĩlya kwake, na ngathĩĩo yake, na wĩnenevyo wake, na wĩng’athĩlĩlyo wa ngoo yake.'),
('kam', 'JER', 48, 30, 'Nĩnĩsĩ ũthilĩku wake, easya Yeova, kana ti kĩndũ; mĩtũlyo yake ndĩkĩte ũndũ nongi.'),
('kam', 'JER', 48, 31, 'Kwondũ wa ũu ngametea Moavi; ĩĩ, ngaĩa ũndũ wa Moavi onthe: makametea andũ ma Kili‐elesi.'),
('kam', 'JER', 48, 32, 'Ngakũĩĩa na kĩĩo kĩvĩtũkĩte kĩĩo kya Yaseli, we mũsavivũ wa Sivima: mbonge syaku nikĩlĩte ũkanga, syavika o ũkanganĩ wa Yaseli: mwanangi nũmavalũkĩle mosyao maku ma ĩvinda ya syũa na ngetha yaku ya nzavivũ.'),
('kam', 'JER', 48, 33, 'Ũtanu na mũyo nĩsyumĩtw’e mũũndanĩ wĩ na ũsyao, o na nthĩ ya Moavi; na nĩnaekethya mbinyu iangionĩ sya nzavivũ; vai ũmwe ũkakinyanga na wasya mũnene; wasya mũnene ndũkethĩwa wĩ wasya mũnene.'),
('kam', 'JER', 48, 34, 'Nĩmaumĩtye wasya woo kuma kĩĩonĩ kya Esivoni o kũvika Eleale, o kũvĩka Yaasa, kuma Nzoali kũvika Olonaimu, kũvika Ekilathi‐selisiya: nũndũ manzĩ namo ma Nimilimu makeethĩwa mang’alĩte.'),
('kam', 'JER', 48, 35, 'Na ĩngĩ, easya Yeova, Ngamũekethya nthĩnĩ wa Moavi, ũla ũthembeaa kũndũ kũtũlu, na ũla ũtoeeasya ngai syake ũvani.'),
('kam', 'JER', 48, 36, 'Kwondũ wa ũu ngoo yakwa nĩnĩkumya wasya ta mĩtũlilũ kwondũ wa Moavi, na ngoo yakwa nĩnĩkumya wasya ta mĩtũlilũ ũndũ wa andũ ma Kili‐elesi: kwondũ wa ũu wingĩ ũla weyũmbanĩsye nĩ mwau.'),
('kam', 'JER', 48, 37, 'Nũndũ kĩla mũtwe wĩ ũvaa, na kĩla kĩng’ew’a nĩ kĩtile: na moko onthe nĩmatw’ĩtwe nthoo, na inyunyu nivotoetwe makunia.'),
('kam', 'JER', 48, 38, 'Ĩũlũ wa nyũmba syonthe sya Moavi na nzĩanĩ nene syayo ve kĩĩo kĩla vandũ; nũndũ nĩnũaĩte Moavi ta mũio ũtatanĩwa nĩ mũndũ, easya ũu Yeova.'),
('kam', 'JER', 48, 39, 'Ko nĩomboetwe! Ko nĩmekũmeta! Moavi ko nĩyonanĩtye mũongo nĩ nthoni! O ta ũu Moavi akatw’ĩka ntheko na ũtĩsyo kwa onthe ala mamĩthyũlũlũkĩte.'),
('kam', 'JER', 48, 40, 'Nũndũ ũu nĩw’o Yeova ũnũkwasya: Sisya, akaũlũka ta ndiũ, na kũtambũũkĩsya Moavi nthwau syake.'),
('kam', 'JER', 48, 41, 'Keliothi nĩ mbose, na ngome syĩ vinya nikwatĩtwe, na mũthenya ũsu ngoo sya ngũmbaũ sya Moavi ikethĩwa ta ngoo ya mũndũ mũka akyaũnya.'),
('kam', 'JER', 48, 42, 'Na Moavi akaanangwa ndakethĩwe ũko wa andũ, nĩkwĩthĩwa nĩwamwĩnenevesye Yeova.'),
('kam', 'JER', 48, 43, 'W’ĩa, na ĩima, na kĩtei, nĩkũkwatĩte, we ũla ũtwĩe Moavi, easya ũu Yeova.'),
('kam', 'JER', 48, 44, 'Ũla ũsembaa akĩĩte w’ĩa ũsu akavalũka ĩimanĩ; na ũla wĩyumya ĩimanĩ akakwatw’a nĩ kĩtei: nũndũ ngamũetee, o Moavi, mwaka wa kũsilĩlwa kwoo, easya ũu Yeova.'),
('kam', 'JER', 48, 45, 'Ala makĩie nĩmaũngeme mate vinya muunyĩnĩ wa Esivoni; nũndũ mwaki nĩwumĩte Esivoni, na ũlĩlĩnzĩ kuma Sioni katĩ, na nĩwanangĩte kĩkoto kya Moavi, na lolotya wa mũtwe wa ala meũlonzan’ya.'),
('kam', 'JER', 48, 46, 'Woo nĩ waku, we Moavi! Andũ ma Kemosi nĩmaĩte; nũndũ ana maku nĩmatwaiwe me atave, o na eĩtu maku me o atave.'),
('kam', 'JER', 48, 47, 'Ĩndĩ ngatũnga Moavi aume kũtavwanĩ mĩthenya ya mũminũkĩlyo, easya ũu Yeova. Kũvika vau nĩ ũsilĩlo wa Moavi.'),
('kam', 'JER', 49, 1, 'Ũvoo wa ana ma Amimoni. Ũũ nĩw’o Yeova ũnũkwasya: Isilaeli nde na ana? Nde na mũtiĩwa? Nũndũ wa kĩ ĩndĩ ĩla ngai Malikamu ĩnĩũtiĩwa Ngati, na andũ make matũaa ndũanĩ syayo?'),
('kam', 'JER', 49, 2, 'Kwondũ wa ũu, sisya, mĩthenya nĩyũkĩte, easya Yeova, ĩla ngatuma mbu ya kaũ yĩw’ĩka ĩũlũ wa ndũa ya Lava ya ana ma Amimoni; na ĩkatw’ĩka kĩvumbu kĩthei, na eĩtu make makavĩvw’a na mwaki: nĩvo Isilaeli akamosa ala mamwosete, easya ũu Yeova.'),
('kam', 'JER', 49, 3, 'Meta, we Esivoni, nũndũ Ai nĩtw’ĩkĩthĩtw’e ĩanzo; ĩai, inyw’ĩ eĩtu me Lava, ĩvotoei makunia: metai, noisemba kũũ na kũũ katĩ wa mbiio; nũndũ ĩla ngai Malikamu ĩkatwawa ĩ ndave, athembi mayo na anene mayo vamwe.'),
('kam', 'JER', 49, 4, 'Nũndũ wa kĩ wĩkathĩĩa ũndũ wa myanda, mwanda waku ũla ũvĩtĩtye manzĩ, we mwĩĩtu ũla wasyokie na ĩtina? Ũla wekwatĩtye ũthwii wake mwie, akyasya, Nũũ ũla wĩmbũkĩa?'),
('kam', 'JER', 49, 5, 'Sisya, ngakũetee w’ĩa, easya Mwĩaĩi, Yeova wa nguthu, kuma andũnĩ onthe ala makũthyũlũlũkĩte; na mũkalũngĩlĩĩlw’a kĩla mũndũ kũasa mũno, na vatikethĩwa mũndũ wa kũmban’ya akĩi.'),
('kam', 'JER', 49, 6, 'Ĩndĩ ĩtina ngatũnga ana ma Amimoni maume kũtavwanĩ, easya ũu Yeova.'),
('kam', 'JER', 49, 7, 'Ũvoo wa Etomu. Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Vati ũĩ ĩngĩ Temani? Ũtao nĩwaĩte kwa ala me kĩlĩko? Ũĩ woo nĩ mũthelu?'),
('kam', 'JER', 49, 8, 'Kĩai, syokai, na mũyĩkala kũndũ kũliku mũno, inyw’ĩ ala mũtwĩe Ndetani; nũndũ ngamũetee wanangĩko wa Esau, ĩvinda yĩla ngamũsilĩla.'),
('kam', 'JER', 49, 9, 'Ethĩwa atwi ma nzavivũ makakũkĩa maikatia nzavivũ sya kũthean’ya? Ethĩwa ing’ei ĩkakũkĩa ũtukũ, itikananga kũvika syavũna?'),
('kam', 'JER', 49, 10, 'Ĩndĩ nĩnĩmũtw’ĩkĩthĩtye Esau mũthei, nĩnĩmũvũĩte kũndũ kwake kwa kĩmbithĩ, na ndakatonya kwĩvitha: ũsyao wake nĩ mwanangĩku, o na ana‐a‐ĩthe make, na atũi make; nake ndavaĩ.'),
('kam', 'JER', 49, 11, 'Tia syana syaku ila syakw’ĩĩwe nĩ aaĩthe, nakwa ngaisũvĩa syĩkale thayũ; na aka maku ndiwa mandĩkĩĩe.'),
('kam', 'JER', 49, 12, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya: Sisya, ala matatw’ĩĩwe kũnyw’a kĩkombe maitĩa kũnyw’a; na nue we ũla ũkatĩa ũkũnwa? Ndũkaekwa ũte mũkũne, ĩndĩ no mũvaka ũnyw’e.'),
('kam', 'JER', 49, 13, 'Nũndũ nyie mwene nĩneevĩtie, easya Yeova, kana Mbosila ĩkatw’ĩka ũseng’yo, na ya kũvũthw’a, na ĩanzo, na kĩumo; na ndũa syonthe syayo ĩkeethĩwa maanzo ĩndĩ yonthe.'),
('kam', 'JER', 49, 14, 'Nĩnĩw’ĩte maũvoo kuma kwa Yeova, na mũtũmwa nũtũmĩtwe katĩ wa mbaĩ, akyasya, Ĩyũmban’yei vamwe, mũmĩendee, ũkĩlai mũkite.'),
('kam', 'JER', 49, 15, 'Nũndũ, sisya, nĩnĩkũtw’ĩkĩthĩtye mũnini katĩ wa mbaĩ, na kũvũthw’a katĩ wa andũ.'),
('kam', 'JER', 49, 16, 'Ũvoonĩ wa ũtĩsyo waku mũnene, ngathĩĩo ya ngoo yaku nĩkũkengete, we ũla wĩkalaa mĩvatĩnĩ ya ĩvia, ũla ũkwete vandũ vatũlu va kĩĩma: o na ethĩwa ũkaaka ndala yaku ĩũlũ ta ndiũ, ngakũtheesya kuma vo, easya ũu Yeova.'),
('kam', 'JER', 49, 17, 'Na Etomu ĩkatw’ĩka ũseng’yo: kĩla mũndũ wĩmĩvĩtĩla akaseng’a, na akamĩtĩmba ũndũ wa mothĩn’yo onthe mayo.'),
('kam', 'JER', 49, 18, 'O tondũ kwailyĩ kũng’uthũlwanĩ kwa Sotomo na Ngomola na ndũa ila syaĩ vakuvĩ nasyo, now’o mũndũ o na wĩva ndakatũa kw’o, o na mwana wa mũndũ o na wĩva ndakekala ũeni kw’o, easya ũu Yeova.'),
('kam', 'JER', 49, 19, 'Sisya, akookĩa wĩkalo wĩ vinya ta mũnyambũ ũindũkĩte kũvinganĩ kwa Yolotani: nũndũ ngamasembya kuma vo na kĩthũlũmũko; na ũla mũnyuve, nĩwe ngaia ĩũlũ wa vo: nũndũ nũũ ũilyĩ takwa? Na nũũ wĩndw’ĩĩa ĩvinda? Na mũĩthi nũũ ũla ũkaũngama mbee wakwa?'),
('kam', 'JER', 49, 20, 'Kwondũ wa ũu ĩthukĩĩsyei ũtw’ĩo wa Yeova, ũla watw’ĩĩe Etomu; na mosũanĩo make ala ũsũanĩĩte kũmeka ala matwĩe Temani: Vate ndĩi makamaumya mamakusĩtye, o na anini ma ndĩthya; vate ndĩi akatw’ĩkĩthya wĩkalo woo ĩanzo vamwe nao.'),
('kam', 'JER', 49, 21, 'Nthĩ nĩnĩkũtetema ũndũ wa kĩlonzo kya kũvalũka kwoo; ve kĩĩo, na kĩlonzo kyakyo nĩkĩkwĩw’ĩka Ũkanganĩ Mũtune.'),
('kam', 'JER', 49, 22, 'Sisya, akambata na kũũlũka ta ndiũ, na kũtambũũkĩsya Mbosila nthwau syake; na mũthenya ũsu ngoo sya ngũmbaũ sya Etomu ikethĩwa ta ngoo ya mũndũ mũka akyaũnya.'),
('kam', 'JER', 49, 23, 'Ũvoo wa Ndamasiku. Amathi nĩnĩũvũavũana, o na Alĩvati; nũndũ nĩsyĩw’ĩte maũvoo mathũku, nitwekete: ve kyeva ũkanganĩ; ndũtonya kũvindya.'),
('kam', 'JER', 49, 24, 'Ndamasiku nĩyaĩte vinya, nĩnĩkwĩthyũũa ĩkĩe, na ĩkwatĩtwe nĩ kũtetema: woo na kyeva nimĩkwatĩte ta mũndũ mũka akyaũnya.'),
('kam', 'JER', 49, 25, 'Ũũ nata ndũa ya ndaĩa ndĩaaekwa, ndũa ya ũtanu wakwa?'),
('kam', 'JER', 49, 26, 'Kwondũ wa ũu anake mayo makavalũka nzĩanĩ syayo nene, na andũ onthe ma kaũ makavindĩthw’a mũthenya ũsu, easya ũu Yeova wa nguthu.'),
('kam', 'JER', 49, 27, 'Nakwa ngakan’ya mwaki ũvainĩ wa Ndamasiku, na ũkavĩvya nyũmba mbanakavye sya Mbene‐aatati.'),
('kam', 'JER', 49, 28, 'Ũvoo wa Ketali, na mosumbi ma Asoli, ala Nevukatilesa mũsumbĩ wa Mbaviloni wakũnie. Ũũ nĩw’o Yeova ũnũkwasya: Ũkĩlai, mwambate Ketali, na kwananga ana ma ngalĩ ya wumĩlonĩ wa syũa.'),
('kam', 'JER', 49, 29, 'Makoosa maeema moo na ndĩthya syoo sya mbũi na malondu; makakua kwondũ woo ene ngũa syoo sya kũtũta, na mĩio yoo yonthe, na ngamĩle syoo; na makaneena na wasya mũnene, makĩmea, Ũtĩsyo ngalĩ syonthe!'),
('kam', 'JER', 49, 30, 'Kĩai, na mũyanganga kũasa, na kwĩkala kũndũ kũliku, inyw’ĩ ala mũtwĩe Asoli, easya ũu Yeova; nũndũ Nevukatilesa mũsumbĩ wa Mbaviloni nũmũsamĩe, na nũmũsũanĩĩte ũndũ.'),
('kam', 'JER', 49, 31, 'Ũkĩlai, mwambate vala ve mbaĩ ĩthũmũĩte, ĩla yĩkalaa ĩte na wĩmakĩo, easya ũu Yeova; ĩla ĩte na mbingĩlo kana ivingi, ila yĩkalaa yĩ yoka.'),
('kam', 'JER', 49, 32, 'Na ngamĩle syoo ikeethĩwa mũtavo, na ĩndo syoo nyingĩ mũtavo: na ngamanyaĩĩkya isevenĩ syonthe ala menzetwe ithũkũ; na ngaete wanangĩko woo kuma ngalĩ syoo syonthe, easya ũu Yeova.'),
('kam', 'JER', 49, 33, 'Na Asoli ĩkeethĩwa wĩkalo wa mbĩwa, ĩanzo tene na tene: mũndũ o na wĩva ndakatũa vo, o na mwana wa mũndũ o na wĩva ndakekala ũeni kw’o.'),
('kam', 'JER', 49, 34, 'Ndeto ya Yeova ĩla yamũkĩe mwathani Yelemia ũndũ wa Elamu, wambĩlĩlyonĩ wa kũsumbĩka kwa Nzetekia mũsumbĩ wa Yuta, ĩkyasya,'),
('kam', 'JER', 49, 35, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Sisya, ngatũla ũta wa Elamu, mũnene wa vinya woo.'),
('kam', 'JER', 49, 36, 'Na ngaetee Elamu iseve inya kuma ikotonĩ inya sya ĩtu, na ngamanyaĩĩkya melekele iseve isu syonthe; na vatikethĩwa mbaĩ o na yĩva ĩla alũngw’a ma Elamu matakathi kwayo.'),
('kam', 'JER', 49, 37, 'Na ngatuma Aelamu mateva mbee wa amaitha moo, na mbee wa ala mamanthaa mathayũ moo; na ngamaetee ũthũku, o ũthatu wakwa mwai, easya ũu Yeova; na ngatũma ũvyũ ĩtina woo, kũvika nĩmamine vyũ:'),
('kam', 'JER', 49, 38, 'na ngaũngamya kĩvĩla kyakwa kya ũsumbĩ ku Elamu, na ngamanangĩa kw’o asumbĩ na anene me mbee ũsumbĩnĩ, easya ũu Yeova.'),
('kam', 'JER', 49, 39, 'Ĩndĩ kũkeethĩwa mĩthenya ya mũminũkĩlyo, ngatũnga Elamu aume kũtavwanĩ kwake, easya ũu Yeova.'),
('kam', 'JER', 50, 1, 'Ndeto ĩla Yeova waneenie ũndũ wa Mbaviloni, ũndũ wa nthĩ ya Akalitei, na kanyw’a wa mwathani Yelemia.'),
('kam', 'JER', 50, 2, 'Tavan’yai katĩ wa mbaĩ na mũinyaĩĩkya, na kũũngamya kĩvevelo; nyaĩĩkyai na mũikavithe: asyai, Mbaviloni nĩ mbose, ĩla ngai Veli nĩsonoketw’e, Melotaki nĩtevete: mĩvw’anano yayo nĩnĩũsonokw’a, mĩvw’anano yayo nĩ myanangĩku.'),
('kam', 'JER', 50, 3, 'Nũndũ kuma ngalĩ ya ĩũlũ mbaĩ nĩmyũkĩe, ĩla ĩkatw’ĩkĩthya nthĩ yayo nthei, na mũndũ o na wĩva ndakamĩtũa: nĩmakĩĩte, nĩmaendete, mũndũ vamwe na nyamũ.'),
('kam', 'JER', 50, 4, 'Mĩthenya ĩsu, na ĩvinda yĩu, ana ma Isilaeli makooka, mo na ana ma Yuta vamwe, easya ũu Yeova; makathi nzĩanĩ yoo makĩĩa, na kũmantha Yeova Ngai woo.'),
('kam', 'JER', 50, 5, 'Makakũlya ũndũ wa Saioni mothyũ moo melekele kw’o makyasya, Ũkai, mũkwatane na Yeova ũtianĩonĩ wa tene na tene ũla ũtakola.'),
('kam', 'JER', 50, 6, 'Andũ makwa maĩ malondu mau: aĩthi moo nĩmamaĩtye: nĩmamalũlĩte maende iĩmanĩ; nĩmaendete kuma kĩĩmanĩ kũvika kalĩmanĩ; nĩmolĩtwe nĩ kũndũ kwoo kwa ũthũmũo.'),
('kam', 'JER', 50, 7, 'Onthe ala mamonie nĩmamaĩte; na amaitha moo masya, Tũti avĩtan’ya, nĩkwĩthĩwa nĩmamũvĩtanĩsye Yeova, wĩkalo wa ũlũngalu, o Yeova, wĩkwatyo wa aaĩthe moo.'),
('kam', 'JER', 50, 8, 'Kĩai mume katĩ wa Mbaviloni, na mũyuma nthĩ ya Akalitei, ĩthĩwaĩ ta nthenge mbee wa ndĩthya.'),
('kam', 'JER', 50, 9, 'Nũndũ, sisya, ngookĩlya nguthu ya mbaĩ nene kuma nthĩ ya ngalĩ ya ĩũlũ nĩmyambatĩĩsye Mbaviloni: na ikeetaũsya syũkĩte nayo; ĩkooswa yume kw’o: mĩsyĩ yasyo ĩkeethĩwa ta ya ngũmbaũ mbũĩ; vati mũsyĩ ũkasyoka mana.'),
('kam', 'JER', 50, 10, 'Na Kalitei ĩkeethĩwa mũtavo: onthe ala memĩtava makeanĩwa, easya ũu Yeova.'),
('kam', 'JER', 50, 11, 'Nĩkwĩthĩwa mwĩ na mũyo, nĩkwĩthĩwa nĩmũtanaa, inyw’ĩ ala mũvutaa ũtiĩwa wakwa, nĩkwĩthĩwa nĩmũnoete ta moi ĩla ĩvũaa ngetha, na kwan’ya ta mbalasi syĩ vinya;'),
('kam', 'JER', 50, 12, 'mwenyu akasonokw’a vyũ; ũla wakũsyaie akavũavũana: sisya, ĩkeethĩwa ĩla yĩ ĩtina katĩ wa mbaĩ syonthe, weũ, na nthĩ nyũmũ, na yalata.'),
('kam', 'JER', 50, 13, 'Nũndũ wa ũthilĩku wa Yeova ndĩkatũwa nĩ andũ, ĩndĩ ĩkeethĩwa ĩei vyũ: kĩla mũndũ wĩvĩtĩla Mbaviloni akaseng’a na kũmĩtimba ũndũ wa mothĩn’yo mayo onthe.'),
('kam', 'JER', 50, 14, 'Ĩtaũsyei mũkite na Mbaviloni mũkĩmĩthyũlũlũka ngalĩ syonthe, inyw’onthe ala mũkootaa ũta; mĩathei, mũikasũvĩe mĩsyĩ: nũndũ nĩyamũvĩtanĩsye Yeova.'),
('kam', 'JER', 50, 15, 'Myũĩĩsyei ngemi ngalĩ syonthe: nĩyĩnenganĩte; ngome syayo nĩ mbalũku, maũvai mayo nĩmaomboetwe; nũndũ nĩ ũĩvanĩsyo wa Yeova: ĩĩvanĩsyei nayo; o ũndũ yekie mĩkei o w’o.'),
('kam', 'JER', 50, 16, 'Vetai mũvũĩi aume Mbaviloni, na ũla ũkwataa kavyũ ke ngoto ĩvinda ya ngetha: makeethyũũa kĩla mũndũ aende andũnĩ make nũndũ wa kũkĩa ũvyũ ũla ũthĩnasya, na makakĩa na kũthi kĩla mũndũ nthĩ yake mwene.'),
('kam', 'JER', 50, 17, 'Isilaeli nĩ ĩlondu yĩnyaĩĩkĩtw’e; mĩnyambũ nĩmũlũngĩtye: mbee, mũsumbĩ wa Asuli amũya; na yu mũminũkĩlyo Nevukatilesa mũsumbĩ wa Mbaviloni nũtũlĩte mavĩndĩ make.'),
('kam', 'JER', 50, 18, 'Kwondũ wa ũu Yeova wa nguthu, Ngai wa Isilaeli, easya: Sisya, ngakũna mũsumbĩ wa Mbaviloni na nthĩ yake, o tondũ namũkũnie mũsumbĩ wa Asuli.'),
('kam', 'JER', 50, 19, 'Na ngaete Isilaeli ĩngĩ kĩsesinĩ kyake, nake akaĩthw’a iĩmanĩ sya Kalimeli na Mbasani, na thayũ wake ũkavũnĩw’a iĩmanĩ sya Evalaimu na Ngileati.'),
('kam', 'JER', 50, 20, 'Mĩthenya ĩsu, na ĩvinda yĩu, easya Yeova, ũthũku wa Isilaeli ũkamanthwa, ĩndĩ ndũkethĩwa vo; na naĩ sya Yuta ikamanthwa, ĩndĩ itikoneka: nũndũ ngamaekea ala nĩtialya methĩwe ũtialo.'),
('kam', 'JER', 50, 21, 'Ambata ũkite na nthĩ ya Melathaimu, ũkite nayo, na ala matwĩe Vekoti: ũaa nokyananga vyũ ũsyao woo, na kwĩka kwĩanana na w’onthe ũla nakwĩaĩe, easya ũu Yeova.'),
('kam', 'JER', 50, 22, 'Kĩtuu kya kaũ na kya wanangĩko mũnene kĩ ĩ nthĩ.'),
('kam', 'JER', 50, 23, 'Kĩiva kya nthĩ nima ko nĩkyatũĩtwe na kũtũlwa! Mbaviloni ko nĩtw’ĩkĩte ĩei katĩ wa mbaĩ!'),
('kam', 'JER', 50, 24, 'Nyie nĩngũteete, naku nũkwatĩtw’e, we Mbaviloni, na ndwaamanya: nĩwonekete, o na kũkwatw’a, nĩkwĩthĩwa nũkĩlanĩtye vinya na Yeova.'),
('kam', 'JER', 50, 25, 'Yeova nũvingũĩte vandũ vake va kwia mĩio ya kaũ, na kumya mĩio ya ũthatu wake; nũndũ Mwĩaĩi, Yeova wa nguthu, e na wĩa wa kwĩka nthĩ ya Akalitei.'),
('kam', 'JER', 50, 26, 'Mĩendeei kuma mũvaka wĩ mũminũkĩlyonĩ; vingũai makũmbĩ mayo; myũmban’yei ta ivumbu, na kũmyananga vyũ, mũikamĩtialye kĩndũ.'),
('kam', 'JER', 50, 27, 'Ũaai tũsalũ twayo tw’onthe twa mũew’a: tũtheee kĩthĩnzĩonĩ: woo nĩ woo! Nũndũ mũthenya woo nĩ mũku, ĩvinda yoo ya kũsilĩlwa.'),
('kam', 'JER', 50, 28, 'Wasya wa ala makĩaa na kũvonoka kuma nthĩ ya Mbaviloni, wa kũtavan’ya Saioni ũĩvanĩsyo wa Yeova Ngai waitũ, kũĩvanĩsya ũndũ wa ĩkalũ yake.'),
('kam', 'JER', 50, 29, 'Mũmbanĩsyei Mbaviloni andũ ma mata, onthe ala makootaa ũta; ambai maeema menyu mũmũthyũlũlũkĩte; mũtikaeke ũmwe woo avonoke: mũĩvei kwĩanana na wĩa wake; kwĩanana na w’onthe ũla wekie, mwĩkei o w’o; nũndũ nĩwekathĩĩe kwĩthĩwa mũnene kwĩ Yeova, Ũla Mũtheu wa Isilaeli.'),
('kam', 'JER', 50, 30, 'Kwondũ wa ũu anake make makavalũka nzĩanĩ syake nene, na andũ make onthe ma kaũ makavindĩthw’a mũthenya ũsu, easya ũu Yeova.'),
('kam', 'JER', 50, 31, 'Sisya, nĩ na ũndũ naku, we mwĩkathĩĩi, easya ũu Mwĩaĩi, Yeova wa nguthu: nũndũ mũthenya waku nĩ mũku, ĩvinda yĩla ngaũsilĩla.'),
('kam', 'JER', 50, 32, 'Na mwĩkathĩĩi akalulutĩka na kũvalũka, na vaikethĩwa wa ũmũkĩlya; na ngakan’ya mwaki ndũanĩ syake, naw’o ũkamina onthe ala mamũthyũlũlũkĩte.'),
('kam', 'JER', 50, 33, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Ana ma Isilaeli na ana ma Yuta nĩmeũthĩnw’a vamwe; na onthe ala mamatwaie me atave nĩmamalũmĩtye mũno; nĩmeũlea kũmalekya.'),
('kam', 'JER', 50, 34, 'Mwovosya woo e vinya; Yeova wa nguthu nĩ syĩtwa yake: akamatetea mũno, nĩ kana amĩthũmũsye nthĩ, na kũmaũũyĩthya ala matwĩe Mbaviloni.'),
('kam', 'JER', 50, 35, 'Ũvyũ nũmokĩe Akalitei, na ala matwĩe Mbaviloni, na anene make me mbee ũsumbĩnĩ, na andũ make oĩ, easya ũu Yeova.'),
('kam', 'JER', 50, 36, 'Ũvyũ nũmokĩe ala mekathĩĩaa, na makatw’ĩka ndia; ũvyũ nũsyũkĩe ngũmbaũ syake, na ũkaitevya.'),
('kam', 'JER', 50, 37, 'Ũvyũ nĩwũkĩe mbalasi syoo, na makasya moo ma kaũ, na andũ onthe ala mevulanĩtye me nthĩnĩ wake; na makatw’ĩka ta aka: ũvyũ nũmokĩe mothwii make maie, na makoswa.'),
('kam', 'JER', 50, 38, 'Mũnyao nĩwũkĩe manzĩ make, na makang’ala; nũndũ nĩ nthĩ ya mĩvw’anano myasũvye, na nĩmakwatĩtwe nĩ ndũũka ũndũ wa mĩvw’anano.'),
('kam', 'JER', 50, 39, 'Kwondũ wa ũu nyamũ mbai sya weũ vamwe na nzũi ikekala kw’o, na nyaa ikekala kw’o: na ndĩkatũwa ĩngĩ tene na tene; o na ndĩkekalwa nĩ mũndũ kuma nzyawa na nzyawa.'),
('kam', 'JER', 50, 40, 'O ta yĩla Ngai wang’uthũlile Sotomo na Ngomola na ndũa ila syaĩ vakuvĩ nasyo, now’o mũndũ o na wĩva ndakatũa kw’o, kana mwana wa mũndũ o na wĩva ndakekala ũeni kw’o, easya ũu Yeova.'),
('kam', 'JER', 50, 41, 'Sisya, ũko wa andũ nĩwũkĩte kuma ngalĩ ya ĩũlũ; na mbaĩ nene na asumbĩ aingĩ makookĩlw’a kuma itulunĩ sya nthĩ.'),
('kam', 'JER', 50, 42, 'Nĩmakwete mata na matumo; nao nĩ ai, na mati na tei; wasya woo nũũlitũka ta ũkanga; na matũlĩte mbalasi, kĩla ũmwe nĩwĩtaũĩtye ta mũndũ wa kaũ, we mwĩĩtu wa Mbaviloni.'),
('kam', 'JER', 50, 43, 'Mũsumbĩ wa Mbaviloni nĩwĩw’ĩte maũvoo moo, na moko moo nĩmekũleela: thĩna nũmũkwatĩte, na woo ta wa mũndũ mũka akyaũnya.'),
('kam', 'JER', 50, 44, 'Sisya, mũmaitha akookĩa wĩkalo wĩ vinya wa mũnyambũ ũindũkĩte kũvinganĩ kwa Yolotani: nũndũ ngamasembya kuma vo na kĩthũlũmũko; na ũla mũnyuve, nĩwe ngaia ĩũlũ wa vo: nũndũ nũũ ũilyĩ takwa? Na nũũ wĩndw’ĩĩa ĩvinda? Na mũĩthi nũũ ũla ũtonya kũũngama mbee wakwa?'),
('kam', 'JER', 50, 45, 'Kwondũ wa ũu ĩthukĩĩsyei ũtw’ĩo wa Yeova, ũla watw’ĩĩe Mbaviloni; na mosũanĩo make, ala ũsũanĩĩte kũmĩka nthĩ ya Akalitei: Vate ndĩi makamaumya mamakusĩtye, o anini ma ndĩthya; vate ndĩi akatw’ĩkĩthya wĩkalo woo ĩanzo o vamwe nao.'),
('kam', 'JER', 50, 46, 'Nthĩ nĩnĩkũtetema ũndũ wa kĩlonzo kya kũkwata Mbaviloni, na kĩĩo nĩkĩkwĩw’ĩka katĩ wa i mbaĩ.'),
('kam', 'JER', 51, 1, 'Ũũ nĩw’o Yeova ũnũkwasya: Sisya, ngauutanĩthya Mbaviloni, na ala matwĩe Levi‐kamai, kĩseve kya kwananga.'),
('kam', 'JER', 51, 2, 'Na ngatũma aeni Mbaviloni, ala makamĩũlũkya; na makatw’ĩkĩthya nthĩ yayo nthei; nũndũ mũthenya wa thĩna makamyũkĩa makĩmĩthyũlũlũka.'),
('kam', 'JER', 51, 3, 'Mũkooti wa ũta mũathi namũkootee ũta wake, na ũla wenenevasya ekĩĩte kakoti kake ka iaa: na mũikatialye anake mayo; anangai vyũ nguthu yayo yonthe.'),
('kam', 'JER', 51, 4, 'Na makavalũka me oae nthĩ ya Akalitei, matonyeetwe nzĩanĩ syake nene.'),
('kam', 'JER', 51, 5, 'Nũndũ Isilaeli ndaaekwa, kana Yuta, nĩ Ngai wake, nĩ Yeova wa nguthu; o na kau nthĩ yoo nĩyusũĩte naĩ ila mamwĩkĩte Ũla Mũtheu wa Isilaeli.'),
('kam', 'JER', 51, 6, 'Kĩai mume nthĩnĩ wa Mbaviloni, kĩla mũndũ natangĩĩe thayũ wake; mũĩkanangwe nĩ ũthũku wayo: nũndũ nĩ ĩvinda ya ũĩvanĩsyo wa Yeova; we akamĩĩva.'),
('kam', 'JER', 51, 7, 'Mbaviloni yaĩ kĩkombe kya thaavu kw’okonĩ kwa Yeova, kĩla kyatoonisye nthĩ yonthe: mbaĩ nĩsyanywie mbinyu yayo; kwondũ wa ũu mbaĩ nikwatĩtwe nĩ ndũũka.'),
('kam', 'JER', 51, 8, 'Mbaviloni nĩ mbalũku na kĩthũlũmũko na kwanangwa: mĩmeteei; mĩtwaĩei seli ũndũ wa kwalw’a kwayo, nokwĩthĩwa nĩtonya kũvoeka.'),
('kam', 'JER', 51, 9, 'Nĩtwendaa kũvosya Mbaviloni, ĩndĩ ndĩnavoeka: mĩtiei, na tũithĩ kĩla mũndũ nthĩ yake mwene; nũndũ ũsilĩlo wayo nũvikĩte ĩtunĩ, na kũkĩlw’a o kũvika matunĩ.'),
('kam', 'JER', 51, 10, 'Yeova nĩumĩlĩtye ũlũngalu wĩtũ: ũkai, tũtavan’ye Saioni wĩa wa Yeova Ngai waitũ.'),
('kam', 'JER', 51, 11, 'Noai mauumu, kwatai mũlũmye ngao: Yeova nĩwũkĩlĩtye maveva ma asumbĩ ma Amitiani; nĩkwĩthĩwa ũsũanĩo wake wĩ ĩũlũ wa Mbaviloni, amyanange: nũndũ nĩ ũĩvanĩsyo wa Yeova, kũĩvanĩsya kwondũ wa ĩkalũ yake.'),
('kam', 'JER', 51, 12, 'Ũngamĩsyai maũvai ma Mbaviloni kĩvevelo, mekĩei asũviĩ vinya, iai asyaĩĩsya, seũvyai kũla kwa kwoveesya; nũndũ Yeova nũsũanĩĩte na nĩwĩkĩte ũla wamaneenee ala matwĩe Mbaviloni.'),
('kam', 'JER', 51, 13, 'We ũla wĩkalaa ĩũlũ wa manzĩ maingĩ, wĩ na ũthwii mwie mwingĩ, mũminũkĩlyo waku nĩ mũviku, kĩthimi kya ĩtomo yaku.'),
('kam', 'JER', 51, 14, 'Yeova wa nguthu nĩwĩvĩtĩte nake mwene, akyasya, Vate ndĩi ngakusũsya na andũ, o ta mbandi; na makakũkĩlĩlya wasya mũnene.'),
('kam', 'JER', 51, 15, 'Nũtw’ĩkĩthĩtye nthĩ kwondũ wa vinya wake, nũlũmĩtye nthĩ kwondũ wa ũĩ wake, na nũtambũũkĩtye matu kwondũ wa ũmanyi wake.'),
('kam', 'JER', 51, 16, 'Yĩla waumya wasya wake ve kĩlitũko kya manzĩ matunĩ, na nũtumaa mũki kwambata kuma itulunĩ sya nthĩ; nũseũvĩasya mbua motisi, na kumya kĩseve ũthwiinĩ wake.'),
('kam', 'JER', 51, 17, 'Kĩla mũndũ nũtw’ĩkĩte ta nyamũ na nde na ũmanyi; kĩla mũtwii wa thaavu nũsonokaw’a nĩ mũvw’anano wake; nũndũ mũvw’anano wake ũla waseũvisye na syĩndũ ila watwekethisye nĩ wa ũvũngu, na vai veva nthĩnĩ wayo.'),
('kam', 'JER', 51, 18, 'Nayo nĩ mana, wĩa wa ũkengani: ĩvinda ya kũsiw’a kwayo ĩkaaa.'),
('kam', 'JER', 51, 19, 'Kĩanda kya Yakovo ti ta ĩsu; nũndũ nĩwe mũmbi wa syĩndũ syonthe; na Isilaeli nĩ mbaĩ ya ũtiĩwa wake: Yeova wa nguthu nĩ syĩtwa yake.'),
('kam', 'JER', 51, 20, 'We nue ĩthoka yakwa ya kũkita nayo na mĩio ya kaũ: na ngũkwete ngaitilanga ilungu i mbaĩ; na ngũkwete ngaananga mosumbĩ;'),
('kam', 'JER', 51, 21, 'na ngũkwete ngatilanga ilungu mbalasi na ũla ũmĩtũlĩte;'),
('kam', 'JER', 51, 22, 'na ngũkwete ngatilanga ilungu ĩkasya na ũla ũkuĩtwe nĩyo; na ngũkwete ngatilanga ilungu mũndũ mũũme na mũndũ mũka; na ngũkwete ngatilanga ilungu mũtumĩa na ũla mũnini; na ngũkwete ngatilanga ilungu mwanake na mwĩĩtu mũtheu;'),
('kam', 'JER', 51, 23, 'na ngũkwete ngatilanga ilungu mũĩthi na ndĩthya yake; na ngũkwete ngatilanga ilungu mũĩmi na kyove kyake kya ng’ombe; na ngũkwete ngatilanga ilungu makavana na amũli.'),
('kam', 'JER', 51, 24, 'Ngaĩvĩa kwa Mbaviloni na kwa onthe ala matwĩe Kalitei ũthũku woo w’onthe ũla meekie Saioni, mwene na metho menyu, easya ũu Yeova.'),
('kam', 'JER', 51, 25, 'Sisya, nĩ na ũndũ naku, we kĩĩma kĩla kyanangaa, kĩla kyanangaa nthĩ yonthe, easya ũu Yeova; na ngakũtambũũkĩsya kw’oko kwakwa, na ũkũvingilitya kuma mavianĩ, na ũkũtw’ĩkĩthya kĩĩma kĩvĩvye.'),
('kam', 'JER', 51, 26, 'Na matikosa kwaku ĩvia ya kĩkotonĩ, kana ĩvia ya myambĩlĩlyo; ĩndĩ ũkeethĩwa ĩei tene na tene, easya ũu Yeova.'),
('kam', 'JER', 51, 27, 'Ũngamyai kĩvevelo ĩ nthĩ, vuvai soo katĩ wa i mbaĩ, vathai mbaĩ sya kũkita nake, metei mosumbĩ ma Alalati, na Mini, na Asikenasi mamũmbanĩe vamwe: mwiĩei kavuteni; ambatyai mbalasĩ ta mbandi yĩ w’ĩa.'),
('kam', 'JER', 51, 28, 'Vathai i mbaĩ sya kũkita nake, asumbĩ ma Ametia, makavana ma vo, na amũli ma vo, na nthĩ yonthe ya ũsumbĩko woo.'),
('kam', 'JER', 51, 29, 'Na nthĩ nĩnĩũtetema na kwalw’a; nũndũ mosũanĩo ma Yeova ũndũ wa Mbaviloni nĩmaũngeme, atw’ĩkĩthye nthĩ ya Mbaviloni nthei, ĩte mũndũ ũmĩtũa.'),
('kam', 'JER', 51, 30, 'Ngũmbaũ sya Mbaviloni nĩsyaleile kũkita, nĩsyĩkalaa ngomenĩ syasyo syĩ vinya; ũtonyi wasyo nĩ mũthelu; nĩsyatw’ĩkĩte ta aka: mawĩkalo mayo nĩmakanĩte mwaki; ivingi syayo nĩ ndũlĩku.'),
('kam', 'JER', 51, 31, 'Mũsembi ũmwe akasemba akomane na ũngĩ, na mũtũmwa ũmwe kũkomana na ũngĩ, kũmwon’ya mũsumbĩ wa Mbaviloni ndũa yake nĩyosetwe kĩla ngalĩko:'),
('kam', 'JER', 51, 32, 'na masyũko nĩ makwate, na nĩmavĩvĩtye mĩangi na mwaki, na andũ ma kaũ nĩmakwatĩtwe nĩ w’ĩa.'),
('kam', 'JER', 51, 33, 'Nũndũ ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Mwĩĩtu wa Mbaviloni ailyĩ kĩvũĩo ĩvinda yĩla kĩũkinyangwa; no kavinda kanini, na ĩvinda ya ngetha yĩkamũkĩa.'),
('kam', 'JER', 51, 34, 'Nevukatilesa mũsumbĩ wa Mbaviloni nũndĩte, nũnganyangĩte, nũndw’ĩkĩthĩtye mũio mũthei, nũmeletye nyie ta mũkũnga, nĩwusũĩtye ĩvu yake na syĩndũ syakwa syĩ mũyo; nũmbĩkĩtye nza.'),
('kam', 'JER', 51, 35, 'Ũla ũtwĩe Saioni akasya, Ũthũku ũla neekiwe na weekwa mwĩĩ wakwa wĩthĩwe ĩũlũ wa Mbaviloni; na Yelusaleme ĩkasya, Nthakame yakwa yĩthĩwe ĩũlũ wa ala matwĩe Kalitei.'),
('kam', 'JER', 51, 36, 'Kwondũ wa ũu Yeova easya: Sisya, ngakũtetea, na kũĩvanĩsya kwondũ waku; na ngang’alya ũkanga wake, na kũng’alya nthongo yake.'),
('kam', 'JER', 51, 37, 'Na Mbaviloni ĩkatw’ĩka ivumbu, wĩkalo wa mbĩwa, na ũseng’yo, na ya kũtimbwa, ĩte mũndũ ũmĩtũa.'),
('kam', 'JER', 51, 38, 'Makaluma vamwe ta mĩnyambũ ya mũika; makang’olota ta maswii ma mĩnyambũ.'),
('kam', 'JER', 51, 39, 'Yĩla me na muutĩa ngamavokea mboka, na ngamatoonethya nĩ kana matane, na kũkoma too mavinda onthe, na kũlea kũamũka, easya ũu Yeova.'),
('kam', 'JER', 51, 40, 'Ngamatheesya kĩthĩnzĩonĩ ta tũtena twa malondu, ta ndũũme vamwe na nthenge.'),
('kam', 'JER', 51, 41, 'A! Sesaki nĩ mbose! Na ndaĩa ya nthĩ yonthe nĩ ngwate! Mbaviloni nĩtw’ĩkĩte ũseng’yo katĩ wa mbaĩ!'),
('kam', 'JER', 51, 42, 'Ũkanga nĩwũkĩlĩte ĩũlũ wa Mbaviloni; nĩvw’ĩkĩtwe na wingĩ wa itulumo syaw’o.'),
('kam', 'JER', 51, 43, 'Ndũa syayo nitw’ĩkĩte maanzo, nthĩ nyũmũ, na yalata, nthĩ ĩteũtũwa nĩ mũndũ, o na mwana wa mũndũ o na wĩva ndeũvĩtĩla kw’o.'),
('kam', 'JER', 51, 44, 'Na ngasĩlĩla ĩla ngai Veli ku Mbaviloni, na ngaumya kanyw’anĩ wayo kĩla ĩmeletye; na mbaĩ itikamĩendea ĩngĩ; ĩĩ, ũvai wa Mbaviloni ũkavalũka.'),
('kam', 'JER', 51, 45, 'Andũ makwa, umai katĩ wayo, mwĩtangĩĩe kĩla mũndũ kuma ũthatunĩ mwai wa Yeova.'),
('kam', 'JER', 51, 46, 'Ngoo syenyu itikaleele, na mũikakĩe ũndũ wa maũvoo ala makew’ĩka ĩ nthĩ; nũndũ maũvoo makoka mwaka ũmwe, na ĩtina wa ũu mwaka ũngĩ, vakoka maũvoo, na ũng’endu ĩ nthĩ, mũsumbĩki akookĩlĩanĩla na mũsumbĩki.'),
('kam', 'JER', 51, 47, 'Kwondũ wa ũu, sisya, mĩthenya nĩyũkĩte, ĩla ngasilĩla mĩvw’anano myasũvye ya Mbaviloni; na nthĩ yayo nima ĩkathokoanw’a; na oawa mayo onthe makavalũka katĩ wayo.'),
('kam', 'JER', 51, 48, 'Nĩvo ĩndĩ matu na nthĩ, na syonthe ila syĩ nthĩnĩ wasyo, ikaina na ũtanu ĩũlũ wa Mbaviloni; nũndũ anangi makamyũkĩa kuma ngalĩ ya ĩũlũ, easya ũu Yeova.'),
('kam', 'JER', 51, 49, 'O tondũ Mbaviloni wavalũkilye kwa kũaa ala ma Isilaeli, now’o ku Mbaviloni kũkavalũkw’a ala meũawa ma ĩ nthĩ yonthe.'),
('kam', 'JER', 51, 50, 'Inyw’ĩ ala mwavonokete ũvyũ, endai, mũikaũngame: lilikanai Yeova mwĩ kũasa, na Yelusaleme nĩlike kĩlilikanonĩ kyenyu.'),
('kam', 'JER', 51, 51, 'Nĩtũthokoanĩte, nĩkwĩthĩwa nĩtwĩw’ĩte kĩvũthyo; kĩthokoan’yo nĩkĩvw’ĩkĩte mothyũ maitũ: nũndũ aeni nĩmalikĩte kũndũ kũtheu kwa nyũmba ya Yeova.'),
('kam', 'JER', 51, 52, 'Kwondũ wa ũu, sisya, mĩthenya nĩyũkĩte, easya Yeova, ĩla ngasilĩla mĩvw’anano yayo myasũvye; na nthĩ yayo yonthe ala okite makaluma.'),
('kam', 'JER', 51, 53, 'O na ethĩwa Mbaviloni ĩkambata ĩtunĩ, na ethĩwa ĩkaiia vandũ vatũlu va vinya wayo, no mũvaka anangi mamĩendee kuma kwakwa, easya ũu Yeova.'),
('kam', 'JER', 51, 54, 'Wasya wa kĩĩo kuma Mbaviloni, na wa wanangĩko mũnene kuma nthĩ ya Akalitei!'),
('kam', 'JER', 51, 55, 'Nũndũ Yeova nũnũũtw’ĩkĩthya Mbaviloni nthei, na kwananga wasya mũnene nthĩnĩ wayo; na itulumo syoo nilitũkaa ta manzĩ maingĩ; kĩlonzo kya wasya woo nĩkyumĩtw’e:'),
('kam', 'JER', 51, 56, 'nũndũ mwanangi nũmĩvikĩe, o Mbaviloni, na ngũmbaũ syayo nĩ ngwate, mata masyo nĩ matũlĩku ilungu; nũndũ Yeova nĩ Ngai wa kũĩva, ndatĩa kũĩvanĩsya.'),
('kam', 'JER', 51, 57, 'Na ngatoonethya anene mayo me mbee ũsumbĩnĩ na andũ mayo oĩ, makavana mayo na amũli mayo, na ngũmbaũ syayo; na makakoma too wa mavinda onthe, na matikaamũka, easya ũu Mũsumbĩ, syĩtwa yake nĩ Yeova wa nguthu.'),
('kam', 'JER', 51, 58, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Maũvai mathanthau ma Mbaviloni makaombowa vyũ, na mbingĩlo syayo ndũlu ikavĩvw’a na mwaki; na ngo sya andũ ikathĩnĩa wĩa mana, na mbaĩ ikathĩn’ya wĩa kwondũ wa mwaki; na makanoa.'),
('kam', 'JER', 51, 59, 'Ndeto ĩla mwathani Yelemia wamwĩaĩe Selaia mwana wa Nelia, mwana wa Maaseia, yĩla waendie Mbaviloni na Nzetekĩa mũsumbĩ wa Yuta mwaka wa kana wa kũsumbĩka kwake. Na Selaia aĩ mũsũvĩi mũnene.'),
('kam', 'JER', 51, 60, 'Na Yelemia aandĩka ĩvukunĩ ũthũku w’onthe ũla wĩũka Mbaviloni, o ndeto ii syonthe ila iandĩkĩtwe ũndũ wa Mbaviloni.'),
('kam', 'JER', 51, 61, 'Na Yelemia amwĩa Selaia, Yĩla wĩũka Mbaviloni, na kwona, na kũsoma ndeto ii syonthe,'),
('kam', 'JER', 51, 62, 'nĩvo ĩndĩ ũkasya, Ame Yeova, nũneenete ũndũ wa vandũ vaa, kũvaveta, vaikethĩwa ũla ũtũa vo, mũndũ kana nyamũ, ĩndĩ vakeethĩwa vathei tene na tene.'),
('kam', 'JER', 51, 63, 'Na kũkeethĩwa, wamina kũsoma ĩvuku yĩu, ũkayoveea ĩvia, na kũyĩkya ũsĩnĩ wa Euvalati katĩ:'),
('kam', 'JER', 51, 64, 'na ũkasya, O ta ũu Mbaviloni ĩkathelekelya, na ndĩkokĩla ĩngĩ nũndũ wa ũthũku ũla ngamĩetee; nao makanoa. Ndeto sya Yelemia syavika vu.'),
('kam', 'JER', 52, 1, 'Nzetekia aĩ wa myaka mĩongo ĩlĩ na ũmwe yĩla wambĩlĩlye kũsumbĩka; na asumbĩka myaka ĩkũmi na ũmwe Yelusaleme: na syĩtwa ya inyia wake eetawa Amutali mwĩĩtu wa Yelemia wa ku Livina.'),
('kam', 'JER', 52, 2, 'Nake eekaa ũndũ Yeova wonaa wĩ ũthũku, kwĩanana na w’onthe ũla Yeoiakimu wekaa.'),
('kam', 'JER', 52, 3, 'Ĩndĩ ũndũ ũsu nĩwekĩkie Yelusaleme na Yuta kwondũ wa ũthatu wa Yeova, kũvika amalũngya kuma mbee wake. Na Nzetekĩa amũng’endea mũsumbĩ wa Mbaviloni.'),
('kam', 'JER', 52, 4, 'Na kweethĩwa mwaka wa kenda wa kũsumbĩka kwake, mwei wa ĩkũmi, mũthenya wa ĩkũmi wa mwei, Nevukatilesa mũsumbĩ wa Mbaviloni ookĩa Yelusaleme, we na ita syake syonthe, na mamba maeema mamĩtaũĩĩe; na mamyakĩa ngome kũmĩthyũlũlũka ngalĩ syonthe.'),
('kam', 'JER', 52, 5, 'O ta ũu ndũa yatw’ĩkanĩw’a kũvika mwaka wa ĩkũmi na ũmwe wa mũsumbĩ Nzetekia.'),
('kam', 'JER', 52, 6, 'Mwei wa kana, mũthenya wa kenda wa mwei, nzaa yaĩ nene ndũanĩ, o na vatyaĩ lĩu kwondũ wa andũ ma nthĩ ĩsu.'),
('kam', 'JER', 52, 7, 'Nĩvo ĩndĩ ndũa yavũthũiwe, na aũme onthe ma kaũ makĩa, na mauma ndũanĩ ũtukũ na nzĩa ya mbingĩlo ĩla yaĩ katĩ wa maũvai elĩ, ĩla yaĩ vakuvĩ na mũũnda wa mũsumbĩ (na Akalitei maĩ manathyũlũlũka ndũa ngalĩ syonthe); na maenda melekele mwanda wa Alava.'),
('kam', 'JER', 52, 8, 'Ĩndĩ ita sya Akalitei syamũatĩĩa mũsumbĩ, na syamũkwatĩa Nzetekia ndiĩnĩ sya Yeliko; na ita syake syonthe syanyaĩĩkw’a kuma vala ũĩ.'),
('kam', 'JER', 52, 9, 'Nĩvo ĩndĩ makwatie mũsumbĩ, na mamũtwaa vala ve mũsumbĩ wa Mbaviloni ku Livila nthĩ ya Amathi; nake amũtw’ĩa ũsilĩlo.'),
('kam', 'JER', 52, 10, 'Na mũsumbĩ wa Mbaviloni ooaa ana ma Nzetekia ene na metho make; o na ooaa anene onthe me mbee ũsumbĩnĩ ma Yuta ku Livila.'),
('kam', 'JER', 52, 11, 'Na amũvũthũanga Nzetekia metho; na mũsumbĩ wa Mbaviloni amwĩkĩa mbĩngũ, na amũtwaa Mbaviloni, na kũmwĩkĩa kolokolonĩ kũvika mũthenya wa kũkw’a kwake.'),
('kam', 'JER', 52, 12, 'Na mwei wa katano, mũthenya ĩkũmi wa mwei, nĩw’o waĩ mwaka wa ĩkũmi na kenda wa kũsumbĩka kwa mũsumbĩ Nevukatilesa, mũsumbĩ wa Mbaviloni, Nevusalatani, kavuteni wa nguthu ya asũvĩi, ũla waũngamaa mbee wa mũsumbĩ wa Mbaviloni, wokie Yelusaleme.'),
('kam', 'JER', 52, 13, 'Nake avĩvya nyũmba ya Yeova, na nyũmba ya mũsumbĩ; na nyũmba syonthe sya Yelusaleme, o kĩla nyũmba nene, avĩvya na mwaki.'),
('kam', 'JER', 52, 14, 'Na ita syonthe sya Akalitei, ila syaĩ na kavuteni wa asũvĩi, syaomboanga maũvai onthe ma Yelusaleme ngalĩ syonthe.'),
('kam', 'JER', 52, 15, 'Nĩvo ĩndĩ Nevusalatani kavuteni wa asũvĩi watwaie me atave ala ngya ki ma andũ, na ũtialo wa andũ ala matialilw’e ndũanĩ, na ala meetilĩte makaenda kwa mũsumbĩ wa Mbaviloni, na ũtialo wa andũ aingĩ.'),
('kam', 'JER', 52, 16, 'Ĩndĩ Nevusalatani kavuteni wa asũvĩi atia amwe ma ala ngya ki ma nthĩ methĩwe ma kũsea mĩsavivũ na ma kũĩma.'),
('kam', 'JER', 52, 17, 'Na ituĩ sya ũthuku ila syaĩ nyũmbanĩ ya Yeova, na ala matina na ũla ũkanga wa ũthuku ila syaĩ nyũmbanĩ ya Yeova, Akalitei nĩmaitũlangile ilungu, na kũtwaa ũthuku w’onthe wasyo Mbaviloni.'),
('kam', 'JER', 52, 18, 'O na matwaa mbisũ, na mĩko, na mĩkasi, na masaani manene, na syĩko, na mĩio yonthe ya ũthuku ĩla mathũkũmaa nayo.'),
('kam', 'JER', 52, 19, 'Na ikombe, na tũvũngũlyũ twa ũkua makaa, na masaani manene, na mbisũ, na syĩndũ ila syĩkĩawa mataa, na syĩko na mbakũli — kĩla kyaĩ kya thaavu, thaavunĩ, na kĩla kyaĩ kya vetha, vethanĩ, kavuteni wa asũvĩi atwaa.'),
('kam', 'JER', 52, 20, 'Ituĩ ilĩ, na ũla ũkanga ũmwe, na nzaũ ĩkũmi na ilĩ sya ũthuku ila syaĩ ĩtheo wa matina, ila mũsumbĩ Solomoni waseũvisye kwondũ wa nyũmba ya Yeova — ũthuku wa mĩio ĩsu yonthe ndwaĩ ũthimĩka.'),
('kam', 'JER', 52, 21, 'Na ũndũ wa ituĩ isu, ũtũlu wa kĩtuĩ kĩmwe waĩ mĩkono ĩkũmi na nyanya; na kũkĩthyũlũlũka nĩ mĩkono ĩkũmi na ĩlĩ; na kĩemo kyakyo kyaĩ kĩemo kya syaa inya: na kyaĩ ĩima nthĩnĩ.'),
('kam', 'JER', 52, 22, 'Na ngovia ya ũthuku yaĩ ĩũlũ wakyo; na ũtũlu wa ngovia ĩmwe waĩ mĩkono ĩtano, yĩ na seng’eng’e na makũngũmanga kũthyũlũlũka ngovianĩ, syonthe sya ũthuku: na kĩtuĩ kya kelĩ nakyo kyaĩ na syĩndũ syailyĩ isu, na makũngũmanga.'),
('kam', 'JER', 52, 23, 'Na kwaĩ makũngũmanga mĩongo kenda na thanthatũ ngalĩ syonthe; makũngũmanga onthe maĩ ĩana ĩũlũ wa seng’eng’e ngalĩ syonthe.'),
('kam', 'JER', 52, 24, 'Na kavuteni wa nguthu ya asũvĩi oosa mũthembi mũnene Selaia, na Nzevania mũthembi wa kelĩ, na ala asũvĩi atatũ ma mwalyonĩ:'),
('kam', 'JER', 52, 25, 'na ndũanĩ oosa mũnene ũmwe ũla waiĩtwe ĩũlũ wa andũ ma kaũ; na andũ mũonza moo ala moonaa ũthyũ wa mũsumbĩ, ala moonekie ndũanĩ; na mũandĩki wa kavuteni wa nguthu, ũla wombanasya andũ ma nthĩ: na andũ mĩongo thanthatũ ma andũ ma nthĩ ĩsu, ala moonekie vu ndũanĩ.'),
('kam', 'JER', 52, 26, 'Na Nevusalatani kavuteni wa nguthu ya asũvĩi amosa, na amatwaa kwa mũsumbĩ wa Mbaviloni ku Livila.'),
('kam', 'JER', 52, 27, 'Na mũsumbĩ wa Mbaviloni amakũna, na amoaĩa ku Livila nthĩ ya Amathi. Ũũ nĩw’o Yuta watwaiwe e mũtave kumw’a nthĩ yake.'),
('kam', 'JER', 52, 28, 'Aa nĩo andũ ala Nevukatilesa wamatwaie me atave: mwaka wa mũonza Ayuti ngili itatũ na mĩongo ĩlĩ na atatũ;'),
('kam', 'JER', 52, 29, 'mwaka wa ĩkũmi na nyanya wa kũsumbĩka kwa Nevukatilesa atwaa me atave andũ maana nyanya na mĩongo ĩtatũ na elĩ kuma Yelusaleme;'),
('kam', 'JER', 52, 30, 'mwaka wa mĩongo ĩlĩ na ĩtatũ wa kũsumbĩka kwa Nevukatilesa, kavuteni wa nguthu ya asũvĩi Nevusalatani atwaa me atave Ayuti andũ maana mũonza na mĩongo ĩna na atano: andũ onthe maĩ ngili inya na maana thanthatũ.'),
('kam', 'JER', 52, 31, 'Na kweethĩwa mwaka wa mĩongo ĩtatũ na mũonza wa kũtavwa kwa Yeoiakini mũsumbĩ wa Yuta, mwei wa ĩkũmi na ĩlĩ, mũthenya wa mĩongo ĩlĩ na ĩtano wa mwei, kana Evili‐melotaki mũsumbĩ wa Mbaviloni, mwaka wa mbee wa kũsumbĩka kwake, ookĩlya mũtwe wa Yeoiakini mũsumbĩ wa Yuta, na amumya kolokolonĩ;'),
('kam', 'JER', 52, 32, 'na aneena nake nesa, na aia kĩvĩla kyake kya ũsumbĩ ĩũlũ wa kĩvĩla kya ũsumbĩ kya asumbĩ ala maĩ nake Mbaviloni,'),
('kam', 'JER', 52, 33, 'na akũan’ya ngũa syake sya kolokolonĩ. Na Yeoiakini aĩsĩaa lĩu mbee wake mavinda onthe mĩthenya yonthe ya thayũ wake:'),
('kam', 'JER', 52, 34, 'na ũndũ wa lĩu wake, kwaĩ lĩu wa mavinda onthe wanengawe nĩ mũsumbĩ wa Mbaviloni, kĩla mũthenya lĩu kũvika mũthenya wa kũkw’a kwake, mĩthenya yonthe ya thayũ wake.'),
('kam', 'LAM', 1, 1, 'Kaĩ ndũa nĩyĩkalaa yĩ nthei, ĩla yaĩ mbusũu andũ! Nĩtw’ĩkĩte ta mũndũ mũka ndiwa, ĩla yaĩ nene katĩ wa i mbaĩ! Yo ĩla yaĩ mwĩĩtu wa mũnene wĩ mbee ũsumbĩnĩ ilungunĩ nene sya nthĩ nĩtw’ĩkĩte ya kumya koti!'),
('kam', 'LAM', 1, 2, 'Nĩĩaa mũno ũtukũ, na methoi mayo me mataunĩ mayo; Katĩ wa endwa mayo onthe ndĩ na ũmwe wa kũmĩkiakisya: Anyanyae mayo onthe nĩmamĩkie ũseleke; nĩmatw’ĩkĩte amaitha mayo.'),
('kam', 'LAM', 1, 3, 'Yuta nĩ mũendu e mũtave nũndũ wa thĩna, na ũkombo wĩ vinya; Nĩwĩkalaa katĩ wa i mbaĩ, ndonaa ũthũmũo: Athĩn’ya make onthe mamũwĩla e vandũ va kũvivinyĩwa.'),
('kam', 'LAM', 1, 4, 'Nzĩa sya Saioni nikũĩa, nĩkwĩthĩwa vati ũmwe ũla wũkaa mbokanĩ ĩtw’ĩtwe: Mbingĩlo syayo syonthe nĩ nthei, athembi mayo nĩmavevũũkaa: Eĩtu atheu mayo nĩmathĩnaw’a, nayo o yo yĩ na ũũ.'),
('kam', 'LAM', 1, 5, 'Nthũ syayo nĩsyatw’ĩkie mũtwe, amaitha mayo nĩmeũunĩka; Nũndũ Yeova nũmĩthĩnĩtye ũndũ wa wingĩ wa mavĩtyo mayo: Syana syayo nini nitwaĩtwe syĩ mbee wa nthĩ syĩ ndave.'),
('kam', 'LAM', 1, 6, 'Ndaĩa yonthe ya mwĩĩtu wa Saioni nĩmumĩte; Anene mayo me mbee ũsumbĩnĩ nĩmatw’ĩkĩte ta ndaatai nzamba ila itonaa kya ũya, Na nĩmaendete mate na vinya mbee wa ũla ũmaatĩĩaa.'),
('kam', 'LAM', 1, 7, 'Mĩthenyanĩ ya monyamao mayo na ya thĩna wayo Yelusaleme nĩnĩũlilikana syĩndũ syayo syonthe sya kwendeesya ila syaĩ vo kuma mĩthenya ya tene: Yĩla andũ mayo mavalũkile mokonĩ ma nthũ, na vatyaĩ ũmwe wamĩtethisye, Nthũ nĩsyamyonie, na syathekeea na kĩvũthya mawanangĩko mayo.'),
('kam', 'LAM', 1, 8, 'Yelusaleme nĩyĩkĩte naĩ mũno; kwondũ wa ũu nĩtw’ĩkĩte ta kĩndũ kĩvuku; Onthe ala mamĩtaĩĩaa nĩmeũmĩvũthya, nĩkwĩthĩwa nĩmamyonete yĩ nthei: Ĩĩ, nĩnĩũvevũũka, na kũsyoka na ĩtina.'),
('kam', 'LAM', 1, 9, 'Ũvuku wayo waĩ ngũanĩ syayo; ndĩaalilikana mũminũkĩlyo wayo; Kwondũ wa ũu nĩtheeete ta ũseng’yo; ndĩ na mũkiakisya: Sisya, ame Yeova, thĩna wakwa; nũndũ mũmaitha nĩwĩnenevetye mwene.'),
('kam', 'LAM', 1, 10, 'Nthũ nĩtambũũkitye kw’oko kwayo ĩũlũ wa syĩndũ syonthe syayo sya kwendeesya: Nũndũ nĩyonete atĩ i mbaĩ nilikĩte vandũ vayo vatheu, Ila weeaie kwondũ wasyo itikaalike ũmbanonĩ waku.'),
('kam', 'LAM', 1, 11, 'Andũ mayo onthe nĩmeũvevũũka, nĩmeũmantha lĩu; Nĩmakũanĩtye syĩndũ syoo sya kwendeesya lĩu wa kũvuũkya thayũ: Ona, ame Yeova, noisisya; nũndũ nĩndw’ĩkĩte kĩndũ kĩte vata.'),
('kam', 'LAM', 1, 12, 'Ti ũndũ kwenyu, inyw’onthe ala mũvĩtaa? Sisyai, nokyona ethĩwa ve woo o na wĩva ũilyĩ woo wakwa, ũla ũetetwe ĩũlũ wakwa, Ũla Yeova ũnthĩnĩtye naw’o mũthenya wa ũthatu wake mwai.'),
('kam', 'LAM', 1, 13, 'Kuma ĩũlũ nũtumĩte mwaki mavĩndĩnĩ makwa, naw’o nũmakĩlasya vinya; Nĩwalanĩte kĩtei ũndũ wa maũũ makwa, nũndũngĩte na ĩtina: Nũmbĩkalĩtye nĩ na ĩvoũ na nĩ mũtevu mũthenya w’onthe.'),
('kam', 'LAM', 1, 14, 'Ĩsoki ya mavĩtyo makwa nĩyovetwe nĩ kw’oko kwake; Nĩmakwatanĩte vamwe, nĩmambatĩte ngingonĩ yakwa; nũtumĩte vinya wakwa waa: Mwĩaĩi nũnenganĩte mokonĩ moo, ala ndatonya kũũngama kũmasiĩĩa.'),
('kam', 'LAM', 1, 15, 'Mwĩaĩi nũtw’ĩkĩthĩtye sya mana ngũmbaũ syakwa syonthe katĩ wakwa; Nũmbũmbanĩsye ũmbano ũkilĩtye akanyange anake makwa: Mwĩaĩi nũkinyangĩte o ta kĩangĩonĩ mwĩĩtu mũtheu wa Yuta.'),
('kam', 'LAM', 1, 16, 'Nũndũ wa maũndũ asu nĩngũĩa; itho yakwa, itho yakwa nĩyĩkũnyũlũlũkya methoi; Nĩkwĩthĩwa mũkiakisya ũla waĩle kũvuũkya thayũ wakwa e kũasa nakwa: Syana syakwa syĩ na ĩvou, nũndũ mũmaitha nũkĩlĩtye vĩnya.'),
('kam', 'LAM', 1, 17, 'Saioni nĩnĩũtambũũkya moko mayo; na vati ũmwe wa kũmĩkiakisya; Yeova nĩwĩaĩte ũndũ wa Yakovo, atĩ ala mamũthyũlũlũkĩte makeethĩwa nthũ syake: Yelusaleme yĩ katĩ wamo ta kĩndũ kĩvuku.'),
('kam', 'LAM', 1, 18, 'Yeova nĩ mũlũngalu; nũndũ nĩnĩng’endee mwĩao wake: Ĩw’ai, nĩngũmwĩsũva, inyw’ĩ ngo syonthe sya andũ, na sisyai woo wakwa: Eĩtu makwa atheu na anake makwa nĩ aendu me atave.'),
('kam', 'LAM', 1, 19, 'Nĩneetie endwa makwa, ĩndĩ nĩmangengie: Athembi makwa na atumĩa makwa nĩmaumiwe nĩ veva me ndũanĩ, Makĩmantha lĩu wa kũvuũkya mathayũ moo.'),
('kam', 'LAM', 1, 20, 'Sisya, ame Yeova; nũndũ nĩ thĩnanĩ; ngoo yakwa nĩnĩkũũũya; Ngoo yakwa nĩnĩthyũũĩe nthĩnĩ wakwa; nũndũ nĩnĩng’endete mũno: Ũtee ũvyũ nũtuma kũkw’ĩĩwa, mũsyĩ kwĩ ta kĩkw’ũ.'),
('kam', 'LAM', 1, 21, 'Nĩmew’ĩte kana nĩnĩvevũũkaa; vati ũmwe wa kũngiakisya; Amaitha makwa onthe nĩmew’ĩte ũndũ wa thĩna wakwa; nĩmekwĩw’a mũyo nũndũ nĩwĩkĩte ũu: Ũkaete mũthenya ũla ũtavanĩtye, na makeethĩwa mailyĩ takwa.'),
('kam', 'LAM', 1, 22, 'Ũthũku woo w’onthe nũvike mbee waku; Naku ũmeke, o tondũ ũmbĩkĩte ũndũ wa mavĩtyo makwa onthe: Nũndũ mavevũũka makwa nĩ maingĩ, na ngoo yakwa nĩnĩũnyala.'),
('kam', 'LAM', 2, 1, 'A! Mwĩaĩi nũvw’ĩkĩte mwĩĩtu wa Saioni na ĩthweo e mũthatu! Nĩwekisye nthĩ kuma ĩtunĩ wanake wa Isilaeli, Na ndalilikene kavĩla kake ka nyaĩĩ mũthenya wa ũthatu wake.'),
('kam', 'LAM', 2, 2, 'Mwĩaĩi nũmeletye motũo onthe ma Yakovo, na ndew’ĩĩte tei: Nũng’uthũlangĩte ngome syĩ vinya sya mwĩĩtu wa Yuta e mũthilĩku; Nĩwitheetye nthĩ; nũvukĩtye ũsumbĩ na anene me mbee ũsumbĩnĩ.'),
('kam', 'LAM', 2, 3, 'Nũvetete e na ũthatu mwai kĩla ũvya wa Isilaeli; Nũtũngĩte kw’oko kwake kwa aũme kumya mbee wa mũmaitha: Na nũvĩvĩtye Yakovo o ta mwaki mwakanu, ũla ũminaa ngalĩ syonthe.'),
('kam', 'LAM', 2, 4, 'Nũkootete ũta wake ta mũmaitha, nũũngamĩte kw’oko kwake kwa aũme kũilyĩ ta nthũ. Na nĩwũaĩte onthe ala maĩ ma kwendeesya itho: Ĩeemanĩ ya mwĩĩtu wa Saioni nĩwonoetye ũthilĩku wake ta mwaki.'),
('kam', 'LAM', 2, 5, 'Mwĩaĩi nũtw’ĩkĩte ta mũmaĩtha, nũmeletye Isilaelĩ; Nũmeletye nyũmba syake syonthe mbanakavye, nĩwanangĩte ngome syake syĩ vinya; Na nĩwingĩvĩtye kĩmeto na kĩĩo mwĩĩtunĩ wa Yuta.'),
('kam', 'LAM', 2, 6, 'Na nũvetete wĩkalo wake na vinya, o ta wa mũũnda; nĩwanangĩte vandũ vake va kũũmbana: Yeova nĩũlĩthĩtye mboka ĩtw’ĩtwe o na savato ku Saioni, Na nũvũthĩtye mũsumbĩ na mũthembi ũthilĩkunĩ wa ũthatu wake.'),
('kam', 'LAM', 2, 7, 'Mwĩaĩi nĩwĩkĩtye kũasa kĩthembeo kyake, nũthĩthĩte vandũ vake vatheu; Nũnenganĩte mokonĩ ma mũmaitha mawako ma nyũmba syake mbanakavye: Nĩmokĩlĩlye mawasya nyũmbanĩ ya Yeova, o ta mũthenya wa ũmbano ũkilĩtye.'),
('kam', 'LAM', 2, 8, 'Yeova nũtw’ĩte kwananga wako wa mwĩĩtu wa Saioni; Nũtambũũkĩtye ũlii, ndatũngĩte kw’oko kwake aeke kwananga: Na nũtumĩte wiio mũlũmu na wako imeta; nileelaa vamwe.'),
('kam', 'LAM', 2, 9, 'Mbingĩlo syake nithelele nthĩ; nĩwanangĩte na kũtũla ivĩngi syake: Mũsumbĩ wake na anene make me mbee ũsumbĩnĩ me katĩ wa i mbaĩ vala vate mĩao; Ĩĩ, athani make matyonaa woni kuma kwa Yeova.'),
('kam', 'LAM', 2, 10, 'Atumĩa ma mwĩĩtu wa Saioni nĩmekalaa nthĩ, maivindya; Nĩmekisye kĩtoo ĩũlũ wa mĩtwe yoo; nĩmevotoete makunia: Eĩtu atheu ma Yelusaleme nĩmakunamasya mĩtwe yoo kũvika nthĩ.'),
('kam', 'LAM', 2, 11, 'Metho makwa nĩmeũseekea ũndũ wa methoi, ngoo yakwa nĩnĩkũũũya; Ĩtema yakwa nĩ yĩtiku ĩũlũ wa nthĩ, nũndũ wa wanangĩko wa mwĩĩtu wa andũ makwa, Nĩkwĩthĩwa syana nini na tũũkenge nikũnyalĩla nzĩanĩ nene sya ndũa.'),
('kam', 'LAM', 2, 12, 'Nikũlasya aainyia masyo, Lĩu wa mbaa ngetha na mbinyu syĩva? Yĩla ĩũnyalĩla nzĩanĩ nene sya ndũa ta ala okite, Yĩla ngoo yasyo ĩnĩkwonow’a kĩthũinĩ kya aainyia masyo.'),
('kam', 'LAM', 2, 13, 'Ngakũkũsĩĩa ũndũ mwaũ? Ngakũelekan’ya na kyaũ, we mwĩĩtu mũtheu wa Yelusaleme? Ngeanan’ya kyaũ naku, nĩ kana ndonye ũkũkiakisya, we mwĩĩtu mũtheu wa Saioni? Nũndũ ũvũthũe waku nĩ mũnene ta ũkanga: ũla ũtonya ũkũvosya nũũ?'),
('kam', 'LAM', 2, 14, 'Athani maku nĩmakwonee mawoni ma ũvũngũ na ũtumanu; Na matyaavuũa ũthũku waku, makũtũnge wume kũtavwanĩ kwaku, Ĩndĩ nĩmakwonee mĩio ya ũvũngũ na maũndũ ma ũtuma ũlũngw’a.'),
('kam', 'LAM', 2, 15, 'Onthe ala mavĩtaa makũkũnangĩaa mbĩ; Nĩmekũtimba na kũmũthingithĩsya mũtwe mwĩĩtu wa Yelusaleme, makyasya, Ĩno nĩyo ndũa ĩla andũ mamĩtie Wĩanĩu wa wanake, Ũtanu wa nthĩ yonthe?'),
('kam', 'LAM', 2, 16, 'Amaitha maku onthe makwathamĩsye makanyw’a moo mũno; Nĩmatimba na kũvevetan’ya maeo; nĩmekwasya, Nĩtũmũmeletye; Vate ndĩi ũmũnthĩ nĩ mũthenya ũla tweteelete; nĩtũwĩlĩte, nĩtũwonete.'),
('kam', 'LAM', 2, 17, 'Yeova nĩwĩkĩte ũndũ watw’ĩte; nĩwĩanĩĩtye ndeto yake ĩla weaie mĩthenya ya tene; Nĩwekisye nthĩ, na ndaew’ĩa tei: Na nũtumĩte mũmaitha atana ĩũlũ waku; nũnenevetye ũvya wa nthũ syaku.'),
('kam', 'LAM', 2, 18, 'Ngoo syoo nĩsyamwĩkaĩlile Mwĩaĩi: We wako wa mwĩĩtu wa Saioni, methoi matheee ta ũsĩ mũthenya na ũtukũ; Ndũkeenenge ũthũmũo: ndũkaeke kyũma kya itho yaku kĩkilye.'),
('kam', 'LAM', 2, 19, 'Ũkila, kaya ũtukũ, wambĩlĩlyonĩ wa mosyaĩĩsyo; Onosya ngoo yaku ta kĩw’ũ mbee wa ũthyũ wa Yeova: Ũmũkĩlĩlye moko maku ũndũ wa thayũ wa syana syaku nini, ila ĩkũnyalĩla nĩ nzaa wambĩlĩlyonĩ wa kĩla nzĩa nene.'),
('kam', 'LAM', 2, 20, 'Ona, ame Yeova, na sisya ũla wamwĩkie ũu! Aka makaya ũsyao woo, o syana ila ithakaw’a mokonĩ? Mũthembi na mwathani makooaĩwa vandũ vatheu va Mwĩaĩi?'),
('kam', 'LAM', 2, 21, 'Ũla wa ĩika na mũtumĩa nĩmakomaa nthĩ nzĩanĩ nene; Eĩtu makwa atheu na anake makwa nĩmavalũkĩtw’e na ũvyũ: Nũmoaĩte mũthenya wa ũthatu waku; nĩwũaĩte, na ndwaew’ĩa tei.'),
('kam', 'LAM', 2, 22, 'Nũmbĩtĩe motĩsyo makwa maume ngalĩ syonthe, o ta mũthenya wa ũmbano ũkilĩtye; Na vatyaĩ ũmwe wavonokie kana kũtiala mũthenya wa ũthatu wa Yeova: Asu ala nathakasya na kũea mũmaitha wakwa nũmaminĩte.'),
('kam', 'LAM', 3, 1, 'Ninyie mũndũ ũla wonete thĩna nũndũ wa ndata ya ũthilĩku wake.'),
('kam', 'LAM', 3, 2, 'Nĩwandongoesye na kũtuma nĩkinya kĩvindunĩ, na ti kyeninĩ.'),
('kam', 'LAM', 3, 3, 'Vate ndĩi nũnthyũũĩaa kw’oko kwake ĩngĩ na ĩngĩ mũthenya w’onthe.'),
('kam', 'LAM', 3, 4, 'Nyama yakwa na kĩkonde kyakwa nĩwitw’ĩkĩthĩtye ngũũ; nũtũlĩte mavĩndĩ makwa.'),
('kam', 'LAM', 3, 5, 'Nĩwambakĩĩe, na kũnthyũlũlũkya na nyongo na thĩna.'),
('kam', 'LAM', 3, 6, 'Nũmbĩkalĩtye kũndũ kwĩ kĩvindu, o ta ala makwie tene.'),
('kam', 'LAM', 3, 7, 'Nũnziĩĩĩte, ũkethĩa nditonya kumaala; nũtw’ĩkĩthĩtye mũnyololo wakwa mũito.'),
('kam', 'LAM', 3, 8, 'Ĩĩ, yĩla ngũkaya na kwĩtya ũtethyo, nũnũũsiĩĩa mboya yakwa.'),
('kam', 'LAM', 3, 9, 'Nũvingĩte nzĩa syakwa na mavia masũvye; nũthyoeketye nzĩa syakwa.'),
('kam', 'LAM', 3, 10, 'Ailyĩ kwakwa ta nduva ĩkyoveesya, ta mũnyambũ kũndũ kwa syĩmbithĩ.'),
('kam', 'LAM', 3, 11, 'Nĩwelelũkilye nzĩa syakwa, na kũndembũanga ilungu; nũndw’ĩkĩthĩtye mũthei.'),
('kam', 'LAM', 3, 12, 'Nũkootete ũta wake, na kũmbia ta ũvano wa kũathwa na mũsyĩ.'),
('kam', 'LAM', 3, 13, 'Nũtumĩte mĩsyĩ ya thyaka wake ilĩka kĩlilikanonĩ kyakwa.'),
('kam', 'LAM', 3, 14, 'Nĩnĩtw’ĩkĩte wa kũthekwa kwa andũ makwa onthe, na wathi woo mũthenya w’onthe.'),
('kam', 'LAM', 3, 15, 'Nũmbusũĩtye na ũũ, nũmbũnĩthĩtye vyũ na kĩndũ kĩ ũũ.'),
('kam', 'LAM', 3, 16, 'Nũtũlĩte maeo makwa na tũvila twa thaathai; nũmbakangĩte mũu.'),
('kam', 'LAM', 3, 17, 'Nũvetete ngoo yakwa kũasa na mũuo; noolwa nĩ ũunĩko.'),
('kam', 'LAM', 3, 18, 'Nakwa naisye, Vinya wakwa nĩwaĩte, o na wĩkwatyo wakwa vala ve Yeova.'),
('kam', 'LAM', 3, 19, 'Lilikana ũnyamao wakwa na thĩna wakwa, kĩndũ kĩ ũũ na nyongo.'),
('kam', 'LAM', 3, 20, 'Kũvika na yu ngoo yakwa nĩnĩkũmalilikana, na kwĩnyivĩsya nthĩnĩ wakwa.'),
('kam', 'LAM', 3, 21, 'Ũu nĩngũlilikana; kwondũ wa ũu nĩ na wĩkwatyo.'),
('kam', 'LAM', 3, 22, 'Nũndũ wa moseo me wendo ma Yeova tũtikũminwa, nĩkwĩthĩwa matei make matithelaa.'),
('kam', 'LAM', 3, 23, 'Nĩ meũ kĩla kĩoko; kĩthito kyaku nĩ kĩnene mũno.'),
('kam', 'LAM', 3, 24, 'Yeova nĩ kĩanda kyakwa, yĩasya ũu ngoo yakwa; kwondũ wa ũu ngamwĩkwatya.'),
('kam', 'LAM', 3, 25, 'Yeova nĩ mũseo kwa ala mamweteelaa, kwa ngoo ĩla ĩmũmanthaa.'),
('kam', 'LAM', 3, 26, 'Nĩ ũseo mũndũ ethĩwe na wĩkwatyo na kweteela na ũuu ũtangĩĩo wa Yeova.'),
('kam', 'LAM', 3, 27, 'Nĩ ũseo kwa mũndũ kũkua ĩsoki wananĩ wake.'),
('kam', 'LAM', 3, 28, 'Nĩekale e weka na kũvindya, nĩkwĩthĩwa nũmwilĩĩle yo.'),
('kam', 'LAM', 3, 29, 'Nĩekĩe kanyw’a wake kĩtoonĩ, ethĩwa nĩw’o kũtonya kwĩthĩwa wĩkwatyo.'),
('kam', 'LAM', 3, 30, 'Nanengane ĩtau yake kwa ũla ũnũũmũkũna; nausũwe ki nĩ kũvũthw’a.'),
('kam', 'LAM', 3, 31, 'Nũndũ Mwĩaĩi ndakekya ũtee tene na tene.'),
('kam', 'LAM', 3, 32, 'O na kau nũnũkwĩw’ĩthya woo, ĩndĩ akeew’ĩa tei kwĩanana na wingĩ wa moseo make me wendo.'),
('kam', 'LAM', 3, 33, 'Nũndũ ndathĩnasya na kwenda, kana kũmew’ĩthya woo ana ma andũ.'),
('kam', 'LAM', 3, 34, 'Kũkinyangĩa ala ove onthe ma nthĩ ungu wa maũũ,'),
('kam', 'LAM', 3, 35, 'Kwathũkya kĩanda kya mũndũ mbee wa ũthyũ wa Ũla Wĩ Ĩũlũ wa Onthe,'),
('kam', 'LAM', 3, 36, 'Kũmũvĩtĩthya mũndũ ũvoonĩ wake, Mwĩaĩi ndetĩkĩlaa.'),
('kam', 'LAM', 3, 37, 'Nũũ ũla ũneenaa, na ũkekĩka, yĩla Mwĩaĩi ũtanawĩaĩa?'),
('kam', 'LAM', 3, 38, 'Kuma kanyw’anĩ wa Ũla Wĩ Ĩũlũ wa Onthe kũtyumaa ũthũku na ũseo?'),
('kam', 'LAM', 3, 39, 'Nũndũ wa kĩ mũndũ wĩ thayũ nũnyungunyĩasya, o mũndũ nũndũ wa ũsilĩlo wa naĩ syake?'),
('kam', 'LAM', 3, 40, 'Tũthianei na kũtata nzĩa sitũ, na kũmwĩthyũũĩa Yeova ĩngĩ.'),
('kam', 'LAM', 3, 41, 'Tũmũkĩlĩlyei Ngai ũla wĩ matunĩ ngoo sitũ vamwe na moko maitũ.'),
('kam', 'LAM', 3, 42, 'Nĩtũvĩtĩtye o na kũng’enda; ndwaaekea.'),
('kam', 'LAM', 3, 43, 'Nĩwĩvw’ĩkĩte ũthatu na kũtũatĩĩa; nĩwũaĩte, ndwaew’ĩa tei.'),
('kam', 'LAM', 3, 44, 'Nĩwĩvw’ĩkĩte ĩthweo, ũkethĩwa mboya o na yĩva ndĩtonya kũvĩta.'),
('kam', 'LAM', 3, 45, 'Nũtũtw’ĩkĩthĩtye ũvaavao na mavutĩ katĩ wa ngo sya andũ.'),
('kam', 'LAM', 3, 46, 'Amaitha maitũ onthe nĩmatwathamĩsye kanyw’a woo mũno.'),
('kam', 'LAM', 3, 47, 'W’ĩa na yĩla ĩima nitũkĩe, o na kĩtuu na wanangĩko.'),
('kam', 'LAM', 3, 48, 'Itho yakwa nĩyĩkũnyũlũlũkya tũlũsĩ twa methoĩ, ũndũ wa wanangĩko wa mwĩĩtu wa andũ makwa.'),
('kam', 'LAM', 3, 49, 'Itho yakwa nĩyĩkonosya, na yĩtikũeka, vate kũtĩĩa,'),
('kam', 'LAM', 3, 50, 'Kũvika yĩla Yeova wĩsisya nthĩ, na kwona e ĩtunĩ.'),
('kam', 'LAM', 3, 51, 'Itho yakwa nĩyĩũthĩn’ya ngoo yakwa, nũndũ wa eĩtu onthe ma ndũa yakwa.'),
('kam', 'LAM', 3, 52, 'Nĩmanzyĩmĩte mũno ta nyũnyi, ala me amaitha makwa vate kĩtumi.'),
('kam', 'LAM', 3, 53, 'Nĩmavetete thayũ wakwa kasũmbanĩ ke nthĩnĩ wa nthĩ, na kwĩkya ĩvia ĩũlũ wakwa.'),
('kam', 'LAM', 3, 54, 'Manzĩ maingĩ nĩmavĩtĩle ĩũlũ wa mũtwe wakwa; naisye, Nyĩe nĩ mũvete.'),
('kam', 'LAM', 3, 55, 'Nĩneekaĩlile syĩtwa yaku, ame Yeova, nĩ kasũmbanĩ ke nthĩnĩ wa nthĩ mũno mbee.'),
('kam', 'LAM', 3, 56, 'Nĩweewie wasya wakwa: ndũkavithe kũtũ kwaku ũndũ wa kũveva kwakwa, ũndũ wa kũkaya kwakwa.'),
('kam', 'LAM', 3, 57, 'Nĩwathengeeie mũthenya ũla nakwĩkaĩlile; waisye, Ndũkakĩe.'),
('kam', 'LAM', 3, 58, 'Ame Mwĩaĩi, nĩwateteie maũndũ ma ngoo yakwa; nĩwoovoisye thayũ wakwa.'),
('kam', 'LAM', 3, 59, 'Ame Yeova, nĩwonete ũndũ nĩkĩtwe; sila ũvoo wakwa.'),
('kam', 'LAM', 3, 60, 'Nĩwonete kwĩĩvanĩsya kwoo kw’onthe na mosũanĩo moo onthe ĩũlũ wakwa.'),
('kam', 'LAM', 3, 61, 'Nĩwĩw’ĩte kĩvũthya kyoo, ame Yeova, na mosũanĩo moo onthe ĩũlũ wakwa,'),
('kam', 'LAM', 3, 62, 'Ilomo sya ala mambũkĩlĩle, na ũsũanĩo woo ĩũlũ wakwa mũthenya w’onthe.'),
('kam', 'LAM', 3, 63, 'Sisya kwĩkala nthĩ kwoo, na kũkĩla kwoo; ninyie wathi woo.'),
('kam', 'LAM', 3, 64, 'Ũkamatũngĩa wĩkũle, ame Yeova, kwĩanana na wĩa wa moko moo.'),
('kam', 'LAM', 3, 65, 'Ũkamanenga wũmũ wa ngoo, kĩumo kyaku kwoo.'),
('kam', 'LAM', 3, 66, 'Ũkamaatĩĩa wĩ mũthatu, na kũmananga maume ĩtheo wa matu ma Yeova.'),
('kam', 'LAM', 4, 1, 'A! Thaavu nũvukĩte! Thaavu ũla mũtheu mbee kaĩ nũalyũkĩte! Mavia ma vala vandũ vatheu nĩmekwĩtwa wambĩlĩlyonĩ wa kĩla nzĩa.'),
('kam', 'LAM', 4, 2, 'Ana ma Saioni ala me vata mũno, meanene na thaavu mũseo mũno, Kaĩ nĩmatalawa ta itete sya yũmba, wĩa wa moko ma mũmbi!'),
('kam', 'LAM', 4, 3, 'O na mbĩwa nasyo nikusasya nondo, nĩsyongasya tũswii twasyo: Mwĩĩtu wa andũ makwa nũtw’ĩkĩte mwai, ta nyaa sya weũnĩ.'),
('kam', 'LAM', 4, 4, 'Ũĩmĩ wa kana kala kongaa nũlũmanasya na kaakaa wa kanyw’a wako nũndũ wa waũni: Syana nini nĩsyĩtasya imũtũ, na vati mũndũ winengae.'),
('kam', 'LAM', 4, 5, 'Ala maie liu mũseo, me ooka nzĩanĩ nene: Ale maeiwe mevw’ĩkĩte ngũa ndune mũno nĩmekwĩvĩtĩĩsya ũtũnda.'),
('kam', 'LAM', 4, 6, 'Nũndũ ũthũku wa mwĩĩtu wa andũ maku nĩ mũnene kwĩ naĩ sya Sotomo, Ĩla yang’uthũlilwe o kavinda kanini, na vatyaĩ moko mailĩĩlwe ĩũlũ wayo.'),
('kam', 'LAM', 4, 7, 'Anene make me ndaĩa maĩ atheu kũvitũka ĩa, maĩ eũ kwĩ ĩia; Maĩ atune mĩĩnĩ kwĩ tũvila twa maliani, kũtendea kwoo kwailyĩ ta kwa savili.'),
('kam', 'LAM', 4, 8, 'Mothyũ moo nĩ maiũ mũno kwĩ makaa; maimanyĩka me nzĩanĩ nene: Kĩkonde kyoo nĩkĩlũmanĩte na mavĩndĩ moo; nĩkyũmĩte, nĩkĩtw’ĩkĩte ta mũtĩ.'),
('kam', 'LAM', 4, 9, 'Ala mooaiwe nĩ ũvyũ me kavaa kwĩ ala mooaiwe nĩ nzaa; Nũndũ aa nĩmang’ong’aa, mang’ong’a vyũ, nũndũ wa kwaĩwa nĩ mosyao ma mũũndanĩ.'),
('kam', 'LAM', 4, 10, 'Moko ma aka me tei nĩmauĩte syana syoo ene; Nĩsyo syaĩ lĩu woo ĩvinda ya kwanangwa kwa mwĩĩtu wa andũ makwa.'),
('kam', 'LAM', 4, 11, 'Yeova nĩwĩanĩtye ũthilĩku wake, nĩwonoetye ũthatu wake mwai; Na nĩwakanĩtye mwaki Saioni, ũla ũminĩte myambĩlĩlyo yayo.'),
('kam', 'LAM', 4, 12, 'Asumbĩ ma nthĩ matyaaĩtĩkĩla, o na andũ onthe ala matwĩe nthĩ, Kana nthũ na mũmaitha nĩmakavota mbingĩlonĩ sya Yelusaleme.'),
('kam', 'LAM', 4, 13, 'Kĩtumi nĩ ũndũ wa naĩ sya athani mayo, na mothũku ma athembi mayo, Ala metĩkisye nthakame ya ala alũngalu nthĩnĩ wayo.'),
('kam', 'LAM', 4, 14, 'Nĩmangangaa ta ililinda nzĩanĩ nene, nĩmevukĩtye na nthakame, Ũkethĩa andũ matitonya kũkiita ngũa syoo.'),
('kam', 'LAM', 4, 15, 'Mamatavisye, Endai inyw’ĩ, Avuku! Endai, endai, mũikakiite! Yĩla makĩie na kwanganga, andũ maneenie katĩ wa i mbaĩ, Matikekala vaa ĩngĩ.'),
('kam', 'LAM', 4, 16, 'Ũthatu wa Yeova nũmanyaĩĩkĩtye; ndakamasyaĩĩsya ĩngĩ: Matyaataĩa athembi, matyaamenda atumĩa.'),
('kam', 'LAM', 4, 17, 'Metho maitũ o na yu nĩmeũseekea makĩsyaĩĩsya ũndũ wa ũtethyo witũ wa mana: Kweteelanĩ kwitũ nĩtweteelile mbaĩ ĩtatonya kũtangĩĩa.'),
('kam', 'LAM', 4, 18, 'Nĩmeũsyĩma matambya maitũ, na kwondũ wa ũu tũtitonya kũthi nzĩanĩ sitũ nene: Mũminũkĩlyo witũ wĩ vakuvĩ, mĩthenya yaitũ nĩ mĩanĩsye; nũndũ mũminũkĩlyo witũ nĩ mũku.'),
('kam', 'LAM', 4, 19, 'Ala matũatĩĩe maĩ mĩtũkĩ kwĩ ndiũ sya matunĩ: Nĩmatũvikĩlile iĩmanĩ, nĩmatwoveeisye weũnĩ.'),
('kam', 'LAM', 4, 20, 'Mĩthũmũ ya manyiũũ maitũ, mwĩtĩkĩw’a mauta wa Yeova, nĩwakwatĩwe maimanĩ moo; Ũla twaneenie ũndũ wake, Ungu wa muunyĩ wake tũkekalaa thayũ katĩ wa i mbaĩ.'),
('kam', 'LAM', 4, 21, 'Tana na kwĩw’a mũyo, we mwĩĩtu wa Etomu, ũla ũtũaa nthĩ yĩtawa Usi: Kĩkombe kĩkavĩtĩla kũvika vala ũĩ; ũkeethĩwa ũtoonetw’e, na kwĩtw’ĩkĩthya mwene mũthei.'),
('kam', 'LAM', 4, 22, 'Ũsilĩlo wa ũthũku waku nĩwĩanĩtw’e, we mwĩĩtu wa Saioni; ndakakũtwaa ĩngĩ wĩ mũtave: Akasilĩla ũthũku waku, we mwĩĩtu wa Etomu; akavuũa naĩ syaku.'),
('kam', 'LAM', 5, 1, 'Lilikana, ame Yeova, ũndũ ũla wũkie ĩũlũ waitũ: Sisya, noiona kũvũthw’a kwitũ.'),
('kam', 'LAM', 5, 2, 'Ũtiĩwa witũ nũalyũlitwe wĩthĩwe wa aeni, Nyũmba sitũ syĩthĩwe sya andũ ma nthĩ ĩngĩ.'),
('kam', 'LAM', 5, 3, 'Twĩ atiwa ala makw’ĩĩwe nĩ aaĩthe; Aainyia maitũ no ta ndiwa.'),
('kam', 'LAM', 5, 4, 'Nĩtũnyw’ĩte manzĩ maitũ kwondũ wa mbesa; Ngũ sitũ nĩ sya thooa.'),
('kam', 'LAM', 5, 5, 'Ala matũatĩĩaa me ngingonĩ sitũ: Twĩ na mĩnoo, na tũti na ũthũmũo.'),
('kam', 'LAM', 5, 6, 'Nĩtũmanengete Amisili kw’oko, O na Aasuli, tũvũnw’e nĩ imũtũ.'),
('kam', 'LAM', 5, 7, 'Aaĩthe maitũ nĩmeekie naĩ, na ti vo maĩ; Na ithyĩ nĩtũkuĩte mothũku moo.'),
('kam', 'LAM', 5, 8, 'Athũkũmi nĩmatũsumbĩkaa: Vati ũmwe wa kũtũvonokya mokonĩ moo.'),
('kam', 'LAM', 5, 9, 'Nĩtũkwona lĩu witũ mũisyonĩ wa mathayũ maitũ, Nũndũ wa ũvyũ wa waũni.'),
('kam', 'LAM', 5, 10, 'Kĩkonde kitũ nĩ kiũ ta iko. Nũndũ wa ĩvyũvĩ ya muutĩa wa yũa.'),
('kam', 'LAM', 5, 11, 'Nĩmakindie aka ma Saioni, Eĩtu atheu ma ndũanĩ sya Yuta.'),
('kam', 'LAM', 5, 12, 'Anene me mbee ũsumbĩnĩ masũw’a na moko moo: Mothyũ ma atumĩa matyaataĩwa.'),
('kam', 'LAM', 5, 13, 'Anake nĩmakuĩe mavia ma ũthia; Na syana nĩsyalulutĩkile ĩkuĩte ngũ.'),
('kam', 'LAM', 5, 14, 'Atumia nĩmaekie kwĩkala mbingĩlonĩ, Na anake wini woo.'),
('kam', 'LAM', 5, 15, 'Ũtanu wa ngoo sitũ nũthelete; Kũsunga kwitũ nĩkũalyũkĩte kũtw’ĩke kũmeta.'),
('kam', 'LAM', 5, 16, 'Ngovia ya ũsumbĩ nĩ mbalũku kuma mũtwenĩ witũ: Woo nĩ witũ! Nũndũ nĩtwĩkĩte naĩ.'),
('kam', 'LAM', 5, 17, 'Nũndũ wa ũu ngoo sitũ nĩ ndevu; Nũndũ wa maũndũ asu metho maitũ me na mbindu;'),
('kam', 'LAM', 5, 18, 'Nũndũ wa kĩĩma kya Saioni, kĩla kĩthei: Mbĩwa nikinyaa ĩũlũ wakyo.'),
('kam', 'LAM', 5, 19, 'We, ame Yeova, nĩwĩkalaa tene na tene; Kĩvĩla kyaku kya ũsumbĩ nĩkĩkalaa kuma nzyawa na nzyawa.'),
('kam', 'LAM', 5, 20, 'Nũndũ wa kĩ woolilwe nĩ ithyĩ tene na tene, Na kũtũtia ĩvinda yĩasavĩte ũu?'),
('kam', 'LAM', 5, 21, 'Tũthyũũe ithyĩ kwaku, ame Yeova, na tũkathyũũĩka; Eũvya mĩthenya yaitũ o ta tene.'),
('kam', 'LAM', 5, 22, 'Ĩndĩ nũtũleete vyũ; Nũtũthilĩkĩle mũno.'),
('kam', 'EZK', 1, 1, 'Na kweethĩwa mwaka wa mĩongo ĩtatũ, mwei wa kana, mũthenya wa katano wa mwei, yĩla naĩ vamwe na ala atave vakuvĩ na ũsĩ wa Kevali, matu mavingũka, na noona mawoni ma Ngai.'),
('kam', 'EZK', 1, 2, 'Mũthenya wa katano wa mwei, naw’o waĩ mwaka wa katano wa kũtavwa kwa mũsumbĩ Yeoiakini,'),
('kam', 'EZK', 1, 3, 'mũthembĩ Esekieli, mwana wa Vusi, ookiwe nĩ ndeto ya Yeova ki, e nthĩ ya Akalitei vakuvĩ na ũsĩ wa Kevali; na kw’oko kwa Yeova kwaĩ ĩũlũ wake kw’o.'),
('kam', 'EZK', 1, 4, 'Na nonie, na, sisya, kĩseve kĩnene kyauma ngalĩ ya ĩũlũ, ĩthweo ĩnene, yĩ na mwaki wĩyakanĩtye, na ũtisu ũyĩthyũlũlũkĩte, na kuma katĩ waw’o kwaĩ kĩndũ kyailyĩ ũthuku wakakaa, kuma katĩ wa mwaki.'),
('kam', 'EZK', 1, 5, 'Na kuma katĩ waw’o kwookie mũvw’ano wa syũmbe inya syĩ thayũ. Na mũvw’anĩle wasyo nĩ ũũ: Syaĩ na mũvw’ano wa mũndũ;'),
('kam', 'EZK', 1, 6, 'na kĩla kĩmwe kyaĩ na mothyũ ana, na kĩla kĩmwe kyasyo kyaĩ na nthwau inya.'),
('kam', 'EZK', 1, 7, 'Na maũũ masyo maĩ malũngalu; na nyaĩĩ sya maũũ masyo syailyĩ ta ũnyaĩĩ wa kũũ kwa kasaũ; na syatisatisaa ta ũthuku mũkute.'),
('kam', 'EZK', 1, 8, 'Na syaĩ na moko ta ma mũndũ ungu wa nthwau syasyo mavavanĩ masyo ana; na isu inya syaĩ na mothyũ masyo na nthwau syasyo ta ũũ;'),
('kam', 'EZK', 1, 9, 'nthwau syasyo syakwatene ũmwe na ũla ũngĩ; ityeethyũũaa yĩla syaendaa; syaendaa kimwe na kĩmwe ilũngalĩte.'),
('kam', 'EZK', 1, 10, 'Ũndũ wa mũvw’ano wa mothyũ masyo, syaĩ na ũthyũ wa mũndũ; na isu inya syaĩ na ũthyũ wa mũnyambũ ngalĩ ya kw’oko kwa aũme; na isu inya syaĩ na ũthyũ wa ng’ombe ngalĩ ya kw’oko kwa aka; na isu inya nasyo syaĩ na ũthyũ wa ndiũ.'),
('kam', 'EZK', 1, 11, 'Na mothyũ masyo na nthwau syasyo nĩsyataanĩsye ngalĩ ya ĩũlũ; nthwau ilĩ sya kĩla kĩmwe nĩsyakwatene ũmwe na ũla ũngĩ, na ilĩ syavw’ĩkĩte mĩĩ yasyo.'),
('kam', 'EZK', 1, 12, 'Na syaendaa mbee kĩmwe na kĩmwe ilũngalĩte: o kũla veva wendaa ũthĩ, nasyo ikĩthi; ityeethyũũaa yĩla syaendaa.'),
('kam', 'EZK', 1, 13, 'Ũvoo wa mũvw’ano wa syũmbe isu inya syĩ thayũ, mũvw’anĩle wasyo wailyĩ ta makaa makanu ma mwaki, ta mũvw’anĩle wa maũmũĩ; mwaki waendaa kũũ na kũũ katĩ wa syũmbe isu syĩ thayũ; na mwaki waĩ na kyeni mũno, na mwakinĩ kwaumie ũtisi.'),
('kam', 'EZK', 1, 14, 'Na syũmbe isu syĩ thayũ syasembaa na kũsyoka ta kwoneka kwa ũtisi.'),
('kam', 'EZK', 1, 15, 'Na yĩla nasiasya syũmbe isu syĩ thayũ, sisya, ndĩa ĩmwe ĩkinyĩte nthĩ ũtee wa syũmbe isu syĩ thayũ, kwondũ wa kĩla ũthyũ wa mothyũ ana makyo.'),
('kam', 'EZK', 1, 16, 'Mũvw’anĩle wa ndĩa na mũseũvĩlw’e wasyo wailyĩ nzumalati ntheu: na isu inya syaĩ na mũvw’ano ũmwe; na mũvw’anĩle wasyo na mũseũvĩlw’e wasyo waĩ ta ndĩa nthĩni wa ndĩa.'),
('kam', 'EZK', 1, 17, 'Yĩla syaendaa, syaendaa ngalĩ syasyo inya: ityeethyũũaa yĩla syaendaa.'),
('kam', 'EZK', 1, 18, 'Undũ wa ndĩa syasyo, syaĩ ndũlu ũndũ itĩsya, na ila ndĩa inya syausũĩte metho ndĩanĩ syasyo ngalĩ syonthe.'),
('kam', 'EZK', 1, 19, 'Na yĩla syũmbe isu syĩ thayũ syaendaa, ndĩa nasyo nĩsyaendaa ũtee wasyo; na yĩla syũmbe isu syĩ thayũ syookĩlaw’a kuma nthĩ, ndĩa nasyo nĩsyookĩlaw’a.'),
('kam', 'EZK', 1, 20, 'O kũla veva wendaa kũthi, nĩkw’o syaendaa; kũla veva wendaa kũthi: na ndĩa syookĩlaw’a ũtee wasyo: nũndũ veva wa kyũmbe kĩ thayũ waĩ ndĩanĩ.'),
('kam', 'EZK', 1, 21, 'Yĩla isu syaendaa, o na ii nasyo ikĩenda; na yĩla isu syaũngamaa, ii nasyo ikĩũngama; na yĩla isu syookĩlaw’a kuma nthĩ, ndĩa nasyo ikyũkĩlw’a ũtee wasyo; nũndũ veva wa kyũmbe kĩ thavũ waĩ ndĩanĩ.'),
('kam', 'EZK', 1, 22, 'Na ĩũlũ wa mũtwe wa kyũmbe kĩ thayũ kwaĩ mũvw’ano wa yayaya, kwa kũsiwa, yailyĩ ta kĩsisyo kĩtisu kya ũtĩsya, yĩtambũũkĩtw’e ĩũlũ wa mĩtwe yasyo.'),
('kam', 'EZK', 1, 23, 'Na ungu wa ĩ yayaya nthwau syasyo nĩsyatambũũkĩtw’e, ũmwe welekele ũla ũngĩ: kĩla kĩmwe kyaĩ na ilĩ ila syavw’ĩkĩte mĩĩ yasyo ngalĩ ĩno, na kĩla kĩmwe kyaĩ na ilĩ ila syavw’ĩkĩte ngalĩ ĩla ĩngĩ.'),
('kam', 'EZK', 1, 24, 'Na yĩla syaendaa, newie kĩuumo kya nthwau syasyo ta kĩlitũko kya manzĩ maingĩ, ta wasya wa Mwene Vinya W’onthe, kĩlonzo kya kĩtuu ta kĩlonzo kya nguthu: yĩla syaũngamaa, syatheeasya nthwau syasyo.'),
('kam', 'EZK', 1, 25, 'Na kwaĩ wasya ĩũlũ wa yayaya yĩla yaĩ ĩũlũ wa mĩtwe yasyo: yĩla syaũngamaa, syatheeasya nthwau syasyo.'),
('kam', 'EZK', 1, 26, 'Na ĩũlũ wa yayaya yĩla yaĩ ĩũlũ wa mĩtwe yasyo kwaĩ mũvw’ano wa kĩvĩla kya ũsumbĩ, ta kwoneka kwa kavila ka savili; na ĩũlũ wa mũvw’ano wa kĩvĩla kyu kwaĩ mũvw’ano kwoneka kwaw’o wailyĩ ta mũndũ ĩũlũ wakyo.'),
('kam', 'EZK', 1, 27, 'Na noona kĩndũ kĩilyĩ ũthuku wakakaa, ta mũvw’anĩle wa mwaki nthĩnĩ waw’o ũthyũlũlũkĩte, kuma mũvw’anĩlenĩ wa kĩnyunyu kyake na kwambata; na kuma mũvw’anĩlenĩ wa kĩnyunyu kyake na kũtheea noona mũvw’anĩle wa mwaki, na kwaĩ ũtisu wamũthyũlũlũkĩte.'),
('kam', 'EZK', 1, 28, 'Ta mũvw’anĩle wa ũtaathi ĩthweonĩ mũthenya wa mbua, now’o wailyĩ mũvw’anĩle wa ũtisu ngalĩ syonthe. Ũũ nĩw’o wailyĩ mũvw’ano wa ũtheu mũtisu wa Yeova. Na yĩla namonie, navalũka na ũthyũ wakwa, na neew’a wasya wa ũmwe ũla waneenie.'),
('kam', 'EZK', 2, 1, 'Na ambĩa, Mwana wa mũndũ, ũngama na maũũ maku, na nganeena naku.'),
('kam', 'EZK', 2, 2, 'Na Veva alika nthĩnĩ wakwa yĩla waneenie nakwa, na anũngamya na maũũ makwa; na neew’a ũla waneenie nakwa.'),
('kam', 'EZK', 2, 3, 'Na ambĩa, Mwana wa mũndũ, nĩngũũtũma kwa ana ma Isilaeli, kwa mbaĩ ila ng’endu, ila syambaie matũ: nao na aaĩthe moo nĩmambĩtanĩasya o na kũvika ũmũnthĩ.'),
('kam', 'EZK', 2, 4, 'Na ana asu me na mothyũ metu na ngoo nyũmũ: nĩngũũtũma kwoo; na ũkamatavya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya.'),
('kam', 'EZK', 2, 5, 'Nao, ethĩwa makeew’a, kana matikew’a (nũndũ nĩ nyũmba ng’endu), nĩmakamanya kana kwaĩ mwathani katĩ woo.'),
('kam', 'EZK', 2, 6, 'Naku, mwana wa mũndũ, ndũkamakĩe, o na ndũkakĩe ndeto syoo, o na kau mĩtae na mĩw’a syĩ vamwe naku, naku nũtũaa katĩ wa ing’auũ; ndũkakĩe ndeto syoo, o na ndũkateve nũndũ wa mothyũ moo, o na kau nĩ nyũmba ng’endu.'),
('kam', 'EZK', 2, 7, 'Na ũkamatavya ndeto syakwa, ethĩwa makeew’a, kana matikew’a; nũndũ nĩ ang’endu ki.'),
('kam', 'EZK', 2, 8, 'Ĩndĩ we, mwana wa mũndũ, ĩthukĩĩsye ũndũ ngũkwĩa; ndũkethĩwe wĩ mũng’endu ta nyũmba ĩsu ng’endu: athamya kanyw’a waku, ũye kĩla ngũũnenga.'),
('kam', 'EZK', 2, 9, 'Na yĩla nasyaisye, sisya, kw’oko kũndambũũkĩe; na sisya, ĩvuku ĩkũnze yaĩ ũ kw’okonĩ;'),
('kam', 'EZK', 2, 10, 'na ayĩvuanĩsya mbee wakwa: na yaĩ ĩandĩke nthĩnĩ na ũtheinĩ; na kwaandĩkĩtwe nthĩnĩ wayo iĩo, na ĩmeto, na mawoo.'),
('kam', 'EZK', 3, 1, 'Na ambĩa, Mwana wa mũndũ, ya kĩla wĩona; ya ĩvuku yĩĩ ĩkũnze, noithi, ũneene na nyũmba ya Isilaeli.'),
('kam', 'EZK', 3, 2, 'Kwondũ wa ũu naathamya kanyw’a wakwa, na atuma nĩyĩya yĩla ĩvuku ĩkũnze.'),
('kam', 'EZK', 3, 3, 'Na ambĩa, Mwana wa mũndũ, ĩthya ĩvu yaku, na vũnĩthya nda yaku na ĩvuku yĩĩ ĩkũnze yĩla ngũũnenga. Nĩvo ĩndĩ nayĩĩe; na kanyw’anĩ wakwa yaĩ mũyo ta ũkĩ wa nzũkĩ.'),
('kam', 'EZK', 3, 4, 'Na ambĩa, Mwana wa mũndũ, enda, ũthi kwa nyũmba ya Isilaeli, noineena nao na ndeto syakwa.'),
('kam', 'EZK', 3, 5, 'Nũndũ ndũtũmĩtwe kwa andũ ma kĩneeno kĩeni na kĩthyomo kĩ vinya, ĩndĩ kwa nyũmba ya Isilaeli;'),
('kam', 'EZK', 3, 6, 'ti kwa ngo mbingĩ sya andũ ila syĩ na kĩneeno kĩeni no kĩthyomo kĩ vinya, ila ũtatonya kũmanya ndeto syasyo. Vate ndĩi, kethĩwa nĩnakũtũmie kwoo, no kũkwĩthukĩĩsya.'),
('kam', 'EZK', 3, 7, 'Ĩndĩ nyũmba ya Isilaeli ndĩkakwĩthukĩĩsya; nũndũ matimbĩthukĩĩasya nyie: nũndũ nyũmba yonthe ya Isilaeli me na kĩtulya kyetu na ngoo nyũmũ.'),
('kam', 'EZK', 3, 8, 'Sisya, nĩnetetye ũthyũ waku welekele mothyũ moo, na nĩnetetye kĩtulya kyaku kyelekele itulya syoo.'),
('kam', 'EZK', 3, 9, 'Nĩnĩtw’ĩkĩthĩtye kĩtulya kyaku kyũmũ mũno kwĩ ĩvia yũmũ ya ũana: ndũkamakĩe, o na ndũkateve ũndũ wa mothyũ moo, o na kau nĩ nyũmba ng’endu.'),
('kam', 'EZK', 3, 10, 'Na ĩngĩ ambĩa, Mwana wa mũndũ, ndeto syakwa syonthe ila nganeena naku syosae ngoonĩ yaku, na syĩw’ae na matũ maku.'),
('kam', 'EZK', 3, 11, 'Na enda, ũthi vala ve ala matavĩtwe, vala ve ana ma andũ maku, ũneene nao, noimatavya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya; ethĩwa makeew’a, kana matikew’a.'),
('kam', 'EZK', 3, 12, 'Nĩvo ĩndĩ Veva wambũkĩlilye, na neew’a ĩtina wakwa wasya wa kĩuumo kĩnene, ũkyasya, Ũtaĩwe ũtheu mũtisu wa Yeova, e o vala ũĩ.'),
('kam', 'EZK', 3, 13, 'Na neew’a kĩuumo kya nthwau sya syũmbe syĩ thayũ yĩla syakiitanganaa, na kĩuumo kya ndĩa ũtee wasyo, o kĩlonzo kya kĩuumo kĩnene.'),
('kam', 'EZK', 3, 14, 'Na ĩndĩ Veva ambũkĩlya, na andwaa vangĩ: na nathi nĩ na ũũ, ũthatunĩ wa veva wakwa; na kw’oko kwa Yeova kwaĩ na vinya ĩũlũ wakwa.'),
('kam', 'EZK', 3, 15, 'Na ĩndĩ nooka vala ve ala matavĩtwe ku Teli‐avivu, ala mekalĩte vakuvĩ na ũsĩ wa Kevali, vala matwĩe; na nekalile kw’o katĩ woo mĩthenya mũonza nĩsaanĩw’e.'),
('kam', 'EZK', 3, 16, 'Na kweethĩwa mĩthenya mũonza yathela, ndeto ya Yeova yambũkĩa, ĩkĩmbĩa.'),
('kam', 'EZK', 3, 17, 'Mwana wa mũndũ, nĩngũtw’ĩte mũsyaĩĩsya wa nyũmba ya Isilaeli: kwondũ wa ũu ĩw’a ndeto ya kanyw’a wakwa, noimataa na ũtao wakwa.'),
('kam', 'EZK', 3, 18, 'Yĩla ngwĩa ũla mũthũku, Ndwĩ ndĩi ya kũkw’a, naku ndũũmũtaa, kana kũneena ũimwon’ya ũla mũthũku aume mũendelenĩ wake mũthũku kana atangĩĩe thayũ wake; mũndũ ũsu mũthũku akakw’a e ũthũkunĩ wake; ĩndĩ nthakame yake ngamĩandũa kw’okonĩ kwaku.'),
('kam', 'EZK', 3, 19, 'Ĩndĩ ethĩwa ũkamwon’ya ũla mũthũku, na ndeĩthyũũa na kũtia ũthũku wake, kana mũendele wake mũthũku, akakw’a e ũthũkunĩ wake; ĩndĩ nũvonoketye thayũ waku.'),
('kam', 'EZK', 3, 20, 'Na ĩngĩ, yĩla mũndũ mũlũngalu ũkeethyũũa na kũtia ũlũngalu wake, na kwĩka ũthũku, na ngĩmwiĩa ũlulutĩkyo, akakw’a: nĩkwĩthĩwa ndwaamũtaa, akakw’a e naĩnĩ yake, na meko make malũngalu ala wekĩte matikalilikanwa; ĩndĩ nthakame yake ngamĩandũa kw’okonĩ kwaku.'),
('kam', 'EZK', 3, 21, 'Ĩndĩ ethĩwa ũkamwon’ya mũndũ mũlũngalu, nĩ kana ũsu mũlũngalu ndakavĩtye, nake akalea kũvĩtya, vate ndĩi akekala thayũ, nũndũ nĩwosie ũtao; naku nũvonoketye thayũ waku.'),
('kam', 'EZK', 3, 22, 'Na kw’oko kwa Yeova kwaĩ ĩũlũ wakwa nĩ kw’o; na ambĩa, Ũkĩla, ũende ũiĩnĩ, na nganeenea naku kw’o.'),
('kam', 'EZK', 3, 23, 'Na ĩndĩ nookĩla, na nathi ũiĩnĩ: na, sisya, ũtheu mũtisu wa Yeova waũngama vo, ta ũtheu mũtisu ũla noonie vakuvĩ na ũsĩ wa Kevali: na navalũka na ũthyũ wakwa.'),
('kam', 'EZK', 3, 24, 'Nĩvo ĩndĩ Veva walikile nthĩnĩ wakwa, na anũngamya na maũũ makwa; na aneena nakwa, na ambĩa, Enda, wĩvingĩe nyũmbanĩ yaku.'),
('kam', 'EZK', 3, 25, 'Ĩndĩ we, mwana wa mũndũ, sisya, makakwĩkĩa syĩndũ sya ũkwova, na makakwova nasyo, na ndũkaumaala vala maĩ;'),
('kam', 'EZK', 3, 26, 'na ngalũman’ya ũĩmĩ waku na kaakaa wa kanyw’a waku, nĩ kana wĩthĩwe ũtatonya kũneena, na ndũkethĩwa mũkan’ya woo; nũndũ mo nĩ nyũmba ng’endu.'),
('kam', 'EZK', 3, 27, 'Ĩndĩ yĩla nĩneenaa naku, ngaathamasya kanyw’a waku, na ũkamatavya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ũla wĩw’aa nĩew’e; na ũla ũtew’aa, ndakew’e: nũndũ mo nĩ nyũmba ng’endu.'),
('kam', 'EZK', 4, 1, 'O naku, mwana wa mũndũ, ĩyosee ĩvali, noiyia mbee waku, ĩvane ĩũlũ wayo ndũa, o Yelusaleme:'),
('kam', 'EZK', 4, 2, 'na ũimĩtw’ĩkanĩsya, na kũmyakĩĩa ngome, na kũmyũmbĩĩa mbumbu; o na kũmyakĩĩa maeema, na ũyia mĩio ya kũvũthũa maũvai ngalĩ syonthe.'),
('kam', 'EZK', 4, 3, 'Na ĩyosee ĩtandaa ya kĩaa, noiyia yĩthĩwe ũvai wa kĩaa katĩ waku na ndũa; na ũimyelekelya ũthyũ waku, na ĩkatw’ĩkanĩw’a, naku ũkamĩtw’ĩkanĩsya. Ũu ũkethĩwa ũvano kwa nyũmba ya Isilaeli.'),
('kam', 'EZK', 4, 4, 'Na ũndũ ũngĩ koma na ĩvava yaku ya ngalĩ ya kw’oko kwa aka, noyĩa ũthũku wa nyũmba ya Isilaeli ĩũlũ wayo; kwĩanana na ũtalo wa mĩthenya ĩla ũkayĩkomea, ũkakua ũthũku woo.'),
('kam', 'EZK', 4, 5, 'Nũndũ nĩndw’ĩte myaka ya ũthũku woo yĩthĩwe kwaku ũtalo wa mĩthenya, o mĩthenya maana atatũ na nĩongo kenda: now’o ũkakua ũthũku wa nyũmba ya Isilaeli.'),
('kam', 'EZK', 4, 6, 'Na ĩngĩ, yĩla ũkethĩwa ũminĩte ĩsu, ũkakoma na ĩvava yaku ya ngalĩ ya kw’oko kwa aũme, na ũkakua ũthũku wa nyũmba ya Yuta: mĩthenya mĩongo ĩna, kĩla mũthenya vandũ va mwaka, nĩngũtw’ĩĩĩte.'),
('kam', 'EZK', 4, 7, 'Na ũkeelekelya ũthyũ waku kũtw’ĩkanĩw’anĩ kwa Yelusaleme, kw’oko kwaku kũte kũvw’ĩke; na ũkamyathanĩa.'),
('kam', 'EZK', 4, 8, 'Na, sisya, nĩngũkwĩkĩa syĩndũ sya ũkwova, na ndũkealyũla, kũvika yĩla ũkeanĩsya mĩthenya ya kũtw’ĩkanĩw’a kwaku.'),
('kam', 'EZK', 4, 9, 'O na ĩyosee nganũ, na mbaale, na mbooso, na ndengũ na mwee, na kusemethu, ũsyĩkĩe ĩsaaninĩ yĩmwe, noyiseũvĩsya kĩmũtũ nasyo; ũkakĩĩsaa kwĩanana na ũtalo wa mĩthenya ĩla ũkakoma na ĩvava yaku, o mĩthenya maana atatũ na mĩongo kenda.'),
('kam', 'EZK', 4, 10, 'Na lĩu waku ũla ũkaĩsaa ũkethĩawa wa kũthimwa, sekeli mĩongo ĩlĩ kĩla mũthenya: ũkooĩsaa kavinda na kavinda.'),
('kam', 'EZK', 4, 11, 'Na ũkanyusaa manzĩ ma kũthimwa, kĩlungu kya thanthatũ kya ini: ũkanyusaa kavinda na kavinda.'),
('kam', 'EZK', 4, 12, 'Na ũkooĩsaa ta tũmũtu twa mbaale, na ũkatũua mene ũivuvĩĩa na mai ma mũndũ.'),
('kam', 'EZK', 4, 13, 'Na Yeova asya, Now’o ana ma Isilaeli makaĩsaa kĩmũtũ kyoo me avuku, katĩ wa i mbaĩ kũla ngamalũngĩlĩĩlya.'),
('kam', 'EZK', 4, 14, 'Nĩvo ĩndĩ naisye, A! Mwĩaĩi Yeova! Sisya, thayũ wakwa ndwaavukw’a; nũndũ kuma wana wakwa o na kũvika yu ndyaaya kĩla kya kũkw’a, kana kĩlĩku; o na kũtyaalika nyama mbuku kanyw’anĩ wakwa.'),
('kam', 'EZK', 4, 15, 'Nĩvo ĩndĩ wambĩie, Sisya, nĩkũnengete kyaa kya ng’ombe vandũ va mai ma mũndũ, na ũkaseũvasya kĩmũtũ kyaku ũkĩvuvĩĩa nakyo.'),
('kam', 'EZK', 4, 16, 'Na ĩngĩ ambĩa, Mwana wa mũndũ, sisya, ngatũlĩla ndata ya kĩmũtũ ku Yelusaleme: na makĩsaa kĩmũtũ kya kũthimwa, me na w’ĩa; na makanyusaa manzĩ ma kũthimwa, maiteva:'),
('kam', 'EZK', 4, 17, 'nĩ kana mende kĩmũtũ na manzĩ, na kũteva ene kwa ene, na kũsonzomea ũthũkunĩ woo.'),
('kam', 'EZK', 5, 1, 'Naku, mwana wa mũndũ, ĩyosee ũvyũ mũĩ; ta wenzi wa mwenzi ũkeeyosea, na ũkeenza mũtwe waku na kĩng’ew’a kyaku: nĩvo wĩosa kĩthimi kya kũthima nakyo, noiaan’ya nzw’ĩĩ.'),
('kam', 'EZK', 5, 2, 'Kĩlungu kya katatũ ũkavĩvĩsya na mwaki ndũanĩ katĩ, yĩla mĩthenya ya kũtw’ĩkanĩw’a yĩĩanĩw’a; na ũkoosa kĩlungu kĩngĩ, noikũnanga na ũvyũ ngalĩ syonthe syakyo; na kĩlungu kĩla kĩngĩ ũkanyaĩĩkya kĩsevenĩ, na ngamaatĩĩa nĩkũĩte ũvyũ.'),
('kam', 'EZK', 5, 3, 'Na ũkoosa imwe nini syasyo, na kũsyoveea mũthyanĩ wa ngũa syaku.'),
('kam', 'EZK', 5, 4, 'Na ĩndĩ ũkoosa imwe sya isu, na kũsyĩkya mwakinĩ katĩ, na kwivĩvya na mwakĩ; kuma vo mwaki ũkauma ũthi nyũmbani yonthe ya Isilaeli.'),
('kam', 'EZK', 5, 5, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ĩno nĩ Yelusaleme; nĩnĩmiĩte katĩ wa i mbaĩ, na nthĩ nimĩthyũlũlũkĩte.'),
('kam', 'EZK', 5, 6, 'Na nĩng’endee motw’ĩo makwa ĩkĩka ũthũku kũthonoka i mbaĩ, na kũng’endea myamũlo yakwa kũthonoka nthĩ ila imĩthyũlũlũkĩte; nũndũ nĩmaleete motw’ĩo makwa, na ũndũ wa myamũlo yakwa, matyaaenda nthĩnĩ wayo.'),
('kam', 'EZK', 5, 7, 'Kwondũ wa ũu Mwĩaĩi Yeova easya: Nĩkwĩthĩwa mwĩ kĩthokoo kũvĩta mbaĩ ila imũthyũlũlũkĩte, na mũtyaaenda myamũlonĩ yakwa, o na mũtyaakwata motw’ĩo makwa, o na mũtyaaatĩĩa motw’ĩo ma mbaĩ ila imũthyũlũlũkĩte;'),
('kam', 'EZK', 5, 8, 'kwondũ wa ũu Mwĩaĩi Yeova easya: Sisya, nyie, o nyie, nĩ na ũndũ naku; na ngakũsilĩla mbaĩ syene.'),
('kam', 'EZK', 5, 9, 'Na ngeeka nthĩnĩ waku ũndũ ndaamba kwĩka, na ũla ndakeka ĩngĩ ũndũ ũilyĩ taw’o, nũndũ wa mothatyo maku onthe.'),
('kam', 'EZK', 5, 10, 'Kwondũ wa ũu aaĩthe makaya ana ala me kwaku, na ana makaya aaĩthe moo; na ngakũsilĩla; na ũtialo w’onthe waku ngoonyaĩĩkya isevenĩ syonthe.'),
('kam', 'EZK', 5, 11, 'Kwondũ wa ũu, o tondũ nĩ thayũ, easya Mwĩaĩi Yeova, vate ndĩi, nũndũ nũvukĩtye vala vandũ vakwa vatheu na syĩndũ syaku syonthe imenetwe, na mothatyo maku onthe, kwondũ wa ũu ngakũnyivya; o na ĩtho yakwa yĩtikaekea, o nakwa ndikew’ĩa tei.'),
('kam', 'EZK', 5, 12, 'Kĩlungu kya katatũ kyaku kĩkooawa nĩ mũimũ, na makaminĩwa nĩ yũa katĩ waku; na kĩlungu kĩngĩ kĩkavalũkw’a na ũvyũ kũũthyũlũlũka; na kĩlungu kĩla kĩngĩ nganyaĩĩkya isevenĩ syonthe, na ngamaatĩĩa nĩkũĩte ũvyũ.'),
('kam', 'EZK', 5, 13, 'Ũu nĩw’o ũthatu wakwa ũkeanĩw’a, na ngatuma ũthilĩku wakwa kwoo ũthela, na ngakiakiĩka: na makamanya kana nyie, Yeova, nĩnĩneenete kĩwĩunĩ kyakwa, yĩla nĩĩthĩwa nĩanĩsye ũthilĩku wakwa ĩũlũ woo.'),
('kam', 'EZK', 5, 14, 'O na ĩngĩ ngakũtw’ĩkĩthya ĩanzo na wa kũvũthĩĩw’a katĩ wa mbaĩ ila ikũthyũlũlũkĩte, metho ma onthe ala mavĩtaa makyona.'),
('kam', 'EZK', 5, 15, 'Kwondũ wa ũu ũndũ ũsu ũkeethĩwa kĩvũthya na ntheko, ũmanyĩsyo na ũseng’yo, kwa mbaĩ ila ikũthyũlũlũkĩte, yĩla ngakũsilĩla na ũthatu na kũthilĩka, na mokan’yo ma ũthilĩku (nyie, Yeova, nĩnĩneenete ũu);'),
('kam', 'EZK', 5, 16, 'yĩla ngamekĩsya mĩsyĩ mĩthũku ya yũa, ĩla ya kwananga, ĩla ngekya ĩmwanange. Na ngamwongeleela yũa, na ngatũla ndata yenyu ya kĩmũtũ;'),
('kam', 'EZK', 5, 17, 'na ngamũetee yũa na nyamũ mbai, na ikatuma ũkw’ĩĩwa; na mũimũ na nthakame ikavĩtĩla kwaku; na ngaete ũvyũ ĩũlũ waku; nyie, Yeova, nĩnĩneenete ũu.'),
('kam', 'EZK', 6, 1, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 6, 2, 'Mwana wa mũndũ, lũlũmĩlya ũthyũ waku welekele iĩma sya Isilaeli, ũsyathanĩe,'),
('kam', 'EZK', 6, 3, 'ũkyasya, Inyw’ĩ iĩma sya Isilaeli, ĩthũkĩĩsyei ndeto ya Mwĩaĩi Yeova: Ũũ nĩw’o Mwĩaĩĩ Yeova ũnũũtavya iĩma na tũlĩma, mbũsĩ na myanda: Sisya, nyie, o nyie, ngaete ũvyũ ĩũlũ wenyu, na ngaananga kũndũ kwenyu kũtũlu.'),
('kam', 'EZK', 6, 4, 'Na ithembeo syenyu ikeethĩwa nthei, na mĩvw’anano yenyu ya syũa ĩkatũlangwa; na oawa menyu ngekya nthĩ mbee wa mĩvw’anano yenyu.'),
('kam', 'EZK', 6, 5, 'Na ngaia simba sya ana ma Isilaeli mbee wa mĩvw’anano yoo; na nganyaĩĩkya mavĩndĩ menyu kũthyũlũlũka ithembeo syenyu.'),
('kam', 'EZK', 6, 6, 'Motũonĩ menyu onthe ndũa ikatw’ĩka maanzo, na kũndũ kũtũlu kũkeethĩwa kwĩ kũthei; nĩ kana ithembeo syenyu syanangwe na kũtw’ĩkĩthw’a nthei, na mĩvw’anano yenyu ĩtũlangwe na kũekwa, na mĩvw’anano yenyu ya syũa ĩtilangwe, na mawĩa menyu manangwe vyũ.'),
('kam', 'EZK', 6, 7, 'Na oawa makavalũka katĩ wenyu, na mũkamanya ninyie Yeova.'),
('kam', 'EZK', 6, 8, 'Ĩndĩ ngatialya ũtialo, nũndũ mũkeethĩwa na amwe ala makavonoka ũvyũ me katĩ wa i mbaĩ, yĩla mũkanyaĩĩkĩw’a i nthĩ.'),
('kam', 'EZK', 6, 9, 'Na ala makavonoka ma inyw’ĩ makandilikanĩla me i mbaĩnĩ vala makatwawa me atave, ũndũ navevenzetwe ũndũ wa ngoo syoo mbathe, ila syandiie, na ũndũ wa metho moo, ala mekaa ũmalwaya makĩatĩĩa mĩvw’anano yoo: na makeekola methonĩ moo nũndũ wa mothũku ala meekie mothatyonĩ moo onthe.'),
('kam', 'EZK', 6, 10, 'Na makamanya ninyie Yeova. Ndyaaneena mana atĩ ngameka ũthũku ũsu.'),
('kam', 'EZK', 6, 11, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Kũnan’ya ũvĩ waku, na tua nthĩ na kũũ kwaku, noiasya, Ĩiaa! Nũndũ wa mothatyo onthe mathũku ma nyũmba ya Isilaeli; nũndũ makavalũkw’a na ũvyũ, na yũa, na mũimũ.'),
('kam', 'EZK', 6, 12, 'Ũla wĩ kũasa akooawa nĩ mũimũ; na ũla wĩ vakuvĩ akavalũkw’a na ũvyũ; na ũla wĩtiala na kũtw’ĩkanĩw’a akooawa nĩ yũa: ũu nĩw’o ngeanĩsya ũthilĩku wakwa kwoo.'),
('kam', 'EZK', 6, 13, 'Na mũkamanya ninyie Yeova, yĩla oawa moo makethĩwa katĩ wa mĩvw’anano yoo mathyũlũlũkĩte ithembeo syoo, ĩũlũ wa kĩla kalĩma katũlu, mĩtumbĩnĩ ya iĩma syonthe, na ĩtina wa kĩla mũtĩ mwĩũ, na ĩtina wa kĩla mũtĩ mũthungu wa mwaloni, kũndũ kũla mamĩtoeeasya mĩvw’anano yoo yonthe mũuke mũseo.'),
('kam', 'EZK', 6, 14, 'Na ngatambũũkya kw’oko kwakwa ĩũlũ woo, na kũtw’ĩkĩthya nthĩ nthei na mbanangĩku, kuma weũnĩ kwelekela Ndivila, o motũonĩ moo onthe; na makamanya ninyie Yeova.'),
('kam', 'EZK', 7, 1, 'Na ĩngĩ ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 7, 2, 'Naku, mwana wa mũndũ, ũũ nĩw’o Mwĩaĩi Yeova ũnũũtavya nthĩ ya Isilaeli, Mũminũkĩlyo: mũminũkĩlyo nũvikĩe ikotonĩ inya sya nthĩ.'),
('kam', 'EZK', 7, 3, 'Yu mũminũkĩlyo nũkũvikĩe, na nĩngũete ũthatu wakwa ĩũlũ waku, na nĩngũũsilĩla kwĩanana na mĩendele yaku; na nĩngũete mothatyo maku onthe ĩũlũ waku.'),
('kam', 'EZK', 7, 4, 'Na itho yakwa yĩtikakũekea, o na ndikew’ĩa tei; ĩndĩ ngaete mĩendele yaku ĩũlũ waku, na mothatyo maku makeethĩwa katĩ waku: na mũkamanya ninyie Yeova.'),
('kam', 'EZK', 7, 5, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ũthũku, o ũthũku w’oka; sisya, nĩwũkĩte.'),
('kam', 'EZK', 7, 6, 'Mũminũkĩlyo nĩ mũviku, mũminũkĩlyo nĩ mũviku; nũkũamũkĩe; sisya, nĩwũkĩte.'),
('kam', 'EZK', 7, 7, 'Ĩvinda yaku ya kũsilĩlwa nĩyĩkũkĩe, we ũla ũtwĩe ĩ nthĩ: ĩvinda nĩ ĩviku, mũthenya nĩ mũthengeeu, mũthenya wa kĩtuu, na ti wasya wa ũtanu, iĩmanĩ ĩũlũ.'),
('kam', 'EZK', 7, 8, 'Yu mĩtũkĩ ngakwonoesya ũthilĩkũ wakwa, na kwĩanĩsya ũthatu wakwa ĩũlũ waku, na ngakũsilĩla kwĩanana na mĩendele yaku; na ngaete ĩũlũ waku, mothatyo maku onthe.'),
('kam', 'EZK', 7, 9, 'Na itho yakwa yĩtikaekea, o na ndikew’ĩa tei: ngaete ĩũlũ waku kwĩanana na mĩendele yaku; na mothatyo maku makeethĩwa katĩ waku; na mũkamanya nyie, Yeova, nĩngũnaa.'),
('kam', 'EZK', 7, 10, 'Sisya, ũla mũthenya, sisya, nĩwũkĩte: ĩvinda yaku ya kũsilĩlwa nĩyaumĩla; ndata nĩlaũkĩte, ngathĩĩo nĩthongooetye.'),
('kam', 'EZK', 7, 11, 'Ung’endu nĩwũkĩlĩte ũkatw’ĩka ndata ya ũthũku; vai ũmwe woo ũkatiala, kana wa wingĩ woo, kana wa ũthwii woo: o na kũikethĩwa kwĩtũlya katĩ woo.'),
('kam', 'EZK', 7, 12, 'Ĩvĩnda nĩ ĩviku, mũthenya nĩ mũthengeeu: mũthooi ndakatane, o na mũthoosya ndakaĩe; nũndũ ũthilĩku wĩ ĩũlũ wa wingĩ woo w’onthe.'),
('kam', 'EZK', 7, 13, 'Nũndũ mũthoosya ndakasyokea kĩla kyathooiw’e, o na ethĩwa me thayũ: nũndũ ũ woni nĩ ũndũ wa wingĩ woo w’onthe, vaĩ ũla ũkasyoka; o na vai ũla ũkeyĩkĩa vinya e ũthũkunĩ wa thayũ wake.'),
('kam', 'EZK', 7, 14, 'Nĩmavuvĩte soo, na nĩmombanĩtye onthe; ĩndĩ vai ũla ũendaa kaũnĩ; nũndũ ũthilĩku wakwa wĩ ĩũlũ wa wingĩ woo w’onthe.'),
('kam', 'EZK', 7, 15, 'Ũvyũ wĩ nza, na mũimũ na yũa syĩ nthĩnĩ: ũla wĩ mũũndanĩ akooawa na ũvyũ; na ũla wĩ ndũanĩ, akaminwa nĩ yũa na mũimũ.'),
('kam', 'EZK', 7, 16, 'Ĩndĩ andũ moo ala makathonoka, makathonoka, na makeethĩwa iĩmanĩ ta mavũĩ ma myandanĩ, onthe makĩkayaa, kĩla ũmwe e ũthũkunĩ wake.'),
('kam', 'EZK', 7, 17, 'Moko onthe makaleela, na mau onthe makeethĩwa mate vinya ta manzĩ.'),
('kam', 'EZK', 7, 18, 'O na makeevotoa makunĩa na w’ĩa mũnene ũkamavw’ĩka; na nthoni ĩkeethĩwa mothyũnĩ onthe, na maũvaa mĩtwenĩ yoo yonthe.'),
('kam', 'EZK', 7, 19, 'Makekangya vetha woo nzĩanĩ nene, na thaavu woo ũkeethĩwa ta kĩndũ kĩvuku; vetha woo na thaavu woo itikatonya kũmavonokya mũthenya wa ũthilĩku wa Yeova: itikavũn’ya mathayũ moo, kana kusũsya mavu moo; nĩkwĩthĩwa nĩsyo syamalulutĩkilye ũthũkunĩ woo.'),
('kam', 'EZK', 7, 20, 'Ũndũ wa ũseo wa wanake wake, nĩwawiĩe ndaĩa; ĩndĩ mĩnaseũvisye mĩvw’anano ya mothatyo moo na ya syĩndũ syoo imenetwe nthĩnĩ waw’o: kwondũ wa ũu nĩnũtw’ĩkĩthĩtye kwoo kĩndũ kĩvuku.'),
('kam', 'EZK', 7, 21, 'Na ngoonengane mokonĩ ma aeni wĩthĩwe mbuta, na kwa athũku ma nthĩ wĩthĩwe mũtavo; nao makoovukya.'),
('kam', 'EZK', 7, 22, 'O na ngathyũũa ũthyũ wakwa ndũkamelekele, na makavukya vandũ vakwa va kĩmbithĩ; na avutani makavalika na kũvavukya.'),
('kam', 'EZK', 7, 23, 'Seũvya mũnyololo; nũndũ nthĩ nĩyusũĩte mavĩtyo me nthakame, na ndũa yusĩe ũng’endu.'),
('kam', 'EZK', 7, 24, 'Kwondũ wa ũu ngaete ila nthũku mũno sya i mbaĩ, na ikoosa nyũmba syoo syĩthĩwe syasyo: o na ngatuma ngathĩĩo ya ala me vinya ĩthela; na kũndũ kwoo kũtheu kũkavukw’a.'),
('kam', 'EZK', 7, 25, 'Wanangĩko nĩwũkĩte; na makamantha mũuo, na kũikethĩwa.'),
('kam', 'EZK', 7, 26, 'Ũthũku ũkaatĩĩa ũthũku, na mawetango makaatĩĩa mawetango; na makamantha woni kwa mwathani; ĩndĩ mĩao ĩkaa kwa mũthembi, na ũtao kwa atumĩa.'),
('kam', 'EZK', 7, 27, 'Mũsumbĩ akameta, na mwana wa mũsumbĩ akavw’ĩkwa wanangĩko, na moko ma andũ ma ĩ nthĩ makathĩnw’a: ngameka o kwĩanana na mĩendele yoo, na ngamasilĩla kwĩanana na ũndũ ũmaĩle; na makamanya ninyie Yeova.'),
('kam', 'EZK', 8, 1, 'Na kweethĩwa mwaka wa thanthatũ, mwei wa thanthatũ, mũthenya wa katano wa mwei, yĩla nekalĩte nyũmbanĩ yakwa, na atumĩa ma Yuta mekalĩte mbee wakwa, kw’oko kwa Mwĩaĩi Yeova kwambalũkĩla nĩ kw’o.'),
('kam', 'EZK', 8, 2, 'Na ĩndĩ noona, na, sisya, mũvw’ano kwoneka kwaw’o wailyĩ mwaki; kuma mũvw’anĩlenĩ wa kĩnyunyu kyake na kũtheea, kwailyĩ mwaki; na kũma kĩnyunyu kyake na kwambata, kũsiw’anĩ kwailyĩ ũtisu, o ta ũthuku wakakaa.'),
('kam', 'EZK', 8, 3, 'Na atambũũkya kĩndũ kĩilyĩ kw’oko, na angwata kĩthũkũ kĩmwe kya mũtwe wakwa; na Veva ambũkĩlya katĩ wa nthĩ na ĩtu, na andwaa mawoninĩ ma Ngai ku Yelusaleme, mũomonĩ wa mbingĩlo ya nza ya nthĩnĩ ila yelekele ngalĩ ya ĩũlũ; vala vaĩ wĩkalo wa mũvw’anano wa kĩwĩu, ũla wĩkĩaa kĩwĩu.'),
('kam', 'EZK', 8, 4, 'Na, sisya, ũtheu mũtisu wa Ngai wa Isilaeli waĩ vo, kwĩanana na woni ũla noonee ũiĩnĩ.'),
('kam', 'EZK', 8, 5, 'Nĩvo ĩndĩ wambĩie, Mwana wa mũndũ, yu ũngalalya metho maku ũsisye nzĩa ĩla yelekele ngalĩ ya ĩũlũ. Kwondũ wa ũu naũngalalya metho makwa nasisya nzĩa ĩla yelekele ngalĩ ya ĩũlũ, na sisya, ngalĩ ya ĩũlũ ya mbingĩlo ya kĩthembeo mũvw’anano ũsu wa kĩwĩu waĩ ũlikĩlonĩ.'),
('kam', 'EZK', 8, 6, 'Na ambĩa, Mwana wa mũndũ, nũkwona ũndũ mekwĩka? O mothatyo manene ala andũ ma nyũmba ya Isilaeli mekĩaa vaa, nĩ kana nĩende kũasa na vandũ vakwa vatheu? Ĩndĩ ũkoona ĩngĩ mothatyo angĩ manene.'),
('kam', 'EZK', 8, 7, 'Na andete mũomonĩ wa nza; na yĩla nasiisye, sisya, ĩima ũvainĩ.'),
('kam', 'EZK', 8, 8, 'Nĩvo ĩndĩ wambĩie, Mwana wa mũndũ yu vũthũa ũvai: na yĩla navũthũie ũvai, sisya, mũomo.'),
('kam', 'EZK', 8, 9, 'Na ambĩa, Lika, wone mothatyo mathũku ala mekĩaa vaa.'),
('kam', 'EZK', 8, 10, 'Kwondũ wa ũu nalika na noona; na sisya, kĩla mũvw’ano wa tũsamũ tũla tũtambũkaa, na nyamũ imene, na mĩvw’anano yonthe ya nyũmba ya Isilaeli, syavanĩtwe ũvainĩ, ngalĩ syonthe.'),
('kam', 'EZK', 8, 11, 'Na kwaũngama mbee wasyo aũme mĩongo mũonza ma atumĩa ma nyũmba ya Isilaeli; na Yaasania mwana wa Savani aũngama katĩ woo, kĩla mũndũ e na kĩtoeesya kyake kw’okonĩ kwake; na mũuke wa mũumbĩ wa ũvani wambata.'),
('kam', 'EZK', 8, 12, 'Nĩvo ĩndĩ wangũlilye, Mwana wa mũndũ, nĩwonete ũndũ atumĩa ma nyũmba ya Isilaeli mekĩaa kĩvindunĩ, kĩla mũndũ tũsũmbanĩ twake twa mĩvw’anano? Nũndũ measya, Yeova ndatwonaa; Yeova nũtiĩte ĩ nthĩ.'),
('kam', 'EZK', 8, 13, 'Na ĩngĩ ambĩa, Ũkoona ĩngĩ mothatyo angĩ manene ala mekaa.'),
('kam', 'EZK', 8, 14, 'Na ĩndĩ andete mũomonĩ wa mbingĩlo ya nyũmba ya Yeova ĩla yelekele ngalĩ ya ĩũlũ; na sisya, aka mekalĩte vo makĩĩĩa Tamusi.'),
('kam', 'EZK', 8, 15, 'Nĩvo ĩndĩ wangũlilye, Nĩwonete ũu, we mwana wa mũndũ? Ũkoona ĩngĩ mothatyo angĩ manene kũvĩtũka aa.'),
('kam', 'EZK', 8, 16, 'Na andete nza ya nthĩnĩ ya nyũmba ya Yeova; na sisya, nũomonĩ wa ĩkalũ ya Yeova, katĩ wa valasya na kĩthembeo, kwaĩ aũme ta mĩongo ĩlĩ na atano, mĩongo yoo yelekele ĩkalũ ya Yeova, na mothyũ moo melekele wumĩlonĩ wa syũa; na maĩ vo makĩthaitha syũa melekele wumĩlonĩ wa syũa.'),
('kam', 'EZK', 8, 17, 'Na ĩndĩ angũlya, Nĩwonete ũu, we mwana wa mũndũ? Nĩ ũndũ ũnini kwa nyũmba ya Yuta mekae mothatyo ala mekĩaa vaa? Nũndũ nĩmausũĩtye nthĩ ũng’endu, na nĩmethyũũĩte ĩngĩ manthatye: na, sisya, mathengeesyaa kaũvonge, manyiũũnĩ.'),
('kam', 'EZK', 8, 18, 'Kwondũ wa ũu nakwa ngeeka na ũthatu; itho yakwa yĩtikaekea, o na ndikew’ĩa tei; o na ethĩwa makaĩĩa matũnĩ makwa na wasya mũnene, ndikamew’a.'),
('kam', 'EZK', 9, 1, 'Nĩvo ĩndĩ waneenie na wasya mũnene matũnĩ makwa, akĩmbĩa, Thengeesya ala me na wĩai ndũanĩ, kĩla mũndũ e na mũio wake wa kaũ wa kwananga kw’okonĩ kwake.'),
('kam', 'EZK', 9, 2, 'Na sisya, aũme thanthatũ mooka na nzĩa ya mbingĩlo ya ĩũlũ, ĩla yelekele ngalĩ ya ĩũlũ, kĩla mũndũ e na mũio wake wa kaũ wa kũaa kw’okonĩ kwake; na mũndũ ũmwe katĩ woo eevw’ĩkĩte ngũa ya katane, e na ũvya wa ingi wa mũandĩki kĩnyunyunĩ kyake. Na malika, na maũngama ũtee wa kĩthembeo kya ũthuku.'),
('kam', 'EZK', 9, 3, 'Na ũtheu mũtisu wa Ngai wa Isilaeli waĩ ũnambata kuma ĩũlũ wa mũkeluvi, vala wekalaa, kũvika mwalyonĩ wa mũomo wa nyũmba: na amwĩta mũndũ ũla wevw’ĩkĩte ngũa ya katane, ũla waĩ na ũvya wa ingi wa mũandĩki kĩnyunyunĩ kyake.'),
('kam', 'EZK', 9, 4, 'Na Yeova amwĩa, Vĩtĩla katĩ wa ndũa, katĩ wa Yelusaleme, noiĩkĩa ũvano itulyanĩ sya andũ ala mavevũũkaa na ala maĩaa nũndũ wa mothatyo onthe ala mekawa katĩ wayo.'),
('kam', 'EZK', 9, 5, 'Na amea ala angĩ ngĩw’a na matũ makwa, Vĩtĩlai ndũanĩ ĩtina wake, na mũikũna: itho yenyu yĩtĩkaekee, o na mũtikew’ĩe tei;'),
('kam', 'EZK', 9, 6, 'ũaai vyũ mũtumĩa, mwanake na mwĩĩtu mũtheu, na syana nini na aka; ĩndĩ mũtikathengeee mũndũ o na wĩva ũla wĩ na ũla ũvano: na ambĩlĩlyai vala vandũ vakwa vatheu. Na ĩndĩ mambĩlĩlya na atumĩa ala maĩ mbee wa ĩ nyũmba.'),
('kam', 'EZK', 9, 7, 'Na amea, Vukyai ĩ nyũmba, na mũyusũsya nza ala mooawa: umaalai. Na maumaala, na makũna ndũa.'),
('kam', 'EZK', 9, 8, 'Na kweethĩwa yĩla maĩ makĩkũna, nakwa nĩtiĩtwe, navalũka na ũthyũ wakwa, na naĩa, na nasya, A! Mwĩaĩi Yeova! Ũkaananga ũtĩalo w’onthe wa Isilaeli kwonosyanĩ kwaku kwa ũthilĩku waku ĩũlũ wa Yelusaleme?'),
('kam', 'EZK', 9, 9, 'Nĩvo ĩndĩ wambĩie, Ũthũku wa nyũmba ya Isilaeli na Yuta nĩ mũnene mũno, na nthĩ nĩyusũĩte nthakame, na ndũa ũng’endu: nũndũ measya, Yeova nũtiĩte ĩ nthĩ, na Yeova ndonaa.'),
('kam', 'EZK', 9, 10, 'Na ngalĩ ĩ yakwa, itho yakwa yĩtikaekea, o na ndikew’ĩa tei, ĩndĩ ngaete mĩendele yoo mĩtwenĩ yoo.'),
('kam', 'EZK', 9, 11, 'Na, sisya, ũla mũndũ wevw’ĩkĩte ngũa ya katane, ũla waĩ na ũvya wa ingĩ kĩnyunyunĩ kyake, atũnga ũvoo, akyasya, Nĩnĩkĩte o ũndũ wambĩaĩe.'),
('kam', 'EZK', 10, 1, 'Na ĩndĩ noona, na, sisya, yayayanĩ yĩla yaĩ ĩũlũ wa mĩtwe ya akeluvi kwoonekie ĩũlũ woo kĩndũ kĩilyĩ kavila ka savili, ta mwonekele wa mũvw’ano wa kĩvĩla kya ũsumbĩ.'),
('kam', 'EZK', 10, 2, 'Na aneena na ũla mũndũ wevw’ĩkĩte ngũa ya katane, na amwĩa, Lika katĩ wa ndĩa ila ithyũlũlũkaa, o ungu wa mũkeluvi noyusũsya moko maku elĩ makaa ma mwaki kuma katĩ wa akeluvi, noimanyaĩĩkya ndũanĩ. Na alika nĩmwene.'),
('kam', 'EZK', 10, 3, 'Na akeluvi maũngama ngalĩ ya kw’oko kwa aũme kwa nyũmba, yĩla ũla mũndũ walikile; na ũla mũumbĩ wausũa nza ya nthĩnĩ.'),
('kam', 'EZK', 10, 4, 'Na ũtheu mũtisu wa Yeova wambata kuma mũkeluvinĩ, na waũngama mwalyonĩ wa mũomo wa nyũmba; na nyũmba yausũwa nĩ mũumbĩ, na nza yausũĩtwe nĩ ũtisũku wa ũtheu mũtisu wa Yeova.'),
('kam', 'EZK', 10, 5, 'Na kĩuumo kya nthwau sya akeluvi nĩkyeew’ĩkie kũvika nza yĩ ũtee, ta wasya wa Ngai Mwene Vinya W’onthe yĩla ũnũũneena.'),
('kam', 'EZK', 10, 6, 'Na kweethĩwa, yĩla weaĩe mũndũ ũla wevw’ĩkĩte ngũa ya katane, akĩmwĩa, Osa mwaki kuma katĩ wa ndĩa ila ithyũlũlũkaa, kuma katĩ wa akeluvi, alika, na aũngama ũtee wa ndĩa ĩmwe.'),
('kam', 'EZK', 10, 7, 'Na mũkeluvi atambũũkya kw’oko kwake kuma katĩ wa akeluvĩ kũvika mwakinĩ ũla waĩ katĩ wa akeluvi, na awosa, ne eekĩa mokonĩ ma ũla wevw’ĩkĩte ngũa ya katane, nake awosa na aumaala.'),
('kam', 'EZK', 10, 8, 'Na kwaumĩla akeluvinĩ mũvw’ano wa kw’oko kwa mũndũ ungu wa nthwau syoo.'),
('kam', 'EZK', 10, 9, 'Na noona, na sisya, ndĩa inya ũtee wa akeluvi, ndĩa ĩmwe ũtee wa mũkeluvi ũmwe, na ndĩa ĩngĩ ũtee wa mũkeluvi ũngĩ; na mũvw’anĩle wa ndĩa wailyĩ kavila ka nzumalati.'),
('kam', 'EZK', 10, 10, 'Na ũndũ wa mwonekele woo, asu ana maĩ na mũvw’ano ũmwe, ta ndĩa yaĩ nthĩnĩ wa ndĩa.'),
('kam', 'EZK', 10, 11, 'Yĩla maendaa, maendaa ngalĩ syoo inya: matyeethyũũaa makĩthi, ĩndĩ o vala mũtwe wasyaĩtye mayũvikĩla; matyeethyũũaa makĩthi.'),
('kam', 'EZK', 10, 12, 'Na mĩĩ yoo yonthe, na mĩongo yoo, na moko moo, na nthwau syoo, na ila ndĩa kwausũĩte metho ngalĩ syonthe, o ndĩa ila asu ana maĩ nasyo.'),
('kam', 'EZK', 10, 13, 'Ũndũ wa ndĩa isu, nĩsyeetiwe ngĩw’a na matũ makwa ndĩa ithyũlũlũkaa.'),
('kam', 'EZK', 10, 14, 'Na kĩla ũmwe aĩ na mothyũ ana: ũthyũ wa mbee waĩ ũthyũ wa mũkeluvi, na ũthyũ wa kelĩ waĩ ũthyũ wa mũndũ, na wa katatũ ũthyũ wa mũnyambũ, na wa kana ũthyũ wa ndiũ.'),
('kam', 'EZK', 10, 15, 'Na akeluvi mambata: kyu nĩkyo kyũmbe kĩ thayũ kĩla noonie vakuvĩ na ũsĩ wa Kevali.'),
('kam', 'EZK', 10, 16, 'Na yĩla akeluvi maendaa, ndĩa nĩsyaendaa ũtee woo; na yĩla akeluvi mookĩlilye nthwau syoo mambate kuma nthĩ, ndĩa nasyo ityaathyũũũka kũtaanĩsya namo.'),
('kam', 'EZK', 10, 17, 'Yĩla maũngamaa, isu nĩsyaũngamaa; na yĩla mambataa, isu nĩsyambataa vamwe namo: nũndũ veva wa kyũmbe kĩ thayũ waĩ nthĩnĩ wasyo.'),
('kam', 'EZK', 10, 18, 'Na ũtheu mũtisu wa Yeova waumaala kuma ĩũlũ wa mwalyo wa mũomo wa nyũmba, na waũngama ĩũlũ wa akeluvi.'),
('kam', 'EZK', 10, 19, 'Na akeluvi mookĩlya nthwau syoo, na mambata kuma nthĩ yĩla maumaalile nene na metho makwa, na ndĩa ũtee woo: na maũngama mũomonĩ wa mbingĩlo ya ngalĩ ya wumĩlonĩ wa syũa ya nyũmba ya Yeova; na ũtheu mũtisu wa Ngai wa Isilaeli waĩ ĩũlũ woo.'),
('kam', 'EZK', 10, 20, 'Kyu nĩkyo kyũmbe kĩ thayũ kĩla noonie ĩtheo wa Ngai wa Isilaeli vakuvĩ na ũsĩ wa Kevali; na namanya nĩ akeluvi.'),
('kam', 'EZK', 10, 21, 'Kĩla ũmwe aĩ na mothyũ ana, na kĩla ũmwe nthwau inya; na mũvw’ano wa moko ma mũndũ waĩ ungu wa nthwau syoo.'),
('kam', 'EZK', 10, 22, 'Na ũndũ wa mũvw’ano wa mothyũ moo, maĩ mothyũ ala noonie vakuvĩ na ũsĩ wa Kevali, mwonekelenĩ woo o namo; nĩmaendaa mbee ũmwe na ũmwe malũngalĩte.'),
('kam', 'EZK', 11, 1, 'Na ĩngĩ Veva nĩwambũkĩlilye, na andete mbingĩlonĩ ya ngalĩ ya wumĩlonĩ wa syũa ya myũmba ya Yeova, ĩla yelekele wumĩlonĩ wa syũa: na sisya, mũomonĩ wa mbingĩlo aũme mĩongo ĩlĩ atano; na noona katĩ woo Yaasania mwana wa Asulu, na Velatia mwana wa Mbenaia, anene ma andũ.'),
('kam', 'EZK', 11, 2, 'Na ambĩa, Mwana wa mũndũ, aa nĩo andũ ala masũanĩaa ũthũku, na manenganae ũtao mũthũku ndũanĩ ĩno;'),
('kam', 'EZK', 11, 3, 'ala maasya, Ĩvinda ti ĩthengeeu ya kwaka nyũmba: ndũa ĩno nĩ kĩteve, na ithyĩ twĩ nyama.'),
('kam', 'EZK', 11, 4, 'Kwondũ wa ũu mathanĩe, athana, we mwana wa mũndũ.'),
('kam', 'EZK', 11, 5, 'Na Veva wa Yeova ambalũkĩla, na ambĩa, Neena, Ũũ nĩw’o Yeova ũnũkwasya: Ũũ nĩw’o ũla mũneenete, inyw’ĩ nyũmba ya Isilaeli; nũndũ nĩnĩsĩ maũndũ ala malikaa kĩlilikanonĩ kyenyu.'),
('kam', 'EZK', 11, 6, 'Nĩmwingĩvĩtye oawa menyu ndũanĩ ĩno, na nĩmusũĩtye nzĩa nene syayo ala moaĩtwe.'),
('kam', 'EZK', 11, 7, 'Kwondũ wa ũu Mwĩaĩi Yeova easya: Oawa menyu ala mwiĩte katĩ wayo, nĩmo nyama, na ndũa ĩno nĩyo kĩteve; ĩndĩ inyw’ĩ mũkaumwa nthĩnĩ wayo.'),
('kam', 'EZK', 11, 8, 'Nĩmũkĩĩte ũvyũ; na ngaete ũvyũ ĩũlũ wenyu, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 11, 9, 'Na ngamumya nthĩnĩ wayo, na kũmũnengane mokonĩ ma aeni, na kũmũsilila.'),
('kam', 'EZK', 11, 10, 'Mũkavalũkw’a na ũvyũ; ngamũsilĩĩla mũvakanĩ wa Isilaeli; na mũkamanya ninyie Yeova.'),
('kam', 'EZK', 11, 11, 'Ndũa ĩno ndĩkethĩwa kĩteve kyenyu, o na inyw’ĩ mũtikethĩwa nyama nthĩnĩ wayo; ngamũsilĩĩla mũvakanĩ wa Isilaeli;'),
('kam', 'EZK', 11, 12, 'na mũkamanya ninyie Yeova; nũndũ mũtyaaenda myamũlonĩ yakwa, o na mũtyaaĩka motw’ĩo makwa, ĩndĩ nĩmwaatĩĩe motw’ĩo ma mbaĩ ila imũthyũlũlũkĩte.'),
('kam', 'EZK', 11, 13, 'Na kweethĩwa, yĩla nathanie, Velatia mwana wa Mbenaia akw’a. Nĩvo ĩndĩ navalũkile na ũthyũ wakwa, na naneena na wasya mũnene, na nasya, A! Mwĩaĩi Yeova! Ũkamina vyũ ũtialo wa Isilaeli?'),
('kam', 'EZK', 11, 14, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 11, 15, 'Mwana wa mũndũ, ana‐a‐ĩthe maku, o ana‐a‐ĩthe maku, andũ ma ũko waku, na andũ ma nyũmba yonthe ya Isilaeli, onthe, nĩmo ala mataviw’e nĩ andũ matwie Yelusaleme, Endai kũasa na Yeova; ithyĩ nĩtũnengetwe nthĩ ĩno yĩthĩwe ng’ũndũ yaitũ.'),
('kam', 'EZK', 11, 16, 'Kwondũ wa ũu neena, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: O na kau nĩnĩmathamĩĩsye kũasa katĩ wa i mbaĩ, na nĩnĩmanyaĩĩkĩsye katĩ wa i nthĩ, ĩndĩ ngeethĩwa kwoo vandũ vavathan’ye kavinda kanini ku nthĩ ila mavikie.'),
('kam', 'EZK', 11, 17, 'Kwondũ wa ũu neena, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ngamũmban’ya kuma ngonĩ sya andũ, na kũmũkomanĩsya vamwe kuma nthĩ kũla mwanyaĩĩkiw’e, na ngamũnenga nthĩ ya Isilaeli.'),
('kam', 'EZK', 11, 18, 'Nao makooka vo, na makaveta syĩndũ syonthe ila imenetwe sya vo na mothatyo onthe ma vo.'),
('kam', 'EZK', 11, 19, 'Na ngamanenga ngoo ĩmwe, na ngeekĩa veva mweũ nthĩnĩ wenyu; na ngaumya mwĩĩnĩ woo ngoo ya ĩvia, na ngamanenga ngoo ya nyama;'),
('kam', 'EZK', 11, 20, 'nĩ kana makinyae myamũlonĩ yakwa, na kũkwataa motw’ĩo makwa, na kũmekaa: nao makeethĩwa andũ makwa, nakwa ngeethĩwa Ngai woo.'),
('kam', 'EZK', 11, 21, 'Ĩndĩ ũndũ wa asu ala ngoo syoo iatĩĩaa ngoo ya syĩndũ syoo ila imenetwe na mothatyo moo, ngaete mĩendele yoo mĩtwenĩ yoo ene, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 11, 22, 'Nĩvo ĩndĩ akeluvi mookĩlilye nthwau syoo, na ndĩa syaĩ ũtee woo; na ũtheu mũtisu wa Ngai wa Isilaeli waĩ ĩũlũ woo.'),
('kam', 'EZK', 11, 23, 'Na ũtheu mũtisu wa Yeova wambata kuma ndũanĩ katĩ, na waũngama kĩĩmanĩ kĩla kĩ ngalĩ ya wumĩlonĩ, wa syũa ya ndũa.'),
('kam', 'EZK', 11, 24, 'Na Veva ambũkĩlya, na andwaa nĩ woninĩ ũndũ wa vinya wa Veva wa Ngai ku Kalitei, kwa ala mataviwe. Naw’o woni ũla nonete wandia.'),
('kam', 'EZK', 11, 25, 'Nĩvo ĩndĩ namatavisye ala matavĩtwe maũndũ onthe ala Yeova wambonetye.'),
('kam', 'EZK', 12, 1, 'Na ĩngĩ ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 12, 2, 'Mwana wa mũndũ, nĩwĩkalaa katĩ wa nyũmba ng’endu, ala me na metho ma kwona, na matyonaa, ala me na matũ ma kwĩw’a na matyĩw’aa; nũndũ nĩ nyũmba ng’endu.'),
('kam', 'EZK', 12, 3, 'Kwondũ wa ũu, we mwana wa mũndũ, ũmban’ya mĩio ũndũ wa kũthama, noithama mũthenya mene; na ũkathame kuma vandũ vaku kũthi vandũ vangĩ mene: nokwĩthĩwa makasũanĩa, o na kau nĩ nyũmba ng’endu.'),
('kam', 'EZK', 12, 4, 'Na ũkaumaalye mĩio yaku mũthenya mene, ya mĩio ya mũthamo; na ũkaumaale we mwene wĩoo mene, o tondũ andũ maumaalaa mathamĩthĩtw’e.'),
('kam', 'EZK', 12, 5, 'Vũthũa ĩima ũvainĩ mene, noikuĩla mĩio vo.'),
('kam', 'EZK', 12, 6, 'Mene na metho moo ũkamĩkue na kĩtuo kyaku, na kũmĩkũĩla kĩvindunĩ; ũkavw’ĩke ũthyũ waku, nĩ kana ndũkone ĩ nthĩ: nũndũ nĩnĩkwiĩte wĩthĩwe wonan’yo kwa nyũmba ya Isilaeli.'),
('kam', 'EZK', 12, 7, 'Na neeka o tondũ neeaĩwe: naumaalya mĩio yakwa mũthenya, o ta mĩio ya mũthamo, na wĩoo navũthũa ũvainĩ na kw’oko kwakwa: namyumaalya kĩvindunĩ, na namĩkua na kĩtuo kyakwa mene.'),
('kam', 'EZK', 12, 8, 'Na kĩoko ndeto ya Yeova yambũkĩa, ĩkĩmbĩa.'),
('kam', 'EZK', 12, 9, 'Mwana wa mũndũ, nyũmba ya Isilaeli, nyũmba ng’endu, ndĩnekũkũlya, Wĩĩka ata?'),
('kam', 'EZK', 12, 10, 'Ũmatavye, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ndeto ĩno ngito nĩ ũvoo wa mũnene wĩ mbee ũsumbĩnĩ wa Yelusaleme, na nyũmba yonthe ya Isilaeli ala me vo katĩ woo.'),
('kam', 'EZK', 12, 11, 'Neena, Nyie nĩ wonan’yo wenyu: o tondũ neeka, now’o makekwa; makathamĩthw’a, maende me atave.'),
('kam', 'EZK', 12, 12, 'Na mũnene ũsu ũla wĩ katĩ woo akakũĩla kĩvindunĩ na kĩtuo kyake, na akaumaala: makavũthũa ũvai makuĩle vo: akavw’ĩka ũthyũ wake, nũndũ ndakona ĩ nthĩ na metho make.'),
('kam', 'EZK', 12, 13, 'Ngalan’ya kĩtei kyakwa ĩũlũ wake, na akakwatw’a nĩ kĩtei kyakwa; na ngamũtwaa Mbaviloni nthĩ ya Akalitei; ĩndĩ ndakamyona, o na kau akakw’ĩa kw’o.'),
('kam', 'EZK', 12, 14, 'Na ngamanyaĩĩkya melekele kĩla kĩseve onthe ala mamũthyũlũlũkĩte mamũtethye, na nguthu syake syonthe; na ngamaatĩĩa nĩkũĩte ũvyũ.'),
('kam', 'EZK', 12, 15, 'Na makamanya ninyie Yeova, yĩla ngamanyaĩĩkya mbaĩnĩ, na kũmekangya kũũ na kũũ nthĩnĩ wa i nthĩ.'),
('kam', 'EZK', 12, 16, 'Ĩndĩ ngatialya andũ avũthũ moo mavonoke ũvyũ, na yũa, na mũimũ; nĩ kana matavanasye mothatyo moo onthe katĩ wa i mbaĩ kũla methi; na makamanya ninyie Yeova.'),
('kam', 'EZK', 12, 17, 'Na ĩngĩ ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 12, 18, 'Mwana wa mũndũ, ya kĩmũtũ kyaku ũitelemanga, noinyw’a manzĩ maku na kũtelemanga na kũkĩa;'),
('kam', 'EZK', 12, 19, 'na matavye andũ ma ĩ nthĩ, Uũ nĩw’o Mwĩaĩĩ Yeova ũnũkwasya ũndũ wa ala matwĩe Yelusaleme, na nthĩ ya Isilaeli: Makaya kĩmũtũ kyoo na w’ĩa, na kũnyw’a manzĩ moo makĩteva, nũndũ nthĩ yake ĩkeethĩwa nthei, nĩ kũtavĩwa kyonthe kĩla kĩ nthĩnĩ wayo, nũndũ wa ũng’endu wa onthe ala mamĩtwĩe.'),
('kam', 'EZK', 12, 20, 'Na ndũa ila syĩ na andũ ikatw’ĩka maanzo, na nthĩ ĩkeethĩwa nthei; na mũkamanya ninyie Yeova.'),
('kam', 'EZK', 12, 21, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 12, 22, 'Mwana wa mũndũ, nthimo ĩno ĩla mwĩ nayo nthĩ ya Isilaeli nĩ myaũ, ĩkwasya, Mĩthenya nĩyongelekete, na kĩla woni ndũkwĩanĩw’a?'),
('kam', 'EZK', 12, 23, 'Kwondũ wa ũu matavye, Ũũ nĩw’o mwĩaĩi Yeova ũnũkwasya: Ngamina nthimo ĩsu, na matĩkamĩneena ĩngĩ ta nthimo nthĩnĩ wa Isilaeli; ĩndĩ matavye, Mĩthenya nĩ mĩthengeeu, na wĩanĩsyo wa kĩla woni.'),
('kam', 'EZK', 12, 24, 'Nũndũ kũtikethĩwa ĩngĩ woni wa ũvũngũ kana kũaũsya kwa ngathĩĩo nthĩnĩ wa nyũmba ya Isilaeli.'),
('kam', 'EZK', 12, 25, 'Nũndũ ninyie Yeova; nganeena, na ndeto ila nganeena ĩkeanĩw’a; ndĩkaselewa ĩngĩ: nũndũ mĩthenyanĩ yenyu, we nyũmba ng’endu, nganeena ĩla ndeto, na ngamĩanĩsya, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 12, 26, 'Na ĩngĩ ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 12, 27, 'Mwana wa mũndũ, sisya, ala ma nyũmba ya Isilaeli measya, Woni ũla ũnũkwona nĩ wa mĩthenya mingĩ yũkĩte, na nũnũkwathana ũvoo wa mavinda me kũasa.'),
('kam', 'EZK', 12, 28, 'Kwondũ wa ũu matavye, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Kũikaselewa ĩngĩ o na ĩmwe ya ndeto syakwa, ĩndĩ ndeto ĩla nganeena ĩkeanĩw’a, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 13, 1, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa.'),
('kam', 'EZK', 13, 2, 'Mwana wa mũndũ, mathanĩe athani ma Isilaeli ala mathanaa, noimatavya ala mathanaa kuma ngoonĩ syoo ene, Ĩw’ai ndeto ya Yeova:'),
('kam', 'EZK', 13, 3, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Woo nĩ wa athani atumanu, ala maatĩĩaa veva woo ene, na matyaaona ũndũ!'),
('kam', 'EZK', 13, 4, 'We Isilaeli, athani maku methĩĩtwe ta mbĩwa syĩ kũndũ kwanangĩku.'),
('kam', 'EZK', 13, 5, 'Inyw’ĩ mũtyaambata movũthũeni, o na mũtyaaaka ũvai kwondũ wa nyũmba ya Isilaeli, nĩ kana mũũngame kaũnĩ mũthenya wa Yeova.'),
('kam', 'EZK', 13, 6, 'Nĩmonete maũndũ ma ũvũngũ, na ũvũngũ wa kũaũsya, ala maasya, Yeova easya; ĩndĩ Yeova ndaamatũma: na matuma andũ methĩwa na wĩkwatyo kana ndeto ĩkeanĩw’a.'),
('kam', 'EZK', 13, 7, 'Mũtyaaona woni wa ũvũngũ, na mũtyaaneena ũvũngũ wa kũaũsya, ũndũ mũkwasya, Yeova easya; nakwa ndyaaneena?'),
('kam', 'EZK', 13, 8, 'Kwondũ wa ũu Mwĩaĩi Yeova easya atĩĩ: Nĩkwĩthĩwa nĩmũneenete ũvũngũ, na mwonete movũngũ, kwondũ wa ũu sisyai, nĩ na ũndũ nenyu, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 13, 9, 'Na kw’oko kwakwa kũkeethĩwa ĩũlũ wa athani ala monaa mawoni ma ũvũngũ, na maaũasya makengane; matikethĩwa nzamanĩ ya andũ makwa, o na matikaandĩkwa vala nyũmba ya Isilaeli ĩandĩkĩtwe, o na matikalika nthĩ ya Isilaeli; na mũkamanya ninyie Mwĩaĩi Yeova.'),
('kam', 'EZK', 13, 10, 'Nĩkwĩthĩwa, ĩĩ, nĩkwĩthĩwa nĩmavĩtĩthĩtye andũ makwa, makyasya, Mũuo; na vati mũuo; na yĩla ũmwe ũnũkwaka ũvai, sisya, nĩmekũvaka sokaa ũte mũlue nesa:'),
('kam', 'EZK', 13, 11, 'matavye ala meũvaka ũvai sokaa ũte mũlue nesa, ũkavalũka: kũkeethĩwa mbua ya mũono ĩtulĩtye; na inyw’ĩ, mavia manene ma mbua, mũkavalũka; na kĩseve kĩnene kĩkootembũa.'),
('kam', 'EZK', 13, 12, 'Sisya, yĩla ũvai wĩvalũka, mũikakũlw’a, Kũĩva kũvaka kũla mwĩũvakĩte?'),
('kam', 'EZK', 13, 13, 'Kwondũ wa ũu Mwĩaĩi Yeova easya atĩĩ: Ngootembũa na kĩseve kĩnene ũthilĩkunĩ wakwa; na kũkeethĩwa mbua ya mũono ĩtulĩtye ũthatunĩ wakwa, na mavia manene ma mbua ma kũmina ũvai ũthilĩkunĩ.'),
('kam', 'EZK', 13, 14, 'Now’o ngaomboa ũvai ũla mũvakĩte sokaa ũte mũlue nesa, na kũũvalũkya nthĩ, na ĩndĩ mwambĩlĩlyo waw’o ũkaumĩla; na ũkavalũka, na mũkaminĩwa vu: na mũkamanya ninyie Yeova.'),
('kam', 'EZK', 13, 15, 'O ta ũu ngeanĩsya ũthilĩku wakwa ũvainĩ, na andũnĩ ala movakĩte sokaa ũte mũlue nesa; na ngamwĩa. Ũvai ti vo ũĩ, o na ala movakie;'),
('kam', 'EZK', 13, 16, 'nao, nĩ athani ma Isilaeli ala mathanaa ũndũ wa Yelusaleme, ala monaa mawoni ma mũuo kwondũ wayo, na vati mũuo, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 13, 17, 'Naku, mwana wa mũndũ, lutĩla eĩtu ma andũ maku ũthyũ waku, asu ala mathanaa kuma ngoonĩ syoo ene; noimathanĩa,'),
('kam', 'EZK', 13, 18, 'ũkyasya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Woo nĩ wa aka ala matumĩaa mĩto ikokoa syonthe, na kũtuma itambaa sya mĩtwe ya andũ ma kĩla kĩũngamo matee mathayũ ma andũ! Mũkatea mathayũ ma andũ makwa, na kũtangĩĩa andũ mekale thayũ kwondũ wenyu?'),
('kam', 'EZK', 13, 19, 'Nĩmũmbukĩtye katĩ wa andũ makwa kwondũ wa mbĩ syusĩe mbaale na kwondũ wa ilungu sya imũtũ, mũae andũ mataĩle kũkw’a, na kũeka me thayũ ala mataĩle kwĩkala thayũ, ũndũ wa kũmatavya andũ makwa movũngũ ala methukĩĩasya movũngũ.'),
('kam', 'EZK', 13, 20, 'Kwondũ wa ũu Mwĩaĩi Yeova easya: Sisya, nĩ na ũndũ na mĩto yenyu, ĩla mũteaa mathayũ ma andũ nayo mũmaũlũkĩthye, na ngamĩtuka yume mokonĩ menyu; na ngaeka andũ mathi, o andũ ala mũmateaa mũmaũlũkye.'),
('kam', 'EZK', 13, 21, 'O na itambaa syenyu ngatembũanga, na kũvonokya andũ makwa kuma mokonĩ menyu, na matikethĩwa ĩngĩ mokonĩ menyu masyĩmwa; na mũkamanya ninyie Yeova.'),
('kam', 'EZK', 13, 22, 'Nikwĩthĩwa nĩmwĩw’ĩthĩtye woo na movũngũ ngoo ya alũngalu, ala ndaamew’ĩthya woo, na mwĩkĩĩte moko ma ũla mũthũku vinya, nĩ kana ndakasyoke kuma mũendelenĩ wake mũthũku, na kũtangĩĩwa ethĩwe thayũ;'),
('kam', 'EZK', 13, 23, 'kwondũ wa ũu mũtikona ĩngĩ mawoni ma ũvũngũ, kana kũaũsya: na ngavonokya andũ makwa kuma kw’okonĩ kwenyu; na mũkamanya ninyie Yeova.'),
('kam', 'EZK', 14, 1, 'Nĩvo ĩndĩ nookĩwe nĩ amwe ma atumĩa ma Isilaeli, na mekala nthĩ mbee wakwa.'),
('kam', 'EZK', 14, 2, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 14, 3, 'Mwana wa mũndũ, andũ aa nĩmekĩĩte mĩvw’anano yoo ngoonĩ syoo, na maiĩte ũlulutĩkyo wa ũthũku woo mbee wa ũthyũ woo: nĩnaĩle kũkũlw’a nĩo ũndũ o na wĩva?'),
('kam', 'EZK', 14, 4, 'Kwondũ wa ũu neena nao, noimatavya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Kĩla mũndũ wa nyũmba ya Isilaeli ũla wĩkĩĩte mĩvw’anano yake ngoonĩ yake, na kwia ũlulutĩkyo wa ũthũku wake mbee wa ũthyũ wake, na akyũka kwa mwathani; nyie Yeova ngamũsũngĩa ũndũnĩ ũsu kwĩanana na wingĩ wa mĩvw’anano yake;'),
('kam', 'EZK', 14, 5, 'nĩ kana nĩkwate nyũmba ya Isilaeli na ngoo syoo ene, nũndũ mo onthe nĩmataanĩsye nakwa kwondũ wa mĩvw’anano yoo.'),
('kam', 'EZK', 14, 6, 'Kwondũ wa ũu tavya nyũmba ya Isilaeli, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Syokai, na ĩthyũũei mũtie mĩvw’anano yenyu; na thyũũai mothyũ menyu matikasisye mothatyo menyu onthe.'),
('kam', 'EZK', 14, 7, 'Nũndũ kĩla ũmwe wa nyũmba ya Isilaeli, kana wa aeni ala mekalaa ũeni nthĩnĩ wa Isilaeli, ũla wĩtaanĩsya nakwa, na kwĩkĩa mĩvw’anano yake ngoonĩ yake, na kwia ũlulutĩkyo wa ũthũku wake mbee wa ũthyũ wake, na akyũka kwa mwathani ekũlĩlye kwakwa; nyie Yeova ngeesũngĩĩa:'),
('kam', 'EZK', 14, 8, 'na ngamũlutĩla mũndũ ũsu ũthyũ wakwa, na ngamũtw’ĩkĩthya ũseng’yo, ethĩwe wonan’yo na nthimo, na ngamũveta katĩ wa andũ makwa; na mũkamanya ninyie Yeova.'),
('kam', 'EZK', 14, 9, 'Na ethĩwa mwathani nũkengetwe na akaneena ndeto, nyie, Yeova, nĩnĩkengete mwathani ũsu, na ngamũtambũũkĩsya kw’oko kwakwa, na ngamwananga aume andũnĩ makwa Isilaeli.'),
('kam', 'EZK', 14, 10, 'Na makakua ũthũku woo: ũthũku wa mwathanĩ ũkethĩwa ta ũthũku wa ũla ũmũkũlasya;'),
('kam', 'EZK', 14, 11, 'nĩ kana nyũmba ya Isilaeli ndĩkaende ĩkyanganga ĩngĩ kũasa nakwa, kana kwĩthũkya ĩngĩ na movĩtyo moo onthe; ĩndĩ nĩ kana methĩwe andũ makwa, nakwa nĩthĩwe Ngai woo, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 14, 12, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 14, 13, 'Mwana wa mũndũ, yĩla nthĩ ĩkambĩtanĩsya kwondũ wa kwĩka naĩ, nakwa ngamĩtambũũkĩsya kw’oko kwakwa, na kũtũla ndata ya kĩmũtũ kyayo, na kũmĩetee yũa, na kũveta kwayo mũndũ na nyamũ;'),
('kam', 'EZK', 14, 14, 'o na ethĩwa andũ aa atatũ, Noa, na Ndanieli, na Yovu, me kw’o, makavonokya no mathayũ moo ene kwondũ wa ũlũngalu woo, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 14, 15, 'Ethĩwa ngavĩtĩlya nyamũ mbai ĩ nthĩ, na ĩkĩmyananga, na ĩkĩtw’ĩka nthei, ũkethĩa mũndũ o na wĩva ndatonya kũmĩvĩtĩla nũndũ wa nyamũ;'),
('kam', 'EZK', 14, 16, 'o na ethĩwa andũ asu atatũ me kw’o, o tondũ nĩ thayũ, easya Mwĩaĩi Yeova, matikavonokya ana kana eĩtu; o mo ene makavonoka, ĩndĩ ĩ nthĩ ĩkeethĩwa nthei.'),
('kam', 'EZK', 14, 17, 'Kana ethĩwa ngamĩetee nthĩ ĩsu ũvyũ, na ngasya, Ũvyũ, enda wangange ĩ nthĩ; nĩ kana nĩvete nthĩnĩ wayo mũndũ na nyamũ;'),
('kam', 'EZK', 14, 18, 'o na ethĩwa andũ asu atatũ me kw’o, o tondũ nĩ thayũ, matikavonokya ana kana eĩtu, ĩndĩ no mo ene makavonoka, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 14, 19, 'Kana ethĩwa ngatũma mũimũ nthĩ ĩsu, na kũmyonoesya ũthilĩku wakwa wa kwĩtĩkya nthakame, nĩvete nthĩnĩ wayo mũndũ na nyamũ;'),
('kam', 'EZK', 14, 20, 'o na ethĩwa Noa, na Ndanieli, na Yovu, me kw’o, o tondũ nĩ thayũ, easya Mwĩaĩi Yeova, matikavonokya mwana kana mwĩĩtu; makavonokya no mathayũ moo ene kwondũ wa ũlũngalu woo.'),
('kam', 'EZK', 14, 21, 'Nũndũ ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nĩ mbee veana ata yĩla ngaetee Yelusaleme mosilĩlo makwa ana mathũku, ũvyũ, na yũa, na nyamũ nthũku, na mũimũ, nĩvete nthĩnĩ wayo mũndũ na nyamũ!'),
('kam', 'EZK', 14, 22, 'Ĩndĩ, sisya, kũkatiala ũtialo nthĩnĩ wayo ũla ũkaumaalw’a, ana na eĩtu; sisya, makamumĩlĩla, na mũkoona mĩendele yoo na meko moo; na mũkakiakiw’a ũndũ wa ũthũku ũla nĩetete Yelusaleme, o w’onthe ũla nĩetete ĩũlũ wayo.'),
('kam', 'EZK', 14, 23, 'Na makamũkiakisya, yĩla mũkona mĩendele yoo na meko moo; na mũkamanya ndyaaĩka vate kĩtumi w’onthe ũla neekie nthĩnĩ wayo, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 15, 1, 'Na ndeto ya Yeova yambũkĩa, ĩkĩngũlya,'),
('kam', 'EZK', 15, 2, 'Mwana wa mũndũ, mũtĩ wa mũsavivũ ũvĩtũkĩte mĩtĩ ĩla ĩngĩ ũndũnĩ wĩva, ũvonge wa mũsavivũ ũla wĩ katĩ wa mĩtĩ ya mũtitũ?'),
('kam', 'EZK', 15, 3, 'Mũtĩ waw’o nĩwoswa ũkatethya wĩa o na wĩva? Kana andũ nĩmosa kyambo kyaw’o kya kwanĩka kĩndũ o na kĩva?'),
('kam', 'EZK', 15, 4, 'Sisya, nũkwĩkw’a mwakinĩ wĩthĩwe ngũ; mwaki nũvĩvĩtye mĩthya ĩli yaw’o, o na nũvĩvĩlw’e katĩ: nĩwaĩla wĩanĩ o na wĩva?'),
('kam', 'EZK', 15, 5, 'Sisya, yĩla waĩ mũima, ndwaĩ vata wĩanĩ o na wĩva: yu nĩ mbee mũno, yĩla mwaki ũminĩte kũwananga, na nũvĩvĩtw’e, kũtonya kũtethya wĩa o na wĩva!'),
('kam', 'EZK', 15, 6, 'Kwondũ wa ũu Mwĩaĩi Yeova easya: Ta mũtĩ wa mũsavivũ katĩ wa mĩtĩ ya mũtitũ, ũla nĩkĩĩte mwakinĩ wĩthĩwe ngũ, now’o nganengane ala matwĩe Yelusaleme.'),
('kam', 'EZK', 15, 7, 'Na ngamalutĩla ũthyũ wakwa; makauma mwakinĩ, ĩndĩ mwaki ũkamamina, na mũkamanya ninyie Yeova, yĩla nĩmalutĩla ũthyũ wakwa.'),
('kam', 'EZK', 15, 8, 'Na ngatw’ĩkĩthya nthĩ nthei, nũndũ nĩmavĩtĩtye, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 16, 1, 'Na ĩngĩ ndeto ya Yeova yambũkĩa, ĩkĩmbĩa.'),
('kam', 'EZK', 16, 2, 'Mwana wa mũndũ, manyĩthya Yelusaleme mothatyo mayo;'),
('kam', 'EZK', 16, 3, 'nokyasya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũũtavya Yelusaleme: Wambĩlĩlyo waku na kũsyaĩwa kwaku nĩ nthĩ ya Mũkanaani; Mũamoli aĩ ĩthe waku, na inyia waku aĩ Mũĩtiti.'),
('kam', 'EZK', 16, 4, 'Na ũndũ wa kũsyawa kwaku, mũthenya ũla wasyaiwe mũkautĩ waku ndwaatilwa, o na ndwaathambw’a na manzĩ ũthee; ndwaavakwa mũnyũ, kana kũvw’ĩkwa ngũa ya ũkenge.'),
('kam', 'EZK', 16, 5, 'Vatyaĩ itho yakwĩw’ĩe tei yĩkwĩke ũndũ o na wĩva wa asu, ya ũkwĩw’ĩa tei; ĩndĩ wekiw’e weũnĩ, nũndũ thayũ waku nĩwameniwe, mũthenya ũla wasyaiwe.'),
('kam', 'EZK', 16, 6, 'Na yĩla navĩtĩle vala ũĩ, na nakwona wĩthokoanĩtye na nthakame yaku, nakwĩa, O na wĩ na nthakame yaku, ĩthĩwa thayũ; ĩĩ, nakwĩa, O na wĩ na nthakame yaku, ĩthĩwa thayũ.'),
('kam', 'EZK', 16, 7, 'Nĩnakwingĩvisye ta kĩla kĩmeaa mũũndanĩ, naku waingĩva na waendeea kũneneva, na wavikĩa kwanakava mũno; nondo syaku syaneneva, na nzw’ĩĩ syaku syeana; o na ũu w’onthe waĩ mũthei, ũte ngũa.'),
('kam', 'EZK', 16, 8, 'Na yĩla navĩtĩle vala ũĩ, na nakũsisya, sisya, ĩvinda yaku yaĩ ĩvinda ya kwendwa; na nakũvw’ĩka na mũthya wa ngũa yakwa, na nakũvw’ĩka wĩ mũthei: ĩĩ, nakwĩavĩa, na natianĩa ũtianĩo naku, na watw’ĩka wakwa, easya, ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 16, 9, 'Nĩvo ĩndĩ nakũthambisye na manzĩ; ĩĩ, nakũthambya nesa nthakame yaku yakuma, na nakũvaka mauta.'),
('kam', 'EZK', 16, 10, 'O na nakũvw’ĩka na ngũa itumĩĩwe wanake, na nakwĩkĩa iatũ sya mbũa sya vomboo, na nakũvotoa na katane nzeo, na nakũvw’ĩka na alili.'),
('kam', 'EZK', 16, 11, 'Na nakwanakavya na mawanake, na neekĩa itang’a mokonĩ maku, na mũnyoo ngingonĩ yaku.'),
('kam', 'EZK', 16, 12, 'Na neekĩa ngome ĩnyiũũnĩ yaku, na ngome sya matũ matũnĩ maku, na ngovia nzeo mũno ya ũsumbĩ mũtwenĩ waku.'),
('kam', 'EZK', 16, 13, 'Wanakavĩtw’e ta ũu na thaavu na vetha; na ngũa yaku yaĩ ya katane nzeo, na ya alili, na ĩtumĩĩwe wanake; waĩsaa mũtu mũvinyu, na ũkĩ wa nzũkĩ, na mauta, na waĩ mwanake mũno, na waathimĩka wavikĩa kĩanda kya kĩũsumbĩ.'),
('kam', 'EZK', 16, 14, 'Na nguma yaku yanyaĩĩka katĩ wa i mbaĩ nũndũ wa wanake waku; nũndũ waĩ mwĩanĩu, kwondũ wa ũnene wakwa ũla nakwĩkĩie, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 16, 15, 'Ĩndĩ nĩwekwatisye wanake waku, na weeka ũmalwaya nũndũ wa nguma yaku, na woonosya ũmalwaya waku ĩũlũ wa kĩla ũmwe ũla wavĩtaa; waĩ wake.'),
('kam', 'EZK', 16, 16, 'Na woosa ngũa syaku, na weeseũvĩsya kũndũ kũtũlu kwanakavĩtw’e na langi wa mĩthemba mingĩ, na weekĩa ũmalwaya kw’o; maũndũ ta asu matikoka, o na kũikethĩwa ũu.'),
('kam', 'EZK', 16, 17, 'O na nĩwoosie mĩio yaku mĩseo ya wanake ya thaavu wakwa na vetha wakwa, ĩla nakũnengie, na weeseũvĩsya mĩvw’anano ya andũ aũme, na weeka ũmalwaya nayo;'),
('kam', 'EZK', 16, 18, 'na woosa ngũa syaku ila itumĩĩwe wanake, na wamĩvw’ĩka, na waia mauta makwa na ũvani wakwa mbee wayo.'),
('kam', 'EZK', 16, 19, 'O na kĩmũtũ kyakwa kĩla nakũnengie, kya mũtu mũvinyu, na mauta, na ũkĩ wa nzũkĩ, kĩla nakũathĩsye, o nakyo waia mbee wayo kĩthĩwe kĩndũ kĩla kĩnyungaa nesa; na kwailyĩ ũu, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 16, 20, 'Na ĩngĩ nĩwosete ana maku na eĩtu maku, ala wanzyaĩe, na asu wamĩthembea maminwe. Ũmalwaya waku waĩ ũndũ ũnini,'),
('kam', 'EZK', 16, 21, 'kana ũae syana syakwa, na kwinengane, ũkivĩtĩlya mwakinĩ ũndũ wayo?'),
('kam', 'EZK', 16, 22, 'Na mothatyonĩ maku onthe na ũmalwayanĩ waku ndwaalilikana mĩthenya ya wana waku, yĩla waĩ mũthei ũte ngũa, na wathokoanĩte na nthakame yaku.'),
('kam', 'EZK', 16, 23, 'Na kwesa kwĩthĩwa ĩtina wa ũthũku waku w’onthe (woo, woo nĩ waku! Easya ũu Mwĩaĩi Yeova),'),
('kam', 'EZK', 16, 24, 'atĩ nĩwĩyakĩe vandũ va nguluĩ, na nĩweeseũvĩsye kũndũ kũtũlu nzĩanĩ nene syonthe.'),
('kam', 'EZK', 16, 25, 'Nĩwakĩte vandũ vaku vatũlu wambĩlĩlyonĩ wa kĩla nzĩa, na nũtw’ĩkĩthĩtye wanake waku ũthatyo, na nũtaanĩĩsye maũũ maku kĩla mũndũ ũla ũvĩtaa, na waingĩvya ũmalwaya waku.'),
('kam', 'EZK', 16, 26, 'O na nĩwĩkĩte ũmalwaya na Amisili, atũi maku, anene ma mwĩĩ; na nĩwingĩvĩtye ũmalwaya waku, ũnthatye.'),
('kam', 'EZK', 16, 27, 'Sisya kwondũ wa ũu, nĩnakũtambũũkĩsye kw’oko kwakwa, na nĩnĩolete lĩu waku wa mavinda onthe, na nĩnĩkũnenganĩte kwendanĩ kwa ala makũmenaa, eĩtu ma Avilisiti, ala meũsonoka ũndũ wa mũendele waku mwathe.'),
('kam', 'EZK', 16, 28, 'O na nĩwĩkĩte ũmalwaya na Aasulĩ, nũndũ ndwaakola; ĩĩ, nĩwĩkĩte ũmalwaya nao, ĩndĩ ndwaaĩanĩw’a.'),
('kam', 'EZK', 16, 29, 'O na ĩngĩ nĩwingĩvĩtye ũmalwaya waku nthĩ ya Kanaani, o na kũvika Kalitei; ĩndĩ ndwaaĩanĩw’a nĩw’o.'),
('kam', 'EZK', 16, 30, 'Ngoo yaku ko nĩ mbonzu, easya Mwĩaĩi Yeova, nũndũ nĩwĩkaa maũndũ asu onthe, wĩa wa ĩlwaya yĩte nthoni;'),
('kam', 'EZK', 16, 31, 'nũndũ nĩwakaa vandũ vaku va nguluĩ wambĩlĩlyonĩ wa kĩla nzĩa, na kũseũvya vandũ vaku vatũlu kĩla nzĩanĩ nene, na ndwailyĩ ta ĩlwaya, ũndũnĩ ũũ wa atĩ wavũthya kũtuvwa.'),
('kam', 'EZK', 16, 32, 'Kĩveti kĩla kĩlaalaa! Kĩla kyosaa aeni vandũ va mũũme wakyo!'),
('kam', 'EZK', 16, 33, 'Nĩmanengae malwaya onthe mĩthĩnzĩo; ĩndĩ we nũnengae endwa maku onthe mĩthĩnzĩo yaku, na kũmatuva, nĩ kana makũkĩe kĩla ngalĩko ũndũ wa ũmalwaya waku.'),
('kam', 'EZK', 16, 34, 'Na wĩ kĩvathũkan’yo na aka ala angĩ ũmalwayanĩ waku, nũndũ vai ũmwe ũla ũkũatĩĩaa eke ũmalwaya; na nũndũ nũtuvanaa, naku ndũtuvawa, kwondũ wa ũu wĩ kĩvathũkan’yo.'),
('kam', 'EZK', 16, 35, 'Kwondũ wa ũu, we ĩlwaya, ĩthukĩĩsye ndeto ya Yeova:'),
('kam', 'EZK', 16, 36, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya, Nĩkwĩthĩwa ũvuku waku nĩwonoetw’e, na nũvuĩtwe woneke wĩ mũthei nũndũ wa ũmalwaya waku na endwa maku; na nũndũ wa mĩvw’anano yonthe ya mothatyo maku, na kwondũ wa nthakame ya syana syaku, ila wamĩnengie;'),
('kam', 'EZK', 16, 37, 'kwondũ wa ũu sisya, ngoomban’ya endwa maku onthe, ala wamatanĩe, na onthe ala wamendie, vamwe na onthe ala wamenie; o na ngamomban’ya ĩũlũ waku ngalĩ syonthe, na ngakũvua woneke wĩ mũthei, nĩ kana mone wĩ mũthei vyũ.'),
('kam', 'EZK', 16, 38, 'Na ngakũsilĩla, o tondũ aka masilĩlawa ala manangaa ũtwaano na kwĩtĩkya nthakame; ngaete ĩũlũ waku nthakame ya ũthilĩku na kĩwĩu.'),
('kam', 'EZK', 16, 39, 'O na ngakũnengane kw’okonĩ kwoo, na makaomboa vandũ vaku va nguluĩ, na kũomboa kũndũ kwaku kũtũlu; na makakumya ngũa syaku, na kwosa mĩio yaku mĩseo ya wanake; na makakũtia wĩ mũthei ũte ngũa.'),
('kam', 'EZK', 16, 40, 'O na makaete nguthu yũkite naku, na makakũkimanga na mavia, na makakũtonyanga na mbyũ syoo.'),
('kam', 'EZK', 16, 41, 'Na makavĩvya nyũmba syaku na mwaki, na ũkũsilĩla aka aingĩ mene; na ngatuma ũeka kwĩka ũmalwaya, na ndũkatuvana ĩngĩ.'),
('kam', 'EZK', 16, 42, 'Now’o ngathũmũsya ũthilĩku wakwa kwaku, na kĩwĩu kyakwa kĩkauma vala ũĩ, na ngekala nĩuĩtye, na ndĩkathata ĩngĩ.'),
('kam', 'EZK', 16, 43, 'Nĩkwĩthĩwa ndwaalilikana mĩthenya ya wana waku, ĩndĩ nĩwanthilĩkile maũndũnĩ asu onthe; kwondũ wa ũu, sisya, ngaete mũendele waku mũtwenĩ waku, easya ũu Mwĩaĩi Yeova: na ndũkeka wathe ũsu vamwe na mothatyo maku onthe.'),
('kam', 'EZK', 16, 44, 'Sisya, kĩla ũmwe ũla ũneenaa nthimo akakũneenea nthimo ĩno, akyasya, O ũndũ inyia ũilyĩ, now’o mwĩĩtu wake ũilyĩ.'),
('kam', 'EZK', 16, 45, 'We wĩ mwĩĩtu wa mwenyu, ũla ũmenaa mũũme wake na syana syake; na wĩ mwĩĩtu‐a‐inyia wa eĩtu‐a‐inyia maku, ala mamenie aũme moo na syana syoo: inyia waku nĩ Mũititi, na au nĩ Mũamoli.'),
('kam', 'EZK', 16, 46, 'Na mwĩĩtu‐a‐nyukwe mũkũũ nĩwe Samalia, ũla ũtũaa ngalĩ ya kw’oko kwaku kwa aka, we na eĩtu make; na mwĩĩtu‐a‐nyukwe mũinau, ũla ũtũaa ngalĩ ya kw’oko kwaku kwa aũme, nĩwe Sotomo na eĩtu make.'),
('kam', 'EZK', 16, 47, 'Ĩndĩ ndwaaendela mĩendelenĩ yoo, kana kwĩka mothatyo moo; ĩndĩ, ta ethĩwa ũu waĩ ũndũ ũnini, waĩ mũthũku kwĩ mo mĩendelenĩ yaku yonthe.'),
('kam', 'EZK', 16, 48, 'O tondũ nĩ thayũ, easya Mwĩaĩi Yeova, Sotomo mwĩĩtu‐a‐inyia waku ndaaĩka, we kana eĩtu make, tondũ we weekie, we na eĩtu maku.'),
('kam', 'EZK', 16, 49, 'Sisya, ũũ waĩ ũthũku wa mwĩĩtu‐a‐nyukwe Sotomo: ngathĩĩo, kũvũnw’a na lĩu, ũthũmũo wa kũunĩka maĩ nthĩnĩ wake na eĩtu make; o na ndaaĩkĩa kw’oko kwa ngya na athĩni vinya.'),
('kam', 'EZK', 16, 50, 'Nao maĩ na wĩng’athĩlĩlyo, na meeka ũthatyo mbee wakwa: kwondũ wa ũu namaveta o tondũ noonie wĩ ũseo.'),
('kam', 'EZK', 16, 51, 'O na Samalia ndaaĩka nyunzu ya naĩ syaku; ĩndĩ nĩwingĩvĩtye mothatyo maku kwĩ mo, na nũtumĩte eĩtu‐a‐mwenyu matalwa alũngalu kwondũ wa mothatyo maku onthe ala wĩkĩte.'),
('kam', 'EZK', 16, 52, 'Naku we, ĩkuĩe nthoni syaku, ila ũsilĩlĩte eĩtu‐a‐mwenyu; kwondũ wa naĩ syaku ila weekie ila ithatasya kwĩ ĩ syoo, nao nĩ alũngalu kwĩ we: ĩĩ, naku soomanĩwa, na kua nthoni syaku, nũndũ nũtumĩte eĩtu‐a‐mwenyu matalwa alũngalu.'),
('kam', 'EZK', 16, 53, 'Na ngamatũnga maume kũtavwanĩ kwoo, kũtavwa kwa Sotomo na eĩtu make, na kũtavwa kwa Samalia na eĩtu make, na kũtavwa kwa atave maku ala me katĩ woo;'),
('kam', 'EZK', 16, 54, 'nĩ kana wĩkuĩe nthoni syaku, na kũsonoka nũndũ wa w’onthe ũla wĩkĩte, nũndũ wĩ ũkiakisyo kwoo.'),
('kam', 'EZK', 16, 55, 'Na eĩtu‐a‐mwenyu, Sotomo na eĩtu make, makasyokea mwĩkalĩle woo wa mbee; na Samalia na eĩtu make makasyokea mwĩkalĩle woo wa mbee; naku na eĩtu maku mũkasyokea mwĩkalĩle wenyu wa mbee.'),
('kam', 'EZK', 16, 56, 'Nũndũ mwĩĩtu‐a‐nyukwe Sotomo ndaawetwa nĩ kanyw’a waku mũthenyanĩ wa ngathĩĩo yaku,'),
('kam', 'EZK', 16, 57, 'ũthũku waku ũtanamba kũvuũwa, ta ĩvinda ya kũvũthya kwa eĩtu ma Silia, na onthe ala mamũthyũlũlũkĩte, eĩtu ma Avilisiti, ala makũvũthasya ngalĩ syonthe.'),
('kam', 'EZK', 16, 58, 'Nũkuĩte wathe waku na mothatyo maku, easya ũu Yeova.'),
('kam', 'EZK', 16, 59, 'Nũndũ ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nakwa ngakwĩka o tondũ weekie, we ũla wavũthisye wĩvĩto ũkyananga ũtianĩo.'),
('kam', 'EZK', 16, 60, 'Ĩndĩ o na ũu w’onthe ngalilikana ũtianĩo wakwa ũla natianĩe naku mĩthenya ya wana waku, na ngakũlũlũmĩlĩlya ũtianĩo wa tene na tene.'),
('kam', 'EZK', 16, 61, 'Nĩvo ĩndĩ ũkalilikana mĩendele yaku, na kũsonoka, yĩla ũkosa eĩtu‐a‐mwenyu, eĩtu‐a‐mwenyu ala akũũ, na ainau; na ngakũnenga mo methĩwe eĩtu maku, ĩndĩ ti kwondũ wa ũtianĩo waku.'),
('kam', 'EZK', 16, 62, 'Na ngalũlũmĩlya ũtianĩo wakwa naku; ũkamanya ninyie Yeova;'),
('kam', 'EZK', 16, 63, 'nĩ kana ũtonye kũlilikana, na kũsoomanĩwa, ũte kwathamya kanyw’a waku o na ĩndĩĩ, nũndũ wa nthoni syaku, yĩla ngakũekea maũndũ asu onthe ala weekie, easya ũu Mwĩanĩi Yeova.'),
('kam', 'EZK', 17, 1, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 17, 2, 'Mwana wa mũndũ, kwatan’ya ndaĩ, na tavya nyũmba ya Isilaeli ngelekan’yo;'),
('kam', 'EZK', 17, 3, 'nokyasya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ndiũ nene yĩ nthwau nene na nzĩa ndasa, i nthwau syusũĩte maw’ĩa, ala maĩ na langi wa mĩthemba mingĩ, yooka Levanoni, na yoosa mũthya wa ĩũlũ wa mũkũũ:'),
('kam', 'EZK', 17, 4, 'yatila kala kakolwa ka ĩũlũ mbee, na yakatwaa nthĩ ya kũtandĩthya; yavanda ndũanĩ ya atandĩthya.'),
('kam', 'EZK', 17, 5, 'O na yoosa mbeũ ya ĩ nthĩ, na yamĩvanda mũthanganĩ ũla ũsyaaa mũno; yamia ũtee wa manzĩ maingĩ; yamĩvanda ta mũtĩ ũla ũmeaa ũsĩnĩ.'),
('kam', 'EZK', 17, 6, 'Na yamea, na yatw’ĩka mũsavivũ mũtambu mũno wĩ mũkuvĩ, ũla ndĩso syaw’o nĩsyoosyookee, na mĩi yaw’o yaĩ ĩtheo yaw’o; ta ũu yatw’ĩka mũsavivũ, na watambya ndĩso, na kũete tũkolwa.'),
('kam', 'EZK', 17, 7, 'O na kwaĩ ndiũ ĩngĩ yaĩ na nthwau nene na maw’ĩa maingĩ: na, sisya, mũsavivũ, ũsu wathyũũa mĩi yaw’o wamyelekelya, na ndĩso syaw’o syathongooa imyelekele, kuma mĩtaũnĩ vala ũvandĩtwe, nĩ kana yũnyithye.'),
('kam', 'EZK', 17, 8, 'Wavandwa mũthanganĩ mũseo vakuvĩ na manzĩ maingĩ, nĩ kana ũthongoosye mbonge, na nĩ kana ũsyae ũsyao, nĩ kana wĩthĩwe mũsavivũ mũseo.'),
('kam', 'EZK', 17, 9, 'Neena atĩĩ, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ũkaaĩla? Ndakakũa mĩi yaw’o, na kũtila usyao waw’o, nĩ kana ũvove; nĩ kana matũ maw’o onthe ala ũthongooetye ma wenze mavove? Na ti kwondũ wa kw’oko kwĩ vinya kana andũ aingĩ ũtonya kũkũanĩw’a na mĩi yaw’o.'),
('kam', 'EZK', 17, 10, 'Ĩĩ, sisya, wavandwa, ũkaaĩla? Ndũkavova vyũ, yĩla kĩseve kyumĩte wumĩlonĩ wa syũa kĩkaũuutanĩa? Ũkavovea mĩtaũnĩ vala wavandiwe.'),
('kam', 'EZK', 17, 11, 'O na ĩngĩ ndeto ya Yeova yambukĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 17, 12, 'Mĩtavye ĩla nyũmba ng’endu, Mũtyĩsĩ ũalyũlo wa maũndũ aa? Matavye, Sisya, mũsumbĩ wa Mbaviloni nĩwokie Yelusaleme, na akwata mũsumbĩ wa kw’o, na anene me mbee ũsumbĩnĩ ma kw’o, na amatwaa kwake Mbaviloni.'),
('kam', 'EZK', 17, 13, 'Na oosa wa ũsyao wa kĩũsumbĩ, na atianĩa ũtianĩo nake; o na amũingĩĩsya evĩte, na atwaa ala me na ũtonyi ma ĩ nthi;'),
('kam', 'EZK', 17, 14, 'nĩ kana ũsumbĩ ũnyivw’e, ndũkeyũkĩlye, ĩndĩ ũndũ wa ũlũmya ũtianĩo wake nũtonya kũũngama.'),
('kam', 'EZK', 17, 15, 'Ĩndĩ nĩwamũng’endeie nũndũ wa ũtũma atũmwa make Misili, nĩ kana mamũnenge mbalasi na andũ aingĩ. Nake akaunĩka? Akavonoka ũla wĩkaa maũndu ta asu? Akaananga ũtianĩo, na ĩndĩ aivonoka?'),
('kam', 'EZK', 17, 16, 'O tondũ nĩ thayu, easya Mwĩaĩi Yeova, vate ndĩi vandũ vala mũsumbĩ wĩkalaa ũla wamũtw’ĩkĩthisye mũsumbĩ, ũla wavũthisye wĩvĩto wake, na ũla wanangie ũtianĩo wake, e nake ku Mbaviloni katĩ akakw’a.'),
('kam', 'EZK', 17, 17, 'O na Valao ndakamũtethya kaũnĩ na ĩta syake syĩ vinya na nguthu yake nene, yĩla makomba mbumbu na kwaka ngome, mavete andũ aingĩ.'),
('kam', 'EZK', 17, 18, 'Nũndũ nũvũthĩtye wĩvĩto kwondũ wa kwananga ũtianĩo; na sisya, nĩwanenganie kw’oko kwake, o na eekie maũndũ asu onthe; ndakavonoka.'),
('kam', 'EZK', 17, 19, 'Kwondũ wa ũu Mwĩaĩi Yeova easya atĩĩ: O tondũ nĩ thayũ, vate ndĩi wĩvĩto wakwa ũla wavũthisye, na ũtianĩo wakwa ũla wanangie, ngaete ĩũlũ wa mũtwe wake mwene.'),
('kam', 'EZK', 17, 20, 'Na ngalan’ya kĩtei kyakwa ĩũlũ wake, na akakwatw’a nĩ mũkwa wakwa, na ngamũete Mbaviloni, na ngamũsĩlĩĩla kw’o nũndũ wa ĩvĩtyo yake yĩla wambĩtanisye.'),
('kam', 'EZK', 17, 21, 'N akĩi make onthe nguthunĩ syake syonthe makavalũkw’a na ũvyũ, na ala metiwa makanyaĩĩkw’a melekele kĩla kĩseve: na mũkamanya kana nyie, Yeova, nĩnĩneenete ũu.'),
('kam', 'EZK', 17, 22, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: O nakwa ngoosa mũthya wĩ ĩũlũ wa mũkũũ, na ngoovanda; ngatema katĩ wa tũkolwa twa ĩũlũ mũno kamwe kololo, na ngakavanda kĩĩmanĩ kĩtũlu na kĩnene:'),
('kam', 'EZK', 17, 23, 'kĩĩmanĩ kĩtũlu kya Isilaeli ngakavanda; na kakathongoosya mbonge, na kũsyaa ũsyao, na kwĩthĩwa mũkũũ mũseo: na nyũnyi syonthe sya kĩla mũthemba wa nthwau ikekala ĩtina waw’o; ikekala muunyĩnĩ wa mbonge syaw’o.'),
('kam', 'EZK', 17, 24, 'Na mĩtĩ yonthe ya kĩthekanĩ ĩkamanya kana nyie, Yeova, nĩnĩtheeetye mũtĩ mũasa, nĩnĩnenevetye mũtĩ mũkuvĩ, nĩnũmĩthĩtye mũtĩ mwĩũ, na nĩnĩthongooetye mũtĩ mũmũ: nyie, Yeova, nĩnĩneenete na nĩnĩkĩte ũu.'),
('kam', 'EZK', 18, 1, 'Ndeto ya Yeova yambũkĩa ĩngĩ, ĩkĩmbĩa,'),
('kam', 'EZK', 18, 2, 'Mwĩasya ata mũineena nthimo ĩno ũndũ wa nthĩ ya Isilaeli, mũkyasya, Aaĩthe nĩmaĩe nzavivũ syĩ ngaati, na maeo ma syana maya nthithi?'),
('kam', 'EZK', 18, 3, 'O tondũ nĩ thayũ, easya Maĩaĩi Yeova, mũtikethĩwa na kĩtumi kya kũneena nthimo ĩsu ĩngĩ nthĩnĩ wa Isilaeli.'),
('kam', 'EZK', 18, 4, 'Sisya, mathayũ onthe nĩ makwa; o tondũ thayũ wa ĩthe nĩ wakwa, now’o thayũ wa mwana nĩ wakwa: na mũndũ ũla wĩkaa naĩ, akakw’a.'),
('kam', 'EZK', 18, 5, 'Ĩndĩ ethĩwa mũndũ nĩ mũlũngalu na ekaa ũla wosanaa na mĩao na ũla wa w’o,'),
('kam', 'EZK', 18, 6, 'na ndaaĩa iĩmanĩ, o na ndaamyũkĩlĩlya mĩvw’anano ya nyũmba ya Isilaeli metho make, o na ndaavukya kĩveti kya mũtũi wake, o na ndaathengeea mũndũ mũka ũla wealũlĩte,'),
('kam', 'EZK', 18, 7, 'na ndaamwĩka mũndũ o na wĩva naĩ, ĩndĩ nũmũtũngĩĩte mũkovwa ngwatĩlĩlyo yake, ndaaosa kĩndũ na mbuta, nũnengete ala me na nzaa lĩu wake, na nũmavw’ĩkĩte ngũa ala athei;'),
('kam', 'EZK', 18, 8, 'ndaakovethya atũngĩwe ũtandĩthyo, o na ndaaosa wongeleko, nũtũngĩte kw’oko kwake ndakeke ũthũku, nũsilanĩtye mũndũ na mũndũ na sila wa katĩ,'),
('kam', 'EZK', 18, 9, 'nake nũendaa myamũlonĩ yakwa, na nũkwatĩte motw’ĩo makwa, ekae w’o; ũsu nĩ mũlũngalũ, ndatĩa kwĩkala thayũ, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 18, 10, 'Ethĩwa akasyaa mwana mũvutani, mwĩtĩkya wa nthakame, na ũla wĩkaa ũmwe wa maũndũ asu,'),
('kam', 'EZK', 18, 11, 'na ndekaa ũmwe wa maũndũ asu ala waĩle kwĩka, ĩndĩ nake nĩwaĩĩe iĩmanĩ, na nũvukĩtye kĩvetĩ kya mũtũi wake,'),
('kam', 'EZK', 18, 12, 'nũmekĩte naĩ ngya na athĩni, nũvutanĩte, ndaatũnga ngwatĩlĩlyo, na nũmyũkĩlĩlye mĩvw’anano metho make, nĩwĩkĩte ũthatyo,'),
('kam', 'EZK', 18, 13, 'nũkovethetye aitũngĩwa ũtandĩthyo, na nĩwosete wongeleko; ũsu akekala thayu? Ndakekala thayũ: nĩwĩkĩte mothatyo asu onthe; ndatĩa ũkw’a; nthakame yake ĩkeethĩwa ĩũlũ wake.'),
('kam', 'EZK', 18, 14, 'Na, sisya, ethĩwa akasyaa mwana, ũla wonaa naĩ syonthe sya ĩthe wake, ila wekie, na nũkĩaa, na ndekaa naĩ ta isu;'),
('kam', 'EZK', 18, 15, 'ndaaĩa iĩmanĩ, o na ndaamyũkĩlĩlya mĩvw’anano ya nyũmba ya Isilaeli metho make, ndaavukya kĩveti kya mũtũi wake,'),
('kam', 'EZK', 18, 16, 'o na ndaamwĩka mũndũ o na wĩva naĩ, ndaaosa kĩndũ kĩthĩwe ngwatĩlĩlyo, o na ndaavutana, ĩndĩ nũnengete ala me na nzaa lĩu wake, na nũvw’ĩkĩte ngũa ala athei;'),
('kam', 'EZK', 18, 17, 'nũtũngĩte kw’oko kwake ndakathĩn’ye ngya, ndaakovethya atũngĩwe ũtandĩthyo kana wongeleko, nĩwĩkĩte motw’ĩo makwa, nũendete myamũlonĩ yakwa; ũsu ndakakw’a kwondũ wa ũthũku wa ĩthe wake, ndatĩa kwĩkala thayũ.'),
('kam', 'EZK', 18, 18, 'Ũndũ wa ĩthe wake, nĩkwĩthĩwa nĩwathĩnasya na thĩna mwai, aĩvuta mwana‐a‐ĩthe, na akĩka ũla ũte ũseo katĩ wa andũ make, sisya, akakw’a e ũthũkunĩ wake.'),
('kam', 'EZK', 18, 19, 'Ĩndĩ inyw’ĩ mwĩasya, Nũndũ wa kĩ mwana ndakuaa ũthũku wa ĩthe? Yĩla wĩkĩte ũla wosanaa na mĩao na ũla wa w’o nũkwatĩte myamũlo yakwa yonthe, na nũmĩkĩte, ndatĩa kwĩkala thayũ.'),
('kam', 'EZK', 18, 20, 'Mũndũ ũla wĩkaa naĩ, ndatĩa kũkw’a: mwana ndakakua ũthũku wa ĩthe, o na ĩthe ndakakua ũthũku wa mwana; ũlũngalu wa ũla mũlũngalu ũkekala ĩũlũ wake, na ũthũku wa ũla mũthũku ũkekala ĩũlũ wake.'),
('kam', 'EZK', 18, 21, 'Ĩndĩ ethĩwa ũla mũthũku akeethyũũa na kũtia naĩ syake syonthe ila wĩkĩte, na kũkwataa myamũlo yakwa yonthe, na kwĩkaa ũla wosanaa na mĩao na ũla wa w’o, ndatĩa kwĩkala thayũ, ndakakw’a.'),
('kam', 'EZK', 18, 22, 'Ĩvĩtyo o na yĩva ya mavĩtyo make ala wĩkĩte yĩtikalilikanwa ĩũlũ wake: ũlũngalunĩ wake ũla wĩkĩte akekala thayũ.'),
('kam', 'EZK', 18, 23, 'Nyie nĩndanĩthaw’a nĩ kĩkw’ũ kya ũla mũthũku? Ekũlya ũu Mwĩaĩi Yeova; na ti kavaa asyoke kũtia mũendele wake, na kwĩkala thayũ?'),
('kam', 'EZK', 18, 24, 'Ĩndĩ yĩla ũla mũlũngalu ũkethyũũa na kũtia ũlũngalu wake, na kwĩkaa ũthũku, na kwĩkaa kwĩanana na mothatyo onthe ala mũndũ mũthũku wĩkaa, ũsu akekala thayũ? O na ũmwe wa meko make malũngalu ala wekie ndũkalilikanwa: ĩvĩtyonĩ yake yĩla wavĩtisye, na naĩnĩ yake ĩla wekie, akakw’ĩa nthĩnĩ wasyo.'),
('kam', 'EZK', 18, 25, 'Ĩndĩ inyw’ĩ mwĩasya, Nzĩa ya Mwĩaĩi ndĩanene. Ĩthukĩĩsye, we nyũmba ya Isilaeli: Nzĩa yakwa ndĩanene? Nzĩa syenyu tisyo iteanene?'),
('kam', 'EZK', 18, 26, 'Yĩla mũndũ mũlũngalu ũkethyũũa na kũtia ũlũngalu wake, nayĩka ũthũku, na kũkw’ĩa nthĩnĩ waw’o; akakw’ĩa ũthũkunĩ wake ũla wekie.'),
('kam', 'EZK', 18, 27, 'Na ĩngĩ, yĩla mũndũ mũthũku ũkethyũũa na kũtia ũthũku wake ũla wekie, na kwĩkaa ũla wosanaa na mĩao na ũla wa w’o, akeetangĩĩa ekale thayu.'),
('kam', 'EZK', 18, 28, 'Nĩkwĩthĩwa nũsũanĩaa, na kwĩthyũũa na kũtĩa mavĩtyo make onthe ala wekie, ndatĩa kwĩkala thayũ, ndakakw’a.'),
('kam', 'EZK', 18, 29, 'Ĩndĩ nyũmba ya Isilaeli ĩasya, Nzĩa ya Mwĩaĩi ndĩanene. We nyũmba ya Isilaeli, nzĩa syakwa ityĩanene? Nzĩa syenyu tisyo iteanene?'),
('kam', 'EZK', 18, 30, 'Kwondũ wa ũu ngakũsilĩla, we nyũmba ya Isilaeli, kĩla ũmwe kwĩanana na mĩendele yake, easya ũu Mwĩaĩi Yeova. Syokai, na mũkĩthyũũa na kũtia mavĩtyo menyu enthe; na ĩndĩ ũthũku ndũkethĩwa wanangĩko wenyu.'),
('kam', 'EZK', 18, 31, 'Ĩkyai kũasa nenyu mavĩtyo menyu onthe, ala mwavĩtisye; ĩseũvĩsyei ngoo nzaũ na veva mweũ: nĩkĩ mũũkw’a, inyw’ĩ nyũmba ya Isilaeli?'),
('kam', 'EZK', 18, 32, 'Nũndũ ndi na ũtanu kĩkw’ũnĩ kya ũla ũnũũkw’a, easya ũu Mwĩaĩi Yeova: kwondũ wa ũu ĩthyũũei, na kwĩkala thayũ.'),
('kam', 'EZK', 19, 1, 'Na ĩngĩ, ambĩlĩlya kĩĩo ũndũ wa anene me mbee ũsumbĩnĩ ma Isilaeli,'),
('kam', 'EZK', 19, 2, 'nokyasya, Ĩnyĩa waku aĩ mwaũ? Mũnyambũ mũka: nĩwamandĩkie katĩ wa mĩnyambũ, aĩthĩsye maswii make katĩ wa mĩnyambũ ya mũika.'),
('kam', 'EZK', 19, 3, 'Na aea yĩmwe ya maswii make; yatw’ĩka mũnyambũ wa mũika, na weemanyĩsya kũkwataa sya nzyĩma; naw’o waya andũ.'),
('kam', 'EZK', 19, 4, 'O na i mbaĩ nĩsyeewie ũvoo waw’o; naw’o wakwatĩw’a ĩimanĩ yasyo; na syooete na mboloi nthĩ ya Misili.'),
('kam', 'EZK', 19, 5, 'Na yĩla wonie nĩweteleete, na vati wĩkwatyo, nĩvo ĩndĩ wosie yĩngĩ ya maswii make, na ayĩtw’ĩkĩthya mũnyambu wa mũika.'),
('kam', 'EZK', 19, 6, 'Naw’o wanganga kũũ na kũũ katĩ wa mĩnyambũ; na watw’ĩka mũnyambũ wa mũika, na weemanyĩsya kũkwata sya nzyĩma; naw’o waya andũ.'),
('kam', 'EZK', 19, 7, 'Na wamanya nyũmba syasyo mbanakavye, na watw’ĩkĩthya ndũa syasyo maanzo; na nthĩ yaĩ nthei, na wusũu wayo, nũndũ wa kĩlonzo kya kũluma kwaw’o.'),
('kam', 'EZK', 19, 8, 'Nĩvo ĩndĩ i mbaĩ syawũkĩe ngalĩ syonthe kuma ilungunĩ nene sya nthĩ; na syalan’ya kĩtei kyasyo ĩũlũ waw’o; naw’o wakwatĩw’a ĩimanĩ yasyo.'),
('kam', 'EZK', 19, 9, 'Syawĩkĩa kyũũnĩ na mboloi, na syooete kwa mũsumbĩ wa Mbaviloni; mooete ngomenĩ syĩ vinya, wasya waw’o ndũkaaĩw’ĩke ĩngĩ iĩmanĩ sya Isilaeli.'),
('kam', 'EZK', 19, 10, 'Inyia waku ailyĩ mũsavivũ, nthakamenĩ yaku, ũvandĩtwe vakuvĩ na manzĩ: waĩ na ũsyao na wusũĩtwe mbonge nũndũ wa manzĩ kwingĩva.'),
('kam', 'EZK', 19, 11, 'Na waĩ na mbonge syĩ vinya kwondũ wa ndata sya ala masumbĩkaa, na kĩũngamo kyaw’o kyookĩla katĩ wa mbonge nthungu, na wooneka ũtũlunĩ waw’o vamwe na wingĩ wa mbonge syaw’o.'),
('kam', 'EZK', 19, 12, 'Ĩndĩ wakũwa ũthilĩkunĩ, wekw’a nthĩ, na kĩseve kyumĩte wumĩlonĩ wa syũa kyoomĩthya ũsyao waw’o: ndata syaw’o syĩ vinya syatũlangwa na syooma; na mwaki waivĩvya.'),
('kam', 'EZK', 19, 13, 'Na yu nũvandĩtwe weũnĩ, nthĩ nyũmũ na yĩ waũni.'),
('kam', 'EZK', 19, 14, 'Na mwaki nĩwũmĩte ndatanĩ sya mbonge syaw’o, nũminĩte ũsyao waw’o, kwondũ wa ũu nthĩnĩ waw’o vati ũvonge wĩ vinya kwondũ wa ndata ya kũsumbĩka. Kĩĩ nĩ kĩĩo, na kĩkeethĩwa nĩkyo kĩĩo.'),
('kam', 'EZK', 20, 1, 'Na kweethĩwa mwaka wa mũonza, mwei wa katano, mũthenya wa ĩkũmi wa mwei, amwe ma atumĩa ma Isilaeli mooka makũlye Yeova, na mekala nthĩ mbee wakwa.'),
('kam', 'EZK', 20, 2, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 20, 3, 'Mwana wa mũndũ, neena na atumĩa ma Isilaeli, noimea, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nĩmwooka kũngũlya nyie? O tondũ nĩ thayũ, easya Mwĩaĩi Yeova, ndĩkũlw’a nĩ inyw’ĩ.'),
('kam', 'EZK', 20, 4, 'Ukamasilĩla, mwana wa mũndũ, ũkamasilĩla? Mamanyĩthye mothatyo ma aaĩthe moo;'),
('kam', 'EZK', 20, 5, 'noimea, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Mũthenya ũla nanyuvie Isilaeli, na nawĩavĩe ũsyao wa nyũmba ya Yakovo, na neemanyĩthanisye kwoo ku nthĩ ya Misili, yĩla nameavie, ngyasya, Ninyie Yeova Ngai wenyu;'),
('kam', 'EZK', 20, 6, 'mũthenya o ũsu nameavĩa, kũmaumya nthĩ ya Misili kũvika nthĩ ĩla namathianĩe, yusũĩte ĩia na ũkĩ wa nzũkĩ, nayo yĩ ndaĩa kwa nthĩ yonthe.'),
('kam', 'EZK', 20, 7, 'Na namea, Ĩkyai kĩla mũndũ mothatyo ma metho, na mũĩkevukye na mĩvw’anano ya Misili; ninyie Yeova Ngai wenyu.'),
('kam', 'EZK', 20, 8, 'Ĩndĩ mang’endea, na malea kũmbĩthukĩĩsya; matyaaĩkya kũasa kĩla mũndũ mothatyo ma metho make, o na matyaatia mĩvw’anano ya Misili. Nĩvo ĩndĩ naisye ngamonoesya ũthilĩku wakwa, nĩanĩsye ũthatu wakwa ĩũlũ woo me nthĩ ya Misili.'),
('kam', 'EZK', 20, 9, 'Ĩndĩ nĩneekie kwondũ wa syĩtwa yakwa, yĩtikathũkw’e methonĩ ma i mbaĩ, ila maĩ katĩ wasyo, ila methonĩ masyo neemanyĩthanisye kwoo, ngĩmaumya nthĩ ya Misili.'),
('kam', 'EZK', 20, 10, 'Kwondũ wa ũu nĩnamaumisye nthĩ ya Misili, na namaete weũnĩ.'),
('kam', 'EZK', 20, 11, 'Na namanenga myamũlo yakwa, na namon’ya motw’ĩo makwa, ala ethĩwa mũndũ nũmekaa, akekala thayũ kwondũ wamo.'),
('kam', 'EZK', 20, 12, 'O na ĩngĩ namanenga masavato makwa, methĩwe ũvano katĩ wakwa nao, nĩ kana mamanye ninyie Yeova ũla ũmavathanasya methĩwe atheu.'),
('kam', 'EZK', 20, 13, 'Ĩndĩ nyũmba ya Isilaeli yang’endeea weũnĩ: matyaaenda myamũlonĩ yakwa, na malea motw’ĩo makwa, ala ethĩwa mũndũ nũmakwataa, akekala thayũ kwondũ wamo; na mavukya masavato makwa mũno. Nĩvo ĩndĩ naisye ngamonoesya ũthilĩku wakwa me weũnĩ, nĩmamine.'),
('kam', 'EZK', 20, 14, 'Ĩndĩ nĩneekie kwondũ wa syĩtwa yakwa, yĩtikavukw’e methonĩ ma i mbaĩ ila syoonie ngĩmaumya.'),
('kam', 'EZK', 20, 15, 'O na ĩngĩ nameavĩĩa weũnĩ, atĩ ndĩkamalikya nthĩnĩ wa nthĩ ĩla namanengie, yusũĩte ĩia na ũkĩ wa nzũkĩ, nayo yĩ ndaĩa kwa nthĩ syonthe;'),
('kam', 'EZK', 20, 16, 'nĩkwĩthĩwa nĩmaleile motw’ĩo makwa, na matyaaenda myamũlonĩ yakwa, na mavukya masavato makwa: nũndũ ngoo syoo nĩsyaatĩĩe mĩvw’anano yoo.'),
('kam', 'EZK', 20, 17, 'Ĩndĩ itho yakwa yamaekea, na ndyaamananga, o na ndyaamaminĩa vyũ weũnĩ.'),
('kam', 'EZK', 20, 18, 'Na naitavĩsya syana syoo weũnĩ, Mũtikaaende myamũlonĩ ya aaĩthe menyu, o na mũtĩkaakwate motw’ĩo moo, kana kwĩvukya na mĩvw’anano yoo.'),
('kam', 'EZK', 20, 19, 'Ninyie Yeova Ngai wenyu: endaai myamũlonĩ yakwa, na kwataai motw’ĩo makwa, na mũimekaa;'),
('kam', 'EZK', 20, 20, 'na vathan’yai masavato makwa methĩwe matheu; na makeethĩwa ũvano katĩ wakwa nenyu, nĩ kana mũmanye ninyie Yeova Ngai wenyu.'),
('kam', 'EZK', 20, 21, 'Ĩndĩ syana nĩsyang’endeie; ityaaenda myamũlonĩ yakwa, o na ityaakwata motw’ĩo makwa imeke, ala ethĩwa mũndũ nũmekaa, akekala thayũ kwondũ wamo; nĩsyavukisye masavato makwa. Nĩvo ĩndĩ naisye ngasyonoesya ũthilĩku wakwa, nĩanĩĩsye ũthatu wakwa kwasyo weũnĩ.'),
('kam', 'EZK', 20, 22, 'Ĩndĩ naveta kw’oko kwakwa, na neeka kwondũ wa syĩtwa yakwa, yĩtikavukw’e methonĩ ma i mbaĩ, ila syoonie ngĩmaumya.'),
('kam', 'EZK', 20, 23, 'Na ĩngĩ nameavĩĩa weũnĩ, kana ngamanyaĩĩkĩsya i mbaĩnĩ, na kũmanyaĩĩkĩsya katĩ wa i nthĩ;'),
('kam', 'EZK', 20, 24, 'nĩkwĩthĩwa matyaaĩka motw’ĩo makwa, ĩndĩ maleile myamũlo yakwa, na mavukisye masavato makwa, na metho moo maatĩĩe mĩvw’anano ya aaĩthe moo.'),
('kam', 'EZK', 20, 25, 'O na ĩngĩ namanenga myamũlo ĩla ĩtaĩ mĩseo, na motw’ĩo ala matatonya kwĩkala thayũ kwondũ wamo;'),
('kam', 'EZK', 20, 26, 'na namavukya mĩthĩnzĩonĩ yoo ene, nũndũ nĩmavĩtĩlye mwakinĩ onthe ala mambaa kuma ĩvunĩ, nĩ kana nĩmatw’ĩkĩthye athei, nĩ kana mamanye ninyie Yeova.'),
('kam', 'EZK', 20, 27, 'Kwondũ wa ũu, mwana wa mũndũ, neena na nyũmba ya Isilaeli, noimea, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Na ĩngĩ ũndũnĩ ũũ aaĩthe menyu nĩmanumĩthisye, nũndũ nĩmambĩtanĩsye.'),
('kam', 'EZK', 20, 28, 'Nũndũ yĩla naminie kũmaete ĩ nthĩ, ĩla nameavĩe nĩmanenge, nĩvo ĩndĩ moonie kĩla kalĩma katũlu, na kĩla mũtĩ mũthungu, na mathembea nthembo syoo kw’o, na maumĩsye ũla ũthatyo wa nthembo yoo kw’o; o na maumĩsya nthembo yoo yĩ mũuke mũseo kw’o, na metĩa nthembo syoo sya kũnyw’a kw’o.'),
('kam', 'EZK', 20, 29, 'Nĩvo ĩndĩ nameie, Nĩ kwa kĩ kũndũ kũtũlu kũla mũendaa? Kwondũ wa ũu syĩtwa ya kw’o yĩtawa Mbama kũvika ũmũnthĩ.'),
('kam', 'EZK', 20, 30, 'Kwondũ wa ũu mĩtavye nyũmba ya Isilaeli, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nĩmwĩvukasya o tondũ aaĩthe menyu meekie? Na kwĩka ũmalwaya mũkĩatĩĩa mothatyo moo?'),
('kam', 'EZK', 20, 31, 'Na yĩla mumasya mĩthĩnzĩo yenyu, yĩla mũũmavĩtĩlya ana menyu mwakinĩ, nĩmwĩvukasya na mĩvw’anano yenyu yonthe kũvika ũmũnthĩ? Na ngakũlw’a nĩ inyw’ĩ, nyũmba ya Isilaeli? O tondũ nĩ thayũ, easya Mwĩaĩi Yeova, ndĩkakũlw’a nĩ inyw’ĩ;'),
('kam', 'EZK', 20, 32, 'na kĩla kĩlikaa kĩlilikanonĩ kyenyu kĩtikethĩwa nongi, nũndũ nĩmũkwasya, Tũkeethĩwa tũilyĩ ta i mbaĩ, ta mĩvĩa ya nthĩ isu, kũthũkũma mĩtĩ na mavia.'),
('kam', 'EZK', 20, 33, 'O tondũ nĩ thayũ, easya Mwĩaĩi Yeova, vate ndĩi ngamũsumbĩka na kw’oko kwĩ vinya, na kw’oko kũtambũũku, na ũthilĩkũ mwonosye.'),
('kam', 'EZK', 20, 34, 'Na ngamumya katĩ wa ngo sya andũ, na ngamũmban’ya kuma nthĩ kũla mwanyaĩĩkĩw’e, na kw’oko kwĩ vinya, na kw’oko kũtambũũku, an ũthilĩku mwonosye;'),
('kam', 'EZK', 20, 35, 'na ngamũete weũnĩ wa ngo sya andũ, na kw’o ngalika silanĩ nenyu ũthyũ kwa ũthyũ.'),
('kam', 'EZK', 20, 36, 'O tondũ nalikile silanĩ na aaĩthe menyu weũnĩ wa nthĩ ya Misili, now’o ngalika silanĩ nenyu, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 20, 37, 'Ngamũvĩtĩlya ĩtheo wa ndata, na ngamũete wovonĩ wa ũtianĩo;'),
('kam', 'EZK', 20, 38, 'na ngamaindũa kwenyu ala ang’endu, na ala mambĩtanĩasya; ngamaumya nthĩ vala mekalaa ũeni, ĩndĩ matikalika nthĩ ya Isilaeli: na mũkamanya ninyie Yeova.'),
('kam', 'EZK', 20, 39, 'Ũndũ wenyu, inyw’ĩ nyũmba ya Isilaeli, ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya; Endai, mũthũkũme kĩla ũmwe mĩvw’anano yake, o na ĩvinda yĩla yũkĩte, ethĩwa mũtikambĩthukĩĩsya; ĩndĩ syĩtwa yakwa ĩtheu mũtikayĩvukye ĩngĩ na mĩthĩnzĩo yenyu, na mĩvw’anano yenyu.'),
('kam', 'EZK', 20, 40, 'Nũndũ kĩĩmanĩ kyakwa kĩtheu, kĩĩmanĩ kĩtũlu kya Isilaeli, easya Mwĩĩai Yeova, kw’o nyũmba yonthe ya Isilaeli, onthe mayo, makanthũkũma me ĩ nthĩ: ku nĩkw’o ngametĩkĩlĩla, na ku nĩkw’o ngamumĩthĩsya nthembo syenyu, na mosyao ma mbee ma nthembo syenyu, vamwe na syĩndũ syenyu syonthe ntheu.'),
('kam', 'EZK', 20, 41, 'Ngamwĩtĩkĩla ta kĩndũ kĩnyungaa nesa, yĩla ngamumya katĩ wa ngo sya andũ, na kũmumya nthĩ ila mwanyaĩĩkĩw’a nthĩnĩ wasyo; na ngeeyonan’ya kwenyu atĩ nĩ mũtheu i mbaĩ syene.'),
('kam', 'EZK', 20, 42, 'Na mũkamanya ninyie Yeova, yĩla nĩmũlikya nthĩ ya Isilaeli, nthĩ ĩla neeavĩe kũnenga aaĩthe menyu.'),
('kam', 'EZK', 20, 43, 'Na mũkalilikanĩla mĩendele yenyu kw’o, na meko menyu onthe, ala mwĩvukĩtye namo; na mũkeemena methonĩ menyu ene ũndũ wa mothũku menyu onthe ala mweekie.'),
('kam', 'EZK', 20, 44, 'Na mũkamanya ninyie Yeova, yĩla ngethĩwa nĩmwĩkĩte kwondũ wa syĩtwa yakwa, tĩ kwĩanana na mĩendele yenyu mĩthũku, kana kwĩanana na meko menyu mathũku, inyw’ĩ nyũmba ya Isilaeli, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 20, 45, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa.'),
('kam', 'EZK', 20, 46, 'Mwana wa mũndũ, elekelye ũthyũ waku ngalĩ ya ĩtheo, na neena ndeto yaku yelekele ngalĩ ya ĩtheo, noyathanĩa mũtitũ wa kĩsesi wa ngalĩ ya Ĩtheo;'),
('kam', 'EZK', 20, 47, 'noiwĩa mũtitũ wa ngalĩ ya Ĩtheo, Ĩthukĩĩsye ndeto ya Yeova: Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya, Sisya, ngakan’ya mwaki nthĩnĩ waku, na ũkavĩvya kĩla mũtĩ mwĩũ wĩ nthĩnĩ waku, na kĩla mũtĩ mũmũ: ũmũĩ mwakanu ndũkavow’a, na mothyũ onthe kuma ngalĩ ya ĩtheo kũvika ngalĩ ya ĩũlũ makavĩvw’a nĩw’o.'),
('kam', 'EZK', 20, 48, 'Na mĩĩ yonthe ĩkoona kana nyie, Yeova, nĩnĩwakanĩtye; na ndũkavow’a.'),
('kam', 'EZK', 20, 49, 'Nĩvo ĩndĩ naisye, A! Mwĩaĩi Yeova! Nĩmekwasya ũndũ wakwa, We tĩ mũneeni wa ngelekan’yo?'),
('kam', 'EZK', 21, 1, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 21, 2, 'Mwana wa mũndũ, elekelya ũthyũ waku Yelusaleme, na neena ndeto yaku yelekele kũndũ kũtheu, noimyathanĩa nthĩ ya Isilaeli;'),
('kam', 'EZK', 21, 3, 'noitavya nthĩ ya Isilaeli, Ũũ nĩw’o Yeova ũnũkwasya: Sisya, nĩ na ũndũ naku, na ngakũa ũvyũ wakwa kumya ndoonĩ yaw’o, na ngaveta kwaku alũngalu na athũku.'),
('kam', 'EZK', 21, 4, 'Na nũndũ ngaveta kwaku alũngalu na athũku, kwondũ wa ũu ũvyũ wakwa ũkauma ndoonĩ yaw’o ũkite na mĩĩ yonthe kuma ngalĩ ya ĩtheo kũvika ngalĩ ya ĩũlũ:'),
('kam', 'EZK', 21, 5, 'na mĩĩ yonthe ĩkamanya nyie, Yeova, nĩnĩkũĩte ũvyũ wakwa kumya ndoonĩ yaw’o; ndũkasyoka ĩngĩ.'),
('kam', 'EZK', 21, 6, 'Kwondũ wa ũu vevũũka, we mwana wa mũndũ; ũkavevũũka mene na metho moo ũndũ wa kũtũlĩka kwa kĩnyunyu kyaku na ũndũ wa woo.'),
('kam', 'EZK', 21, 7, 'Na kũkeethĩwa, yĩla mekũkũlya, Wĩvevũũkw’a nĩ kyaũ? Ũkasũngĩa, Nũndũ wa ũvoo, nũndũ nĩwũkĩte; na kĩla ngoo ĩkatweka, na moko onthe makaleela, na kĩla veva ũkateva, na mau onthe makeethĩwa mate vinya ta manzĩ: sisya, nĩwũkĩte, na ũkeekĩka, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 21, 8, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 21, 9, 'Mwana wa mũndũ, athana, noyasya, Ũũ nĩw’o Yeova ũnũkwasya: Neena, Ũvyũ, ũvyũ, nĩ mũnoe, o na nĩ mũkute;'),
('kam', 'EZK', 21, 10, 'nũnoetwe nĩ kana wũae; nũkutĩtwe nĩ kana wĩthĩwe ta ũtisi: nĩtwaĩlwe nĩ kũtana? Ndata ya mwana wakwa, nĩvũthasya kĩla mũtĩ.'),
('kam', 'EZK', 21, 11, 'Na nũnenganĩtwe ũkutwe, nĩ kana ũkwatangwe: ũvyũ, nũnoetwe, ĩĩ, ũnenganwe kw’okonĩ kwa mũaani.'),
('kam', 'EZK', 21, 12, 'Ĩa noikaya mũno, mwana wa mũndũ; nũndũ ũvyũ wĩ ĩũlũ wa andũ makwa, wĩ ĩũlũ wa anene onthe ma Isilaeli ala me mbee ũsumbĩnĩ: nĩmanenganĩtwe ũvyũnĩ vamwe na andũ makwa; kwondũ wa ũu kũna waswa waku.'),
('kam', 'EZK', 21, 13, 'Nũndũ ve ũtatwa; na nata ethĩwa o na ndata ĩla ĩvũthasya ndĩkethĩwa vo ĩngĩ? Easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 21, 14, 'Kwondũ wa ũu, mwana wa mũndũ, athana, noikũnangan’ya mbĩ syaku; na ũvyũ wongelwe mavinda elĩ, o na mavinda atatũ, ũvyũ wa ala akũnange kũvikĩa kĩkw’ũ; nĩ ũvyũ wa ũla mũnene ũla ũkũnangĩtwe kũvikĩa kĩkw’ũ, ũla ũlikaa tũsũmbanĩ twoo twa nthĩnĩ.'),
('kam', 'EZK', 21, 15, 'Nĩniĩte ũvyũ wa kũtĩsya welekele mbingĩlo syoo syonthe, nĩ kana ngoo syoo itweke, na molulutĩkyo moo maingĩvwe: asi! Ũseũvĩtw’e ta ũtisi, nĩwĩkĩĩtwe mũthya wa kũaana.'),
('kam', 'EZK', 21, 16, 'Ĩyũmban’ye, enda ngalĩ ya kw’oko kwa aũme, ĩtaũsye ũkite, enda ngalĩ ya kw’oko kwa aka, o vala ũthyũ waku welekele.'),
('kam', 'EZK', 21, 17, 'Nakwa ngakũnangan’ya mbĩ syakwa, na ngathũmũsya ũthilĩkũ wakwa: nyie, Yeova nĩnĩneenete ũu.'),
('kam', 'EZK', 21, 18, 'Ndeto ya Yeova yambũkĩa ĩngĩ, ĩkĩmbĩa,'),
('kam', 'EZK', 21, 19, 'Na ĩngĩ, we mwana wa mũndũ, ia nzĩa ilĩ, nĩ kana ũvyũ wa mũsumbĩ wa Mbaviloni wũke; isu syelĩ ikauma nthĩ ĩmwe: na vana vandũ, ũvane wambĩlĩlyonĩ wa nzĩa ĩla ĩendete ndũanĩ.'),
('kam', 'EZK', 21, 20, 'Ũkaia nzĩa ya ũvyũ ya kũka ndũa ya Lava ya ana ma Amimoni, na ya kũka Yuta ku Yelusaleme ndũa mbiie.'),
('kam', 'EZK', 21, 21, 'Nũndũ mũsumbĩ wa Mbaviloni aũngamie mataanĩsyonĩ ma nzĩa, wambĩlĩlyonĩ wa nzĩa isu ilĩ, nĩ kana aaũsye: athũngũthangya mĩsyĩ, akũlya mĩvw’anano yĩtawa telavimu, asisya ĩtema.'),
('kam', 'EZK', 21, 22, 'Kw’okonĩ kwake kwa aũme kwaĩ ĩaũ ya kũaũsya ya Yelusaleme, nĩ kana aie mĩio ya kũomboa vyũ, na kwathamya kanyw’a kũaanwe, na kũkĩlya wasya na kũlonzan’ya, na kwiĩa mbingĩlo mĩio ya kwiomboa, na kũmba mbumbu, na kwaka ngome.'),
('kam', 'EZK', 21, 23, 'Na kũkeethĩwa kwoo ũvũngũ wa kũaũsya methonĩ moo, ala mamevĩtĩe mawĩvĩto; ĩndĩ we nũmalilikanasya ũthũku, nĩ kana makwatwe.'),
('kam', 'EZK', 21, 24, 'Kwondũ wa ũu Mwĩaĩi Yeova easya atĩĩ: Nĩkwĩthĩwa nĩmwatumie ũthũku wenyu ũlilikanwa, nũndũ mavĩtyo menyu nĩ mavue, o kũvika naĩ syenyu nikwoneka mekonĩ menyu onthe; nũndũ nĩmwalilikanwa, mũkakwatwa na kw’oko.'),
('kam', 'EZK', 21, 25, 'Naku, mũthũku, ũla ũkũnangĩtwe kũvikĩa kĩkw’ũ, mũnene wĩ mbee ũsumbĩnĩ wa Isilaeli, ũla mũthenya waku nĩ mũku, ĩvinda ya ũthũku wa mũminũkĩlyo,'),
('kam', 'EZK', 21, 26, 'ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Umya ĩla ngutw’a, na umya ngovia ya mũsumbĩ; isu itikethĩwa itilyĩ ĩngĩ tondũ syailyĩ: nenevya kĩla kĩnyivu, noinyivya kĩla kĩtũlu.'),
('kam', 'EZK', 21, 27, 'Ngang’uthũla, ng’uthũle, nũng’uthũle: ũũ ndũkethĩwa ĩngĩ, kũvika yĩla wĩũka ũla kĩanda kĩ kyake; na ngamũnenga.'),
('kam', 'EZK', 21, 28, 'Naku, mwana wa mũndũ, athana, noyasya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya ũndũ wa ana ma Amimoni, na ũndũ wa kũvũthw’a kwoo; na ũkyasya, Ũvyũ, ũvyũ nũkũĩtwe, nũkutĩtwe ũndũ wa kũaana, ũmine, nĩ kana wĩthĩwe ta ũtisi;'),
('kam', 'EZK', 21, 29, 'yĩla mekwona mawoni ma ũvũngũ ũndũ waku, yĩla meũkũathĩa movũngũ, makwie ngingonĩ sya athũku ala makũnangĩtwe kũvikĩa kĩkw’ũ, ala mũthenya woo nĩ mũku ĩvinda ya ũthũku wa mũminũkĩlyo.'),
('kam', 'EZK', 21, 30, 'Ũtũngĩe ndoonĩ yaw’o. Ngakũsilĩĩla vandũ vala woombĩwe, nthĩ ya kũsyaĩwa kwaku.'),
('kam', 'EZK', 21, 31, 'Na ngakwonoesya ũthatu wakwa; ngakũvuvĩĩa na mwaki wa ũthilĩku wakwa; na ngakũnengane kw’okonĩ kwa andũ mailyĩ ta nyamũ mbai, me na ũĩ wa kwananga.'),
('kam', 'EZK', 21, 32, 'Ũkeethĩwa ngũ sya mwaki; nthakame yaku ĩkeethĩwa ku ĩ nthĩ katĩ; ndũkalilikanwa ĩngĩ: nũndũ nyie, Yeova, nĩnĩneenete ũu.'),
('kam', 'EZK', 22, 1, 'Na ĩngĩ ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 22, 2, 'Naku, mwana wa mũndũ, ũkasilĩla, ũkasilĩla ndũa ya nthakame? Ĩndĩ ũmĩmanyĩthye mothatyo mayo onthe.'),
('kam', 'EZK', 22, 3, 'Na ũkasya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ndũa ĩla yĩtĩkasya nthakame katĩ wayo, nĩ kana ĩvinda yayo yũke, na ĩla yĩseũvĩasya mĩvw’anano ya kwĩvukya!'),
('kam', 'EZK', 22, 4, 'Nũtw’ĩkĩte mũvĩtan’ya nthakamenĩ yaku ĩla wetĩkisye na nĩwĩvukĩtye mĩvw’ananonĩ yaku ĩla waseũvisye; na nũtumĩte mĩthenya yaku ĩthengeea, o na nũvikĩe myaka yaku: kwondũ wa ũu nĩnakũtw’ĩkĩthisye wa kũvũthw’a kwa i mbaĩ, na kũvũĩwa ngũĩ kwa nthĩ syonthe.'),
('kam', 'EZK', 22, 5, 'Ala me vakuvĩ, na ala me kũasa naku, makakũvũĩa ngũĩ, we ũla mũthũku mũno na wusũĩte kĩtuu.'),
('kam', 'EZK', 22, 6, 'Sisya, anene me mbee ũsumbĩnĩ ma Isilaeli, kĩla ũmwe kwĩanana na vinya wake, maĩ nthĩnĩ waku metĩkye nthakame.'),
('kam', 'EZK', 22, 7, 'Nthĩnĩ waku nĩmavũthĩtye ĩthe na nyinyia; katĩ waku nĩmanyamaĩtye mwĩkali wa ũeninĩ; nthĩnĩ waku nĩmamekĩte naĩ ala makwĩĩwe nĩ aaĩthe na aka ndiwa.'),
('kam', 'EZK', 22, 8, 'Nũvũthĩtye syĩndũ syakwa ntheu, na nũvukĩtye masavato makwa.'),
('kam', 'EZK', 22, 9, 'Andũ ala masukanaa maĩ nthĩnĩ waku metĩkye nthakame; na nthĩnĩ waku nĩmaĩĩe lĩu iĩmanĩ ĩũlũ: nthĩnĩ waku nĩmekĩte wathe.'),
('kam', 'EZK', 22, 10, 'Nthĩnĩ waku nĩmavuĩte aaĩthe moo moneke me athei; nthĩnĩ waku nĩmamũthũkĩtye mũndũ mũka ũla wealũlĩte.'),
('kam', 'EZK', 22, 11, 'Na ũmwe nĩwĩkĩte ũthatyo na kĩveti kya mũtũi wake; na ũngĩ nũthũkĩtye mũka wa mwana na wathe; na nthĩnĩ waku ũngĩ nũthũkĩtye mwĩĩtu‐wa‐ĩthe.'),
('kam', 'EZK', 22, 12, 'Nthĩnĩ waku nĩmosete mavaki metĩkye nthakame; nũkovethetye ũtũngĩwe ũtandĩthyo na wongeleko, na nũtandĩthĩtye na ũtoonu atũinĩ maku ũndũ wa kũmathĩn’ya, na nĩwũlĩtwe ninyie, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 22, 13, 'Sisya, kwondũ wa ũu, nĩngũnanganĩtye mbĩ syakwa nũndũ wa ũtandĩthyo waku wa ũkengani ũla watandĩthisye, na nũndũ wa nthakame yaku ĩla yaĩ nthĩnĩ waku.'),
('kam', 'EZK', 22, 14, 'Ngoo yaku nĩtonya kũmĩĩsya, kana moko maku nĩmatonya kwĩthĩwa na vinya, mĩthenya ĩla ngakũsilĩla? Nyie, Yeova, nĩnĩneenete ũu, na ngawĩka.'),
('kam', 'EZK', 22, 15, 'Na ngakũnyaĩĩkĩsya i mbaĩnĩ, na ũkũnyaĩĩkya katĩ wa i nthĩ; na ngamina ũvuku waku ũkũthele.'),
('kam', 'EZK', 22, 16, 'Na ũkavukw’a nthĩnĩ waku mwene, methonĩ ma i mbaĩ; na ũkamanya ninyie Yeova.'),
('kam', 'EZK', 22, 17, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 22, 18, 'Mwana wa mũndũ, nyũmba ya Isilaeli nĩtw’ĩkĩte makwaũ kwakwa: onthe mayo nĩ ũthuku na kĩaa kya ivava na kĩaa na ĩvulũ, nthĩnĩ wa iko ĩnene; nao nĩ makwaũ ma vetha.'),
('kam', 'EZK', 22, 19, 'Kwondũ wa ũu Mwĩaĩi Yeova easya atĩĩ: Nĩkwĩthĩwa inyw’onthe nĩmũtw’ĩkĩte makwaũ, kwondũ wa ũu, sisya, ngamũmban’ya Yelusaleme katĩ.'),
('kam', 'EZK', 22, 20, 'O tondũ mombanasya vetha na ũthuku na kĩaa na ĩvulũ na kĩaa kya ivava ikonĩ ĩnene, maivuvĩĩa mwaki, maitwekethye; o ta ũu ngamũmban’ya inyw’ĩ ũthatunĩ wakwa na kũthilĩkanĩ kwakwa, na ngamwia vo, na kũmũtwekethya.'),
('kam', 'EZK', 22, 21, 'Ĩĩ, ngamũmban’ya, na kũmũvuvĩĩa mwaki wa ũthilĩku wakwa, na mũkatwekethw’a nthĩnĩ wayo.'),
('kam', 'EZK', 22, 22, 'O tondũ vetha ũtwekethaw’a nthĩnĩ wa iko ĩnene, o ta ũu mũkatwekethw’a nthĩnĩ wayo; na mũkamanya kana nyie, Yeova, nĩnonoetye ũthilĩku wakwa ĩũlũ wenyu.'),
('kam', 'EZK', 22, 23, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 22, 24, 'Mwana wa mũndũ, mĩtavye, We wĩ nthĩ ĩte nthesye, o na ĩtaauĩwa mũthenya wa ũthatu.'),
('kam', 'EZK', 22, 25, 'Ve wĩw’ano mũthũku wa athani mayo katĩ wayo, ta mũnyambũ ũkũuuma ũkĩya sya nzyĩma: nĩmaminĩte andũ; nĩmosaa ũthwii mwie na syĩndũ syĩ vata mũno; nĩmatw’ĩkĩthĩtye aka aingĩ mayo ndiwa.'),
('kam', 'EZK', 22, 26, 'Athembi mayo nĩmang’endeete mĩao yakwa, na mavukĩtye syĩndũ syakwa ntheu: matyaavathũkan’ya kĩla kĩtheu na kĩla kĩte kĩtheu, o na matyaatuma andũ mavathũkan’ya kĩla kĩtheu na kĩla kĩte kĩtheu, na nĩmamavithĩte masavato makwa metho moo, na nyie nĩvukĩtwe katĩ woo.'),
('kam', 'EZK', 22, 27, 'Anene mayo me mbee ũsumbĩnĩ nthĩnĩ wayo mailyĩ nzũi ikĩya sya nzyĩma, metĩkye nthakame, na kwananga andũ, nĩ kana mose ũtandĩthyo wa ũkengani.'),
('kam', 'EZK', 22, 28, 'Na athani mayo mavakĩte sokaa ũte mũlue nesa kwondũ woo, makyona mawoni ma ũvũngũ, na maimathĩa movũngũ, makyasya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya, yĩla Yeova ũtaneenete.'),
('kam', 'EZK', 22, 29, 'Andũ ma ĩ nthĩ nĩmathĩnĩtye, na nĩmavutanĩte, ĩĩ, nĩmathĩnĩtye ngya na ala athĩni, na manyamaĩtye mwĩkali wa ũeninĩ na nzĩa ĩte ndũngalu.'),
('kam', 'EZK', 22, 30, 'Na namantha mũndũ katĩ woo, ũla wĩaka ũvai, na kũũngama vandũ vaomboku mbee wakwa kwondũ wa ĩ nthĩ, ndikamyanange; ĩndĩ ndyaaona ũmwe.'),
('kam', 'EZK', 22, 31, 'Kwondũ wa ũu nĩnĩmonoesye ũthatu wakwa; nĩnĩmaminĩte na mwaki wa ũthilĩku wakwa: mũendele woo ene nĩnĩetete ĩũlũ wa mĩtwe yoo, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 23, 1, 'Ndeto ya Yeova yambũkĩa ĩngĩ, ĩkĩmbĩa,'),
('kam', 'EZK', 23, 2, 'Mwana wa mũndũ, kwaĩ aka elĩ, eĩtu ma inyia ũmwe:'),
('kam', 'EZK', 23, 3, 'na meeka ũmalwaya nthĩ ya Misili; meeka ũmalwaya wĩĩtunĩ woo; nondo syoo nĩsyavivĩwe kw’o, na kĩthũi kya wĩĩtu woo kyakwatangĩwa kw’o.'),
('kam', 'EZK', 23, 4, 'Na masyĩtwa moo, ũla mũkũũ eetawa Oola, na mwĩĩtu‐a‐inyia Ooliva: na matw’ĩka makwa, na masyaa ana na eĩtu. Na ũndũ wa masyĩtwa moo, Samalia nĩ Oola, na Yelusaleme nĩ Ooliva.'),
('kam', 'EZK', 23, 5, 'Na Oola eeka ũmalwaya yĩla waĩ wakwa; na amenda mũno endwa make, nao nĩ Aasuli atũi make,'),
('kam', 'EZK', 23, 6, 'ala meevw’ĩkĩte ngũa sya vuluu, makavana na asumbĩki, onthe anake ma kwendwa, andũ maendaa makuĩtwe nĩ mbalasi.'),
('kam', 'EZK', 23, 7, 'Na eeka ũmalwaya wake nao, andũ onthe ala aseo mbee ma Asuli; na o ala wamendaa, nĩwevukisye na mĩvw’anano yoo yonthe.'),
('kam', 'EZK', 23, 8, 'O na ndaatia ũmalwaya wake kuma mĩthenya ya Misili; nũndũ yĩla waĩ wĩĩtunĩ wake nĩmakomaa nake, na makwatangaa kĩthũi kya wĩĩtu wake; na mamwĩtĩkĩsya ũmalwaya woo.'),
('kam', 'EZK', 23, 9, 'Kwondũ wa ũu namũnengane kw’okonĩ kwa endwa make, kw’okonĩ kwa Aasuli, ala wamendaa.'),
('kam', 'EZK', 23, 10, 'Asu mamũvua oneke e mũthei; moosa ana make na eĩtu make; na mamũaa na ũvyũ: na atw’ĩka wa kũvũthĩĩw’a akanĩ; nũndũ nĩmamũsilĩle.'),
('kam', 'EZK', 23, 11, 'Na mwĩĩtu‐a‐inyia Ooliva oona ũu, ĩndĩ nake aĩ mũthũku kwĩ we kwendanĩ kwake, na ũmalwayanĩ wake ũla waĩ mwingĩ kwĩ ũmalwaya wa mwĩĩtu‐a‐inyia.'),
('kam', 'EZK', 23, 12, 'Nĩwamendaa Aasuli, makavana na asumbĩki, atũi make, meevw’ĩkĩte ngũa mbanakavye, andũ maendaa makuĩtwe nĩ mbalasi, onthe anake ma kwendwa.'),
('kam', 'EZK', 23, 13, 'Na noona nĩwavukĩtw’e; asu elĩ nĩmaendaa na nzĩa ĩmwe.'),
('kam', 'EZK', 23, 14, 'Nake aingĩvya ũmalwaya wake; nũndũ nĩwonie aũme mavanĩtwe ũvainĩ, mĩvw’ano ya Akalitei mĩvane na langi mũtune mũno,'),
('kam', 'EZK', 23, 15, 'mavotoete inyunyu syoo mĩsivi, na mĩtwenĩ yoo mekĩĩte ngutw’a syĩkĩĩtwe langi, onthe anene me mbee ũsumbĩnĩ kwonekanĩ kwoo, kũatĩĩa mũvw’anĩle wa Ambaviloni nthĩ ya Kalitei, nthĩ ĩla masyaĩwe.'),
('kam', 'EZK', 23, 16, 'Na o yĩla wamonie amenda, na amatũmĩa atũmwa ku Kalitei.'),
('kam', 'EZK', 23, 17, 'Na Ambaviloni mathi vala ũĩ ũkomonĩ wa wendo, na mamũvukya na ũmalwaya woo, nake avukanĩw’a nao, na ngoo yake yataanĩsya nao.'),
('kam', 'EZK', 23, 18, 'Kwondũ wa ũu avua ũmalwaya wake, na eevua oneke e mũthei: nĩvo ĩndĩ ngoo yakwa yataanĩsya nake, o tondũ ngoo yakwa yataanĩsye na mwĩĩtu‐a‐inyia wake.'),
('kam', 'EZK', 23, 19, 'Ĩndĩ aingĩvya ũmalwaya wake, akĩlilikana mĩthenya ya wĩĩtu wake, yĩla wekie ũmalwaya e nthĩ ya Misili.'),
('kam', 'EZK', 23, 20, 'Na nĩwamendaa endwa moo, ala mĩĩ yoo ĩilyĩ mĩĩ ya mang’oi, na mũluo woo ũilyĩ mũluo wa mbalasi.'),
('kam', 'EZK', 23, 21, 'O ta ũu nũlilikanaa wathe wa wĩĩtu waku, ũndũ wa kũkwatangwa kĩthũi kyaku nĩ Amisli nũndũ wa nondo sya wĩĩtu waku.'),
('kam', 'EZK', 23, 22, 'Kwondũ wa ũu, we Ooliva, ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, ngakũkĩlĩlya endwa maku, ala ngoo yaku ĩtaanĩtw’e nao, na ngamaete mokite naku kĩla ngalĩko:'),
('kam', 'EZK', 23, 23, 'Ambaviloni na Akalitei onthe, Vekoti na Soa na Koa, na Aasuli onthe vamwe nao; anake ma kwendwa, onthe nĩ makavana na asumbĩki, anene me mbee ũsumbĩnĩ na andũ me ndaĩa, onthe makuĩtwe nĩ mbalasi.'),
('kam', 'EZK', 23, 24, 'Na makakũkĩa na mĩio ya kaũ, makasya ma kaũ, na makasya ma mĩio, na me na nguthu ya ngo sya andũ; makeeyũmban’ya mokite naku me na tũkalo na ngao na ngovia mathyũlũlũkĩte ngalĩ syonthe: na ngamanenga kũsila, na makakũsilĩla kwĩanana na mosilĩlo moo.'),
('kam', 'EZK', 23, 25, 'Na ngakwelekelya kĩwĩu kyakwa, na makakwĩka na ũthatu mwai; makaumya ĩnyiũũ yaku na matũ maku; na ũtialo waku ũkavalũkw’a na ũvyũ: na makoosa ana maku na eĩtu maku; na ũtialo waku ũkavĩvw’a na mwaki.'),
('kam', 'EZK', 23, 26, 'O na makakumya ngũa syaku, na makakũvuta mĩio yaku mĩseo ya wanake.'),
('kam', 'EZK', 23, 27, 'O ta ũu ngakũekethya wathe waku, o na ũmalwaya waku ũla waetie kuma nthĩ ya Misili; nĩ kana ndũkaawũkĩlĩlye metho maku, o na kũlilikana Misili ĩngĩ.'),
('kam', 'EZK', 23, 28, 'Nũndũ ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, ngakũnengane kw’okonĩ kwa ala ũmamenaa, kw’okonĩ kwa ala ngoo yaku yĩtaanĩsye nao;'),
('kam', 'EZK', 23, 29, 'na makakwĩka na kĩmena, na makaveta wĩa waku w’onthe, na makaũtia wĩ mũthei ũte ngũa; na ũthei wa ũmalwaya waku ũkavuũwa woneke wĩ mũthei, wathe waku na ũmalwaya waku syelĩ.'),
('kam', 'EZK', 23, 30, 'Ũkeekwa maũndũ asu, nũndũ nĩwĩkĩte ũmalwaya na i mbaĩ, na nũndũ nũvukĩtw’e nĩ mĩvw’anano yoo.'),
('kam', 'EZK', 23, 31, 'Nũkinyĩte mũendelenĩ wa mwĩĩtu‐a‐nyukwe; kwondũ wa ũu ngakũnenga kĩkombe kyake kw’okonĩ kwaku.'),
('kam', 'EZK', 23, 32, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ũkanyw’a kĩkombe kya mwĩĩtu‐a‐nyukwe, kĩla kĩ kĩliku na kĩnene; ũkathekeewa mũno na kũvũthw’a; nĩ kyusĩe ki.'),
('kam', 'EZK', 23, 33, 'Ũkausũw’a ũthengi na woo, kĩkombe kya ũseng’ya na wanangĩko, kĩkombe kya mwĩĩtu‐a‐nyukwe Samalia.'),
('kam', 'EZK', 23, 34, 'Ũkakĩnyw’a na kũkĩng’ũlũlya, na ũkaveveta ilĩo syakyo, na ũkatembũanga nondo syaku; nũndũ nĩnĩneenete ũu, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 23, 35, 'Kwondũ wa ũu Mwĩaĩi Yeova easya: Nũndũ nĩwũlĩtwe ninyie, na nũndũngĩte ĩtina waku, kwondũ wa ũu kua wathe waku na ũmalwaya waku.'),
('kam', 'EZK', 23, 36, 'Na ĩndĩ Yeova angũlya: Mwana wa mũndũ, ũkasilĩla Oola na Ooliva? Ĩndĩ matavye mothatyo moo.'),
('kam', 'EZK', 23, 37, 'Nũndũ nĩmekĩte ũlaalai, na nthakame yĩ mokonĩ moo; na nĩmekĩte ũlaalai na mĩvw’anano yoo; o na ana moo, ala manzyaĩe, mavĩtĩlya mwakinĩ kwondũ wayo mavĩvw’e.'),
('kam', 'EZK', 23, 38, 'Na ĩngĩ nĩmambĩkĩte ũũ: nĩmavukisye vandũ vakwa vatheu mũthenya o ũsu, na mavukĩtye masavato makwa.'),
('kam', 'EZK', 23, 39, 'Nũndũ yĩla mamyũaĩĩte mĩvw’anano yoo syana syoo, nĩvo ĩndĩ mookie o mũthenya ũsu vandũnĩ vakwa vatheu mavavukye; na, sisya, ũu nĩmeekĩe nyũmbanĩ yakwa nthĩnĩ.'),
('kam', 'EZK', 23, 40, 'Na ũndũ ũngĩ nĩmũtũmanĩte andũ maume kũasa, ala mũtũmwa watũmiwe kwoo, na, sisya, nĩmokie; na wathamba, na wavaka metho maku langi, na weeyanakavya na mĩio ya wanake kwondũ woo,'),
('kam', 'EZK', 23, 41, 'na wekalĩla ũkomo wa ndaĩa, na mesa yalanĩtw’e mbee waw’o, ĩla waiĩte ũvani wakwa na mauta makwa.'),
('kam', 'EZK', 23, 42, 'Na wasya wa andũ aingĩ ala mathũmũĩte waĩ nake: na vamwe na andũ mate ndaĩa nĩkwaetiwe athengi kuma weũnĩ; na mamekĩa asu elĩ itang’a mokonĩ moo, na ngovia sya ũsumbĩ nzeo mũno mĩtwenĩ yoo.'),
('kam', 'EZK', 23, 43, 'Nĩvo ĩndĩ naisye ũndũ wa ũla waĩ mũkũũ molaalainĩ, Yu makeeka ũmalwaya nake, nake nao.'),
('kam', 'EZK', 23, 44, 'Na malika vala waĩ, o tondũ malikaa kwa ĩlwaya: now’o malikaa kwa Oola na kwa Ooliva, aka athe.'),
('kam', 'EZK', 23, 45, 'Na andũ alũngalu makamasilĩla na ũsilĩlo wa ilaalai, na ũsilĩlo wa aka ala metĩkasya nthakame; nĩkwĩthĩwa nĩ ilaalai, na nthakame yĩ mokonĩ moo.'),
('kam', 'EZK', 23, 46, 'Nũndũ ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ngamaetee nguthu, na ngamanengane mekangw’e kũũ na kũũ na kũvutwa.'),
('kam', 'EZK', 23, 47, 'Na nguthu ĩkamakimanga na mavia, na kũmoaa na mbyũ syoo; makooaa ana moo na eĩtu moo, na kũvĩvya nyũmba syoo na mwaki.'),
('kam', 'EZK', 23, 48, 'Ta ũu ngatuma wathe ũthela ĩ nthĩ, nĩ kana aka onthe mamanyĩw’e matikaatĩĩe wathe wenyu.'),
('kam', 'EZK', 23, 49, 'Na makamũĩva wathe wenyu, na mũkakua naĩ sya mĩvw’anano yenyu; na mũkamanya ninyie Mwĩaĩi Yeova.'),
('kam', 'EZK', 24, 1, 'Ĩngĩ, mwaka wa kenda, mwei wa ĩkũmi, mũthenya wa ĩkũmi wa mwei, ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 24, 2, 'Mwana wa mũndũ, andĩka syĩtwa ya mũthenya, o mũthenya ũũ: mũsumbĩ wa Mbaviloni nũthengeeie Yelusaleme mũthenya o ũũ.'),
('kam', 'EZK', 24, 3, 'Na tavya ĩla nyũmba ng’endu ngelekan’yo, noimea, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya, Tinĩsya kĩteve, kĩtinĩsye, o na ĩkĩa manzĩ nthĩnĩ wakyo:'),
('kam', 'EZK', 24, 4, 'osan’ya ilungu wĩkĩe nthĩnĩ wakyo, o kĩla kĩlungu kĩseo, kũũ, na kw’oko; kyusũsye mavĩndĩ ala maseo mbee.'),
('kam', 'EZK', 24, 5, 'Osa ila nzeo sya ndĩthya ya mbũi na malondu, o na ũmbanĩsya kĩvumbu kya mavĩndĩ ungu wakyo; noikĩtheũkya mũno; ĩĩ, mavĩndĩ makyo matheũkw’e me nthĩnĩ wakyo.'),
('kam', 'EZK', 24, 6, 'Kwondũ wa ũu Mwĩaĩi Yeova easya: Woo nĩ wa ndũa ya nthakame, na wa kĩteve kĩla ĩtheũko yakyo yĩ nthĩnĩ wakyo, na ĩtheũko yakyo yĩtinauma nthĩnĩ wakyo! Umya nthĩnĩ wakyo kĩlungu na kĩlungu; kũti mũlimano o na wĩva waavalũka ĩũlũ wayo.'),
('kam', 'EZK', 24, 7, 'Nũndũ nthakame yayo yĩ katĩ wayo; yamiie ĩũlũ wa ĩvia ĩthei; ndĩaamĩta ĩũlũ wa nthĩ, ĩmĩvw’ĩke na kĩtoo.'),
('kam', 'EZK', 24, 8, 'Nĩ kana ĩtume ũthilĩku wũkĩla wĩĩvanĩsye, nĩniĩte nthakame yayo ĩũlũ wa ĩvia ĩthei, ndĩkavw’ĩkwe.'),
('kam', 'EZK', 24, 9, 'Kwondũ wa ũu Mwĩaĩi Yeova easya: Woo nĩ wa ndũa ya nthakame! Nakwa nganenevya mbumbu ĩthĩwe nene.'),
('kam', 'EZK', 24, 10, 'Ĩkĩa ngũ mbingĩ, akan’ya mwaki, theũkya nyama mũno, noiseũvya mũsavũ mũkamu, na mavĩndĩ mavĩvw’e.'),
('kam', 'EZK', 24, 11, 'Na ĩndĩ kie kĩ kĩthei ĩũlũ wa makaa makyo, nĩ kana kĩthĩwe kĩ kĩvyũ, na ũthuku wakyo ũvĩvw’e, na nĩ kana ũvuku wakyo ũtwekee nthĩnĩ wakyo, nĩ kana yĩla ĩtheũko yakyo yĩthele.'),
('kam', 'EZK', 24, 12, 'Nĩkĩnoetye na wĩa; ĩndĩ ĩtheũko yakyo yingĩ yĩtyumaa nthĩnĩ wakyo; ĩtheũko yakyo yĩtyumaa kwondũ wa mwaki.'),
('kam', 'EZK', 24, 13, 'Ũvukunĩ waku ve wathe: nĩkwĩthĩwa nĩnĩkũtheetye na ndwaathea, ndũkathew’a ũvuku waku ĩngĩ, kũvika yĩla ngathũmũsya ũthilĩku wakwa kwaku.'),
('kam', 'EZK', 24, 14, 'Nyie, Yeova, nĩnĩneenete ũu: kũkeekĩka na ngawĩka; ndikasyoka ĩtina, o na ndikaekea, o na ndiketũnga; kwĩanana na mĩendele yaku, na kwĩanana na meko maku, makakũsilĩla, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 24, 15, 'O na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 24, 16, 'Mwana wa mũndũ, sisya, nĩngumya kwaku na ĩkũna yĩmwe kĩla kyendetwe nĩ metho maku: ĩndĩ ndũkamete kana kũĩa, o na methoi maku maiketĩke.'),
('kam', 'EZK', 24, 17, 'Vevũũka, ũvindĩtye, ndũkametee ũla mũkw’ũ; ĩyove kakovila kaku, noyĩkĩa iatũ syaku maũũnĩ maku, na ndũkavw’ĩke ilomo syaku, o na ndũkaye lĩu wa andũ.'),
('kam', 'EZK', 24, 18, 'Na ĩndĩ naneena na andũ asu kĩoko; na wĩoo kĩveti kyakwa kyakw’a; na kĩoko neeka ũndũ neaĩwe.'),
('kam', 'EZK', 24, 19, 'Na andũ mangũlya, Ndwĩtũtavya maũndũ aa ũndũ mailyĩ kwitũ, kana wĩke ũu?'),
('kam', 'EZK', 24, 20, 'Nĩvo ĩndĩ namatavisye, Ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 24, 21, 'Neena na nyũmba ya Isilaeli, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, ngavukya vandũ vakwa vatheu, ngathĩĩo ya vinya wenyu, kĩla kyendetwe nĩ metho menyu, na kĩla ngoo yenyu ĩkĩw’ĩa tei; na ana menyu na eĩtu menyu ala mwatiie ĩtina makavalũkw’a na ũvyũ.'),
('kam', 'EZK', 24, 22, 'Na mũkeeka o tondũ nĩkĩte: mũtikavw’ĩka ilomo syenyu, kana kũya lĩu wa andũ.'),
('kam', 'EZK', 24, 23, 'Na tũkovila twenyu tũkeethĩwa mĩtwenĩ yenyu, na iatũ syenyu maũũnĩ menyu: mũtikameta kana kũĩa; ĩndĩ mũkasonzomea ũthũkunĩ wenyu, na kũmalumanĩla ũmwe na ũla ũngĩ.'),
('kam', 'EZK', 24, 24, 'O ta ũu Esekieli akeethĩwa ũvano kwenyu; kwĩanana na w’onthe ũla wekie nĩw’o mũkeka: yĩla ũu wĩũka, nĩvo mũkamanya ninyie Mwĩaĩi Yeova.'),
('kam', 'EZK', 24, 25, 'Naku, mwana wa mũndũ, kũtikethĩwa mũthenya yĩla nĩmaumya vinya woo, ũtanu wa ndaĩa yoo, kĩla kyendetwe nĩ metho moo, na kĩla mend na ngoo yoo, ana moo na eĩtu moo,'),
('kam', 'EZK', 24, 26, 'kana mũthenya o ũsu ũla wĩvonoka akakũkĩa, atume wĩw’a ũu na matũ maku?'),
('kam', 'EZK', 24, 27, 'Mũthenya ũsu kanyw’a waku ũkaathamw’a kwa ũsu mũvonoku, na ũkaneena, na ndũkethĩwa ũtatonya kũneena ĩngĩ: o ta ũu ũkeethĩwa ũvano kwoo; nao makamanya ninyie Yeova.'),
('kam', 'EZK', 25, 1, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 25, 2, 'Mwana wa mũndũ, elekelya ana ma Amimoni ũthyũ waku, noimathanĩa:'),
('kam', 'EZK', 25, 3, 'na matavye ana ma Amimoni, Ĩthukĩĩsyei ndeto ya Mwĩaĩi Yeova: Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya, Nĩkwĩthĩwa waisye, Aa! Ĩũlũ wa vandũ vakwa vatheu, yĩla vavukiw’e; na ĩũlũ wa nthĩ ya Isilaeli, yĩla yatw’ĩwe nthei; na ĩũlũ wa nyũmba ya Yuta, yĩla maendie me atave:'),
('kam', 'EZK', 25, 4, 'kwondũ wa ũu, sisya, ngakũnengane kwa ana ma ngalĩ ya wumĩlonĩ wa syũa wĩthĩwe woo, na makamba myako yoo ya maeema nthĩnĩ waku, na kũseũvya mawĩkalo moo nthĩnĩ waku; makaĩsaa mosyao ma mĩtĩ yaku, na makanyusaa ĩia yaku.'),
('kam', 'EZK', 25, 5, 'Na ngatw’ĩkĩthya Lava nyũmba ya ngamĩle, na ana ma Amimoni vandũ va kũtindisya ndĩthya sya mbũi na malondu: na mũkamanya ninyie Yeova.'),
('kam', 'EZK', 25, 6, 'Nũndũ ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nĩkwĩthĩwa nũkũnanganĩtye mbĩ syaku, na nũtuangĩĩte maũũ nthĩ, na nũtanĩte na kĩvũthya kyonthe kya ngoo yaku ĩũlũ wa nthĩ ya Isilaeli;'),
('kam', 'EZK', 25, 7, 'kwondũ wa ũu, sisya, nĩnĩkũtambũũkĩsye kw’oko kwakwa, na ngakũnengane wĩthĩwe mũtavo kwa i mbaĩ; na ngakũveta wume ngonĩ sya andũ, na ngatuma waa wume i nthĩ: ngakwananga; na ũkamanya ninyie Yeova.'),
('kam', 'EZK', 25, 8, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nĩkwĩthĩwa Moavi na Seili ikwasya, Sisya, nyũmba ya Yuta ĩilyĩ ta mbaĩ syonthe;'),
('kam', 'EZK', 25, 9, 'kwondũ wa ũu, sisya, ngavingũa ngalĩko ya Moavi kuma ndũanĩ, kuma ndũanĩ syayo ila syĩ mĩvakanĩ yayo, ndaĩa ya ĩ nthĩ, Mbethi‐yesimothi, na Mbaali‐meoni, na Kiliathaimu,'),
('kam', 'EZK', 25, 10, 'kũvika ana ma wumĩlonĩ wa syũa, mũkite na ana ma Amimoni; na ngamanengane methĩwe menyu, nĩ kana ana ma Amimoni matikaalilikanwe katĩ wa i mbaĩ:'),
('kam', 'EZK', 25, 11, 'na ngasilĩla Moavi; an makamanya ninyie Yeova.'),
('kam', 'EZK', 25, 12, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnukwasya: Nĩkwĩthĩwa Etomu nĩyĩkĩte nyũmba ya Yuta kwa kwĩĩvanĩsya, na nĩmĩvĩtanĩĩtye mũno, na nĩyĩĩvanĩĩtye kwoo;'),
('kam', 'EZK', 25, 13, 'kwondũ wa ũu Mwĩaĩi Yeova easya, Ngatambũũkĩsya Etomu kw’oko kwakwa, na ngaveta mũndũ na nyamũ nthĩnĩ wayo; na ngamĩtw’ĩkĩthya nthei kuma Temani; o na kũvika Ndetani makavalũkw’a na ũvyũ.'),
('kam', 'EZK', 25, 14, 'Na ngeeĩvanĩsya ĩũlũ wa Etomu na kw’oko kwa andũ makwa Isilaeli; na makeeka nthĩnĩ wa Etomu kwĩanana na ũthatu wakwa na kwĩanana na kũthilĩka kwakwa; na makamanya ũĩvanĩsyo wakwa, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 25, 15, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nĩkwĩthĩwa Avilisiti nĩmekĩte kwa kwĩĩvanĩsya, na nĩmeĩvanĩsye na kĩvũthya kya ngoo syoo manange na ũthũ ũtatw’ĩkanaa;'),
('kam', 'EZK', 25, 16, 'kwondũ wa ũu Mwĩaĩi Yeova ũnũkwasya, Sisya, ngamatambũũkĩsya Avilisiti kw’oko kwakwa, na ngaveta Akelethi, na kwananga ũtialo ũla wĩkalĩte ũtee wa ũkanga.'),
('kam', 'EZK', 25, 17, 'Na ngeeĩvanĩsya ĩũlũ woo na mokan’yo mai; na makamanya ninyie Yeova, yĩla ngeeĩvanĩsya ĩũlũ woo.'),
('kam', 'EZK', 26, 1, 'Na kweethĩwa mwaka wa ĩkũmi na ũmwe, mũthenya wa mbee wa mwei, ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 26, 2, 'Mwana wa mũndũ, nĩkwĩthĩwa Tile nĩneeneete Yelusaleme, Aa! Nake nũtũlĩtwe ũla waĩ mbingĩlo ya ngo sya andũ; nĩwĩnthyũũĩe; nakwa ngausũwa, nũndũ yu nũtw’ĩkĩthĩtw’e ĩanzo:'),
('kam', 'EZK', 26, 3, 'kwondũ wa ũu Mwĩaĩi Yeova ũnũkwasya, Sisya, nĩ na ũndũ naku, we Tile, na ngambatya mbaĩ mbingĩ syũke kũkita naku, o tondũ ũkanga wũkĩlanasya itulumo syaw’o.'),
('kam', 'EZK', 26, 4, 'Na ikaananga maũvai ma Tile, na kũomboa myako yayo mĩtũlu ya mĩnyoolo: o na ngavyaĩa kĩtoo kyayo, na ũmĩtw’ĩkĩthya ĩvia ĩthei.'),
('kam', 'EZK', 26, 5, 'Ĩkeethĩwa vandũ va kwalan’ya itei sya makũyũ ũkanganĩ katĩ; nũndũ nĩnĩneenete ũu, easya ũu Mwĩaĩi Yeova; na ĩkatw’ĩka mũtavo wa i mbaĩ.'),
('kam', 'EZK', 26, 6, 'Na eĩtu mayo ala me kĩsesinĩ makooawa na ũvyũ: na makamanya ninyie Yeova.'),
('kam', 'EZK', 26, 7, 'Nũndũ ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, ngaete ĩũlũ wa Tile Nevukatilesa mũsumbĩ wa Mbaviloni, mũsumbĩ wa asumbĩ, kuma ngalĩ ya ĩũlũ, e na mbalasi, na makasya ma kaũ, na andũ ma ũtũla mbalasi, na nguthu, na andũ aingĩ.'),
('kam', 'EZK', 26, 8, 'Akooaa na ũvyũ eĩtu maku me kĩsesinĩ; na akakwakĩĩa ngome, na kũkũmbĩĩa mbumbu, na ũkũkĩlĩlya kakalo.'),
('kam', 'EZK', 26, 9, 'Na akaiĩa maũvai maku mĩio yake ya kũmavũthũa, na akaomboa myako yaku mĩtũlu ya mĩnyoolo na mathoka make.'),
('kam', 'EZK', 26, 10, 'Nũndũ wa wingĩ wa mbalasi syake kĩtoo kyasyo kĩkakũvw’ĩka: maũvai maku makathingithanga ũndũ wa kĩlonzo kya ala matũlĩte mbalasi, na kya makasya ma mĩio, na makasya ma kaũ, yĩla wĩlika mbingĩlonĩ syaku, o tondũ andũ malikaa ndũanĩ ĩla yavũthũiwe.'),
('kam', 'EZK', 26, 11, 'Akakinyanga nzĩa syaku syonthe nene na mavũngũ ma mbalasi syake; akooaa andũ maku na ũvyũ; na itũĩ sya vinya waku ikavalũka nthĩ.'),
('kam', 'EZK', 26, 12, 'Na makatava ũthwii waku, na syĩndũ syaku sya kũthoosya ikeethĩwa mũtavo; na makaomboa maũvai maku, na kwananga nyũmba syaku sya kwendeesya; na makeekĩa mavia maku na mĩtĩ yaku na kĩtoo kyaku manzĩnĩ.'),
('kam', 'EZK', 26, 13, 'Ngavindĩthya kĩlonzo kya mbathi syaku; na wasya wa mbeve syaku ndũkew’ĩka ĩngĩ.'),
('kam', 'EZK', 26, 14, 'Na ngakũtw’ĩkĩthya ĩvia ĩthei; ũkeethĩwa vandũ va kwalan’ya itei sya makũyũ; ndũkakwa ĩngĩ: nũndũ nyie Yeova nĩnĩneenete ũu, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 26, 15, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũũkũlya Tile: Ithama itikathingithanga ũndũ wa wasya wa kũvalũka kwaku, yĩla ala okite melumaa, yĩla ũaani ũkethĩwa kwaku?'),
('kam', 'EZK', 26, 16, 'Nĩvo ĩndĩ anene onthe me mbee ũsumbĩnĩ ma ũkanga makatheea kuma ivĩlanĩ syoo sya ũsumbĩ, na kwia nthĩ ngũa syoo ndasa, na kumya ngũa syoo itumĩĩwe wanake: makevw’ĩka kũtetema; makekala nthĩ, na makatetema kĩla kaven’ya, na kũseng’w’a nue.'),
('kam', 'EZK', 26, 17, 'Na makambĩlĩlya ũkũĩĩa, na ũkwĩa, Wanangĩkie ata, we ũla watwĩwe nĩ andũ ala maendaa ũkanganĩ, ndũa ya nguma, ĩla yaĩ na vinya ũkanganĩ, nake na ala make matwĩe kw’o, ala mamatĩsasya onthe ala matwĩe kw’o!'),
('kam', 'EZK', 26, 18, 'Yu ithama ikatetema mũthenya wa kũvalũka kwaku; ĩĩ, ithama syĩ ũkanganĩ ikateva ũndũ wa kũthela kwaku.'),
('kam', 'EZK', 26, 19, 'Nũndũ ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Yĩla ngakũtw’ĩkĩthya ndũa ya ĩanzo, ta ndũa ĩtatwĩwe; yĩla ngambatya manzĩ ma syũngũ nene ĩũlũ waku, na manzĩ maingĩ makakũvw’ĩka;'),
('kam', 'EZK', 26, 20, 'nĩvo ĩndĩ ngakũtheesya vamwe na ala matheeaa yĩla ĩimanĩ, vala ve andũ ma tene, na ngakwĩkalya kũndũ kwĩ nthĩnĩ wa nthĩ, kũndũ kũla kũthei kuma tene, vamwe na ala matheeaa yĩla ĩimanĩ, nĩ kana ndũkaatũwe nĩ andũ; na ngaia ndaĩa nthĩ ya ala me thayũ.'),
('kam', 'EZK', 26, 21, 'Ngakũtw’ĩkĩthya ũtĩsyo, na ndũkethĩwa ĩngĩ; o na ethĩwa ũkamanthwa, ndũkoneka ĩngĩ, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 27, 1, 'Ndeto ya Yeova yambũkĩa ĩngĩ, ĩkĩmbĩa,'),
('kam', 'EZK', 27, 2, 'Naku, mwana wa mũndũ, ambĩlĩlya kĩĩo ũndũ wa Tile;'),
('kam', 'EZK', 27, 3, 'noitavya Tile, We ũla ũtwĩe ũlikĩlonĩ wa ũkanga, wĩ mũthoosya kwa ngoosya andũ kwondũ wa ithama nyingĩ, ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: We, Tile, ũneenete, Nyie nĩ mwĩanĩu kwanakavanĩ.'),
('kam', 'EZK', 27, 4, 'Mĩvaka yaku yĩ nthĩnĩ wa maũkanga; aki maku nĩmeanĩĩtye kwanakava kwaku.'),
('kam', 'EZK', 27, 5, 'Nĩmaseũvĩtye mbwaũ syaku syonthe sya ngalawa sya mĩtĩ ya mĩsonovali kuma Senili; nĩmosete mũkũũ ku Levanoni makũseũvĩsye mũlingoti.'),
('kam', 'EZK', 27, 6, 'Nĩmaseũvĩtye mĩtĩ yaku ya ũkũtwaa ya mĩtĩ ya myaloni ya ku Mbasani; nĩmaseũvĩtye ivĩla syaku sya mĩtĩ ya mĩvuena ithũĩĩwe na tũlungu twa maeo ma nzou, kuma ithamanĩ sya Kitimu.'),
('kam', 'EZK', 27, 7, 'Ngũa yaku ĩla yĩkĩawa mũtĩnĩ ĩkwate kĩseve yaĩ ya katane nzeo yatumĩĩwe wanake ku Misili, nĩ kana yĩthĩwe kwaku kĩvevelo; kyandalua kyaku kyaĩ kya vuluu na kya langi wailyĩ mũtune kuma ithamanĩ sya Elisaa.'),
('kam', 'EZK', 27, 8, 'Ala matwĩe Sitoni na Alivati maĩ atwai maku: andũ maku oĩ, we Tile, maĩ nthĩnĩ waku, nĩmo maĩ atongoi maku.'),
('kam', 'EZK', 27, 9, 'Atumĩa ma Ngevali o na andũ oĩ ma vo nĩmo malindaa mbatũku syaku: ngalawa syonthe sya ũkanganĩ vamwe na andũ ala maendaa nasyo maĩ nthĩnĩ waku matandĩthye syĩndũnĩ syaku sya ũthoosya.'),
('kam', 'EZK', 27, 10, 'Andũ ma Velisia na Luti na Vutu maĩ itanĩ syaku, andũ maku ma kaũ: nĩmanĩkie ngao na ngovia nthĩnĩ waku; nĩmoonanisye ndaĩa yaku.'),
('kam', 'EZK', 27, 11, 'Andũ ma Alivati vamwe na ita syaku maĩ maũvainĩ maku ngalĩ syonthe, na andũ me na ũkũmbaũ maĩ myakonĩ yaku mĩtũlu ya mĩnyoolo; nĩmanĩkie ngao syoo maũvainĩ maku ngalĩ syonthe; nĩmeanĩĩtye kwanakava kwaku.'),
('kam', 'EZK', 27, 12, 'Talisisi yathooasya kwaku nũndũ wa wingĩ wa mĩthemba yonthe ya ũthwii; makũanasya vetha, na kĩaa, na kĩaa kya ivava, na ĩvulũ, na syĩndũ syaku sya ũthoosya.'),
('kam', 'EZK', 27, 13, 'Yavani, Tuvali, na Meseki, maĩ atandĩthya kwaku; makũanasya mathayũ ma andũ na mĩio ya ũthuku na syĩndũ syaku sya ũthoosya.'),
('kam', 'EZK', 27, 14, 'Ala ma nyũmba ya Tokalima maetae mbalasi na mbalasi sya kaũ na nyũmbũ makũan’ye na syĩndũ syaku sya ũthoosya.'),
('kam', 'EZK', 27, 15, 'Andũ ma Ndetani maĩ atandĩthya kwaku; ithama nyingĩ syaĩ ing’ang’a sya kw’oko kwaku: nĩmakũetee makũan’ye mbya sya maeo ma nzou na mũvĩngo,'),
('kam', 'EZK', 27, 16, 'Silia yathoosya kwaku kwondũ wa wingĩ wa mawĩa maku ma moko: maetae nzumalati, na langi ũilyĩ ta mũtune, na ngũa itumĩĩwe wanake, na katane nzeo, na tũvila twa vethaluka, na maliani, makũan’ye na syĩndũ syaku sya ũthoosya.'),
('kam', 'EZK', 27, 17, 'Yuta, na nthĩ ya Isilaeli, syaĩ atandĩthya kwaku: maetae nganũ kuma Minithi, na vanaka, na ũkĩ wa nzũkĩ, na mauta, na seli, makũan’ye na syĩndũ syaku sya ũthoosya.'),
('kam', 'EZK', 27, 18, 'Ndamasiku yathoosya kwaku kwondũ wa wingĩ wa mawĩa maku ma moko, nũndũ wa wingĩ wa mĩthemba yonthe ya ũthwii, maetae mbinyu kuma Elivoni, na w’ĩa mweũ wa malondu.'),
('kam', 'EZK', 27, 19, 'Vetani na Yavani makũanasya ndii na syĩndũ syaku sya ũthoosya: kĩaa kĩtue, na kalavuu, na ithua, syaĩ syĩndũnĩ syaku sya ũthoosya.'),
('kam', 'EZK', 27, 20, 'Ndetani yaĩ mũtandĩthya kwaku wa ngũa nzeo sya kwilĩĩla ĩũlũ wa mbalasi.'),
('kam', 'EZK', 27, 21, 'Alavia, na anene onthe me mbee ũsumbĩnĩ ma Ketali, mathooasya kw’okonĩ kwaku; tũtena twa malondũ na ndũũme, na mbũi, nĩsyo mathooasya kwaku.'),
('kam', 'EZK', 27, 22, 'Atandĩthya ma Sieva na Laama, maĩ atandĩthya kwaku; maetae mĩtĩ ĩla yĩ mũuke mũseo mbee, na tũvila tw’onthe twĩ thooa mũnene, na thaavu, makũan’ye na syĩndũ syaku sya ũthoosya.'),
('kam', 'EZK', 27, 23, 'Aalani na Kane na Eteni, atandĩthya ma Sieva, Asuli na Kilimati, maĩ atandĩthya kwaku.'),
('kam', 'EZK', 27, 24, 'Asu maĩ atandĩthya kwaku syĩndũnĩ nzeo, masuka ma vuluu matumĩĩwe wanake, na masandũkũ me ngũa nzeo mũno, movetwe na ndii, na matumĩtwe na mũkũũ, syĩndũnĩ syaku sya ũthoosya.'),
('kam', 'EZK', 27, 25, 'Ngalawa sya Talisisi syaĩ syaku sya ũkua syĩndũ syaku sya ũthoosya: naku wausũwa, na wataĩwa mũno katĩ wa maũkanga.'),
('kam', 'EZK', 27, 26, 'Ala atwai maku makũetie manzĩnĩ maingĩ: kĩseve kyumĩte wumĩlonĩ wa syũa nĩkĩkũtũĩlĩe katĩ wa maũkanga.'),
('kam', 'EZK', 27, 27, 'Mothwii maku, na mĩio yaku, syĩndũ syaku sya ũthoosya, na andũ maku ma ngalawa syaku, na atongoi maku, na maku ala malindaa mbatũku, na akũan’ya ma mĩio yaku, na andũ maku onthe ma kaũ, ala me nthĩnĩ waku, vamwe na nguthu yaku yonthe ĩla yĩ katĩ waku, makavalũka katĩ wa maũkanga mũthenya wa wanangĩko waku.'),
('kam', 'EZK', 27, 28, 'Syengo syĩ ndee ikathingithanga yĩla kwĩ kĩlonzo kya kĩĩo kya atongoi maku.'),
('kam', 'EZK', 27, 29, 'Na onthe ala makwataa mĩtĩ ya kũtwaa, andũ ma ngalawa, na atongoi onthe ma ũkanganĩ, makatheea maume ngalawanĩ syoo; makaũngama nthĩ,'),
('kam', 'EZK', 27, 30, 'na makakwĩw’ĩthya wasya woo, na makaĩa me na woo, na makekya kĩtoo mĩtwenĩ yoo; makeeyalalya mũunĩ:'),
('kam', 'EZK', 27, 31, 'na makeeyenza ũvaa kwondũ waku, na kwĩvotoa makunĩa, na makakũĩĩa me na woo ngoonĩ makĩmeta na woo.'),
('kam', 'EZK', 27, 32, 'Na makĩmeta makambĩlĩlya kĩĩo kwondũ waku, na makakũĩĩa, makyasya, Nũũ ũilyĩ ta Tile, ta ũla ũvindĩthĩtw’e katĩ wa ũkanga?'),
('kam', 'EZK', 27, 33, 'Yĩla syĩndũ syaku sya ũthoosya syaumaw’a maũkakanganĩ, wausũasya ngo mbingĩ sya andũ; wathuasya asumbĩ ma nthĩ na wingĩ wa mothwii maku na wa syĩndũ syaku sya ũthoosya.'),
('kam', 'EZK', 27, 34, 'Ĩvinda yĩla watũlilwe nĩ maũkanga syũngũnĩ sya manzĩ, syĩndũ syaku sya ũthoosya na nguthu yaku yonthe yavalũka katĩ waku.'),
('kam', 'EZK', 27, 35, 'Onthe ala matwĩe ithamanĩ nĩmeũseng’a ũndũ waku, na asumbĩ moo nĩmakĩĩte mũno; nĩmekũũũya mothyũnĩ moo.'),
('kam', 'EZK', 27, 36, 'Athoosya katĩ wa ngo sya andũ nĩmeũkũtimba; nũtw’ĩkĩte ũtĩsyo, na ndũkethĩwa ĩngĩ.'),
('kam', 'EZK', 28, 1, 'Ndeto ya Yeova yambũkĩa ĩngĩ, ĩkĩmbĩa,'),
('kam', 'EZK', 28, 2, 'Mwana wa mũndũ, mwĩe mũnene wĩ mbee ũsumbĩnĩ wa Tile, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nĩkwĩthĩwa ngoo yaku nĩyĩtũlĩtye, naku nĩwaĩtye, Nyie nĩ ngai, nĩkalaa kĩvĩlanĩ kya Ngai, katĩ wa maũkanga; ĩndĩ wĩ mũndũ, na ndwĩ Ngai, o na kau nĩwaiie ngoo yaku ta ngoo ya Ngai;—'),
('kam', 'EZK', 28, 3, 'sisya, wĩ mũĩ kwĩ Ndanieli; vati nzama ĩvithĩte kwaku;'),
('kam', 'EZK', 28, 4, 'kwondũ wa ũĩ waku na ũmanyi waku nĩwĩyone ũthwii, na nĩwĩyosee thaavu na vetha ũilikya mothwiinĩ maku maie;'),
('kam', 'EZK', 28, 5, 'kwondũ wa ũĩ waku mwingĩ na kwondũ wa kũtandĩthya kwaku nĩwingĩvĩtye ũthwii waku, na ngoo yaku nĩyĩtũlĩtye ũndũ wa ũthwii waku;—'),
('kam', 'EZK', 28, 6, 'kwondũ wa ũu Mwĩaĩi Yeova easya: Nĩkwĩthĩwa nĩwiĩte ngoo yaku ta ngoo ya Ngai,'),
('kam', 'EZK', 28, 7, 'kwondũ wa ũu, sisya, ngaete aeni ĩũlũ waku, ala ma ũtĩsya ma i mbaĩ; na makakũĩa mbyũ syoo wanake wa ũĩ waku, na makavukya ũtisu waku.'),
('kam', 'EZK', 28, 8, 'Makakũtheesya ĩimanĩ; na ũkakw’a kĩkw’ũ kya ala mooaĩwe maũkanganĩ nthĩnĩ.'),
('kam', 'EZK', 28, 9, 'Ukaneena mbee wa ũla ũnũũkũaa, Nyie nĩ Ngai? Ĩndĩ we wĩ mũndũ, na ndwĩ Ngai, kw’okonĩ kwa ũla ũkũkitĩte.'),
('kam', 'EZK', 28, 10, 'Ukakw’a kĩkw’ũ kya ala mate aĩke kwondũ wa kw’oko kwa aeni: nũndũ nĩnĩneenete ũu, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 28, 11, 'Na ĩndĩ ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 28, 12, 'Mwana wa mũndũ, ambĩlĩlya kĩĩo ũndũ wa mũsumbĩ wa Tile, noimwĩa, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nĩwĩkĩĩte wĩanĩu ũsiĩlo, wusũĩte ũĩ, na mwĩanĩu kwanakavanĩ.'),
('kam', 'EZK', 28, 13, 'Waĩ Eteni, mũũnda wa Ngai; kĩla kavila ke thooa mũnene kaĩ ka kwĩvw’ĩka kwaku, salitũ, tovasi, na salitonyi, nzumalati ntheu, nzumalati, na yasivi, sumalati, na alimasi ndune, na thaavu; wĩa wa tũthembe twaku na mĩtũlilũ yaku waĩ nthĩnĩ waku; mũthenya ũla woombiwe nĩsyaseũviw’e.'),
('kam', 'EZK', 28, 14, 'Waĩ mũkeluvi ũla wetĩkĩw’e mauta ũla wavw’ĩkaa: na nakwia, o na weethĩwa ĩũlũ wa kĩĩma kĩtheu kya Ngai; nĩwaendaa kũũ na kũũ katĩ wa mavia ma mwaki.'),
('kam', 'EZK', 28, 15, 'Waĩ mwĩanĩu mĩendelenĩ yaku kuma mũthenya ũla woombiwe, kũvika yĩla ũla ũte ũlũngalu woonekie nthĩnĩ waku.'),
('kam', 'EZK', 28, 16, 'Kwondũ wa wingĩ wa kũtandĩthya kwaku makusũsya nthĩnĩ ũng’endu, na nũvĩtĩtye: kwondũ wa ũu nĩnakwĩkisye ta wĩ mũvuku kũkumya kĩĩmanĩ kya Ngai; na nĩngwanangĩte, we mũkeluvi ũla wavw’ĩkaa, ngakumya katĩ wa mavia ma mwaki.'),
('kam', 'EZK', 28, 17, 'Ngoo yaku nĩyĩtũlĩtye nũndũ wa kwanakava kwaku; nũvukĩtye ũĩ waku nũndũ wa ũtisu waku: nĩngwĩkĩtye nthĩ; nĩngwiĩte mbee wa asumbĩ, nĩ kana makwone.'),
('kam', 'EZK', 28, 18, 'Kwondũ wa wingĩ wa mothũku maku, ũndũnĩ ũla ũte ũlũngalu wa kũtandĩthya kwaku, nũvukĩtye kũndũ kwaku kũtheu; kwondũ wa ũu nĩnumĩtye mwaki nthĩnĩ waku; naw’o nũkũvĩvĩtye, nakwa nĩnĩkũtw’ĩkĩthĩtye mũu ĩũlũ wa nthĩ mbee wa onthe ala makwonaa.'),
('kam', 'EZK', 28, 19, 'Onthe ala makwĩsĩ katĩ wa ngo sya andũ makaseng’a ũndũ waku: nũtw’ĩkĩte ũtĩsyo, na ndũkethĩwa ĩngĩ nongi.'),
('kam', 'EZK', 28, 20, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 28, 21, 'Mwana wa mũndũ, elekelya ũthyũ waku Sitoni, noimyathanĩa,'),
('kam', 'EZK', 28, 22, 'ũkyasya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, nĩ na ũndũ naku, we Sitoni; na ngataĩwa nthĩnĩ waku; na makamanya ninyie Yeova, yĩla nĩĩthĩwa nĩminĩte kũmũsilĩla, na kwĩyonan’ya kwake atĩ nĩ mũtheu.'),
('kam', 'EZK', 28, 23, 'Nũndũ ngaete mũimũ nthĩnĩ wake, na nthakame nzĩanĩ nene syake; na ala mokitĩtwe makavalũka nthĩnĩ wake, ũvyũ wĩ ĩũlũ wake kĩla ngalĩko; na makamanya ninyie Yeova.'),
('kam', 'EZK', 28, 24, 'Na kũikethĩwa ĩngĩ mũtae wa kĩthekanĩ ũla ũtonyaa nyũmba ya Isilaeli, kana mwĩw’a ũla wĩw’ĩthasya woo ala mamathyũlũlũkĩte, ala mamavũthisye; na makamanya ninyie Mwĩaĩi Yeova.'),
('kam', 'EZK', 28, 25, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Yĩla ngethĩwa nũmbanĩtye nyũmba ya Isilaeli kũmaumya katĩ wa ngo sya andũ ila manyaĩĩkĩtw’e katĩ wasyo, na nĩyonanĩtye kwoo atĩ nĩ mũtheu i mbaĩ syene, nĩvo ĩndĩ makatũa nthĩ yoo ene ĩla namũnengie mũthũkũmi wakwa Yakovo.'),
('kam', 'EZK', 28, 26, 'Na makekalaa kw’o meyelele; ĩĩ, makaaka nyũmba, na kũvanda mĩũnda ya mĩsavivũ, na makekalaa meyelele, yĩla ngethĩwa nĩminĩte kũmasilĩla onthe ala mamavũthasya mamathyũlũlũkĩte; na makamanya kana ninyie Yeova Ngai woo.'),
('kam', 'EZK', 29, 1, 'Mwaka wa ĩkũmi, mwei wa ĩkũmi, mũthenya wa ĩkũmi na ĩlĩ wa mwei, ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 29, 2, 'Mwana wa mũndũ, elekelya Valao mũsumbĩ wa Misili ũthyũ waku, noimwathanĩa, o na Misili yonthe;'),
('kam', 'EZK', 29, 3, 'neena, noimwĩa, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, nĩ na ũndũ naku, we Valao mũsumbĩ wa Misili, mũkũnga mũnene ũla wĩkalaa mbũsĩnĩ syake, ũla waĩtye, Usĩ wakwa nĩ wakwa mwene, na nĩnzeũvĩtye kwondũ wakwa mwene.'),
('kam', 'EZK', 29, 4, 'Na ngeekĩa mboloi nene ngambuunĩ syaku, na ngatuma makũyũ ma mbũsĩ syaku malũman’ya na makwaũ maku; na ngakumya nthĩnĩ wa mbũsĩ syaku, vamwe na makũyũ onthe ma mbũsĩ syaku ala malũmanasya na makwaũ maku.'),
('kam', 'EZK', 29, 5, 'Na ngakwĩkya weũnĩ, we na makũyũ onthe ma mbũsĩ syaku: ũkavalũka weũnĩ; ndũkombanw’a vamwe, o na ndũkatũngĩanĩwa; nĩnĩkũnenganĩte wĩthĩwe lĩu wa nyamũ sya kũũ nthĩ na nyũnyi sya yayaya.'),
('kam', 'EZK', 29, 6, 'Na onthe ala matwĩe Misili makamanya ninyie Yeova, nĩkwĩthĩwa maĩ ndata ya mũangi kwa nyũmba ya Isilaeli.'),
('kam', 'EZK', 29, 7, 'Yĩla makũkwatie kw’oko kwaku, watũlĩka, na watembũa ituo syoo syonthe; na yĩla makwaĩĩe, watũlĩka, na watuma inyunyu syoo syonthe itetema.'),
('kam', 'EZK', 29, 8, 'Kwondũ wa ũu Mwĩaĩi Yeova nũnũkwasya: Sisya, ngaete ũvyũ ĩũlũ waku, na ngaveta kwaku mũndũ na nyamũ.'),
('kam', 'EZK', 29, 9, 'Na nthĩ ya Misili ĩkeethĩwa nthei na mbanangĩku; na makamanya ninyie Yeova. Nĩkwĩthĩwa nĩwaĩtye, Ũsĩ nĩ wakwa, ninyie nawũmbie;'),
('kam', 'EZK', 29, 10, 'kwondũ wa ũu, sisya, nĩ na ũndũ naku, na mbũsĩ syaku, na ngaananga vyũ nthĩ ya Misili na ĩkeethĩwa nthei, kuma mwako mũtũlu wa mũnyoolo wa Sevene o kũvika mũvaka wa Ethiovia.'),
('kam', 'EZK', 29, 11, 'Vati kũũ kwa mũndũ kũkamĩvĩtĩla, o na kũũ kwa nyamũ kũikamĩvĩtĩla, o na ndĩkatũwa myaka mĩongo ĩna.'),
('kam', 'EZK', 29, 12, 'Na ngatw’ĩkĩthya nthi ya Misili nthei katĩ wa nthĩ ila nthei; na ndũa syayo katĩ wa ndũa ila itw’ĩkĩthĩtw’e maanzo ikeethĩwa nthei myaka mĩongo ĩna; na nganyaĩĩkĩsya Amislili katĩ wa i mbaĩ, na kũmanyaĩĩkĩsya katĩ wa i nthĩ.'),
('kam', 'EZK', 29, 13, 'Nũndũ ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Myaka mĩongo ĩna yathela ngoomban’ya Amisili kuma ngonĩ sya andũ kũla manyaĩĩkĩw’e;'),
('kam', 'EZK', 29, 14, 'na ngatũnga Misili maume kũtavwanĩ, na ngatuma masyoka nthĩ ya Vathilosi, nthĩ ya kũsyaĩwa kwoo; na makeethĩwa kw’o ũsumbĩ ĩtheo vyũ.'),
('kam', 'EZK', 29, 15, 'Katĩ wa mosumbĩ ũkeethĩwa ĩtheo vyũ; o na ndũketũlya ĩngĩ ĩũlũ wa i mbai: na ngamanyivya, nĩ kana matikasumbĩke i mbaĩ ĩngĩ.'),
('kam', 'EZK', 29, 16, 'Na ndũkethĩwa wĩkwatyo wa nyũmba ya Isilaeli ĩngĩ, ũkĩete ũkilikan’yo wa ũthũku, yĩla makethyũũa kũmasisya: na makamanya ninyie Mwĩaĩi Yeova.'),
('kam', 'EZK', 29, 17, 'Na kweethĩwa mwaka wa mĩongo ĩlĩ na mũonza, mwei wa mbee, mũthenya wa mbee wa mwei, ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 29, 18, 'Mwana wa mũndũ, Nevukatilesa mũsumbĩ wa Mbaviloni athũkũmĩthisye ita syake ũthũkũmi mũnene ĩũlũ wa Tile: kĩla mũtwe waya ũvaa, na kĩla kĩtuo kyasyũlĩka; ĩndĩ ndaĩ na ĩtuvi, o na ita syake, kuma Tile, nũndũ wa ũthũkũmi ũla wathũkũmie ĩũlũ wayo.'),
('kam', 'EZK', 29, 19, 'Kwondũ wa ũu Mwĩaĩi Yeova nũnũkwasya: Sisya, ngamũnenga Nevukatilesa mũsumbĩ wa Mbaviloni nthĩ ya Misili; na akatwaa wingĩ wa andũ mayo, na kwosa mũtavo wayo, na kwosa mbuta yayo; na ĩkeethĩwa ĩtuvi ya ita syake.'),
('kam', 'EZK', 29, 20, 'Nĩnĩmũnengete nthĩ ya Misili yĩthĩwe ĩtuvi yake yĩla wathũkũmĩe, nĩkwĩthĩwa nĩmanthũkũmie, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 29, 21, 'Mũthenya ũsu ngathongoosya ũvya nyũmbanĩ ya Isilaeli, na ngakũnenga kwathamya kanyw’a waku katĩ woo; na makamanya ninyie Yeova.'),
('kam', 'EZK', 30, 1, 'Ndeto ya Yeova yambũkĩa ĩngĩ, ĩkĩmbĩa,'),
('kam', 'EZK', 30, 2, 'Mwana wa mũndũ, athana, nokyasya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ĩai, Ĩiaa! Nũndũ wa ũ mũthenya!'),
('kam', 'EZK', 30, 3, 'Nũndũ mũthenya nĩ mũthengeeu, o mũthenya wa Yeova nĩ mũthengeeu; ũkeethĩwa mũthenya wa matu, ĩvinda ya i mbaĩ.'),
('kam', 'EZK', 30, 4, 'Na ũvyũ ũkookĩa Misili, na woo mũnene ũkeethĩwa Ethiovia, yĩla oawa makavalũka ku Misili; na makaveta andũ aingĩ mayo, na myambĩlĩlyo yayo ĩkaombowa.'),
('kam', 'EZK', 30, 5, 'Ethiovia, na Vutu, na Luti, o na andũ onthe mavulanĩte, na Kuvu, na ana ma nthĩ ya ũtianĩo, makavalũkw’a na ũvyũ vamwe nao.'),
('kam', 'EZK', 30, 6, 'Ũũ nĩw’o Yeova ũnũkwasya: O nao ala meũlũman’ya na Misili makavalũka; na ngathĩĩo ũndũ wa vinya wayo ũkatheea: kuma mwakonĩ mũtũlu wa mũnyoolo wa Sevene makavalũkĩlw’a na ũvyũ nthĩnĩ wayo, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 30, 7, 'Na makeethĩwa me athei katĩ wa nthĩ ila nthei; na ndũa syayo ikeethĩwa katĩ wa ndũa ila itw’ĩkĩte maanzo.'),
('kam', 'EZK', 30, 8, 'Na makamanya ninyie Yeova, yĩla nĩĩthĩwa nakanĩtye mwaki nthĩnĩ wa Misili, na atethya mayo onthe nĩmanangĩte.'),
('kam', 'EZK', 30, 9, 'Mũthenya ũsu atũmwa makauma kwakwa maende ngalawanĩ mamatĩsye Aethiovia ala mate kĩio; na kũkeethĩwa woo mũnene ĩũlũ woo, o ta mũthenyanĩ wa Misili; nũndũ, sisya, nĩwũkĩte.'),
('kam', 'EZK', 30, 10, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ngamina wingĩ wa andũ ma Misili, na kw’oko kwa Nevukatilesa mũsumbĩ wa Mbaviloni.'),
('kam', 'EZK', 30, 11, 'We na andũ make vamwe nake, ala ma kũtĩsya ma i mbaĩ, makaetwe manange ĩ nthĩ; na makamĩkũĩa Misili mbyũ syoo, na kusũsya nthĩ ala mooaiwe.'),
('kam', 'EZK', 30, 12, 'Na ngang’alĩthya mbũsĩ, na ngathoosya ĩ nthĩ kw’okonĩ kwa andũ athũku; na ngatw’ĩkĩthya nthĩ ĩsu nthei, na kyonthe kĩla kĩ nthĩnĩ wayo, na kw’oko kwa aeni: nyie, Yeova, nĩnĩneenete ũu.'),
('kam', 'EZK', 30, 13, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: O na ngaananga mĩvw’anano, na ngatuma mĩvw’anano ĩthela ku Memivisi; na kũikethĩwa ĩngĩ mũnene wĩ mbee ũsumbĩnĩ nthĩ ya Misili: na ngeekĩa w’ĩa nthĩ ya Misili.'),
('kam', 'EZK', 30, 14, 'Na ngamĩtw’ĩkĩthya Vathilosi nthei, na ngakan’ya mwaki Nzoani, na ngasilĩla ndũa ya No.'),
('kam', 'EZK', 30, 15, 'Na ngoonoesya ũthilĩku wakwa ĩũlũ wa Sini, ngome yĩ vinya ya Misili; na ngaveta wingĩ wa andũ ma No.'),
('kam', 'EZK', 30, 16, 'Na ngakan’ya mwaki Misili: Sini ĩkeethĩwa na woo mwingĩ, na No ĩkatũlangwa ilungu; na Memivisi ĩkeethĩwa na amaitha o mũthenya.'),
('kam', 'EZK', 30, 17, 'Anake ma Aveni na ma Vi‐vesethi makavalũkw’a na ũvyũ; na ndũa isu ikatavwa.'),
('kam', 'EZK', 30, 18, 'O na kũu Teaveneesi mũthenya ũkeethĩwa kĩvindu, yĩla ngatũlĩla masoki ma Misili kw’o, na ngathĩĩo ũndũ wa vinya wayo ĩkathela nthĩnĩ wayo: na ũndũ wayo, ĩthweo yĩkamĩvw’ĩka, na eĩtu mayo makaenda me atave.'),
('kam', 'EZK', 30, 19, 'Ũũ nĩw’o ngasilĩla Misili; na makamanya ninyie Yeova.'),
('kam', 'EZK', 30, 20, 'Na kweethĩwa mwaka wa ĩkũmi na ũmwe, mwei wa mbee, mũthenya wa mũonza wa mwei, ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 30, 21, 'Mwana wa mũndũ, nĩnĩtũlĩte kw’oko kwa Valao mũsumbĩ wa Misili; na, sisya, kũtyaaovwa, kwĩkĩwe mĩtĩ ya ũvosya, kũlingĩlĩĩlwe kĩtambaa, nĩ kana kwĩthĩwe na vinya wa kũkwata ũvyũ.'),
('kam', 'EZK', 30, 22, 'Kwondũ wa ũu Mwĩaĩi Yeova nũnũkwasya: Sisya, nĩ na ũndũ na Valao mũsumbĩ wa Misili, na ngatũla moko make, kw’oko kwĩ vinya, na kũla kwaĩ kũtũlĩku; na ngatuma ũvyũ ũvalũka kuma kw’okonĩ kwake.'),
('kam', 'EZK', 30, 23, 'Na nganyaĩĩkĩsya Amisili mbaĩnĩ, na kũmanyaĩĩkĩsya katĩ wa i nthĩ.'),
('kam', 'EZK', 30, 24, 'Na ngamekĩa vinya moko ma mũsumbĩ wa Mbaviloni, na kwĩkĩa ũvyũ wakwa kw’okonĩ kwake: ĩndĩ ngatũla moko ma Valao, na akalumĩlaa mbee wake ta kĩlumo kya mũndũ ũkitĩtwe kũvikĩa kĩkw’ũ.'),
('kam', 'EZK', 30, 25, 'Na ngookĩlya moko ma mũsumbĩ wa Mbaviloni; na moko ma Valao makaniina; na makamanya ninyie Yeova, yĩla nĩĩkĩa ũvyũ wakwa kw’okonĩ kwa mũsumbĩ wa Mbaviloni, nake akakũtambũũkya ĩũlũ wa nthĩ ya Misili.'),
('kam', 'EZK', 30, 26, 'Na nganyaĩĩkĩsya Amisili i mbaĩnĩ, na kũmanyaĩĩkĩsya katĩ wa i nthĩ; na makamanya ninyie Yeova.'),
('kam', 'EZK', 31, 1, 'Na kweethĩwa mwaka wa ĩkũmi na ũmwe, mwei wa katatũ, mũthenya wa mbee wa mwei, ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 31, 2, 'Mwana wa mũndũ, mũkũlye Valao mũsumbĩ wa Misili, na nguthu yake: Ũilyĩ taũ ũnenenĩ waku?'),
('kam', 'EZK', 31, 3, 'Sisya, Mũasuli aĩ mũtĩ wa mũkũũ wĩ mbonge nzeo nthĩnĩ wa Levanoni, na wĩ muunyĩ wailyĩ wa mũtitũ, na wa kĩũngamo kĩasa; na mũthya waw’o waĩ katĩ wa mbonge nthungu.'),
('kam', 'EZK', 31, 4, 'Manzĩ moonyithya, manzĩ ma syũngũ moomesya: mbũsĩ syasyo syathyũlũlũka vala wavandiwe; na ikatwaĩa tũlũsĩ twasyo mĩtĩnĩ yonthe ya mũũnda.'),
('kam', 'EZK', 31, 5, 'Kwondũ wa ũu ũtũlu waw’o wambatw’a kwĩ mĩtĩ yonthe ya mũũnda; na mbonge syaw’o syongeleka, na mbonge syaw’o syaasava nũndũ wa manzĩ maingĩ, yĩla wathongooisye.'),
('kam', 'EZK', 31, 6, 'Nyũnyi syonthe sya yayaya syaakaa ndala syasyo mbongenĩ syaw’o; na nyamũ syonthe sya kĩthekanĩ syasyaĩaa maswii masyo ungu wa mbonge syaw’o; na mbaĩ syonthe nene syekalaa muunyĩnĩ waw’o.'),
('kam', 'EZK', 31, 7, 'Waseũvĩte o ta ũu ũnenenĩ waw’o, ũasanĩ wa mbonge syaw’o; nũndũ mũi waw’o waĩ vakuvĩ na manzĩ maingĩ.'),
('kam', 'EZK', 31, 8, 'Mĩkũũ mũũndanĩ wa Ngai ĩtyaatonya kũũvitha; mĩtĩ ya mĩsonovali ndĩailyĩ mbonge syaw’o, na mĩtĩ ya mĩalamoni ndĩailyĩ mbonge syaw’o; o na vatyaĩ mũtĩ o na wiva mũũndanĩ wa Ngai wailyĩ taw’o kwanakavanĩ kwaw’o.'),
('kam', 'EZK', 31, 9, 'Nĩnooseũvisye wĩthĩwe mũseo kwondũ wa wingĩ wa mbonge syaw’o, mũvaka mĩtĩ yonthe ya Eteni, ĩla yaĩ mũũndanĩ wa Ngai, yawĩw’ĩa kĩwĩu.'),
('kam', 'EZK', 31, 10, 'Kwondũ wa ũu Mwĩaĩi Yeova nũnũkwasya: Nĩkwĩthĩwa nũtũlĩtw’e ũasanĩ, na kwia mũthya wake katĩ wa mbonge nthungu, na ngoo yake nĩtũlĩtw’e ũasanĩ wake;'),
('kam', 'EZK', 31, 11, 'ngamũnengane kw’okonĩ kwa ũla wĩ ũtonyi wa i mbaĩ; vate ndĩĩ akatwaatwaana nake; nĩnĩmũlũngĩtye ũndũ wa ũthũku wake.'),
('kam', 'EZK', 31, 12, 'Na aeni, ala ma ũtĩsya ma i mbaĩ, nĩmamũvetete, na nĩmamũtiĩte: mbonge syake nivalũkĩte iĩmanĩ ĩũlũ na myandanĩ yonthe, na mbonge syake nitũlĩkĩte vakuvĩ na mbũsĩ syonthe sya ĩ nthĩ; na ngo syonthe sya andũ sya nthĩ nĩsyatheeie kuma muunyĩnĩ wake, na nĩsyamũtiie.'),
('kam', 'EZK', 31, 13, 'Nyũnyi syonthe sya yayaya ikekala wanangĩkonĩ wake, na nyamũ syonthe sya kĩthekanĩ ikeethĩwa mbongenĩ syake;'),
('kam', 'EZK', 31, 14, 'nĩ kana mĩtĩ yonthe yĩ vakuvĩ na manzĩ ndĩkenenevye ũasanĩ wayo, kana kwia mĩthya yayo katĩ wa mbonge nthungu, kana ĩla yĩ vinya katĩ wayo ĩũngame ũasanĩ wayo, o yonthe ĩla ĩnyusaa manzĩ: nũndũ onthe nĩmanenganĩte makw’e, kũvika kũndũ kwĩ nthĩnĩ wa nthĩ, katĩ wa ana ma andũ, vamwe na ala matheeaa yĩla ĩimanĩ.'),
('kam', 'EZK', 31, 15, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Mũthenya ũla watheeie Seoli nĩnatwie kũmetwe: navw’ĩka syũngũ nene kwondũ wake, na nasiĩĩa mbũsĩ sya vo; na ala manzĩ maingĩ masiĩĩwa; na natuma Levanoni ĩmũmetea, na mĩtĩ yonthe ya kĩthekanĩ yathelekela kwondũ wake.'),
('kam', 'EZK', 31, 16, 'Nathingithangya i mbaĩ ũndũ wa kĩuumo kya kũvalũka kwake, yĩla namwĩkisye Seoli vamwe na ala matheeaa yĩla ĩimanĩ; na mĩtĩ yonthe ya Eteni, ĩla mĩnyuve na mĩseo mbee ya Levanoni, yonthe ĩla ĩnyusaa kĩw’ũ, yakiakiĩw’a kũndũ kwĩ nthĩnĩ wa nthĩ.'),
('kam', 'EZK', 31, 17, 'Nao matheea Seoli vamwe nake vala vaĩ ala mooaiwe na ũvyũ; ĩĩ, ala maĩ kw’oko kwake, ala mekalile muunyĩnĩ wake katĩ wa i mbaĩ.'),
('kam', 'EZK', 31, 18, 'Ũilyĩ taũ ndaĩanĩ na ũnenenĩ katĩ wa mĩtĩ ya Eteni? Ĩndĩ ũkatheew’a vamwe na mĩtĩ ya Eteni kũvika kũndũ kwĩ nthĩnĩ wa nthĩ: ũkakoma katĩ wa ala mate aĩke, vamwe na ala mooaiwe na ũvyũ. Ũsu nĩ Valao na nguthu yake yonthe, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 32, 1, 'Na kweethĩwa mwaka wa ĩkũmi na ĩlĩ, mwei wa ĩkũmi na ĩlĩ, mũthenya wa mbee wa mwei, ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 32, 2, 'Mwana wa mũndũ, ambĩlĩlya kĩĩo ĩũlũ wa Valao mũsumbĩ wa Misili, noimwĩa, Waelekanilw’e na mũnyambũ wa mũika wa i mbaĩ: ĩndĩ ũilyĩ mũkũnga mũnene maũkanganĩ; na waumĩla na vinya mbũsĩnĩ syaku, na wathokoan’ya manzĩ na maũũ maku, na wavukya mbũsĩ syoo.'),
('kam', 'EZK', 32, 3, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ngalan’ya kĩtei kyakwa ĩũlũ waku kya ngo mbingĩ sya andũ; nao makakũkwatya na kĩtei kyakwa.'),
('kam', 'EZK', 32, 4, 'Na ngakũtia wĩ ĩũlũ wa nthĩ, ngakwĩkya weũnĩ, ngatuma nyũnyi syonthe sya yayaya ikũvũĩla, na ngavũnĩthya nyamũ sya nthĩ yonthe na nyama sya mwĩĩ waku.'),
('kam', 'EZK', 32, 5, 'Na ngaia nyama sya mwĩĩ waku ĩĩmanĩ, na kusũsya myanda ũtũlu waku.'),
('kam', 'EZK', 32, 6, 'O na nganyithya na nthakame yaku nthĩ ya kũthambĩa kwaku, o kũvika iĩmanĩ; na mbũsĩ ikausũwa nue.'),
('kam', 'EZK', 32, 7, 'Na yĩla ngakũvosya, ngavw’ĩka matu, na kwĩkĩa ndata kĩvindu; ngavw’ĩka syũa na ĩthweo, na mwei ndũkaumya kyeni kyaw’o.'),
('kam', 'EZK', 32, 8, 'Syeni syonthe sya ĩtunĩ ila itisaa ngaitw’ĩkĩthya kĩvindu ĩũlũ waku, na ngaia kĩvindu ĩũlũ wa nthĩ yaku, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 32, 9, 'O na ngathĩn’ya ngoo sya ngo mbingĩ sya andũ, yĩla nĩete wanangĩko waku katĩ wa i mbaĩ, ũlike nthĩ ila ũtaaimanya.'),
('kam', 'EZK', 32, 10, 'Ĩĩ, ngatuma ngo mbingĩ sya andũ iseng’w’a nue, na asumbĩ moo makakĩa na w’ĩa mwai kwondũ waku, yĩla ngavyũlĩlya ũvyũ wakwa mbee woo; na makatetema kĩla kaven’ya, kĩla mũndũ kwondũ wa thayũ wake mwene, mũthenya wa kũvalũka kwaku.'),
('kam', 'EZK', 32, 11, 'Nũndũ ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ũvyũ wa mũsumbĩ wa Mbaviloni ũkooka ĩũlũ waku.'),
('kam', 'EZK', 32, 12, 'Ngavalũkya aingĩ maku na mbyũ sya ala me na ũtonyi; asu onthe nĩo ala ma ũtĩsya ma i mbaĩ: na makatw’ĩkĩthya ngathĩĩo ya Misili ya mana, na wingĩ w’onthe wa andũ ma vo makaanangwa.'),
('kam', 'EZK', 32, 13, 'O na ngaananga nyamũ syonthe sya vo ila syĩ ũtee wa manzĩ maingĩ; o na kũũ kwa mũndũ kũikamauluan’ya ĩngĩ, kana mavũngũ ma nyamũ maikamauluan’ya.'),
('kam', 'EZK', 32, 14, 'Nĩvo ĩndĩ nĩkelemya manzĩ moo, na ngatwaĩthya mbũsĩ syoo iende ta mauta, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 32, 15, 'Yĩla ngatw’ĩkĩthya nthĩ ya Misili nthei na ĩeketwe, nthĩ ĩthelelwe nĩ kusũa kwayo, yĩla ngakũna onthe ala mamĩtwĩe, nĩvo ĩndĩ makamanya ninyie Yeova.'),
('kam', 'EZK', 32, 16, 'Kĩĩ nĩkyo kĩĩo kĩla makaĩa nakyo; eĩtu ma i mbaĩ makaĩa nakyo; makamĩmetea Misili na wingĩ w’onthe wa andũ mayo nakyo, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 32, 17, 'Na kweethĩwa mwaka wa ĩkũmi na ĩlĩ, mũthenya wa ĩkũmi na ĩtano wa mwei, ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 32, 18, 'Mwana wa mũndũ, ĩa kwondũ wa wingĩ wa andũ ma Misili, noimekya nthĩ, o we, na eĩtu ma mbaĩ syĩ nguma, kũvika kũndũ kwĩ nthĩnĩ wa nthĩ, vamwe na ala matheeaa yĩla ĩimanĩ.'),
('kam', 'EZK', 32, 19, 'Ũvĩtũkĩte ũũ kwanakavanĩ? Theea, noyiwa vamwe na ala mate aĩke.'),
('kam', 'EZK', 32, 20, 'Makavalũka katĩ wa ala mooaiwe na ũvyũ: we nũnenganĩtwe ũvyũnĩ; mũkusye ũmũtwae vamwe na wingĩ wa andũ make.'),
('kam', 'EZK', 32, 21, 'Ala me vinya katĩ wa ala me na ũtonyi makaneena nake me Seoli vamwe na ala mamũtethasya: nĩmatheeete, nĩmakomaa ki, o ala mate aĩke, mooaiwe na ũvyũ.'),
('kam', 'EZK', 32, 22, 'Asuli e vo na nguthu yake yonthe; mbũa syake nimũthyũlũlũkĩte; onthe moaĩtwe, mavalũkĩtw’e na ũvyũ;'),
('kam', 'EZK', 32, 23, 'mbũa syoo siĩtwe kĩtulunĩ kya yĩla ĩima, na nguthu yake nĩthyũlũlũkĩte mbũa yake; onthe moaĩtwe, mavalũkĩtw’e na ũvyũ, ala matĩsasya me nthĩ ya ala me thayũ.'),
('kam', 'EZK', 32, 24, 'Elamu e vo, na wingĩ wa andũ make mathyũlũlũkĩte mbũa yake; onthe moaĩtwe, mavalũkĩtw’e na ũvyũ, ala matheeie mate aĩke kũndũ kwĩ nthĩnĩ wa nthĩ, ala matĩsasya me nthĩ ya ala me thayũ, na nĩmakuĩte nthoni syoo vamwe na ala matheeaa yĩla ĩimanĩ.'),
('kam', 'EZK', 32, 25, 'Nĩmamwiĩe ũkomo katĩ wa ala mooaiwe vamwe na wingĩ w’onthe wa andũ make; mbũa syake nimũthyũlũlũkĩte; onthe mate aĩke, moaĩtwe na ũvyũ; nũndũ ũtĩsyo woo watĩsasya me nthĩ ya ala me thayũ, na nĩmakuĩte nthoni syoo vamwe na ala matheeaa yĩla ĩimanĩ: nĩwiĩtwe katĩ wa ala moaiwe.'),
('kam', 'EZK', 32, 26, 'Meseki, Tuvali, na wingĩ w’onthe wa andũ moo me vo; mbũa syoo nimathyũlũlũkĩte; onthe mate aĩke, moaĩtwe na ũvyũ; nũndũ matĩsasya me nthĩ ya ala me thayũ.'),
('kam', 'EZK', 32, 27, 'Na matikakoma vamwe na ala me na ũtonyi ala mavalũkile ma ala mate aĩke, ala matheeie Seoli me na mĩio yoo ya kaũ, na maiĩte mbyũ syoo ungu wa mĩtwe yoo, na mothũku moo me ĩũlũ wa mavĩndĩ moo; nũndũ maĩ ũtĩsyo wa ala me na ũtonyi nthĩ ya ala me thayũ.'),
('kam', 'EZK', 32, 28, 'Ĩndĩ we ũkatũlĩlwa katĩ wa ala mate aĩke, na ũkakoma na ala mooaiwe na ũvyũ.'),
('kam', 'EZK', 32, 29, 'Etomu e vo, asumbĩ make na anene make onthe me mbee ũsumbĩnĩ, ala me na vinya woo makomiw’e vamwe na ala mooaiwe na ũvyũ: makakoma na ala mate aĩke, na vamwe na ala matheeaa yĩla ĩimanĩ.'),
('kam', 'EZK', 32, 30, 'Me vo anene me mbee ũsumbĩnĩ ma ngalĩ ya ĩũlũ, onthe, na Asitoni onthe, ala matheeie vamwe na ala oawa; nĩmeũsonokw’a ũtĩsyonĩ ũla meekie kwondũ wa vinya woo; na nĩmakomaa mate aĩke vamwe na ala mooaiwe na ũvyũ na nĩmakuaa nthoni syoo vamwe na ala matheeaa yĩla ĩimanĩ.'),
('kam', 'EZK', 32, 31, 'Valao akamona, na akakiakiw’a kwondũ wa wingĩ wa andũ make, o Valao na ita syake syonthe, moaĩtwe na ũvyũ, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 32, 32, 'Nũndũ nĩnĩkĩĩte ũtĩsyo wake nthĩ ya andũ me thayũ; na akaiwa katĩ wa ala mate aĩke, vamwe na ala mooaiwe na ũvyũ, o Valao, na wingĩ w’onthe wa andũ make, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 33, 1, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 33, 2, 'Mwana wa mũndũ, neena na ana ma andũ maku, noimatavya, Yĩla nĩete ũvyũ ĩũlũ wa nthĩ, na andũ ma nthĩ ĩsu meumya mũndũ katĩ woo, na makĩmwĩa ethĩwa mũsyaĩĩsya woo;'),
('kam', 'EZK', 33, 3, 'ethĩwa, yĩla wĩona ũvyũ wũkĩte ĩ nthĩ, akavuva soo, na kũmon’ya andũ;'),
('kam', 'EZK', 33, 4, 'nĩvo ĩndĩ ũla ũkew’a wasya wa soo, na ailea wonan’yo ũsu; ethĩwa ũvyũ ũkooka, na kũmũveta, nthakame yake ĩkeethĩwa ĩũlũ wa mũtwe wake mwene.'),
('kam', 'EZK', 33, 5, 'Nĩwewie wasya wa soo, na akyũlea; nthakame yake ĩkeethĩwa ĩũlũ wake; ĩndĩ kethĩwa nĩwawĩtĩkĩlĩle, ethĩwa atangĩĩe thayũ wake.'),
('kam', 'EZK', 33, 6, 'Ĩndĩ ethĩwa mũsyaĩĩsya nũnũkwona ũvyũ wũkĩte, na ailea kũvuva soo, na andũ matĩkũmanyĩthw’a mũisyo, na ũvyũ ũkyũka, na kumya mũndũ o na wĩva katĩ woo; nũvetetwe e ũthũkũnĩ wake, ĩndĩ nthakame yake ngamĩandũa kw’okonĩ kwa mũsyaĩĩsya.'),
('kam', 'EZK', 33, 7, 'Naku, mwana wa mũndũ, nĩngwĩĩte wĩthĩwe mũsyaĩĩsya wa nyũmba ya Isilaeli; kwondũ wa ũu ĩw’a ndeto ya kanyw’a wakwa, noimataa na ũtao wakwa.'),
('kam', 'EZK', 33, 8, 'Yĩla ngwĩa ũla mũthũku, We mũndũ mũthũku, ndwĩ ndĩi ya ũlea ũkw’a, naku ndũũneena ũimwon’ya ũla mũthũku aume mũendelenĩ wake; mũndũ ũsu mũthũku akakw’a e ũthũkunĩ wake, ĩndĩ nthakame yake ngamĩandũa kw’okonĩ kwaku.'),
('kam', 'EZK', 33, 9, 'Ĩndĩ ethĩwa ũkamwon’ya ũla mũthũku ũndũ wa mũendele wake ethyũũe aũtie, na ndeĩthyũũa na kũtia mũendele wake; akakw’a e ũthũkunĩ wake, ĩndĩ we nũvonoketye thayũ waku.'),
('kam', 'EZK', 33, 10, 'Naku, mwana wa mũndũ, tavya nyũmba ya Isilaeli: Inyw’ĩ mũneenaa ũũ, mũkyasya, Mavĩtyo maitũ na naĩ sitũ syĩ ĩũlũ waitũ, na nĩtũũsonzomea nthĩnĩ wasyo; tũtonya ata ĩndĩ kwĩkala thayũ?'),
('kam', 'EZK', 33, 11, 'Matavye O, tondũ nĩ thayũ, easya ũu Mwĩaĩi Yeova, nditanĩthaw’a nĩ kĩkw’ũ kya mũthũku; ĩndĩ nĩ kana ũla mũthũku ethyũũe atie mũendele wake na kwĩkala thayũ: ĩthyũũei, ĩthyũũei mume mĩendelenĩ yenyu mĩthũku; nĩkĩ mũũkw’a, inyw’ĩ nyũmba ya Isilaeli?'),
('kam', 'EZK', 33, 12, 'Naku, mwana wa mũndũ, tavya ana ma andũ maku, Ũlũngalu wa ũla mũlũngalu ndũkamũvonokya mũthenya wa kũvĩtya kwake; na ũndũ wa ũthũku wa ũla mũthũku, ndakavalũka ũndũ waw’o mũthenya ũla ũkethyũũa atie ũthũku wake; o na ũla mũlũngalu ndakatonya kwĩkala thayũ kwondũ waw’o mũthenya ũla ũkeka naĩ.'),
('kam', 'EZK', 33, 13, 'Yĩla ngũmwĩa ũla mũlũngalu, ndatĩa kwĩkala thayũ; ethĩwa akaĩkĩĩa ũlũngalu wake, na kwĩka ũthũku, vai ũmwe wa meko make malũngalu ũkalilikanwa; ĩndĩ ũthũkunĩ wake ũla wekie, nĩvo wĩkw’ĩa.'),
('kam', 'EZK', 33, 14, 'Ĩngĩ, yĩla ngũmwĩa ũla mũthũku, Ndwĩ ndĩi ya ũlea ũkw’a; ethĩwa akeethyũũa na kũtia naĩ yake, na kwĩka ũla wosanaa na mĩao na ũla w’o;'),
('kam', 'EZK', 33, 15, 'ethĩwa ũla mũthũku akatũnga ngwatĩlĩlyo, na kũtũnga kĩla wosete na mbuta, na kũendaa myamũlonĩ ya thayũ, na kũlea kwĩka ũthũku; ndatĩa kwĩkala thayũ, ndakakw’a.'),
('kam', 'EZK', 33, 16, 'Naĩ syake ila wekie itikalilikanwa ĩũlũ wake o na ĩmwe yasyo: nĩwĩkĩte ũla wosanaa na mĩao na ũla wa w’o; ndatĩa kwĩkala thayũ.'),
('kam', 'EZK', 33, 17, 'Ĩndĩ ana ma andũ maku measya, Nzĩa ya Mwĩaĩi ndĩanene: ĩndĩ ũndũ woo, nzĩa yoo ndĩanene.'),
('kam', 'EZK', 33, 18, 'Yĩla mũlũngalu ũkethyũũa na kũtia ũlũngalu wake, na kwĩkaa ũthũku, akakw’ĩa nthĩnĩ waw’o.'),
('kam', 'EZK', 33, 19, 'Na yĩla ũla mũthũku ũkethyũũa na kũtia ũthũku wake, na kwĩkaa ũla wosanaa na mĩao na ũla wa w’o, akekala thayũ kwondũ waw’o.'),
('kam', 'EZK', 33, 20, 'Ĩndĩ inyw’ĩ mwĩasya, Nzĩa ya Mwĩaĩi ndĩanene. Inyw’ĩ nyũmba ya Isilaeli, ngamũsilĩla kĩla ũmwe kwĩanana na mĩendele yake.'),
('kam', 'EZK', 33, 21, 'Na kweethĩwa mwaka wa ĩkũmi na ĩlĩ wa kũtavwa kwitũ, mwei wa ĩkũmi, mũthenya wa katano wa mwei, ũmwe ũla wavonokie kuma Yelusaleme ambũkĩa, akĩmbĩa, Ndũa nĩ ngũne.'),
('kam', 'EZK', 33, 22, 'Na kw’oko kwa Yeova kũnaĩ ĩũlũ wakwa wĩoo, ũla ũvonokete atanoka; na eĩ anaathamya kanyw’a wakwa, kũvika yĩla wambũkĩe kĩoko; na kanyw’a wakwa waathamw’a, na ndyaaĩthĩwa ndatonya kũneena ĩngĩ.'),
('kam', 'EZK', 33, 23, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 33, 24, 'Mwana wa mũndũ, andũ ala matwĩe kũndũ kũu kwanangĩku nthĩ ya Isilaeli nĩmeũneena, makyasya, Avalaamu aĩ ũmwe, nake atĩĩwa nthĩ: ĩndĩ ithyĩ twĩ aingĩ; nĩtũnengetwe nthĩ yĩthĩwe ũtiĩwa.'),
('kam', 'EZK', 33, 25, 'Kwondũ wa ũu matavye, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nĩmũĩsanĩasya na nthakame, na kũmyũkĩlĩlya mĩvw’anano yenyu metho menyu, na kwĩtĩkya nthakame: na mũkamĩmesya ĩ nthĩ?'),
('kam', 'EZK', 33, 26, 'Nĩmũũngamaa kwondũ wa ũvyũ wenyu, nĩmwĩkaa ũthatyo, na nĩmũvukasya kĩla ũmwe kĩveti kya mũtũi wake: na inyw’ĩ mũkamesya ĩ nthĩ?'),
('kam', 'EZK', 33, 27, 'Ũũ nĩw’o ũkamatavya, Mwĩaĩi Yeova easya atĩĩ: O tondũ nĩ thayũ, vate ndĩi ala me kũndũ kwanangĩku makavalũkw’a na ũvyũ; na ũla wĩ weũnĩ ngamũnengane alĩke nĩ nyamũ; na ala me ngomenĩ syĩ vinya na ngunganĩ makooawa nĩ mũimũ.'),
('kam', 'EZK', 33, 28, 'Na ngamĩtw’ĩkĩthya nthĩ nthei na ũseng’yo; na ngathĩĩo ũndũ wa vinya wayo ĩkathela; na iĩma sya Isilaeli ikeethĩwa nthei, ũkethĩa mũndũ ndakũvĩtĩla.'),
('kam', 'EZK', 33, 29, 'Nĩvo ĩndĩ makamanya ninyie Yeova, yĩla ngethĩwa nĩtw’ĩkĩthĩtye nthĩ nthei na ũseng’yo, nũndũ wa mothatyo moo onthe ala mekĩte.'),
('kam', 'EZK', 33, 30, 'Na ũndũ waku, mwana wa mũndũ, ana ma andũ maku nĩmeũneena ũndũ waku vakuvĩ na maũvai na mĩomonĩ ya nyũmba, na nĩmeũneenan’ya ene kwa ene, kĩla ũmwe na mwana‐a‐ĩthe, makyasya, Ũkai, nĩngũmwĩsũva, mwĩw’e ndeto ĩla yumaa kwa Yeova.'),
('kam', 'EZK', 33, 31, 'Na nĩmokaa kwaku o ũndũ andũ mokaa, na nĩmekalaa nthĩ mbee waku ta andũ makwa, na nĩmeĩthukĩĩasya ndeto syaku, ĩndĩ matisyĩkaa; nũndũ nĩmonanasya wendo mwingĩ na makanyw’a moo, ĩndĩ ngoo syoo nĩatĩĩaa ũtandĩthyo woo.'),
('kam', 'EZK', 33, 32, 'Na, sisya, ũilyĩ kwoo ta wathi mũseo mũno wa ũmwe ũla wĩ na wasya wendeeasya, na ũtonya kũinga nesa kĩndũ kya kĩnga; nũndũ nĩmew’aa ndeto syaku, ĩndĩ matisyĩkaa.'),
('kam', 'EZK', 33, 33, 'Na yĩla ũkekĩka (sisya, nĩwũkĩte), nĩvo ĩndĩ makamanya kana kwaĩ mwathanĩ katĩ woo.'),
('kam', 'EZK', 34, 1, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 34, 2, 'Mwana wa mũndũ, athanĩa aĩthi ma Isilaeli, athana, noimea, o aĩthi, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Woo nĩ wa aĩthi ma Isilaeli ala meĩthasya! Aĩthi matyaĩle kũĩthya malondũ?'),
('kam', 'EZK', 34, 3, 'Nĩmũĩsaa mathunya, na nĩmwĩvw’ĩkaa w’ĩa wa malondu, nĩmũaaa ala manou; ĩndĩ mũtiĩthasya malondu.'),
('kam', 'EZK', 34, 4, 'Ala mawau mũtyaamekĩa vinya, o na mũtyaavosya yĩla ĩwau, o na mũtyaaoveea yĩla ĩtũlĩku, o na mũtyaatũnga yĩla yalũngilw’e, o na mũtyaamantha yĩla yau, ĩndĩ nĩmũmasumbĩkĩte na vinya na kũmathĩn’ya.'),
('kam', 'EZK', 34, 5, 'Na nĩmanyaĩĩkiw’e, nũndũ kũtyaĩ mũĩthi; na matw’ĩka lĩu wa nyamũ syonthe sya kĩthekanĩ, na manyaĩĩkw’a.'),
('kam', 'EZK', 34, 6, 'Malondu makwa nĩmangangaa iĩmanĩ syonthe, na ĩũlũ wa kĩla kalĩma katũlu: ĩĩ, malondu makwa manyaĩĩkw’a ĩũlũ wa nthĩ yonthe; na vatyaĩ ũmwe waakũlĩĩlya kana kũmamantha.'),
('kam', 'EZK', 34, 7, 'Kwondũ wa ũu, inyw’ĩ aĩthi, ĩthukĩĩsyei ndeto ya Yeova:'),
('kam', 'EZK', 34, 8, 'O tondũ nĩ thayũ, easya ũu Mwĩaĩi Yeova, nũndũ vate ndĩi malondu makwa nĩmataviwe, na malondu makwa matw’ĩka lĩu wa nyamũ syonthe sya kĩthekanĩ, nĩkwĩthĩwa kũtyaĩ mũĩthi, o na aĩthi makwa matyaamantha malondu makwa, ĩndĩ aĩthi nĩmeeĩthasya, na matyaaĩthya malondu makwa;'),
('kam', 'EZK', 34, 9, 'kwondũ wa ũu, inyw’ĩ aĩthi, ĩthukĩĩsyei ndeto ya Yeova:'),
('kam', 'EZK', 34, 10, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya, Sisya, nĩ na ũndũ na aĩthi; na ngaandũa malondu makwa kw’okonĩ kwoo, na ngamaekethya wĩa wa kũĩthya malondu; o na aĩthi matikeĩthya ĩngĩ; na ngavonokya malondu makwa kũmaumya kanyw’anĩ woo, matikethĩwe lĩu woo.'),
('kam', 'EZK', 34, 11, 'Nũndũ ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, nyie mwene, o nyie, ngakũlĩĩlya malondu makwa, na kũmamantha.'),
('kam', 'EZK', 34, 12, 'O tondũ mũĩthi ũmanthaa ndĩthya yake mũthenya ũla wĩ katĩ wa malondu make ala manyaĩĩku, now’o ngamantha malondu makwa; ngamaumya kũndũ kw’onthe kũla manyaĩĩkĩtw’e mũthenya wa matu na kĩvindu.'),
('kam', 'EZK', 34, 13, 'Na ngamaumya katĩ wa ngo sya andũ, na kũmomban’ya kuma i nthĩ, na ngamaete nthĩ yoo ene; na ngamaĩthya iĩmanĩ sya Isilaeli, vakuvĩ na mbũsĩ, na kũndũ kw’onthe kwa ĩ nthĩ kũla kũtwĩe andũ.'),
('kam', 'EZK', 34, 14, 'Ngamaĩthya kĩsesinĩ kĩseo; na iĩmanĩ ndũlu sya Isilaeli kũkeethĩwa kyengo kyoo: nĩkw’o makakoma kyengonĩ kĩseo; na makaĩthw’a kĩsesinĩ kĩnou iĩmanĩ sya Isilaeli.'),
('kam', 'EZK', 34, 15, 'Nyie mwene ngethĩwa mũĩthi wa malondu makwa, ngamatindisya, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 34, 16, 'Ngamantha ũla waĩte, na ngatũnga ũla walũngilw’e, na ngooveea ũla watũlĩtwe, na ngeekĩa vinya ũla wawaie: ĩndĩ ala anou na me vinya ngaananga; ngamaĩthasya na sila mũlũngalu.'),
('kam', 'EZK', 34, 17, 'Na ũndũ wenyu, inyw’ĩ ndĩthya yakwa, ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, nĩsilan’ya malondu na malondu, ndũũme na nthenge.'),
('kam', 'EZK', 34, 18, 'Nĩmũkwona nĩ ũndũ ũnini mwaĩthw’a kĩsesinĩ kĩseo, ĩndĩ no mũvaka mũkinyange na maũũ menyu ũtialo wa kĩsesi kyenyu? Na mwanyw’a manzĩ makelemu, ĩndĩ no mũvaka mũluan’ye ala matialile na maũũ menyu?'),
('kam', 'EZK', 34, 19, 'Na ũndũ wa malondu makwa, nĩmaĩsaa kĩla mũkinyangĩte na maũũ menyu, na manyusaa kĩla muluanĩtye na maũũ menyu.'),
('kam', 'EZK', 34, 20, 'Kwondũ wa ũu, Mwĩaĩi Yeova nũnũũmea: Sisyai, nyie, o nyie, ngasilan’ya malondu manou na malondu mamosu.'),
('kam', 'EZK', 34, 21, 'Nũndũ nĩmũũtindĩkana na mbau na kĩtuo, na kũlumangya onthe awau na mbya syenyu, kũvika nĩmũmanyaĩĩkĩtye;'),
('kam', 'EZK', 34, 22, 'kwondũ wa ũu ngatangĩĩa ndĩthya yakwa, na matikethĩwa mũtavo ĩngĩ: na ngasilan’ya malondu na malondu.'),
('kam', 'EZK', 34, 23, 'Na ngamaiĩa mũĩthi ũmwe, na akamaĩthya, o mũthũkũmi wakwa Ndaviti; akamaĩthya, na akeethĩwa mũĩthi woo.'),
('kam', 'EZK', 34, 24, 'Na nyie, Yeova, ngeethĩwa Ngai woo, na mũthũkũmi wakwa Ndaviti mũnene wĩ mbee ũsumbĩnĩ katĩ woo; nyie, Yeova, nĩnĩneenete ũu.'),
('kam', 'EZK', 34, 25, 'Na ngatianĩa ũtianĩo wa mũuo nao, na ngatuma nyamũ mbai ithela ĩ nthĩ: na makatũaa meyelele weũnĩ, na kũkomaa mũtitũnĩ.'),
('kam', 'EZK', 34, 26, 'Na ngamatw’ĩkĩthya mo na kũndũ kũthyũkũlũkĩte kĩĩma kyakwa ũathimo; na ngausya mĩono ĩvinda yayo; kũkeethĩwa mĩono ya ũathimo.'),
('kam', 'EZK', 34, 27, 'Na mũtĩ wĩ mũũndanĩ ũkasyaaa ũsyao waw’o, na nthĩ ĩkasyaaa ũsyao wayo, na makekalaa nthĩ yoo meyelele; na makamanya ninyie Yeova, yĩla ngethĩwa ndũlĩte mĩtĩ ya ĩsoki yoo, na kũmaumya kw’okonĩ kwa ala mamatw’ĩkĩthisye ngombo.'),
('kam', 'EZK', 34, 28, 'Na matikethĩwa mũtavo ĩngĩ kwa i mbaĩ, o na nyamũ sya nthĩ itikamaya; ĩndĩ makekalaa meyelele, na vai ũla ũkamatĩsya.'),
('kam', 'EZK', 34, 29, 'Na ngamokĩlĩlya mũũnda wĩ nguma, na matikaminwa ĩngĩ nĩ yũa nthĩ ĩsu, o na matikakua, nthoni sya i mbaĩ ĩngĩ.'),
('kam', 'EZK', 34, 30, 'Na makamanya nyie, Yeova Ngai woo, nĩ vamwe nao, na kana nyũmba ya Isilaeli mo, nĩ andũ makwa, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 34, 31, 'Na inyw’ĩ malondu makwa, malondu ma kĩsesi kyakwa, mwĩ andũ, na nyie nĩ Ngai wenyu, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 35, 1, 'Na ĩngĩ ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 35, 2, 'Mwana wa mũndũ, lutĩla kĩĩma kya Seili ũthyũ waku, noikyathanĩa,'),
('kam', 'EZK', 35, 3, 'ũkĩtavye, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, nĩ na ũndũ naku, we kĩĩma kya Seili, na ngakũtambũũkĩsya kw’oko kwakwa, na ngakũtw’ĩkĩthya mũthei na ũseng’yo.'),
('kam', 'EZK', 35, 4, 'Ngatw’ĩkĩthya ndũa syaku maanzo, na ũkeethĩwa wĩ mũthei; na ũkamanya ninyie Yeova.'),
('kam', 'EZK', 35, 5, 'Nĩkwĩthĩwa waĩ na ũthũ mavinda onthe, na nĩwanenganie ana ma Isilaeli vinyanĩ wa ũvyũ ĩvinda ya wanangĩko woo mũnene, ĩvinda ya ũthũku wa mũminũkĩlyo;'),
('kam', 'EZK', 35, 6, 'kwondũ wa ũu, o tondũ nĩ thayũ, easya ũu Mwĩaĩi Yeova, ngakwia kũvikĩa nthakame, na nthakame ĩkakũatĩĩa: nũndũ ndwaamena nthakame, kwondũ wa ũu nthakame ĩkakũatĩĩa.'),
('kam', 'EZK', 35, 7, 'O ta ũu ngatw’ĩkĩthya kĩĩma kya Seili ũseng’yo na kĩthei; na ngamũvetanĩsya nakyo ũla ũkĩvĩtĩlaa na ũla ũkĩsyokelaa.'),
('kam', 'EZK', 35, 8, 'Na ngausũsya ĩima syakyo ala mooaiwe makyo: ala mooaiwe na ũvyũ makavalũka tũlĩmanĩ twaku na myandanĩ yaku na mbũsĩnĩ syaku syonthe.'),
('kam', 'EZK', 35, 9, 'Ngakũtw’ĩkĩthya mũthei mavinda onthe, na ndũa syaku itikatũwa; na mũkamanya ninyie Yeova.'),
('kam', 'EZK', 35, 10, 'Nũndũ nũneenete, Mbaĩ ii ilĩ na nthĩ ii ilĩ ikeethĩwa syakwa, na tũkaimesya; o na kau Yeova aĩ vo:'),
('kam', 'EZK', 35, 11, 'kwondũ wa ũu, o tondũ nĩ thayũ, easya ũu Yeova, ngeeka kwĩanana na ũthatu waku, na kwĩanana na kĩwĩu kyaku kĩla woonanisye kĩmenanĩ kyaku kĩla wamamenie; na ngeemanyĩthan’ya katĩ woo, yĩla ngakũsilĩla.'),
('kam', 'EZK', 35, 12, 'Na ũkamanya nyie, Yeova, nĩnĩw’ĩte kũumana kwaku kw’onthe kũla ũumĩte iĩma sya Isilaeli, ũkyasya, Nitiĩtwe nthei, nĩtũũnengetwe syo tũsyanange.'),
('kam', 'EZK', 35, 13, 'Na nĩmwambĩnenevesye na kanyw’a wenyu, na nĩmwambingĩvĩsye ndeto syenyu: nĩnĩw’ĩte ũu.'),
('kam', 'EZK', 35, 14, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Yĩla nthĩ yonthe yĩtanaa, ngakũtw’ĩkĩthya mũthei.'),
('kam', 'EZK', 35, 15, 'O tondũ watanĩe ũtiĩwa wa nyũmba ya Isilaeli, nũndũ yaĩ nthei, now’o ngakwĩka: ũkeethĩwa wĩ mũthei, we kĩĩma kya Seili, na Etomu yonthe, o yonthe vyũ; na makamanya ninyie Yeova.'),
('kam', 'EZK', 36, 1, 'Naku, mwana wa mũndũ, athanĩa iĩma sya Isilaeli, nokyasya, Inyw’ĩ iĩma sya Isilaeli, ithukĩĩsyei ndeto ya Yeova.'),
('kam', 'EZK', 36, 2, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nĩkwĩthĩwa mũmaitha nũmũneenee, Aa! Na, Kũndũ kũtũlu kwa tene nĩ kwitũ, ng’ũndũ sitũ;'),
('kam', 'EZK', 36, 3, 'kwondũ wa ũu athana, nokyasya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nĩkwĩthĩwa, o nĩkwĩthĩwa nĩmamũtw’ĩkĩthĩtye athei, na nĩmamũmeletye kĩla ngalĩko, nĩ kana mwĩthĩwe ng’ũndũ ya ala matialile ma i mbaĩ, na nĩmũwetawa ilomonĩ sya aneeni, na ũvoonĩ mũthũku wa andũ;'),
('kam', 'EZK', 36, 4, 'kwondũ wa ũu, inyw’ĩ iĩma sya Isilaeli, ĩthukĩĩsyei ndeto ya Mwĩaĩi Yeova: Ũũ nĩw’o Mwĩaĩi Yeova ũnũũtavya iĩma na tũlĩma, mbũsĩ na myanda, kũndũ kũthei kwanangĩku na ndũa ila itiĩtwe, ila itw’ĩkĩte mũtavo na ntheko kwa ala matialile ma i mbaĩ ila ithyũlũlũkĩte;'),
('kam', 'EZK', 36, 5, 'kwondũ wa ũu Mwĩaĩi Yeova easya atĩĩ: Vate ndĩi mwakinĩ wa kĩwĩu kyakwa nĩnĩneenete ĩũlũ wa ala matialile ma i mbaĩ, na Etomu yonthe, ala meyosee nthĩ yakwa yĩthĩwe ng’ũndũ yoo na ũtanu wa ngoo yoo yonthe, na kĩvũthya kya ngoo, mamĩkye yĩthĩwe mũtavo.'),
('kam', 'EZK', 36, 6, 'Kwondũ wa ũu athana ũndũ wa nthĩ ya Isilaeli, noitavya iĩma na tũlĩma, mbũsĩ na myanda, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisyai, nĩnĩneenete kĩwĩunĩ kyakwa na ũthilĩkunĩ wakwa, nĩkwĩthĩwa nĩmũkuĩte nthoni sya i mbaĩ:'),
('kam', 'EZK', 36, 7, 'kwondũ wa ũu Mwĩaĩi Yeova easya atĩĩ: Nĩnĩavĩte, ngyasya, Vate ndĩi mbaĩ ila imũthyũlũlũkĩte, ikakua nthonĩ syasyo.'),
('kam', 'EZK', 36, 8, 'Ĩndĩ inyw’ĩ, iĩma sya Isilaeli, mũkathongoosya mbonge syenyu, na kũsyaa ũsyao wenyu kwondũ wa andũ makwa Isilaeli; nũndũ nĩmathengeee kũka.'),
('kam', 'EZK', 36, 9, 'Nũndũ, sisya, nyie nĩ ngalĩ yenyu, na ngamwĩthyũũĩa, na mũkaĩmwa na kũvandwa;'),
('kam', 'EZK', 36, 10, 'na ngaingĩvya andũ kwenyu, nyũmba yonthe ya Isilaeli, o yo yonthe; na ndũa ikatũwa, na kũndũ kwanangĩku kũkaakwa;'),
('kam', 'EZK', 36, 11, 'na ngaingĩvya kwenyu mũndũ na nyamũ; na ikaingĩva na kũsyaa; na ngamũtũĩthya o ta tene, na ngamwĩka nesa kwĩ myambĩlĩyo yenyu: na mũkamanya ninyie Yeova.'),
('kam', 'EZK', 36, 12, 'Ĩĩ, ngatambũũkĩlya andũ ĩũlũ wenyu, o andũ makwa Isilaeli; na makaũmesya, na ũkeethĩwa ũtiĩwa woo, na kuma yu ndũkamakw’ĩĩthĩsya syana ĩngĩ.'),
('kam', 'EZK', 36, 13, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nĩkwĩthĩwa nĩmeũmwĩa, We nthĩ wĩ mũyi wa andũ, na waĩ ũla wamĩkw’ĩĩthĩsye mbaĩ yaku;'),
('kam', 'EZK', 36, 14, 'kwondũ wa ũu ndũkaya andũ ĩngĩ, o na ndũkamĩkw’ĩĩthĩsya mbaĩ yaku ĩngĩ, easya ũu Mwĩaĩi Yeova;'),
('kam', 'EZK', 36, 15, 'o na ndikakũeka wĩw’e ĩngĩ nthoni sya i mbaĩ, o na ndũkakua kĩvũthya kya ngo sya andũ ĩngĩ, o na ndũkalulutĩkya mbaĩ yaku ĩngĩ, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 36, 16, 'Na ĩngĩ ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 36, 17, 'Mwana wa mũndũ, yĩla nyũmba ya Isilaeli yatwĩe nthĩ yoo ene, mamĩvukisye ũndũ wa mĩendele yoo na meko moo: mĩendele yoo mbee wakwa yailyĩ ũvuku wa mũndũ mũka ũla wealũlĩte.'),
('kam', 'EZK', 36, 18, 'Kwondũ wa ũu nĩnamonoesye ũthilĩku wakwa nũndũ wa nthakame ĩla metĩkisye nthĩ, na nũndũ nĩmamĩthũkisye na mĩvw’anano yoo;'),
('kam', 'EZK', 36, 19, 'na nĩnamanyaĩĩkisye katĩ wa i mbaĩ, na manyaĩĩkw’a katĩ wa i nthĩ: nĩnamasilĩle kwĩanana na mĩendele yoo na kwĩanana na meko moo.'),
('kam', 'EZK', 36, 20, 'Na yĩla mavikĩe i mbaĩ, kũla maendie, mavukya syĩtwa yakwa ĩtheu; kũvika andũ maneena ũndũ woo, Aa nĩ andũ ma Yeova, na nĩmaumĩte nthĩ yake.'),
('kam', 'EZK', 36, 21, 'Ĩndĩ nayĩw’ĩa tei syĩtwa yakwa ĩtheu, yĩla nyũmba ya Isilaeli yavukisye katĩ wa i mbaĩ, kũla maendie.'),
('kam', 'EZK', 36, 22, 'Kwondũ wa ũu tavya nyũmba ya Isilaeli, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ndikwĩka ũu kwondũ wenyu, ĩnyw’ĩ nyũmba ya Isilaeli, ĩndĩ kwondũ wa syĩtwa yakwa ĩtheu, yĩla mũvukĩsye katĩ wa i mbaĩ, kũla mwaendie.'),
('kam', 'EZK', 36, 23, 'Na ngavathan’ya syĩtwa yakwa ĩnene, yĩla yavukĩwe katĩ wa i mbaĩ, yĩla ĩnyw’ĩ mwavukĩsye katĩ wasyo; na mbaĩ ikamanya ninyie Yeova, easya ũu Mwĩaĩi Yeova, yĩla ngeyonan’ya kwenyu mbee wa metho moo atĩ nĩ mũtheu.'),
('kam', 'EZK', 36, 24, 'Nũndũ ngamumya katĩ wa i mbaĩ, na kũmũmban’ya kuma nthĩ syonthe, na ngamũete nthĩ yenyu ene.'),
('kam', 'EZK', 36, 25, 'Na ngamũminzangĩsya manzĩ matheu, na mũkeethĩwa mwĩ atheu: ngamũthesya ũvuku wenyu w’onthe, mĩvw’anano yenyu yonthe.'),
('kam', 'EZK', 36, 26, 'O na ngamũnenga ngoo nzaũ, na ngeekĩa veva mweũ nthĩnĩ wenyu; na ngaumya ngoo ya ĩvia mĩĩnĩ yenyu, na ngamũnenga ngoo ya nyama.'),
('kam', 'EZK', 36, 27, 'Na ngeekĩa Veva wakwa nthĩnĩ wenyu, na ngamũkinyĩthasya myamũlonĩ yakwa, na mũkakwataa motw’ĩo makwa, na kũmeka.'),
('kam', 'EZK', 36, 28, 'Na mũkekalaa nthĩ ĩla nanengie aaĩthe menyu; na mũkeethĩwa andũ makwa, na ngeethĩwa Ngai wenyu.'),
('kam', 'EZK', 36, 29, 'Na ngamũtangĩĩa kuma ũvukunĩ wenyu w’onthe: na ngeeta lĩu wa mbaa ngetha, na ngawingĩvya, na ndikamwĩĩa yũa.'),
('kam', 'EZK', 36, 30, 'Na ngaingĩvya ũsyao wa mũtĩ, na wingĩvo wa mũũnda, nĩ kana mũtikaavũthw’e ĩngĩ ũndũ wa yũa katĩ wa i mbaĩ.'),
('kam', 'EZK', 36, 31, 'Nĩvo ĩndĩ mũkalilikana mĩendele yenyu mĩthũku, na meko menyu ala mataĩ maseo; na mũkeemena methonĩ menyu ene mũndũ wa mothũku menyu na nũndũ wa mothatyo menyu.'),
('kam', 'EZK', 36, 32, 'Nĩkũmanyĩke kwenyu ti kwondũ wenyu nĩkaa ũu, easya ũu Mwĩaĩi Yeova: sonokai na thokoanai nũndũ wa mĩendele yenyu, inyw’ĩ nyũmba ya Isilaeli.'),
('kam', 'EZK', 36, 33, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Mũthenya ũla nĩmũthesya mothũku menyu onthe, ngatuma ndũa itũwa na kũla kwanangĩku kũkaakwa.'),
('kam', 'EZK', 36, 34, 'Na nthĩ ĩla yaĩ nthei ĩkaĩmwa, ĩla yaĩ nthei ĩkyoneka nĩ onthe ala mamĩvĩtĩlaa.'),
('kam', 'EZK', 36, 35, 'Na makasya, Nthĩ ĩno ĩla yaĩ nthei nĩtw’ĩkĩte ta mũũnda wa Eteni; na ndũa ila syaĩ maanzo na nthei na nomboange nĩ mbiie na nitũĩtwe.'),
('kam', 'EZK', 36, 36, 'Nĩvo ĩndĩ mbaĩ ila itiĩtwe imũthyũlũlũkĩte ikamanya kana nyie, Yeova, nĩndũngĩĩĩte kũndũ kũomboku, na nĩnĩvandĩte kũla kwaĩ kũthei: nyie, Yeova, nĩnĩneenete ũu, na ngawĩka.'),
('kam', 'EZK', 36, 37, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: O na ĩngĩ, ngakũlw’a ũndũ ũsu nĩ nyũmba ya Isilaeli, nĩwĩke kwondũ woo: ngamaingĩvya andũ methĩwe ta ndĩthya ya mbũi na malondu.'),
('kam', 'EZK', 36, 38, 'Ta ndĩthya kwondũ wa nthembo, ta ndĩthya ya Yelusaleme kwondũ wa mboka syayo ila itw’ĩtwe, o ta ũu ndũa ila syaĩ maanzo ikausũw’a ndĩthya sya andũ; na makamanya ninyie Yeova.'),
('kam', 'EZK', 37, 1, 'Kw’oko kwa Yeova kwai ĩũlũ wakwa, na anumaalya nĩ Vevanĩ wa Yeova, na ambĩkalya nthĩ mwandanĩ katĩ; na waĩ mũsũu mavĩndĩ.'),
('kam', 'EZK', 37, 2, 'Na atuma nĩvĩta nĩmathyũlũlũkĩte: na, sisya, kwaĩ maingĩ mũno mwandanĩ ũtheinĩ; na, sisya, maĩ momũ mũno.'),
('kam', 'EZK', 37, 3, 'Na angũlya, Mwana wa mũndũ, mavĩndĩ aa nĩmatonya kwĩthĩwa thayũ? Na nasũngĩa, We Mwĩaĩi Yeova, nĩwĩsĩ.'),
('kam', 'EZK', 37, 4, 'Ĩngĩ ambĩa, Athana ĩũlũ wa mavĩndĩ aa, ũmatavye, Inyw’ĩ mavĩndĩ momũ, ĩthukĩĩsyei ndeto ya Yeova.'),
('kam', 'EZK', 37, 5, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũũmea mavĩndĩ aa: Sisyai, ngatuma veva ũlika nthĩnĩ wenyu, na mũkeethĩwa thayũ.'),
('kam', 'EZK', 37, 6, 'Na ngeekĩa malangũ ĩũlũ wenyu, na ngaete nyama ĩũlũ wenyu, na kũmũvw’ĩka kĩkonde, na kwĩkĩa veva nthĩnĩ wenyu, na mũkeethĩwa thayũ; na mũkamanya ninyie Yeova.'),
('kam', 'EZK', 37, 7, 'Na ĩndĩ nathana o tondũ neaĩwe: na ngyathana, kwaĩ kĩlonzo, na, sisya, kĩtetemo kya nthĩ; na mavĩndĩ mathengeeanĩa, ĩvĩndĩ na ĩvĩndĩ yayo.'),
('kam', 'EZK', 37, 8, 'Na noona, na, sisya, kwaĩ malangũ ĩũlũ wamo, na nyama yookĩla, na kĩkonde kyamavw’ĩka ĩũlũ; ĩndĩ vatyaĩ veva nthĩnĩ wamo.'),
('kam', 'EZK', 37, 9, 'Nĩvo ĩndĩ wambĩie, Athanĩa kĩseve, athana, mwana wa mũndũ, ũtavye kĩseve, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ũka kuma isevenĩ inya, we veva, noiveveea aa mooaiwe, nĩ kana methĩwe thayũ.'),
('kam', 'EZK', 37, 10, 'Na ĩndĩ nathana o ũndũ wambĩaĩe, na veva wamalika, na maĩ na thayũ, na maũngama na maũũ noo, nguthu nene mũno ya kaũ.'),
('kam', 'EZK', 37, 11, 'Nĩvo ĩndĩ wambĩie, Mwana wa mũndũ, mavĩndĩ aa nĩ nyũmba yonthe ya Isilaeli: sisya, measya, Mavĩndĩ maitũ nĩ momũ, na wĩkwatyo witũ nĩ mwau; nĩtũvetetwe vyũ.'),
('kam', 'EZK', 37, 12, 'Kwondũ wa ũu athana, noimatavya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, ngavingũa mbũa syenyu, na kũmumya mbũanĩ syenyu, inyw’ĩ andũ makwa; na ngamũlikya nthĩ ya Isilaeli.'),
('kam', 'EZK', 37, 13, 'Na mũkamanya ninyie Yeova, yĩla ngavingũa mbũa syenyu, na kũmumya mbũanĩ syenyu, inyw’ĩ andũ makwa.'),
('kam', 'EZK', 37, 14, 'Na ngeekĩa Veva wakwa nthĩnĩ wenyu, na mũkeethĩwa thayũ, na ngamwĩkalya nthĩ yenyu ene: na mũkamanya kana nyie, Yeova, nĩnĩneenete ũu na nĩnĩkĩte, easya ũu Yeova.'),
('kam', 'EZK', 37, 15, 'Ndeto ya Yeova yambũkĩa ĩngĩ, ĩkĩmbĩa,'),
('kam', 'EZK', 37, 16, 'Naku, mwana wa mũndũ, osa mũtĩ ũmwe, ũandĩke ĩũlũ waw’o, Kwa Yuta, na kwa ana ma Isilaeli atindan’ya make: na ĩndĩ osa mũtĩ ũngĩ, ũandĩke ĩũlũ waw’o, Kwa Yosevu, mũtĩ wa Evalaimu, na kwa nyũmba yonthe ya Isilaeli atindan’ya make:'),
('kam', 'EZK', 37, 17, 'noimĩkwatan’ya ũmwe na ũla ũngĩ yĩthĩwe mũtĩ ũmwe kwondũ waku, nĩ kana ĩtw’ĩke ũmwe kw’okonĩ kwaku.'),
('kam', 'EZK', 37, 18, 'Na yĩla ana ma andũ maku makaneena naku, makĩũkũlya, Ndwĩtwon’ya ũndũ ũkwasya na ĩno?'),
('kam', 'EZK', 37, 19, 'Matavye, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, ngoosa mũtĩ wa Yosevu, ũla wĩ kw’okonĩ kwa Evalaimu, na mbaĩ sya Isilaeli atindan’ya make; na ngamekĩa vamwe naw’o, o vamwe na mũtĩ wa Yuta, na ngamĩtw’ĩkĩthya mũtĩ ũmwe, na makeethĩwa ũmwe kw’okonĩ kwakwa.'),
('kam', 'EZK', 37, 20, 'Na mĩtĩ ĩla wĩmĩandĩka ĩkeethĩwa kw’okonĩ kwaku mbee wa metho moo.'),
('kam', 'EZK', 37, 21, 'Na matavye, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, ngaumya ana ma Isilaeli katĩ wa i mbaĩ, kũla maendie, na ngamomban’ya kĩla ngalĩko, na kũmalikya nthĩ yoo ene:'),
('kam', 'EZK', 37, 22, 'na ngamatw’ĩkĩthya mbaĩ ĩmwe nthĩnĩ wa ĩ nthĩ, ĩũlũ wa iĩma sya Isilaeli; na mũsumbĩ ũmwe akeethĩwa mũsumbĩ wa onthe; na matikethĩwa mbaĩ ilĩ ĩngĩ, o na matikataanĩw’a methĩwe mosumbĩ elĩ ĩngĩ o na ĩndĩĩ;'),
('kam', 'EZK', 37, 23, 'o na matikevukya ĩngĩ na mĩvw’anano yoo, kana na syĩndũ syoo imenetwe, kana o na yĩmwe ya mavĩtyo moo; ĩndĩ ngamatangĩĩa kuma motũonĩ moo onthe, kũla mavĩtĩsye, na ngamathesya: kwondũ wa ũu makeethĩwa andũ makwa, na ngeethĩwa Ngai woo.'),
('kam', 'EZK', 37, 24, 'Na mũthũkũmi wakwa Ndaviti akeethĩwa mũsumbĩ woo; nao onthe makeethĩwa na mũĩthĩ ũmwe: o na makaendaa motw’ĩonĩ makwa, na kũsũvĩa myamũlo yakwa na kũmĩkaa.'),
('kam', 'EZK', 37, 25, 'Na makekala nthĩ ĩla nĩmũnengete Yakovo mũthũkũmi wakwa, vala aaĩthe menyu matwĩe; na makekala vo, mo, na syana syoo, na nzũkũlũ syoo, tene na tene: na Ndaviti mũthũkũmi wakwa akeethĩwa mũnene woo wĩ mbee ũsumbĩnĩ tene na tene.'),
('kam', 'EZK', 37, 26, 'Na ĩngĩ ngatianĩa ũtianĩo wa mũuo nao, ũkeethĩwa ũtianĩo kwoo wa tene na tene; na ngamaia na, kũmaingĩvya, na ngaia vandũ vakwa vatheu katĩ woo tene na tene.'),
('kam', 'EZK', 37, 27, 'O na wĩkalo wakwa ũkeethĩwa vamwe nao; na ngeethĩwa Ngai woo, na makeethĩwa andũ makwa.'),
('kam', 'EZK', 37, 28, 'Na mbaĩ ĩkamanya ninyie Yeova ũla ũvathanasya Isilaeli methĩwe atheu, yĩla vandũ vakwa vatheu vakethĩwa katĩ woo tene na tene.'),
('kam', 'EZK', 38, 1, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'EZK', 38, 2, 'Mwana wa mũndũ, elekelye ũthyũ waku Ngoki, wa nthĩ ya Makoki, mũnene wĩ mbee ũsumbĩnĩ wa Losi, Meseki, na Tuvali, noimwathanĩa,'),
('kam', 'EZK', 38, 3, 'na asya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, nĩ na ũndũ naku, we Ngoki, mũnene wĩ mbee ũsumbĩnĩ wa Losi, Meseki, na Tuvali:'),
('kam', 'EZK', 38, 4, 'na ngakũthyũũa, na kwĩkĩa mboloi ngambuunĩ syaku, na ngakumaalya, na ita syaku syonthe, mbalasi na ala matũlĩte mbalasi, onthe mekĩĩte mĩio yonthe ya kaũ, nguthu nene yĩ na kakalo na ngao, onthe makwete mbyũ:'),
('kam', 'EZK', 38, 5, 'Velisia, Kusi, na Vutu vamwe nao, onthe me na ngao na ngovia;'),
('kam', 'EZK', 38, 6, 'Ngomeli, na nguthu syake syonthe; nyũmba ya Tokalima itulunĩ sya ngalĩ ya ĩũlũ, na nguthu syake syonthe; o ngo mbingĩ sya andũ vamwe naku.'),
('kam', 'EZK', 38, 7, 'Ĩkala wĩyũmbanĩtye, ĩĩ, ĩyũmban’ye, we, na nguthu syaku syonthe ila ĩkũmbanĩe, na ĩthĩwa mũsũvĩi kwamo.'),
('kam', 'EZK', 38, 8, 'Ĩtina wa mĩthenya mingĩ ũkookĩwa: myaka ya mũminũkĩlyo ũkalika nthĩ ĩla ĩtũngĩtwe kuma ũvyũnĩ, ĩla yũmbanĩtw’e kuma ngonĩ mbingĩ sya andũ, iĩmanĩ sya Isilaeli, ila syekalaa mbanangĩku mavinda onthe; ĩndĩ nĩyumĩtwe nthĩnĩ wa ngo sya andũ, na makekala meyelele, onthe moo.'),
('kam', 'EZK', 38, 9, 'Na ũkambata, ũkooka ta kĩuutani, ũkeethĩwa ta ĩthweo ya kũvw’ĩka nthĩ, we, na nguthu syaku syonthe na ngo mbingĩ sya andũ vamwe naku.'),
('kam', 'EZK', 38, 10, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Kũkeethĩwa mũthenya ũsu, maũndũ makalika kĩlilikanonĩ kyaku, na ũkasũanĩa ũsũanĩo mũthũku:'),
('kam', 'EZK', 38, 11, 'na ũkasya, Ngambata nthĩ yĩ tũmĩsyĩ tũte twiie; ngathi kwa ala mathũmũĩte, ala mekalaa meyelele, onthe mekalĩte mate na maũvai, na mate na ivingi kana mbingĩlo;'),
('kam', 'EZK', 38, 12, 'nose mũtavo o na syĩndũ sya mbuta; nĩthyũũe kw’oko kwaku ĩũlũ wa kũndũ kũla kwaeketwe kũla yu kũtwĩwe nĩ andũ, na ĩũlũ wa andũ mombanĩtw’e kuma i mbaĩnĩ, ala me na indo na syĩndũ, ala matũaa nthĩ katĩ.'),
('kam', 'EZK', 38, 13, 'Sieva, na Ndetani, na athoosya ma Talisisi, vamwe na mĩnyambũ yonthe ya mũika ya vo, makakũkũlya, Nĩwooka kwosa mũtavo? Nĩwũmbanĩtye nguthu yaku wose syĩndũ sya mbuta? Ũkue vetha na thaavu, ũtwae indo na syĩndũ, ũtwae mũtavo mũnene?'),
('kam', 'EZK', 38, 14, 'Kwondũ wa ũu, mwana wa mũndũ, athana, ũtavye Ngoki, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Mũthenya ũsu yĩla andũ makwa Isilaeli makatũa meyelele, ndũkamanya ũu?'),
('kam', 'EZK', 38, 15, 'Na ũkauma vandũ vaku kuma itulunĩ sya ngalĩ ya ĩũlũ, we, na ngo mbingĩ sya andũ vamwe naku, onthe makuĩtwe nĩ mbalasi nguthu nene na ita syĩ ũtonyi;'),
('kam', 'EZK', 38, 16, 'na ũkamokĩa andũ makwa Isilaeli, ta ĩthweo ũvw’ĩke nthĩ: kũkeethĩwa mĩthenya ya mũminũkĩlyo, ngakũete ũkite na nthĩ yakwa, nĩ kana i mbaĩ imanye nyie, yĩla ngeyonan’ya kwaku, we Ngoki, atĩ nĩ mũtheu, mbee wa metho moo.'),
('kam', 'EZK', 38, 17, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Nue ũla naneenie ũndũ wake ĩvinda ya tene na makanyw’a ma athũkũmi makwa athani ma Isilaeli, ala mathanaa mĩthenya ĩsu vandũ va myaka mingĩ atĩ ngakũete ũkie nao?'),
('kam', 'EZK', 38, 18, 'Na kũkethĩwa mũthenya ũsu, yĩla Ngoki ĩkamyũkĩa nthĩ ya Isilaeli, easya ũu Mwĩaĩi Yeova, ũthilĩku wakwa ũkambata manyiũũnĩ makwa.'),
('kam', 'EZK', 38, 19, 'Nũndũ kĩwĩunĩ kyakwa na mwakinĩ wa ũthilĩku wakwa nĩnĩneenete, Vate ndĩi mũthenya ũsu kũkethĩwa kĩthingithyo kĩnene nthĩ ya Isilaeli;'),
('kam', 'EZK', 38, 20, 'o kũvika makũyũ ma ũkanganĩ, na nyũnyi sya yayaya, na nyamũ sya kĩthekanĩ, na tũsamũ tw’onthe tũla tũtambũkaa ĩũlũ wa nthĩ, na andũ onthe ala me ĩũlũ wa nthĩ, makatetemea mbee wakwa, na iĩma ikang’uthũlangwa nthĩ, na kũndũ kwĩ ilĩso kũkavalũka, na kĩla ũvai ũkavalũka nthĩ.'),
('kam', 'EZK', 38, 21, 'Na ngeetĩsya iĩma syakwa syonthe ũvyũ wa kũmũkita, easya ũu Mwĩaĩi Yeova: ũvyũ wa kĩla mũndũ ũkeethĩwa ĩũlũ wa mwana‐a‐inyia.'),
('kam', 'EZK', 38, 22, 'Na ngalika silanĩ nake na nzĩa ya mũimũ na nthakame; na ngausya ĩũlũ wake, na nguthu syake, na ngo mbingĩ sya andũ ala me vamwe nake, mbua ya mũono ĩtulĩtye, na mbua ya mavia manene, na mwaki, na mũvĩlĩtĩ.'),
('kam', 'EZK', 38, 23, 'Na ngeenenevya, na kwĩyonan’ya atĩ nĩ mũtheu, na ngeemanyĩthan’ya methonĩ ma mbaĩ mbingĩ; na ikamanya ninyie Yeova.'),
('kam', 'EZK', 39, 1, 'Naku, mwana wa mũndũ, athanĩa Ngoki, noyasya, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Sisya, nĩ na ũndũ naku, we Ngoki, mũnene wĩ mbee ũsumbĩnĩ wa Losi, Meseki, na Tuvali:'),
('kam', 'EZK', 39, 2, 'na ngakũthyũũa, na ngakũtongoesya, na ngakũete kuma itulunĩ sya ngalĩ ya ĩũlũ; na ngakũete iĩmanĩ sya Isilaeli;'),
('kam', 'EZK', 39, 3, 'na ngakũna ũta waku wume kw’okonĩ kwaku kwa aka, na ngatuma mĩsyĩ yaku ĩvalũka kuma kw’okonĩ kwaku kwa aũme.'),
('kam', 'EZK', 39, 4, 'Ũkavalũka iĩmanĩ sya Isilaeli, we, na nguthu syaku syonthe, na ngo sya andũ ala me vamwe naku: ngakũnengane kwa nyũnyi mbai sya kĩla mũthemba, na kwa nyamũ sya kĩthekanĩ ũĩwe nĩsyo.'),
('kam', 'EZK', 39, 5, 'Ũkavalũka weũnĩ; nũndũ nĩnĩneenete ũu, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 39, 6, 'Na ngatwaa mwaki ĩũlũ wa Makoki, o na ala mekalaa meyelele ithamanĩ; na makamanya ninyie Yeova.'),
('kam', 'EZK', 39, 7, 'Na ngamanyĩthan’ya syĩtwa yakwa ĩtheu katĩ wa andũ makwa Isilaeli; o na ndikaeka syĩtwa yakwa ĩtheu yĩvukw’e ĩngĩ: na i mbai ikamanya ninyie Yeova, Ũla Mũtheu wa Isilaeli.'),
('kam', 'EZK', 39, 8, 'Sisya, ũu nĩwũkĩte, na ũkeekwa, easya ũu Mwĩaĩi Yeova: ũũ nĩw’o mũthenya ũla nawetie.'),
('kam', 'EZK', 39, 9, 'Na ala mekalaa ndũanĩ sya Isilaeli makaumaala, na makavuvaa myaki na mĩio ya kaũ na kũmĩvĩvya, o ngao na tũkalo, mata na mĩsyĩ, na mĩsenge, na tũkalo, mata na mĩsyĩ, na mĩsenge, na matumo, na makavuvaa myaki nayo myaka mũonza;'),
('kam', 'EZK', 39, 10, 'o na matikauna ngũ kĩthekanĩ, kana kũkela ngũ mĩtitũnĩ; nũndũ makavuvaa myaki na mĩio ya kaũ; na makatava ala mamatavie, na makavuta ala mamavutie, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 39, 11, 'Na kũkethĩwa mũthenya ũsu, nganenga Ngoki vandũ va kũthika andũ nthĩ ya Isilaeli, mwanda wa ala mavĩtĩlaa ngalĩ ya wumĩlonĩ wa syũa ya ũkanga; na vakasiĩĩaa ala mavĩtĩlaa vo: na ku nĩkw’o makenzĩa Ngoki nthĩ na wingĩ w’onthe wa andũ make; na makaveta Mwanda wa Aamoni‐ngoki.'),
('kam', 'EZK', 39, 12, 'Na andũ ma nyũmba ya Isilaeli makamenzĩa nthĩ myei mũonza, nĩ kana mathesye nthĩ.'),
('kam', 'EZK', 39, 13, 'Ĩĩ, andũ onthe ma ĩ nthĩ makamenzĩa nthĩ; na kũkeethĩwa nguma kwoo mũthenya ũla ngataĩwa, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 39, 14, 'Na makanyuva andũ ma kũtethya wĩa ĩndĩ yonthe, ala mevĩtĩlaa ĩ nthĩ, makĩnzĩa nthĩ me na avĩti ala matialĩte ĩũlũ wa nthĩ, mamĩthesye: ĩtina wa myei mũonza makamantha.'),
('kam', 'EZK', 39, 15, 'Na ala avĩti mavĩtĩlaa ĩ nthĩ makavĩtĩlaa; yĩla ũmwe wona ĩvĩndĩ ya mũndũ, akaũngamya ũvano vakuvĩ nayo, kũvika yĩla ala menzĩaa nthĩ meyĩnzĩa nthĩ mwandanĩ wa Aamoni‐ngoki.'),
('kam', 'EZK', 39, 16, 'O na ĩngĩ syĩtwa ya Amona yĩkeethĩwa ya ndũa. Ũũ nĩw’o makathesya nthĩ.'),
('kam', 'EZK', 39, 17, 'Naku, mwana wa mũndũ, ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Neena na nyũnyi sya kĩla mũthemba, na kĩla nyamũ ya kĩthekanĩ, Ĩyũmban’yei, na mũkyũka; ĩyũmban’yei kĩla ngalĩko mũke nthembonĩ yakwa ĩla nĩthemba kwondũ wenyu, o nthembo nene iĩmanĩ sya Isilaeli, nĩ kana mũye nyama na kũnyw’a nthakame.'),
('kam', 'EZK', 39, 18, 'Mũkaya nyama sya mĩĩ ya ala me ũtonyi, na kũnyw’a nthakame ya anene me mbee mosumbĩnĩ ma nthĩ, ya ndũũme, ya tũtena twa malondu, ya mbũi, ya tũsalũ twa mũew’a, syonthe ila nou sya Mbasani.'),
('kam', 'EZK', 39, 19, 'Na mũkaya mathunya kũvika mwavũna, na kũnyw’a nthakame kũvika mwatoona, ya nthembo yakwa ĩla nĩthembete kwondũ wenyu.'),
('kam', 'EZK', 39, 20, 'Na mũkavũnĩthw’a mesanĩ yakwa nĩ mbalasi na makasya ma kaũ, na ngũmbaũ, na andũ onthe ma kaũ, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 39, 21, 'Na ngaia ndaĩa yakwa katĩ wa i mbaĩ; na mbaĩ syonthe ikoona ũsilĩlo wakwa ũla nasilile, na kw’oko kwakwa kũla niĩte ĩũlũ woo.'),
('kam', 'EZK', 39, 22, 'Kwondũ wa ũu nyũmba ya Isilaeli makamanya ninyie Yeova Ngai woo, kuma mũthenya ũsu na kũendeea.'),
('kam', 'EZK', 39, 23, 'Na i mbaĩ ikamanya nyũmba ya Isilaeli nĩyaendie yĩ ndave nũndũ wa ũthũku wayo; nĩkwĩthĩwa nĩmambĩtanĩsye, na namavitha ũthyũ wakwa; kwondũ wa ũu namanenganie kw’okonĩ kwa amaitha moo, na onthe mavalũkw’a na ũvyũ.'),
('kam', 'EZK', 39, 24, 'Kwĩanana na ũvuku woo na kwĩanana na mavĩtyo moo now’o namekie; na namavitha ũthyũ wakwa.'),
('kam', 'EZK', 39, 25, 'Kwondũ wa ũu Mwĩaĩi Yeova easya atĩĩ: Yu ngatũnga Yakovo kuma kũtavwanĩ, na ngeew’ĩa tei nyũmba yonthe ya Isilaeli; na ngeethĩwa na kĩwĩu kwondũ wa syĩtwa yakwa ĩtheu.'),
('kam', 'EZK', 39, 26, 'Na makakua nthoni syoo, na mavĩtyo moo onthe ala mambĩtanĩsye, yĩla makatũa meyelele nthĩ yoo, na vai ũla ũkamatĩsya;'),
('kam', 'EZK', 39, 27, 'yĩla ngethĩwa nĩmatũngĩte kuma ngonĩ sya andũ, kũmomban’ya kũmaumya nthĩ sya amaitha moo, na nĩyonanĩtye kwoo atĩ nĩ mũtheu mbaĩ nyingĩ syene.'),
('kam', 'EZK', 39, 28, 'Na makamanya ninyie Yeova Ngai woo, nũndũ nĩnamatwaĩthisye me atave katĩ wa i mbaĩ, na nĩnĩmombanĩtye nthĩ yoo ene; na ndikatia ũmwe wamo kw’o ĩngĩ;'),
('kam', 'EZK', 39, 29, 'o na ndikamavitha ũthyũ wakwa ĩngĩ; nũndũ nĩnonoesye nyũmba ya Isilaeli Veva wakwa, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 40, 1, 'Mwaka wa mĩongo ĩlĩ na ĩtano wa kũtavwa kwitũ, wambĩlĩlyonĩ wa mwaka, mũthenya wa ĩkũmi wa mwei, mwaka wa ĩkũmi na ĩna ĩtina wa kũkũnwa kwa ndũa, mũthenya o ũsu, kw’oko kwa Yeova kwaĩ ĩũlũ wakwa, na andete kw’o.'),
('kam', 'EZK', 40, 2, 'Mawonĩnĩ ma Ngai andete nthĩ ya Isilaeli, na ambia nthĩ kĩĩmanĩ kĩtũlu mũno, na ĩũlũ wakyo kwaĩ mwakĩle wa ndũa ngalĩ ya ĩtheo.'),
('kam', 'EZK', 40, 3, 'Na andete kw’o, na, sisya, kwaĩ mũndũ, mũvw’anĩle wake waĩ ta mũvw’anĩle wa ũthuku, e na ũlii wa katane kw’okonĩ kwake, na mũangi wa kũthima naw’o; na aũngama mbingĩlonĩ.'),
('kam', 'EZK', 40, 4, 'Na ũ mũndũ ambĩa, Mwana wa mũndũ, sisya na metho maku, na ĩw’a na matũ maku, na enda mũno ngoonĩ yaku w’onthe ũla ngakwon’ya; nũndũ nũetetwe vaa, nĩ kana nĩkwon’ye; tavya nyũmba ya Isilaeli w’onthe ũla wĩona.'),
('kam', 'EZK', 40, 5, 'Na, sisya, ũvai ũtee wa nyũmba ũmĩthyũlũlũkĩte, na kw’okonĩ kwa ũ mũndũ mũangi wa ũthima ũasa waw’o mĩkono thanthatũ, ũasa wa kĩla ũmwe nĩ mũkono na ũthanthau wa kĩtaa kya kw’oko: ta ũu athima ũthanthau wa mwako, mũangi ũmwe; na ũtũlu, mũangi ũmwe.'),
('kam', 'EZK', 40, 6, 'Na ĩndĩ avika mbingĩlonĩ ĩla yelekele wumĩlonĩ wa syũa, na ambata mbasyanĩ syayo: na athima mwalyo wa mbingĩlo, ũthanthau waw’o mũangi ũmwe; na mwalyo ũla ũngĩ, ũthanthau waw’o mũangi ũmwe.'),
('kam', 'EZK', 40, 7, 'Na kĩla kasũmba ka mũsũvĩi ũasa wako waĩ mũangi ũmwe, na ũthanthau wako mũangi ũmwe; na ũthei katĩ wa tũsũmba waĩ mĩkono ĩtano; na mwalyo wa mbingĩlo vakuvĩ na valasya wa mbingĩlo kwelekela nyũmba waĩ mũangi ũmwe.'),
('kam', 'EZK', 40, 8, 'O na athima valasya wa mbingĩlonĩ ũla welekele nyũmba, mũangi ũmwe.'),
('kam', 'EZK', 40, 9, 'Na ĩndĩ athima valasya wa mbingĩlonĩ, mĩkono nyanya; na ituĩ syaw’o, mĩkono ĩlĩ; na valasya wa mbingĩlonĩ welekele nyũmba.'),
('kam', 'EZK', 40, 10, 'Na tũsũmba twa asũvĩi twa mbingĩlonĩ ngalĩ ya wumĩlonĩ wa syũa twaĩ tũtatũ ngalĩ ĩno, na tũtatũ ngalĩ ĩya; tũu tũtatũ twaĩ twa kĩthimo kĩmwe: na ituĩ syaĩ sya kĩthimo kĩmwe ngalĩ ĩno na ngalĩ ĩya.'),
('kam', 'EZK', 40, 11, 'Na athima ũthanthau wa vandũ va ũvotela mbingĩlonĩ, mĩkono ĩkũmi; na ũasa wa mbingĩlo, mĩkono ĩkũmi na ĩtatũ;'),
('kam', 'EZK', 40, 12, 'na mbee wa tũla tũsũmba vaĩ vandũ vaumĩlĩte nza, mũkono ũmwe ngalĩ ĩno, na vandũ vaumĩlĩte, mũkono ũmwe ngalĩ ĩya; na tũla tũsũmba, mĩkono thanthatũ ngalĩ ĩno, na mĩkono thanthatũ ngalĩ ĩya.'),
('kam', 'EZK', 40, 13, 'Na athima mbingĩlo kuma kĩalanĩ kya kasũmba kamwe kũvika kĩala kya kala kangĩ, ũthanthau wa mĩkono mĩongo ĩlĩ na ĩtano; mũomo welekele mũomo.'),
('kam', 'EZK', 40, 14, 'O na aseũvya ituĩ, mĩkono mĩongo thanthatũ; na nza yavikĩte ituĩnĩ, kũthyũlũlũka mbingĩlo.'),
('kam', 'EZK', 40, 15, 'Na kuma ngalĩ ya mbee ya mbingĩlo vala ve ũlikĩlo kũvika ngalĩ ya mbee ya valasya wa nthĩnĩ wa mbingĩlo nĩ mĩkono mĩongo ĩtano.'),
('kam', 'EZK', 40, 16, 'Na kwaĩ mbũthi ntheke sya tũsũmba, na sya ituĩ syatw’o nthĩnĩ wa mbingĩlo ithyũlũlũkĩte, na ĩngĩ sya ngulumbe; na mbũthi nĩsyathyũlũlũkĩte ngalĩ ya nthĩnĩ; na ĩũlũ wa kĩla kĩtuĩ kwaĩ mĩtĩ ya mĩtende.'),
('kam', 'EZK', 40, 17, 'Na ĩndĩ andwaa nza yĩ ũtee; na, sisya, kwaĩ tũsũmba na nthĩ nzeũvye na mavia malan’ye, vaseũvĩtwe kwondũ wa nza kũthyũlũlũka ngalĩ syonthe: tũsũmba mĩongo ĩtatũ twaĩ ĩũlũ wa nthĩ ĩsu nzeũvye.'),
('kam', 'EZK', 40, 18, 'Na nthĩ ĩsu yaĩ vakuvĩ na mbingĩlo, kũelekana na ũasa wa mbingĩlo, o nthĩ ĩsu nzeũvye ĩtheo.'),
('kam', 'EZK', 40, 19, 'Nĩvo ĩndĩ wathimie ũthanthau kuma ngalĩ ya mbee ya mbingĩlo ya ĩtheo kũvika ngalĩ ya mbee ya nza ya nthĩnĩ ngalĩ ya ũtee, mĩkono ĩana, ngalĩ ya wumĩlonĩ wa syũa, o na ngalĩ ya ĩũlũ.'),
('kam', 'EZK', 40, 20, 'Na mbingĩlo ya nza yĩ ũtee ĩla yelekele ngalĩ ya ĩũlũ, athima ũasa wayo na ũthanthau wayo.'),
('kam', 'EZK', 40, 21, 'Na tũsũmba twa asũviĩ twayo twaĩ tũtatũ ngalĩ ĩno na tũtatũ ngalĩ ĩya; na ituĩ syayo na ngulumbe syayo nĩsyeanene na kĩthimo kya mbingĩlo ya mbee: ũasa wayo waĩ mĩkono mĩongo ĩtano, na ũthanthau mĩkono mĩongo ĩlĩ na ĩtano.'),
('kam', 'EZK', 40, 22, 'Na mbũthi syayo, na ngulumbe syayo, na mĩtende yayo, nĩsyeanene na kĩthimo kya mbingĩlo ĩla yelekele wumĩlonĩ wa syũa; na mambata vo na matambya mũonza; na ngulumbe syayo syaĩ mbee wasyo.'),
('kam', 'EZK', 40, 23, 'Na kwaĩ mbingĩlo ya nza ya nthĩnĩ yelekele mbingĩlo ĩla ĩngĩ, ngalĩ ya ĩũlũ na ngalĩ ya wumĩlonĩ wa syũa; na athima kuma mbingĩlo kũvika mbingĩlo mĩkono ĩana.'),
('kam', 'EZK', 40, 24, 'Na andongoesya kwelekela ngalĩ ya ĩtheo; na, sisya, mbingĩlo yelekele ngalĩ ya ĩtheo: na athima ituĩ syayo na ngulumbe syayo kwĩanana na ithimo isu.'),
('kam', 'EZK', 40, 25, 'Na kwaĩ mbũthi nthĩnĩ wayo na nthĩnĩ wa ngulumbe syayo ngalĩ syonthe, syailyĩ mbũthi isu: ũasa waĩ mĩkono mĩongo ĩtano, na ũthanthau mĩkono mĩongo ĩlĩ na ĩtano.'),
('kam', 'EZK', 40, 26, 'Na kwaĩ matambya mũonza ma kwambata kwayo, na ngulumbe syayo syaĩ mbee wasyo; na yaĩ na mĩtĩ ya mĩtende, ũmwe ngalĩ ĩno, na ũngĩ ngalĩ ĩya, ĩũlũ wa ituĩ syayo.'),
('kam', 'EZK', 40, 27, 'Na kwaĩ mbingĩlo ya nza ya nthĩnĩ ngalĩ ya ĩtheo: na athima kuma mbingĩlo kũvika mbingĩlo kwelekela ngalĩ ya ĩtheo mĩkono ĩana.'),
('kam', 'EZK', 40, 28, 'Na ĩndĩ andwaa nza ya nthĩnĩ na mbingĩlo ya ngalĩ ya ĩtheo: na athima mbingĩlo ya ngalĩ ya ĩtheo kwĩanana na ithimo isu;'),
('kam', 'EZK', 40, 29, 'na tũsũmba twa asũvĩi twayo, na ituĩ syayo, na ngulumbe syayo, kwĩanana na ithimo isu: na kwaĩ mbũthi nthĩnĩ wayo na nthĩnĩ wa ngulumbe syayo ngalĩ syonthe; ũasa wayo waĩ mĩkono mĩongo ĩtano, na ũthanthau mĩkono mĩongo ĩlĩ na ĩtano.'),
('kam', 'EZK', 40, 30, 'Na kwaĩ ngulumbe ithyũlũlũkĩte ngalĩ syonthe, ũasa wa mĩkono mĩongo ĩlĩ na ĩtano, na ũthanthau mĩkono ĩtano.'),
('kam', 'EZK', 40, 31, 'Na ngulumbe syayo syelekele nza yĩ ũtee; na mĩtĩ ya mĩtende yaĩ ituĩnĩ syayo: na wambatĩlo wayo waĩ wa matambya nyanya.'),
('kam', 'EZK', 40, 32, 'Na andete nza ya nthĩnĩ kwelekela wumĩlonĩ wa syũa: na athima mbingĩlo kwĩanana na ithimo isu;'),
('kam', 'EZK', 40, 33, 'na tũsũmba twa asũvĩi twayo, na ituĩ syayo, na ngulumbe syayo, kwĩanana na ithimo isu: na kwaĩ mbũthi nthĩnĩ wayo na nthĩnĩ wa ngulumbe syayo ngalĩ syonthe; ũasa wayo waĩ mĩkono mĩongo ĩtano, na ũthanthau mĩkono mĩongo ĩlĩ na ĩtano.'),
('kam', 'EZK', 40, 34, 'Na ngulumbe syayo syelekele nza yĩ ũtee; na mĩtĩ ya mĩtende yaĩ ituĩnĩ syayo, ngalĩ ĩno, na ngalĩ ĩya: na wambatĩlo wayo waĩ wa matambya nyanya.'),
('kam', 'EZK', 40, 35, 'Na andete mbingĩlonĩ ya ngalĩ ya ĩũlũ: na amĩthima kwĩanana na ithimo isu;'),
('kam', 'EZK', 40, 36, 'tũsũmba twa asũvĩi twayo, ituĩ syayo, na ngulumbe syayo: na kwaĩ mbũthi nthĩnĩ wayo ngalĩ syonthe; ũasa waĩ mĩkono mĩongo ĩtano, na ũthanthau mĩkono mĩongo ĩlĩ na ĩtano.'),
('kam', 'EZK', 40, 37, 'Na ituĩ syayo syelekele nza yĩ ũtee; na mĩtĩ ya mĩtende yaĩ ĩũlũ wa ituĩ syayo, ngalĩ ĩno, na ngalĩ ĩya: na wambatĩlo wayo waĩ wa matambya nyanya.'),
('kam', 'EZK', 40, 38, 'Na kasũmba vamwe na mũomo wako kaĩ vakuvĩ na ituĩ mbingĩlonĩ; vau nĩmathambĩasya nthembo ya kũvĩvw’a.'),
('kam', 'EZK', 40, 39, 'Na valasyanĩ wa mbingĩlo kwaĩ mesa ilĩ ngalĩ ĩno, na mesa ilĩ ngalĩ ĩya, na ĩũlũ wasyo masyũaĩaa nthembo ya kũvĩvw’a na nthembo ya naĩ na nthembo ya mavĩtyo.'),
('kam', 'EZK', 40, 40, 'Na ngalĩ ĩmwe ũtee, vandũ va kwambatĩla ũlikĩlonĩ wa mbingĩlo kwelekela ngalĩ ya ĩũlũ, kwaĩ mesa ilĩ: na ngalĩ ĩla ĩngĩ, ĩla yaĩ ya valasya wa mbingĩlo, kwaĩ mesa ilĩ.'),
('kam', 'EZK', 40, 41, 'Mesa inya syaĩ ngalĩ ĩno, na mesa inya ngalĩ ĩya, vakuvĩ na mbingĩlo; mesa nyanya, ila mooaĩaa nthembo ĩũlũ wasyo.'),
('kam', 'EZK', 40, 42, 'Na kwaĩ mesa inya sya nthembo sya kũvĩvw’a, sya mavia masũvye, ũasa wa mũkono na nyunzu, na ũthanthau wa mũkono na nyunzu, na ũtũlu wa mũkono; ila mailĩĩlaa mĩio ĩla mooaaa nthembo ya kũvĩvw’a na nthembo ya kũtonywa nayo.'),
('kam', 'EZK', 40, 43, 'Na mboloi, ũasa wasyo waĩ kĩtaa kya kw’oko, syaathĩĩwe nthĩnĩ ngalĩ syonthe: na ĩũlũ wa mesa isu kwaĩ nyama sya nthembo.'),
('kam', 'EZK', 40, 44, 'Na ũtee wa mbingĩlo ya nthĩnĩ kwaĩ tũsũmba kwondũ wa aini nza ya nthĩnĩ, ĩla yaĩ vakuvĩ na mbingĩlo ya ngalĩ ya ĩũlũ; na twelekele ngalĩ ya ĩtheo; kamwe vakuvĩ mbingĩlo ya wumĩlonĩ wa syũa kelekele ngalĩ ya ĩũlũ.'),
('kam', 'EZK', 40, 45, 'Na ambĩa, Kasũmba kaa, kala kelekele ngalĩ ya ĩtheo, nĩ ka athembi, asũvĩi ma wĩaĩo wa nyũmba;'),
('kam', 'EZK', 40, 46, 'na kasũmba kala kelekele ngalĩ ya ĩũlũ nĩ ka athembi, asũvĩi ma wĩaĩo wa kĩthembeo: asu nĩ ana ma Nzatoki, ala kuma ananĩ ma Livai mathengeeaa Yeova mamũthũkũmae.'),
('kam', 'EZK', 40, 47, 'Na athima nza, ũasa wayo mĩkono ĩana, na ũthanthau wayo mĩkono ĩana, ngalĩ inya syĩanene; na kĩthembeo kyaĩ mbee wa nyũmba.'),
('kam', 'EZK', 40, 48, 'Na ĩndĩ andete valasyanĩ wa nyũmba, na athima kĩla kĩtuĩ kya valasya, mĩkono ĩtano ngalĩ ĩno, na mĩkono ĩtano ngalĩ ĩya: na ũthanthau wa mbingĩlo waĩ mĩkono ĩtatũ ngalĩ ĩno, na mĩkono ĩtatũ ngalĩ ĩya.'),
('kam', 'EZK', 40, 49, 'Ũasa wa valasya waĩ mĩkono mĩongo ĩlĩ, na ũthanthau mĩkono ĩkũmi na ũmwe; na mambataa vo na matambya asu: na kwaĩ ituĩ vakuvĩ na mĩtĩ yĩ ndee sya mũomo, kĩmwe ngalĩ ĩno, na kĩngĩ ngalĩ ĩya.'),
('kam', 'EZK', 41, 1, 'Na andete ĩkalũnĩ, na athima ituĩ, mĩkono thanthatũ ũthanthau wa ngalĩ ĩmwe, na mĩkono thanthatũ wa ngalĩ ĩla ĩngĩ, naw’o waĩ ũthanthau wa yĩla ĩeema.'),
('kam', 'EZK', 41, 2, 'Na ũthanthau wa ũlikĩlo waĩ mĩkono ĩkũmi; na ndee sya ũlikĩlo syaĩ mĩkono ĩtano ngalĩ ĩmwe, na mĩkono ĩtano ngalĩ ĩla ĩngĩ: na athima ũasa wa vo, mĩkono mĩongo ĩna, na ũthanthau, mĩkono mĩongo ĩlĩ.'),
('kam', 'EZK', 41, 3, 'Nĩvo ĩndĩ walikile nthĩnĩ, na athima kĩla kĩtuĩ kya ũlikĩlonĩ, mĩkono ĩlĩ; na ũlikĩlo, mĩkono thanthatũ; na ũthanthau wa ũlikĩlo, mĩkono mũonza.'),
('kam', 'EZK', 41, 4, 'Na athima ũasa wa vo, mĩkono mĩongo ĩlĩ, na ũthanthau, mĩkono mĩongo ĩlĩ, na ũthanthau, mĩkono mĩongo ĩlĩ, ngalĩ ya mbee ya ĩkalũ: na ambĩa, Vaa nĩ vandũ vala vatheu mbee.'),
('kam', 'EZK', 41, 5, 'Na ĩndĩ athima wako wa nyũmba, mĩkono thanthatũ; na ũthanthau wa kĩla kasũmba ke ũtee, mĩkono ĩna, kũthyũlũlũka nyũmba kĩla ngalĩko.'),
('kam', 'EZK', 41, 6, 'Na tũsũmba tũla twaĩ ũtee twaĩ tũtatũ twilĩanĩlw’e, kamwe ĩũlũ wa kangĩ, na mĩongo ĩtatũ tũatĩanĩe; na twaakĩĩwe wakonĩ ũla wa nyũmba wĩthĩwe na tũsũmba twĩ ndee tũthyũlũlũkĩte, nĩ kana tũkwatane nthĩnĩ waw’o, na tũtyakwatene, na wako wa ĩ nyũmba.'),
('kam', 'EZK', 41, 7, 'Na tũsũmba twĩ ndee twaĩ tũthanthaangu tũkĩthyũlũlũka ĩũlũ na ĩũlũ: nũndũ kũthyũlũlũka kwa nyũmba kwambatie ĩũlũ na ĩũlũ ngalĩ syonthe sya nyũmba: kwondũ wa ũu ũthanthau wa nyũmba nĩwaendeee kũthanthaa kũvika ĩũlũ; na mũndũ ambataa ta ũu kuma kasũmba ka ĩtheo kũvika kasũmba ke ĩũlũ aivĩtĩla kasũmba ka katĩ.'),
('kam', 'EZK', 41, 8, 'O na ĩngĩ noona ĩ nyũmba yaĩ na wambĩlĩlyo ũkĩlĩĩlw’e ĩũlũ wa nthĩ ngalĩ syonthe: myambĩlĩlyo ya tũsũmba twĩ ndee yaĩ mũangi mwĩanĩu wa mĩkono thanthatũ mĩasa.'),
('kam', 'EZK', 41, 9, 'Kĩemo kya wako, ũla waĩ wa tũsũmba twĩ ndee, ngalĩ ya nza, kyaĩ mĩkono ĩtano: na ũthei ũla watialile waĩ vandũ va tũsũmba twĩ ndee tũla twa nyũmba.'),
('kam', 'EZK', 41, 10, 'Na katĩ wa tũsũmba kwaĩ ũthanthau wa mĩkono mĩongo ĩlĩ kũthyũlũlũka nyũmba ngalĩ syonthe.'),
('kam', 'EZK', 41, 11, 'Na mĩomo ya tũsũmba twĩ ndee yelekele vandũ vala vatialile, mũomo ũmwe welekele ngalĩ ya ĩũlũ, na mũomo ũngĩ welekele ngalĩ ya ĩtheo: na ũthanthau wa vandũ vau vatiele waĩ mĩkono ĩtano ngalĩ syonthe.'),
('kam', 'EZK', 41, 12, 'Na mwako ũla waĩ mbee wa vandũ vavathan’ye ngalĩ ĩla yelekele ũthũĩlonĩ wa syũa ũthanthau waw’o waĩ mĩkono mĩongo mũonza; na kĩemo kya wako wa mwako ũsu kyaĩ mĩkono ĩtano ngalĩ syonthe, na ũasa waw’o waĩ mĩkono mĩongo kenda.'),
('kam', 'EZK', 41, 13, 'O ta ũu athima nyũmba, ũasa wayo waĩ mĩkono ĩana; na vandũ vavathan’ye, na mwako, vamwe na mawako maw’o, ũasa nĩ mĩkono ĩana;'),
('kam', 'EZK', 41, 14, 'o na ũthanthau wa ngalĩ ya mbee ya nyũmba, na wa vandũ vavathan’ye kwelekela wumĩlonĩ wa syũa, nĩ mĩkono ĩana.'),
('kam', 'EZK', 41, 15, 'Na athima ũasa wa mwako mbee wa vandũ vavathan’ye vala vaĩ ĩtina waw’o, na mavalasya maw’o me ĩũlũ nthĩnĩ ngalĩ ĩmwe na ngalĩ ĩla ĩngĩ, mĩkono ĩana; na ĩkalũ ya nthĩnĩ, na mavalasya ma nza;'),
('kam', 'EZK', 41, 16, 'myalyo ya mĩomo, na mbũthi mbinge, na mavalasya me ĩũlũ nthĩnĩ mathyũlũlũkĩte tũsũmba tũũ tũtatũ, kamwe ĩũlũ wa kangĩ, kwelekela mwalyo wa mũomo, syaseũvw’a nthĩnĩ kw’onthe na mbwaũ, na kuma nthĩ kũvika mbũthi (na mbũthi syaĩ mbw’ĩke),'),
('kam', 'EZK', 41, 17, 'kũvika ũthei ũla wĩ ĩũlũ wa mũomo, o kũvika nyũmba ya nthĩnĩ, na ngalĩ ya nza, kũvikĩa wako w’onthe ũla ũthyũlũlũkĩte nthĩnĩ na ũtee, kwa kũthima.'),
('kam', 'EZK', 41, 18, 'Na waseũvw’a wĩ na akeluvi na mĩtĩ ya mĩtende; na kwaĩ mũtĩ wa mũtende katĩ wa mũkeluvi na mũkeluvi, na kĩla mũkeluvi aĩ na mothyũ elĩ;'),
('kam', 'EZK', 41, 19, 'o ta ũu kwaĩ ũthyũ wa mũndũ welekele mũtĩ wa mũtende ngalĩ ĩmwe, na ũthyũ wa mũnyambũ wa mũika welekele mũtĩ wa mũtende ngalĩ ĩla ĩngĩ. Kwaseũviw’e ta ũu nyũmbanĩ yonthe ngalĩ syonthe:'),
('kam', 'EZK', 41, 20, 'kuma nthĩ kũvika ĩũlũ wa mũomo kwaseũviw’e akeluvi na mĩtĩ ya mĩtende; wako wa ĩkalũ wailyĩ ta ũu.'),
('kam', 'EZK', 41, 21, 'Ũndũ wa ĩkalũ, mĩtĩ ĩla yĩ ndee sya mũomo yaseũvw’a yĩanene ngalĩ inya; na ũndũ wa ngalĩ ya mbee ya vala vandũ vatheu, mũvw’anĩle wa vo wailyĩ mũvw’anĩle wa ĩkalũ.'),
('kam', 'EZK', 41, 22, 'Kĩthembeo kyaĩ kya mĩtĩ, ũtũlu wakyo mĩkono ĩtatũ, na ũasa wakyo mĩkono ĩlĩ; na ĩkoto syakyo, na ũasa wakyo, na mavava makyo, maĩ ma mĩtĩ: na ambĩa, Ĩno nĩyo mesa ĩla yĩ mbee wa Yeova.'),
('kam', 'EZK', 41, 23, 'Na ĩkalũ na vala vandũ vatheu syaĩ na mĩomo ĩlĩ.'),
('kam', 'EZK', 41, 24, 'Na mĩomo yaĩ na mbwaũ ilĩ kĩla ũmwe, mbwaũ ilĩ ila ithyũlũlũkaa: mbwaũ ilĩ sya mũomo ũmwe, na mbwaũ ilĩ sya mũomo ũla ũngĩ.'),
('kam', 'EZK', 41, 25, 'Na kwavanĩĩw’a ĩũlũ wayo, mĩomonĩ ya ĩkalũ, akeluvi na mĩtĩ ya mĩtende, ta ila syavanĩĩw’e mawakonĩ; na kwaĩ mĩamba mĩnene mbee wa valasya ngalĩ ya nza.'),
('kam', 'EZK', 41, 26, 'Na kwaĩ mbũthi mbinge na mĩtĩ ya mĩtende ngalĩ ĩmwe na ngalĩ ĩla ĩngĩ, ndee sya valasya: tũsũmba twĩ ndee sya ĩla nyũmba na myalyo ya mĩomo syailyĩ ũu.'),
('kam', 'EZK', 42, 1, 'Na ĩndĩ anumaalya nza yĩ ũtee, nzĩa ya kũthi ngalĩ ya ĩũlũ: na andete kasũmbanĩ kala kelekele vala vandũ vavathan’ye, na kelekele mwako ngalĩ ya ĩũlũ.'),
('kam', 'EZK', 42, 2, 'Mbee wa ũla ũasa wa mĩkono ĩana kwaĩ mũomo wa ngalĩ ya ĩũlũ, na ũthanthau waĩ mĩkono mĩongo ĩtano.'),
('kam', 'EZK', 42, 3, 'Kwelekela mĩkono mĩongo ĩlĩ ĩla ya nza ya nthĩnĩ, na kwelekela nthĩ nzeũvye na mavia ĩla ya nza yĩ ũtee, kwaĩ valasya wa ĩũlũ nthĩnĩ welekele valasya wa ĩũlũ nthĩnĩ kasũmbanĩ ka katatũ ka tũla twilĩanĩlw’e.'),
('kam', 'EZK', 42, 4, 'Na mbee wa tũsũmba kwaĩ nzĩa ya ũthanthau wa mĩkono ĩkũmi ya kũlika nthĩnĩ, nzĩa ya mũkono ũmwe; na mĩomo yatw’o yelekele ngalĩ ya ĩũlũ.'),
('kam', 'EZK', 42, 5, 'Tũsũmba twa ĩũlũ twaĩ tũkuvangĩ; nũndũ mavalasya ma ĩũlũ nĩmaolete tũsũmba tũu, kũvĩtũka ũndũ tũla twa ĩtheo na tũla twa katĩ twaoletwe, mwakonĩ ũsu.'),
('kam', 'EZK', 42, 6, 'Nũndũ twaĩ tũsũmba tũtatũ twilĩanĩlw’e, na tũtyaĩ na ituĩ, ta ituĩ sya nza: kwondũ wa ũu kala kaĩ ĩũlũ kaĩ katheke kwĩ kala ke ĩtheo na kala ke katĩ kuma nthĩ.'),
('kam', 'EZK', 42, 7, 'Na wako ũla waĩ ngalĩ ya nza ũtee wa tũsũmba, kwelekela nza yĩ ũtee ngalĩ ya mbee ya tũsũmba, ũasa waw’o waĩ mĩkono mĩongo ĩtano.'),
('kam', 'EZK', 42, 8, 'Nũndũ ũasa wa tũsũmba tũla twaĩ nza yĩ ũtee waĩ mĩkono mĩongo ĩtano: na, sisya, ngalĩ ya mbee ya ĩkalũ kwaĩ mĩkono ĩana.'),
('kam', 'EZK', 42, 9, 'Na kuma ĩtheo wa tũsũmba tũu kwaĩ ũlikĩlo ngalĩ ya wumĩlonĩ wa syũa, vala mũndũ ũvotelaa nthĩnĩ watw’o kuma nza yĩ ũtee.'),
('kam', 'EZK', 42, 10, 'Kĩemonĩ kya ũvai wa nza kwelekela wumĩlonĩ wa syũa, mbee wa vala vandũ vavathan’ye, na mbee wa mwako, kwaĩ tũsũmba.'),
('kam', 'EZK', 42, 11, 'Na nzĩa yĩ mbee watw’o yaĩ na mũvw’anĩle wa nzĩa ya tũsũmba tũla twelekele ngalĩ ya ĩũlũ; kwĩanana na ũasa watw’o now’o ũthanthau watw’o wailyĩ: na mawumaalĩlo onthe matw’o maĩ kwĩanana na moseũvĩlw’e matw’o, na kwĩanana na mĩomo yatw’o.'),
('kam', 'EZK', 42, 12, 'Na kwĩanana na mĩomo ya tũsũmba tũla twelekele ngalĩ ya ĩtheo kwaĩ mũomo wambĩlĩlyonĩ wa nzĩa, o nzĩa ĩla yaendele mbee wa ũvai yelekele ngalĩ ya wumĩlonĩ wa syũa, o vala mũndũ wavotelaa nthĩnĩ watw’o.'),
('kam', 'EZK', 42, 13, 'Nĩvo ĩndĩ wambĩĩe, Tũsũmba twa ngalĩ ya ĩũlũ na tũsũmba twa ngalĩ ya ĩtheo, tũla twĩ mbee wa vala vandũ vavathan’ye, tũu nĩtw’o tũsũmba tũtheu, vala athembi ala me vakuvĩ na Yeova makaĩsaa syĩndũ ila ntheu mũno: vau makaia syĩndũ ntheu mbee, na nthembo ya mũtu, na nthembo ya naĩ, na nthembo ya mavĩtyo; nũndũ vandũ vau nĩ vatheu.'),
('kam', 'EZK', 42, 14, 'Yĩla athembi malika, matikaumaalae kuma vala vandũ vatheu kũthi nza yĩ ũtee, ĩndĩ meiaa ngũa syoo vo ila methũkũmaa nasyo; nũndũ nĩ ntheu: na meĩkĩaa ngũa ingĩ, na makĩthengeea vala ve andũ.'),
('kam', 'EZK', 42, 15, 'Na yĩla waminie kũthima nyũmba ya nthĩnĩ, anumaalya na nzĩa ya mbingĩlo ĩla yelekele ngalĩ ya wumĩlonĩ wa syũa, na amĩthima ngalĩ syonthe.'),
('kam', 'EZK', 42, 16, 'Athima ngalĩ ya wumĩlonĩ wa syũa na mũangi wa kũthima mĩangi maana atano, na mũangi wa kũthima ngalĩ syonthe.'),
('kam', 'EZK', 42, 17, 'Athima ngalĩ ya ĩũlũ mĩangi maana atano na mũangi wa kũthima ngalĩ syonthe.'),
('kam', 'EZK', 42, 18, 'Athima ngalĩ ya ĩtheo mĩangi maana atano, na mũangi wa kũthima.'),
('kam', 'EZK', 42, 19, 'Eethyũũa ngalĩ ya ũthũĩlonĩ wa syũa, na athima mĩangi maana atano na mũangi wa kũthima.'),
('kam', 'EZK', 42, 20, 'Amĩthima ngalĩ inya: yaĩ na ũvai ũthyũlũlũkĩte, ũasa maana atano, na ũthanthau maana atano, wa kũvathan’ya vala vatheu na vala vate vatheu.'),
('kam', 'EZK', 43, 1, 'Ĩtina wa ũu andete mbingĩlonĩ, o mbingĩlonĩ ĩla yelekele ngalĩ ya wumĩlonĩ wa syũa.'),
('kam', 'EZK', 43, 2, 'Na, sisya, ũtheu mũtisu wa Ngai wa Isilaeli wooka wumĩte ngalĩ ya wumĩlonĩ wa syũa: na wasya wake wailyĩ kĩuumo kya manzĩ maingĩ; na nthĩ yatisw’a nĩ ũtheu mũtisu wake.'),
('kam', 'EZK', 43, 3, 'Na mũvw’anĩle waw’o wailyĩ mũvw’anĩle wa woni ũla noonie, o kwĩanana na woni ũla noonie yĩla nookie kwananga ĩ ndũa; na mawoni mailyĩ woni ũla noonie vakuvĩ na ũsĩ wa Kevali; na navalũka na ũthyũ wakwa.'),
('kam', 'EZK', 43, 4, 'Na ũtheu mũtisu wa Yeova walika nyũmbanĩ na nzĩa ya mbingĩlo ĩla yelekele ngalĩ ya wumĩlonĩ wa syũa.'),
('kam', 'EZK', 43, 5, 'Na Veva ambũkĩlya, na andete nza ya nthĩnĩ; na, sisya, ũtheu mũtisu wa Yeova wausũa nyũmba.'),
('kam', 'EZK', 43, 6, 'Na neew’a ũmwe aineena nakwa e nyũmbanĩ; na mũndũ aũngama vakuvĩ nakwa.'),
('kam', 'EZK', 43, 7, 'Na ambĩa, Mwana wa mũndũ, vaa nĩ vandũ va kĩvĩla kyakwa kya ũsumbĩ, na vandũ va nyaĩĩ syakwa, vala ngatũaa katĩ wa ana ma Isilaeli tene na tene. Na nyũmba ya Isilaeli ndĩkavukya syĩtwa yakwa ĩtheu ĩngĩ, mo, kana asumbĩ moo, kwondũ wa ũmalwaya woo, na kwondũ wa simba sya asumbĩ moo syĩ kũndũ kwoo kũtũlu;'),
('kam', 'EZK', 43, 8, 'makia mwalyo woo wa mũomo vakuvĩ na mwalyo wakwa wa mũomo, na mũtĩ woo wĩ ũtee wa mũomo vakuvĩ na mũtĩ wakwa wĩ ũtee wa mũomo, na kwaĩ no ũvai katĩ wakwa nao; na nĩmavũkĩtye syĩtwa yakwa ĩtheu kwondũ wa mothatyo moo ala mekĩte: kwondũ wa ũu nĩnĩmaminĩte ũthatunĩ wakwa.'),
('kam', 'EZK', 43, 9, 'Yu nĩmavete kũasa nakwa ũmalwaya woo, na simba sya asumbĩ moo; na ngatũaa katĩ woo tene na tene.'),
('kam', 'EZK', 43, 10, 'Naku, mwana wa mũndũ, on’ya nyũmba ya Isilaeli ĩ nyũmba, nĩ kana masonoke nũndũ wa mothũku moo; na nĩmathime ngelekan’yo yayo.'),
('kam', 'EZK', 43, 11, 'Na ethĩwa makasonoka nũndũ wa maũndũ onthe ala meekie, mamanyĩthye mũvw’ano wa nyũmba, na mwakĩle wayo, na mawumaalĩlo mayo, na molilĩlo mayo, na mĩvw’ano yonthe yayo, na motw’ĩo onthe mayo, na mĩvw’ano yonthe yayo, na mĩao yonthe yayo; noiandĩka mene; nĩ kana masũvĩe mũvw’ano w’onthe wayo, na motw’ĩo onthe mayo, na kũmeka.'),
('kam', 'EZK', 43, 12, 'Mwĩao wa nyũmba nĩ ũũ: kĩĩmanĩ ĩũlũ mũvakanĩ w’onthe wakyo ngalĩ syonthe kĩkeethĩwa kĩtheu mũno. Sisya, ũũ nĩw’o mwĩao wa nyũmba.'),
('kam', 'EZK', 43, 13, 'Na ii nĩsyo ithimo sya kĩthembeo ikĩthimwa na mĩkono (mũkono nĩ mũkono na ũthanthau wa kĩtaa kya kw’oko): ĩtina yakyo yĩkeethĩwa mũkono, na ũthanthau mũkono, na ũengo wakyo vakuvĩ na ũtee wakyo kũthyũlũlũka nĩ ĩkwata yĩmwe ya kĩtaa; na yĩu yĩkeethĩwa ĩtina ya kĩthembeo.'),
('kam', 'EZK', 43, 14, 'Na kuma ĩtina yĩ nthĩ kũvika ũnyitĩku wa ĩtheo kũkeethĩwa mĩkono ĩlĩ, na ũthanthau mũkono ũmwe; na kuma ũnyitĩku mũnini kũvika ũnyitĩku mũnene kũkeethĩwa mĩkono ĩna, na ũthanthau mũkono ũmwe.'),
('kam', 'EZK', 43, 15, 'Na kĩthembeo kya ĩũlũ kĩkeethĩwa mĩkono ĩna; na kuma kaikonĩ ka kĩthembeo na kũthi ĩũlũ kũkeethĩwa mbya inya.'),
('kam', 'EZK', 43, 16, 'Na kaiko ka kĩthembeo kakeethĩwa mĩkono ĩkũmi na ĩlĩ ũasa wako, na ĩkũmi na ĩlĩ ũthanthau, ngalĩ inya syako syĩanene.'),
('kam', 'EZK', 43, 17, 'Na ũnyitĩku ũkeethĩwa mĩkono ĩkũmi na ĩna ũasa waw’o na ĩkũmi na ĩna ũthanthau waw’o ngalĩ inya syaw’o; na ũengo ũtee wakyo ũkeethĩwa nyunzu ya mũkono; na ĩtina yakyo yĩkeethĩwa mũkono ngalĩ syonthe; na kyambatĩlo kyakyo kĩkeelekela ngalĩ ya wumĩlonĩ wa syũa.'),
('kam', 'EZK', 43, 18, 'Na ambĩa, Mwana wa mũndũ, ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Aa nĩ motw’ĩo ma kĩthembeo mũthenya ũla makakĩseũvya, mathembe nthembo ya kũvĩvw’a ĩũlũ wakyo, na kũminzangĩsya nthakame ĩũlũ wakyo.'),
('kam', 'EZK', 43, 19, 'Athembi Alivai ala ma ũsyao wa Nzatoki, ala me vakuvĩ nakwa, manthũkũme, ũkamanenga kasalũ kamwe kethĩwe nthembo ya naĩ, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 43, 20, 'Na ũkoosa nthakame yako, na kũmĩkĩa mbyanĩ inya syakyo, na ikotonĩ inya sya ũnyitĩku, na ũengonĩ ũthyũlũlũkĩte: ta ũu ũkakĩthesya na kumya nthembo ya wĩw’anĩthyo kwondũ wakyo.'),
('kam', 'EZK', 43, 21, 'O na ũkoosa kala kasalũ ka nthembo ya naĩ, na kakavĩvw’a vandũ vatw’e va ĩ nyũmba, ũtee wa vala vandũ vatheu.'),
('kam', 'EZK', 43, 22, 'Na mũthenya wa kelĩ ũkathemba nthenge ĩte kĩema ĩthĩwe nthembo ya naĩ; na makathesya kĩthembeo, o ũndũ makĩtheisye na kala kasalũ.'),
('kam', 'EZK', 43, 23, 'Na wamina ũkĩthesya, ũkathemba kasalũ kate kĩema, na ndũũme ya ndĩthya ĩte kĩema.'),
('kam', 'EZK', 43, 24, 'Na ũkaithengeesya mbee wa Yeova, na athembi makasyĩkĩa mũnyũ, na makaithembea Yeova syĩthĩwe nthembo ya kũvĩvw’a.'),
('kam', 'EZK', 43, 25, 'Mĩthenya mũonza o kĩla mũthenya ũkaseũvasya mbũi yĩthĩwe nthembo ya naĩ: o na makaseũvya kasalũ, na ndũũme ya ndĩthya, ite kĩema.'),
('kam', 'EZK', 43, 26, 'Mĩthenya mũonza makathembaa nthembo ya wĩw’anĩthyo kwondũ wa kĩthembeo na kũkĩthesya; makakĩvathanasya kĩthĩwe kĩtheu ta ũu.'),
('kam', 'EZK', 43, 27, 'Na yĩla meanĩsya mĩthenya, kũkeethĩwa atĩ mũthenya wa nyanya, na kũendeea mbee, athembi makaseũvya nthembo syenyu sya kũvĩvw’a kĩthembeonĩ, na nthembo syenyu sya mũuo; na ngamwĩtĩkĩla inyw’ĩ, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 44, 1, 'Na ĩndĩ nĩwandũngĩle nzĩanĩ ya mbingĩlo ya nza ya vala vandũ vatheu, ĩla yelekele ngalĩ ya wumĩlonĩ wa syũa; na yaĩ mbinge.'),
('kam', 'EZK', 44, 2, 'Na Yeova ambĩa, Mbingĩlo ĩno ĩkavingwa; na ndĩkavingũwa, na mũndũ o na wĩva ndakamĩvotela; nũndũ Yeova, Ngai wa Isilaeli, nũmĩvotele; kwondũ wa ũu ĩkavingwa.'),
('kam', 'EZK', 44, 3, 'Ũndũ wa mũnene wĩ mbee ũsumbĩnĩ, akekala nthĩnĩ wayo ta mũnene wĩ mbee ũsumbĩnĩ aĩe lĩu mee wa Yeova; akavota na nzĩa ya valasya wa mbingĩlo, na akaumaalĩla nzĩa o ĩsu.'),
('kam', 'EZK', 44, 4, 'Na ĩndĩ andete na nzĩa ya mbingĩlo yĩ ngalĩ ya ĩũlũ mbee wa nyũmba; na noona, na, sisya, ũtheu mũtisu wa Yeova wausũa nyũmba ya Yeova: na navalũka na ũthyũ wakwa.'),
('kam', 'EZK', 44, 5, 'Na Yeova ambĩa, Mwana wa mũndũ, sũvĩa nesa, wone na metho maku, na kwĩw’a na matũ maku w’onthe ũla ngũkwĩa ũndũ wa motw’ĩo onthe ma nyũmba ya Yeova, na mĩao yonthe yayo; na sũvĩa nesa ũlikĩlo wa nyũmba, na kĩla wumaalĩlo wa vala vandũ vatheu.'),
('kam', 'EZK', 44, 6, 'Na ũkamatavya ala ang’endu, o nyũmba ya Isilaeli, Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Inyw’ĩ nyũmba ya Isilaeli, ĩanĩwai nũu mothatyonĩ menyu onthe,'),
('kam', 'EZK', 44, 7, 'nũndũ nĩmwaetie andũ ma nthĩ ingĩ, mate aĩke ngoonĩ, na mate aĩke mwĩĩnĩ, malike vala vandũ vakwa vatheu, mavavukye, o nyũmba yakwa, yĩla mũthembaa kĩmũtũ kyakwa, mathunya na nthakame, nao nĩmanangĩte ũtianĩo wakwa, mongeleele mothatyo menyu onthe.'),
('kam', 'EZK', 44, 8, 'Na inyw’ĩ mũtyaasũvĩa wĩaĩo wa syĩndũ syakwa ntheu; ĩndĩ nĩmwiĩte asũvĩi ma wĩaĩo wakwa ma vala vandũ vakwa vatheu kwondũ wenyu ene.'),
('kam', 'EZK', 44, 9, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya, Vai mũndũ wa nthĩ ĩngĩ o na wĩva, ũte mwaĩke ngoonĩ na ũte mwaĩke mwĩĩnĩ, ũkalika vala vandũ vakwa vatheu, wa andũ ma nthĩ ingĩ o na meva ala me katĩ wa ana ma Isilaeli.'),
('kam', 'EZK', 44, 10, 'Ĩndĩ Alivai ala maendie kũasa nakwa, ala mandiie makĩatĩĩa mĩvw’anano yoo, o yĩla Isilaeli maaĩte, makakua ũthũku woo.'),
('kam', 'EZK', 44, 11, 'Ĩndĩ makeethĩwa athũkũmi vala vandũ vakwa vatheu, me asyaĩĩsya mbingĩlonĩ sya nyũmba, na makĩthũkũma nyũmbanĩ: makooaa nthembo ya kũvĩvw’a na nthembo ya kũtonywa kwondũ wa andũ, na makaũngama mbee woo mamathũkũme.'),
('kam', 'EZK', 44, 12, 'Nĩkwĩthĩwa nĩmamathũkũmĩe vu mbee wa mĩvw’anano yoo, na matw’ĩka ũlulutĩkyo wa ũthũku kwa nyũmba ya Isilaeli; kwondũ wa ũu nĩnĩmokĩlĩlye kw’oko kwakwa, easya ũu Mwĩaĩi Yeova, na makakua ũthũku woo.'),
('kam', 'EZK', 44, 13, 'Na matikanthengeea, manthũkũme wĩanĩ wa ũthembi, kana kũthengeea kĩndũ o na kĩva kya syĩndũ syakwa ntheu, syĩndũ ila ntheu mbee; ĩndĩ makakua nthoni syoo, na mothatyo moo ala mekaa.'),
('kam', 'EZK', 44, 14, 'Ĩndĩ ngamatw’ĩkĩthya asũvĩi ma wĩaĩo wa nyũmba, kwondũ wa ũthũkũmi w’onthe wayo, na kwondũ wa w’onthe ũla ũkekwa nthĩnĩ wayo.'),
('kam', 'EZK', 44, 15, 'Ĩndĩ athembi Alivai, ana ma Nzatoki, ala masũvĩaa wĩaĩo wa vala vandũ vakwa vatheu yĩla ana ma Isilaeli mandiĩte, makanthengeea manthũkũme; na makaũngama mbee wakwa manthembee mathunya na nthakame, easya ũu Mwĩaĩi Yeova:'),
('kam', 'EZK', 44, 16, 'makalika vala vandũ vakwa vatheu, na makathengeea mesa yakwa, manthũkũme, na makasũvĩa wĩaĩo wakwa.'),
('kam', 'EZK', 44, 17, 'Na kũkeethĩwa, yĩla melika mbingĩlonĩ sya nza ya nthĩnĩ, makeethĩawa mekĩĩte ngũa sya katane; na maikekĩe ngũa ya w’ĩa wa ĩlondu, yĩla methũkũmaa mbingĩlonĩ sya nza yĩ nthĩnĩ, o na nthĩnĩ.'),
('kam', 'EZK', 44, 18, 'Makeethĩwa na tũkovila twa katane mĩtwenĩ yoo, na makeethĩwa na masulualĩ ma katane inyunyunĩ syoo; na matĩkevotoa kĩndũ o na kĩva kĩkĩa yuutĩa.'),
('kam', 'EZK', 44, 19, 'Na yĩla meumaala nza yĩ ũtee, o nza yĩ ũtee vala ve andũ, makaumya ngũa syoo ila mathũkũmaa nasyo, na kũsia tũsũmbanĩ tũtheu; na makeekĩa ngũa ingĩ, nĩ kana matikavathan’ye andũ methĩwe atheu kwondũ wa ngũa isu syoo.'),
('kam', 'EZK', 44, 20, 'O na matikenze mĩtwe yoo, kana kũeka nzw’ĩĩ syoo syĩane mũno; no kũtilangaa nzwiĩĩ sya mĩtwe yoo.'),
('kam', 'EZK', 44, 21, 'O na mũthembi o na wĩva ndakanyw’e mbinyu, yĩla melikaa nza ya nthĩnĩ.'),
('kam', 'EZK', 44, 22, 'O na matikatwae ndiwa syĩthĩwe iveti syoo, kana ũla ũeketwe; ĩndĩ makatwaa eitu atheu ma ũsyao wa nyũmba ya Isilaeli, kana ndĩwa ĩnaĩ mũka wa mũthembi.'),
('kam', 'EZK', 44, 23, 'Na makamanyĩsya andũ makwa kĩvathũkan’yo katĩ wa kĩla kĩtheu na kĩla kĩte kĩtheu, na kũtuma mavathũkan’ya katĩ wa kĩla kĩvuku na kĩla kĩtheu.'),
('kam', 'EZK', 44, 24, 'Na ngananĩonĩ makaũngama kũsila; makatusaa kwĩanana na motw’ĩo makwa: na makakwata mĩao yakwa na myamũlo yakwa mbokanĩ syakwa syonthe itw’ĩtwe; na makavathan’ya masavato makwa methĩwe matheu.'),
('kam', 'EZK', 44, 25, 'Na matikalika vala ve mũndũ mũkw’ũ mevukye; ĩndĩ kwondũ wa ĩthe, kana nyinyia, kana mwana, kana mwĩĩtu, kana mwana‐a‐inyia, kana mwĩĩtu‐a‐inyia ũla ũtaĩ na mũũme, nĩmatonya kwĩvukya.'),
('kam', 'EZK', 44, 26, 'Na amina kũthew’a, makamũtalĩla mĩthenya mũonza.'),
('kam', 'EZK', 44, 27, 'Na mũthenya ũla wĩlika vala vandũ vatheu, nza ya nthĩnĩ, athũkũmĩe vala vandũ vatheu, akathemba nthembo yake ya naĩ, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 44, 28, 'Na makeethĩwa na ũtiĩwa: ninyie ũtiĩwa woo; na mũtikamanenga ng’ũndũ o na yĩva nthĩnĩ wa Isilaeli; ninyie ng’ũndũ yoo.'),
('kam', 'EZK', 44, 29, 'Makaĩsaa nthembo ya mũtu, na nthembo ya naĩ, na nthembo ya mavĩtyo; na kĩla kĩndũ kĩvathe nthĩnĩ wa Isilaeli kĩkethĩwa kyoo.'),
('kam', 'EZK', 44, 30, 'Na kĩla kya mbee kya mosyao onthe ma mbee ma kĩla kĩndũ, na kĩla nthembo ya kĩla kĩndũ, nthembonĩ syenyu syonthe, ikethĩwa sya mũthembi: o na mũkanenga athembi kĩla kya mbee kya mũtu wenyu, ũtume ũathimo wĩkala nyũmbanĩ yaku.'),
('kam', 'EZK', 44, 31, 'Athembi matikaya kĩndũ kya kũkw’a, kana kĩlĩku, ethĩwa nĩ nyũnyi kana nyamũ.'),
('kam', 'EZK', 45, 1, 'Na ĩngĩ, yĩla mũkaaan’ya kwondũ wa kũlimana nthĩ yĩthĩwe ũtiĩwa, mũkamũthembea Yeova nthembo, kĩlungu kĩtheu kya nthĩ; ũasa ũkethĩwa ũasa wa mĩangi ngili mĩongo ĩlĩ na ĩtano, na ũthanthau ũkethĩwa ngili ĩkũmi: kĩkethĩwa kĩtheu mũvakanĩ w’onthe wakyo ngalĩ syonthe.'),
('kam', 'EZK', 45, 2, 'Nthĩnĩ wakyo kwondũ wa vala vandũ vatheu kũkethĩwa ũasa wa maana atano na ũthanthau wa maana atano, yĩanene ngalĩ syonthe; na mĩkono mĩongo ĩtano kwondũ wa syengo syakyo ngalĩ syonthe.'),
('kam', 'EZK', 45, 3, 'Na kĩthimonĩ kyu ũkathima ũasa wa ngili mĩongo ĩlĩ na ĩtano, na ũthanthau wa ngili ĩkũmi: na nthĩnĩ wa vo kũkeethĩwa vala vandũ vatheu, vala vatheu mbee.'),
('kam', 'EZK', 45, 4, 'Nĩ kĩlungu kĩheu kya ĩ nthĩ; kĩkethĩwa kya athembi, athũkũmi ma vala vandũ vatheu, ala mathengeeaa mamũthũkũmae Yeova; na kĩkethĩwa vandũ va nyũmba syoo, na vandũ vatheu va vala vandũ vatheu.'),
('kam', 'EZK', 45, 5, 'Na ũasa wa ngili mĩongo ĩlĩ na itano, na ũthanthau wa ngili ĩkũmi, kĩkethĩwa kya Alivai, athũkũmi ma ĩ nyũmba, kĩkethĩwa ng’ũndũ kwoo, kwondũ wa tũsũmba mĩongo ĩlĩ.'),
('kam', 'EZK', 45, 6, 'Na mũkatila kĩlungu kya ndũa ũthanthau ngili itano, na ũasa ngili mĩongo ĩlĩ na itano, kĩvakanĩte na nthembo ya kĩla kĩlungu kĩtheu: kĩkethĩwa kya nyũmba yonthe ya Isilaeli.'),
('kam', 'EZK', 45, 7, 'Na kĩlungu o na kĩva kwondũ wa mũnene wĩ mbee ũsumbĩnĩ kĩkethĩwa ngalĩ ĩmwe na ngalĩ ĩla ĩngĩ ya ĩla nthembo ntheu na ya kĩla kĩlungu kya ndũa, mbee wa ĩla nthembo ntheu na mbee wa kĩla kĩlungu kya ndũa, ngalĩ ya ũthũĩlonĩ wa syũa, na ngalĩ ya wumĩlonĩ wa syũa; na ũasa wakyo wĩanene na kĩlungu kĩmwe, kuma mũvaka wa ngalĩ ya ũthũĩlonĩ wa syũa kũvika mũvaka wa ngalĩ ya wumĩlonĩ wa syũa.'),
('kam', 'EZK', 45, 8, 'Ĩ nthĩ ĩkethĩwa kwake ũtiĩwa nthĩnĩ wa Isilaeli: na anene makwa me mbee ũsumbĩnĩ matikathĩn’ya andũ makwa ĩngĩ; makanenga nyũmba ya Isilaeli ĩ nthĩ kwĩanana na mbaĩ syayo.'),
('kam', 'EZK', 45, 9, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ĩanĩwai nũu, inyw’ĩ anene me mbee ũsumbĩnĩ ma Isilaeli: vetai ũng’endu na kũtava mũtavo, noisila sila wa katĩ na mũlũngalu; vetai kwa andũ makwa kumĩthya kwenyu kwa vinya, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 45, 10, 'Ĩthĩwai na ithimi sya w’o, na eva ya w’o, na vathi ya w’o.'),
('kam', 'EZK', 45, 11, 'Eva na vathi ikeethĩwa ũndũ ũmwe, nĩ kana vathi ĩthĩwe ya kĩlungu kya ĩkũmi kya omeli, na eva kĩlungu kya ĩkũmi kya omeli: omeli ĩkeethĩwa ya kwĩananĩthya ithimo.'),
('kam', 'EZK', 45, 12, 'Na sekeli ĩkeethĩwa ngela mĩongo ĩlĩ; sekeli mĩongo ĩlĩ, sekeli mĩongo ĩlĩ na itano, sekeli ĩkũmi na itano, ikeethĩwa kĩthimi kyenyu kĩtawa mane.'),
('kam', 'EZK', 45, 13, 'Ĩno nĩyo nthembo ĩla mũkathemba: kĩlungu kya thanthatũ kya eva kumya kĩthiminĩ kya omeli ya nganũ; na mũkanengane kĩlungu kya thanthatũ kya eva ya omeli ya mbaale;'),
('kam', 'EZK', 45, 14, 'na kĩlungu kitw’e kya mauta, kya vathi ya mauta, kĩlungu kya ĩkũmi kya vathi kumya kĩthiminĩ kya kolo, nayo nĩ vathi ĩkũmi, o omeli (nũndũ vathi ĩkũmi nĩ omeli);'),
('kam', 'EZK', 45, 15, 'na katena kamwe ka ĩlondu ka ndĩthya, kumya vala ve maana elĩ, kuma isesinĩ sya Isilaeli syĩ manzĩ maingĩ; — kwondũ wa nthembo ya mũtu, na nthembo ya kũvĩvw’a, na nthembo sya mũuo, kwondũ wa kwĩw’anĩthw’a kwoo, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 45, 16, 'Andũ onthe ma ĩ nthĩ makanengane kwondũ w nthembo ĩsu kwondũ wa mũnene wĩ mbee ũsumbĩnĩ wa Isilaeli.'),
('kam', 'EZK', 45, 17, 'Na kĩkeethĩwa kĩanda kya mũnene ũsu kũnengane nthembo sya kũvĩvw’a, na nthembo sya mũtu, na nthembo sya kũnyuwa, mbokanĩ, na syathĩnĩ sya mĩtisonĩ ya myei, na masavatonĩ, mbokanĩ syonthe itw’ĩtwe sya nyũmba ya Isilaeli: akaseũvya nthembo ya naĩ, na nthembo ya mũtu, na nthembo ya kũvĩvw’a, na nthembo sya mũuo, syĩthĩwe nthembo ya wĩw’anĩthyo kwondũ wa nyũmba ya Isilaeli.'),
('kam', 'EZK', 45, 18, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Mwei wa mbee, mũthenya wa mbee wa mwei, ũkoosa kasalũ kate kĩema; na ũkathesya vala vandũ vatheu.'),
('kam', 'EZK', 45, 19, 'Na mũthembi akoosa nthakame ĩmwe ya nthembo ya naĩ, noivaka mĩtĩnĩ ĩla yĩ ndee sya mũomo, na ikotonĩ inya sya ũnyitĩku wa kĩthembeo, na mĩtĩnĩ yĩ ndee sya mbingĩlo ya nza ya nthĩnĩ.'),
('kam', 'EZK', 45, 20, 'Na now’o ũkeka mũthenya wa mũonza wa mwei kwondũ wa kĩla ũmwe ũla ũvĩtasya, na kwondũ wa ũla ũte na ũmanyi: ũu now’o mũkathemba nthembo ya wĩw’anĩthyo kwondũ wa ĩ nyũmba.'),
('kam', 'EZK', 45, 21, 'Mwei wa mbee, mũthenya wa ĩkũmi na ĩna wa mwei, mũkeethĩwa na vasaka, mboka ya mĩthenya mũonza; kĩmũtũ kĩte ĩlawa kĩkaĩwa.'),
('kam', 'EZK', 45, 22, 'Na mũthenya ũsu mũnene wĩ mbee ũsumbĩnĩ akaseũvya kwondũ wake mwene na kwondũ wa andũ onthe ma ĩ nthĩ kasalũ ka mũew’a kethĩwe nthembo ya naĩ.'),
('kam', 'EZK', 45, 23, 'Na mĩthenya ĩsu mũonza ya mboka akamũseũvĩsya Yeova nthembo ya kũvĩvw’a, tũsalũ mũonza twa mũew’a na ndũũme mũonza ite kĩema kĩla mũthenya mĩthenya ĩsu mũonza; na nthenge kĩla mũthenya yĩthĩwe nthembo ya naĩ.'),
('kam', 'EZK', 45, 24, 'Na akaseũvya nthembo ya mũtu, eva kwondũ wa kĩla kasalũ ka mũew’a, na eva kwondũ wa kĩla ndũũme, na ini ya mauta ũndũ wa kĩla eva.'),
('kam', 'EZK', 45, 25, 'Mwei wa mũonza, mũthenya wa ĩkũmi na ĩtano wa mwei, akeeka ũu mbokanĩ mĩthenya mũonza; kwĩanana na nthembo ya naĩ, kwĩanana na nthembo ya kũvĩvw’a, na kwĩanana na nthembo ya mũtu, na kwĩanana na mauta.'),
('kam', 'EZK', 46, 1, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Mbingĩlo ya nza ya nthĩnĩ ĩla yelekele wumĩlonĩ wa syũa ĩkavingwa mĩthenya thanthatũ ya kũtethya wĩa; ĩndĩ mũthenya wa savato ĩkavingũwa, na mũthenya wa mũtiso wa mwei ĩkavingũwa.'),
('kam', 'EZK', 46, 2, 'Na mũnene wĩ mbee ũsumbĩnĩ akalika na nzĩa ya valasya wa mbingĩlo yĩ ũtee, na akaũngama vakuvĩ na mũtĩ wĩ ũtee wa mbingĩlo; na athembi makaseũvya nthembo yake ya kũvĩvw’a na nthembo syake sya mũuo, na akathaithĩa mwalyonĩ wa mbingĩlo: na ĩndĩ akaumaala; ĩndĩ mbingĩlo ndĩkavingwa mũvaka wĩoo.'),
('kam', 'EZK', 46, 3, 'Na andũ ma ĩ nthĩ makathaithĩa mũomonĩ wa mbingĩlo ĩsu mbee wa Yeova mĩthenya ya masavato na ya mĩtĩso ya myei.'),
('kam', 'EZK', 46, 4, 'Na nthembo ya kũvĩv’wa ĩla mũnene wĩ mbee ũsumbĩnĩ ũkamũthembea Yeova ĩkeethĩwa tũtena thanthatũ twa malondu tũte kĩema na ndũũme ĩte kĩema mũthenya wa savato;'),
('kam', 'EZK', 46, 5, 'na nthembo ya mũtu ĩkeethĩwa eva kwondũ wa ĩla ndũũme, na nthembo ya mũtu kwondũ wa tũla tũtena twa ĩlondu o ũndũ ũtonya kũnengane, na ini ya mauta kwondũ wa kĩla eva.'),
('kam', 'EZK', 46, 6, 'Na mũthenya wa mũtiso wa mwei ĩkeethĩwa kasalũ kate kĩema, na tũtena thanthatũ twa malondu, na ndũũme; ikeethĩwa ite na kĩema:'),
('kam', 'EZK', 46, 7, 'na akaseũvya nthembo ya mũtu, eva kwondũ wa kala kasalũ, na eva kwondũ wa ĩla ndũũme, na kwondũ wa tũla tũtena twa malondu kwĩanana na ũndũ ũtonya, na ini ya mauta kwondũ wa kĩla eva.'),
('kam', 'EZK', 46, 8, 'Na yĩla mũnene wĩ mbee ũsumbĩnĩ ũkalika, akalika na nzĩa ya valasya wa mbingĩlo, na akaumaala na nzĩa yaw’o.'),
('kam', 'EZK', 46, 9, 'Ĩndĩ yĩla andũ ma ĩ nthĩ makoka mbee wa Yeova mbokanĩ itw’ĩtwe, ũla ũlikaa na nzĩa ya mbingĩlo ya ngalĩ ya ĩũlũ athaithe akaumaalĩla nzĩanĩ ya mbingĩlo yĩ ngalĩ ya ĩtheo; na ũla ũlikaa na nzĩa ya mbingĩlo yĩ ngalĩ ya ĩtheo akaumaalĩla nzĩanĩ ya mbingĩlo ya ngalĩ ya ĩũlũ; ndakasyokela nzĩanĩ ya mbingĩlo ĩla walikĩle, ĩndĩ akaumaala alũngalĩte.'),
('kam', 'EZK', 46, 10, 'Na mũnene wĩ mbee ũsumbĩnĩ, yĩla malikaa, akalikaa e katĩ woo; na yĩla maumaalaa, makaumaala vamwe.'),
('kam', 'EZK', 46, 11, 'Na mbokanĩ, na mbokanĩ ila itw’ĩtwe, nthembo ya mũtu ĩkeethĩwa eva kwondũ wa kasalũ ka mũew’a, na eva kwondũ wa ndũũme, na kwondũ wa tũla tũtena twa malondu o ũndũ ũtonya kũnengane, na ini ya mauta kwondũ wa kĩla eva.'),
('kam', 'EZK', 46, 12, 'Na yĩla mũnene wĩ mbee ũsumbĩnĩ ũkaseũvya nthembo ya kũthemba na ngoo ya kwenda, nthembo ya kũvĩvw’a kana nthembo sya mũuo syĩthĩwe nthembo ya kũmũthembea Yeova na ngoo ya kwenda, mũndũ ũmwe ũkamũvingũĩa mbingĩlo ĩla yelekele wumĩlonĩ wa syũa; na akaseũvya nthembo yake ya kũvĩvw’a na nthembo syake sya mũuo, o tondũ wĩkaa mũthenya wa savato: na ĩndĩ akaumaala; na ĩtina wa kumaala kwake ũmwe akavinga mbingĩlo.'),
('kam', 'EZK', 46, 13, 'Na ũkaseũvasya katena ka ĩlondu ka mwaka ũmwe kate kĩema kethĩwe nthembo ya kũvĩvw’a ya kũthembea Yeova kĩla mũthenya: kĩoko na kĩoko ũkamĩseũvasya.'),
('kam', 'EZK', 46, 14, 'Na ũkaseũvasya nthembo ya mũtu vamwe nayo kĩoko na kĩoko, kĩlungu kya thanthatũ kya eva, na kĩlungu kya katatũ kya ini ya mauta, ma kũvulan’ya na mũtu mũvinyu; nthembo ya mũtu ĩtatw’ĩkanaa ya kũmũthembea Yeova kwondũ wa ũtw’ĩo wa tene na tene.'),
('kam', 'EZK', 46, 15, 'Ũu nĩw’o makaseũvasya katena ka ĩlondu, na nthembo ya mũtu, na mauta, kĩoko na kĩoko, syĩthĩwe nthembo ya kũvĩvw’a ĩtatw’ĩkanaa.'),
('kam', 'EZK', 46, 16, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ethĩwa mũnene wĩ mbee ũsumbĩnĩ akanenga ũmwe o na wĩva wa ana make mũthĩnzĩo, nĩ ũtiĩwa wake, ũkeethĩwa wa ana make; nĩ ũtiĩwa woo wa kũtiĩwa.'),
('kam', 'EZK', 46, 17, 'Ĩndĩ ethĩwa akanenga ũmwe wa athũkũmi make mũthĩnzĩo kuma ũtiĩwanĩ wake, ũkeethĩwa wake kũvika mwaka wa ũthasyo; nĩvo ĩndĩ ũkamũsyokea ũla mũnene; ĩndĩ ũvoo wa ũtiĩwa wake, naw’o ũkeethĩwa wa ana make.'),
('kam', 'EZK', 46, 18, 'Na ĩngĩ mũnene wĩ mbee ũsumbĩnĩ ndakosa ũtiĩwa wa andũ, amaumya ũtiĩwanĩ woo; akanenga ana make ũtiĩwa kuma ũtiĩwanĩ wake mwene, nĩ kana andũ makwa matikanyaĩĩkw’e kĩla mũndũ kuma ũtiĩwanĩ wake.'),
('kam', 'EZK', 46, 19, 'Na ĩndĩ andikĩlya ũlikĩlonĩ, ũla waĩ ũtee wa mbingĩlo, andikya tũsũmbanĩ tũla tũtheu twa athembi, tũla twelekele ngalĩ ya ĩũlũ: na, sisya, kwaĩ vandũ kĩlungunĩ kĩ ĩtina ngalĩ ya ũthũĩlonĩ wa syũa.'),
('kam', 'EZK', 46, 20, 'Na ambĩa, Vaa nĩ vandũ vala athembi makauĩaa nthembo ya mavĩtyo na nthembo ya naĩ, na vala makakaangĩa nthembo ya mũtu; nĩ kana matikasyumaalye nza yĩ ũtee, mavathan’ye andũ methĩwe atheu.'),
('kam', 'EZK', 46, 21, 'Nĩvo ĩndĩ wanumaalilye nza yĩ ũtee, na ambĩtĩlya ikotonĩ inya sya nza; na, sisya, kĩla kĩkotonĩ kya nza kwaĩ nza.'),
('kam', 'EZK', 46, 22, 'Ikotonĩ inya sya nza kwaĩ nza mbiie, ũasa wa mĩkono mĩongo ĩna na ũthanthau mĩongo ĩtatũ: isu inya syĩ ikotonĩ syaĩ sya kĩthimi kĩmwe.'),
('kam', 'EZK', 46, 23, 'Na kwaĩ ũvai ũthyũlũlũkĩte nthĩnĩ wasyo, kũthyũlũlũka isu inya, na kũndũ kwa kũuĩa kwaseũvĩtw’e ungu wa maũvai ngalĩ syonthe.'),
('kam', 'EZK', 46, 24, 'Nĩvo ĩndĩ wambĩie, Ii nĩsyo nyũmba sya kũuĩa, vala athũkũmi ma ĩ nyũmba makauĩaa nthembo ya andũ.'),
('kam', 'EZK', 47, 1, 'Na andũngĩla mũomonĩ wa nyũmba; na, sisya, manzĩ mauma ungu wa mwalyo wa nyũmba melekele ngalĩ ya wumĩlonĩ wa syũa (nũndũ ngalĩ ya mbee ya nyũmba yelekele wumĩlonĩ wa syũa); na manzĩ matheeie kuma ungu, kuma ngalĩ ya kw’oko kwa aũme kwa nyũmba, ngalĩ ya ĩtheo ya kĩthembeo.'),
('kam', 'EZK', 47, 2, 'Na ĩndĩ anumaalilye na nzĩa ya mbingĩlo yelekele ngalĩ ya ĩũlũ, na andongoesya nzĩanĩ yĩ ũtee kũvika mbingĩlo ya nza, na nzĩa ya mbingĩlo ĩla yelekele wumĩlonĩ wa syũa; na, sisya, manzĩ maumĩte ngalĩ ya kw’oko kwa aũme.'),
('kam', 'EZK', 47, 3, 'Yĩla ũ mũndũ waumaalile elekele wumĩlonĩ wa syũa e na ũlii kw’okonĩ kwake, athima mĩkono ngili, na ambĩtĩlya manzĩnĩ, manzĩ ala mavikĩte ngũlimũ.'),
('kam', 'EZK', 47, 4, 'Ĩngĩ athima ngili, an ambĩtĩlya manzĩnĩ, manzĩ mavikĩte mau. Ĩngĩ athima ngili, na ambĩtĩlya manzĩnĩ, manzĩ mavikĩte kĩnyunyu.'),
('kam', 'EZK', 47, 5, 'Ĩtina athima ngili; na kwaĩ ũsĩ ũla ndaatonya kũkĩlĩkya; nũndũ manzĩ nĩmookĩlanasya, manzĩ ma kũthambĩĩla nthĩnĩ wamo, ũsĩ ũtatonya kũkĩlĩka.'),
('kam', 'EZK', 47, 6, 'Na ambĩa, Mwana wa mũndũ, nĩwonete ũu? Nĩvo ĩndĩ wandwaie, na andũnga ngũkanĩ ya ũsĩ.'),
('kam', 'EZK', 47, 7, 'Na yĩla navikĩte, sisya, ngũkanĩ ya ũsĩ kwaĩ mĩtĩ mingĩ mũno ngalĩ ĩmwe na ngalĩ ĩla ĩngĩ.'),
('kam', 'EZK', 47, 8, 'Nĩvo ĩndĩ wambĩie, Manzĩ aa maumĩte maendete nthĩ ya ngalĩ ya wumĩlonĩ wa syũa, na makatheea maende mwandanĩ wa Alava; na makaenda melekele ũkanga; manzĩ ala maumĩlĩtw’e makathi ũkanganĩ; na manzĩ makavow’a.'),
('kam', 'EZK', 47, 9, 'Na kũkeethĩwa, kana kĩla kyũmbe kĩ thayũ kĩla kingĩvĩte, kĩla vandũ vala mbũsĩ syũkaa, kĩkekala thayũ; na kũkeethĩwa wingĩ mũno wa makũyũ; nũndũ manzĩ asu mavikĩte, vo na manzĩ ma ũkanga makavow’a, na kĩla kĩndũ kĩkekala thayũ o vala ũsĩ wĩvika.'),
('kam', 'EZK', 47, 10, 'Na kũkeethĩwa, atei ma makũyũ makaũngama ũtee waw’o: kuma Eni‐ngeti o kũvika Eni‐ekilaimu kũkeethĩwa vandũ va kwalan’ya itei; makũyũ moo o mĩthemba yamo, ta makũyũ ma ũkanga mũnene, maingĩ mũno.'),
('kam', 'EZK', 47, 11, 'Ĩndĩ kũndũ kwaw’o kwĩ ndaka, na isoo syaw’o, kũtikavow’a; kũkeethĩwa kwa mũnyũ.'),
('kam', 'EZK', 47, 12, 'Na ũtee wa ũsĩ ngũkanĩ yaw’o, ngalĩ ĩno na ngalĩ ĩya, kũkamea kĩla mũtĩ kwondũ wa lĩu, ĩtu yaw’o yĩtikavova, o na ũsyao waw’o ndũkanyiva: ũkasyaa ũsyao mweũ kĩla mwei, nũndũ manzĩ maw’o maumaa vala vandũ vatheu; na ũsyao waw’o ũkeethĩwa wa kũĩwa, na ĩtu yaw’o ya kũvosya.'),
('kam', 'EZK', 47, 13, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ũũ ũkeethĩwa mũvaka, ũla mũkaan’ya nthĩ naw’o kwondũ wa ũtiĩwa kwĩanana na mbaĩ ĩkũmi na ilĩ sya Isilaeli: Yosevu akeethĩwa na ianda ilĩ.'),
('kam', 'EZK', 47, 14, 'Na mũkamĩtiĩwa, ũmwe ta ũla ũngĩ; nũndũ nĩnameavĩe aaĩthe menyu nĩmanenge: na nthĩ ĩno ĩkatw’ĩka yenyu yĩthĩwe ũtiĩwa.'),
('kam', 'EZK', 47, 15, 'Na ũũ ũkeethĩwa mũvaka wa ĩ nthĩ: Ngalĩ ya ĩũlũ, kuma ũkanga mũnene, kwa nzĩa ya kũthi Ethiloni, kũvika ũlikĩlonĩ wa Nzetati;'),
('kam', 'EZK', 47, 16, 'Amathi, Mbelotha, Sivilaimu, ĩla yĩ katĩ wa mũvaka wa Ndamasiku na mũvaka wa Amathi; Aseli‐atikoni, ĩla yĩ vakuvĩ na mũvaka wa Aulani.'),
('kam', 'EZK', 47, 17, 'Na mũvaka kuma ũkanganĩ, ũkeethĩwa Asali‐enani mũvakanĩ wa Ndamasiku; na ngalĩ ya ĩũlũ kwelekela ĩũlũ kwĩ mũvaka wa Amathi. Ĩsu nĩyo ngalĩ ya ĩũlũ.'),
('kam', 'EZK', 47, 18, 'Na ngalĩ ya wumĩlonĩ wa syũa, katĩ wa Aulani na Ndamasiku na Ngileati na nthĩ ya Isilaeli, kũkeethĩwa ũsĩ wa Yolotani; kuma mũvaka wa ngalĩ ya ĩũlũ, kũvika ũkanga wa ngalĩ ya wumĩlonĩ wa syũa mũkathima. Ĩsu nĩyo ngalĩ ya wumĩlonĩ wa syũa.'),
('kam', 'EZK', 47, 19, 'Na ngalĩ ya ĩtheo kwelekela ĩtheo ũkeethĩwa kuma Tamali kũvika manzĩ ma Meliva‐katesi, kũvĩka kalũsĩ ka Misili, o kũvika ũkanga mũnene. Ĩsu nĩyo ngalĩ ya ĩtheo kwelekela ĩtheo.'),
('kam', 'EZK', 47, 20, 'Na ngalĩ ya ũthũĩlonĩ wa syũa ũkeethĩwa ũkanganĩ mũnene, kuma mũvaka wa ngalĩ ya ĩtheo kũvika ũlikĩlonĩ wa Amathi. Ĩsu nĩyo ngalĩ ya ũthũĩlonĩ wa syũa.'),
('kam', 'EZK', 47, 21, 'Ũu nĩw’o mũkeaan’ya nthĩ ĩno kwĩanana na mbaĩ sya Isilaeli.'),
('kam', 'EZK', 47, 22, 'Na kũkeethĩwa, mũkamĩaan’ya na nzĩa ya kũlimana yĩthĩwe ũtiĩwa kwenyu na kwa aeni ala mekalaa ũeni kwenyu, ala makasyaa syana me katĩ wenyu; na makeethĩwa kwenyu ta ala masyaĩwe kwenyu katĩ wa ana ma Isilaeli; makeethĩwa na ũtiĩwa vamwe nenyu katĩ wa mbaĩ sya Isilaeli.'),
('kam', 'EZK', 47, 23, 'Na kũkeethĩwa, o mbaĩnĩ vala mũeni wĩkalaa ũeni, vo mũkamũnenga ũtiĩwa wake, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 48, 1, 'Aa nĩmo masyĩtwa ma i mbaĩ: Kuma mũthya wa ngalĩ ya ĩũlũ, ũtee wa nzĩa ya Ethiloni kũvika ũlikĩlonĩ wa Amathi, Asali‐enani mũvakanĩ wa Ndamasiku, kwelekela ngalĩ ya ĩũlũ vakuvĩ na Amathi (na makeethĩwa na ndee syoo ngalĩ ya wumĩlonĩ wa syũa na ngalĩ ya ũthũĩlonĩ wa syũa), Ndani, kĩanda kĩmwe.'),
('kam', 'EZK', 48, 2, 'Na ĩngĩ mũvakanĩ wa Ndani, kuma ngalĩ ya wumĩlonĩ wa syũa kũvika ngalĩ ya ũthũĩlonĩ wa syũa, Aseli, kĩanda kĩmwe.'),
('kam', 'EZK', 48, 3, 'Na mũvakanĩ wa Aseli, kuma ngalĩ ya wumĩlonĩ wa syũa o kũvika ngalĩ ya ũthũĩlonĩ wa syũa, Navitali, kĩanda kĩmwe.'),
('kam', 'EZK', 48, 4, 'Na mũvakanĩ wa Navitali, kuma ngalĩ ya wumĩlonĩ wa syũa kũvika ngalĩ ya ũthũĩlonĩ wa syũa, Manase, kĩanda kĩmwe.'),
('kam', 'EZK', 48, 5, 'Na mũvakanĩ wa Manase, kuma ngalĩ ya wumĩlonĩ wa syũa kũvika ngalĩ ya ũthũĩlonĩ wa syũa, Evalaimu, kĩanda kĩmwe.'),
('kam', 'EZK', 48, 6, 'Na mũvakanĩ wa Evalaimu, kuma ngalĩ ya wumĩlonĩ wa syũa kũvika ngalĩ ya ũthũĩlonĩ wa syũa, Leuveni, kĩanda kĩmwe.'),
('kam', 'EZK', 48, 7, 'Na ĩngĩ mũvakanĩ wa Leuveni, kuma ngalĩ ya wumĩlonĩ wa syũa kũvika ngalĩ ya ũthũĩlonĩ wa syũa, Yuta, kĩanda kĩmwe.'),
('kam', 'EZK', 48, 8, 'Na mũvakanĩ wa Yuta, kuma ngalĩ ya wumĩlonĩ wa syũa kũvika ngalĩ ya ũthũĩlonĩ wa syũa, kũkeethĩwa ĩla nthembo ya nthĩ ĩla mũkathemba, ũthanthau wa mĩangi ngili mĩongo ĩlĩ na itano, na ũasa ta kĩanda kĩmwe, kuma ngalĩ ya wumĩlonĩ wa syũa kũvika ngalĩ ya ũthũĩlonĩ wa syũa: na vala vandũ vatheu vakeethĩwa katĩ wakyo.'),
('kam', 'EZK', 48, 9, 'Nthembo ĩsu ĩla mũkamũthembea Yeova ĩkeethĩwa ũasa wa mĩangi ngili mĩongo ĩlĩ na itano, na ũthanthau wa ngili ĩkũmi.'),
('kam', 'EZK', 48, 10, 'Nthembo ĩsu ntheu ĩkeethĩwa kwondũ wa aa, o kwondũ wa athembi; kwelekela ngalĩ ya ĩũlũ ũasa wa ngili mĩongo ĩlĩ na itano, na kwelekela ngalĩ ya ũthũĩlonĩ wa syũa ũthanthau wa ngili ĩkũmi, na kwelekela ngalĩ ya wumĩlonĩ wa syũa ũthanthau wa ngili ĩkũmi, na kwelekela ngalĩ ya ĩtheo ũasa wa ngili mĩongo ĩli na itano: na vala vandũ vatheu va Yeova vakeethĩwa katĩ wakyo.'),
('kam', 'EZK', 48, 11, 'Kĩkeethĩwa kya athembi ala mavathĩtwe methĩwe atheu ma ana ma Nzatoki, ala masũvĩaa wĩaĩo wakwa, ala mataandia yĩla ana ma Isilaeli mandiĩte, o tondũ Alivai mandiie.'),
('kam', 'EZK', 48, 12, 'Na kĩkeethĩwa kwoo nthembo kuma nthembonĩ ya nthĩ, kĩndũ kĩtheu ki, mũvakanĩ wa Alivai.'),
('kam', 'EZK', 48, 13, 'Na kwĩanana na mũvaka wa athembi, Alivai makeethĩwa na kĩanda ũasa wa ngili mĩongo ĩlĩ na itano, na ũthanthau wa ngili ĩkũmi: ũasa w’onthe ũkeethĩwa ngili mĩongo ĩlĩ na itano, na ũthanthau ngili ĩkũmi.'),
('kam', 'EZK', 48, 14, 'Na matikathoosya kĩlungu kyakyo, kana kũkũan’ya, o na mosyao ma mbee ma nthĩ matikekwa ũndũ ũngĩ; nũndũ nĩ ntheu kwa Yeova.'),
('kam', 'EZK', 48, 15, 'Na ngili itano ila itialĩte sya ũthanthau, mbee wa ila ngili mĩongo ĩlĩ na itano, ikeethĩwa sya kũtethya onthe, kwondũ wa ndũa, kwondũ wa kũtũaa na kwondũ wa isesi; na ndũa ĩkeethĩwa vu katĩ.'),
('kam', 'EZK', 48, 16, 'Na ii ikeethĩwa ithimo sya vo: ngalĩ ya ĩũlũ ngili inya na maana atano, na ngalĩ ya ĩtheo ngili inya na maana atano, na ngalĩ ya wumĩlonĩ wa syũa ngili inya na maana atano, na ngalĩ ya ũthũĩlonĩ wa syũa ngili inya na maana atano.'),
('kam', 'EZK', 48, 17, 'Na ndũa ĩkeethĩwa na syengo: kwelekela ngalĩ ya ĩũlũ maana elĩ na mĩongo ĩtano, na kwelekela ngalĩ ya ĩtheo maana elĩ na mĩongo ĩtano, na kwelekela ngalĩ ya wumĩlonĩ wa syũa maana elĩ na mĩongo ĩtano, na kwelekela ngalĩ ya ũthũĩlonĩ wa syũa maana elĩ na mĩongo ĩtano.'),
('kam', 'EZK', 48, 18, 'Ũtialo wa ũasa, kwĩanana na ĩla nthembo ntheu, ũkeethĩwa ngili ĩkũmi kwelekela ngalĩ ya wumĩlonĩ wa syũa, na ngili ĩkũmi kwelekela ngalĩ ya ũthũĩlonĩ wa syũa; kwĩanana na ĩla nthembo ntheu; na wingĩvonĩ wa ũsyao waw’o kũkeethĩwa lĩu wa ala matethasya wĩa ndũanĩ.'),
('kam', 'EZK', 48, 19, 'Na ala matethasya wĩa ndũanĩ, kuma mbaĩnĩ syonthe sya Isilaeli, makamĩĩmaa.'),
('kam', 'EZK', 48, 20, 'Nthembo ĩsu yonthe ya nthĩ ĩkeethĩwa ngili mĩongo ĩlĩ na itano kwa ngili mĩongo ĩlĩ na itano: mũkathemba nthembo ntheu yĩanene ngalĩ inya, vamwe na kĩlungu kya ndũa.'),
('kam', 'EZK', 48, 21, 'Na ĩla ĩkatiala ĩkeethĩwa ya ũla mũnene wĩ mbee ũsumbĩnĩ, ngalĩ ĩmwe na ngalĩ ĩla ĩngĩ ya ĩla nthembo ntheu na kĩlungu kya ndũa; ngalĩ ya mbee ya ila ngili mĩongo ĩlĩ na itano ya ĩla nthembo kwelekela mũvaka wa ngalĩ ya wumĩlonĩ wa syũa, na kwelekela ngalĩ ya ũthũĩlonĩ wa syũa ngalĩ ya mbee ya ila ngili mĩongo ĩlĩ na itano kwelekela mũvaka wa ngalĩ ya ũthũĩlonĩ wa syũa, kwĩanana na ila ianda, vakeethĩwa va mũnene wĩ mbee ũsumbĩnĩ: na nthembo ntheu na vandũ vatheu va nyũmba vakeethĩwa vu katĩ.'),
('kam', 'EZK', 48, 22, 'Na ĩngĩ kuma ng’ũndũnĩ ya Alivai, na kuma kĩlungunĩ kya ndũa, nũndũ kĩ katĩ wa kĩla kya ũla mũnene wĩ mbee ũsumbĩnĩ, katĩ wa mũvaka wa Yuta na mũvaka wa Mbenyamini, kũkeethĩwa kya ũla mũnene.'),
('kam', 'EZK', 48, 23, 'Na ũndũ wa mbaĩ ila ingĩ: kuma ngalĩ ya wumĩlonĩ wa syũa kũvika ngalĩ ya ũthũĩlonĩ wa syũa, Mbenyamini, kĩanda kĩmwe.'),
('kam', 'EZK', 48, 24, 'Na ĩngĩ mũvakanĩ wa Mbenyamini, kuma ngalĩ ya wumĩlonĩ wa syũa kũvika ngalĩ ya ũthũĩlonĩ wa syũa, Simeoni, kĩanda kĩmwe.'),
('kam', 'EZK', 48, 25, 'Na ĩngĩ mũvakanĩ wa Simeoni, kuma ngalĩ ya wumĩlonĩ wa syũa kũvika ngalĩ ya ũthũĩlonĩ wa syũa, Isakali, kĩanda kĩmwe.'),
('kam', 'EZK', 48, 26, 'Na ĩngĩ mũvakanĩ wa Isakali, kuma ngalĩ ya wumĩlonĩ wa syũa kũvika ngalĩ ya ũthũĩlonĩ wa syũa, Nzevuluni, kĩanda kĩmwe.'),
('kam', 'EZK', 48, 27, 'Na ĩngĩ mũvakanĩ wa Nzevuluni, kuma ngalĩ ya wumĩlonĩ wa syũa kũvika ngalĩ ya ũthũĩlonĩ wa syũa, Ngati, kĩanda kĩmwe.'),
('kam', 'EZK', 48, 28, 'Na ĩngĩ mũvakanĩ wa Ngati, ngalĩ ya ĩtheo kwelekela ĩtheo, mũvaka ũkeethĩwa kuma Tamali kũvika manzĩ ma Meliva‐katesi, kũvika kalũsĩ ka Misili, kũvika ũkanga mũnene.'),
('kam', 'EZK', 48, 29, 'Ĩsu nĩyo nthĩ ĩla mwĩaan’ya mbaĩnĩ sya Isilaeli na nzĩa ya kũlimana yĩthĩwe ũtiĩwa, na isu nĩsyo ianda syasyo, easya ũu Mwĩaĩi Yeova.'),
('kam', 'EZK', 48, 30, 'Na aa nĩmo mawumaalĩlo ma ndũa: Ngalĩ ya ĩũlũ mĩangi ngili inya na maana atano kwa kũthima;'),
('kam', 'EZK', 48, 31, 'na mbingĩlo sya ndũa ikeetanĩaw’a na masyĩtwa ma mbaĩ sya Isilaeli, mbingĩlo itatũ ngalĩ ya ĩũlũ: mbingĩlo ya Leuveni, ĩmwe; mbingĩlo ya Yuta, ĩmwe; mbingĩlo ya Livai, ĩmwe.'),
('kam', 'EZK', 48, 32, 'Na ngalĩ ya wumĩlonĩ wa syũa mĩangi ngili inya na maana atano, na mbingĩlo itatũ: o mbingĩlo ya Yosevu, ĩmwe; mbingĩlo ya Mbenyamini, ĩmwe; mbingĩlo ya Ndani, ĩmwe.'),
('kam', 'EZK', 48, 33, 'Na ngalĩ ya ĩtheo mĩangi ngili inya na maana atano kwa kũthima, na mbingĩlo itatũ: mbingĩlo ya Simeoni, ĩmwe; mbingĩlo ya Isakali, ĩmwe; mbingĩlo ya Nzevuluni, ĩmwe.'),
('kam', 'EZK', 48, 34, 'Ngalĩ ya ũthũĩlonĩ wa syũa, mĩangi ngili inya na maana atano, vamwe na mbingĩlo itatũ syoo: mbingĩlo ya Ngati, ĩmwe; mbingĩlo ya Aseli, ĩmwe: mbingĩlo ya Navitali, ĩmwe.'),
('kam', 'EZK', 48, 35, 'Ĩkeethĩwa mĩangi ngili ĩkũmi na nyanya kũthyũlũlũka ngalĩ syonthe: na syĩtwa ya ndũa kuma mũthenya ũsu yĩkeethĩwa, Yeova e vo.'),
('kam', 'DAN', 1, 1, 'Mwaka wa katatũ wa kũsumbĩka kwa Yeoiakimu mũsumbĩ wa Yuta, Nevukatilesa mũsumbĩ wa Mbaviloni nĩwokie Yelusaleme, na amĩthyũlũlũka amĩtw’ĩkanĩsya.'),
('kam', 'DAN', 1, 2, 'Na Mwĩaĩi anengane Yeoiakimu mũsumbĩ wa Yuta kw’okonĩ kwake, vamwe na kĩlungu kya mĩio ya nyũmba ya Ngai; nake amĩtwaa nthĩ ya Sinali nyũmbanĩ ya ngai yake: na aete mĩio nyũmbanĩ ya kwia ũthwii ya ngai yake.'),
('kam', 'DAN', 1, 3, 'Na mũsumbĩ amwĩa Asivenasi vwana wa avakũe make, aete ana amwe ma Isilaeli, o ma nzyawa sya kĩũsumbĩ na ma ala anene me ndaĩa;'),
('kam', 'DAN', 1, 4, 'imwana ila ite kĩema, ĩndĩ syĩthĩwe na wũmbe mũseo, na ũtũĩka uĩnĩ w’onthe, syĩ na ũmanyi, na kũmanya ũĩ wa wĩmanyĩso, na ila itonya kũũngama nyũmbanĩ nene mbanakavye ya mũsumbĩ; na aimanyĩsye momanyĩsyo na kĩthyomo kya Akalitei.'),
('kam', 'DAN', 1, 5, 'Na mũsumbĩ aitw’ĩa lĩu wa kĩla mũthenya wa kya ũya kĩseo kya mũsumbĩ, na mbinyu ĩla wanyusaa we mwene, iĩthw’e myaka ĩtatũ; nĩ kana mũminũkĩlyo wayo iũngame mbee wa mũsumbĩ.'),
('kam', 'DAN', 1, 6, 'Na ĩndĩ katĩ wa ii nĩvo syaĩ, sya ana ma Yuta, Ndanieli, na Aanania, na Misaeli, na Asalia.'),
('kam', 'DAN', 1, 7, 'Nake mũnene wa avakũe aitw’ĩĩa masyĩtwa: Ndanieli amwĩta syĩtwa yake Mbelitesasa; na Aanania, Satalaki; na Misaeli, Mesaki; na Asalia, Aveti‐neko.'),
('kam', 'DAN', 1, 8, 'Ĩndĩ Ndanieli nĩwetw’ĩĩe ngoonĩ yake kana ndakevukya na kĩla kya ũya kĩseo kya mũsumbĩ, kana na ĩla mbinyu ũnyusaa: kwondũ wa ũu avoya ũla mũnene wa avakũe ndakevukye.'),
('kam', 'DAN', 1, 9, 'Na ĩndĩ Ngai anenga Ndanieli kwona ũseo na ĩnee kwa mũnene wa avakũe.'),
('kam', 'DAN', 1, 10, 'Na mũnene wa avakũe amwĩa Ndanieli, Nĩngũkĩa mwĩaĩi wakwa mũsumbĩ, ũla wamũtw’ĩe lĩu wenyu na kya ũnyw’a kyenyu: nũndũ nĩkĩ wĩona mothyũ menyu mate maseo ta mothyũ ma imwana sya nthuke ĩmwe nenyu? Nĩvo mwĩĩkĩa mũtwe wakwa mũisyonĩ vala ve mũsumbĩ.'),
('kam', 'DAN', 1, 11, 'Na ĩndĩ Ndanieli amwĩa mũsyaĩĩsya ũla waiĩtwe nĩ mũnene wa avakũe ĩũlũ wa Ndanieli, na Aanania, na Misaeli, na Asalia:'),
('kam', 'DAN', 1, 12, 'Nĩngũkwĩsũva, tũtate ithyĩ athũkũmi maku matukũ ĩkũmi; na nĩmatũnenge isyo sya kũya, na manzĩ ma ũnyw’a.'),
('kam', 'DAN', 1, 13, 'Nĩvo ĩndĩ mothyũ maitũ mesyaĩw’a mbee waku, na mothyũ ma imwana ila iĩsaa kyaũya kĩseo kya mũsumbĩ; naku o ũndũ wĩona, wĩĩka athũkũmi maku ũu.'),
('kam', 'DAN', 1, 14, 'Na ĩndĩ asyĩthukĩĩsya ũndũnĩ ũsu, na aitata matukũ ĩkũmi.'),
('kam', 'DAN', 1, 15, 'Na mũminũkĩlyo wa matukũ ĩkũmi mothyũ moo mooneka me maseo, na maĩ anou, kwĩ imwana syonthe ila syaĩsaa kya ũya kĩseo kya mũsumbĩ.'),
('kam', 'DAN', 1, 16, 'Kwondũ wa ũu mũsyaĩĩsya aveta kya ũya kyoo kĩseo, na mbinyu ya ũnyuwa, na ainenga isyo.'),
('kam', 'DAN', 1, 17, 'Na ĩndĩ imwana isu inya, Ngai ainenga ũmanyi na ũtũĩka ũmanyĩsyonĩ w’onthe na ũĩnĩ: na Ndanieli aĩ na ũmanyi wa mawoni onthe na ndoto.'),
('kam', 'DAN', 1, 18, 'Na mũminũkĩlyo wa matukũ ala mũsumbĩ watwie ma kwiete, mũnene wa avakũe aiete vala ve Nevukatilesa.'),
('kam', 'DAN', 1, 19, 'Na mũsumbĩ aneenan’ya nasyo; na katĩ wa isu syonthe vaiaaoneka ingĩ itilyĩ ta Ndanieli, na Aanania, na Misaeli, na Asalia: na kwondũ wa ũu syaũngama mbee wa mũsumbĩ.'),
('kam', 'DAN', 1, 20, 'Na maũndũnĩ onthe ma ũĩ na ũmanyi, ala mũsumbĩ waikũlilye, asyona ivĩtũkĩte kũndũ ĩkũmi eki ma syama na awe onthe, ala maĩ ũsumbĩnĩ wake w’onthe.'),
('kam', 'DAN', 1, 21, 'Na Ndanieli ekala kũvika mwaka wa mbee wa kũsumbĩka kwa mũsumbĩ Kulusi.'),
('kam', 'DAN', 2, 1, 'Na mwaka wa kelĩ wa kũsumbĩka kwa Nevukatilesa, Nevukatilesa nĩwaotie ndoto; na veva wake waũũya, na too wake wamwaĩa.'),
('kam', 'DAN', 2, 2, 'Nĩvo ĩndĩ mũsumbĩ weaie metwe eki ma syama, na awe, na aoi, na Akalitei, mon’ye mũsumbĩ ndoto syake. Na ĩndĩ mooka na maũngama mbee wa mũsumbĩ.'),
('kam', 'DAN', 2, 3, 'Na mũsumbĩ amea, Nĩnĩotie ndoto, na veva wakwa nũkũũũya nĩ kana nĩmanye ĩ ndoto.'),
('kam', 'DAN', 2, 4, 'Nĩvo ĩndĩ Akalitei matavisye mũsumbĩ na kĩthyomo kya Asilia, We mũsumbĩ, ĩkala tene na tene: tavya athũkũmi maku ĩ ndoto, naitũ nĩtũkwonan’ya ũalyũlo wayo.'),
('kam', 'DAN', 2, 5, 'Mũsumbĩ asũngĩa na amea Akalitei, Ũndũ ũsu nũkũmbaĩa: ethĩwa mũiũmanyĩthya ĩ ndoto na ũlayũlo wayo, mũkatilangwa ilungu, na nyũmba syenyu ikatw’ĩka maũtũnda ma syaa.'),
('kam', 'DAN', 2, 6, 'Ĩndĩ ethĩwa nĩmũkwonan’ya ĩ ndoto na ũalyũlo wayo, mũkanengwa ninyie mĩthĩnzĩo na matuvi na ndaĩa nene: kwondũ wa ũu mbon’yai ndoto na ũalyũlo wayo.'),
('kam', 'DAN', 2, 7, 'Masũngĩa ĩngĩ ya kelĩ na mamwĩa, Mũsumbĩ natũtavye ithyĩ athũkũmi make ĩ ndoto, naitũ nĩtũkwonan’ya ũalyũlo wayo.'),
('kam', 'DAN', 2, 8, 'Mũsumbĩ asũngĩa na amea, Nĩnĩsĩ vyũ nĩmũkwenda kũasavya ĩvinda, nũndũ nĩmũkwona ũndũ ũsu nũkũmbaĩa.'),
('kam', 'DAN', 2, 9, 'Ĩndĩ ethĩwa mũikũmanyĩthya ĩ ndoto, ve mwĩao ũmwe kwenyu tũ; nũndũ nĩmwĩyiĩe ndeto sya ũvũngũ na nthũku sya kũneena vala nĩĩ, kũvika ĩvinda yĩalyũlwe: kwondũ wa ũu ndavyai ĩ ndoto, nakwa nĩngũmanya kana nĩmũtonya kũmbon’ya ũalyũlo wayo.'),
('kam', 'DAN', 2, 10, 'Akalitei masũngĩa vala ve mũsumbĩ, na mamwĩa, Kũti mũndũ ĩũlũ wa nthĩ ũtonya kwonan’ya ũndũ ũsu wa mũsumbĩ, nũndũ kũti mũsumbĩ, o na mwĩaĩi, o na mũsumbĩki, waakũlya ũndũ ta ũsu kwa mwĩki wa syama, kana kwa mũndũ mũe, kana kwa Mũkalitei.'),
('kam', 'DAN', 2, 11, 'Na ũndũ ũsu wĩ vinya ũla mũsumbĩ ũnũkwenda, o na kũti ũngĩ ũtonya kũwonan’ya vala ve mũsumbĩ, ate o ngai, ila itekalaa na mwĩĩ.'),
('kam', 'DAN', 2, 12, 'Kwondũ wa ũu mũsumbĩ athata na aĩ na ũthatu mwai mũno, na eeaa andũ oĩ onthe ma Mbaviloni manangwe.'),
('kam', 'DAN', 2, 13, 'Na ĩndĩ ũtw’ĩo waumw’a, andũ oĩ moawe; na mamantha Ndanieli na atindan’ya make moawe.'),
('kam', 'DAN', 2, 14, 'Nĩvo ĩndĩ Ndanieli ũndũ wa kũsũanĩa na ũndũ wa kĩlĩko wasũngĩie Alioko kavuteni wa nguthu ya asũvĩi ma mũsumbĩ, ũla waĩ anaumaala oae andũ oĩ ma Mbaviloni:'),
('kam', 'DAN', 2, 15, 'asũngĩa na amwĩa Alioko kavuteni wa kwa mũsumbĩ, Nũndũ wa kĩ ũtw’ĩo waumw’a kwa mũsumbĩ na mĩtũkĩ ĩana ũu? Na ĩndĩ Alioko amanyĩthya Ndanieli ũla ũndũ.'),
('kam', 'DAN', 2, 16, 'Na Ndanieli avota, na enda mũsumbĩ amũnenge ũthei, nake akamanyĩthya mũsumbĩ ũalyũlo.'),
('kam', 'DAN', 2, 17, 'Nĩvo ĩndĩ Ndanieli waendie nyũmbanĩ kwake, na amanyĩthya Aanania, na Misaeli, na Asalia, atindan’ya make ũndũ ũsu:'),
('kam', 'DAN', 2, 18, 'nĩ kana metye matei kwa Ngai wa ĩtunĩ ũndũnĩ ũũ ũvithe; nĩ kana Ndanieli na atindan’ya make maikoawe vamwe na andũ oĩ angĩ ma Mbaviloni.'),
('kam', 'DAN', 2, 19, 'Nĩvo ĩndĩ ũndũ ũsu ũvithe wavuanĩw’e Ndanieli woninĩ wa ũtukũ. Na ĩndĩ Ndanieli ataĩa Ngai wa ĩtunĩ.'),
('kam', 'DAN', 2, 20, 'Ndanieli asũngĩa na asya, Syĩtwa ya Ngai yĩtaĩwe tene na tene; nũndũ ũĩ na vinya nĩ syake.'),
('kam', 'DAN', 2, 21, 'Nake nũalyũlaa mavinda na syathĩ; nũvetaa asumbĩ, na nĩwũkĩlasya asumbĩ; nũnengae ala oĩ ũĩ, na ũmanyi ala mekũmanya;'),
('kam', 'DAN', 2, 22, 'nũvuanasya maũndũ maliku na mavithe; nĩwĩsĩ ala me kĩvindunĩ, na kyeni nĩkĩkalaa nake.'),
('kam', 'DAN', 2, 23, 'Nĩngũũtũngĩa mũvea, na ũkũtaĩa, ame Ngai wa aasa makwa, nũndũ nũnengete ũĩ na vinya, na nĩwamanyĩthya oyu ũla tũkwendaa kwaku; nũndũ nĩwatũmanyĩthya ũla ũndũ wa mũsumbĩ.'),
('kam', 'DAN', 2, 24, 'Kwondũ wa ũu Ndanieli aenda kwa Alioko, ũla mũsumbĩ wamwiĩte anange andũ oĩ ma Mbaviloni; aenda na amwĩa atĩĩ: Ndũkanange andũ oĩ ma Mbaviloni; ũndwae vala ve mũsumbĩ, nakwa nĩngwon’ya mũsumbĩ ũalyũlo.'),
('kam', 'DAN', 2, 25, 'Nĩvo ĩndĩ Alioko wamũtwaie Ndanieli vala ve mũsumbĩ na mĩtũkĩ, na amwĩa atĩĩ, Nĩnoona mũndũ wa ana ma kũtavwa ma Yuta, ũla ũkũmanyĩthya mũsumbĩ ũalyũlo.'),
('kam', 'DAN', 2, 26, 'Mũsumbĩ asũngĩa na akũlya Ndanieli, ũla wetawa syĩtwa yake Mbelitesasa, Nũtonya kũmanyĩthya ndoto ĩla nĩnoonie, na ũalyũlo wayo?'),
('kam', 'DAN', 2, 27, 'Ndanieli asũngĩa vala ve mũsumbĩ, na amwĩa, Ũndũ ũvithe ũla mũsumbĩ ũkũlĩtye, andũ oĩ, o na awe, o na eki ma syama, o na ala mathanaa maũndũ, maitonya kwon’ya mũsumbĩ;'),
('kam', 'DAN', 2, 28, 'ĩndĩ ĩtunĩ ve Ngai ũvuanasya maũndũ mavithe, nake nũmanyĩthĩtye mũsumbĩ Nevukatilesa ũla ũkethĩwa mĩthenya ya mũminũkĩlyo. Ndoto yaku, na mawoni ma mũtwe waku wĩ ũkomonĩ waku, nĩmo aa:'),
('kam', 'DAN', 2, 29, 'ũndũ waku, we mũsumbĩ, malilikano maku manakũkĩe ũkomonĩ waku, ũndũ kũkethĩwa ĩtina, na ũla ũvuanasya maũndũ mavithe nũkũmanyĩthĩtye maũndũ ala makethĩwa.'),
('kam', 'DAN', 2, 30, 'Ĩndĩ ũndũ wakwa, ũndũ ũũ ũvithe ndũnavuanw’a kwakwa ũndũ wa kwĩthĩwa na ũĩ kwĩ ũngĩ wĩ thayũ, ĩndĩ nĩ kana mũsumbĩ amanyĩthw’e ũalyũlo, na nĩ kana ũmanye malilikano ma ngoo yaku.'),
('kam', 'DAN', 2, 31, 'Naku, we mũsumbĩ, nũnoonie, na sisya, mũvw’anano mũnene. Mũvw’anano ũsu, ũla ũnaĩ mũnene mũno, na kũtisa kwaw’o kũnaĩ kũseo mũno, ũnaĩ ũũngamĩte mbee waku; na kwoneka kwaw’o kũnaĩ kwa kũtĩsya.'),
('kam', 'DAN', 2, 32, 'Na ũndũ wa mũvw’anano ũsu, mũtwe waw’o ũnaĩ wa thaavu mũtheu, na kĩthũi kyaw’o na moko maw’o manaĩ ma vetha, na ĩvu yaw’o na mawaswa maw’o manaĩ ma ũthuku,'),
('kam', 'DAN', 2, 33, 'na maũũ maw’o manaĩ ma kĩaa, na nyaĩĩ syaw’o inaĩ nyunzu ya kĩaa, na nyunzu ya yũmba.'),
('kam', 'DAN', 2, 34, 'Naku woona mũvaka ĩvia yatilĩka vate moko, yĩla yĩnakũnie mũvw’anano nyaĩĩnĩ syaw’o ila sya kĩaa na yũmba, na yaitilanga ilungu.'),
('kam', 'DAN', 2, 35, 'Nĩvo ĩndĩ kĩaa, na yũmba, na ũthuku, na vetha, na thaavu, inatilanganilw’e ilungu vamwe, na syekala ta wewa wa ivũĩo sya ĩvinda ya syũa; na kĩseve kyaũlũkya, na vaineeoneka vandũ vasyo: na ĩvia yĩla yĩnakũnie mũvw’anano yatw’ĩka kĩĩma kĩnene, yausũa nthĩ yonthe.'),
('kam', 'DAN', 2, 36, 'Ĩsu nĩyo ndoto; na ithyĩ nĩtũũneena ũalyũlo wayo vala ve mũsumbĩ.'),
('kam', 'DAN', 2, 37, 'Naku, we mũsumbĩ, wĩ mũsumbĩ wa asumbĩ, ũla Ngai wa ĩtunĩ ũkũnengete ũsumbĩ, na ũtonyi, na vinya, na ndaĩa;'),
('kam', 'DAN', 2, 38, 'na kw’onthe o kũla kwĩkalaa ana ma andũ, nyamũ sya kĩtheka na nyũnyi sya yayaya nũnenganĩte kw’okonĩ kwaku, na nũkũsumbĩkĩthĩtye ĩũlũ wasyo syonthe: nue mũtwe ũsu wa thaavu.'),
('kam', 'DAN', 2, 39, 'Na ĩtina waku vakookĩla ũsumbĩ ũngĩ mũnyivu kwĩ we; na ũsumbĩ ũngĩ wa katatũ wa ũthuku, ũla ũkasumbĩka nthĩ yonthe.'),
('kam', 'DAN', 2, 40, 'Na ũsumbĩ wa kana ũkeethĩwa na vinya ta kĩaa, o tondũ kĩaa kĩtilangaa ilungu na kũkĩlya syĩndũ syonthe vinya; na ta kĩaa kĩla kĩkanyangaa ii syonthe, ũkatilanga na kũkanyanga.'),
('kam', 'DAN', 2, 41, 'Na o tondũ ũnoonie nyaĩĩ na syaa, nyunzu ya yũmba ya mũmbi, na nyunzu ya kĩaa, ũsumbĩ ũkaolekangana; ĩndĩ nthĩnĩ waw’o vakeethĩwa vinya wa kĩaa, o tondũ ũnoonie kĩaa kĩvulanĩte na yũmba yulue.'),
('kam', 'DAN', 2, 42, 'Na o ũndũ syaa sya nyaĩĩ inaĩ nyunzu kĩaa, na nyunzu yũmba, ũsumbĩ ũkeethĩwa nyunzu wĩ na vinya, na nyunzu mũtilĩkanganu o ta ũu.'),
('kam', 'DAN', 2, 43, 'Na o tondũ ũnoonie kĩaa kĩvulanĩtw’e na yũmba yulue, makeevulan’ya na ũsyao wa andũ; ĩndĩ maikalũman’ya ene kwa ene, o tondũ kĩaa kĩivulanaa na yũmba.'),
('kam', 'DAN', 2, 44, 'Na mĩthenya ya asumbĩ asu Ngai wa ĩtunĩ akaũngamya ũsumbĩ ũtakaanangĩka tene na tene, o na ũsumbĩki waw’o ndũkaatiĩwa ũko ũngĩ wa andũ; ĩndĩ ũkatilanga ilungu na kũmina mosumbĩ asu onthe, naw’o ũkekalaa tene na tene.'),
('kam', 'DAN', 2, 45, 'O tondũ ũnoonie ĩvia yatilĩka kĩĩmanĩ vate moko, na yatilanga ilungu kĩaa, na ũthuku, na yũmba, na vetha, na thaavu; Ngai ũla mũnene nũmanyĩthĩtye mũsumbĩ ũla ũkethĩwa ĩtina: na ndoto nĩ ya w’o, na ũalyũlo wayo nĩ wa kũĩkĩĩwa.'),
('kam', 'DAN', 2, 46, 'Nĩvo ĩndĩ mũsumbĩ Nevukatilesa wavalũkile nthĩ na ũthyũ wake, na athaitha Ndanieli, na eeaa mamũthembee nthembo na kĩla kĩnyungaa nesa.'),
('kam', 'DAN', 2, 47, 'Mũsumbĩ asũngĩa Ndanieli, na amwĩa, Nĩ w’o, Ngai wenyu nĩ Ngai wa ngai, na Mwĩaĩi wa asumbĩ, na mũvuan’ya wa maũndũ mavithe, nũndũ nĩwatonya kũvuan’ya ũndũ ũũ ũvithe.'),
('kam', 'DAN', 2, 48, 'Na ĩndĩ mũsumbĩ anenevya Ndanieli, na amũnenga mĩthĩnzĩo mingĩ mĩnene, na amũtw’a mũnene ĩũlũ wa kĩlungu kĩnene kyonthe kya nthĩ kĩtawa Mbaviloni, na ngavana wa mbee ĩũlũ wa andũ oĩ onthe ma Mbaviloni.'),
('kam', 'DAN', 2, 49, 'Na Ndanieli avoya mũsumbĩ, na aia Satalaki, na Mesaki, na Aveti‐neko ĩũlũ wa maũndũ ma kĩlungu kyu kĩnene kya nthĩ kĩtawa Mbaviloni: ĩndĩ Ndanieli ekalaa mbingĩlonĩ ya kwa mũsumbĩ.'),
('kam', 'DAN', 3, 1, 'Mũsumbĩ Nevukatilesa aseũvĩthya mũvw’anano wa thaavu, ũtũlu waw’o waĩ wa mĩkono mĩongo thanthatũ, na ũthanthau waw’o mĩkono thanthatũ: awũũngamya ũiĩnĩ wa Ndula, kĩlungunĩ kĩnene kya nthĩ kĩtawa Mbaviloni.'),
('kam', 'DAN', 3, 2, 'Na ĩndĩ mũsumbĩ Nevukatilesa atũmana kũmbanw’e asumbĩ anini, na amũli, na makavana, na asili, na asũvĩi ma ũthwii, na atai, na asilan’ya, na asumbĩki onthe ma ilungu isu nene sya nthĩ, moke kwambĩlĩya ũthaithi wa mũvw’anano ũla mũsumbĩ Nevukatilesa waĩ anaũngamya.'),
('kam', 'DAN', 3, 3, 'Na ĩndĩ asumbĩ anini, na amũli, na makavana, na asili, na asũvĩi ma ũthwii, na atai, na asilan’ya, na asumbĩki onthe ma ilungu isu nene sya nthĩ, moombana kwambĩlĩlya ũthaithi wa mũvw’anano ũla mũsumbĩ Nevukatilesa waĩ anaũngamya; na maũngama mbee wa mũvw’anano ũla Nevukatilesa waĩ anaũngamya.'),
('kam', 'DAN', 3, 4, 'Nĩvo ĩndĩ mũtavan’ya waneenie na wasya mũnene, Nĩ inyw’ĩ mweeaĩwa, inyw’ĩ ngo sya andũ, na mbaĩ, na ithyomo,'),
('kam', 'DAN', 3, 5, 'ĩvinda yĩla mwĩĩw’a wasya wa soo mũkelemu, na nzumalĩ, na mbeve, na kaveve, na kĩnanda, na mũtũlilũ, na mĩthemba yonthe ya mbeve syĩ mawasya, mwĩvalũka nthĩ na kũthaitha mũvw’anano wa thaavu ũla mũsumbĩ Nevukatilesa ũnaũngamisye;'),
('kam', 'DAN', 3, 6, 'na ũla ũtevalũka nthĩ na kũthaitha saa o ũsu akekw’a nthĩnĩ wa iko yĩ mwaki mwakanu.'),
('kam', 'DAN', 3, 7, 'Na ĩndĩ ĩvinda yĩu, ngo syonthe sya andũ syeew’a wasya wa soo mũkelemu, na nzumalĩ, na mbeve, na kaveve, na kĩnanda, na mĩthemba yonthe ya mbeve syĩ mawasya, ngo syonthe sya andũ, na mbaĩ, na ithyomo, syavalũka nthĩ na syathaitha mũvw’anano wa thaavu ũla mũsumbĩ Nevukatilesa waĩ anaũngamya.'),
('kam', 'DAN', 3, 8, 'Kwondũ wa ũu ĩvinda yĩu Akalitei amwe mathengeea, na mavinganĩsya Ayuti.'),
('kam', 'DAN', 3, 9, 'Maneena na mamwĩa mũsumbĩ Nevukatilesa, We mũsumbĩ, ĩkala tene na tene.'),
('kam', 'DAN', 3, 10, 'Naku, we mũsumbĩ, nũtw’ĩte ũtw’ĩo, kana kĩla mũndũ wĩĩw’a wasya wa soo mũkelemu, na nzumalĩ, na mbeve, na kaveve, na kĩnanda, na mũtũlilũ, na mĩthemba yonthe ya mbeve syĩ mawasya, evalũka nthĩ na kũthaitha mũvw’anano ũsu wa thaavu;'),
('kam', 'DAN', 3, 11, 'na o ũla ũtevalũka nthĩ na kũthaitha, akekw’a nthĩnĩ iko yĩ mwaki mwakanu.'),
('kam', 'DAN', 3, 12, 'Ve Ayuti amwe ala waiie ĩũlũ wa maũndũ ma kĩlungu kĩnene kya nthĩ kĩtawa Mbaviloni: Satalaki, na Mesaki, na Aveti‐neko; andũ asu, we mũsumbĩ, mainakũkĩa: maithũkũmaa ngai syaku, o na maiũthaitha mũvw’anano wa thaavu ũla ũnaũngamisye.'),
('kam', 'DAN', 3, 13, 'Nĩvo ĩndĩ Nevukatilesa weaie, e na ũthilĩku na ũthatu mwai, kana Satalaki, na Mesaki, na Aveti‐neko maetwe. Na ĩndĩ maete andũ asu vala ve mũsumbĩ.'),
('kam', 'DAN', 3, 14, 'Nevukatilessa aneena na amea, Nĩ kwa kwĩtw’ĩĩa, inyw’ĩ Satalaki, na Mesaki, na Aveti‐neko, mũithũkũmaa ngai yakwa, o na mũiũthaitha mũvw’anano wa thaavu ũla nĩnaũngamisye?'),
('kam', 'DAN', 3, 15, 'Na ĩndĩ ethĩwa nĩmwĩyũmbanĩtye ĩvinda yĩla mwĩĩw’a wasya wa soo mũkelemu, na nzumalĩ, na mbeve, na kaveve, na kĩnanda, na mũtũlilũ, na mĩthemba yonthe ya mbeve syĩ mawasya, mwĩvalũka nthĩ na kũthaitha mũvw’anano ũla nĩnaseũvĩthisye, nĩ ũseo: ĩndĩ ethĩwa mũiũthaitha, mũkekw’a saa o ũsu nthĩnĩ wa iko yĩ mwaki mwakanu; na nũũ ngai ĩsu ĩkamumya mokonĩ makwa?'),
('kam', 'DAN', 3, 16, 'Satalaki, na Mesaki, na Aveti‐neko masũngĩa na mamwĩa mũsumbĩ, We Nevukatilesa, ithyĩ tũti na vata wa ũkũsũngĩa ũndũnĩ ũsu.'),
('kam', 'DAN', 3, 17, 'O na ethĩwa nĩ ũu, Ngai waitũ ũla tũthũkũmaa nũtonya kũtũtangĩĩa kuma ikonĩ yĩ mwaki mwakanu; nake akatũtangĩĩa kuma mokonĩ maku, we mũsumbĩ.'),
('kam', 'DAN', 3, 18, 'Ĩndĩ ethĩwa ti ũu, ũmanyĩke kwaku, we mũsumbĩ, tũtithũkũma ngai syaku, o na kũthaitha mũvw’anano wa thaavu ũla ũnaũngamisye.'),
('kam', 'DAN', 3, 19, 'Nĩvo ĩndĩ Nevukatilesa wausũiwe nĩ ũthatu mwai, na mũvw’ano wa ũthyũ wake wamaalyũkĩla Satalaki, na Mesaki, na Aveti‐neko; kwondũ wa ũu aneena, na eeaa mekĩe iko mwaki kũndũ mũonza mbee wa ũndũ yakothaa kwĩkĩwa mwaki.'),
('kam', 'DAN', 3, 20, 'Na eeaĩa ngũmbaũ imwe sya ita syake syove Satalaki, na Mesaki, na Aveti‐neko, na kũmekya nthĩnĩ wa iko yĩ mwaki mwakanu.'),
('kam', 'DAN', 3, 21, 'Nĩvo ĩndĩ andũ asu mooviwe me na makanzũ moo, na makoti moo, na masuka moo, na ngũa ingĩ syoo, na mekw’a nthĩnĩ wa iko yĩ mwaki mwakanu.'),
('kam', 'DAN', 3, 22, 'Na ĩndĩ nĩkwĩthĩwa mwĩao wa mũsumbĩ waĩ wa kũkalaata, na iko yakanĩte mwaki mũno, kĩtw’ĩki kya mwaki kyooaa andũ ala mamakwatie Satalaki, na Mesaki, na Aveti‐neko.'),
('kam', 'DAN', 3, 23, 'Na andũ asu atatũ, Satalaki, na Mesaki, na Aveti‐neko, mavalũka me ove nthĩni wa iko yĩ mwaki mwakanu.'),
('kam', 'DAN', 3, 24, 'Nĩvo ĩndĩ mũsumbĩ Nevukatilesa waseng’ie, na ookĩla na mĩtũkĩ: aneena na akũlya atai make, Tũinekya andũ atatũ me ove nthĩnĩ wa mwaki? Masũngĩa na mamwĩa mũsumbĩ, Nĩ w’o, we mũsumbĩ.'),
('kam', 'DAN', 3, 25, 'Asũngĩa na amea, Sisya, nĩngwona andũ ana athasye, maikinyĩla nthĩnĩ wa mwaki, nao mati na ũndũ; na mũvw’ano wa ũla wa kana nĩ ta mwana wa i ngai.'),
('kam', 'DAN', 3, 26, 'Nĩvo ĩndĩ Nevukatilesa wathengeeie vakuvĩ na mũomo wa iko yĩ mwaki mwakanu: aneena na asya, Satalaki, na Mesaki, na Aveti‐neko, inyw’ĩ athũkũmi ma Ngai Ũla Wĩ Ĩũlũ wa Onthe, umaalai, mũke kũũ. Na ĩndĩ Satalaki, na Mesaki, na Aveti‐neko mauma mwakinĩ nthĩnĩ.'),
('kam', 'DAN', 3, 27, 'Na asumbĩ anini, na amũli, na makavana, na atai ma mũsumbĩ, ala maĩ manoombana vamwe, moona andũ asu, kana mwaki ndwĩĩ na vinya mĩĩnĩ yoo, o na nzw’ĩĩ sya mĩtwe yoo itinavya, o na makanzũ moo matinaalyũka, o na mũuke wa mwaki ndũnamakwata.'),
('kam', 'DAN', 3, 28, 'Nevukatilesa aneena na asya, Nataĩwe Ngai wa Satalaki, na Mesaki, na Aveti‐neko, ũla ũtũmie mũlaĩka wake, na atangĩĩa athũkũmi make ala mamwĩkwatasya, na maalyũlĩte ndeto ya mũsumbĩ, na manengane mĩĩ yoo, maikathũkũme o na kũthaitha ngai o na yĩva, ate o Ngai woo ene.'),
('kam', 'DAN', 3, 29, 'Kwondũ wa ũu nĩngũtw’a ũtw’ĩo, kana kĩla ũko wa andũ, na mbaĩ, na yĩthyomo, ala makamũneenea ndeto ĩtaĩle Ngai wa Satalaki, na Mesaki, na Aveti‐neko, makatilangwa ilungu, na nyũmba syoo ikatw’ĩka maũtũnda ma syaa; nũndũ vati ngai ĩngĩ ĩtonya kũtangĩĩa ta ũu.'),
('kam', 'DAN', 3, 30, 'Nĩvo ĩndĩ mũsumbĩ wanenevisye Satalaki, na Mesaki, na Aveti‐neko kĩlungunĩ kyu kĩnene kya nthĩ kĩtawa Mbaviloni.'),
('kam', 'DAN', 4, 1, 'Mũsumbĩ Nevukatilesa, kwa ngo syonthe sya andũ, na mbaĩ, na ithyomo, ila itwĩe nthĩ yonthe: Mũuo wingĩve kwenyu.'),
('kam', 'DAN', 4, 2, 'Nĩkwonekete ta nĩ ũseo kwakwa kwonan’ya mawonan’yo na moseng’yo ala Ngai Ũla Wĩ Ĩũlũ wa Onthe wekie kwakwa.'),
('kam', 'DAN', 4, 3, 'Mawonan’yo make ũndũ manenevete! Na moseng’yo make ũndũ mean’ya vinya! Ũsumbĩ wake nĩ ũsumbĩ wa tene na tene, na ũsumbĩko wake nĩ kuma nzyawa na nzyawa.'),
('kam', 'DAN', 4, 4, 'Nyie, Nevukatilesa, nathũmũĩte nyũmbanĩ yakwa, na kwingĩvĩwa nyũmbanĩ yakwa nene mbanakavye.'),
('kam', 'DAN', 4, 5, 'Nĩnoonie ndoto ĩla yambĩkĩie w’ĩa; na malilikano nĩ ũkomonĩ wakwa na mawoni ma mũtwe wakwa nĩmanthĩnisye.'),
('kam', 'DAN', 4, 6, 'Kwondũ wa ũu natw’a ũtw’ĩo andũ oĩ onthe ma Mbaviloni maetwe vala nĩĩ, mamanyĩthye ũalyũlo wa ndoto.'),
('kam', 'DAN', 4, 7, 'Nĩvo ĩndĩ mookie eki ma syama, na awe, na Akalitei, na ala mathanaa maũndũ; nakwa natavan’ya ĩ ndoto vala maĩ; ĩndĩ matyaamanyĩthya ũalyũlo wayo.'),
('kam', 'DAN', 4, 8, 'Ĩndĩ mũminũkĩlyo Ndanieli alika vala nĩĩ, ũla wetawa syĩtwa yake Mbelitesasa, o ta syĩtwa ya ngai yakwa, na ũla nthĩnĩ wake ve veva wa ila ngai ntheu: nakwa natavan’ya ndoto vala ũĩ, ngĩmwĩa,'),
('kam', 'DAN', 4, 9, 'We Mbelitesasa, vwana wa eki ma syama, nĩkwĩthĩwa nĩnĩsĩ veva wa ila ngai ntheu wĩ nthĩnĩ waku, na vati ũndũ ũvithe ũkũthĩn’ya, ndavya mawoni ma ndoto yakwa ala nĩnoonie, na ũalyũlo wamo.'),
('kam', 'DAN', 4, 10, 'Aa nĩo mawoni ma mũtwe wakwa nĩ ũkomonĩ wakwa: nĩnĩnoonie, na sisya, mũtĩ katĩ wa nthĩ; na ũtũlu waw’o ũnaĩ mũnene.'),
('kam', 'DAN', 4, 11, 'Mũtĩ weana, na ũnaĩ na vinya, na ũtũlu waw’o wavika ĩtunĩ, na kwoneka kwaw’o kwavika kĩtulunĩ kya nthĩ yonthe.'),
('kam', 'DAN', 4, 12, 'Matũ maw’o manaĩ maseo, na ũsyao waw’o mwingĩ, na nthĩnĩ waw’o vanaĩ lĩu wa onthe: nyamũ sya kĩtheka inaĩ na muunyĩ ĩtina waw’o, na nyũnyi sya yayaya inekalaa mbongenĩ syaw’o, na mĩĩ yonthe ĩnaĩthaw’a nĩw’o.'),
('kam', 'DAN', 4, 13, 'Noona mawoninĩ ma mũtwe wakwa nĩ ũkomonĩ wakwa, na, sisya, mũsyaĩĩsya, nake nĩ mũtheu, atheea kuma ĩtunĩ.'),
('kam', 'DAN', 4, 14, 'Aneena na wasya mũnene, na asya atĩĩ, Tema mũtĩ ũvalũke, na ũitilanga mbonge syaw’o, thingithya wĩtĩkye matũ maw’o, na ũinyaĩĩkya ũsyao waw’o: nyamũ syume ĩtina waw’o, na nyũnyi mbongenĩ syaw’o.'),
('kam', 'DAN', 4, 15, 'Ĩndĩ tia kĩtina kya mĩi kyaw’o nthĩnĩ wa nthĩ, o nyekinĩ nziũ sya kĩsesi, kĩ o na kĩtang’a kya kĩaa na ũthuku; na nĩkĩthĩawe na ũthithu wa ĩmwe ya ĩtunĩ: na kya ũya kyake nĩkĩthĩawe vamwe na nyamũ nyekinĩ sya nthĩ:'),
('kam', 'DAN', 4, 16, 'ngoo yake nĩalyũke ndĩkethĩwe ngoo ya mũndũ, na nanengwe ngoo ya nyamũ; na mavinda mũonza mavĩte ĩũlũ wake.'),
('kam', 'DAN', 4, 17, 'Ũsilĩlo ũsu nĩ ũndũ wa ũtw’ĩo wa asyaĩĩsya, na kwenda kũu nĩ kwondũ wa ndeto ya ala atheu; nĩ kana ala me thayũ mamanye Ũla Wĩ Ĩũlũ wa Onthe nũsũmbĩkaa ũsumbĩnĩ wa andũ, na nũmũnengae o ũla wendaa, na nũsumbĩkasya ĩũlũ waw’o ũla wĩ ĩtheo mũno andũnĩ.'),
('kam', 'DAN', 4, 18, 'Ndoto ĩsu nyie, mũsumbĩ Nevukatilesa, nĩnĩnoonie; naku, we Mbelitesasa, tavan’ya ũalyũlo wayo, nũndũ andũ oĩ onthe ma ũsumbĩ wakwa maitonya kũmanyĩthya ũalyũlo; ĩndĩ we nũtonya; nũndũ veva wa ila ngai ntheu wĩ nthĩnĩ waku.'),
('kam', 'DAN', 4, 19, 'Nĩvo ĩndĩ Ndanieli, ũla wetawa syĩtwa yake Mbelitesasa, ekala ataneenekya ĩvinda ĩnene, na malilikano make mamũthĩn’ya. Mũsumbĩ asũngĩa na amwĩa, Mbelitesasa, ĩ ndoto ndĩkakũthĩn’ye, o na ũalyũlo wayo. Mbelitesasa asũngĩa na amwĩa, Mwĩaĩi wakwa, ndoto ĩsu nĩyĩthĩwe kwa ala makũmenaa, na ũalyũlo wayo kwa nthũ syaku.'),
('kam', 'DAN', 4, 20, 'Mũtĩ ũla ũnoonie, ũla ũneanaa, na ũnaĩ na vinya, ũla ũtũlu waw’o ũnavikie ĩtunĩ, na kwoneka kwaw’o kwavika nthĩ yonthe;'),
('kam', 'DAN', 4, 21, 'ũla matũ maw’o manaĩ maseo, na ũsyao waw’o ũnaĩ mwingĩ, na nthĩnĩ waw’o vanaĩ lĩu wa onthe; ũla nyamũ sya kĩtheka inekalaa ĩtina waw’o, na nyũnyi sya yayaya inaĩ na wĩkalo wasyo mbongenĩ syaw’o:'),
('kam', 'DAN', 4, 22, 'nue, we mũsumbĩ, ũla weanie na waya vinya; nũndũ ũnene waku nĩweanie, na ũvikĩte ĩtunĩ, na ũsumbĩko waku wavika kĩtulunĩ kya nthĩ.'),
('kam', 'DAN', 4, 23, 'Na nĩkwĩthĩwa mũsumbĩ nũnoonie mũsyaĩĩsya, nake nĩ mũtheu, atheeete kuma ĩtunĩ, na akyasya, Tema mũtĩ ũvalũke, na ũiwananga; ĩndĩ tia kĩtina kya mĩi kyaw’o nthĩnĩ wa nthĩ, nyekinĩ nziũ sya kĩsesi, kĩ o na kĩtang’a kya kĩaa na ũthuku, na nĩkĩthĩawe na ũthithu wa ĩmwe ya ĩtunĩ; na kya ũya kyake nĩkĩthĩawe vamwe na nyamũ sya kĩtheka, mũvaka mavinda mũonza mavĩte ĩũlũ wake;'),
('kam', 'DAN', 4, 24, 'ũalyũlo nĩ ũũ, we mũsumbĩ, na nĩ ũtw’ĩo wa Ũla Wĩ Ĩũlũ wa Onthe, ũmũkĩe mwĩaĩi wakwa mũsumbĩ:'),
('kam', 'DAN', 4, 25, 'atĩ ũkalũngw’a wume andũnĩ, na ũtũo waku ũkethĩawa vamwe na nyamũ sya kĩtheka, naku mũvaka ũĩsae nyeki ya ng’ombe, na ũkethĩawa na ũthithu wa ĩmwe ya ĩtunĩ, na mavinda mũonza makavĩta ĩũlũ waku; kũvika yĩla ũkamanya atĩ Ũla Wĩ Ĩũlũ wa Onthe nĩwe ũsumbĩkaa ũsumbĩnĩ wa andũ, na nũnengae o ũla wendaa.'),
('kam', 'DAN', 4, 26, 'Na nĩkwĩthĩwa nĩmaneeaie kũtia kĩtina kya mĩi kya mũtĩ; ũsumbĩ waku ũkeethĩwa wĩ mũlũmu kwaku, ĩtina wa wamanya kana matu nĩmo masumbĩkaa.'),
('kam', 'DAN', 4, 27, 'Kwondũ wa ũu, we mũsumbĩ, ũtao wakwa nĩwĩtĩkĩlwe kwaku, na ũkĩĩva naĩ syaku na ũlũngalu, na mothũku maku na kũmew’ĩa ala ngya tei; ethĩwa nũtonyeka mũuo waku wongeleke.'),
('kam', 'DAN', 4, 28, 'Aa onthe mookĩa mũsumbĩ Nevukatilesa.'),
('kam', 'DAN', 4, 29, 'Myei ĩkũmi na ĩlĩ yathela, aanganga ĩũlũ wa nyũmba nene mbanakavye ya kĩũsumbĩ ya Mbaviloni.'),
('kam', 'DAN', 4, 30, 'Mũsumbĩ aneena na asya, Ĩno ti Mbaviloni nene, ũla naakie nyie na vinya mũnene wa ũtonyi wakwa na nũndũ wa ndaĩa ya ũnene wakwa, yĩthĩwe yĩ ũtũo wa kĩũsumbĩ?'),
('kam', 'DAN', 4, 31, 'Yĩla ndeto yaĩ kanyw’anĩ wa mũsumbĩ, kwatheea wasya kuma ĩtunĩ, ũkĩmwĩa, We mũsumbĩ Nevukatilesa, we nũũtavw’a: Ũsumbĩ nĩwauma kwaku:'),
('kam', 'DAN', 4, 32, 'naku ũkalũngw’a wume andũnĩ; na ũtũo waku ũkethĩawa vamwe na nyamũ sya kĩtheka; naku mũvaka ũĩsae nyeki ta ng’ombe; na mavinda mũonza makavĩta ĩũlũ waku; kũvika yĩla ũkamanya kana Ũla Wĩ Ĩũlũ wa Onthe nĩwe ũsumbĩkaa ũsumbĩnĩ wa andũ, na nũnengae o ũla wendaa.'),
('kam', 'DAN', 4, 33, 'Saa o ũsu ũla ũndũ weanĩw’a ĩũlũ wa Nevukatilesa: na alũngw’a aume andũnĩ, na aĩsaa nyeki ta ng’ombe, na mwĩĩ wake weethĩawa na ũthithu wa ĩmwe ya ĩtunĩ, kũvika nzw’ĩĩ syake syeethĩawa ta maw’ĩa ma ndiũ, na mbwaa syake ta mbwaa sya nyũnyi.'),
('kam', 'DAN', 4, 34, 'Na mũminũkĩlyo wa mĩthenya ĩsu nyie, Nevukatilesa, nang’elelya metho makwa ĩtunĩ, na ũmanyi wakwa wanzyokea, nakwa nataĩa Ũla Wĩ Ĩũlũ wa Onthe, na nataĩa na kũkatha ũla wĩkalaa tene na tene; nũndũ ũsumbĩko wake nĩ ũsumbĩko wa tene na tene, na ũsumbĩ wake nĩ kuma nzyawa na nzyawa;'),
('kam', 'DAN', 4, 35, 'na andũ onthe ala matwĩe nthĩ matalawa kwĩthĩwa ti kĩndũ; nake ekaa kwĩanana na kwenda kwake nguthunĩ ya kaũ ya matunĩ, na andũnĩ ala matwĩe nthĩ; o na vati ũmwe ũtonya kũsiĩĩa kw’oko kwake, kana kũmũkũlya, Wĩĩka ata?'),
('kam', 'DAN', 4, 36, 'Ĩvinda o yĩu ũmanyi wakwa wanzyokea; na kwondũ wa ndaĩa ya ũsumbĩ wakwa, ũnene wakwa na kũtisa kwakwa kwanzyokea; na atai makwa na eaĩi ma kwakwa mamantha makĩmbenda; nakwa nalũlũmĩlw’a ũsumbĩnĩ wakwa, na nongeleelwa ũnene mũseo mbee.'),
('kam', 'DAN', 4, 37, 'Na yu nyie, Nevukatilesa, nĩngũtaĩa na kũnenevya na kũkatha Mũsumbĩ wa ĩtunĩ; nũndũ mawĩa make onthe nĩ ma w’o, na mĩendele yake nĩ ya ũsili wa katĩ; na ala maendaa na wĩnenevyo nũtonya kũmanyivya.'),
('kam', 'DAN', 5, 1, 'Mũsumbĩ Mbelisasa nĩwavokeie eaĩi ngili ma kwake mboka nene, nake anyw’ĩa mbinyu vu mbee wa asu ngili.'),
('kam', 'DAN', 5, 2, 'Mbelisasa, akĩsama ĩla mbinyu, eeaa maete mĩio ya thaavu na vetha ĩla ĩthe wake Nevukatilesa waumĩtye ĩkalũnĩ yĩla yaĩ Yelusaleme; nĩ kana mũsumbĩ na eaĩi ma kwake, na iveti syake na aka make ngombo, manyw’e nayo.'),
('kam', 'DAN', 5, 3, 'Na ĩndĩ maete mĩio ya thaavu ĩla yaumiwe ĩkalũnĩ ya nyũmba ya Ngai ĩla yaĩ Yelusaleme; na mũsumbĩ na eaĩi ma kwake, na iveti syake na aka make ngombo, manyw’a nayo.'),
('kam', 'DAN', 5, 4, 'Manyw’a mbinyu, na mataĩa ngai sya thaavu, na sya vetha, na sya ũthuku, na sya kĩaa, na sya mũtĩ, na sya ĩvia.'),
('kam', 'DAN', 5, 5, 'Saa o ũsu syaumĩla syaa sya kw’oko kwa mũndũ, na syaandĩka sokaanĩ wa wakonĩ wa nyũmba nene mbanakavye ya mũsumbĩ syelekele kĩndũ kĩla kĩkĩawa mataa: na mũsumbĩ oona kĩlungu kya kw’oko kĩla kyaandĩkaa.'),
('kam', 'DAN', 5, 6, 'Nĩvo ĩndĩ ũthyũ wa mũsumbĩ waalyũkile, na malilikano make mamũthĩn’ya; na maleenyu ma kĩnyunyu kyake maleela na mau make matinangana.'),
('kam', 'DAN', 5, 7, 'Mũsumbĩ aneena na wasya mũnene awe, na Akalitei, na ala mathanaa maũndũ maetwe. Mũsumbĩ aneena na amea andũ oĩ ma Mbaviloni, O ũla ũkũsoma ũandĩko ũũ, na kũmbon’ya ũalyũlo waw’o, akeekĩwa ngũa ĩtilyĩ ta ndune, na mũnyoo wa thaavu ngingonĩ yake, na akeethĩwa mũsumbĩki wa katatũ ũsumbĩnĩ.'),
('kam', 'DAN', 5, 8, 'Na ĩndĩ andũ oĩ onthe ma mũsumbĩ mooka; ĩndĩ maiaatonya kũsoma ũandĩko, o na kũmanyĩthya mũsumbĩ ũalyũlo waw’o.'),
('kam', 'DAN', 5, 9, 'Nĩvo ĩndĩ mũsumbĩ Mbelisasa waũũyie mũno, na ũthyũ wake waalyũka, na eaĩi ma kwake masũanĩwa.'),
('kam', 'DAN', 5, 10, 'Na ĩndĩ inyia wa mũsumbĩ nũndũ wa ndeto sya mũsumbĩ na eaĩi ma kwake ooka nyumbanĩ ya mboka: na inyia wa mũsumbĩ aneena na amwĩa, We mũsumbĩ, ĩkala tene na tene; malilikano maku maikakũthĩn’ye, o na ũthyũ waku ndũkaalyũke.'),
('kam', 'DAN', 5, 11, 'Ve mũndũ ũsumbĩnĩ waku, wĩ na veva wa ila ngai ntheu nthĩnĩ wake; na mĩthenya ya au waku kyeni na ũmanyi na ũĩ, ta ũĩ wa ila ngai, nĩmoonekie nthĩnĩ wake; na mũsumbĩ Nevukatilesa au waku, o ũsu mũsumbĩ, au waku, amũtw’ĩkĩthya vwana wa eki ma syama, na wa awe, na Akalitei, na ala mathanaa maũndũ;'),
('kam', 'DAN', 5, 12, 'nũndũ veva mũseo, na ũĩ, na ũmanyi, na ũalyũlo wa ndoto, na kũvuan’ya nthimo, na kũlingisũkan’ya maũndũ malingisanu, nĩmoonekie nthĩnĩ wa Ndanieli ũsu, ũla mũsumbĩ wamwĩtie Mbelitesasa. Na yu Ndanieli nĩetwe, nake nũnũkwonan’ya ũalyũlo.'),
('kam', 'DAN', 5, 13, 'Nĩvo ĩndĩ Ndanieli waetiwe vala ve mũsumbĩ. Mũsumbĩ aneena na akũlya Ndanieli, We nue Ndanieli ũsu wa ana ma ala matavĩtwe ma Yuta, ala mũsumbĩ, asa wakwa, wamaetie kuma Yuta?'),
('kam', 'DAN', 5, 14, 'Nyie nĩneew’a ũvoo waku, kana veva wa ila ngai wĩ nthĩnĩ waku, na ĩngĩ kyeni na ũmanyi na ũĩ mũseo nĩmonekete nthĩnĩ waku.'),
('kam', 'DAN', 5, 15, 'Na yu andũ oĩ, ala awe, nĩmaetiwe vala nĩĩ nĩ kana masome ũandĩko ũũ, na kũmanyĩthya ũalyũlo waw’o; ĩndĩ mainatonya kũmbon’ya ũalyũlo wa ũndũ ũũ.'),
('kam', 'DAN', 5, 16, 'Ĩndĩ nĩneew’a ũvoo waku, kana nũtonya kũalyũla, na kũlingisũkan’ya maũndũ malingisanu; ĩndĩ yu ethĩwa nũtonya kũsoma ũla ũandĩko, na kũmanyĩthya ũalyũlo waw’o, ũkeekĩwa ngũa ĩtilyĩ ta ndune, na mũnyoo wa thaavu ngingonĩ yaku, naku ũkeethĩwa mũsumbĩki wa katatũ ũsumbĩnĩ.'),
('kam', 'DAN', 5, 17, 'Nĩvo ĩndĩ Ndanieli wasũngĩie na aneenea vu mbee wa mũsumbĩ, Mĩthĩnzĩo yaku nĩyĩthĩwe yaku mwene, na ũĩnenga ũngĩ matuvi maku; ĩndĩ nakwa nĩngũsomea mũsumbĩ ũandĩko, na kũmũmanyĩthya ũalyũlo.'),
('kam', 'DAN', 5, 18, 'Naku, we mũsumbĩ, Ngai Ũla Wĩ Ĩũlũ wa Onthe nĩwanengie au waku Nevukatilesa ũsumbĩ, na ũnene, na ndaĩa, na ũkatho:'),
('kam', 'DAN', 5, 19, 'na nũndũ wa ũnene ũla wamũnengie, ngo syonthe sya andũ, na mbaĩ, na ithyomo nĩmatetemaa na kũkĩa mbee wake: ũla wendie kũmũaa aimũaa, na ũla wendie kũmũeka aimũeka e thayũ; ũla wendie kũmũkĩlya aimũkĩlya, na ũla wendie kũmũtheesya aimũtheesya.'),
('kam', 'DAN', 5, 20, 'Ĩndĩ yĩla ngoo yake yokĩlilw’e, na veva wake wooma kũvika eeka na ngathĩĩo, aumw’a kĩvĩlanĩ kyake kya ũsumbĩ, na mamũvena ndaĩa yake:'),
('kam', 'DAN', 5, 21, 'na alũngw’a auma ananĩ ma andũ na ngoo yake yatw’ĩkĩthw’a ta ya nyamũ, na ũtũo wake waĩ vamwe na mang’oi ma kĩthekanĩ; na aĩthaw’a nyeki ta ng’ombe, na mwĩĩ wake weethĩawa na ũthithu wa ĩmwe ya ĩtunĩ; kũvika yĩla wamanyie kana Ngai Ũla Wĩ Ĩũlũ wa Onthe nĩwe ũsumbĩkaa ũsumbĩnĩ wa andũ, na nĩwiaa ĩũlũ waw’o o ũla wendaa.'),
('kam', 'DAN', 5, 22, 'Naku mwanae, we Mbelisasa, ndwaanyivya ngoo yaku, o na wamanya maũndũ asu onthe,'),
('kam', 'DAN', 5, 23, 'ĩndĩ nĩweenenevesye Mwĩaĩi wa ĩtunĩ; nao maete mĩio ya nyũmba yake vala ũĩ, naku na eaĩi ma kwaku, na iveti syaku na aka maku ngombo, manyw’a mbinyu nayo; naku nũtaĩĩte ngai sya vetha na thaavu, na ũthuku, na kĩaa, na mũtĩ, na ĩvia, ila itonaa, o na kwĩw’a, o na kũmanya; na Ngai ũla mĩthũmũ yaku ĩ mokonĩ make, na nzĩa syaku syonthe nĩ syake, ndwaamũtaĩa.'),
('kam', 'DAN', 5, 24, 'Nĩvo ĩndĩ kĩlungu kya kw’oko kĩetiwe nĩwe, na ũandĩko ũũ waandĩkwa.'),
('kam', 'DAN', 5, 25, 'Na ũandĩko nĩ ũũ ũla ũandĩkiwe: MENE, MENE, TEKELI, UVALASINI.'),
('kam', 'DAN', 5, 26, 'Ũalyũlo waw’o nĩ ũũ: MENE; Ngai nũtalĩte ũsumbĩ waku, na kũwũmina.'),
('kam', 'DAN', 5, 27, 'TEKELI; nũthimĩtwe kĩthiminĩ, na nĩwonekete kwĩthĩwa nũtielye.'),
('kam', 'DAN', 5, 28, 'VELESI; ũsumbĩ waku nũaanĩtwe, na nũnengetwe Ametia na Avelisia.'),
('kam', 'DAN', 5, 29, 'Nĩvo ĩndĩ Mbelisasa weaie, na meekĩa Ndanieli ngũa ĩtilyĩ ta ndune, na mamwĩkĩa ngingonĩ yake mũnyoo wa thaavu, na matavan’ya ũvoo wake, ethĩwe mũsumbĩki wa katatũ ũsumbĩnĩ.'),
('kam', 'DAN', 5, 30, 'Ũtukũ ũsu Mbelisasa mũsumbĩ wa Akalitei ooawa.'),
('kam', 'DAN', 5, 31, 'Na Ndalio Mũmetia anengwa ũsumbĩ, e wa myaka ta mĩongo thanthatũ na ĩlĩ.'),
('kam', 'DAN', 6, 1, 'Ndalio nĩwendeew’e nĩ kwia ĩũlũ wa ũsumbĩ asumbĩ anini ĩana na mĩongo ĩlĩ, methĩwe ĩũlũ wa ũsumbĩ w’onthe;'),
('kam', 'DAN', 6, 2, 'na ĩũlũ wa asu anene atatũ, ũmwe woo aĩ Ndanieli; nĩ kana asumbĩ asu anini maumasye ũtalo kwoo, na nĩ kana mũsumbĩ ndakethĩwe na wasyo.'),
('kam', 'DAN', 6, 3, 'Na ĩndĩ Ndanieli ũsu ataĩawa kwĩ anene asu na asumbĩ anini, nĩkwĩthĩwa veva mũseo waĩ nthĩnĩ wake; mũsumbĩ nake asũanĩaa kũmwia ĩũlũ wa ũsumbĩ w’onthe.'),
('kam', 'DAN', 6, 4, 'Nĩvo ĩndĩ anene asu na asumbĩ anini mamanthie ũndũ wa kwilĩĩla Ndanieli maũndũnĩ ma ũsumbĩ; ĩndĩ maiaaona ũndũ o na ĩvĩtyo, nĩkwĩthĩwa aĩ na kĩthito, o na kũiaaoneka kwake ĩvĩtyo kana ũndũ ũtaĩle.'),
('kam', 'DAN', 6, 5, 'Na ĩndĩ andũ asu masya, Tũikona ũndũ wa kwilĩĩla Ndanieli ũũ, ate o tũiona wa kũmwilĩĩla maũndũnĩ ma mĩao ya Ngai wake.'),
('kam', 'DAN', 6, 6, 'Nĩvo ĩndĩ anene asu na asumbĩ anini moombanĩe mũsumbĩ vamwe, na mamwĩa atĩĩ, Mũsumbĩ Ndalio, ĩkala tene na tene.'),
('kam', 'DAN', 6, 7, 'Anene onthe ma ũsumbĩ, o na amũli na asumbĩ anini, na atai na makavana, nĩmasũanĩĩte vamwe kwia mwamũlo wa kĩũsumbĩ, na kũtw’a ũtw’ĩo mũlũmu, kana o ũla wĩvoya ũndũ wa ngai o na yĩva kana kwa mũndũ ĩvinda ya matukũ mĩongo ĩtatũ, ate o kwaku, we mũsumbĩ, akekw’a ngunganĩ ya mĩnyambũ.'),
('kam', 'DAN', 6, 8, 'Na ĩndĩ, we mũsumbĩ, lũmya ũtw’ĩo, na ũkĩkĩa ũandĩko saii, ndũkaalyũlwe, kwĩanana na mwĩao wa Ametia na Avelisia, ũla ũtaalyũlĩka.'),
('kam', 'DAN', 6, 9, 'Kwondũ wa ũu mũsumbĩ Ndalio eekĩa ũandĩko na ũtw’ĩo saii.'),
('kam', 'DAN', 6, 10, 'Na yĩla Ndanieli wamanyie kana ũandĩko nĩweekĩwa saii, aenda nyũmbanĩ yake (na ĩndĩ mbũthi sya kasũmba kake syaĩ mbingũe kwelekela Yelusaleme); na atulasya ndu kĩla mũthenya katatũ, aivoya, na aitũngĩa mũvea vu mbee wa Ngai wake, o tondũ weekaa tene.'),
('kam', 'DAN', 6, 11, 'Nĩvo ĩndĩ andũ asu moombanie, na mamwona Ndanieli aivoya na akĩĩsũvanĩa vu mbee wa Ngai wake.'),
('kam', 'DAN', 6, 12, 'Na ĩndĩ mathengeea, na maneenea mbee wa mũsumbĩ ũndũ wa ũtw’ĩo wa mũsumbĩ: Ndũneekĩa ũtw’ĩo saii, kana kĩla mũndũ ũla wĩvoya ngai o na yĩva kana mũndũ ĩvinda ya matukũ mĩongo ĩtatũ, ate o kwaku, we mũsumbĩ, akekw’a ngunganĩ ya mĩnyambũ? Mũsumbĩ asũngĩa na amea, Ũndũ ũsu nĩ wa w’o, kwĩanana na mwĩao wa Ametia na Avelisia, ũla ũtaalyũlĩka.'),
('kam', 'DAN', 6, 13, 'Na ĩndĩ masũngĩa na maneenea vala ve mũsumbĩ, Ndanieli ũsu, wa ma ala matavĩtwe ma Yuta, ndeũkũkĩa, we mũsumbĩ, o na ũla ũtw’ĩo ũneekĩie saii, ĩndĩ nũvoyaa kĩla mũthenya katatũ.'),
('kam', 'DAN', 6, 14, 'Na ĩndĩ mũsumbĩ, eew’a ndeto isu, eew’a woo mũno, na eetw’ĩĩa ngoonĩ yake kũvonokya Ndanieli; nake athĩnĩa wĩa kũvika syũa yathũa amũtangĩĩe.'),
('kam', 'DAN', 6, 15, 'Nĩvo ĩndĩ andũ asu moombanĩe mũsumbĩ vamwe, na meea mũsumbĩ, Manya, we mũsumbĩ, kana nĩ mwĩao wa Ametia na Avelisia, kana ũtw’ĩo o na mwamũlo ũlũlũmĩlw’e nĩ mũsumbĩ ndũalyũlĩkaa.'),
('kam', 'DAN', 6, 16, 'Nĩvo ĩndĩ mũsumbĩ weaie, na maete Ndanieli, na mamwĩkya ngunganĩ ya mĩnyambũ. Mũsumbĩ aneena na amwĩa Ndanieli, Ngai waku ũla ũthũkũmaa mavinda onthe, nĩwe wĩkũtangĩĩa.'),
('kam', 'DAN', 6, 17, 'Na ĩvia yaetwe, na yaiwa mũomonĩ wa ngunga; na mũsumbĩ asiĩla na ngome yake mwene ya ũvana ũsiĩlo, na ngome ya ũvana ũsiĩlo ya eaĩi ma kwake; nĩ kana ũndũ o na wĩva ndũkaalyũlwe ũndũ wa Ndanieli.'),
('kam', 'DAN', 6, 18, 'Na ĩndĩ mũsumbĩ aenda nyũmbanĩ yake nene mbanakavye, na ũtukũ w’onthe atĩĩa ũya; o na syĩndũ sya kũinga ityaaetwe vala ũĩ: na too wake wamwaĩa.'),
('kam', 'DAN', 6, 19, 'Na ĩndĩ mũsumbĩ ookĩla kĩoko tene mũno, na aenda na mĩtũkĩ ngunganĩ ya mĩnyambũ.'),
('kam', 'DAN', 6, 20, 'Na yĩla wathengeeie ngunganĩ vala ve Ndanieli, aĩa na wasya wa woo; mũsumbĩ aneena na akũlya Ndanieli, We Ndanieli, mũthũkũmi wa Ngai ũla wĩ thayũ, Ngai waku ũla ũthũkũmaa mavinda onthe, nũtonya ũkũtangĩĩa mĩnyambũnĩ?'),
('kam', 'DAN', 6, 21, 'Nĩvo ĩndĩ Ndanieli wasũngĩie mũsumbĩ, We mũsumbĩ, ĩkala tene na tene.'),
('kam', 'DAN', 6, 22, 'Ngai wakwa nũtũmie mũlaĩka wake, na atumya makanyw’a ma mĩnyambũ, na ndĩnambĩka ũndũ: nũndũ mbee wake nĩnonekete nde na ĩvĩtyo; o na ĩngĩ mbee waku, we mũsumbĩ, ndineevĩtya.'),
('kam', 'DAN', 6, 23, 'Nĩvo ĩndĩ mũsumbĩ watanie mũno, na eeaa maumye Ndanieli ngunganĩ. Na ĩndĩ Ndanieli aumw’a ngunganĩ, na ũndũ o na wĩva ndwaaoneka mwĩĩnĩ wake, nũndũ nũmũĩkĩĩĩte Ngai wake.'),
('kam', 'DAN', 6, 24, 'Na mũsumbĩ eeaa, na maete andũ asu ala mamũvinganĩsye Ndanieli, mamekya ngunganĩ ya mĩnyambũ, mo, na syana syoo, na aka moo; na mĩnyambũ yamakĩlya vinya, na yatilanga tũlungu mavĩndĩ moo onthe, mbee wa matanavika nthĩ ngunganĩ.'),
('kam', 'DAN', 6, 25, 'Nĩvo ĩndĩ mũsumbĩ Ndalio waandĩkĩie ngo syonthe sya andũ, na mbaĩ, na ithyomo, ila syatwĩe nthĩ yonthe: Mũuo wingĩvwe kwenyu.'),
('kam', 'DAN', 6, 26, 'Nĩngũtw’a ũtw’ĩo, kana ũsumbĩkonĩ w’onthe wa ũsumbĩ wakwa andũ mateteme na kũkĩa vala ve Ngai wa Ndanieli; nĩkwĩthĩwa nĩwe Ngai ũla wĩ thayũ, na ũla wĩkalaa tene na tene, na ũsumbĩ wake nĩ ũla ũtakanangĩka; na ũsumbĩko wake ũkeethĩwa o na kũvika mũminũkĩlyonĩ.'),
('kam', 'DAN', 6, 27, 'Nũvonokasya na kũtangĩĩaa, na nĩwĩkaa mawonan’yo na moseng’yo ĩtunĩ na nthĩ, ũla ũtangĩĩe Ndanieli kuma vinyanĩ wa mĩnyambũ.'),
('kam', 'DAN', 6, 28, 'Na ĩndĩ Ndanieli ũsu aathimĩka kũsumbĩkanĩ kwa Ndalio, na kũsumbĩkanĩ kwa Kulusi Mũvelisia.'),
('kam', 'DAN', 7, 1, 'Mwaka wa mbee wa kũsumbĩka kwa Mbelisasa mũsumbĩ wa Mbaviloni Ndanieli aĩ na ndoto na mawoni ma mũtwe wake e ũkomonĩ wake: na ĩndĩ aandĩka ndoto na aumya ũtalo wa maũndũ asu.'),
('kam', 'DAN', 7, 2, 'Ndanieli aneena na asya, Nĩnoonie woninĩ wakwa ũtukũ, na, sisya, iseve inya sya ĩtunĩ syauutana na vinya ĩũlũ wa ũkanga mũnene.'),
('kam', 'DAN', 7, 3, 'Na nyamũ inya nene syauma ũkanganĩ, itailyĩ ũndũ ũmwe.'),
('kam', 'DAN', 7, 4, 'Ya mbee yailyĩ ta mũnyambũ, na yaĩ na nthwau sya ndiũ: nasyaĩĩsya kũvika nthwau syayo syakũwa, na yookĩlw’a kuma nthĩ, na yaũngamw’a na maũũ elĩ ta mũndũ; na yanengwa ngoo ya mũndũ.'),
('kam', 'DAN', 7, 5, 'Na, sisya, nyamũ ĩngĩ, ya kelĩ, ĩtilyĩ ta nduva; nayo yeeyũkĩlya ngalĩ ĩmwe, na mbau itatũ syaĩ kanyw’anĩ wayo katĩ wa maeo mayo: na mamĩa atĩĩ, Ũkĩla, ũkaye nyama nyingĩ.'),
('kam', 'DAN', 7, 6, 'Ĩtina wa ũu noona, na, sisya, ĩngĩ, ĩtilyĩ ta ngo, ĩla yaĩ na nthwau inya sya nyũnyi mũongonĩ wayo; na ĩngĩ nyamũ ĩsu yaĩ na mĩtwe ĩna; na yanengwa ũsumbĩko.'),
('kam', 'DAN', 7, 7, 'Ĩtina wa ũu noona mawoninĩ ma ũtukũ, na, sisya, nyamũ ya kana, ya ũtĩsya na ya kwĩw’ĩthya w’ĩa, na ya vinya mũnene mũno; na yaĩ na maeo manene ma kĩaa; yamelya na yatũlanga ilungu, na yakinyanga matialyo na maũũ mayo: nayo ndĩailyĩ ta nyamũ syonthe sya mbee; na yaĩ na mbya ĩkũmi.'),
('kam', 'DAN', 7, 8, 'Naketeeaa ila mbya, na, sisya, wookĩla katĩ wasyo ũvya ũngĩ, mũnini, ũla mbee waw’o itatũ sya ila mbya sya mbee syakũiwe na mĩi: na, sisya, ũvyanĩ ũsu vaĩ metho ta metho ma mũndũ, na kanyw’a ũineena maũndũ manene.'),
('kam', 'DAN', 7, 9, 'Noona kũvika ivĩla sya ũsumbĩ syaiwa, na ũmwe ũla waĩ mũtumĩa wa matukũ ekalĩla: ngũa syake syaĩ nzaũ ta ĩa, na nzw’ĩĩ sya mũtwe wake ta w’ĩa mũtheu wa ĩlondu; kĩvĩla kyake kya ũsumbĩ kyaĩ itw’ĩki sya mwaki, na ndĩa syakyo syaĩ mwaki mwakanu.'),
('kam', 'DAN', 7, 10, 'Ũsĩ wa mwaki waumĩla wumĩte kwake: ngili kũndũ ngili mamũthũkũma, na ngili ĩkũmi kũndũ ngili ĩkũmi maũngama mbee wake: ũsilĩlo waiwa, na mavuku mavuanw’a.'),
('kam', 'DAN', 7, 11, 'Naketeea ĩvinda yĩu nũndũ wa wasya wa ndeto nene ila ũvya waneenie; naketeea kũvika nyamũ yooawa, na mwĩĩ wayo waanangwa, na wanenganwe ũvĩvw’e na mwaki.'),
('kam', 'DAN', 7, 12, 'Na ũndũ wa ila nyamũ syatialile, nĩsyaveniwe ũsumbĩko wasyo: ĩndĩ mathayũ masyo nĩsyongeleelwe kyathĩ na ĩvinda.'),
('kam', 'DAN', 7, 13, 'Noona mawoninĩ ma ũtukũ, na, sisya, kwooka na mathweo ma ĩtu ũmwe avw’anene na mwana wa mũndũ, o na ookĩa mũtumĩa wa matukũ, na mamũthengeesya vala ũĩ.'),
('kam', 'DAN', 7, 14, 'Na anengwa ũsumbĩko, na ndaĩa, na ũsumbĩ, nĩ kana ngo syonthe sya andũ, na mbaĩ, na ithyomo imũthũkũmae: ũsumbĩko wake nĩ ũsumbĩko wa tene na tene, ũla ũtakavĩta, na ũsumbĩ wake ũla ũtakanangĩka.'),
('kam', 'DAN', 7, 15, 'Ĩndĩ nyie, Ndanieli, nĩneewie woo vevanĩ wakwa katĩ wa mwĩĩ wakwa, na mawoni ma mũtwe wakwa manthĩn’ya.'),
('kam', 'DAN', 7, 16, 'Nathengeea ũmwe wa ala maũngyĩ vakuvĩ, na namũkũlya w’o wa ũndũ ũũ w’onthe. Na ĩndĩ andavya, na amanyĩthya ũalyũlo wa maũndũ asu.'),
('kam', 'DAN', 7, 17, 'Nyamũ isu nene, syĩ inya, nĩ asumbĩ ana, ala makokĩla kuma nthĩ.'),
('kam', 'DAN', 7, 18, 'Ĩndĩ atheu ma Ũla Wĩ Ĩũlũ wa Onthe nĩmakosa ũsumbĩ, na nĩmakasumbĩka tene na tene, o kũvika tene na tene.'),
('kam', 'DAN', 7, 19, 'Nĩvo ĩndĩ nendie kũmanya w’o ũndũ nyamũ ya kana yatilyĩ, ĩla ĩtailyĩ ta ila ĩngĩ syonthe, ya kũtĩsya mũno, ĩla maeo mayo maĩ ma kĩaa, na mbwaa syayo syaĩ sya ũthuku; ĩla yamelilye, na yatilanga ilungu, na yakinyanga matialyo na maũũ mayo;'),
('kam', 'DAN', 7, 20, 'na ũndũ wa mbya ĩkũmi ila syaĩ mũtwenĩ wayo, na ũvya ũngĩ ũla wookĩlile, na ũla mbee waw’o itatũ syavalũkile, o ũla ũvya waĩ na metho na kanyw’a ũla waneenaa maũndũ manene, na ũla ũthyũ waw’o waĩ vinya kwĩ ila ingĩ waĩ nasyo.'),
('kam', 'DAN', 7, 21, 'Naketeea, na ũvya o ũsu wokita na atheu, na wamakĩlya vinya;'),
('kam', 'DAN', 7, 22, 'kũvika yĩla mũtumĩa wa matukũ wokie, na atheu ma Ũla Wĩ Ĩũlũ wa Onthe manengwa ũsili, na ĩvinda yeanĩa yĩla atheu meethĩiwe na ũsumbĩ.'),
('kam', 'DAN', 7, 23, 'Ũũ nĩw’o waisye, Nyamũ ya kana nĩkethĩwa ũsumbĩ wa kana ĩũlũ wa nthĩ, ũla ũkethĩwa ũtailyĩ ta mosumbĩ onthe, na nũkamelya nthĩ yonthe, na kũmĩkinyanga, na kũmĩtilanga ilungu.'),
('kam', 'DAN', 7, 24, 'Na ũndũ wa mbya ĩkũmi, kuma ũsumbĩ ũsu asumbĩ ĩkũmi nĩmakokĩla: na ũngĩ nũkokĩla ĩtina woo; nake nũkethĩwa atailyĩ ta ũla wa mbee, nake nũkakĩlya asumbĩ atatũ vinya.'),
('kam', 'DAN', 7, 25, 'Na nũkamũneenea ndeto Ũla Wĩ Ĩũlũ wa Onthe, na nũkavinyĩthya atheu ma Ũla Wĩ Ĩũlũ wa Onthe; na nũkekwatya kũalyũla ĩvinda na mĩao; nao nĩmakanenganwe mokonĩ make kũvika ĩvinda na mavinda na nyunzu ya ĩvinda.'),
('kam', 'DAN', 7, 26, 'Ĩndĩ ũsili nũkekala, nao nĩmakamũvena ũsumbĩko wake, mominũkĩlye na kwananga kũvika mũminũkĩlyo.'),
('kam', 'DAN', 7, 27, 'Na ũsumbĩ na ũsumbĩko, na ũnene wa mosumbĩ ala me ungu wa ĩtu yonthe, nĩmakanengwa andũ ma atheu ma Ũla Wĩ Ĩũlũ wa Onthe: ũsumbĩ wake nĩ ũsumbĩ wa tene na tene, na mosumbĩko onthe nĩmakamũthũkũmaa we na kũmwĩw’aa.'),
('kam', 'DAN', 7, 28, 'Mũminũkĩlyo wa ũla ũndũ nĩ ũsu. Nakwa, Ndanieli, malilikano makwa manthĩn’ya mũno, na ũthyũ wakwa wangalyũkĩla: ĩndĩ nekalya ũndũ ũsu ngoonĩ yakwa.'),
('kam', 'DAN', 8, 1, 'Mwaka wa katatũ wa kũsumbĩka kwa mũsumbĩ Mbelisasa woni wanumĩlĩla, o nyie Ndanieli, ĩtina wa ũla wanumĩlĩle mbee.'),
('kam', 'DAN', 8, 2, 'Nakwa noona woninĩ; na ĩndĩ kweethĩwa, ngyona, naĩ nyũmbanĩ nene mbanakavye ku Susani, ĩla yĩ kĩlungunĩ kĩnene kya nthĩ kĩtawa Elamu; nakwa noona woninĩ, na naĩ vakuvĩ na ũsĩ wa Ulai.'),
('kam', 'DAN', 8, 3, 'Nĩvo ĩndĩ nookĩlilye metho makwa, noona, na, sisya, kwaũngama ndũũme ũtee wa ũsĩ yĩ na mbya ilĩ: na ila mbya ilĩ syaĩ ndasa; ĩndĩ ũmwe waĩ mũasa kwĩ ũngĩ, na ũla mũasa wookĩla ĩtina.'),
('kam', 'DAN', 8, 4, 'Noona ndũũme ĩluutĩte kwelekela ũthũĩlonĩ wa syũa, na ngalĩ ya ĩũlũ, na ngalĩ ya ĩtheo; na nyamũ o na syĩva itayaatonya kũũngama mbee wayo, o na kũtyaĩ ũtonya kũtangĩĩa kw’okonĩ kwayo; ĩndĩ yeeka kwĩanana na kwenda kwayo, na yeenenevya.'),
('kam', 'DAN', 8, 5, 'Nakwa ngĩsũanĩa, sisya, nthenge yauma ũthũĩlonĩ wa syũa yavĩtĩla ĩũlũ wa nthĩ yonthe, na ndĩakiitĩte nthĩ: na ĩla nthenge yaĩ na ũvya wa ũseng’ya katĩ wa metho mayo.'),
('kam', 'DAN', 8, 6, 'Na yookĩa ndũũme ĩla yaĩ na mbya ilĩ, ĩla namyonie ĩũngeme ũtee wa ũsĩ, na yamĩsembea na ũthatu mwai wa ũtonyi wayo.'),
('kam', 'DAN', 8, 7, 'Nakwa noona yathengeea ndũũme, na yamĩthatĩa, na yakima ndũũme, na yatũla mbya ilĩ syayo; o na ndũũme ndyaĩ na ũtonyi wa kũũngama mbee wayo; ĩndĩ yamĩvalũkya nthĩ, na yamĩkinyanga; o na kũtyaĩ ũtonya kũtangĩĩa ndũũme kw’okonĩ kwayo.'),
('kam', 'DAN', 8, 8, 'Na ĩndĩ nthenge ĩsu yeenenevya mũno: na yĩla yaĩ na vinya, ũvya mũnene watũlĩka; na vandũ vaw’o syookĩla mbya inya sya ũseng’ya syelekele iseve inya sya ĩtu.'),
('kam', 'DAN', 8, 9, 'Na nthĩnĩ wa ũmwe wasyo wauma ũvya mũnini, ũla wanenevie mũno, kwelekela ngalĩ ya ĩtheo, na wumĩlonĩ wa syũa, na ngalĩ ya ĩla nthĩ nzeo mũno.'),
('kam', 'DAN', 8, 10, 'Na waneneva, o na kũvika nguthu ya ĩtunĩ; na wavalũkya nthĩ imwe sya ĩla nguthu na sya ndata, na waikinyanga.'),
('kam', 'DAN', 8, 11, 'Ĩĩ, weenenevya, o na kũvika mũnene wĩ mbee ũsumbĩnĩ wa ĩ nguthu; na wamũvena nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na vandũ va vala vatheu vake vavalũkw’a.'),
('kam', 'DAN', 8, 12, 'Na ĩla nguthu yaumw’a yawũnengwa kwondũ wa ĩvĩtyo vamwe na nthembo ya kũvĩvw’a ĩtatw’ĩkanaa; na wekya w’o kũvika nthĩ, na weeka ũndũ wendete na waunĩka.'),
('kam', 'DAN', 8, 13, 'Nĩvo ĩndĩ neewie mũtheu ũmwe aineena; na mũtheu ũngĩ amwĩa ũsu ũmwe ũla waneenaa, Nĩ kũvika ĩndĩĩ woni wa nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na ĩvĩtyo yanangaa, kũnengane vala vandũ vatheu na nguthu nayo ikinyangwe na nyaĩĩ?'),
('kam', 'DAN', 8, 14, 'Nake anzũngĩa, Kũvika mawĩoo na ioko ngili ilĩ na maana atatũ; nĩvo ĩndĩ vala vandũ vatheu vakathew’a.'),
('kam', 'DAN', 8, 15, 'Na kweethĩwa, nyie, o nyie Ndanieli, yĩla noonie woni, namantha kũwũmanya; na, sisya, kwaũngama mbee wakwa ta mũvw’ano wa mũndũ.'),
('kam', 'DAN', 8, 16, 'Nakwa neew’a wasya wa mũndũ katĩ wa ũsĩ wa Ulai, ũla weetanie, na wasya, Kavilieli, manyĩthya mũndũ ũũ ũla woni.'),
('kam', 'DAN', 8, 17, 'Na ĩndĩ athengeea vala naũngyĩ; na ooka, nakwatwa nĩ w’ĩa, na navalũka na ũthyũ wakwa: ĩndĩ ambĩa, Manya, we mwana wa mũndũ; nũndũ ũ woni nĩ wa ĩvinda ya mũminũkĩlyo.'),
('kam', 'DAN', 8, 18, 'Na ĩndĩ akĩneena nakwa, nakwatwa nĩ too mũnene ũthyũ wakwa welekele nthĩ; ĩndĩ angiita, na anũngamya vala naũngyĩ.'),
('kam', 'DAN', 8, 19, 'Nake ambĩa, Sisya, nĩngũũmanyĩthya ũndũ ũkethĩwa ĩvinda ya mũminũkĩlyo wa ũla ũthatu mũnene; nũndũ nĩ wa ĩvinda yatwiwe ya mũminũkĩlyo.'),
('kam', 'DAN', 8, 20, 'Ndũũme ĩla woonie, yĩ na mbya ilĩ, nĩsyo asumbĩ ma Metia na Velisia.'),
('kam', 'DAN', 8, 21, 'Nayo nthenge yĩ maw’ĩa maingĩ nĩ mũsumbĩ wa Ngiliki: na ũvya mũnene wĩ katĩ wa metho mayo nĩ mũsumbĩ wa mbee.'),
('kam', 'DAN', 8, 22, 'Na ũndũ wa ũvya ũla watũlĩkile, ũla vandũ vaw’o syaũngamie inya, mosumbĩ ana nĩmakaũngama kuma mbaĩnĩ ĩsu, ĩndĩ matikethĩwa na ũtonyi take.'),
('kam', 'DAN', 8, 23, 'Na ĩvinda ya mũminũkĩlyo wa ũsumbĩ woo, yĩla avĩtan’ya makeanĩa, mũsumbĩ wĩ ũthyũ mwai, na mũmanyi wa nthimo, nũkaũngama.'),
('kam', 'DAN', 8, 24, 'Na ũtonyi wake nũkethĩwa wĩ mũnene mũno, ĩndi ti kwa ũtonyi wake mwene; na nũkananga kũvika kũseng’ya, na nũkaunĩka na kwĩka kwenda kwake; na nũkananga ala me vinya mũno na ala andũ atheu.'),
('kam', 'DAN', 8, 25, 'Na kwondũ wa mwĩkĩle wake nũkaingĩvya ũkengani kw’okonĩ kwake; na nũkenenevya ngoonĩ yake, na nũkananga aingĩ meyelele: na ĩngĩ nũkaũngama kũsiĩĩa mũnene wa anene; ĩndĩ nũkatilĩka vate kw’oko.'),
('kam', 'DAN', 8, 26, 'Na woni wa mawĩoo na ioko ũla ũneenetwe nĩ wa w’o: ĩndĩ vingĩa woni; nũndũ nĩ wa matukũ maingĩ meũka.'),
('kam', 'DAN', 8, 27, 'Nakwa, Ndanieli, nanyala, na nawaa matũkũ amwe; nĩvo ĩndĩ nookĩlile, na natethya wĩa wa mũsumbĩ: na naseng’a nũndũ wa woni, ĩndĩ vati ũmwe waaũmanya.'),
('kam', 'DAN', 9, 1, 'Mwaka wa mbee wa kũsumbĩka kwa Ndalio mwana wa Aasuelo, wa nzyawa sya Ametia, ũla waiiwe mũsumbĩ wa ũsumbĩko wa Akalitei,'),
('kam', 'DAN', 9, 2, 'mwaka wa mbee wa kũsumbĩka kwake nyie, Ndanieli, nĩnamanyĩiw’e nĩ mavuku ũtalo wa myaka, ĩla kwondũ wayo ndeto ya Yeova yookĩe mwathani Yelemia, kwondũ wa kwĩanĩsya mawanangĩko ma Yelusaleme, o myaka mĩongo mũonza.'),
('kam', 'DAN', 9, 3, 'Na nekalya ũthyũ wakwa welekele Mwĩaĩi Ngai ngĩmũmantha na mboya na mawĩsũvano, ngĩtĩĩa ũya na ngĩkĩa makunia na kwĩyũmba mũu.'),
('kam', 'DAN', 9, 4, 'Na navoya Yeova Ngai wakwa, na naumbũla, na nasya, Ame Mwĩaĩi, Ngai mũnene na wa kũkĩwa, ũla ũlilikanaa ũtianĩo na ũseo wĩ wendo kwa ala mamwendaa na kũkwataa mĩao yake,'),
('kam', 'DAN', 9, 5, 'nĩtuvĩtĩtye, na nĩtwĩkĩte naĩ, na nĩtwĩkĩte ũthũku, na nĩtũng’endete, o na kũvika kwathũkĩa mawĩaĩo maku na motw’ĩo maku;'),
('kam', 'DAN', 9, 6, 'o na tũtyaaĩthukĩĩsya athũkũmi maku athani, ala maneenie syĩtwanĩ yaku na asumbĩ maitũ, na anene maitũ me mbee ũsumbĩnĩ, na aasa maitũ, na andũ onthe ma nthĩ.'),
('kam', 'DAN', 9, 7, 'Ame Mwĩaĩi, ũlũngalu nĩ waku, ĩndĩ kwitũ nĩ kũsonoka ũthyũnĩ, o ta ũmũnthĩ; kwa andũ ma Yuta, na kwa ala matwĩe Yelusaleme, na kwa Isilaeli onthe, ala me vakuvĩ, na ala me kũasa, nthĩ syonthe ila wamalũngĩlĩĩlye, kwondũ wa ĩvĩtyo yoo yĩla makũvĩtanĩsye.'),
('kam', 'DAN', 9, 8, 'Ame Mwĩaĩi, kwitũ nĩ kũsonoka ũthyũnĩ, kwa asumbĩ maitũ, na kwa anene maitũ me mbee ũsumbĩnĩ, na kwa aasa maitũ, nũndũ nĩtwakũvĩtanĩsye.'),
('kam', 'DAN', 9, 9, 'Kwa Mwĩaĩi Ngai waitũ ve matei na ũekeo; nũndũ nĩtũmũng’endeete;'),
('kam', 'DAN', 9, 10, 'o na tũineew’ĩte wasya wa Yeova Ngai waitũ, nĩ kana tũendae mĩaonĩ yake, ĩla waiie mbee waitũ na athũkũmi make athani.'),
('kam', 'DAN', 9, 11, 'Ĩĩ, Isilaeli onthe nĩmavĩtĩtye mĩao yaku, kũvika kwathũka, matikew’e wasya waku: kwondũ wa ũu kĩumo nĩkyonoetwe ĩũlũ waitũ, na wĩvĩto ũla ũandĩkĩtw’e mĩaonĩ ya Mose mũthũkũmi wa Ngai; nũndũ nĩtũmũvĩtanĩsye.'),
('kam', 'DAN', 9, 12, 'Na nĩweanĩsye ndeto syake, ila watũneenee ithyĩ, na asili maitũ ala matũsilĩle, nĩ kũtũetee ũthũku mũnene; nũndũ ungu wa ĩtu yonthe kũiaaĩkĩka o tondũ kweekĩkie Yelusaleme.'),
('kam', 'DAN', 9, 13, 'O tondũ kũandĩkĩtwe mĩaonĩ ya Mose, ũthũku ũũ w’onthe ũnatũkĩe: ĩndĩ tũiaaĩsũva ĩnee ya Yeova Ngai waitũ, nĩ kana twĩthyũũe kuma mothũkunĩ maitũ. Kũmanya w’o waku.'),
('kam', 'DAN', 9, 14, 'Kwondũ wa ũu Yeova nũsyaĩĩasya ũla ũthũku, na akĩtũetee o w’o; nũndũ Yeova Ngai waitũ nĩ mũlũngalu mawĩanĩ make onthe ala wĩkaa, naitũ tũiaaĩw’a wasya wake.'),
('kam', 'DAN', 9, 15, 'Na yu, ame Mwĩaĩi Ngai waitũ, ũla waumisye andũ maku nthĩ ya Misili na kw’oko kwĩ vinya, na weeyosea ndaĩa, ta ũmũnthĩ; nĩtũvĩtĩtye, nĩtwĩkĩte ũthũku.'),
('kam', 'DAN', 9, 16, 'Ame Mwĩaĩi, kwĩanana na ũlũngalu waku w’onthe, nĩngũkũvoya, ũthatu waku na ũthilĩku waku ũthyũũwe kuma ndũa yaku Yelusaleme, kĩĩma kyaku kĩtheu; nĩkwĩthĩwa Yelusaleme na andũ maku matw’ĩkĩte kĩvũthya kwa onthe ala matũthyũlũlũkĩte ngalĩ sitũ syonthe, nũndũ wa naĩ sitũ, na nũndũ wa mothũku ma aasa maitũ.'),
('kam', 'DAN', 9, 17, 'Na yu ĩndĩ, ame Ngai waitũ, kwondũ wa Mwĩaĩi, ĩthukĩĩsye kũvoya kwa mũthũkũmi waku, na kwĩsũvana kwake, na ũitisasya ũthyũ waku ĩũlũ wa vala vandũ vatheu vaku vanangĩtwe.'),
('kam', 'DAN', 9, 18, 'Ame Ngai wakwa, tea kũtũ kwaku, wĩw’e; salukya metho maku, wone mawanangĩko maitũ, na ndũa ĩla ĩkwĩtanĩw’a na syĩtwa yaku: nĩkwĩthĩwa tũtiũete mboya sitũ vala ũĩ nũndũ wa ũlũngalu witũ, ĩndĩ nũndũ wa matei maku manene.'),
('kam', 'DAN', 9, 19, 'Ame Mwĩaĩi, ĩw’a; ame Mwĩaĩi, ekea; ame Mwĩaĩi, ĩthukĩĩsye, wĩke; kwondũ waku we, ndũketeele, ame Ngai wakwa, nũndũ ndũa yaku na andũ maku nĩmetanĩw’a na syĩtwa yaku.'),
('kam', 'DAN', 9, 20, 'Nakwa, ngĩneena, na ngĩvoya, na ngyumbũla naĩ yakwa na naĩ ya andũ makwa Isilaeli, na ngĩete wĩsũvano wakwa vala ve Yeova Ngai wakwa nũndũ wa kĩĩma kĩtheu kya Ngai wakwa;'),
('kam', 'DAN', 9, 21, 'ĩĩ, ngĩneena mboyete, mũndũ Kavilieli, ũla namwonie woninĩ wambĩlĩlyonĩ, akĩulũkĩthw’a mĩtũkĩ, angiita ta ĩvinda ya nthembo ya wĩoo.'),
('kam', 'DAN', 9, 22, 'Nake amanyĩthya, na aneena nakwa, na ambĩa, We Ndanieli, nĩnaumĩla oyu ngũnenge ũĩ na ũmanyi.'),
('kam', 'DAN', 9, 23, 'Wambĩlĩlyonĩ wa mawĩsũvano maku mwĩao nĩwaumiwe, nakwa nĩnooka kũkũtavya; nũndũ we nĩwendetwe mũno: kwondũ wa ũu sũanĩa ũndũ ũũ, na ũimanya woni.'),
('kam', 'DAN', 9, 24, 'Syumwa mĩongo mũonza nitw’ĩtwe ĩũlũ wa andũ maku na ĩũlũ wa ndũa yaku ntheu, sya kũminũkĩlya yĩla ĩvĩtyo, na kũvingĩa naĩ, na kwĩw’anĩthya kwondũ wa ũthũku, na kũete ũlũngalu wa tene na tene, na kũsiĩla woni na wathani, na kwĩtĩkĩsya mauta vala vandũ vatheu mbee.'),
('kam', 'DAN', 9, 25, 'Manya ĩndĩ ũvathũkan’ye, kana kuma mwĩao waumw’a wa kũtũngĩĩa na kwaka Yelusaleme kũvika ũla mwĩtĩkĩw’a mauta, ũla mũnene, kũkeethĩwa syumwa mũonza, na syumwa thanthatũ na ilĩ: nĩkakwa ĩngĩ, na nzĩa nene na ũvai mũlũmu, o mavindanĩ ma thĩna.'),
('kam', 'DAN', 9, 26, 'Na ĩtina wa syumwa mĩongo thanthatũ na ilĩ ũla mwĩtĩkĩw’a mauta nũkavetwa, o na nũkethĩwa ate na kĩndũ: na andũ ma mũnene ũla ũkoka nĩmakananga ndũa na vala vandũ vatheu; na mũminũkĩlyo waw’o nũkethĩwa na kĩw’ũ kingĩ, o na kũvika mũminũkĩlyo nĩkũkethĩwa kaũ; mawanangĩko nĩmatw’ĩtwe.'),
('kam', 'DAN', 9, 27, 'Nake nũkatianĩa ũtianĩo mũlũmu na aingĩ vandũ va kyumwa kĩmwe: na kyumwanĩ kyu katĩ nũkamina nthembo ya kũtonywa na nthembo ya mũtu; na nthwaunĩ sya mothatyo ũmwe ũla wĩkaa wanangĩko nũkoka; o na kũvika mũminũkĩlyo ki, naw’o nĩ ũla watwiwe, ũthilĩku nũkonow’a ĩũlũ wa mwene wanangĩko.'),
('kam', 'DAN', 10, 1, 'Mwaka wa katatũ wa kũsumbĩka kwa Kulusi mũsumbĩ wa Velisia, Ndanieli, ũla wetawa syĩtwa yake Mbelitesasa, avuanĩw’a ũndũ; na ũndũ ũsu waĩ wa w’o, naw’o waĩ kaũ mũnene: nake amanya ũndũ ũsu, na aĩ na ũmanyi wa ũla woni.'),
('kam', 'DAN', 10, 2, 'Matukũ asu nyie, Ndanieli, neethĩiwe na kĩmako syumwa itatũ nima.'),
('kam', 'DAN', 10, 3, 'Ndyaaya lĩu mũseo, o na nyama o na mbinyu ityaalika kanyw’anĩ wakwa, o na ndyaaĩvaka mauta nongi, mũvaka syumwa itatũ nima syeanĩa.'),
('kam', 'DAN', 10, 4, 'Na mũthenya wa mĩongo ĩlĩ na ĩna wa mwei wa mbee, yĩla naĩ ũtee wa ũsĩ mũnene, nĩw’o Itekeli,'),
('kam', 'DAN', 10, 5, 'nookĩlya metho makwa, noona, na, sisya, mũndũ ũmwe ekĩĩte ngũa ya katane, na kĩnyunyu kyake kĩvotoetwe thaavu mũtheu wa Uvasi:'),
('kam', 'DAN', 10, 6, 'mwĩĩ wake naw’o watilyĩ ta nzumalati ntheu, na ũthyũ wake ta kwoneka kwa ũtisi, na metho make ta mũĩ syakanĩte mwaki, na moko make na maũũ make ta ũthuku mũkute, na wasya wa ndeto syake ta wasya wa wingĩ wa andũ.'),
('kam', 'DAN', 10, 7, 'Nakwa, Ndanieli, nĩ nyioka noona woni; nũndũ andũ ala maĩ nakwa maiaaona woni; ĩndĩ kũtetema kũnene kwamavalũkĩla, na makĩa mevithe.'),
('kam', 'DAN', 10, 8, 'Nakwa natiwa nyioka, na noona woni ũsu mũnene, o na vaiaatiala vinya nthĩnĩ wakwa; nũndũ ũseo wakwa waalyũkile nthĩnĩ wakwa weethĩwa ũthũku, o na ndyaaĩthĩwa na vinya.'),
('kam', 'DAN', 10, 9, 'Ĩndĩ neew’a wasya wa ndeto syake; nakwa yĩla newie wasya wa ndeto syake, nĩvo ĩndĩ nakwatiwe nĩ too mũnene nĩvalũkĩte na ũthyũ wakwa, ũthyũ wakwa welekele nthĩ.'),
('kam', 'DAN', 10, 10, 'Na, sisya, kw’oko kwangiita, kũla kwambiie ĩũlũ wa mau makwa na ĩũlũ wa itaa sya moko makwa.'),
('kam', 'DAN', 10, 11, 'Nake ambĩa, Ndanieli, we mũndũ wendetwe mũno, manya ndeto ila ngũũtavya, naku ũngama ũlũngele; nũndũ natũmwa kwaku oyu. Na ĩndĩ andavya ndeto ĩsu, naũngama ngĩtetema.'),
('kam', 'DAN', 10, 12, 'Nĩvo ĩndĩ wambĩie, Ndanieli, ndũkakĩe; nũndũ kuma mũthenya wa mbee ũla waiie ngoo yaku kũmanya, na kwĩnyivya vala ve Ngai waku, ndeto syaku nĩsyeew’ĩkie: nakwa nooka kwondũ wa ndeto syaku.'),
('kam', 'DAN', 10, 13, 'Ĩndĩ mũnene wĩ mbee ũsumbĩnĩ wa ũsumbĩ wa Velisia anziĩĩa mĩthenya mĩongo ĩlĩ na ũmwe; ĩndĩ, sisya, Mikaeli, ũmwe wa anene, ooka kũndethya: nakwa nekala vau na asumbĩ ma Velisia.'),
('kam', 'DAN', 10, 14, 'Yu nĩnooka ũkũmanyĩthya ũla ũkakwata andũ maku mĩthenya ya mũminũkĩlyo; nũndũ woni nĩ wa ĩtina wa matukũ maingĩ.'),
('kam', 'DAN', 10, 15, 'Nake aneena nakwa ndeto ta isu, neelekelya ũthyũ wakwa nthĩ, ndaneenekya.'),
('kam', 'DAN', 10, 16, 'Na, sisya, ũmwe ũla ũilyĩ mũvw’ano wa ana ma andũ angiita ilomo syakwa: na ĩndĩ naathamya kanyw’a wakwa, na naneena na namwĩa ũla waũngyĩ mbee wakwa, We mwĩaĩi wakwa, nũndũ wa ũla woni mawoo makwa nĩmangalyũkĩla, o na ndi na vinya.'),
('kam', 'DAN', 10, 17, 'Nũndũ mũthũkũmi wa mwĩaĩi ũũ wakwa atonya ata kũneena na mwĩaĩi ũũ wakwa? Nũndũ ngalĩ ĩ yakwa, oyu kũiaatiala vinya nthĩnĩ wakwa, o na mĩthũmũ ndĩaaĩkala nthĩnĩ wakwa.'),
('kam', 'DAN', 10, 18, 'Nĩvo ĩndĩ wangiitie ĩngĩ ũmwe ũilyĩ mũvw’ano wa mũndũ, nake ambĩkĩa vinya.'),
('kam', 'DAN', 10, 19, 'Na ambĩa, We mũndũ ũla wendetwe mũno, ndũkakĩe: mũuo nĩwĩthĩwe kwaku, ĩthĩwa na vinya, ĩĩ, wĩthĩwe na vinya. Na akĩneena nakwa, neekĩwa vinya, na namwĩa, Mwĩaĩi wakwa naneene; nũndũ nĩwambĩkĩa vinya.'),
('kam', 'DAN', 10, 20, 'Na ĩndĩ angũlya, Nĩwĩsĩ kĩla kyatuma nũka kwaku? Na yu nĩngũsyoka nũkite na mũnene wĩ mbee ũsumbĩnĩ wa Velisia: nakwa yĩla nĩuma kw’o, sisya, mũnene wĩ mbee ũsumbĩnĩ wa Ngiliki akooka.'),
('kam', 'DAN', 10, 21, 'Ĩndĩ nĩngũkũtavya ũla ũandĩkĩtwe maandĩkonĩ ma w’o: o na vati wĩyĩkĩa vinya vamwe nakwa kwondũ wa maũndũ aa, ate o Mikaeli mũnene wenyu.'),
('kam', 'DAN', 11, 1, 'Nakwa nyie, mwaka wa mbee wa kũsumbĩka kwa Ndalio Mũmeti, naũngama kũmũlũlũmĩlya na kũmwĩkĩa vinya.'),
('kam', 'DAN', 11, 2, 'Na yu nĩngũkwon’ya ũla w’o. Sisya, makaũngama ĩtina asumbĩ atatũ kũu Velisia; na ũla wa kana akeethĩwa na ũthwii mwingĩ kũvĩta angĩ onthe: nake aya vinya kwondũ wa ũthwii wake, akaingĩanĩsya onthe mokite na ũsumbĩ wa Ngiliki.'),
('kam', 'DAN', 11, 3, 'Na mũsumbĩ wĩ vinya akaũngama, ũla wĩsumbĩka na ũsumbĩko mũnene, na kwĩka kwĩanana na kwenda kwake.'),
('kam', 'DAN', 11, 4, 'Na yĩla wĩũngama, ũsumbĩ wake ũkatilĩkana na ũkaaanw’a kwa iseve inya sya ĩtu, o na ti kwa mosyaanĩo make, o na ti kũatĩĩa ũsumbĩko wake ũla wasumbĩkĩte; nũndũ ũsumbĩ wake ũkakũwa, o na kwondũ wa angĩ eka asu.'),
('kam', 'DAN', 11, 5, 'Na mũsumbĩ wa ngalĩ ya ĩtheo akeethĩwa na vinya, na ũmwe wa anene make me mbee ũsumbĩnĩ; nake akeethĩwa na vinya kũmũvĩtũka, na akeethĩwa na ũsumbĩko; ũsumbĩko wake ũkeethĩwa wĩ ũsumbĩko mũnene.'),
('kam', 'DAN', 11, 6, 'Na mũminũkĩlyo wa myaka makalũman’ya; na mwĩĩtu wa mũsumbĩ wa ngalĩ ya ĩtheo akooka kwa mũsumbĩ wa ngalĩ ya ĩũlũ kwĩw’ana nake: ĩndĩ mwĩĩtu ndakaendeea na vinya wa kw’oko kwake; o na mũsumbĩ ndakaũngama, o na kw’oko kwake; ĩndĩ ũla mwĩĩtu akavetwa, o na ala mamũetie, o na ũla wamũsyaie, o na ũla wamwĩkĩie vinya mavinda asu.'),
('kam', 'DAN', 11, 7, 'Ĩndĩ kuma nthongoonĩ ya mĩi yake ũmwe akaũngama vandũ vake, ũla wĩũka na ita, na akalika ngomenĩ ya mũsumbĩ wa ngalĩ ya ĩũlũ, nake akameka maũndũ, na kũkĩlya vinya.'),
('kam', 'DAN', 11, 8, 'O na ngai syoo, vamwe na mĩvw’anano yoo ya syĩndũ itwekethetw’e, na mĩio yoo yĩ vata mũno ya vetha na thaavu, akatava atwae Misili; nake akaekana na mũsumbĩ wa ngalĩ ya ĩũlũ myaka ĩmwe.'),
('kam', 'DAN', 11, 9, 'Nake akalika ũsumbĩkonĩ wa mũsumbĩ wa ngalĩ ya ĩtheo, ĩndĩ akasyoka nthĩ yake mwene.'),
('kam', 'DAN', 11, 10, 'Na ana make makokita, na makoomban’ya wingĩ wa nguthu ila nene, ala meũka mateũtĩa, na kusũa, na kũvĩta mũkuthũ; namo makasyoka na kũkita, o na kũvika ngomenĩ yake.'),
('kam', 'DAN', 11, 11, 'Na mũsumbĩ wa ngalĩ ya ĩtheo akakwatwa nĩ ũthatu, na akaumaala na kũkita nake, o mũsumbĩ ũsu wa ngalĩ ya ĩũlũ; nake akaumya nguthu nene, na ĩla nguthu ĩkanenganwe kw’okonĩ kwake.'),
('kam', 'DAN', 11, 12, 'Na amina ũkũa ĩla nguthu, ngoo yake ĩkookĩlw’a; na akavalũkya ngili makũmi, ĩndĩ ndakakĩlya vinya.'),
('kam', 'DAN', 11, 13, 'Na mũsumbĩ wa ngalĩ ya ĩũlũ akasyoka, na akaumya nguthu nene kwĩ ĩla ya mbee; na akooka mũminũkĩlyonĩ wa mavinda, no myaka, e na ita nene na ũthwii mwingĩ.'),
('kam', 'DAN', 11, 14, 'Na mavindanĩ asu aingĩ makaũngama kũsiĩĩa mũsumbĩ wa ngalĩ ya ĩtheo: na ĩngĩ ana ma ang’endu katĩ wa andũ maku makeeyũkĩlya kũlũlũmĩlya ũla woni; ĩndĩ makavalũka.'),
('kam', 'DAN', 11, 15, 'Na ĩndĩ mũsumbĩ wa ngalĩ ya ĩũlũ akooka, na kũmba kĩvumbu, na kwosa ndũa mbiie nesa: o na okiti ma ngalĩ ya ĩtheo maikakĩlya vinya, o na andũ anyuve make, o na kũikethĩwa vinya wa kũkĩlya.'),
('kam', 'DAN', 11, 16, 'Ĩndĩ we ũla wũkĩte kũkita nake akeeka kwĩanana na kwenda kwake mwene, o na vati ũkaũngama mbee wake; nake akaũngama ĩla nthĩ nzeo, na kw’okonĩ kwake vakeethĩwa wanangĩko.'),
('kam', 'DAN', 11, 17, 'Na akeelekelya ũthyũ wake kũka na vinya wa ũsumbĩ wake w’onthe, na e na maũndũ ma ũlũngalu; nake akeeka ũu: nake akamũnenga mwĩĩtu wa aka, kũmwananga; ĩndĩ ndakaũngama, o na kwĩthĩwa ngalĩ yake.'),
('kam', 'DAN', 11, 18, 'Ĩtina wa ũu akathyũũa ũthyũ wake elekele ithama, na akoosa nyingĩ: ĩndĩ mũnene ũmwe wĩ mbee ũsumbĩnĩ akatuma kĩvũthya kĩla kyaetiwe nĩ ũsu kĩthela; ĩĩ, na ĩngĩ, akatuma kĩvũthya kyake kĩmũsyokea mwene.'),
('kam', 'DAN', 11, 19, 'Nĩvo ĩndĩ ũkathyũũa ũthyũ wake elekele ngome sya nthĩ yake mwene; ĩndĩ akatũlw’a na kũvalũka, na ndakoneka.'),
('kam', 'DAN', 11, 20, 'Nĩvo ĩndĩ ũmwe ũkaũngama vandũ vake ũla ũkavĩtĩlya mumya wa koti ndaĩanĩ ya ũsumbĩ; ĩndĩ ĩvinda ya matukũ mavũthũ akaanangĩka, ti kwondũ wa ũthatu, o na ti kwondũ wa kaũ.'),
('kam', 'DAN', 11, 21, 'Na vandũ vake mũndũ mũvũthye akaũngama, ũtaanengwa nĩmo ndaĩa ya ũsumbĩ: ĩndĩ akooka ĩvinda ya mũuo, na akoosa ũsumbĩ kwondũ wa kũkathĩĩanga.'),
('kam', 'DAN', 11, 22, 'Na nguthu ila ikĩlasya vinya ikakĩlw’a vinya mũno nĩwe, na ikatũlĩka; ĩĩ, o na mũnene wa ũtianĩo nake.'),
('kam', 'DAN', 11, 23, 'Na ĩtina wa kũseũvya wĩw’ano nake akeeka na ũkengani; nũndũ akambata na andũ avũthũ, na akeethĩwa na vinya.'),
('kam', 'DAN', 11, 24, 'Ĩvinda ya mũuo akooka o na kũvika kũla kũnou mbee kwa kĩlungu kyu kĩnene kya nthĩ; nake akeeka ũla aaĩthe make mataaĩka, o na aaĩthe ma aaĩthe make; akamaaan’ya syĩndũ sya mbuta, na mũtavo, na ũthwii: ĩĩ, akasũanĩa kwĩka ngome syĩ vinya maũndũ, kũvika ĩvinda.'),
('kam', 'DAN', 11, 25, 'Nake akakan’ya ũtonyi wake na ũnyiau wake elekele mũsumbĩ wa ngalĩ ya ĩtheo e na ita nene; nake mũsumbĩ wa ngalĩ ya ĩtheo akokita kaũ e na ita nene mũno, syĩ vinya; ĩndĩ ndakaũngama; nũndũ makamũsũanĩĩa maũndũ.'),
('kam', 'DAN', 11, 26, 'Ĩĩ, ala maĩsaa kya ũya kyake kĩseo makamwananga, na ita syake ikausũa itivũke; na aingĩ makavalũka me oae.'),
('kam', 'DAN', 11, 27, 'Na ũndũ wa asumbĩ asu elĩ, ngoo syoo ikeethĩwa sya kwĩka ũthũku, nao makaneena movũngũ me mesanĩ ĩmwe: ĩndĩ ndũkaathimĩka; nũndũ mũminũkĩlyo ũkeethĩwa wĩ o wa ĩvinda yĩla yatwiwe.'),
('kam', 'DAN', 11, 28, 'Nĩvo ĩndĩ ũkasyoka nthĩ yake na ũthwii mwingĩ; na ngoo yake ĩkeethĩwa yĩ na kĩmena na ũtianĩo mũtheu; na akeeka kwenda kwake, na kũsyoka nthĩ yake mwene.'),
('kam', 'DAN', 11, 29, 'Ĩvinda yĩla yatwiwe akasyoka, na kũvika ngalĩ ya ĩtheo; ĩndĩ ndũkethĩwa ĩvinda ya mũminũkĩlyo o tondũ weethĩiwe ĩvinda ya mbee.'),
('kam', 'DAN', 11, 30, 'Nũndũ ngalawa sya Kitimu nikoka kwake; nũndũ wa ũu akeew’ĩthw’a woo, na akasyoka, na akathilĩkĩa ũtianĩo mũtheu, na akeeka kwenda kwake: o na akasyoka, na kwĩthukĩĩsya ala matiĩte ũtianĩo mũtheu.'),
('kam', 'DAN', 11, 31, 'Na okiti makaũngama ngalĩ yake, nao makavukya vala vandũ vatheu, o na ngome, na makaveta nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na makaũngamya ũthatyo ũla wanangaa.'),
('kam', 'DAN', 11, 32, 'Na ala mekaa ũtianĩo naĩ akamasya na ndeto sya kũkathĩĩanga; ĩndĩ ala mesĩ Ngai woo makeethĩwa na vinya, na makeeka maũndũ manene.'),
('kam', 'DAN', 11, 33, 'Na ala me na ũĩ andũnĩ makamanyĩsya aingĩ; ĩndĩ makavalũkw’a mĩthenya mingĩ na ũvyũ na mwaki, na kũtavwa na kũvutwa.'),
('kam', 'DAN', 11, 34, 'Na ĩndĩ yĩla mevalũka, makatetheew’a na ũtethyo mũnini; ĩndĩ aingĩ makalũman’ya nao na ndeto sya kũkathĩĩana.'),
('kam', 'DAN', 11, 35, 'Na amwe ma ala oĩ makavalũka, matheethw’e, na kũthew’a, na kweũvw’a, o kũvika ĩvinda ya mũminũkĩlyo; nũndũ nĩ wa o yĩla ĩvinda yĩtw’ĩtwe.'),
('kam', 'DAN', 11, 36, 'Na mũsumbĩ akeeka kwĩanana na kwenda kwake; na akeetũlya, na kwĩnenevya ĩũlũ wa kĩla ngai, na akaneenea Ngai wa ngai maũndũ ma kũseng’ya; nake akaunĩka kũvika ũthilĩku wĩanĩw’e; nũndũ ũla watwiwe ũkeekwa.'),
('kam', 'DAN', 11, 37, 'O na ndakona ngai sya aaĩthe make ta kĩndũ, o na kwenda kwa aka, kana kwona ngai o na yĩva ta kĩndũ; nũndũ akeenenevya ĩũlũ wa syonthe.'),
('kam', 'DAN', 11, 38, 'Ĩndĩ vandũ vake akataĩa ngai ya i ngome; na ngai ĩla aaĩthe make matamĩsĩ akataĩa na thaavu, na vetha, na tũvila twĩ thooa mũnene na syĩndũ sya kwendeesya.'),
('kam', 'DAN', 11, 39, 'Na akatwaatwaana na ngome ila syĩ vinya mbee kwondũ wa ũtethyo wa ngai ngeni: o ũla wĩmwĩtĩkĩla akamwongela ndaĩa; na akamasumbĩkĩthya aingĩ, na akaaan’ya nthĩ kwondũ wa ĩtuvi.'),
('kam', 'DAN', 11, 40, 'Na ĩvinda ya mũminũkĩlyo mũsumbĩ wa ngalĩ ya ĩtheo nũkakĩlan’ya vinya nake; na mũsumbĩ wa ngalĩ ya ĩũlũ nũkoka ta kĩlingi okite nake, e na makasya ma kaũ, na ala matũlĩte mbalasi, na ngalawa nyingĩ; nake nũkavota nthĩ isu, na kusũa na kũvĩtĩla mũkuthũ.'),
('kam', 'DAN', 11, 41, 'Nake nũkavota ĩ nthĩ nzeo, na nthĩ nyingĩ nikakũlumanw’a; ĩndĩ ii nikatangĩĩwa kuma kw’okonĩ kwake: Etomu, na Moavi, na ala me mbee ma ana ma Amimoni.'),
('kam', 'DAN', 11, 42, 'Na ĩngĩ nũkatambũũkya kw’oko kwake ĩũlũ wa i nthĩ; na nthĩ ya Misili ndĩkavonoka.'),
('kam', 'DAN', 11, 43, 'Ĩndĩ nũkethĩwa na ũtonyi mothwiinĩ maie ma thaavu na ma vetha, na syĩndũnĩ syonthe syĩ vata sya Misili; na Alivia na Aethiovia nĩmakethĩwa makĩmũatĩĩa.'),
('kam', 'DAN', 11, 44, 'Ĩndĩ maũvoo ala makauma wumĩlonĩ wa syũa na ala makauma ngalĩ ya ĩũlũ nĩmakamũthĩn’ya; nake nũkauma athi na ũthilĩku mũnene kwananga na kũmaveta vyũ aingĩ.'),
('kam', 'DAN', 11, 45, 'Na nũkamba maeema ma nyũmba yake nene mbanakavye katĩ wa ũkanga na kĩla kĩĩma kĩseo kĩtheu; ĩndĩ nũkavika mũminũkĩlyo wake, na vati ũmwe ũkamũtethya.'),
('kam', 'DAN', 12, 1, 'Na ĩvinda yĩu Mikaeli nũkaũngama, ũla mũnene wĩ mbee mũno ũsumbĩnĩ ũla ũũngamaa kwondũ wa ana ma andũ maku; na nĩkũkethĩwa ĩvinda ya thĩna, o tondũ ũtaaĩthĩwa kuma kweethĩwa mbaĩ kũvika ĩvinda o yĩu: na ĩvinda yĩu andũ maku nĩmakatangĩĩwa, kĩla ũmwe ũkoneka aandĩkĩtwe ĩvukunĩ.'),
('kam', 'DAN', 12, 2, 'Na aingĩ ma ala makomaa kĩtoonĩ kya nthĩ nĩmakaamũka, amwe kũvika thayũ ũtathela, na amwe kũvika kũsonoka na kũvũthw’a kũtakathela.'),
('kam', 'DAN', 12, 3, 'Na ala oĩ nĩmakatisa ta ũtisu wa yayaya; na ala maalyũlaa aingĩ methĩwe na ũlũngalu nĩmakatisa ta ndata tene na tene.'),
('kam', 'DAN', 12, 4, 'Ĩndĩ we, we Ndanieli, vingĩa ndeto, na siĩla ĩvuku, o kũvika ĩvinda ya mũminũkĩlyo: aingĩ makasemba kũũ na kũũ, na ũmanyi ũkongeleka.'),
('kam', 'DAN', 12, 5, 'Nĩvo ĩndĩ nyie, Ndanieli, noonie, na, sisya, angĩ elĩ maũngama, ũmwe ngũkanĩ ya ũsĩ mũingo ũũ, na ũngĩ ngũkanĩ ya ũsĩ mũingo ũya.'),
('kam', 'DAN', 12, 6, 'Na ũmwe amwĩa ũla wekĩĩte ngũa sya katane, ũla waĩ ĩũlũ wa manzĩ ma ũsĩ, Nĩ kũvika ĩndĩĩ mũminũkĩlyo wa moseng’ya aa?'),
('kam', 'DAN', 12, 7, 'Nakwa neew’a mũndũ ũla wekĩĩte ngũa sya katane, ũla waĩ ĩũlũ wa manzĩ ma ũsĩ, yĩla wokĩlilye kw’oko kwake kwa aũme na kw’oko kwake kwa aka elekelye ĩtunĩ, na eevĩta kwa ũla wĩkalaa tene na tene kana kũkeethĩwa ĩvinda, na mavinda, na nyunzu ya ĩvinda; namo mamina kwananga ũtonyi wa ala andũ atheu, maũndũ aa onthe nĩmakeanĩw’a.'),
('kam', 'DAN', 12, 8, 'Nakwa neew’a, ĩndĩ ndyaamanya: nĩvo ĩndĩ nakũlilye, We mwaĩaĩi wakwa, mũminũkĩlyo wa maũndũ aa nĩ mwaũ?'),
('kam', 'DAN', 12, 9, 'Nake asũngĩa, Ĩendee, we Ndanieli; nũndũ ndeto nĩsyavingĩwa na kũsiĩlwa kũvika ĩvinda ya mũminũkĩlyo.'),
('kam', 'DAN', 12, 10, 'Aingĩ makeethesya, na kwĩyeũvya, na kũtheethw’a; ĩndĩ athũku makeeka ũthũku; o na vati ũmwe wa ala athũku ũkamanya; ĩndĩ ala oĩ nĩmakamanya.'),
('kam', 'DAN', 12, 11, 'Na kuma ĩvinda yĩla nthembo ya kũvĩvw’a ĩtatw’ĩkanaa ĩkavetwa, na ũthatyo wĩkaa wanangĩko ũkaũngamwa, nĩkũkethĩwa nĩ mĩthenya ngili na maana elĩ na mĩongo kenda.'),
('kam', 'DAN', 12, 12, 'Nĩ mũathime ũla weteelaa, na kũvika mĩthenya ĩsu ngili na maana atatũ na mĩongo ĩtatũ na ĩtano.'),
('kam', 'DAN', 12, 13, 'Ĩndĩ ĩendee, we, kũvika mũminũkĩlyo; nũndũ nũkathũmũa, na kũũngama kĩandanĩ kyaku, mũminũkĩlyo wa mĩthenya.'),
('kam', 'HOS', 1, 1, 'Ndeto ya Yeova ĩla yamũkĩe Osea mwana wa Veeli, mĩthenya ya Usia, na Yothamu, na Aasu, na Esekia, asumbĩ ma Yuta, na mĩthenya ya Yelovoamu mwana wa Yoasi, mũsumbĩ wa Isilaeli.'),
('kam', 'HOS', 1, 2, 'Yĩla Yeova waneenie ĩ ya mbee na kanyw’a wa Osea, Yeova amwĩa Osea, Enda, wĩtwaĩe kĩveti ĩlwaya na syana sya ũmalwaya; nũndũ ĩ nthĩ nĩyĩkaa ũmalwaya mũno, ĩkĩmũtia Yeova.'),
('kam', 'HOS', 1, 3, 'Na ĩndĩ aenda na atwaa Ngomeli mwĩĩtu wa Ndivilaimu; nake aitava, na amũsyaĩa mwana.'),
('kam', 'HOS', 1, 4, 'Na Yeova amwĩa, Mwĩte syĩtwa yake Yesileeli; nũndũ no vandũ vanini, na ngaĩvanĩsya nthakame ya Yesileeli nyũmbanĩ ya Yeu, na ngatuma ũsumbĩ wa nyũmba ya Isilaeli ũthela.'),
('kam', 'HOS', 1, 5, 'Na kũkeethĩwa mũthenya ũsu, ngatũlĩla ũta wa Isilaeli mwandanĩ wa Yesileeli.'),
('kam', 'HOS', 1, 6, 'Na aitava ĩngĩ, na asyaa mwĩĩtu. Na Yeova amwĩa, Mwĩte syĩtwa yake Lo‐luama; nũndũ ndikambĩla kwĩw’ĩa nyũmba ya Isilaeli tei ĩngĩ, nĩmaekee kwondũ wa ũndũ o na wĩva.'),
('kam', 'HOS', 1, 7, 'Ĩndĩ ngeew’ĩa nyũmba ya Yuta tei, na ngamatangĩĩa na vinya wa Yeova Ngai woo, na ndikamatangĩĩa na ũta, kana ũvyũ, kana kaũ, kana mbalasi, kana ala matũlĩte mbalasi.'),
('kam', 'HOS', 1, 8, 'Na ĩndĩ yĩla wamũaĩisye Lo‐luama, aitava na asyaa mwana.'),
('kam', 'HOS', 1, 9, 'Na Yeova asya, Mwĩte syĩtwa yake Lo‐amimi; nũndũ inyw’ĩ mũti andũ makwa, na ndikethĩwa Ngai wenyu.'),
('kam', 'HOS', 1, 10, 'Ĩndĩ ũtalo wa ana ma Isilaeli ũkeethĩwa ta kĩthangathĩ kya ũkanga, kĩla kĩtathimĩka kana kũtalĩka; na kũkeethĩwa vala meeiwe, Mũti andũ makwa, makeewa, Mwĩ ana ma Ngai ũla wĩ thayũ.'),
('kam', 'HOS', 1, 11, 'Na ana ma Yuta na ana ma Isilaeli makoombanw’a vamwe, na makeeyiĩa mũtongoi ũmwe, na makambata kuma nthĩ ĩsu; nũndũ mũthenya wa Yesileeli ũkeethĩwa mũnene.'),
('kam', 'HOS', 2, 1, 'Matavyei ana‐a‐ĩthe menyu, Amimi; na eĩtu‐a‐inyia menyu, Luama.'),
('kam', 'HOS', 2, 2, 'Tetan’yai na inyia wenyu, tetan’yai; nũndũ ti kĩveti kyakwa, o nakwa ndi mũũme wake; na navete ũmalwaya wake ũthyũnĩ wake, na maũlaalai make katĩ wa nondo syake;'),
('kam', 'HOS', 2, 3, 'ndikese ũmũvua ethĩwe mũthei, na kũmwĩkalya o ta mũthenya ũla wasyaiwe, na kũmũtw’ĩkĩthya ta weũ, na kũmwĩkalya ta nthĩ nyũmũ, na kũmũaa na waũni.'),
('kam', 'HOS', 2, 4, 'Ĩĩ, ndikew’ĩa syana syake tei; nũndũ nĩ syana sya ũmalwaya;'),
('kam', 'HOS', 2, 5, 'nũndũ inyia wasyo nĩwekie ũmalwaya; ũla waiitavie nĩwekie ũndũ wĩ nthoni; nũndũ aisye, Nĩngũatĩĩa endwa makwa, ala manengae lĩu wakwa na kĩw’ũ kyakwa, na w’ĩa wakwa wa ĩlondu, na katane yakwa, na mauta makwa na kya ũnyw’a kyakwa.'),
('kam', 'HOS', 2, 6, 'Kwondũ wa ũu, sisya, ngaiia nzĩa yaku na mĩw’a, na ngamwakĩĩa ũvai, nĩ kana ndakone nzĩa syake.'),
('kam', 'HOS', 2, 7, 'Na akaatĩĩa endwa make, ĩndĩ ndakamawĩla; na akamamantha, ĩndĩ ndakamona: nĩvo wĩasya, Nĩngũenda nĩsyokee mũũme wakwa wa mbee; nũndũ ĩvinda yĩu kwaĩ kavaa kwakwa kwĩ yu.'),
('kam', 'HOS', 2, 8, 'Nũndũ ndaamanya kana nĩnamũnengaa lĩu wa mbaa ngetha, na mbinyu mbĩthĩ, na mauta, na kũmwingĩvĩsya vetha na thaavu, ila maumĩasya Mbaali.'),
('kam', 'HOS', 2, 9, 'Kwondũ wa ũu ngatũnga lĩu wakwa wa mbaa ngetha ĩvinda yaw’o, na mbinyu yakwa mbĩthĩ ĩvinda yayo, na ngaveta w’ĩa wakwa wa ĩlondu na katane yakwa ĩla ĩnaĩ ya kũmũvw’ĩka e mũthei.'),
('kam', 'HOS', 2, 10, 'Nakwa yu ngamũvua kwake kwĩ nthoni endwa make mene, na kũti ũmwe wĩmũtangĩĩa kuma kw’okonĩ kwakwa.'),
('kam', 'HOS', 2, 11, 'O na ĩngĩ ngatuma ũtanu wake w’onthe ũthela, mboka syake, na mboka syake sya mĩtiso ya myei, na masavato make, na maũmbano make onthe matw’ĩtwe.'),
('kam', 'HOS', 2, 12, 'Na ngaananga mĩsavivũ yake na mĩkũyũ yake, ĩla kwondũ wayo ũneenete, Ĩno nĩyo ĩtuvi yakwa yĩla endwa makwa manengete; na ngamĩtw’ĩkĩthya mũtitũ, na nyamũ sya kĩtheka ikamĩya.'),
('kam', 'HOS', 2, 13, 'Na ngeeĩvanĩsya kwake mĩthenya ya Mbaalimu, ila watoeesye ũvani, yĩla weseũvĩsye mwene na ngome sya matũ, na mĩio yake ya wanake, na kũatĩĩa endwa make, na oolwa ninyie, easya ũu Yeova.'),
('kam', 'HOS', 2, 14, 'Kwondũ wa ũu, sisya, ngamũkusya na ũĩ, na kũmũtwaa weũnĩ, na kũneena nake na ndeto sya ũkiakisyo.'),
('kam', 'HOS', 2, 15, 'Na ngamũnenga mĩũnda yake ya mĩsavivũ kw’o, na mwanda wa Akoli ũtw’ĩke mũomo wa wĩkwatyo; na akeetika e kw’o, o ta mĩthenyanĩ ya wana wake, na ta mũthenya ũla wambatie kuma nthĩ ya Misili.'),
('kam', 'HOS', 2, 16, 'Na kũkeethĩwa mũthenya ũsu, ũkambĩta Isi, na ndũkambĩta ĩngĩ Vaali, easya ũu Yeova.'),
('kam', 'HOS', 2, 17, 'Nũndũ ngaveta masyĩtwa ma Mbaalimu kanyw’anĩ wake, na itikawetwa ĩngĩ na masyĩtwa masyo.'),
('kam', 'HOS', 2, 18, 'Na mũthenya ũsu ngatianĩa ũtianĩo na nyamũ sya kĩtheka kwondũ woo, na nyũnyi sya yayaya, o na tũsamũ twa nthĩ tũla tũtambũkaa; na ũta na ũvyũ na kaũ ngaitũla syume nthĩ, na ngatuma makoma vate mũisyo.'),
('kam', 'HOS', 2, 19, 'Na ngakwĩvasya wĩthĩwe wakwa tene na tene; ĩĩ, ngakwĩvasya na ũlũngalu, na ũsili wa katĩ, na ũseo wĩ wendo, na matei, wĩthĩwe wakwa.'),
('kam', 'HOS', 2, 20, 'O na ngakwĩvasya na kĩthito wĩthĩwe wakwa; na ũkamũmanya Yeova.'),
('kam', 'HOS', 2, 21, 'Na kũkeethĩwa mũthenya ũsu, ngasũngĩa, easya ũu Yeova, ngasũngĩa matu, namo makasũngĩa nthĩ;'),
('kam', 'HOS', 2, 22, 'na nthĩ ĩkasũngĩa lĩu wa mbaa ngetha, na mbinyu mbĩthĩ, na mauta; nasyo ikasũngĩa Yesileeli.'),
('kam', 'HOS', 2, 23, 'Na ngamũvanda nthĩ kwondũ wakwa; na ngamwĩw’ĩa tei ũla ũtaaĩw’ĩwa tei; na ngamea ala mataĩ andũ makwa, Mwĩ andũ makwa; na makasya, Wĩ Ngaĩ wakwa.'),
('kam', 'HOS', 3, 1, 'Na Yeova ambĩa, Enda ĩngĩ, ũmwende mũndũ mũka, kĩlaalai, wendetwe nĩ mũnyanyae, o tondũ Yeova wendete ana ma Isilaeli, o na kau methyũũĩaa ngai ingĩ, na kwenda tũkũmbwa twa nzavivũ mbovu.'),
('kam', 'HOS', 3, 2, 'Na ĩndĩ namwĩthooee we na ilungu ĩkũmi na itano sya vetha, na omeli ya mbaale, na nyunzu ya omeli ya mbaale;'),
('kam', 'HOS', 3, 3, 'na namwĩa, Ukekala nũndũ wakwa mĩthenya mingĩ; ndũkeka ũmalwaya, na ndũkethĩwa kĩveti kya mũndũ ũngĩ: nakwa kwaku ngeethĩwa o ta ũu.'),
('kam', 'HOS', 3, 4, 'Nũndũ ana ma Isilaeli makekala mĩthenya mingĩ mate na mũsumbĩ, na mate na mũnene wa mbee ũsumbĩnĩ, na mate na nthembo, na mate na kĩtuĩ, na mate na evoti kana telavimu:'),
('kam', 'HOS', 3, 5, 'ĩtina wa ũu ana ma Isilaeli makasyoka, na kũmantha Yeova Ngai woo, na Ndaviti mũsumbĩ woo, na makooka kwa Yeova na ũseo wake me na kĩkĩo mĩthenyanĩ ya mũminũkĩlyo.'),
('kam', 'HOS', 4, 1, 'Ĩw’ai ndeto ya Yeova, inyw’ĩ ana ma Isilaeli; nũndũ Yeova e na ngananĩo na ala matwĩe ĩ nthĩ, nũndũ kũti w’o, kana ũseo, kana ũmanyi wa Ngai ĩ nthĩ.'),
('kam', 'HOS', 4, 2, 'Kũti ũndũ ũngĩ no kwĩavaa, na kwanangaa wĩw’ano, na kũaaa, na kũyaa, na kwĩkaa ũlaalai; nĩmeyalĩlasya, na nthakame nikwataa nthakame.'),
('kam', 'HOS', 4, 3, 'Kwondũ wa ũu nthĩ ĩkameta, na kĩla ũmwe ũla ũmĩtwĩe akaaa vinya, vamwe na nyamũ sya kĩtheka na nyũnyi sya yayaya; ĩĩ, na makũyũ ma ũkanga nao makavetwa.'),
('kam', 'HOS', 4, 4, 'Ĩndĩ kũikethĩwe mũndũ kũtetan’ya, kana mũndũ o na wĩva kũkan’ya; nũndũ andũ maku nĩ ta ala matetanasya na mũthembi.'),
('kam', 'HOS', 4, 5, 'Naku ũkalulutĩka mũthenya, na mwathani nake akalulutĩka vamwe naku ũtukũ; nakwa ngaananga inyia waku.'),
('kam', 'HOS', 4, 6, 'Andũ makwa nĩmanangawa nĩ kwaa ũmanyi: nĩkwĩthĩwa nĩwaleile ũmanyi, o nakwa ngakũlea, nĩ kana ndũkethĩwe mũthembi kwakwa: nũndũ nĩwũlĩtwe nĩ mĩao ya Ngai waku, o nakwa ngoolwa nĩ syana syaku.'),
('kam', 'HOS', 4, 7, 'O tondũ maingĩvie, now’o mambĩtanĩsye: ngaalyũla ndaĩa yoo ĩtw’ĩke nthoni.'),
('kam', 'HOS', 4, 8, 'Maĩsaa naĩ ya andũ makwa, na kwenda mũno ngoonĩ syoo ũthũku woo.'),
('kam', 'HOS', 4, 9, 'Na kũkeethĩawa, o ũndũ andũ mailyĩ, now’o mũthembi; nakwa ngamasilĩla nũndũ wa mĩendele yoo, na ngamaĩva o meko moo.'),
('kam', 'HOS', 4, 10, 'Na makaya, na matikavũna; makeeka ũmalwaya, na matikongeleka; nĩkwĩthĩwa nĩmaekie kũmwĩw’a Yeova.'),
('kam', 'HOS', 4, 11, 'Ũmalwaya na mbinyu na mbinyu mbĩthĩ nivetaa ũmanyi.'),
('kam', 'HOS', 4, 12, 'Andũ makwa nĩmakũlasya kĩthukĩ kyoo ũtao, na ndata yoo nĩmavuanĩasya; nũndũ veva wa ũmalwaya nũmavĩtĩthasya, na nĩmekaa ũmalwaya, makyuma ungu wa Ngai woo.'),
('kam', 'HOS', 4, 13, 'Nĩmathembaa iĩmanĩ ĩũlũ, na kũtoeesya ũvani ĩũlũ wa tũlĩma, ĩtina wa mĩtĩ ya myaloni na mĩlivina na mĩelo, nĩkwĩthĩwa muunyĩ wayo nĩ mũseo: kwondũ wa ũu eĩtu menyu nĩmekaa ũmalwaya, na atwawa menyu nĩmekaa ũlaalai.'),
('kam', 'HOS', 4, 14, 'Ndikasilĩla eĩtu menyu meeka ũmalwaya, kana atwawa menyu meeka ũlaalai; nũndũ o namo ene maendaa mwathũko na malwaya, na makĩthemba me na malwaya; na andũ ala mate na ũmanyi makaanangwa.'),
('kam', 'HOS', 4, 15, 'O na kau we, Isilaeli, nĩwĩkaa ũmalwaya, ĩndĩ Yuta ndakavĩtye; na mũtikoke Ngilikali, o na mũtikambate Mbethi‐aveni, kana kwĩvĩta, mũkyasya, O tondũ Yeova wĩ thayũ.'),
('kam', 'HOS', 4, 16, 'Nũndũ Isilaeli nĩwekie ũng’endu, o ta moi ng’endu: yu Yeova akamaĩthya ta katena ka ĩlondu vandũ vaamu.'),
('kam', 'HOS', 4, 17, 'Evalaimu nũkwatene na mĩvw’anano; mũeke.'),
('kam', 'HOS', 4, 18, 'Kya ũnyw’a kyoo nĩkĩkaatĩte; nĩmekaa ũmalwaya ĩndĩ yonthe; asumbĩki make nĩmendaa mũno maũndũ me nthoni.'),
('kam', 'HOS', 4, 19, 'Kĩseve nĩkĩmũlingalingĩte nthwaunĩ syakyo; na makasonokw’a nũndũ wa nthembo syoo.'),
('kam', 'HOS', 5, 1, 'Ĩw’ai ũũ, inyw’ĩ athembi, na ĩthukĩĩsye, nyũmba ya Isilaeli, na tea kũtũ, nyũmba ya mũsumbĩ; nũndũ ũsilĩlo nũmwelekele; nũndũ mũtw’ĩkĩte kĩtei ku Misiva, na kĩtei kyalanĩtw’e ĩũlũ wa Tavoli.'),
('kam', 'HOS', 5, 2, 'Na alei nĩmalikĩte mũno ũainĩ; ĩndĩ nyie nĩ mũkan’ya wa onthe.'),
('kam', 'HOS', 5, 3, 'Nĩnĩmwĩsĩ Evalaimu, na Isilaeli ndembithĩte; nũndũ yu, we Evalaimu, nĩwĩkĩte ũmalwaya, Isilaeli nũvukĩtw’e.'),
('kam', 'HOS', 5, 4, 'Meko moo maikamaeka methyũũĩe Ngai woo; nũndũ veva wa ũmalwaya wĩ nthĩnĩ woo, na maimwĩsĩ Yeova.'),
('kam', 'HOS', 5, 5, 'Na ngathĩĩo sya Isilaeli nĩkũsĩĩaa mbee wa ũthyũ wake: kwondũ wa ũu Isilaeli na Evalaimu makalulutĩka ũthũkunĩ woo; nake Yuta akalulutĩka vamwe nao.'),
('kam', 'HOS', 5, 6, 'Makaenda na ndĩthya syoo sya mbũi na malondu na ndĩthya syoo sya ng’ombe mamũmanthe Yeova; ĩndĩ matikamwona: nĩwĩvathanĩte nao.'),
('kam', 'HOS', 5, 7, 'Nĩmekĩte Yeova ũseleke; nũndũ nĩmasyaĩte syana ngeni: yu mwei mũtisu ũkamamina vamwe na mĩũnda yoo.'),
('kam', 'HOS', 5, 8, 'Vuvĩai soo mũkelemu Ngivea, na soo Lama: na mũivuvĩa soo wĩ wasya wa kũtĩsya Mbethi‐aveni; ĩtina waku, we Mbenyamini.'),
('kam', 'HOS', 5, 9, 'Evalaimu akatw’ĩka ĩanzo mũthenya wa ũkan’yo: katĩ wa mbaĩ sya Isilaeli nĩnĩtavanĩtye ũndũ wĩĩthĩwa vate ndĩi.'),
('kam', 'HOS', 5, 10, 'Anene me mbee ũsumbĩnĩ ma Yuta mailyĩ ta ala makũĩĩasya kyambo kya mũvaka: ngamonoesya kũthilĩka kwakwa ta kĩw’ũ.'),
('kam', 'HOS', 5, 11, 'Evalaimu nũthĩnĩtw’e, nũtumbĩĩwe ũsilĩlonĩ; nĩkwĩthĩwa nĩwendeew’e nĩ kũatĩĩa mwĩao wa mũndũ.'),
('kam', 'HOS', 5, 12, 'Kwondũ wa ũu nyie kwa Evalaimu nĩilyĩ lungulu, na kwa nyũmba ya Yuta nĩilyĩ wou.'),
('kam', 'HOS', 5, 13, 'Yĩla Evalaimu wonie ũwau wake, na Yuta wonie wũkite wake, nĩvo Evalaimu waendie Asuli, na atũmana kwa mũsumbĩ Yalevu: ĩndĩ ndatonya kũkũvosya, o na ndakakũvosya wũkite waku.'),
('kam', 'HOS', 5, 14, 'Nũndũ ngeethĩwa kwa Evalaimu nĩilyĩ mũnyambũ, na ta mũnyambũ wa mũika kwa nyũmba ya Yuta: nyie, o nyie, ngatembũanga na ngĩthi; ngakua ndwae, na kũikethĩwa wa kũtangĩĩa.'),
('kam', 'HOS', 5, 15, 'Ngaenda nĩsyoke vandũ vakwa, mũvaka meetĩkĩla ĩvĩtyo yoo, na kũmantha ũthyũ wakwa: thĩnanĩ woo makamantha na kĩthing’ĩĩsyo.'),
('kam', 'HOS', 6, 1, 'Ũkai, na tũimũsyokea Yeova; nũndũ nũtũtembũĩte, na akatũvosya; nũtũkũnĩte, na akatwova.'),
('kam', 'HOS', 6, 2, 'Ĩtina wa mĩthenya ĩlĩ akatũvuũkya: mũthenya wa katatũ akatũkĩlya, na tũkeethĩwa thayũ mbee wake.'),
('kam', 'HOS', 6, 3, 'Na tũmanyei, ĩĩ, tũatĩĩei kũmũmanya Yeova: kumĩla kwake kũitĩa o ta kũkya; na akatũkĩa o ta mbua, ta mbua ya uũa ĩla ĩkolasya nthĩ.'),
('kam', 'HOS', 6, 4, 'We Evalaimu, nĩkwĩka ata? We Yuta, nĩkwĩka ata? Nũndũ ũseo wenyu nĩ ta ĩthweo ya kĩoko, na ta ĩmwe yĩla yĩtw’ĩkaa tene.'),
('kam', 'HOS', 6, 5, 'Kwondũ wa ũu nĩnamatemie na athani; nĩnamoaie na ndeto sya kanyw’a wakwa: na mosili maku nĩ ta kyeni kĩla kyumĩlaa.'),
('kam', 'HOS', 6, 6, 'Nũndũ nyie nendaa ũseo, na ti nthembo; na kũmanya Ngai kwĩ nthembo sya kũvĩvw’a.'),
('kam', 'HOS', 6, 7, 'Ĩndĩ nĩmavĩtĩtye ũtianĩo o ta Atamu: nĩvo mambĩkĩte ũseleke.'),
('kam', 'HOS', 6, 8, 'Ngileati nĩ ndũa ya ala mekaa ũthũku; nĩkwatangĩtw’e nthakame.'),
('kam', 'HOS', 6, 9, 'Na o tondũ nguthu sya avutani syoveesyaa mũndũ, now’o nguthu ya athembi moaĩaa nzĩanĩ kwelekela Sekemu; ĩĩ, nĩmekĩte wathe.'),
('kam', 'HOS', 6, 10, 'Nĩnonete ũndũ ũthũku nũmo nyũmbanĩ ya Isilaeli: nĩkwonekete ũmalwaya vu kwa Evalaimu, Isilaeli nũvukĩtw’e.'),
('kam', 'HOS', 6, 11, 'Na ĩngĩ, we Yuta, ve ngetha wiĩwe, yĩla nĩtũnga andũ makwa kuma kũtavwanĩ kwoo.'),
('kam', 'HOS', 7, 1, 'Yĩla nenda kũvosya Isilaeli, nĩvo ũthũku wa Evalaimu ũkumĩla, na ũthũku wa Samalia; nũndũ nĩmekaa ũkengani, na kĩng’ei nĩkĩlikaa nthĩnĩ, na nguthu ya avutani ĩkyanangĩla nza.'),
('kam', 'HOS', 7, 2, 'Na matisũanĩaa ngoonĩ syoo kana nĩnĩlilikene ũthũku woo w’onthe: yu meko moo ene nĩmamathyũlũlũkĩte; me mbee wa ũthyũ wakwa.'),
('kam', 'HOS', 7, 3, 'Nĩmeũtanĩthya mũsumbĩ na ũthũku woo, na kũtanĩthya anene me mbee ũsumbĩnĩ na movũngũ moo.'),
('kam', 'HOS', 7, 4, 'Onthe nĩ ilaalai; mailyĩ ta iko yĩlaatĩkĩtw’e nĩ mũui wa mĩkate; aekaa kũkitĩanĩsya mwaki, kuma ailitya ngũmbwa, kũvika waimba.'),
('kam', 'HOS', 7, 5, 'Mũthenya wa mũsumbĩ waitũ anene me mbee ũsumbĩnĩ nĩmeewaisye na muutĩa wa mbinyu; atambũũkisye kw’oko kwake vamwe na akaakaan’ya.'),
('kam', 'HOS', 7, 6, 'Nũndũ nĩmaseũvĩtye ngoo syoo o ta iko, ĩvinda yĩla moveesye: mũui woo wa mĩkate nũkomaa ũtukũ mũima; na kĩoko yĩkyakana ta itw’ĩki sya mwaki.'),
('kam', 'HOS', 7, 7, 'Onthe nĩ avyũ ta iko, na maminaa asili moo; asumbĩ moo onthe nĩ avalũku: na vati ũmwe katĩ wamo wĩngaĩlaa.'),
('kam', 'HOS', 7, 8, 'Evalaimu, nake nũkwĩvulan’ya na ngo sya andũ; Evalaimu nĩ kamũtũ kate kaalyũle.'),
('kam', 'HOS', 7, 9, 'Aeni nĩmaminĩte vinya wake, na ndesĩ: ĩĩ, mbuĩ syĩ vaa na vaa kwake, na ndesĩ.'),
('kam', 'HOS', 7, 10, 'Na ngathĩĩo sya Isilaeli nikũsĩĩaa mbee wa ũthyũ wake: ĩndĩ o na ũu w’onthe matisyokete kwa Yeova Ngai woo, o na kũmũmantha.'),
('kam', 'HOS', 7, 11, 'Na Evalaimu ailyĩ ĩvũĩ ĩtumanu, yĩte na ũmanyi: nĩmekaĩlaa Misili, o na maendaa Asuli.'),
('kam', 'HOS', 7, 12, 'Yĩla methi, ngalan’ya kĩtei kyakwa ĩũlũ wamo; ngamatheesya nthĩ ta nyũnyi sya yayaya; ngamasilĩla, o tondũ ũmbano woo wĩw’ĩte.'),
('kam', 'HOS', 7, 13, 'Woo nĩ woo! Nũndũ nĩmandiie; wanangĩko nĩ woo! Nũndũ nĩmambĩtanĩsye: o na kau nĩnenda kũmovosya, ĩndĩ nĩmaneenee movũngũ.'),
('kam', 'HOS', 7, 14, 'Na matyaaĩngaĩla na ngoo syoo, ĩndĩ nĩmakayaa me mokomonĩ moo: nĩmombanaa kwondũ wa lĩu wa mbaa ngetha na mbinyu mbĩthĩ; nĩmang’endeeaa.'),
('kam', 'HOS', 7, 15, 'O na kau nĩnĩmamanyĩĩtye na ngekĩa moko moo vinya, ĩndĩ nĩmanzũanĩĩaa ũthũku.'),
('kam', 'HOS', 7, 16, 'Nĩmasyokaa, ĩndĩ ti kwa ũla wĩ ĩũlũ; mailyĩ ĩtati: anene moo me mbee ũsumbĩnĩ makavalũkw’a na ũvyũ nũndũ wa ũthatu mwai wa nĩmĩ syoo: ũu ũkeethĩwa kũthekeew’a kwoo me nthĩ ya Misili.'),
('kam', 'HOS', 8, 1, 'Tinĩĩsya soo kanyw’anĩ waku. Nĩwũkĩle ĩũlũ wa nyũmba ya Yeova ta ndiũ, nĩkwĩthĩwa nĩmavĩtĩtye ũtianĩo wakwa, na kũvĩtan’ya mĩao yakwa.'),
('kam', 'HOS', 8, 2, 'Makeengaĩla, makyasya, Ngai wakwa, ithyĩ Isilaeli nĩtũkwĩsĩ.'),
('kam', 'HOS', 8, 3, 'Isilaeli nĩwekisye ũtee kĩla kĩseo: mũmaitha akamũatĩĩa.'),
('kam', 'HOS', 8, 4, 'Nĩmokĩlĩtye asumbĩ, ĩndĩ ti ũndũ wakwa; nĩmaiĩte anene me mbee ũsumbĩnĩ, na ndyaamanya: nĩmeeseũvĩsye mĩvw’anano na vetha na thaavu woo, nĩ kana mese kũvetwa.'),
('kam', 'HOS', 8, 5, 'Nake nĩwekisye kasaũ kaku ũtee, we Samalia; ũthatu wakwa nĩwakanĩtw’e ĩũlũ woo: kũkeethĩwa ĩvinda yĩana ata asu makĩvika vala mate na ĩvĩtyo?'),
('kam', 'HOS', 8, 6, 'Nũndũ o ko kaumie kwa Isilaeli: ndũĩka nĩkaseũvĩtye, nako ti Ngai; ĩĩ, kasaũ ka Samalia kakatilangwa tũlungu.'),
('kam', 'HOS', 8, 7, 'Nũndũ mavuĩaa kĩseve, na makaketha kĩlingi: nde na lĩu ũtũĩtye; mũmea ndũkasyaa lĩu; ethĩwa ũkasyaa, aeni makoomelya.'),
('kam', 'HOS', 8, 8, 'Isilaeli nĩ mũmelye: yu me katĩ wa i mbaĩ o ta mũio ũte mũndũ ũwenda.'),
('kam', 'HOS', 8, 9, 'Nũndũ nĩmambatie Asuli, ta ĩng’oi ya kĩthekanĩ yĩ yoka: Evalaimu nĩwethooee endwa.'),
('kam', 'HOS', 8, 10, 'Ĩĩ, o na kau mathooaa katĩ wa i mbaĩ, yu ngamomban’ya; na nĩmekwambĩlĩlya kũoleka nũndũ wa mũio wa mũsumbĩ wa anene me mbee ũsumbĩnĩ.'),
('kam', 'HOS', 8, 11, 'Nĩkwĩthĩwa Evalaimu nĩwaingĩvisye ithembeo ekae naĩ, ithembeo nitw’ĩkĩte kwake kũndũ kwa naĩ.'),
('kam', 'HOS', 8, 12, 'Namũandĩkĩe maũndũ ngili ĩkũmi ma mĩao yakwa; ĩndĩ nĩmatalĩtwe o ta kĩndũ kĩeni.'),
('kam', 'HOS', 8, 13, 'Ũvoonĩ wa kũthemba nthembo syakwa, nĩmathembaa nyama na makiya; ĩndĩ Yeova ndametĩkĩlaa: yu akalilikana ũthũku woo, na kũsilĩla naĩ syoo; makasyoka Misili.'),
('kam', 'HOS', 8, 14, 'Nũndũ Isilaeli nĩwũlĩtwe nĩ Mũmbi wake, na akaka nyũmba nene mbanakavye; na Yuta nĩwaingĩvisye ndũa mbiie; ĩndĩ ngaete mwaki ndũanĩ syake, na ũkamina nyũmba nene syĩ iemo syasyo.'),
('kam', 'HOS', 9, 1, 'Ndũkatane, we Isilaeli, nũndũ wa mũyo, ta ngo sya andũ; nũndũ nĩwĩkĩte ũmalwaya, ũkĩmũtia Ngai waku; nĩwendete kwĩthooesyaa o kĩla kĩvũĩonĩ kya lĩu wa mbaa ngetha.'),
('kam', 'HOS', 9, 2, 'Kĩvũĩo na kĩangĩo kya nzavivũ itikamavũn’ya, na mbinyu mbĩthĩ ĩkamwaĩa.'),
('kam', 'HOS', 9, 3, 'Matikatũa nthĩ ya Yeova; ĩndĩ Evalaimu akasyoka Misili, na makaya lĩu mũvuku ku Asuli.'),
('kam', 'HOS', 9, 4, 'Matikatulũla nthembo sya mbinyu kwondũ wa Yeova, o na matikamwendeesya: nthembo syoo ikeethĩwa kwoo ta lĩu wa ala mametaa; onthe ala makaya nĩmakavukw’a; nũndũ lĩu woo ũkeethĩwa ũndũ wa kũmina nzaa yoo; ndũkalika nyũmbanĩ ya Yeova.'),
('kam', 'HOS', 9, 5, 'Inyw’ĩ mũkeeka ata mũthenya wa ũmbano ũtw’ĩtwe, na mũthenya wa mboka ya Yeova?'),
('kam', 'HOS', 9, 6, 'Nũndũ, sisya, nĩmaendie makĩa wanangĩko; ĩndĩ Misili ĩkamomban’ya, Memivisi ikamathika; syĩndũ syoo sya vetha sya kwendeesya, syĩnyeelya ikoosa syĩthĩwe syasyo; mĩw’a ĩkeethĩwa maeemanĩ moo.'),
('kam', 'HOS', 9, 7, 'Mĩthenya ya kũsilĩlwa nĩ myũku, mĩthenya ya kũĩvanĩsya nĩ myũku; Isilaeli akamanya ũndũ ũsu: mwathani nĩ mũtumanu, mũndũ ũla wĩ na ũ veva e na ndũũka, nũndũ wa ũthũku waku kwingĩva, na nĩkwĩthĩwa ũmaitha nĩ mũnene.'),
('kam', 'HOS', 9, 8, 'Evalaimu aĩ mũsyaĩĩsya vamwe na Ngai wakwa: na ũvoo wa mwathani, kĩtei kya mũtei wa nyũnyi kĩ nzĩanĩ syake syonthe, na ũmaitha nyũmbanĩ ya Ngai wake.'),
('kam', 'HOS', 9, 9, 'Nĩmeyanangĩte mũno, o ta mĩthenyanĩ ya Ngivea: akalilikana ũthũku woo, na akasilĩla naĩ syoo.'),
('kam', 'HOS', 9, 10, 'Noonie Isilaeli ailyĩ ta nzavivũ weũnĩ; noonie aaĩthe menyu o ta ĩkũyũ yambaa kwĩw’a mũkũyũnĩ ĩvinda ya kũsyaa kwaw’o kwa mbee: ĩndĩ maenda kwa Mbaali‐veoli, meenengane kwa kĩndũ kyu kĩ nthoni, na matw’ĩka kĩla kĩthatasya o ta kyu mendete.'),
('kam', 'HOS', 9, 11, 'Ũvoo wa Evalaimu, ndaĩa yoo ĩkaũlũka ta nyũnyi ĩthi: vaikethĩwa ũsyaa, kana wĩ ĩvu, kana kũitava.'),
('kam', 'HOS', 9, 12, 'O na maea syana syoo, ngatuma makw’ĩĩwa nĩsyo, nĩ kana vatikatiale mũndũ: ĩĩ, na ĩngĩ woo nĩ woo yĩla nĩmatia!'),
('kam', 'HOS', 9, 13, 'Evalaimu, o tondũ noonie Tile ĩilyĩ, nũvandĩtwe vandũ va kwendeesya: ĩndĩ Evalaimu akaumaalĩlya syana syake mũai.'),
('kam', 'HOS', 9, 14, 'Manenge, ame Yeova‐wĩmanenga kĩ? Manenge mavu ala metĩkaa na nondo ng’alu.'),
('kam', 'HOS', 9, 15, 'Ũthũku woo w’onthe wĩ Ngilikali; nũndũ nĩnamamenee kw’o: nũndũ wa ũthũku wa meko moo ngamalũngya maume nyũmbanĩ yakwa; o na ndikamenda ĩngĩ; anene moo me mbee ũsumbĩnĩ onthe nĩ alei.'),
('kam', 'HOS', 9, 16, 'Evalaimu nĩ mũkũne, kĩtina kyoo nĩkyũmĩte, maikasyaa ũsyao: ĩĩ, o na masyaa, ngooaa ũsyao ũla wendetwe wa ĩvu yoo.'),
('kam', 'HOS', 9, 17, 'Ngai wakwa akamekya kũasa, nĩkwĩthĩwa matyaamwĩthukĩĩsya; na makeethĩwa angangi katĩ wa i mbaĩ.'),
('kam', 'HOS', 10, 1, 'Isilaeli nĩ mũsavivũ mũteku mũno, ũla ũsyaaa ũsyao wake: o kwĩanana na kwingĩva kwa ũsyao wake now’o wingĩvĩtye ithembeo syake; kwĩanana na ũseo wa nthĩ yoo nĩmaseũvĩtye ituĩ nzeo.'),
('kam', 'HOS', 10, 2, 'Ngoo syoo niaanĩtw’e; na yu makooneka kwĩthĩwa nĩ avĩtan’ya: we akakũna ithembeo syoo, na kwananga ituĩ syoo.'),
('kam', 'HOS', 10, 3, 'Vate ndĩi yu makaneena, Tũti na mũsumbĩ; nũndũ tũtiũkĩa Yeova; na mũsumbĩ, nake atonya kũtũtethya na ata?'),
('kam', 'HOS', 10, 4, 'Meneena ndeto sya mana, makĩvĩta ũvũngũ yĩla meũtianĩa motianĩo: kwondũ wa ũu ũsilĩlo nũkumĩla ta mũtĩ wĩ ũũ wĩ mĩkaonĩ ya mũũnda.'),
('kam', 'HOS', 10, 5, 'Ala matwĩe Samalia makaũũyĩa tũsaũ twa Mbethi‐aveni mũno; nũndũ andũ ma vo makakametea, o na athembi ma vo ala makatanĩaa, ũndũ wa ũtaĩo wako, nĩkwĩthĩwa nũkatiĩte.'),
('kam', 'HOS', 10, 6, 'O na ĩngĩ kakatwawa Asuli katw’ĩke mũthĩnzĩo kwa mũsumbĩ Yalevu: Evalaimu akasonokw’a, na Isilaeli akasonokea ũtao wake mwene.'),
('kam', 'HOS', 10, 7, 'Ũvoo wa Samalia, mũsumbĩ wayo nĩ mũvete, o ta ĩvuo ĩũlũ wa manzĩ.'),
('kam', 'HOS', 10, 8, 'Na ĩngĩ kũndũ kũtũlu kwa Aveni, nĩkw’o naĩ ya Isilaeli, kũkaanangwa: mĩw’a na thangila ikamea ĩũlũ wa ithembeo syoo; na makatavya iĩma, Tũvw’ĩkei; na tũlĩma, Tũvalũkĩlei.'),
('kam', 'HOS', 10, 9, 'We Isilaeli, nũvĩtĩtye kuma mĩthenya ya Ngivea: nĩkw’o maũngyĩ; kaũ ĩũlũ wa ana ma ũthũku ndwĩmakwatĩa Ngivea.'),
('kam', 'HOS', 10, 10, 'Yĩla nĩenda, ngamasilĩla; na ngo sya andũ ikamombanĩa, yĩla meovanw’a vamwe na mavĩtyo moo elĩ.'),
('kam', 'HOS', 10, 11, 'Na Evalaimu nĩ moi ĩla ĩmanyĩĩtw’e, ĩla yendete kũvũa lĩu wa mbaa ngetha; ĩndĩ nĩmbĩtĩle ĩũlũ wa ngingo yayo nzeo: ngaiĩa Evalaimu mũtũli; Yuta akenza, Yakovo akavukũlya mavali make.'),
('kam', 'HOS', 10, 12, 'Ĩvuĩĩei inyw’ĩ ene ũlũngalunĩ, kethai kwĩanana na ũseo; ĩnzai maei menyu; nũndũ nĩ ĩvinda ya kũmantha Yeova, kũvika ooka na kũmũĩsya mbua ya ũlũngalu.'),
('kam', 'HOS', 10, 13, 'Nĩmwĩnzĩte ũthũku, na nĩmũkethete ũthũku; nĩmũĩte ũsyao wa movũngũ: nũndũ weekwatisye nzĩa yaku, o wingĩ wa ngũmbaũ syaku.'),
('kam', 'HOS', 10, 14, 'Kwondũ wa ũu kĩtuu kĩkookĩla katĩ wa andũ maku, na ngome syonthe syaku ikaanangwa, tondũ Salimani wanangie Mbethi‐aliveli mũthenya wa kaũ: inyia ang’atanw’a atilĩkange tũlungu vamwe na syana syake.'),
('kam', 'HOS', 10, 15, 'Now’o Mbethi‐eli wĩkwĩka nũndũ wa ũthũku waku mũnene: o w’oa ũkĩtema mũsumbĩ wa Isilaeli akavetwa vyũ.'),
('kam', 'HOS', 11, 1, 'Yĩla Isilaeli waĩ kana, nĩnamwendie, na namwĩta mwana wakwa aume Misili.'),
('kam', 'HOS', 11, 2, 'O ũndũ athani maendeea kũmeta, now’o namo maendeeaa kũmatia: mathembeaa Mbaalimu, na kũtoeeasya ũvani mĩvw’anano myaseũvye.'),
('kam', 'HOS', 11, 3, 'Ĩndĩ nĩnamanyĩisye Evalaimu kũkinya; na namakua na moko makwa; ĩndĩ maiaamanya kana nĩnamavoisye.'),
('kam', 'HOS', 11, 4, 'Nĩnamakusisye na ndii sya o mũndũ na mawovanu ma wendo; na nailyĩ kwoo o ta ala maumasya ĩsoki ngambuunĩ syoo; na namaetee lĩu.'),
('kam', 'HOS', 11, 5, 'Maikasyoka nthĩ ya Misili; ĩndĩ Mũasuli akeethĩwa mũsumbĩ woo, nĩkwĩthĩwa nĩmaleile kũnzyokea.'),
('kam', 'HOS', 11, 6, 'Na ũvyũ ũkavalũkĩla ndũa syoo, na kũmina ivingo syoo, na kũmaya, kwondũ wa mosũanĩo moo ene.'),
('kam', 'HOS', 11, 7, 'Na andũ makwa nĩmendaa kũsyoka na ĩtina mandie: o na kau nĩmeũmeta moke kwa ũla wĩ ĩũlũ, vati o na ũmwe ũkamũnenevya.'),
('kam', 'HOS', 11, 8, 'Ngakũeka ata we, Evalaimu? Ngakwĩkya ũtee ata we, Isilaeli? Ngakũtw’a ta Atima ata? Ngakwĩkalya ta Nzevoiimu ata? Ngoo yakwa nĩ ngalyũku nthĩnĩ wakwa, manee makwa nĩmakanĩte vamwe.'),
('kam', 'HOS', 11, 9, 'Ndikeka kwĩanana na wai wa ũthatu wakwa, ndikasyoka kwananga Evalaimu: mũndũ ninyie Ngai, na ndi mũndũ; Ũla Mũtheu katĩ waku; na ndikoka nĩ mũthilĩku.'),
('kam', 'HOS', 11, 10, 'Nĩmakamũvikĩla Yeova, ũla ũkaluma ta mũnyambũ; nũndũ nũkaluma, na syana nikoka kuma ũthũĩlonĩ wa syũa itetemete.'),
('kam', 'HOS', 11, 11, 'Nikoka kuma Misili itetemete ta nyũnyi, na ta ĩvũĩ syumĩte nthĩ ya Asuli; na nĩngatuma matũa nyũmbanĩ syoo, easya ũu Yeova.'),
('kam', 'HOS', 11, 12, 'Evalaimu ninthyũlũlũkĩte na ũvũngũ, na nyũmba ya Isilaeli na ũkengani; ĩndĩ Yuta nũsumbĩkĩte na Ngai kũvika yu, na e na kĩthito kwa Ũla Mũtheu.'),
('kam', 'HOS', 12, 1, 'Evalaimu nũĩsaa kĩseve, na kũatĩĩa kĩesve kyumĩte wumĩlonĩ wa syũa: nake aendeeaa kwingĩvya movũngũ na wanangĩko; na nĩmeũtianĩa ũtianĩo na Asuli, na mauta nĩmatwaawa Misili.'),
('kam', 'HOS', 12, 2, 'O na ĩngĩ Yeova e na ngananĩo na Yuta, na akasilĩla Yakovo kwĩanana na mĩendele yake; kwĩanana na mĩkĩle yake akamũĩva.'),
('kam', 'HOS', 12, 3, 'E ĩvunĩ amũkwatie mwana‐ainyia kĩtiinyo; na e mũndũ mũima aĩ na ũtonyi kwa Ngai:'),
('kam', 'HOS', 12, 4, 'ĩĩ, aĩ na ũtonyi ĩũlũ wa mũlaĩka, na akĩlya vinya; aĩa, na amwĩsũva: amwĩthĩa Mbethi‐eli, na nĩvo waneenee naitũ,'),
('kam', 'HOS', 12, 5, 'o Yeova, Ngai wa nguthu; Yeova nĩ syĩtwa yake ya ũlilikan’yo.'),
('kam', 'HOS', 12, 6, 'Kwondũ wa ũu ĩthyũũĩe Ngai waku: sũvĩa ũseo na ũsili wa katĩ, na ũkyeteelaa Ngai waku mavinda onthe.'),
('kam', 'HOS', 12, 7, 'We nĩ mũtandĩthya, ithimi sya ũkengani syĩ kw’okonĩ kwake: endete kũthĩn’ya.'),
('kam', 'HOS', 12, 8, 'Na Evalaimu asya, Nĩ w’o, nĩndw’ĩkĩte mũthwii, nyie nĩnĩyoneete ũthwĩĩ: kũthĩnanĩ kwakwa kw’onthe kwa wĩa maikona ũthũku nthĩnĩ wakwa ũla wĩthĩwa naĩ.'),
('kam', 'HOS', 12, 9, 'Ĩndĩ ninyie Yeova Ngai waku o kuma nthĩ ya Misili; ngatuma ũtũa maeemanĩ o ĩngĩ, o ta mĩthenyanĩ ya mboka ĩtw’ĩtwe.'),
('kam', 'HOS', 12, 10, 'O na ĩngĩ nĩneenete na athani, na nĩningĩvĩtye mawoni; na kwondũ wa ũthũkũmi wa athani nĩnĩelekanĩtye na ngelekan’yo.'),
('kam', 'HOS', 12, 11, 'Ngileati nĩ ũthũku? Mo nĩ akengani vyũ; kũu Ngilikali nĩmeũthemba tũsalũ twa mũew’a; ĩĩ, ithembeo syoo nĩ ta mbumbu mĩkaonĩ ya mĩũnda.'),
('kam', 'HOS', 12, 12, 'Na Yakovo akĩa athi nthĩ ya Alamu, na Isilaeli athũkũma nĩ kana one kĩveti, na nĩ kana one kĩveti aĩthasya malondu.'),
('kam', 'HOS', 12, 13, 'Na Yeova amumya Isilaeli Misili na kw’oko kwa mwathani, o na nĩwasũvĩiwe na kw’oko kwa mwathani.'),
('kam', 'HOS', 12, 14, 'Evalaimu nũthatĩtye ũthatu wĩ woo mũno: kwondũ wa ũu nthakame yake ĩkatiwa ĩũlũ wake, na kĩvũthya kyake Mwĩaĩi wake akamũtũngĩa.'),
('kam', 'HOS', 13, 1, 'Yĩla Evalaimu waneenie, kwaĩ kũtetema; eenenevya mwene nthĩnĩ wa Isilaeli; ĩndĩ yĩla wavĩtisye maũndũnĩ ma Mbaali, nĩwakwie.'),
('kam', 'HOS', 13, 2, 'Na yu nĩmekaa naĩ mbee na mbee, na meeseũvĩsye mĩvw’anano ya vetha woo matwekethetye, o mĩvw’anano kwĩanana na ũmanyi woo ene, yonthe wĩa wa ndũĩka: maneenaa ũndũ wayo, Andũ ala mathembaa nĩmamumunye tũsaũ.'),
('kam', 'HOS', 13, 3, 'Kwondũ wa ũu makeethĩwa ta ĩthweo ya kĩoko, na ta ĩmwe yĩla yĩtw’ĩkaa tene, ta wewa ũla ũtwaawa nĩ kĩlingi kuma kĩvũĩonĩ, na ta syũki yĩla yumaa mũtotenĩ.'),
('kam', 'HOS', 13, 4, 'Ĩndĩ ninyie Yeova Ngai waku o kuma nthĩ ya Misili; na ndũkaamanye ngai ĩngĩ ate o nyie, na nde vo nyie vati mũtangĩĩi.'),
('kam', 'HOS', 13, 5, 'Nyie nĩnakũmanyĩe weũnĩ, nthĩ yĩ mũnyao mũnene.'),
('kam', 'HOS', 13, 6, 'O kwĩanana na kĩsesi kyoo, now’o mavũnie; nĩmavũnie, na ngoo syoo syaneneva: kwondũ wa ũu nĩmolĩtwe ninyie.'),
('kam', 'HOS', 13, 7, 'Kwondũ wa ũu kwoo nĩilyĩ ta mũnyambũ; ngooveesya o ta ngo nzĩanĩ;'),
('kam', 'HOS', 13, 8, 'ngakomana namo ta nduva ĩvenetwe maswii mayo, na ngatembũa wambũ wa ngoo syoo; na ngamaĩa vu ta mũnyambũ mũka; nyamũ mbai ĩkamatembũanga.'),
('kam', 'HOS', 13, 9, 'Nĩ wanangĩko waku, we Isilaeli, nũndũ nũndeete, kũlea mũtethya waku.'),
('kam', 'HOS', 13, 10, 'Aĩva yu mũsumbĩ waku, nĩ kana akũtangĩĩe ndũanĩ syaku syonthe? Na asili maku, ala waneenie ũndũ wamo, Nenga mũsumbĩ na anene me mbee ũsumbĩnĩ?'),
('kam', 'HOS', 13, 11, 'Nĩnĩkũnengete mũsumbĩ ũthatunĩ wakwa, na namũveta kũthilĩkanĩ kwakwa.'),
('kam', 'HOS', 13, 12, 'Ũthũku wa Evalaimu nĩ mwove; naĩ yake nĩyiĩtwe.'),
('kam', 'HOS', 13, 13, 'Mawoo ma mũndũ mũka ũnũkwaũnya makamũkwata: nĩ mwana ũte mũĩ; nũndũ nĩ ĩvinda ũtaĩlwe nĩ kwĩkala vandũ va kũsyaĩwa syana.'),
('kam', 'HOS', 13, 14, 'Ngamovosya kuma vinyanĩ wa Seoli; ngamatangĩĩa kuma kĩkw’ũnĩ: we kĩkw’ũ, maĩva mothĩn’yo maku? We Seoli, ũĩva wanangi waku? Ũalyũlo wa ngoo ũkavithĩka methonĩ makwa.'),
('kam', 'HOS', 13, 15, 'O na akeethĩwa na ũsyao mwingĩ katĩ wa ana‐a‐ĩthe, kĩseve kĩkooka kyumĩte wumĩlonĩ wa syũa, mĩthũmũ ya Yeova ĩkyambata kuma weũnĩ; na mbuluti yake ĩkang’ala, na nthongo yake ĩkang’ala: akatava mũtavo wa ũthwii mwie wa mĩio yonthe mĩseo.'),
('kam', 'HOS', 13, 16, 'Samalia akakua ĩvĩtyo yake; nũndũ nĩwamũng’endee Ngai wake: makavalũkw’a na ũvyũ; tũũkenge twoo tũkang’atanganw’a tũtilĩkange tũlungu na aka moo aito makataũwa.'),
('kam', 'HOS', 14, 1, 'Ame Isilaeli, syokea Yeova Ngai waku; nũndũ nũvalũkĩte nũndũ wa ũthũku waku.'),
('kam', 'HOS', 14, 2, 'Osai ndeto mũthi nasyo, na mũimũsyokea Yeova: mũmwĩe, Veta ũthũku w’onthe, na ũkĩtĩkĩla ũla ũseo: na ĩndĩ tũkathemba nthembo sya ilomo sitũ ta kũthemba tũsalũ twa mũew’a.'),
('kam', 'HOS', 14, 3, 'Asuli ndĩkatũtangĩĩa; tũikatũla mbalasi; o na tũikea wĩa wa moko maitũ ĩngĩ, Nĩ inyw’ĩ ngai sitũ; nũndũ ala makw’ĩĩwe nĩ aaĩthe monaa tei kwaku.'),
('kam', 'HOS', 14, 4, 'Ngavosya kũsyoka na ĩtina kwoo, ngamenda mũno; nũndũ ũthatu wakwa nũalyũkĩte kuma kwake.'),
('kam', 'HOS', 14, 5, 'Ngeethĩwa ta ĩmwe kwa Isilaeli; akalaũka ta ĩlaa ya lili, na akatambũũkya mĩi yake ta Levanoni.'),
('kam', 'HOS', 14, 6, 'Mbonge syake ikeenyasya, na wanake wake ũkeethĩwa ta mũthata, na mũuke wake ta Levanoni.'),
('kam', 'HOS', 14, 7, 'Ala matũaa ungu wa muunyĩ wake makasyoka; makathayũũka ta mbeke, na kũlaũka ta mũsavivũ: mũuke wake ũkeethĩwa ta mbinyu ya Levanoni.'),
('kam', 'HOS', 14, 8, 'Evalaimu akasya, Nĩ ũndũ ũngĩ mwaũ na mĩvw’anano? Nĩnzũngĩĩte, nakwa ngamũsyaĩĩsya: nĩilyĩ ta mũtĩ wa mũsonovali mũthithinĩu; vala nĩĩ ũsyao waku nĩwonekaa.'),
('kam', 'HOS', 14, 9, 'Nũũ ũla mũĩ, amanye maũndũ aa? Ũla wĩ kĩlĩko, kana amamanye? Nũndũ nzĩa sya Yeova nĩ ndũngalu, na ala alũngalu makaiendelaa; ĩndĩ avĩtan’ya makavalũkaa nthĩnĩ wasyo.'),
('kam', 'JOL', 1, 1, 'Ndeto ya Yeova ĩla yamũkĩe Yoeli mwana wa Vethueli.'),
('kam', 'JOL', 1, 2, 'Ĩw’ai ũũ, inyw’ĩ atumĩa, na teai kũtũ, inyw’onthe ala mũtwĩe ĩ nthĩ. Ũũ waaĩthĩwa mĩthenyanĩ yenyu, kana mĩthenyanĩ ya aaĩthe menyu?'),
('kam', 'JOL', 1, 3, 'Tavyai syana syenyu ũũ, na syana syenyu nitavye syana syoo, na syana syoo nzyawa ĩngĩ.'),
('kam', 'JOL', 1, 4, 'Kyu kĩla kyatialilw’e nĩ kĩtĩlĩ nĩkyalĩkile nĩ ngie; na kyu kĩla kyatialilw’e nĩ ngie nĩkyalĩkile nĩ mbandi; na kyu kĩla kyatialilw’e nĩ mbandi nĩkyalĩkile nĩ kĩthesa.'),
('kam', 'JOL', 1, 5, 'Amũkai, inyw’ĩ athengi, na ĩai; na kayai, inyw’onthe anywi ma mbinyu, kwondũ wa mbinyu ĩ mũyo; nũndũ nĩvetetwe makanyw’anĩ menyu.'),
('kam', 'JOL', 1, 6, 'Nũndũ mbaĩ nĩyambatĩĩa nthĩ yakwa, yĩ vinya, na ĩtatalĩka; maeo mayo nĩ maeo ma mũnyambũ, na yĩ na mbosela sya mũnyambũ mũka.'),
('kam', 'JOL', 1, 7, 'Nĩyanangĩte mũsavivũ wakwa, na yasyũlya mũkũyũ wakwa: yũsyũlĩtye ũkathea kw’ũ, na kũwĩkya kũasa; mbonge syaw’o syeeũva.'),
('kam', 'JOL', 1, 8, 'Ĩa ta mwĩĩtu mũtheu ũvotoetwe makunia nũndũ wa mũũme wamwĩvaĩtye.'),
('kam', 'JOL', 1, 9, 'Nthembo ya mũtu na nthembo ya kũnyuwa nivetetwe nyũmbanĩ ya Yeova; athembi, athũkũmi ma Yeova, nĩmeũmeta.'),
('kam', 'JOL', 1, 10, 'Mũũnda nĩ mwanange, nthĩ nĩnĩũmeta; nũndũ lĩu wa mbaa ngetha nĩ mwanange, na mbinyu mbĩthĩ nĩ ng’alu, na mauta nĩmekũnyiva.'),
('kam', 'JOL', 1, 11, 'Thokoanai, inyw’ĩ aĩmi, kayai, inyw’ĩ asũvĩi ma mĩsavivũ, nũndũ wa nganũ na nũndũ wa mbaale; nũndũ ngetha ya mĩũnda nĩyaĩte.'),
('kam', 'JOL', 1, 12, 'Mũsavivũ nĩwũmĩte, na mũkũyũ nũvovete; mũkũngũmanga, na mũtende naw’o, na mũevo, o mĩtĩ yonthe ya mĩũndanĩ nĩyũmĩte: nũndũ ũtanu nũthelete ananĩ ma andũ.'),
('kam', 'JOL', 1, 13, 'Ĩvotoei makunia na kũĩa, inyw’ĩ athembi; kayai, inyw’ĩ athũkũmi ma kĩthembeo; ũkai, mũkome ũtukũ mũima mwĩvw’ĩkĩte makunia, inyw’ĩ athũkũmi ma Ngai wakwa: nũndũ nthembo ya mũtu na nthembo ya kũnyuwa nisiĩĩwe itikethĩwe nyũmbanĩ ya Ngai wenyu.'),
('kam', 'JOL', 1, 14, 'Vathai ĩvinda ya kũtĩĩa kũya, mete mombane ũmbano ũkilĩtye, ũmban’yai atumĩa na onthe ala matwĩe ĩ nthĩ nyũmbanĩ ya Yeova Ngai wenyu, na mũkĩmwĩkaĩla Yeova.'),
('kam', 'JOL', 1, 15, 'Ĩiaa! Mũthenya ũsu! Nũndũ mũthenya wa Yeova nĩ mũthengeeu, na ũkooka ta wanango kuma kwa Mwene Vinya W’onthe.'),
('kam', 'JOL', 1, 16, 'Lĩu ti mũvete mbee wa metho maitũ, ĩĩ, ũtanu na mũyo kuma nyũmbanĩ ya Ngai waitũ?'),
('kam', 'JOL', 1, 17, 'Mbeũ nĩ syoee mavandanĩ kũla iĩ; makũmbĩ nĩ mathei, makũmbĩ manene nĩ manangĩku; nũndũ lĩu wa mbaa ngetha nĩwũmĩte.'),
('kam', 'JOL', 1, 18, 'A! Ũndũ nyamũ iũluma! Ndĩthya sya ng’ombe nisaanĩw’e, nĩkwĩthĩwa iti na ũĩthyo; ĩĩ, ndĩthya sya malondu nĩ nthĩnu.'),
('kam', 'JOL', 1, 19, 'Ame Yeova, nĩngũkwĩkaĩla; nũndũ mwaki nũminĩte isesi sya weũnĩ, na ũlĩlĩnzĩ nũvĩvĩtye mĩtĩ yonthe ya kĩsesinĩ.'),
('kam', 'JOL', 1, 20, 'Ĩĩ, nyamũ sya kĩthekanĩ niũkũvevavevea; nũndũ tũlũsĩ nĩ tũng’alu, na mwaki nũminĩte isesi sya weũnĩ.'),
('kam', 'JOL', 2, 1, 'Vuvĩai soo Saioni, na vuvĩai soo wĩ wasya wa kũtĩsya kĩĩmanĩ kyakwa kĩtheu; onthe ala matwĩe ĩ nthĩ mateleme: nũndũ mũthenya wa Yeova nĩwũkĩte, nũndũ nũthengeee;'),
('kam', 'JOL', 2, 2, 'mũthenya wa kĩvindu na mũki mũnene, mũthenya wa matu na kĩvindu kya ngokomi, o tondũ w’oa ũtemaa ĩũlũ wa iĩma; andũ anene na me vinya; kũtyaaĩthĩwa o na ĩndĩĩ ala mailyĩ ũu, o na kũtikethĩwa angĩ ĩtina wamo, o na kũvika myaka ya nzyawa mbingĩ.'),
('kam', 'JOL', 2, 3, 'Mwaki nũvĩvasya mbee woo; na ĩtina woo ũlĩlĩnzĩ wa mwaki nĩwakene: nthĩ ĩilyĩ mũũnda wa Eteni mbee woo, na ĩtina woo nĩ weũ mũthei; ĩĩ, na kũiĩ waavonoka.'),
('kam', 'JOL', 2, 4, 'Mũvw’anĩle woo nĩ ta mũvw’anĩle wa mbalasi; na ta ala matũlĩte mbalasi, nĩw’o masembaa.'),
('kam', 'JOL', 2, 5, 'Nĩmatũlĩlaa ta makasya me kĩtuu me ĩũlũ wa iĩma, ta ũlĩlĩnzĩ wa mwaki wĩ kĩuumo ũla ũminaa ũa, ta andũ me vinya mataũĩw’e kaũ.'),
('kam', 'JOL', 2, 6, 'Me vo ngo sya andũ syĩthĩwaa na woo mũnene; na mothyũ onthe makĩalyũka.'),
('kam', 'JOL', 2, 7, 'Masembaa ta ngũmbaũ; na malĩsĩlaa ũvainĩ ta andũ ma kaũ; na maendaa kĩla ũmwe aeleele mbee, na mĩkwĩlĩnĩ yoo mativĩtavĩtanaa.'),
('kam', 'JOL', 2, 8, 'O na vati ũmwe ũnũkũtina ũngĩ; maendaa kĩla ũmwe aeleele mbee; na malĩlasya mĩionĩ ya kaũ, na matiũngamaa.'),
('kam', 'JOL', 2, 9, 'Mathaanyũkĩaa ndũa; masembaa ĩũlũ wa ũvai; malĩsaa nyũmbanĩ; malikĩlaa mbũthinĩ ta kĩng’ei.'),
('kam', 'JOL', 2, 10, 'Nthĩ nĩthingithaa mbee woo; matu nĩmatetemaa; syũa na mwei niĩsaa kĩvindu, na ndata niekaa kũtisa kwasyo.'),
('kam', 'JOL', 2, 11, 'Na Yeova nĩwumasya wasya wake mbee wa ita syake sya kaũ; nũndũ mwako wake wa maeema nĩ mũnene mũno; nũndũ e vinya ũla wĩanĩasya ndeto yake; nũndũ mũthenya wa Yeova nĩ mũnene na wa kũtĩsya mũno; na nũũ ũla ũtonya kũwũmĩĩsya?'),
('kam', 'JOL', 2, 12, 'Ĩndĩ o na yu, easya ũu Yeova, ĩnthyũũĩei nyie na ngoo syenyu syonthe, na kũtĩĩa kũya, na kũĩa, na kũmeta:'),
('kam', 'JOL', 2, 13, 'na mũkĩtembũa ngoo syenyu, na tĩ ngũa syenyu, na mũkĩmwĩthyũũĩa Yeova Ngai wenyu; nũndũ nĩ mũseo na e tei, mũmĩĩsya wa kũthata, na e na ũseo mwingĩ wĩ wendo, na etũngaa ndakeke ũla ũthũku.'),
('kam', 'JOL', 2, 14, 'Nũũ wĩsĩ ethĩwa ndeĩthyũũa na kwĩtũnga, na kũtia ũathimo ĩtina wake, o nthembo ya mũtu na nthembo ya kũnyuwa ya Yeova Ngai wenyu?'),
('kam', 'JOL', 2, 15, 'Vuvĩai soo Saioni, vathai ĩvinda ya kũtĩĩa kũya, mete mombane ũmbano ũkilĩtye;'),
('kam', 'JOL', 2, 16, 'ũmban’yai andũ, vathan’yai ũmbano wĩthĩwe mũtheu, ũmban’yai atumĩa, ũmban’yai syana, o na tũla twongaa; mũtwaani naume nyũmbanĩ yake ya nthĩnĩ, na mũtwawa naume nyũmbanĩ yake ya nthĩnĩ.'),
('kam', 'JOL', 2, 17, 'Athembi, athũkũmi ma Yeova, nĩmaĩe me katĩ wa valasya na kĩthembeo, na nĩmasye, Ekea andũ maku, ame Yeova, na ndũkanengane ũtiĩwa waku ũvũthĩĩw’e, kana i mbaĩ imasumbĩke: nĩ ũndũ wa kĩ kwĩse kũneenanw’a katĩ wa ngo sya andũ makyasya, Ngai woo aĩva?'),
('kam', 'JOL', 2, 18, 'Nĩvo ĩndĩ Yeova wewie kĩwĩu nũndũ wa nthĩ yake, na eew’ĩa andũ make ĩnee.'),
('kam', 'JOL', 2, 19, 'Na Yeova asũngĩa na amea andũ make, Sisyai, ngamũetee lĩu wa mbaa ngetha, na mbinyu mbĩthĩ, na mauta, na mũkeanĩwa nĩsyo; na ndikatuma mũvũthĩĩw’a ĩngĩ katĩ wa i mbaĩ;'),
('kam', 'JOL', 2, 20, 'ĩndĩ ngaveta ita sya kaũ sya ngalĩ ya ĩũlũ kũasa nenyu, na kwilũngĩlĩĩlya nthĩ nyũmũ na nthei, kĩlungu kya mbee kyasyo ũkanganĩ wa ngalĩ ya wumĩlonĩ wa syũa, na kĩlungu kya ĩtina ũkanganĩ wa ũthũĩlonĩ wa syũa; na mũnyungo wasyo mũthũku ũkataavũka, na mũuke wasyo mũthũku ũkataavũka, nĩkwĩthĩwa nĩsyĩkĩte maũndũ manene.'),
('kam', 'JOL', 2, 21, 'Ndũkakĩe, we nthĩ, tana na kwĩw’a mũyo; nũndũ Yeova nĩwĩkĩte maũndũ manene.'),
('kam', 'JOL', 2, 22, 'Mũikakĩe, inyw’ĩ nyamũ sya kĩthekanĩ; nũndũ isesi sya weũnĩ nithongooete, nũndũ mũtĩ nũsyaĩte ũsyao waw’o, mũkũyũ na mũsavivũ nĩyumĩlĩtye vinya wayo.'),
('kam', 'JOL', 2, 23, 'Tanai ĩndĩ, inyw’ĩ ana ma Saioni, na kwĩw’ĩa Yeova Ngai wenyu mũyo; nũndũ nũmũnengae mbua ya nthwa na kĩthimi kya w’o, na nũtumaa mbua yua nũndũ wenyu, mbua ya nthwa na mbua ya uũa mwei wa mbee.'),
('kam', 'JOL', 2, 24, 'Na ivũĩo ikausũwa nĩ nganũ, na maviva makausũa na kũng’okwa nĩ mbinyu mbĩthĩ na mauta.'),
('kam', 'JOL', 2, 25, 'Na ngamũtũngĩa myaka ĩla yalĩkile nĩ ngie, na mbandi, na kĩthesa, na kĩtĩlĩ, nguthu yakwa nene ya kaũ, ĩla ndũmĩte katĩ wenyu.'),
('kam', 'JOL', 2, 26, 'Na mũkaya mwĩanĩwe na kũvũna, na kũtaĩa syĩtwa ya Yeova Ngai wenyu, ũla ũmwĩkĩte maũndũ ma ũseng’ya; na andũ makwa matikasonokw’a o na ĩndĩĩ.'),
('kam', 'JOL', 2, 27, 'Na mũkamanya kana nyie nĩ katĩ wa Isilaeli, na kana ninyie Yeova Ngai wenyu, o na kũti ũngĩ; na andũ makwa matikasonokw’a o na ĩndĩĩ.'),
('kam', 'JOL', 2, 28, 'Na kũkeethĩwa ĩtina wa ũu, kana ngamĩtulũĩla mĩĩ yonthe Veva wakwa; na ana menyu na eĩtu menyu makathana, atumĩa menyu makaota ndoto, anake menyu makoona mawoni:'),
('kam', 'JOL', 2, 29, 'na ĩngĩ ngaitulũĩla ngombo, aũme na aka, Veva wakwa mĩthenyanĩ ĩsu.'),
('kam', 'JOL', 2, 30, 'Na ngoonan’ya moseng’yo matunĩ na nthĩ: nthakame, na mwaki, na ituĩ sya syũki.'),
('kam', 'JOL', 2, 31, 'Syũa yĩkaalyũkw’a yĩthĩwe kĩvindu, na mwei wĩthĩwe nthakame, mbee wa mũthenya mũnene na wa ũtĩsya wa Yeova ũtanoka.'),
('kam', 'JOL', 2, 32, 'Na kũkeethĩwa, o ũla ũkekaĩla syĩtwa ya Yeova nũkatangĩĩwa; nũndũ kĩĩmanĩ kya Saioni na Yelusaleme vakeethĩwa ala makavonoka, o tondũ Yeova waĩtye, na katĩ wa ũtialo vakeethĩwa ala Yeova ũketa.'),
('kam', 'JOL', 3, 1, 'Nũndũ, sisya, mĩthenya ĩsu, na ĩvinda yĩu, yĩla ngatũnga Yuta na Yelusaleme maume kũtavwanĩ,'),
('kam', 'JOL', 3, 2, 'nĩngomban’ya mbaĩ syonthe, na ngaitheesya mwandanĩ wa Yeosavati; na ngaisilĩĩla o vo nũndũ wa andũ makwa na nũndũ wa ũtiĩwa wakwa Isilaeli, ala syanyaĩĩkisye katĩ wa mbaĩ i ingĩ: na syaaan’ya nthĩ yakwa,'),
('kam', 'JOL', 3, 3, 'na syalimana nũndũ wa andũ makwa, na syakũan’ya kĩvĩsĩ na ĩlwaya, na kũthoosya mwĩĩtu nũndũ wa mbinyu, nĩ kana manyw’e.'),
('kam', 'JOL', 3, 4, 'Ĩĩ, na inyw’ĩ, we Tile, na Sitoni, na nthĩ syonthe sya Vilisitia mwĩ kyaũ kwakwa? Mũkeetũngĩa mwĩkũle vala nĩĩ? Na ethĩwa mũkeekũlanĩlya kwakwa, mĩtũkĩ nzembete ngatũnga wĩkũlo wenyu ĩũlũ wa mũtwe wenyu.'),
('kam', 'JOL', 3, 5, 'Nĩkwĩthĩwa nĩmwosete vetha wakwa na thaavu wakwa, na mwatwaa makalũnĩ menyu syĩndũ syakwa nzeo syĩ vata mũno,'),
('kam', 'JOL', 3, 6, 'na nĩmũthooetye ana ma Yuta na ana ma Yelusaleme kwa ana ma Akiliki, nĩ kana mũmavete kũasa na mũvaka woo;'),
('kam', 'JOL', 3, 7, 'sisyai, ngamokĩlya kuma vala mwamathooisye, na ngatũnga wĩkũlo wenyu ĩũlũ wa mũtwe wenyu ene;'),
('kam', 'JOL', 3, 8, 'nakwa ngathoosya ana menyu na eĩtu menyu kw’okonĩ kwa ana ma Yuta, namo makamathoosya kwa andũ ma Sieva, kwa mbaĩ yĩ kũasa: nũndũ Yeova nũneenete ũu.'),
('kam', 'JOL', 3, 9, 'Tavan’yai ũndũ ũũ katĩ wa i mbaĩ; ĩyũmbanĩsyei kaũ; ũkĩlyai ngũmbaũ; andũ onthe ma kaũ nĩmathengeee, na nĩmambate.'),
('kam', 'JOL', 3, 10, 'Tusyai mĩthya ya maembe menyu ma ng’ombe ĩtw’ĩke mbyũ, na tũvyũ twĩ ngoto twa ũsea tũtw’ĩke matumo: ũla mwonzu nĩasye, Nĩ na vinya.'),
('kam', 'JOL', 3, 11, 'Ĩkalaatei, na mũkyũka, inyw’ĩ mbaĩ syonthe ila ithyũlũlũkĩte kw’onthe, na mũkyũmbana vamwe: tuma a me ũtonyi maku matheea kw’o, ame Yeova.'),
('kam', 'JOL', 3, 12, 'Eka mbaĩ syĩyũkĩlye, na kwambata mwandanĩ wa Yeosavati; nũndũ ngekala nthĩ kw’o nzilĩle mbaĩ syonthe ila ithyũlũlũkĩte kw’onthe.'),
('kam', 'JOL', 3, 13, 'Likyai kavyũ ke ngoto mũkethe; nũndũ ngetha nĩ mbĩu: ũkai, mũange; nũndũ kĩangĩo kya nzavivũ nĩ kyusũu, maviva nĩ mausĩe na kũng’okwa; nũndũ ũthũku woo nĩ mũnene.'),
('kam', 'JOL', 3, 14, 'Nguthu, nguthu mwandanĩ wa kũtw’ĩwa maũndũ! Nũndũ mũthenya wa Yeova wĩ vakuvĩ mwandanĩ wa kũtw’ĩwa maũndũ.'),
('kam', 'JOL', 3, 15, 'Syũa na mwei niĩsaa kĩvindu, na ndata niekaa kũtisa kwayo.'),
('kam', 'JOL', 3, 16, 'Na Yeova akaluma e Saioni, na kumya wasya wake e Yelusaleme; na matu na nthĩ ikathingitha: ĩndĩ Yeova akeethĩwa wĩvitho wa andũ make, na ngome yĩ vinya kwa ana ma Isilaeli.'),
('kam', 'JOL', 3, 17, 'Kwondũ wa ũu mũkamanya kana ninyie Yeova Ngai wenyu, ndwĩe Saioni kĩĩmanĩ kyakwa kĩtheu: nĩvo Yelusaleme ĩkethĩwa ntheu, na vatikethĩwa aeni mamĩvĩtĩla ĩngĩ.'),
('kam', 'JOL', 3, 18, 'Na kũkeethĩwa mũthenya ũsu, atĩ iĩma iketĩkya mbinyu ĩ mũyo, na tũlĩma tũkanyũlũlũkya ĩia, na tũlũsĩ tw’onthe twa Yuta tũkavĩtya manzĩ; na nthongo ĩkaumĩlĩla nyũmbanĩ ya Yeova, na ĩkanyithya mwanda wa Sitimu.'),
('kam', 'JOL', 3, 19, 'Misili ĩkeethĩwa nthei, na Etomu ĩkeethĩwa weũ mũthei, nũndũ wa ũng’endu ũla wĩkĩtwe ana ma Yuta, nĩkwĩthĩwa nĩmetĩkisye nthakame ĩte ĩvĩtyo nthĩ yoo.'),
('kam', 'JOL', 3, 20, 'Ĩndĩ Yuta akekalaa tene na tene, na Yelusaleme nzyawa na nzyawa.'),
('kam', 'JOL', 3, 21, 'Na ngathesya nthakame yoo, ĩla ndaathesya: nũndũ Yeova atwĩe Saioni.'),
('kam', 'AMO', 1, 1, 'Ndeto sya Amosi, ũla waĩ katĩ wa aĩthi ma Tekoa, ila wonie ũndũ wa Isilaeli mĩthenya ya Usia mũsumbĩ wa Yuta, na mĩthenya ya Yelovoamu mwana wa Yoasi mũsumbĩ wa Isilaeli, myaka ĩlĩ mbee wa kĩla kĩtetemo kya nthĩ.'),
('kam', 'AMO', 1, 2, 'Na asya, Yeova akaluma e Saioni, na kumĩlĩlya wasya wake e Yelusaleme; na isesi sya aĩthi ikameta, na mũthya wa kĩĩma kya Kalimeli ũkooma.'),
('kam', 'AMO', 1, 3, 'Ũũ nĩw’o Yeova ũnũkwasya: Nũndũ wa mavĩtyo atatũ ma Ndamasiku, ĩĩ, nũndũ wa ana, ndikathyũũa ũsilĩlo wayo; nĩkwĩthĩwa nĩmavũĩte Ngileati na ivũi sya kĩaa.'),
('kam', 'AMO', 1, 4, 'Ĩndĩ ngaete mwaki nyũmbanĩ ya Aasaeli, na ũkamina nyũmba nene mbanakavye sya Mbeni‐aatati.'),
('kam', 'AMO', 1, 5, 'Na ngatũlan’ya kĩvingi kya Ndamasiku, na kũmũveta ũla ũtwĩe mwandanĩ wa Aveni, na ũla ũkwete ndata ya ũsumbĩ kuma nyũmbanĩ ya Eteni; na andũ ma Silia makaenda me atave kũvika Kili, easya ũu Yeova.'),
('kam', 'AMO', 1, 6, 'Ũũ nĩw’o Yeova ũnũkwasya: Nũndũ wa mavĩtyo atatũ ma Ngasa, ĩĩ, nũndũ wa ana, ndikathyũũa ũsilĩlo wayo; nĩkwĩthĩwa nĩmatavie mbaĩ nima, nĩ kana mamanengane kwa Etomu.'),
('kam', 'AMO', 1, 7, 'Ĩndĩ ngaete mwaki ĩũlũ wa ũvai wa Ngasa, na ũkamina nyũmba nene mbanakavye syayo.'),
('kam', 'AMO', 1, 8, 'Na ngamũveta ũla ũtwĩe Asitoti, na ũla ũkwete ndata ya ũsumbĩ Asikeloni; na ngathyũũĩa Ekiloni kw’oko kwakwa; na ũtialo wa Avilisiti ũkaa, easya ũu Mwĩaĩi Yeova.'),
('kam', 'AMO', 1, 9, 'Ũũ nĩw’o Yeova ũnũkwasya: Nũndũ wa mavĩtyo atatũ ma Tile, ĩĩ, nũndũ wa ana, ndikathyũũa ũsilĩlo wayo; nĩkwĩthĩwa manenganie mbaĩ nima kwa Etomu, na matyaalilikana ũtianĩo wa ana‐a‐ĩthe.'),
('kam', 'AMO', 1, 10, 'Ĩndĩ ngaete mwaki ĩũlũ wa ũvai wa Tile, na ũkamina nyũmba nene mbanakavye syayo.'),
('kam', 'AMO', 1, 11, 'Ũũ nĩw’o Yeova ũnũkwasya: Nũndũ wa mavĩtyo atatũ ma Etomu, ĩĩ, nũndũ wa ana, ndikathyũũa ũsilĩlo wayo; nĩkwĩthĩwa amũatĩĩe mwana‐a‐ĩthe e na ũvyũ, na avetete ĩnee yonthe, na ũthatu wake watembũangaa mavinda onthe, na nĩwekalaa na ũthatu wake ĩndĩ yonthe.'),
('kam', 'AMO', 1, 12, 'Ĩndĩ ngaete mwaki ĩũlũ wa Temani, na ũkamina nyũmba nene mbanakavye sya Mbosila.'),
('kam', 'AMO', 1, 13, 'Ũũ nĩw’o Yeova ũnũkwasya: Nũndũ wa mavĩtyo atatũ ma ana ma Amimoni, ĩĩ, nũndũ wa ana, ndikathyũũa ũsilĩlo wayo; nĩkwĩthĩwa mamataũie aka me aito ma Ngileati, nĩ kana makũĩĩsye mĩvaka yoo.'),
('kam', 'AMO', 1, 14, 'Ĩndĩ ngakwatya mwaki ũvainĩ wa Lava, na ũkamina nyũmba nene mbanakavye syayo, vamwe na kua mbu mũthenya wa kaũ, na kĩuutani mũthenya wa kĩlingĩ;'),
('kam', 'AMO', 1, 15, 'na mũsumbĩ woo akaenda e mũtave, we vamwe na anene make me mbee ũsumbĩnĩ, easya ũu Yeova.'),
('kam', 'AMO', 2, 1, 'Ũũ nĩw’o Yeova ũnũkwasya: Nũndũ wa mavĩtyo atatũ ma Moavi, ĩĩ, nũndũ wa ana, ndikathyũũa ũsilĩlo wayo; nĩkwĩthĩwa avĩvisye mavĩndĩ ma mũsumbĩ wa Etomu matw’ĩka sokaa.'),
('kam', 'AMO', 2, 2, 'Ĩndĩ ngaete mwaki ĩũlũ wa Moavi, na ũkamina nyũmba nene mbanakavye sya Keliothi; na Moavi ĩkakw’ĩa kĩtuunĩ, na mbu, na wasya wa soo;'),
('kam', 'AMO', 2, 3, 'na ngaveta mũsili aume katĩ wayo, na kũaa anene onthe mayo me mbee ũsumbĩnĩ vamwe nake, easya ũu Yeova.'),
('kam', 'AMO', 2, 4, 'Ũũ nĩw’o Yeova ũnũkwasya: Nũndũ wa mavĩtyo atatũ ma Yuta, ĩĩ, nũndũ wa ana, ndikathyũũa ũsilĩlo wayo; nĩkwĩthĩwa nĩmaleete mĩao ya Yeova, na matyaasũvĩa myamũlo yake, na movũngũ moo nĩmamavĩtĩthĩtye, ala aaĩthe moo maatĩĩe.'),
('kam', 'AMO', 2, 5, 'Ĩndĩ ngaete mwaki ĩũlũ wa Yuta, na ũkamina nyũmba nene mbanakavye sya Yelusaleme.'),
('kam', 'AMO', 2, 6, 'Ũũ nĩw’o Yeova ũnũkwasya: Nũndũ wa mavĩtyo atatũ ma Isilaeli, ĩĩ, nũndũ wa ana, ndikathyũũa ũsilĩlo wayo; nĩkwĩthĩwa nĩmathooetye ala alũngalu vetha, na nĩmathooetye athĩni iatũ ilĩ—'),
('kam', 'AMO', 2, 7, 'o ala mendaa mũno kĩtoo kya nthĩ kĩthĩwe mĩtwenĩ ya ngya, na kwelelũkasya nzĩa ya ũla mũuu: na mũndũ na ĩthe makĩenda kwa mwĩĩtu ũmwe, mavukye syĩtwa yakwa ĩtheu:'),
('kam', 'AMO', 2, 8, 'na nĩmekomasya nthĩ ũtee wa kĩla kĩthembeo ĩũlũ wa ngũa syaiiwe ngwatĩlĩlyo; na nyũmbanĩ ya Ngai woo manyusĩaa mbinyu ya asu maumĩtw’e vaini.'),
('kam', 'AMO', 2, 9, 'Ĩndĩ nĩnaanangie Mũamoli mbee woo, ũla ũasa wake waĩ ta ũasa wa mĩtĩ ya mĩkũũ, na aĩ vinya ta mĩtĩ ya myaloni; ĩndĩ nĩnaanangie ũsyao wake kuma ĩũlũ, na mĩi yake kuma nthĩ.'),
('kam', 'AMO', 2, 10, 'Ĩngĩ nĩnamwambatisye kumumya nthĩ ya Misili, na namũtongoesya myaka mĩongo ĩna weũnĩ, mũmesye nthĩ ya Mũamoli.'),
('kam', 'AMO', 2, 11, 'Nakwa nookĩlilye athani ananĩ menyu, na Anasili anakenĩ menyu. Ti o ũu, inyw’ĩ ana ma Isilaeli? Ekũlya ũu Yeova.'),
('kam', 'AMO', 2, 12, 'Ĩndĩ nĩmwanengie Anasili mbinyu manyw’e, na mweeaĩa athani, mũkĩmea, Mũikathane.'),
('kam', 'AMO', 2, 13, 'Sisyai, ngamũvinyĩĩa vala mũĩ, o tondũ ĩkasya yĩvinyĩĩaa yusũĩtwe nĩ syove sya ngetha.'),
('kam', 'AMO', 2, 14, 'Na kũsemba kũkaaa kwa mũsembi; na ũla wĩ vinya ndakeyongeleela vinya; o na ũla wĩ ũtonyi ndaketangĩĩa mwene;'),
('kam', 'AMO', 2, 15, 'o na ũla wĩkalaa na ũta ndakaũngama; o na ũla wĩ maũũ mũno ndaketangĩĩa mwene; o na ũla ũtũlaa mbalasi ndaketangĩĩa mwene;'),
('kam', 'AMO', 2, 16, 'na ũla wĩ ũkũmbaũ katĩ wa ala me ũtonyi akakĩa e mũthei mũthenya ũsu, easya ũu Yeova.'),
('kam', 'AMO', 3, 1, 'Ĩw’ai ndeto ĩno ĩla Yeova ũneenete ĩũlũ wenyu, inyw’ĩ ana ma Isilaeli, ĩũlũ wa mũvĩa mũima ũla nambatisye kuma nthĩ ya Misili, ngyasya,'),
('kam', 'AMO', 3, 2, 'No inyw’ĩ nĩsĩ katĩ wa mĩvĩa yonthe ya nthĩ: kwondũ wa ũu ngamũsilĩlaa ũndũ wa mothũku menyu onthe.'),
('kam', 'AMO', 3, 3, 'Elĩ makaendan’ya vamwe, matew’anĩte?'),
('kam', 'AMO', 3, 4, 'Mũnyambũ ũkaluma kĩthekanĩ yĩla ũtakwatĩte? Mũnyambũ wa mũika ũkakoomea kĩsumonĩ kyaw’o, ethĩwa ndũkwete kĩndũ?'),
('kam', 'AMO', 3, 5, 'Nyũnyi nĩtonya kũkwatw’a nĩ kĩtei ĩũlũ wa nthĩ, vala ĩtaseũvĩw’e kĩtei? Kĩtei kĩkavyanyũka nthĩ, kĩtakwatĩtye kĩndũ nongi?'),
('kam', 'AMO', 3, 6, 'Soo ũkavuvĩwa ndũanĩ, na andũ mailea ũkĩa? Ũthũku ũkakwata ndũa, na ti Yeova ũwĩkĩte?'),
('kam', 'AMO', 3, 7, 'Nĩ w’o, Mwĩaĩi Yeova ndakeka ũndũ, ateũvuanĩsya athũkũmi make athani nzama yake.'),
('kam', 'AMO', 3, 8, 'Mũnyambũ nũminĩte kũluma; nũũ ũteĩw’a w’ĩa? Mwĩaĩi Yeova nũneenete; nũũ ĩndĩ ũtonya kũlea kwathana?'),
('kam', 'AMO', 3, 9, 'Nyaĩĩkyai ũvoo nyũmbanĩ nene mbanakavye vu Asitoti, na nyũmbanĩ nene mbanakavye nthĩ ya Misili, na kwasya, Ũmbanĩai iĩmanĩ sya Samalia, na mũisisya ũndũ inenevete ituu ila syĩ vo nthĩnĩ, na ũndũ mathĩna manenevete katĩ wasyo.'),
('kam', 'AMO', 3, 10, 'Nũndũ matyĩsĩ kwĩka w’o, easya Yeova, ala meyiĩaa ũng’endu na ũvutani nyũmbanĩ nene syoo mbanakavye.'),
('kam', 'AMO', 3, 11, 'Kwondũ wa ũu Mwĩaĩi Yeova easya atĩĩ: Kũkeethĩwa mũmaitha, o na kũthyũlũlũka ĩ nthĩ; na akavalũkya vinya waku nthĩ wume kwaku, na nyũmba syaku nene mbanakavye ikeethĩwa syĩ ndave.'),
('kam', 'AMO', 3, 12, 'Ũũ nĩw’o Yeova ũnũkwasya: O tondũ mũĩthi ũvonokanasya maũũ elĩ kuma kanyw’anĩ wa mũnyambũ, kana kĩlungu kya kũtũ, o ta ũu ana ma Isilaeli makavonokanw’a mekalaa Samalia kĩkotonĩ kya ũkomo, na ĩũlũ wa mĩto ya alili ya ũkomo.'),
('kam', 'AMO', 3, 13, 'Ĩw’ai inyw’ĩ, na kũsĩĩai nyũmba ya Yakovo, easya ũu Mwĩaĩi Yeova, Ngai wa nguthu.'),
('kam', 'AMO', 3, 14, 'Nũndũ mũthenya ũla nĩsilĩla Isilaeli ũndũ wa mavĩtyo make, ngasilĩla ithembeo sya Mbethi‐eli nasyo; na mbya sya kĩthembeo ikatilwa, na kũvalũka nthĩ.'),
('kam', 'AMO', 3, 15, 'Na ngakũna nyũmba ya ĩvinda ya mbevo vamwe na nyũmba ya ĩvinda ya syũa; na nyũmba iseũvĩtw’e na maeo ma nzou ikaanangĩka, na nyũmba ila nene ikathela, easya ũu Yeova.'),
('kam', 'AMO', 4, 1, 'Ĩw’ai ndeto ĩno, inyw’ĩ ng’ombe nga sya Mbasani, ila syĩ kĩĩmanĩ kya Samalia, ila ithĩnasya ngya, na kũvinyĩĩa athĩni, ila syĩaa eaĩi masyo, Etei, tũnyw’e.'),
('kam', 'AMO', 4, 2, 'Mwĩaĩi Yeova nĩwĩvĩtĩte na ũtheu wake, sisyai, mĩthenya nĩkamũkĩa, ĩla makamũtwaa na mboloi, na ũtialo wenyu na ngolya sya ũkwatya makũyũ.'),
('kam', 'AMO', 4, 3, 'Nenyu nĩmũkaumaalĩla vala ve movũthũe, kĩla ũmwe aeleele mbee wake; na mũkeeyĩkya inyw’ĩ ene Alimoni, easya ũu Yeova.'),
('kam', 'AMO', 4, 4, 'Ũkai Mbethi‐eli, mũvĩtye; ũkai Ngilikali, mwongeleele mavĩtyo; na etei nthembo syenyu kĩla kĩoko, na ilungu syenyu sya ĩkũmi ĩtina wa kĩla mĩthenya ĩtatũ;'),
('kam', 'AMO', 4, 5, 'na thembai nthembo ya mũvea ya kĩla kĩkĩĩtwe ĩlawa, na tavan’yai na kũnyaĩĩkya ũvoo wa nthembo sya kumya na ngoo ya kwenda: nũndũ ũu nũmwendeeasya, inyw’ĩ ana ma Isilaeli, easya ũu Mwĩaĩi Yeova.'),
('kam', 'AMO', 4, 6, 'O na ĩngĩ nakwa nĩnĩmũnengete maeo momũ ndũanĩ syenyu syonthe, na kwaĩwa nĩ kĩmũtũ kũndũ kwenyu kw’onthe; ĩndĩ mũtinzyokeete, easya ũu Yeova.'),
('kam', 'AMO', 4, 7, 'O na ĩngĩ nakwa nĩnĩmĩsiĩĩe mbua ndĩkaue kwenyu, yĩla vatiele myei ĩtatũ kũvikĩa ngetha; na namyusya ndũanĩ ĩmwe, na natuma ĩtaua ndũanĩ ĩngĩ: kĩlungu kĩmwe nĩkyauie, na kĩlungu kĩla kĩtaaua kyooma.'),
('kam', 'AMO', 4, 8, 'Na ĩndĩ ndũa ilĩ kana itatũ syanganga syathi ndũanĩ ĩmwe inyw’e kĩw’ũ, na ityaalaũka; ĩndĩ mũtinzyokeete, easya ũu Yeova.'),
('kam', 'AMO', 4, 9, 'Nĩnĩmũkũnĩte na wũmanĩlu na mbuka: wingĩ wa mĩũnda yenyu na mĩũnda yenyu ya mĩsavivũ na mĩkũyũ yenyu na mĩthata yenyu kĩtĩlĩ nĩkĩminĩte: ĩndĩ mũtinzyokeete, easya ũu Yeova.'),
('kam', 'AMO', 4, 10, 'Nĩnĩetete katĩ wenyu mũimũ o ta mũthemba ũla wa Misili: anake menyu nĩnĩmoaĩte na ũvyũ, na nĩndwaĩte mbalasi syenyu; na nĩndumĩte mũnyungo mũthũku wa mwakonĩ wa maeema wenyu wambata o na manyiũũnĩ menyu: ĩndĩ mũtinzyokeete, easya ũu Yeova.'),
('kam', 'AMO', 4, 11, 'Nĩnĩng’uthũlangĩte ndũa katĩ wenyu, o ta yĩla Ngai wang’uthũlangile Sotomo na Ngomola, na mwailyĩ kĩsinga kĩvulĩtw’e yekethenĩ: ĩndĩ mũtinzyokeete, easya ũu Yeova.'),
('kam', 'AMO', 4, 12, 'Kwondũ wa ũu ngakwĩka ũu, we Isilaeli; na nĩkwĩthĩwa ngakwĩka ũu, ĩyũmban’ye kũkomana na Ngai waku, we Isilaeli.'),
('kam', 'AMO', 4, 13, 'Nũndũ, sisya, ũsu wũmbaa iĩma, na wũmba kĩseve, na aivuanĩsya mũndũ ũla wĩ kĩlilikanonĩ kyake; ũla ũtusaa kĩoko kĩvindu, na kũkinyangaa kũndũ kũtũlu kwa nthĩ — Yeova, Ngai wa nguthu, nĩyo syĩtwa yake.'),
('kam', 'AMO', 5, 1, 'Ĩw’ai, inyw’ĩ, ndeto ĩno ĩla ngũneena ĩtw’ĩke kĩĩo kya kũmũĩĩa, inyw’ĩ nyũmba ya Isilaeli.'),
('kam', 'AMO', 5, 2, 'Mwĩĩtu mũtheu wa Isilaeli nũvalũkĩte; ndakokĩla ĩngĩ: nĩwĩkĩtw’e nthĩ ĩũlũ wa nthĩ yake; vai ũmwe wa kũmũkĩlya.'),
('kam', 'AMO', 5, 3, 'Nũndũ ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya: Ndũa ĩla yaumaalile me ngili ĩkatiala ĩana, na ĩla yaumaalile me ĩana ĩkatiala ĩkũmi, ma nyũmba ya Isilaeli.'),
('kam', 'AMO', 5, 4, 'Nũndũ Yeova etavya nyũmba ya Isilaeli atĩĩ, Manthai nyie, na mũkeethĩwa thayũ;'),
('kam', 'AMO', 5, 5, 'ĩndĩ mũikamanthe Mbethi‐eli, o na mũikalike Ngilikali, na mũikavĩte mũthi Mbeeli‐sieva: nũndũ vate ndĩi Ngilikali ĩkaenda yĩ ndave, na Mbethi‐eli ĩkatw’ĩka mana.'),
('kam', 'AMO', 5, 6, 'Manthai Yeova, na mũkeethĩwa thayũ; ndakese kwakana ta mwaki nyũmbanĩ ya Yosevu, na kũmĩmina, na kũtikethĩwa wa kũvosya nthĩnĩ wa Mbethi‐eli.'),
('kam', 'AMO', 5, 7, 'Inyw’ĩ ala mũalyũlaa ũsili wa katĩ wĩthĩwe kĩndũ kĩ ũũ, na kwĩkya ũlũngalu nthĩ,'),
('kam', 'AMO', 5, 8, 'mũmanthei ũla ũseũvĩtye Kĩeemea na Olioni, na kũalyũla kyuu kya kĩkw’ũ kĩthĩwe kĩoko, na kũtw’ĩkĩthya mũthenya kĩvindu kwondũ wa kũtuka; ũla wĩtaa manzĩ ma ũkanga moke, na aimatulũla ĩũlũ wa nthĩ (Yeova nĩyo syĩtwa yake);'),
('kam', 'AMO', 5, 9, 'ũla ũetae wanangĩko wa kĩthũlũmũko ĩũlũ wa ala me na vinya, na kwondũ wa ũu wanangĩko nĩwũkĩaa ngome.'),
('kam', 'AMO', 5, 10, 'Nĩnamũmenaa ũla ũmakanĩasya mbingĩlonĩ, na kũmũthĩtha mũno ũla ũneenaa w’o.'),
('kam', 'AMO', 5, 11, 'Nĩkwĩthĩwa ĩndĩ mũkinyangaa ũla ngya, na kũmumĩthya nganũ na vinya: nĩmwakĩte nyũmba sya mavia masũvye, ĩndĩ mũikatũa nthĩnĩ wasyo; nĩmũvandĩte mĩũnda ya mĩsavivũ mĩseo, ĩndĩ mũikanyw’a mbinyu yayo.'),
('kam', 'AMO', 5, 12, 'Nũndũ nĩnĩsĩ mavĩtyo menyu ũndũ maingĩvĩte, na naĩ syenyu ũndũ inenevete — inyw’ĩ ala mũthĩnasya alũngalu, na kwosa ĩvaki, na kwathũkya athĩni ala me mbingĩlonĩ matikose kĩla kyoo.'),
('kam', 'AMO', 5, 13, 'Kwondũ wa ũu ũla wĩ kĩlĩko akakilya ĩvinda ta yĩu; nũndũ nĩ ĩvinda ĩthũku.'),
('kam', 'AMO', 5, 14, 'Manthai ũseo, na ti ũthũku, nĩ kana mwĩthĩwe thayũ; na ĩndĩ Yeova, Ngai wa nguthu, akeethĩwa nenyu, o tondũ mwaasya.'),
('kam', 'AMO', 5, 15, 'Menai ũla ũthũku, na mũkyenda ũla ũseo, na kũlũlũmĩlya ũsili wa katĩ mbingĩlonĩ: nokwĩthĩwa Yeova, Ngai wa nguthu, eĩka ũtialo wa Yosevu nesa.'),
('kam', 'AMO', 5, 16, 'Kwondũ wa ũu Yeova, Ngai wa nguthu, Mwĩaĩi, easya atĩĩ: Kĩĩo kĩkeethĩwa nzĩanĩ nthanthau syonthe; na makaĩĩaa nzĩanĩ nene syonthe, Ĩiaa! Ĩiaa! Na makeeta mũĩmi kĩmetonĩ, na ala ai kũĩanĩ maĩe.'),
('kam', 'AMO', 5, 17, 'Na mĩũndanĩ yonthe ya mĩsavivũ kũkeethĩwa kĩĩo; nũndũ ngavĩtĩla katĩ waku, easya ũu Yeova.'),
('kam', 'AMO', 5, 18, 'Woo nĩ wenyu ala mwendaa mũthenya ũsu wa Yeova! Nĩ ũndũ wa kĩ mũkwenda kwĩthĩwa na mũthenya wa Yeova? Nĩ kĩvindu, na ti kyeni.'),
('kam', 'AMO', 5, 19, 'No ta kethĩwa mũndũ akakĩa mũnyambũ, na nduva ĩkakomana nake; kana akĩenda nyũmba na kwaĩĩsya kw’oko kwake wakonĩ, na nzoka ĩkĩmũũma.'),
('kam', 'AMO', 5, 20, 'Mũthenya ũsu wa Yeova ndũkethĩwa kĩvindu, na ti kyeni? O kĩvindu kĩnene, na vate ũtisu nthĩnĩ waw’o?'),
('kam', 'AMO', 5, 21, 'Nĩngũmena, nĩngũvũthya mboka syenyu, o na nditanaw’a nĩ maũmbano menyu makilĩtye.'),
('kam', 'AMO', 5, 22, 'Ĩĩ, o na mwanthembea nthembo syenyu sya kũvĩvw’a na nthembo sya mũtu, ndikasyĩtĩkĩla; o na ndikasyĩtĩkĩla nthembo sya mũuo sya indo syenyu nou.'),
('kam', 'AMO', 5, 23, 'Veta wasya wa mbathi syaku vala nĩĩ; nũndũ ndikew’a wasya wa tũnanda twaku.'),
('kam', 'AMO', 5, 24, 'Ĩndĩ ũsili wa katĩ ũtheee ta manzĩ, na ũlũngalu ta ũsĩ mũnene.'),
('kam', 'AMO', 5, 25, 'Mwaandetee nthembo sya kũtonywa na nthembo sya mũtu weũnĩ myaka mĩongo ĩna, inyw’ĩ nyũmba ya Isilaeli?'),
('kam', 'AMO', 5, 26, 'Ĩĩ, nĩmwakuie kakalũ ka mũsumbĩ wenyu na kakalũ ka mĩvw’anano yenyu, ndata ya ngai yenyu, ila mweeseũvĩsye ene.'),
('kam', 'AMO', 5, 27, 'Kwondũ wa ũu ngatuma mũenda mwĩ atave mbee wa Ndamasiku, easya ũu Yeova, ũla syĩtwa yake nĩ Ngai wa nguthu.'),
('kam', 'AMO', 6, 1, 'Woo nĩ wa ala methũmũĩtye Saioni, na wa ala mekalĩte meyelele kĩĩmanĩ kya Samalia, andũ me na nguma ma mbaĩ ĩla yĩ na ũnene, ala nyũmba ya Isilaeli ĩendaa kwoo!'),
('kam', 'AMO', 6, 2, 'Vĩtai mũende Kalene, na mũisisya; na kuma vo endai Amathi ĩla nene; na ĩndĩ theeai Ngathi ya Avilisiti: me kavaa kwĩ mosumbĩ asu? Kana mũvaka wamo nĩ mũnene kwĩ mũvaka wenyu?'),
('kam', 'AMO', 6, 3, 'Inyw’ĩ ala mũtwaangaa mũthenya Mũthũku kũasa, na kũtuma wĩkalo wa ũng’endu ũthengeea;'),
('kam', 'AMO', 6, 4, 'ala makomaa mokomonĩ ma maeo ma nzou, na kwĩkooteaa mokomonĩ moo, na kũĩsaa tũtena twa malondu maumĩtye ndĩthyanĩ, na tũsaũ maumĩtye kĩtũũnĩ;'),
('kam', 'AMO', 6, 5, 'ala mainaa mbathi sya mana na wasya wa kananda; ala meyambĩlĩlĩasya syĩndũ sya kũinga, o ta Ndaviti;'),
('kam', 'AMO', 6, 6, 'na ala manywĩaa mbinyu mbakũlinĩ, na kwĩvaka ene mauta ala maseo mbee; ĩndĩ ĩndĩ mati na woo nũndũ wa thĩna wa Yosevu.'),
('kam', 'AMO', 6, 7, 'Kwondũ wa ũu yu makaenda me atave vamwe na ala metavwa mbee; na kĩsekele kya ala meekootaa kĩkathela.'),
('kam', 'AMO', 6, 8, 'Mwĩaĩi Yeova nĩwevĩtie nake mwene, easya ũu Yeova, Ngai wa nguthu: Nĩngũthĩtha ũnene wa Yakovo, na nĩngũmena nyũmba nene syake mbanakavye; kwondũ wa ũu nganengane ĩ ndũa na syonthe ila syĩ nthĩnĩ wayo.'),
('kam', 'AMO', 6, 9, 'Na kũkeethĩwa, ethĩwa vakatiala andũ ĩkũmi nyũmbanĩ ĩmwe, makakw’a.'),
('kam', 'AMO', 6, 10, 'Na yĩla mwendw’a‐ĩthe wa mũndũ ũla mũkw’u wĩũkĩlya ĩ kimba, aumye mavĩndĩ nyũmbanĩ, o ũsu wĩkĩvĩvya, na akakũlya ũla wĩ kũndũ kwĩ nthĩnĩ kwa nyũmba, Ve o ũmwe wĩ naku? Nake akasũngĩa, Aiee; nĩvo ĩndĩ wĩasya, Kilya ki; nũndũ tũtitonya kũweta syĩtwa ya Yeova.'),
('kam', 'AMO', 6, 11, 'Nũndũ, sisya, Yeova nĩwaĩaĩte, na nyũmba ĩla nene ĩkakũnwa ĩye mawatũe, na nyũmba ĩla nini ĩye mawatũku.'),
('kam', 'AMO', 6, 12, 'Mbalasi ikasembela ĩvianĩ? Ve ũmwe wĩĩma vo na ng’ombe? Ũndũ inyw’ĩ mũalyũlĩte ũsili wa katĩ ũtw’ĩke nyongo, na ũsyao wa ũlũngalu ũtw’ĩke kĩndũ kĩ ũũ;'),
('kam', 'AMO', 6, 13, 'inyw’ĩ ala mũtanĩaa ũndũ wa mana, na kwasya, Tũtyĩyoseete mbya na vinya witũ ene?'),
('kam', 'AMO', 6, 14, 'Nũndũ, sisyai, ngamũkĩlĩlya mbaĩ, inyw’ĩ nyũmba ya Isilaeli, easya ũu Yeova, Ngai wa nguthu; na makamũthĩn’ya kuma ũlikĩlonĩ wa Amathi kũvika kalũsĩ ke Alava.'),
('kam', 'AMO', 7, 1, 'Ũũ nĩw’o Mwĩaĩi Yeova wambonisye: na, sisya, oombie ngie mwambĩlĩlyonĩ wa kũthongooa kwa ĩthongooa ya ĩtina; na, sisya, ĩthongooa yĩu ya ĩtina yaĩ ĩtina wa mũsumbĩ eengethya nyeki sya ũĩthyo.'),
('kam', 'AMO', 7, 2, 'Na kweethĩwa, yĩla syaminũkĩlye kũya nyeki sya nthĩ, nĩvo naisye, Ame Mwĩaĩi Yeova, ekea, nĩngũkwĩsũva: Yakovo akaũngama ata? Nũndũ nĩ mũnini.'),
('kam', 'AMO', 7, 3, 'Yeova eetũnga ũndũ wa ũu: Ũũ ndũkethĩwa, easya ũu Yeova.'),
('kam', 'AMO', 7, 4, 'Ũũ nĩw’o Mwĩaĩi Yeova wambonisye: na, sisya, Mwĩaĩi Yeova eetie mokĩlan’yo ma mwaki; na wamina ala manzĩ ma syũngũ nene, na waĩ ũtonya kũya ĩ nthĩ.'),
('kam', 'AMO', 7, 5, 'Nĩvo naisye, Ame Mwĩaĩi Yeova, eka, nĩngũkwĩsũva: Yakovo akaũngama ata? Nũndũ nĩ mũnini.'),
('kam', 'AMO', 7, 6, 'Yeova eetũnga ũndũ wa ũu: O na ũũ ndũkethĩwa, easya ũu Yeova.'),
('kam', 'AMO', 7, 7, 'Ũũ nĩw’o wambonisye: na, sisya, Mwĩaĩi aũngama ũtee wa wako wakĩtwe wĩ mũthime na kavilũ, e na kavilũ kw’okonĩ kwake.'),
('kam', 'AMO', 7, 8, 'Na Yeova angũlya, Amosi, wĩona kyaũ? Nakwa nasya, Nĩ kavilũ. Nĩvo Mwĩaĩi waisye, Sisya, nĩngwia kavilũ katĩ wa andũ makwa Isilaeli; ndikamavĩta ĩngĩ o na ĩndĩĩ;'),
('kam', 'AMO', 7, 9, 'na kũla kũndũ kũtũlu kwa Isaka kũkeethĩwa kũthei, na kũla kũndũ kũtheu kwa Isilaeli kũkaanangwa; na ngookĩlĩla nyũmba ya Yelovoamu na ũvyũ.'),
('kam', 'AMO', 7, 10, 'Nĩvo Amasia mũthembi wa Mbethi‐eli watũmanie kwa Yelovoamu mũsumbĩ wa Isilaeli, akĩmwĩa, Amosi nũkũsamĩĩte katĩ wa nyũmba ya Isilaeli: nthĩ nĩemetwe nĩ kũmĩĩsya ndeto syake syonthe.'),
('kam', 'AMO', 7, 11, 'Nũndũ Amosi aasya atĩĩ, Yelovoamu akooawa na ũvyũ, na vate ndĩi Isilaeli akatavwa kumw’a nthĩ yake.'),
('kam', 'AMO', 7, 12, 'Na ĩngĩ Amasia amwĩa Amosi, We mwoni, kĩa, ũthi nthĩ ya Yuta, na ũkĩaa kĩmũtũ kw’o, na kwathanĩaa kw’o:'),
('kam', 'AMO', 7, 13, 'ĩndĩ ndũkathanĩe ĩngĩ o na ĩndĩĩ vaa Mbethi‐eli; nũndũ nĩ vala vandũ vatheu va mũsumbĩ, na nĩ nyũmba ya kĩũsumbĩ.'),
('kam', 'AMO', 7, 14, 'Nĩvo Amosi wasũngĩie, na amwĩa Amasia, Ndyaĩ mwathani, o na ndyaĩ mwana wa mwathani; ĩndĩ naĩ mũĩthi, na mũsĩvĩi wa mĩkũyũ:'),
('kam', 'AMO', 7, 15, 'na Yeova ambosa ngĩĩthya ndĩthya sya mbũi na malondu, na Yeova ambĩa, Enda, wathane andũnĩ makwa ma Isilaeli.'),
('kam', 'AMO', 7, 16, 'Na yu kwondũ wa ũu ĩw’a ndeto ya Yeova: We wĩmbĩa, Ndũkathanĩe Isilaeli, na ndũkaneenee nyũmba ya Isaka ndeto yaku;'),
('kam', 'AMO', 7, 17, 'kwondũ wa ũu Yeova easya atĩĩ: Kĩveti kyaku kĩkeethĩwa ĩlwaya ndũanĩ, na ana maku na eĩtu maku makavalũkw’a na ũvyũ, na nthĩ yaku ĩkaaanw’a na ũlii wa kũthima; naku mwene ũkakw’ĩa nthĩ mbuku, na Isilaeli vate ndĩi kũtavwa aumw’e nthĩ yake.'),
('kam', 'AMO', 8, 1, 'Ũũ nĩw’o Mwĩaĩi Yeova wambonisye: na, sisya, kĩkavũ kĩ ũsyao wa ĩvinda ya syũa.'),
('kam', 'AMO', 8, 2, 'Nake akũlya, Amosi, wĩona kyaũ? Nakwa nasũngĩa, Kĩkavũ kĩ ũsyao wa ĩvinda ya syũa. Nĩvo Yeova wambĩie, Mũminũkĩlyo nĩwooka ĩũlũ wa andũ makwa Isilaeli; ndikamavĩta ĩngĩ o na ĩndĩĩ.'),
('kam', 'AMO', 8, 3, 'Na mbathi sya ĩkalũ ikatw’ĩka iĩo mũthenya ũsu, easya ũu Mwĩaĩi Yeova: simba ikeethĩwa nyingĩ; kĩla vandũ makasyĩkya nza mavindĩtye.'),
('kam', 'AMO', 8, 4, 'Ĩw’ai ũũ, inyw’ĩ ala mwendaa kũmelya athĩni, na kũtuma ngya sya nthĩ ithela,'),
('kam', 'AMO', 8, 5, 'mũkyasya, Mũtiso wa mwei ũkathela ĩndĩĩ, nĩ kana twĩthoosye lĩu wa mbaa ngetha? Na savato ũkathela ĩndĩĩ, nĩ kana tumĩlye nganũ, tũkĩnyivya eva, na tũkyongela sekeli, na kũkenga andũ na ithimi sya ũkengani;'),
('kam', 'AMO', 8, 6, 'nĩ kana tũthooe ngya na vetha, na kũthooa mũthĩni na iatũ ilĩ, na kũthoosya nganũ ĩla ĩte nzeo?'),
('kam', 'AMO', 8, 7, 'Yeova nĩwevĩtie na ũnene wa Yakovo, Vate ndĩi ndikolwa nongi nĩ wĩa woo o na ũmwe.'),
('kam', 'AMO', 8, 8, 'Nthĩ ndĩkatetema nũndũ wa ũu, na kĩla ũmwe ũmĩtwĩe ndakameta? Ĩĩ, ĩkookĩla vyũ ta ũla Ũsĩ; na ĩkathokoana na kũusya ĩngĩ, ta Ũsĩ wa Misili.'),
('kam', 'AMO', 8, 9, 'Na kũkeethĩwa mũthenya ũsu, ngathũsya syũa yĩ katambanga, na ngatulĩthya nthĩ kĩvindu kwĩ mũthenya kwĩsang’ũlĩtye, easya ũu Mwĩaĩi Yeova.'),
('kam', 'AMO', 8, 10, 'Na ngaalyũla mboka syenyu itw’ĩke kĩmeto, na mbathi syenyu syonthe itw’ĩke kĩĩo; na ngatuma inyunyu syonthe ivotowa makunia, na ũvaa ĩũlũ wa kĩla mũtwe; na ngakĩtw’ĩkĩthya ta kũĩĩwa kwa mwana e ũmwe, na mũminũkĩlyo wamo ta mũthenya wĩ ũũ.'),
('kam', 'AMO', 8, 11, 'Sisya, mĩthenya nĩyũkĩte, easya ũu Mwĩaĩi Yeova, ĩla ngaete yũa nthĩ, na ti yũa ya lĩu, o na waũni wa kĩw’ũ, ĩndĩ nĩ ya kwĩw’a ndeto sya Yeova.'),
('kam', 'AMO', 8, 12, 'Na makangangaa kuma ũkanga kũvika ũkanga, na kuma ngalĩ ya ĩũlũ o na kũvika ngalĩ ya wumĩlonĩ wa syũa; makasemba kũũ na kũũ mamanthe ndeto ya Yeova, na matikamyona.'),
('kam', 'AMO', 8, 13, 'Mũthenya ũsu eĩtu aseo atheu na anake makanyala nũndũ wa waũni.'),
('kam', 'AMO', 8, 14, 'Ala mevĩtaa na naĩ ya Samalia, na kwasya, O tondũ ngai yaku, we Ndani, ĩ thayũ; na, O tondũ mwĩkalĩle wa Mbeeli‐sieva wĩ thayũ; makavalũka, na matikokĩla ĩngĩ.'),
('kam', 'AMO', 9, 1, 'Noonie Mwĩaĩi aũngeme ũtee wa kĩthembeo: na asya, Kũna mĩthya ya ituĩ, nĩ kana myalyo ya mĩomo ĩthingithe; noimĩtilangĩla ilungu mĩtwenĩ yoo yonthe; na ngooaa ũtialo woo na ũvyũ: vati ũmwe wamo ũkakĩa, na vati ũmwe wamo ũkavonoka.'),
('kam', 'AMO', 9, 2, 'O na makenza kũvika Seoli, kw’oko kwakwa kũkamaumya o vo; o na makambata ĩtunĩ, ngamatũnga nthĩ kuma vo.'),
('kam', 'AMO', 9, 3, 'O na makeevitha ene kĩĩmanĩ kya Kalimeli ĩũlũ, ngamantha na kũmaumya o vo; o na me avithe kyũngũnĩ kya ũkanga ndikamone, o vo ngeeaĩa nzoka, na ĩkamaũma.'),
('kam', 'AMO', 9, 4, 'O na makaenda mbee wa amaitha moo me atave, o vo ngeeaĩa ũvyũ, na ũkamoaa: na ngamaketeea na metho makwa nĩmeke naĩ, na ndimeka nesa.'),
('kam', 'AMO', 9, 5, 'Nũndũ Mwĩaĩi, Yeova wa nguthu, nĩwe ũla ũkiitaa nthĩ na ĩkĩtweka, na onthe ala mamĩtwĩe makameta; na ĩkookĩla vyũ ta ũla Ũsĩ, na ĩkalika ĩngĩ, ta Ũsĩ wa Misili;'),
('kam', 'AMO', 9, 6, 'nĩwe ũla wakaa nyũmba syake matunĩ, na kũlũlũmĩlya mwambĩlĩlyo wa ũtũo wake nthĩ; ũla wĩtaa manzĩ ma ũkanga moke, na akĩmatulũla ĩũlũ wa nthĩ; Yeova nĩyo syĩtwa yake.'),
('kam', 'AMO', 9, 7, 'Inyw’ĩ mũi ta ana ma Aethiovia kwakwa, inyw’ĩ ana ma Isilaeli? Ekũlya ũu Yeova. Ndyaambatya Isilaeli kuma nthĩ ya Misili, na Avilisiti kuma Kavitoli, na Asilia kuma Kili?'),
('kam', 'AMO', 9, 8, 'Sisyai, metho ma Mwĩaĩi Yeova me ĩũlũ wa ũsumbĩ mwathe, na ngawananga kuma ĩũlũ wa nthĩ; ate o ndikamyananga vyũ nyũmba ya Yakovo, easya ũu Yeova.'),
('kam', 'AMO', 9, 9, 'Nũndũ, sisyai, ngeeaĩa, na ngathũngũthangĩsya nyũmba ya Isilaeli katĩ wa mbaĩ syonthe, tondũ lĩu wa mbaa ngetha ũthũngũthangaw’a kĩsunginĩ, ĩndĩ kũikavalũka kaveke kamwe nthĩ.'),
('kam', 'AMO', 9, 10, 'Athe onthe na andũ makwa makooawa na ũvyũ, ala maasya, Ũla ũthũku ndũkatũkwata, o na kũkomana naitũ.'),
('kam', 'AMO', 9, 11, 'Mũthenya ũsu ngaũngamya wĩkalo wa Ndaviti ũla mũvalũku, na kũlinda mawatũe maw’o; na ngatũngĩĩa kũla waombokie, na ngootũngĩĩa o tondũ watilyĩ mĩthenya ya tene;'),
('kam', 'AMO', 9, 12, 'nĩ kana mamesye ũtialo wa Etomu, na mbaĩ syonthe ila syĩtanĩaw’a na syĩtwa yakwa, easya ũu Yeova ũla wĩkaa ũu.'),
('kam', 'AMO', 9, 13, 'Sisyai, mĩthenya nĩyũkĩte, yĩla mũĩmi wĩkwata mũkethi, na mũangi wa nzavivũ wĩkwata ũla ũvuĩaa mbeũ, easya ũu Yeova; na iĩma ikalovotangya mbinyu ĩ mũyo, na tũlĩma tw’onthe tũkatweka.'),
('kam', 'AMO', 9, 14, 'Na ngatũnga andũ makwa Isilaeli kuma kũtavwanĩ, na makatũngĩĩa ndũa ila syaĩ maanzo, na kwitũaa; na makavanda mĩũnda mĩsavivũ, na kũnyusaa mbinyu yayo; o na makaseũvya mĩũnda, na kũĩsaa ũsyao wayo.'),
('kam', 'AMO', 9, 15, 'Na ngamavanda nthĩ yoo, na maikakũwa nthĩ yoo ĩngĩ ĩla nĩmanengete, easya ũu Yeova Ngai waku.'),
('kam', 'OBA', 1, 1, 'Woni wa Ovatia. Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya ũndũ wa Etomu: Nĩtwĩw’ĩte ũvoo kuma kwa Yeova, na mũtũmwa nũtũmĩtwe katĩ wa i mbaĩ, akyasya, Ũkĩlai inyw’ĩ, na tũkĩlei tũkwatye kaũ nake.'),
('kam', 'OBA', 1, 2, 'Sisya, nĩngũtw’ĩte mũnini katĩ wa i mbaĩ: nũvũthĩtw’e mũno.'),
('kam', 'OBA', 1, 3, 'Ngathĩĩo sya ngoo yaku nikũkengete, we ũla ũtwĩe mĩvatĩnĩ ya ĩvia, ũla ũtũo waku wĩ ĩũlũ; ũla waasya ngoonĩ yake, Nũũ ũla ũkantheesya nthĩ?'),
('kam', 'OBA', 1, 4, 'O na ũkambata ĩũlũ ta ndiũ, o na ũkaka ndala yaku katĩ wa ndata, ngakũtheesya nthĩ kuma vo, easya ũu Yeova.'),
('kam', 'OBA', 1, 5, 'Ethĩwa ing’ei ikakũkĩa, kana ethĩwa avutani makakũkĩa ũtukũ (wanangĩtwe ta kĩ!), Matikoya mũvaka meanĩwa? Ethĩwa atwi ma nzavivũ makakũkĩa, matikatialya nzavivũ imwe sya kũkolan’ya?'),
('kam', 'OBA', 1, 6, 'A! Ũndũ maũndũ ma Esau mamanthĩtwe! Ũndũ mothwii make mavithe maumbũĩtwe!'),
('kam', 'OBA', 1, 7, 'Andũ onthe ala mew’anĩte naku nĩmakumaaisye, o kũvika mũvakanĩ: andũ ala waĩ mũuo namo nĩmakũkengete, na makũkĩlya vinya; ala maĩsaa lĩu waku nĩmakũteaa na kĩtei ungu waku: vai ũmanyi nthĩnĩ wake.'),
('kam', 'OBA', 1, 8, 'Yeova ekũlya, Mũthenya ũsu ndikananga andũ oĩ ma Etomu, na ũmanyi wae kĩĩmanĩ kya Esau?'),
('kam', 'OBA', 1, 9, 'Na ngũmbaũ syaku, we Temani, ikateva, kũvika yĩla kĩla ũmwe wĩvetwa aume kĩĩmanĩ kya Esau kwondũ wa kũawa.'),
('kam', 'OBA', 1, 10, 'Nũndũ wa ũng’endu ũla wĩkĩtwe mwana‐a‐mwenyu Yakovo, nthoni ikakũvw’ĩka, na ũkavetwa tene na tene.'),
('kam', 'OBA', 1, 11, 'Mũthenya ũla waũngamĩte mũingo ũla ũngĩ, mũthenya ũla aeni matwaie syĩndũ syake, na andũ ma nthĩ ĩngĩ malikile mbingĩlonĩ syake, na kũlimana ũndũ wa Yelusaleme, o naku wailyĩ ta ũmwe wamo.'),
('kam', 'OBA', 1, 12, 'Ĩndĩ ndũkasisye mũthenya wa mwana‐a‐mwenyu mũthenya wa thĩna wake mũnene, na ndũkatane ĩũlũ wa ana ma Yuta mũthenya wa wanangĩko woo; o na ndũkaneene na ngathĩĩo mũthenya wa thĩna.'),
('kam', 'OBA', 1, 13, 'Ndũkalike mbingĩlonĩ ya andũ makwa mũthenya wa wanangĩko woo mũnene; ĩĩ, ndũkasisye kũnyamawa kwoo mũthenya wa wanangĩko woo mũnene, o na mũikaakwate syĩndũ syoo mũthenya wa wanangĩko woo mũnene.'),
('kam', 'OBA', 1, 14, 'Na ndũkaũngame mavĩtanĩonĩ ma nzĩa, kũmamina andũ make ala meũvonoka; na ndũkamanengane ala make meũtiala mũthenya ũsu wa thĩna.'),
('kam', 'OBA', 1, 15, 'Nũndũ mũthenya wa Yeova wĩ vakuvĩ ĩũlũ wa mbaĩ syonthe: o ũndũ weekie, ũkeekwa o w’o; kwĩka kwaku kũkasyoka ĩũlũ wa mũtwe waku mwene.'),
('kam', 'OBA', 1, 16, 'Nũndũ o tondũ mwanyw’ĩĩe kĩĩmanĩ kyakwa kĩtheu, o ta ũu mbaĩ syonthe ikanyusaa ĩndĩ yonthe; ĩĩ, ikanyw’a, na kũmelya, na ikeethĩwa o ta itaĩ vo.'),
('kam', 'OBA', 1, 17, 'Ĩndĩ kĩĩmanĩ kya Saioni kũkeethĩwa ala makavonoka, nakyo kĩkeethĩwa kĩtheu; na nyũmba ya Yakovo ĩkamesya ng’ũndũ syoo.'),
('kam', 'OBA', 1, 18, 'Na nyũmba ya Yakovo ĩkatw’ĩka mwaki, na nyũmba ya Yosevu ũlĩlĩnzĩ, na nyũmba ya Esau ĩkatw’ĩka mavuthĩ, na makakana katĩ woo, na kũmamina; na vaikatiala o na ũmwe nyũmbanĩ ya Esau; nũndũ Yeova nũneenete ũu.'),
('kam', 'OBA', 1, 19, 'Na ala ma ngalĩ ya Ĩtheo makamesya kĩĩma kya Esau, na ala ma nthĩ ndindimalu makamesya Avilisiti; na makamesya weũ wa Evalaimu, na weũ wa Samalia; na Mbenyamini akamesya Ngileati.'),
('kam', 'OBA', 1, 20, 'Na ala mataviwe ma nguthu ĩsu ya ana ma Isilaeli, ala me katĩ wa Akanaani, makamesya o kũvika Nzalevathi; na ala mataviwe ma Yelusaleme ala me Sevalati, makamesya ndũa sya ngalĩ ya ĩtheo.'),
('kam', 'OBA', 1, 21, 'Na atangĩĩi makambata kĩĩmanĩ kya Saioni makĩsilĩle kĩĩma kya Esau; na ũsumbĩ ũkeethĩwa wa Yeova.'),
('kam', 'JON', 1, 1, 'Na ĩndĩ ndeto ya Yeova yamũkĩe Yona mwana wa Amitai, ĩkĩmwĩa,'),
('kam', 'JON', 1, 2, 'Ũkĩla, ũende Nineva, ndũa ĩsu nene, na ũkĩmyũkĩlĩlya wasya; nũndũ ũthũku woo nĩ mwambatu vala nĩĩ.'),
('kam', 'JON', 1, 3, 'Ĩndĩ Yona ookĩla akĩĩe Talisisi aume vala ve Yeova; na atheea Yova, na awĩla ngalawa ĩendete Talisisi: na ĩndĩ aĩva ĩtuvi yayo, na alika nthĩnĩ wayo, kũendan’ya namo Talisisi aume vala ve Yeova.'),
('kam', 'JON', 1, 4, 'Ĩndĩ Yeova aete kĩseve kĩnene ĩũlũ wa ũkanga, na kwaĩ kĩuutani kĩ vinya ĩũlũ wa ũkanga, o na ngalawa yesaa kwanangwa.'),
('kam', 'JON', 1, 5, 'Nĩvo ĩndĩ andũ ma ngalawa meewie w’ĩa, na meekaĩla kĩla mũndũ ngai yake; na mekangya syĩndũ ila syaĩ ngalawanĩ ũkanganĩ, nĩ kana yĩthĩwe mbũthũ kwamo. Ĩndĩ Yona nĩwalikĩte kũndũ kwĩ nthĩnĩ ngalawanĩ; na akakoma, akalĩkwa.'),
('kam', 'JON', 1, 6, 'Na ĩndĩ mũnene wa ngalawa amũkĩa, na amũkũlya, Wĩ na kĩ, we mũkomi? Ũkĩla, wĩkaĩle Ngai waku, no kwĩthĩwa Ngai atũlilikana, tũtikae.'),
('kam', 'JON', 1, 7, 'Na maneenan’ya kĩla mũndũ na ũla ũngĩ, Ũkai, tũlimane, nĩ kana tũmanye nĩ ũndũ waũ ũthũku ũũ wĩ ĩũlũ waitũ. Na ĩndĩ malimana, naw’o wamũvalũkĩla Yona.'),
('kam', 'JON', 1, 8, 'Nĩvo ĩndĩ mamwĩie, Tũtavye, nĩtũũkwĩsũva, nũũ ũla ũtumie ũthũku ũũ wĩthĩwa ĩũlũ waitũ; wĩa waku nĩ mwaũ? Na wumĩte nakũ? Nthĩ yaku nĩ yĩkũ? Na wĩ mũmwaũ?'),
('kam', 'JON', 1, 9, 'Nake amea, Nyie nĩ Mũevelania; na nĩngũkĩa Yeova, Ngai wa ĩtu, ũla wombie ũkanga na nthĩ nyũmũ.'),
('kam', 'JON', 1, 10, 'Nĩvo ĩndĩ andũ meewie w’ĩa mũno, na mamũkũlya, Wĩkĩte ũndũ mwaũ? Nũndũ andũ nĩmamanyie kana nĩwakĩĩte kuma vala ve Yeova, nĩkwĩthĩwa nĩwamatavya.'),
('kam', 'JON', 1, 11, 'Nĩvo ĩndĩ mamwĩie, Twĩkwĩka ata, nĩ kana ũkanga ũtũuĩsye? Nũndũ ũkanga wookĩlangilye itulumo mbee na mbee.'),
('kam', 'JON', 1, 12, 'Nake amea, Mbũkĩlyai, na mũimbĩkya ũkanganĩ; na ĩndĩ ũkanga ũkamũuĩsya: nũndũ nĩnĩsĩ kana nũndũ wakwa kĩuutani kĩĩ kĩnene kĩ ĩũlũ wenyu.'),
('kam', 'JON', 1, 13, 'Ĩndĩ andũ matwaa na vinya masyoke nthĩ; ĩndĩ matyaatonya; nũndũ ũkanga wamokĩlangĩlye itulumo mbee na mbee.'),
('kam', 'JON', 1, 14, 'Kwondũ wa ũu mamwĩkaĩla Yeova, na masya, Nĩtũũkwĩsũva, ame Yeova, nĩtũũkwĩsũva, tũikae nũndũ wa thayũ wa mũndũ ũũ, na ndũkatũtalĩle nthakame ĩte ĩvĩtyo; nũndũ we, ame Yeova, nĩweeka ũla wakwendeesya.'),
('kam', 'JON', 1, 15, 'Na ĩndĩ mamũkĩlya Yona, na mamwĩkya ũkanganĩ; na ũkanga waeka kũkĩlangan’ya.'),
('kam', 'JON', 1, 16, 'Nĩvo ĩndĩ andũ makĩie Yeova mũno; na mathembea Yeova nthembo, na meava.'),
('kam', 'JON', 1, 17, 'Na Yeova aseũvĩtye ĩkũyũ ya kũmũmelya Yona; na Yona aĩ ĩvunĩ ya ĩkũyũ mĩthenya ĩtatũ na matukũ atatũ.'),
('kam', 'JON', 2, 1, 'Nĩvo ĩndĩ Yona wavoyie Yeova Ngai wake e ĩvunĩ ya ĩkũyũ.'),
('kam', 'JON', 2, 2, 'Nake asya, Nĩnĩkaĩlile Yeova kwondũ wa thĩna wakwa, Nake anzũngĩa; Nakaya nĩ nda ya Seoli, Naku weew’a wasya wakwa.'),
('kam', 'JON', 2, 3, 'Nũndũ nũmbĩkĩtye kyũngũnĩ, katĩ wa maũkanga nthĩnĩ, Na kĩw’ũ kingĩ nĩkinthyũlũlũkĩte; Itulumo syaku syonthe, na mĩkĩndo yaku ya manzĩ nivĩtĩle ĩũlũ wakwa.'),
('kam', 'JON', 2, 4, 'Nakwa nasya, Nĩmbetetwe mbee wa metho maku; Ĩndĩ ngasisya ĩngĩ kwelekela ĩkalu yaku ĩtheu.'),
('kam', 'JON', 2, 5, 'Manzĩ nĩmanthyũlũlũkĩte ngalĩ syonthe, o na kũvika ngoonĩ; Manzĩ ma syũngũ nene nĩmanthyũlũlũkĩte; Malula nĩmendingĩlĩte mũtwe.'),
('kam', 'JON', 2, 6, 'Nĩnĩlikĩte ĩtheo kũvika myambĩlĩlyo ya iĩma; Nthĩ nĩyĩĩmbingĩĩte na ivingo syayo tene na tene: Ĩndĩ nĩwumĩtye thayũ wakwa ĩimanĩ, ame Yeova Ngai wakwa.'),
('kam', 'JON', 2, 7, 'Yĩla ngoo yakwa ĩnĩũthelekelaa nthĩnĩ wakwa, nĩnĩmũlilikanile Yeova; Na mboya yakwa nĩyũkie kwaku, ĩkalũnĩ yaku ĩtheu.'),
('kam', 'JON', 2, 8, 'Ala mendaa maũndũ ma mana ma ũvũngũ Meimaa tei woo ene.'),
('kam', 'JON', 2, 9, 'Ĩndĩ ngakũthembea vamwe na wasya wa mũvea; Ũndũ nĩvĩtĩte ngeanĩsya. Ũtangĩĩo nĩ wa Yeova.'),
('kam', 'JON', 2, 10, 'Na Yeova aneena na ĩkũyũ, nayo yamũtavĩka Yona nthĩ nyũmũ.'),
('kam', 'JON', 3, 1, 'Na ndeto ya Yeova yamũkĩa Yona ĩvinda ya kelĩ, ĩkĩmwĩa,'),
('kam', 'JON', 3, 2, 'Ũkĩla, ũende Nineva, ndũa ĩsu nene, na ũmĩtavye ũtavan’yo ũla ngũkwĩa.'),
('kam', 'JON', 3, 3, 'Na ĩndĩ Yona ookĩla, na athi Nineva, kwĩanana na ndeto ya Yeova. Na Nineva yaĩ ndũa nene mũno, mũendo wa mĩthenya ĩtatũ.'),
('kam', 'JON', 3, 4, 'Na Yona ambĩlĩlya kũlika ĩla ndũa mũendo wa mũthenya ũmwe, nake ookĩlya wasya, akyasya, Vatiele o matukũ mĩongo ĩna, na Nineva ĩkĩng’uthũlangwa.'),
('kam', 'JON', 3, 5, 'Na andũ ma Nineva meetĩkĩla Ngai; na matavan’ya kũtĩĩa kũya, na meekĩa makunia, kuma ũla mũnene wamo o na kũvika ũla mũnini wamo.'),
('kam', 'JON', 3, 6, 'Na ũvoo wavikĩa mũsumbĩ wa Nineva, nake ookĩla kuma kĩvĩlanĩ kyake kya ũsumbĩ, na aia ngũa yake ya ũsumbĩ, na eevw’ĩka makunia, na ekala mũunĩ.'),
('kam', 'JON', 3, 7, 'Nake aumya ũtũmane na anyaĩĩkya Nineva kw’onthe kwa ũtw’ĩo wa mũsumbĩ na anene make me ndaĩa, akyasya, Kũtikasamwe kĩndũ o na kĩmwe nĩ mũndũ kana indo, ndĩthya ya ng’ombe kana ya mbũi na malondu; kũtikaĩwe, kana kũnyuwa kĩw’ũ;'),
('kam', 'JON', 3, 8, 'ĩndĩ nĩkwĩvw’ĩkwe makunia, mũndũ o na indo, na nĩkwĩkaĩlwe Ngai na vinya: ĩĩ, nĩmethyũũe kĩla ũmwe kuma mũendelenĩ wake mũthũku, na kuma ũng’endunĩ ũla wĩ mokonĩ make.'),
('kam', 'JON', 3, 9, 'Nũũ wĩsĩ ethĩwa Ngai ndeĩthyũũa na kwĩtũnga, na kwĩthyũũa aeke ũthatu wake mwai kana tũtikae?'),
('kam', 'JON', 3, 10, 'Na Ngai oona mawĩa moo, kana nĩmeethyũũie kuma mũendelenĩ woo mũthũku; na Ngai eetũnga aeka ũthũku ũla waĩtye akameka; na ndaawĩka.'),
('kam', 'JON', 4, 1, 'Ĩndĩ ũndũ ũsu wamwĩw’ĩthya Yona woo mũno, na aĩ mũthatu.'),
('kam', 'JON', 4, 2, 'Nake avoya Yeova, na asya, Nĩngũkũvoya, ame Yeova, ũndũ ũũ tiw’o naisye, o yĩla naĩ nthĩ yaitũ? Kwondũ wa ũu nĩneekalaatile kũkĩĩa Talisisi; nũndũ nĩneesĩ kana we wĩ Ngai mũseo, na wĩ tei, mũmĩĩsya wa kũthata, na wĩ na ũseo mwingĩ wĩ wendo, na wĩtũngaa ndũkeke ũla ũthũku.'),
('kam', 'JON', 4, 3, 'Kwondũ wa ũu yu, ame Yeova, numya thayũ, nĩngũkwĩsũva; nũndũ nĩ kavaa kwakwa nĩkw’e kwĩ kwĩkala thayũ.'),
('kam', 'JON', 4, 4, 'Na Yeova amũkũlya, Nũkwĩka nesa ũkĩthata?'),
('kam', 'JON', 4, 5, 'Nĩvo ĩndĩ Yona waumie ndũanĩ, na ekala ũtee wa ndũa ngalĩ ya wumĩlonĩ wa syũa, na kũu eeyakĩa kalwanda, na ekala muunyĩnĩ wako, ambe kwona ũndũ ndũa ĩnĩkwĩkĩka.'),
('kam', 'JON', 4, 6, 'Na Yeova Ngai aseũvya wũngũ, na atuma ũtamba ĩũlũ vala ve Yona, kana ũtw’ĩke muunyĩ ĩũlũ wa mũtwe wake, ũmũvonokye mwĩkalĩlenĩ wake mũthũku. Na ĩndĩ Yona aĩ mũtanu mũno nũndũ wa wũngũ.'),
('kam', 'JON', 4, 7, 'Ĩndĩ Ngai aseũvya kĩinyũ kũikya ũnĩ ũsu, na kyaũma ũ wũngũ, na wooma.'),
('kam', 'JON', 4, 8, 'Na kweethĩwa, yĩla syũa yaumie, Ngai aseũvya kĩseve kĩ ĩvyũvĩ kyumĩte wumĩlonĩ wa syũa; na syũa yavĩvya Yona mũtwe, na akwatwa nĩ mũnyalo, na eekũlĩlya nĩ kana akw’e, na asya, Nĩ kavaa kwakwa nĩkw’e kwĩ kwĩkala thayũ.'),
('kam', 'JON', 4, 9, 'Na Ngai akũlya Yona, Nũkwĩka nesa ũkĩthata nũndũ wa wũngũ? Nake asũngĩa, Nĩngwĩka nesa kũthata, o na kũvikĩa kũkw’a.'),
('kam', 'JON', 4, 10, 'Na Yeova amwĩa, We nĩwĩw’ĩe wũngũ tei, ũla ũtaaũthĩnĩa, o na ndwaatuma wĩana; ũla ũnameie ũtukũ na wanangĩka o ũtukũ:'),
('kam', 'JON', 4, 11, 'nakwa ndyaĩlwe nĩ kwĩw’ĩa Nineva tei, ndũa ĩsu nene, ĩla nthĩnĩ wayo ve aingĩ kwĩ andũ ngili ĩana na mĩongo ĩlĩ ala matatonya kũvathũkan’ya katĩ wa kw’oko kwoo kwa aũme na kw’oko kwoo kwa aka; na ĩngĩ yĩ indo mbingĩ?'),
('kam', 'MIC', 1, 1, 'Ndeto ya Yeova ĩla yamũkĩe Mika Mũmolasiti mĩthenya ya Yothamu, na Aasu, na Esekia, asumbĩ ma Yuta, ĩla wonie ũndũ wa Samalia na Yelusaleme.'),
('kam', 'MIC', 1, 2, 'Ĩw’ai, inyw’ĩ ngo sya andũ, inyw’onthe; ĩthukĩĩsye, we nthĩ, na syonthe ila syĩ vo: na Mwĩaĩi Yeova namũkũsĩĩe, Mwĩaĩi e ĩkalũnĩ yake ĩtheu.'),
('kam', 'MIC', 1, 3, 'Nũndũ, sisya, Yeova, nũkumĩla aumĩte vandũ vake, na akatheea, na kũkinyanga kũndũ kũtũlu kwa nthĩ.'),
('kam', 'MIC', 1, 4, 'Na iĩma ikatweka ungu wake, na myanda ĩkaatũka, ta ĩseso vala ve mwaki, ta manzĩ mavaũũkĩle kĩvaũũkonĩ.'),
('kam', 'MIC', 1, 5, 'Nũndũ ũũ w’onthe nĩ ũndũ wa ĩvĩtyo ya Yakovo, na ũndũ wa naĩ sya nyũmba ya Isilaeli. Ĩvĩtyo ya Yakovo nĩ yĩva? Ti Samalia? Na kũndũ kũtũlu kwa Yuta nĩ kwĩkũ? Ti Yelusaleme?'),
('kam', 'MIC', 1, 6, 'Kwondũ wa ũu ngatw’ĩkĩthya Samalia ta kĩvumbu kĩ mũũndanĩ, na ta kũndũ kwa kũvanda mĩsavivũ; na ngekya mavia mayo kyandanĩ, na ngavukũa myambĩlĩlyo yayo.'),
('kam', 'MIC', 1, 7, 'Na mĩvw’anano yayo yonthe myasũvye ĩkakũnwa ĩtilĩkange tũlungu, na matuvi mayo onthe makavĩvw’a na mwaki, na mĩvw’anano yayo yonthe ngamyananga; nũndũ nĩyamyũmbanĩtye na ĩtuvi ya ũmalwaya, na ĩkatũngĩthw’a ĩtuvinĩ ya ũmalwaya.'),
('kam', 'MIC', 1, 8, 'Kwondũ wa ũu ngaĩa na kũkaya; ngathi nĩvuĩte na nĩ mũthei; ngaamba o ta mbĩwa, na kũĩa kĩĩo kĩilyĩ kya nyaa.'),
('kam', 'MIC', 1, 9, 'Nũndũ mawũkite make mativoeka; nũndũ nĩwũkĩte o na kũvika Yuta; nũvikĩte mbingĩlonĩ ya andũ makwa, o Yelusaleme.'),
('kam', 'MIC', 1, 10, 'Mũtikotavan’ye Ngathi, mũtikaĩe nongi: ku Mbethi‐le‐avila nĩnĩyalalĩtye kĩtoonĩ.'),
('kam', 'MIC', 1, 11, 'Vĩta, we ũla ũtwĩe Savili, wĩ mũthei na wĩ na nthoni: ũla ũtwĩe Nzaanani ndanamba kumĩla; kũkaya kwa Mbethi‐eseli kũkamũvena inyw’ĩ wĩkwatyo wavo.'),
('kam', 'MIC', 1, 12, 'Nũndũ ũla ũtwĩe Malothi eteele ũseo e na kĩũũyũ, nĩkwĩthĩwa ũthũku nĩ mũku kuma kwa Yeova kũvika mbingĩlonĩ ya Yelusaleme.'),
('kam', 'MIC', 1, 13, 'Ova mbalasi yĩ maũũ ĩkasyanĩ ya kaũ, we ũla ũtwĩe Lakisi: nĩyo mwambĩlĩlya wa naĩ kwa mwĩĩtu wa Saioni; nũndũ mavĩtyo ma Isilaeli nĩmoonekie nthĩnĩ waku.'),
('kam', 'MIC', 1, 14, 'Kwondũ wa ũu ũkanenga Molesethingathi mũthĩnzĩo wa kũtaanĩsya: nyũmba sya Akisivu ikeethĩwa kĩndũ kya ũkengana kwa asumbĩ ma Isilaeli.'),
('kam', 'MIC', 1, 15, 'We ũla ũtwĩe Malesa, ngesa ũkũetee ũla ũkakũsumbĩka: ũtaĩo wa Isilaeli ũkavika o na Atulamu.'),
('kam', 'MIC', 1, 16, 'Ĩyenze ũvaa, noitilanga nzw’ĩĩ syaku nũndũ wa syana ila ikũtanasya: nenevangya ũvaa waku ta ndiũ; nũndũ nĩ nendu syĩ ndave kuma kwaku.'),
('kam', 'MIC', 2, 1, 'Woo nĩ wa ala masũanĩaa ũthũku na kwĩkĩa ũthũku mokomonĩ moo! Na kĩoko kũikya maiwĩka, nũndũ wĩ ũtonyinĩ wa kw’oko kwoo.'),
('kam', 'MIC', 2, 2, 'Na nĩmew’ĩaa mĩũnda ĩtomo, na kũmyosa; o na nyũmba, na maivenana: na nĩmathĩnasya mũndũ na nyũmba yake, o na mũndũ na ũtiĩwa wake.'),
('kam', 'MIC', 2, 3, 'Kwondũ wa ũu Yeova easya atĩĩ: Sisyai, mũvĩa ũũ nĩngũsũanĩĩa ũthũku, ũla mũtakeyumya ngingo syenyu vo, o na mũikathi na wĩng’athĩlĩlyo; nũndũ nĩ ĩvinda ĩthũku.'),
('kam', 'MIC', 2, 4, 'Mũthenya ũsu makamũtila ngelekan’yo, na kũĩa kĩĩo kĩ woo, na kwasya, Nĩtwanangĩtwe vyũ: nũnũkũalyũla kĩanda kya andũ makwa: a! Ũndũ ũnũkũkĩveta kwakwa! Nũnũkũaĩa ala ang’endu mĩũnda yaitũ.'),
('kam', 'MIC', 2, 5, 'Kwondũ wa ũu ĩkomanonĩ ya Yeova ndũkethĩwa na ũmwe ũla ũkekya ũlii wa kũthima na nzĩa ya kula.'),
('kam', 'MIC', 2, 6, 'Mũikathane, na mathanĩĩa. Matikamathanĩe: ivũthya itikathela.'),
('kam', 'MIC', 2, 7, 'Kũkaw’a, we nyũmba ya Yakovo, Veva wa Yeova nĩ mũoleku? Meko aa nĩ make? Ndeto syakwa itimwĩkaa nesa ũla ũendaa na mĩendele myaĩlu?'),
('kam', 'MIC', 2, 8, 'Ĩndĩ o ĩoo yĩthei andũ makwa manookĩlile ta mũmaitha: nĩmumasya na vinya ngũa ya ĩũlũ kuma ngũanĩ ya ala mavĩtaa meyelele ta andũ matekwenda kaũ.'),
('kam', 'MIC', 2, 9, 'Aka ma andũ makwa nĩmũmaumasya nyũmbanĩ syoo sya kwendeesya; syana syoo nini nĩmwivenaa ndaĩa yakwa tene na tene.'),
('kam', 'MIC', 2, 10, 'Ũkĩlai, na mũkĩthi; nũndũ vaa ti vandũ venyu va kũthũmũa; nũndũ wa ũvuku ũla wanangaa, ĩĩ, o na wanango mũnene mũno.'),
('kam', 'MIC', 2, 11, 'Ethĩwa mũndũ aendete nthĩnĩ wa veva wa ũvũngũ nũnũkengana, akyasya, Ngakwathanĩa ũndũ wa mbinyu na kĩla kĩtoonasya; o nake kaeethĩwa mwathani wa andũ aa.'),
('kam', 'MIC', 2, 12, 'Nditĩa kũmban’ya onthe a maku, we Yakovo; nditĩa kũmban’ya ũtialo wa Isilaeli; ngamomban’ya vamwe ta malondu ma Mbosila, ta ndĩthya ya mbũi na malondu katĩ wa kĩsesi kyayo; makookĩlya kĩuumo kĩnene nũndũ wa andũ kwingĩva.'),
('kam', 'MIC', 2, 13, 'Ũla mũvevenzi ambata mbee wamo; meevũthũĩa na mavĩta kũvika mbingĩlonĩ, na kumaalĩla vo; na mũsumbĩ woo atongosya mbee woo, na Yeova vu mbee.'),
('kam', 'MIC', 3, 1, 'Na nasya, Ĩw’ai, nĩngũmwĩsũva, inyw’ĩ atongoi ma kwa Yakovo na asumbĩki ma nyũmba ya Isilaeli: ti ũndũ wenyu kũmanya ũsili wa katĩ?'),
('kam', 'MIC', 3, 2, 'Inyw’ĩ ala mũmenaa ũseo, na kwenda ũthũku; ala mũthĩnzaa kĩkonde kyoo, na nyama syoo kũsyumya mavĩndĩnĩ moo;'),
('kam', 'MIC', 3, 3, 'o na ĩngĩ ala mũĩsaa nyama sya mĩĩ ya andũ makwa, na kũmathĩnza kĩkonde kyoo, na kũtũlanga mavĩndĩ moo, na kũmatilanga tũlungu, ta tũkwĩkĩwa mbisũnĩ, na ta nyama kĩtevenĩ.'),
('kam', 'MIC', 3, 4, 'Nĩvo memwĩkaĩla Yeova, ĩndĩ ndakamasũngĩa; ĩĩ, akamavitha ũthyũ wake ĩvinda yĩu, kwĩanana na ũndũ meekie ũthũku mekonĩ moo.'),
('kam', 'MIC', 3, 5, 'Ũũ nĩw’o Yeova ũnũkwasya ũndũ wa athani ala mavĩtĩthasya andũ makwa; ala maũmaa na maeo moo, na kwaasya, Mũuo; na o ũla ũtekwĩkĩa kĩndũ makanyw’anĩ moo, no makwatasya kaũ nake:'),
('kam', 'MIC', 3, 6, 'Kwondũ wa ũu kũkeethĩwa ũtukũ kwenyu, nĩ kana mũtikethĩwe na woni; na kũkeethĩwa kĩvindu kwenyu, nĩ kana mũtikaaũsye; na syũa yĩkamathũĩa athani, na mũthenya ũkeethĩwa mwiũ kwoo.'),
('kam', 'MIC', 3, 7, 'Na oni makasonokw’a, na ala maaũasya makathokoana; ĩĩ, onthe makeevw’ĩka ilomo; nũndũ vati ũsũngĩo wa Ngai.'),
('kam', 'MIC', 3, 8, 'Ĩndĩ ngalĩ ĩ yakwa, kwondũ wa Veva wa Yeova, nĩnusũĩtw’e nĩ vinya, na ũsili, na ũtonyi, non’ye Yakovo ĩvĩtyo yake, na Isilaeli naĩ yake.'),
('kam', 'MIC', 3, 9, 'Ĩw’ai ũũ, nĩngũmwĩsũva, inyw’ĩ atongoi ma nyũmba ya Yakovo, na asumbĩki ma nyũmba ya Isilaeli, ala mũthĩthaa ũsili wa katĩ, na kwelelũkasya ũlũngalu w’onthe.'),
('kam', 'MIC', 3, 10, 'Meaka Saioni na nthakame, na Yelusaleme na ũthũku.'),
('kam', 'MIC', 3, 11, 'Atongoi mayo masilaa nũndũ wa mĩthĩnzĩo, na athembi mayo mamanyĩasya nũndũ wa kũtuvwa, na athani mayo maaũasya nũndũ wa mbesa: o na kau meĩkwatya Yeova, na kwasya, Yeova nde katĩ waitũ? Vati ũthũku ũkatũvikĩa.'),
('kam', 'MIC', 3, 12, 'Kwondũ wa ũu Saioni ĩkenzwa ta mũũnda kwondũ wenyu, na Yelusaleme ĩkatw’ĩka ivumbu, na kĩĩma kya ĩ nyũmba ta kũndũ kũtũlu kwa mũtitũ.'),
('kam', 'MIC', 4, 1, 'Ĩndĩ mĩthenya ya mũminũkĩlyo kũkeethĩwa, kĩĩma kĩ nyũmba ya Yeova kĩkekalaa kĩ kĩtũlu kwĩ ila ingĩ, na kũkĩla ĩũlũ wa tũlĩma; na ngo sya andũ ikaendaa vo.'),
('kam', 'MIC', 4, 2, 'Na mbaĩ mbingĩ ikathi ikyasya, Ũkai, twambate kĩĩmanĩ kya Yeova, na nyũmbanĩ ya Ngai wa Yakovo; na akatũmanyĩasya mĩendele yake, na tũkaendaa nzĩanĩ syake. Nũndũ mĩao ĩkaumaa Saioni, na ndeto ya Yeova ĩkaumaa Yelusaleme;'),
('kam', 'MIC', 4, 3, 'na akasilanasya ngo mbingĩ sya andũ, na akatusĩaa mbaĩ syĩ vinya sya kũasa maũndũ: na makatusya mbyũ syoo itw’ĩke mĩthya ya maembe ma ng’ombe, na matumo moo tũvyũ twĩ ngoto twa ũsea; mbaĩ ndĩkokĩlĩlya mbaĩ ĩngĩ ũvyũ, o na itikemanyĩsya kaũ ĩngĩ.'),
('kam', 'MIC', 4, 4, 'Ĩndĩ makekalaa kĩla mũndũ ĩtina wa mũsavivũ wake na ĩtina wa mũkũyũ wake; na vati ũmwe ũkatuma makĩa: nũndũ kanyw’a wa Yeova wa nguthu nũneenete ũu.'),
('kam', 'MIC', 4, 5, 'Nũndũ ngo syonthe sya andũ iendaa kĩla ũmwe syĩtwanĩ ya ngai yake: na ithyĩ tũkaendaa syĩtwanĩ ya Yeova Ngai waitũ tene na tene.'),
('kam', 'MIC', 4, 6, 'Mũthenya ũsu, ngatũnga ũla ũthuaa, na ngatũnga ũla ũlũngĩtw’e, na ũla nĩthĩnĩtye, easya ũu Yeova;'),
('kam', 'MIC', 4, 7, 'na ngatw’a ũla wathuaa ũtialo, na ũla wekĩtw’e kũasa mbaĩ yĩ vinya: na Yeova akamasumbĩka kĩĩmanĩ kya Saioni kuma yu o na kũvika tene na tene.'),
('kam', 'MIC', 4, 8, 'Naku, we mwako mũtũlu wa mũnyoolo wa ndĩthya ya mbũi na malondu, kalĩma ka mwĩĩtu wa Saioni, kwaku ũkooka, ĩĩ, ũsumbĩko wa mbee ũkooka, ũsumbĩ wa mwĩĩtu wa Yelusaleme.'),
('kam', 'MIC', 4, 9, 'Na yu nĩkĩ ũkũkaya na wasya mũnene? No kwĩ mũsumbĩ nthĩnĩ waku, mũtai waku nĩwaĩte, ũndũ woo ũkũkwatĩte ta mũndũ mũka ũnũkwaũnya?'),
('kam', 'MIC', 4, 10, 'Ĩthĩwa na woo, na ũithĩna ũsyae, we mwĩĩtu wa Saioni, o ta mũndũ mũka ũnũkwaũnya; nũndũ yu ũkauma ndũanĩ, na ũkatũa weũnĩ, na ũkathi o kũvika Mbaviloni: nĩkw’o wĩtangĩĩĩwa; nĩkw’o Yeova wĩkwovoesya kuma kw’okonĩ kwa amaitha maku.'),
('kam', 'MIC', 4, 11, 'Na yu mbaĩ mbingĩ nikũmbanĩe, ila syaasya, Navukw’e, na metho maitũ nĩmone ũndũ tũkwenda ĩũlũ wa Saioni.'),
('kam', 'MIC', 4, 12, 'Ĩndĩ matyĩsĩ mosũanĩo ma Yeova, o na matiũmanya nzama yake; nũndũ nũmombanĩtye ta syove sya ngetha kĩvũĩonĩ.'),
('kam', 'MIC', 4, 13, 'Ũkĩla, we mwĩĩtu wa Saioni, ũvũe; nũndũ ngatw’ĩkĩthya ũvya waku kĩaa, na ngatw’ĩkĩthya mavũngũ maku ũthuku; na ũkakũna ngo mbingĩ sya andũ itw’ĩke tũlungu: na ngavathĩa Yeova ũtandĩthyo woo, na syĩndũ syoo Mwĩaĩi wa nthĩ yonthe.'),
('kam', 'MIC', 5, 1, 'Yu ũkeeyũmban’ya nguthu nguthu, we mwĩĩtu wa nguthu; nũtũthyũlũlũkĩte atũtw’ĩkanĩsye; makakũna mũsili wa Isilaeli na ndata ĩtau.'),
('kam', 'MIC', 5, 2, 'Ĩndĩ we, Mbethi‐leemu ya Evilatha, ũla wĩ mũnini ũtatalwa katĩ wa ngili sya Yuta, kwaku kũkauma ũmwe ambũkĩe ũla wĩtw’ĩka mũsumbĩki kwa Isilaeli; ũla kumĩla kwake nĩ kuma ĩvinda ya tene, kuma tene tene.'),
('kam', 'MIC', 5, 3, 'Kwondũ wa ũu akaekana namo, kũvika ĩvinda yĩla ũla ũnũkwaũnya wĩĩthĩwa asyaĩte: nĩvo ĩndĩ ũtialo wa ana‐a‐ĩthe make wĩsyoka kwa ana ma Isilaeli.'),
('kam', 'MIC', 5, 4, 'Na akaũngama, na akaĩthya ĩĩthya yake vinyanĩ wa Yeova, ũnenenĩ wa syĩtwa ya Yeova Ngai wake: na makekala; nũndũ yu akeethĩwa e mũnene kũvika itulunĩ sya nthĩ.'),
('kam', 'MIC', 5, 5, 'Na mũndũ ũsu akeethĩwa mũuo witũ. Yĩla Mũasuli wĩũka nthĩ yaitũ, na aikinyanga nthĩnĩ wa nyũmba sitũ nene mbanakavye, nĩvo twĩmũkĩlĩlya aĩthi mũonza, na andũ anene nyanya.'),
('kam', 'MIC', 5, 6, 'Na makaananga nthĩ ya Asuli na ũvyũ, o na nthĩ ya Nimiloti molikĩlonĩ mayo: nake akatũtangĩĩa kuma kwa Mũasuli, yĩla wĩũka nthĩ yaitũ, na yĩla wĩkinyanga mũvakanĩ witũ.'),
('kam', 'MIC', 5, 7, 'Na ũtialo wa Yakovo ũkeethĩwa katĩ wa ngo mbingĩ sya andũ o ta ĩmwe kuma kwa Yeova, ta mĩono ya mbua nyekinĩ, ila itekalaa nũndũ wa mũndũ, o na kweteela ana ma andũ.'),
('kam', 'MIC', 5, 8, 'Na ũtialo wa Yakovo ũkeethĩwa katĩ wa i mbaĩ, o katĩ wa ngo mbingĩ sya andũ, ta mũnyambũ katĩ wa nyamũ sya mũtitũnĩ, ta mũnyambũ wa mũika katĩ wa ndĩthya sya malondu; ũla, ethĩwa wavĩtĩla vo, ũangĩaa nthĩ na kũtembũanga tũlungu, na kũti wa kũtangĩĩa.'),
('kam', 'MIC', 5, 9, 'Kw’oko kwaku nĩkũkĩlw’e ĩũlũ wa nthũ syaku, na amaitha maku onthe nĩmavetwe.'),
('kam', 'MIC', 5, 10, 'Na kũkeethĩwa mũthenya ũsu, ngaveta mbalasi syaku syume vala ũĩ, na ngaananga makasya maku ma kaũ, easya ũu Yeova:'),
('kam', 'MIC', 5, 11, 'na ngaveta ndũa sya nthĩ yaku, na ngang’uthũlanga ngome syaku syonthe syĩ vinya.'),
('kam', 'MIC', 5, 12, 'Na ngaveta mooi maume kw’okonĩ kwaku; na ndũkethĩwa na ala mathanaa maũndũ ĩngĩ:'),
('kam', 'MIC', 5, 13, 'na ngaveta mĩvw’anano yaku myasũvye na ituĩ syaku kuma vala ũĩ; na ndũkathaitha ĩngĩ wĩa wa moko maku;'),
('kam', 'MIC', 5, 14, 'na ngakũa Aselimu yaku yume vala ũĩ; na ngaananga ndũa syaku.'),
('kam', 'MIC', 5, 15, 'Na ngaĩvanĩsya kwa mbaĩ ingĩ ila iteew’aa nĩ mũthatu na mũthilĩku.'),
('kam', 'MIC', 6, 1, 'Ĩw’ai yu ũndũ Yeova ũnũkwasya: Ũkĩla, ũkatetee mbee wa iĩma, na tũlĩma nĩtwĩw’e wasya waku.'),
('kam', 'MIC', 6, 2, 'Ĩw’ai, inyw’ĩ iĩma, ngananĩo ya Yeova, na inyw’ĩ myambĩlĩlyo ya nthĩ ĩla yĩkalaa; nũndũ Yeova e na ngananĩo na andũ make, na akatetan’ya na Isilaeli.'),
('kam', 'MIC', 6, 3, 'We ũko wakwa, nĩkwĩkĩte ata? Na nĩkũnoetye ũndũnĩ wĩva? Ngũsĩĩa.'),
('kam', 'MIC', 6, 4, 'Nũndũ nĩnakwambatisye kũkumya nthĩ ya Misili, na nakwovosya kuma nyũmbanĩ ya ũkombo; na natũma Mose, na Aluni, na Miliamu makũtongoesye.'),
('kam', 'MIC', 6, 5, 'Ame andũ makwa, lilikanai yu ũndũ Mbalaki mũsumbĩ wa Moavi wasũanĩie, na ũndũ Mbalaamu mwana wa Mbeoli wamũsũngĩie; lilikanai ũndũ kweekĩkie kuma Sitimu kũvika Ngilikali, nĩ kana mũmanye meko malũngalu ma Yeova.'),
('kam', 'MIC', 6, 6, 'Ngathengeea mbee wa Yeova na kyaũ, na kwĩkunamĩsya Ngai ũla wĩ ĩũlũ? Ngamũthengeea nĩ na nthembo sya kũvĩvw’a, na tũsaũ twa mwaka ũmwe?'),
('kam', 'MIC', 6, 7, 'Yeova akendeew’a nĩ ngili sya ndũũme, kana nĩ ngili makũmi sya mbũsĩ sya mauta? Nganengane ĩkithathi yakwa nũndũ wa ĩvĩtyo yakwa, ũsyao wa mwĩĩ wakwa nũndũ wa naĩ ya ngoo yakwa?'),
('kam', 'MIC', 6, 8, 'Nake nũkwonetye ũndũ ũseo, we mũndũ; na ũndũ ũla Yeova ũnũkũandũa kwaku nĩ mwaũ, ate o kwĩkaa ũlũngalu, na kwendaa ũseo, na kũendanasya na Ngai waku?'),
('kam', 'MIC', 6, 9, 'Wasya wa Yeova nũkwanĩĩsya ndũa, na mũndũ wĩ ũĩ akoona syĩtwa yaku: mĩw’ei ndata, na ũla ũmĩnyuvĩte.'),
('kam', 'MIC', 6, 10, 'Ve mothwii maie ma ũthũku o na yu nyũmbanĩ ya mũthũku, na kĩthimi kĩte kĩanĩu kĩla kĩthatasya?'),
('kam', 'MIC', 6, 11, 'Ngeethĩwa nĩ mũtheu nĩ na ithimi ila nthũku, na nĩ na mũvuko wĩ mavia ala mathimaa ma ũkenganĩ?'),
('kam', 'MIC', 6, 12, 'Nũndũ athwii mayo mausũĩtwe nĩ ũng’endu, na ala mamĩtwĩe nĩmaneenete movũngũ, na nĩmĩ syoo nĩ ngengani makanyw’anĩ moo.'),
('kam', 'MIC', 6, 13, 'Kwondũ wa ũu nakwa nĩngũkũnĩte ĩkũna yĩ woo; nĩngũtw’ĩte ĩanzo kwondũ wa naĩ syaku.'),
('kam', 'MIC', 6, 14, 'Ũkaya, ĩndĩ ndũkavũna; na kũnyivw’a kwaku ũkeethĩwa nakw’o: na ũkaia, ĩndĩ ndũkasũvĩĩkya; na kĩla wĩsũvĩa ngakĩnenga ũvyũ.'),
('kam', 'MIC', 6, 15, 'Ũkavuĩa, ĩndĩ ndũkaketha; ũkakinyanga mathata, ĩndĩ ndũkevaka a mauta; na ngetha ya mĩsavivũ, ĩndĩ ndũkanyw’a ĩ mbinyu.'),
('kam', 'MIC', 6, 16, 'Nũndũ myamũlo ya Omili nĩyakwatawa, na mawĩa onthe ma nyũmba ya Aavu, na nĩmũkinyaa motaonĩ moo; nĩ kana ngũtw’ĩkĩthye ĩanzo, na ala mavatwĩe ma kũtimbwa: na mũkakua kĩvũthya kya andũ makwa.'),
('kam', 'MIC', 7, 1, 'Woo nĩ wakwa! Nũndũ nĩilyĩ ta yĩla mombanĩtye mosyao ma ĩvinda ya syũa, ta ũkolan’yo wa ngetha ya nzavivũ: vati kĩtũngo kya kũĩwa; ngoo yakwa nĩyendete ĩkũyũ yĩla yambaa kwĩw’a.'),
('kam', 'MIC', 7, 2, 'Mũkĩi wa Ngai nĩwaĩte kũũ nthĩ, na kũti ũmwe mũlũngalu katĩ wa andũ: onthe moveesyaa metĩkye nthakame; nĩmasyĩmaa kĩla mũndũ mwana‐a‐ĩthe na kĩtei.'),
('kam', 'MIC', 7, 3, 'Moko moo me ũndũnĩ ũla ũthũku kũwĩka na kĩthing’ĩĩsyo; mũnene wĩ mbee ũsumbĩnĩ nĩwĩtasya, na mũsili nĩwĩyũmbanĩtye kwosa mũthĩnzĩo; na mũndũ wĩ nguma, nũneenaa kwenda kũthũku kwa ngoo yake: o ta ũu nĩmatumaa ũndũ ũsu vamwe.'),
('kam', 'MIC', 7, 4, 'Ũla mũseo mbee katĩ woo ailyĩ mũtae wa kĩthekanĩ; ũla mũlũngalu mbee nĩ mũthũku kwĩ wiio wa mĩw’a: mũthenya wa asyaĩĩsya maku, o wa kũsiw’a kwaku, nĩ mũku; yu kũkeethĩwa kũsaanĩw’a kwoo.'),
('kam', 'MIC', 7, 5, 'Mũtikaĩkĩĩe mũtũi; mũtikekwatye mũnyanya; sũvĩa ilomo sya kanyw’a waku kwa mũndũ mũka ũla ũkomaa kĩthũinĩ kyaku.'),
('kam', 'MIC', 7, 6, 'Nũndũ mwana nĩwanangaa ndaĩa ya ĩthe, na mwĩĩtu nũng’endeaa inyia wake, na mũka‐a‐mwana nũng’endeaa inyia wa mũũme; amaitha ma mũndũ nĩ andũ ma nyũmba yake mwene.'),
('kam', 'MIC', 7, 7, 'Ĩndĩ ngalĩ ĩ yakwa, ngamũsisya Yeova; ngamweteela Ngai wa ũtangĩĩo wakwa: Ngai wakwa akambĩw’a.'),
('kam', 'MIC', 7, 8, 'Ndũkatane ĩũlũ wakwa, we mũmaitha wakwa: yĩla ngũvalũka, ngookĩla; yĩla ngwĩkala kĩvindunĩ, Yeova akeethĩwa kyeni kwakwa.'),
('kam', 'MIC', 7, 9, 'Ngakua kũthilĩka kwa Yeova, nũndũ nĩnĩmũvĩtanĩsye, kũvika andetea, na kũsilĩla ũndũ wakwa: akanumĩlya kyeninĩ, na ngoona ũlũngalu wake.'),
('kam', 'MIC', 7, 10, 'Nĩvo ĩndĩ mũmaitha wakwa wĩwona, na nthoni ikamwĩkunĩkĩlya ũla wambĩie, Aĩva Yeova Ngai waku? Metho makwa makoona ũndũ ngwenda ĩũlũ wake; yu akakinyangĩwa nthĩ ta ndaka syĩ nzĩanĩ nene.'),
('kam', 'MIC', 7, 11, 'A! Mũthenya wa kwaka maũvai maku! Mũthenya ũsu ũtw’ĩo ũkavetwa kũasa.'),
('kam', 'MIC', 7, 12, 'Mũthenya ũsu makooka kwaku kuma Asuli na ndũanĩ sya Misili, na kuma Misili o kũvika ũla Ũsĩ, na kuma ũkanga kũvika ũkanga, na kuma kĩĩma kũvika kĩĩma.'),
('kam', 'MIC', 7, 13, 'Ĩndĩ nthĩ ĩkeethĩwa nthei nũndũ wa ala mamĩtwĩe, kwondũ wa ũsyao wa meko moo.'),
('kam', 'MIC', 7, 14, 'Ĩthya andũ maku na ndata yaku, ĩĩthya ya ũtiĩwa waku, yĩla yĩtwĩe yĩ yoka mũtitũnĩ ku Kalimeli: yĩĩsae Mbasani na Ngileati, o ta mĩthenya ya tene.'),
('kam', 'MIC', 7, 15, 'Ngoonan’ya kwoo maũndũ ma ũseng’ya o ta mĩthenya ĩla waumie nthĩ ya Misili.'),
('kam', 'MIC', 7, 16, 'I mbaĩ ikoona na ikĩsonoka ũndũ wa ũtonyi wasyo w’onthe; ikakunĩka kanyw’a na kw’oko; matũ masyo makeethĩwa matew’a.'),
('kam', 'MIC', 7, 17, 'Ikanyenya kĩtoo ta nzoka; ikooka itetemete kuma mawĩvithonĩ masyo iilyĩ ta tũsamũ twa nthĩ tũla tũtambũkaa; ikooka syĩ na w’ĩa kwa Yeova Ngai waitũ, na nũndũ waku ikakĩa.'),
('kam', 'MIC', 7, 18, 'Nũũ Ngai ũilyĩ taku, ũla ũekeaa ũthũku, na kũkĩla naĩ ya ũtialo wa ũtiĩwa wake? Ndekalaa na ũthatu wake ĩndĩ yonthe, nĩkwĩthĩwa nĩwendeeaw’a nĩ ũseo wĩ wendo.'),
('kam', 'MIC', 7, 19, 'Akatwĩw’ĩa ĩnee ĩngĩ; akakinyanga mothũku maitũ na nyaĩĩ; na ũkekya naĩ syoo syonthe syũngũnĩ sya ũkanga.'),
('kam', 'MIC', 7, 20, 'We ũkeanĩsya ũla w’o kwa Yakovo, na ũseo wĩ wendo kwa Avalaamu, ũla weevĩtĩe aaĩthe maitũ kuma mĩthenya ya tene.'),
('kam', 'NAM', 1, 1, 'Ndeto ngito ũndũ wa Nineva. Ĩvuku ya woni wa Naumu Mũelikosi.'),
('kam', 'NAM', 1, 2, 'Yeova nĩ Ngai wĩ kĩwĩu na nũĩvanĩasya; Yeova nũĩvanĩasya na nĩwusũĩtwe nĩ ũthilĩku; Yeova nĩwĩĩvanĩasya kwa nthũ syake, na nĩwiaa ũthilĩku nũndũ wa amaitha make.'),
('kam', 'NAM', 1, 3, 'Yeova nĩ mũmĩĩsya wa kũthata, na mũnene ũtonyinĩ, na ndakamũtala o na ata mũvĩtan’ya ta ũte na ũndũ: Yeova e na nzĩa yake kĩlinginĩ na kĩuutaninĩ, na mathweo nĩ kĩtoo kya nyaĩĩ syake.'),
('kam', 'NAM', 1, 4, 'Nũkanasya ũkanga, na akong’alya, na kũng’alya mbũsĩ syonthe: Mbasani nĩkũleela, na Kalimeli; na ĩlaa ya Levanoni nĩyĩkũvova.'),
('kam', 'NAM', 1, 5, 'Iĩma nitetemaa nũndũ wake, na tũlĩma tũkĩtweka; na nthĩ nĩyũkĩlanĩtye mbee wake, ĩĩ, nthĩ, na syonthe ila imĩtwĩa.'),
('kam', 'NAM', 1, 6, 'Nũũ ũla ũtonya kũũngama mbee wa ũthilĩku wake? Na nũũ ũla ũtonya kwĩkala wainĩ wa ũthatu wake? Ũthilĩku wake nĩ mwonosye ta mwaki, na mavia manene nĩmatũanganĩtw’e nĩwe.'),
('kam', 'NAM', 1, 7, 'Yeova nĩ mũseo, ngome yĩ vinya mũthenya wa thĩna; na nũmesĩ ala mevithaa nthĩnĩ wake.'),
('kam', 'NAM', 1, 8, 'Ĩndĩ akaminũkĩlya vandũ vayo vyũ na kĩw’ũ kingĩ kĩvĩtĩte, na akamaatĩĩa amaitha make malike kĩvindũnĩ.'),
('kam', 'NAM', 1, 9, 'Mwĩsũanĩĩa Yeova ata? Akaminũkĩlya vyũ; thĩna ndũkokĩla ĩvinda ya kelĩ.'),
('kam', 'NAM', 1, 10, 'O na makwatanĩte ta mĩw’a, na matoonetw’e nĩ kũnyw’a kwoo, ĩndĩ nĩmaminĩtwe vyũ ta ũa wũmũ.'),
('kam', 'NAM', 1, 11, 'Kwĩ ũmwe wumĩte kwaku, ũla ũsũanĩĩaa Yeova ũthũku, ũla ũtaanaa ũtao mũthũku.'),
('kam', 'NAM', 1, 12, 'Ũũ nĩw’o Yeova ũnũkwasya: O na ethĩwa nĩmausũĩtwe nĩ vinya ki, o na ethĩwa nĩ aingĩ, ĩndĩ makatemangwa mavalũke nthĩ, na akavĩta athi. O na ethĩwa nĩngũthĩnĩtye, ndikakũthĩn’ya ĩngĩ.'),
('kam', 'NAM', 1, 13, 'Na yu ngatũla ĩsoki yake yume kwaku, na ngatilan’ya kĩla kĩkwovete.'),
('kam', 'NAM', 1, 14, 'Na Yeova nũnenganĩte mwĩao ũndũ waku, kana matikavuĩwa ĩngĩ o na ũmwe ala ma syĩtwa yaku: ngaveta mũvw’anano mwasũvye na mũvw’anano wa syĩndũ itwekethetw’e kuma nyũmbanĩ ya ngai syaku; ngenza va ũkũthika; nũndũ wĩ mũvuku.'),
('kam', 'NAM', 1, 15, 'Sisya, iĩmanĩ maũũ ma ũla ũetae ũvoo mũseo, ũla ũnyaĩĩkasya mũuo! Lilikana mboka syaku, we Yuta, ĩanĩsya mawĩvĩto maku; nũndũ ũla mũthũku ndakavĩtĩla kwaku ĩngĩ; nĩ mũvete vyũ.'),
('kam', 'NAM', 2, 1, 'Ũla ũvevenzaa tũlungu nĩwakwambatĩĩa: sũvĩa ngome, syaĩĩsya nzĩa, ĩkia kĩnyunyu kyaku vinya, lũlũmĩlya ũtonyi waku mũno mũnene.'),
('kam', 'NAM', 2, 2, 'Nũndũ Yeova nũnũkũtũnga ũnene wa Yakovo, o ta ũnene wa Isilaeli; nũndũ amini nĩmamaminĩte, na kwananga mbonge syoo sya mĩsavivũ.'),
('kam', 'NAM', 2, 3, 'Ngao ya ngũmbaũ syake nĩ ndunĩvye, andũ me ũkũmbaũ mekĩĩte ngũa ndune mũno: makasya ma kaũ me iaa nĩmatisatisaa mũthenya wa kwĩyũmban’ya kwake, na matumo ma mĩtalakwe nĩmavyũlavyũlaw’a.'),
('kam', 'NAM', 2, 4, 'Makasya ma kaũ nĩmasembaa nzĩanĩ nene ta mekũũũka; nĩmaendaa mĩtũkĩ kũũ na kũũ nzĩanĩ nthanthau: mwonekele wamo ũilyĩ ta mĩmũĩ; nĩmasembaa o ta motisi.'),
('kam', 'NAM', 2, 5, 'Nũlilikanaa anene make me ndaĩa: nĩmalulutĩkaa mĩtambĩlyenĩ yoo; nĩmekalaatĩlaa ũvainĩ wayo, na kĩla kĩsiĩĩaa nĩkyũmbanaw’a.'),
('kam', 'NAM', 2, 6, 'Mbingĩlo sya mbũsĩ nĩ mbingũe, na nyũmba nene mbanakavye nĩ mbanangĩku.'),
('kam', 'NAM', 2, 7, 'Usavu nũvuĩtwe, nũtwaĩtwe kũasa; na athũkũmi make eĩtu nĩmang’ulasya ta wasya wa mavũĩ, makĩkũnanga ithũi syoo.'),
('kam', 'NAM', 2, 8, 'Ĩndĩ Nineva yatwĩe ĩtilyĩ ndia ya kĩw’ũ kuma tene: ĩndĩ nĩmeũkĩa. Mamanĩĩsyaa, Ũngamai, ũngamai; ĩndĩ vati ũsisya na ĩtina.'),
('kam', 'NAM', 2, 9, 'Tavai vetha, tavai thaavu; nũndũ vatĩ mũminũkĩlyo wa syĩndũ mbie, ũtaĩo wa mĩio mĩseo yonthe.'),
('kam', 'NAM', 2, 10, 'Ndĩ na kĩndũ, na nĩ nthei, na mbanange na ngoo nĩnĩũtweka, na mau kũkũnangana, na woo wĩ inyunyunĩ syonthe, na mothyũ moo onthe nĩ maalyũku.'),
('kam', 'NAM', 2, 11, 'Kĩĩva kĩsumo kya mĩnyambũ, na vala ĩĩthĩaw’a mĩnyambũ ya mũika, vala mũnyambũ na mũnyambũ mũka yangangaa, na ĩswii ya mũnyambũ, na vate wa kũmĩtelemya?'),
('kam', 'NAM', 2, 12, 'Mũnyambũ watembũangaa tũlungu twĩanĩu nũndũ wa tũswii twaw’o, na kwita nũndũ wa mĩnyambũ yaw’o mĩka, na kusũsya ngunga syaw’o na sya nzyĩma, na isumo syaw’o na kĩla ũtembũangĩte.'),
('kam', 'NAM', 2, 13, 'Sisya, nĩ ũndũ naku, easya ũu Yeova wa nguthu, na ngavĩvĩsya makasya make ma kaũ nthĩnĩ wa syũki, na ũvyũ ũkamina mĩnyambũ yaku ya mũika; na ngaveta sya nzyĩma syaku syume nthĩ, na wasya wa atũmwa maku ndũkew’ĩka ĩngĩ.'),
('kam', 'NAM', 3, 1, 'Woo nĩ wa ndũa ya nthakame! Nĩyusũĩte movũngũ na ũvutani vyũ; mũtavo ndumaa.'),
('kam', 'NAM', 3, 2, 'Kĩtoleko kya mũsalisa na kĩlonzo kya ndĩa ikĩkayan’ya, na mbalasi itũlĩlangĩte, na makasya ma kaũ kũthakanga,'),
('kam', 'NAM', 3, 3, 'ũla ũtũlaa mbalasi akĩtũla, na ũvyũ ũkĩtisatisa, na ĩtumo yĩkĩtisatisa, na wingĩ wa oawa, na mbumbu nene ya simba, na vati mũminũkĩlyo wa simba; nĩmalulutĩkaa ĩũlũ wa simba syoo; —'),
('kam', 'NAM', 3, 4, 'nũndũ wa wingĩ wa ũmalwaya wa ĩlwaya yanake, ĩnene ya mooi, yĩla yĩthooasya mbaĩ kwondũ wa ũmalwaya wayo, na mĩvĩa kwondũ wa mooi mayo.'),
('kam', 'NAM', 3, 5, 'Sisya, nĩ na ũndũ naku, easya ũu Yeova wa nguthu, na ngakũvua ngũa syaku nĩvikye ũthyũnĩ waku; na ngoon’ya mbaĩ wĩ mũthei, na mosumbĩ nthoni syaku.'),
('kam', 'NAM', 3, 6, 'Na ngakwĩkĩsya ũvuku ũthatasya, na ũkũvukya, na ngakwĩkalya ta wĩ wa kukũnũĩwa metho.'),
('kam', 'NAM', 3, 7, 'Na kũkeethĩwa, atĩ onthe ala meũkũsisya makakĩa kuma vala ũĩ, na kwasya, Nineva nĩyanangĩtwe: nũũ wĩmĩmetea? Nĩkũmanthĩa akiakisya nakũ?'),
('kam', 'NAM', 3, 8, 'We wĩ kavaa kwĩ No‐amoni, ĩla yaĩ katĩ wa mbũsĩ, ĩla yathyũlũlũkĩtwe nĩ manzĩ; ĩla wiio mũlũmu wayo waĩ ũkanga, na ũvaĩ wayo waĩ o ũkanga?'),
('kam', 'NAM', 3, 9, 'Ethiovia na Misili nĩsyo syaĩ vinya wayo, na waĩ ũtathela; Vutu na Luvimu syaĩ atethya maku.'),
('kam', 'NAM', 3, 10, 'Ĩndĩ nĩwatwaiwe, nĩwaendie e mũtave; tũũkenge twake natw’o twang’atanganĩw’a twatilĩkangĩla tũlungu myambĩlĩlyonĩ ya nzĩa nene syonthe; na malimana ũndũ wa andũ make ala me ndaĩa, na andũ make onthe anene moovwa na mĩnyololo.'),
('kam', 'NAM', 3, 11, 'O naku ũkanyw’a ũmilwe; ũkavithwa; o na ĩngĩ ũkamantha ngome yĩ vinya nũndũ wa mũmaitha.'),
('kam', 'NAM', 3, 12, 'Ngome syaku syonthe ikeethĩwa ta mĩkũyũ ĩ na makũyũ mambaa kwĩwa: ethĩwa ĩkathingithw’a, nĩmeũvalũka kanyw’anĩ wa mũyi.'),
('kam', 'NAM', 3, 13, 'Sisya, andũ maku ala me katĩ waku nĩ iveti; mbingĩlo sya nthĩ yaku nĩ mbingũe vyũ kwa amaitha maku: mwaki nũminĩte ivingo syaku.'),
('kam', 'NAM', 3, 14, 'Ĩtavĩe kĩw’ũ kya yĩla wĩtw’ĩkanĩw’a; lũlũmĩlya ngome syaku; enda yũmbanĩ noianga ndaka; lũlũmĩlya kĩvĩvĩsyo kya mavali.'),
('kam', 'NAM', 3, 15, 'Mwaki ũkakũvĩvĩsya vo; ũvyũ ũkakũveta; ũkakũmina o tondũ mbandi iminaa: ĩyingĩvye o ta mbandi; ĩvingĩvye o ta ngie.'),
('kam', 'NAM', 3, 16, 'Nĩwingĩvĩtye athoosya maku kwĩ ndata sya ĩtu: mbandi nikwananga, na ikĩũlũka ikĩthi.'),
('kam', 'NAM', 3, 17, 'Anene maku me mbee ũsumbĩnĩ nĩ ta ngie, na anene maku nĩ ta mĩkũmbĩ ya ngie nene ila ikomaa wiionĩ mũthenya kwĩ mbevo, ĩndĩ syũa yaumĩla ikĩũlũka ikĩthi, na vala iĩ vakĩlea kũmanyĩka.'),
('kam', 'NAM', 3, 18, 'Aĩthi maku nĩmomboetye, we mũsumbĩ wa Asuli; anene maku me ndaĩa nĩmathũmũĩte; andũ maku nĩmanyaĩĩkĩte iĩmanĩ, na vatiĩ o na ũmwe wa kũmomban’ya.'),
('kam', 'NAM', 3, 19, 'Ĩkũnwa yaku yĩtivoeka; wũkite waku wĩ woo: onthe ala mew’aa ũvoo waku nĩmaũkũnangĩaa mbĩ; nũndũ nũũ ũthũku waku ũtavĩtĩlaa ĩũlũ wake ĩndĩ yonthe?'),
('kam', 'HAB', 1, 1, 'Ndeto ngito ĩla mwathani Avakuki wonie.'),
('kam', 'HAB', 1, 2, 'Ame Yeova, ngaĩa ĩvinda yĩana ata, naku ndũkwenda kwĩw’a? Nĩngũkwĩkaĩla ũndũ wa ũng’endu wĩ kw’o, na ndũkwenda kũtangĩĩa.'),
('kam', 'HAB', 1, 3, 'Nĩkĩ naku ũmbonasya ũthũku, na kũtuma nĩsiasya maũndũ ma ngũlũ? Nũndũ wanangĩko na ũng’endu me mbee wakwa; na ve ĩteta, na ngananĩo nikũkĩla.'),
('kam', 'HAB', 1, 4, 'Kwondũ wa ũu mĩao ndĩ na vinya, na sila wa katĩ ndumĩlaa nongi; nũndũ ala thũku nĩmathyũlũlũkĩte ala alũngalu; kwondũ wa ũu sila wa katĩ nĩwelelũkaw’a.'),
('kam', 'HAB', 1, 5, 'Sisyai, inyw’ĩ i mbaĩnĩ, na mũiketeea, na kũseng’a mũseng’eee; nũndũ nĩtethya wĩa mĩthenya yenyu, ũla mũtaketĩkĩla o na mwatavw’a.'),
('kam', 'HAB', 1, 6, 'Nũndũ, sisyai, nĩngũkĩlya Akalitei, mbaĩ yĩ wai na nthangaau, ala maendaa ũthanthaunĩ wa nthĩ, kwĩyosea motũo ala mate moo.'),
('kam', 'HAB', 1, 7, 'Nĩ ma kũtĩsya na kũtw’a nda; ũsilĩli woo na ũnene woo wumaa kwoo ene.'),
('kam', 'HAB', 1, 8, 'O na mbalasi syoo syĩ maũũ kwĩ ngo, na nĩ mbai kwĩ nzũi wĩoo; na atũli ma mbalasi moo maendaa na ngathĩĩo: ĩĩ, atũli ma mbalasi moo mokaa kuma kũasa; maũlũkaa ta ndiũ yĩkalaatĩle kũya.'),
('kam', 'HAB', 1, 9, 'Mokaa onthe kwondũ wa ũng’endu; mothyũ moo malũlũmĩle kwelekela mbee; na mombanasya atavwa o ta kĩthangathĩ.'),
('kam', 'HAB', 1, 10, 'Ĩĩ, nũvũthĩĩasya asumbĩ, na kũmathekeea anene me mbee ũsumbĩnĩ; nũthekeeaa kĩla ngome yĩ vinya; nũndũ nũmyũmbĩaa mũthanga, na akĩmyosa.'),
('kam', 'HAB', 1, 11, 'Nĩvo ĩndĩ wĩvĩta o ta kĩseve, na akĩvĩtũka, na akĩthĩwa mũvĩtan’ya, we ũla ũtonyi wake nĩ ngai yake.'),
('kam', 'HAB', 1, 12, 'We ndwĩ wa tene na tene, ame Yeova Ngai wakwa, Mũtheu wakwa? Tũikakw’a. Ame Yeova, we nĩwamwiie nũndũ wa ũsilĩlo; naku, ame Ĩvia, nĩwamũũngamisye nũndũ wa ũkan’yo wa mavĩtyo.'),
('kam', 'HAB', 1, 13, 'We ũla wĩ na metho matheu ũtasiasya ũthũku, na ũla ũtatonya kũsisya ngũlũ, nĩ ũndũ wa kĩ ũsiasya ala mekaa ũseleke, na ũyĩkilĩlya yĩla mũthũku ũnũkũmelya mũndũ ũla wĩ na ũlũngalu kũmũvĩtũka;'),
('kam', 'HAB', 1, 14, 'na aitw’ĩkĩthya andũ ta makũyũ ma ũkanganĩ, na ta tũsamũ tũla tũtambũkaa, tũte mũnene watw’o?'),
('kam', 'HAB', 1, 15, 'Nũmakwatasya onthe na ngolya, nũmakwatasya na kĩtei kyake, na aimomban’ya ĩkengenĩ yake: kwondũ wa ũu nũtanaa na kwĩw’a mũyo.'),
('kam', 'HAB', 1, 16, 'Kwondũ wa ũu nũthembeaa kĩtei kyake, na kũtoeesya ĩkenge yake ũvani; nũndũ kwondũ wasyo kĩanda kyake nĩ kĩnou, na lĩu wake nĩ mwingĩ.'),
('kam', 'HAB', 1, 17, 'Kwondũ wa ũu nũkaumya onthe ala me kĩteinĩ kyake, na aieka kũsyũaa mbaĩ ĩvinda yonthe?'),
('kam', 'HAB', 2, 1, 'Ngaũngama ũsyaĩĩsyonĩ wakwa, na kwĩũngamya ĩũlũ wa mwako mũtũlu wa mũnyoolo, na ngasisya none ũndũ wĩneena nakwa, na ũndũ nĩsũngĩa ũndũ wa kũnyungunyĩsya kwakwa.'),
('kam', 'HAB', 2, 2, 'Na Yeova anzũngĩa, na ambĩa, Andĩka woni masengeanĩ, wumĩlye nesa, nĩ kana ũla ũsomaa atonye kũsemba.'),
('kam', 'HAB', 2, 3, 'Nũndũ woni no wa ĩvinda yĩla yatwiwe, na wĩkalaatĩle kwelekela mũminũkĩlyo, na ndwĩĩthĩwa ũvũngũ: o na wekala, wĩweteela; nĩkwĩthĩwa ndũtĩa kũka, ndũkekala.'),
('kam', 'HAB', 2, 4, 'Sisya, ngoo yake nĩĩyimbĩtye, ti ndũngalu nthĩnĩ wake; ĩndĩ ũla mũlũngalu akekala thayũ kwondũ wa mũĩkĩĩo wake.'),
('kam', 'HAB', 2, 5, 'Ĩĩ, o na mbee wa ũu, mbinyu nĩ ngengani, nĩyo mũndũ wĩ mĩtũlyo, ũla ũtekalaa kwake; ũla ũnenevasya kwenda kwake ta Seoli, nake nĩ ta kĩkw’ũ, na ndatonya kũvũnĩthw’a, ĩndĩ eyũmbanĩasya mbaĩ syonthe, na kwĩyũmbanĩsya ngo syonthe sya andũ.'),
('kam', 'HAB', 2, 6, 'Asu onthe matikamũtila ngelekan’yo, na kũmũkũlũla nthimo, makyasya, Woo nĩ wa ũla wongeleelaa kĩla kĩte kyake! Nĩ kũvika ĩndĩĩ? Na wa ũla wĩkuĩthasya mũio wa ngwatĩlĩlyo!'),
('kam', 'HAB', 2, 7, 'Maikokĩla na kĩthũlũmũko ala makakũũma, na kũamũka ala makakũthĩn’ya, naku ndũkethĩwa mũtavo kwoo?'),
('kam', 'HAB', 2, 8, 'Nĩkwĩthĩwa nũtavĩte mbaĩ mbingĩ, ũtialo w’onthe wa ngo sya andũ ũkakũtava, kwondũ wa nthakame ya andũ, na kwondũ wa ũng’endu ũla wĩkĩtwe nthĩ ĩsu, ndũa ĩsu na onthe ala matwie nthĩnĩ wayo.'),
('kam', 'HAB', 2, 9, 'Woo nĩ wa ũla ũtandĩthĩasya nyũmba yake ũtandĩthyo mũthũku, nĩ kana atũlye ndala yake ĩũlũ, kana atangĩĩwe kuma kw’okonĩ kwa ũthũku!'),
('kam', 'HAB', 2, 10, 'We nũmanthĩe nyũmba yaku nthoni, nũndũ wa kũveta ngo mbingĩ sya andũ, na nĩwĩyĩkĩte naĩ.'),
('kam', 'HAB', 2, 11, 'Nũndũ ĩvia yĩkalonzanĩlya wakonĩ, na mũamba wĩ mĩtĩnĩ ya mwako ũkayĩsũngĩa.'),
('kam', 'HAB', 2, 12, 'Woo nĩ wa ũla wakaa katũla na nthakame, na kũlũlũmĩlya ndũa na ũthũku!'),
('kam', 'HAB', 2, 13, 'Sisya, ti ũndũ wa Yeova wa nguthu ngo sya andũ syĩthĩnĩa wĩa ũvĩvw’e nĩ mwaki, na mbaĩ ikĩnosya mana?'),
('kam', 'HAB', 2, 14, 'Nũndũ nthĩ ĩkausũwa nĩ kũmanya ũnene wa Yeova, o tondũ manzĩ makunĩkĩlye ũkanga.'),
('kam', 'HAB', 2, 15, 'Woo nĩ wa ũla ũnengae mũtũi wake kya ũnyw’a, kwaku we, ũla wongelanasya kya ũmũtoon’ya kyaku, na ĩngĩ ũituma amilwa, nĩ kana ũtonye kũmasisya me athei!'),
('kam', 'HAB', 2, 16, 'Wusũĩtwe nĩ nthoni, na ti ndaĩa: nyw’a o naku, na ĩthĩwa o ta ũmwe ũte mwaĩke; kĩkombe kĩ kw’okonĩ kwa aũme kwa Yeova kĩkakũsyokea, na nthoni nthũku ikavw’ĩka ndaĩa yaku.'),
('kam', 'HAB', 2, 17, 'Nũndũ ũng’endu ũla weekiwe Levanoni, na wanango wa nyamũ, ũla watumie makĩa, ũkakũvw’ĩka; nũndũ wa nthakame sya andũ, na nũndũ wa ũng’endu ũla weekiwe nthĩ ĩsu, ndũa ĩsu na onthe ala matwĩe nthĩnĩ wayo.'),
('kam', 'HAB', 2, 18, 'Mũvw’anano mwasũvye ũunaa na kyaũ, kĩtuma mwaseũvya waw’o awasũvya; mũvw’anano mũseũvye wa syĩndũ itwekethetw’e, nĩw’o mũmanyĩsya wa movũngũ, ũunaa na kyaũ, kĩtuma ũla ũseũvasya mũmbĩle waw’o oĩkĩĩa, nĩ kana aseũvye mĩvw’anano ĩtaneenaa?'),
('kam', 'HAB', 2, 19, 'Woo nĩ wa ũla wĩaa mũtĩ, Amũka; na ĩvia yĩtaneenaa, Ũkĩla! Syĩndũ ii ikamanyĩsya? Sisya, nivw’ĩkĩtwe na thaavu na vetha, o na vai mĩvevo nongi nthĩnĩ wasyo.'),
('kam', 'HAB', 2, 20, 'Ĩndĩ Yeova e ĩkalũnĩ yake ĩtheu: nthĩ yonthe nĩvindye mbee wake.'),
('kam', 'HAB', 3, 1, 'Mboya ya mwathani Avakuki, ya mwinĩle wa kũkaya.'),
('kam', 'HAB', 3, 2, 'Ame Yeova, nĩnĩw’ĩte ũvoo waku, na nĩngũkĩa; Ame Yeova, vuũkya wĩa waku katĩ wa myaka; Katĩ wa myaka tuma ũmanyĩka; Wathilĩka, lilikana tei.'),
('kam', 'HAB', 3, 3, 'Ngai nĩwokie kuma Temani, Na Ũla Mũtheu kuma kĩĩmanĩ kya Valani. Ũtheu mũtisu wake wavw’ĩka matu, Na nthĩ yausũwa nĩ ndaĩa yake.'),
('kam', 'HAB', 3, 4, 'Na ũtisu wake wailyĩ kyeni; Aĩ na syeni syumĩte kw’okonĩ kwake; Na vo vaĩ kĩmbithĩ kya ũtonyi wake.'),
('kam', 'HAB', 3, 5, 'Mbee wake kwatongosya mũimũ, Na makaa makanu maendela maũũnĩ make.'),
('kam', 'HAB', 3, 6, 'Aũngama, na athima nthĩ; Asisya, na alũngĩlĩĩlya i mbaĩ kũũ na kũũ; Na iĩma sya tene na tene syanyaĩĩkw’a; Mĩendele yake yailyĩ o ta ĩla ya tene.'),
('kam', 'HAB', 3, 7, 'Nonie maeema ma Kusani me thĩnanĩ; Motũtũ ma ngũa ma nthĩ ya Mitiani mathingitha.'),
('kam', 'HAB', 3, 8, 'Atĩ Yeova nĩwew’ĩthiwe’ woo nĩ mbũsĩ? Ũthatu waku waĩ ĩũlũ wa mbũsĩ, Kana ũthilĩku waku ĩũlũ wa ũkanga, Ũndũ waendete ũtũlĩte mbalasi syaku, Makasyanĩ maku ma ũtangĩĩo?'),
('kam', 'HAB', 3, 9, 'Ũta waku waĩ mumĩlye vyũ; Iavo i syeavĩwe mbaĩ syaĩ ndeto ya w’o. We nĩwaatũangie nthĩ na mbũsĩ.'),
('kam', 'HAB', 3, 10, 'Iĩma syakwona, na syeew’a w’ĩa; Kyũkĩlan’yo kya manzĩ maingĩ kyavĩta kyathi; Manzĩ ma syũngũ nene maumya wasya wamo, Na mookĩlya moko mamo ĩũlũ.'),
('kam', 'HAB', 3, 11, 'Syũa na mwei syaũngama ki ũtũonĩ wasyo, Kwondũ wa kyeni kya mĩsyĩ yaku ĩvĩtĩte, Kwondũ wa ũtisu wa ĩtumo yaku yĩkĩtisatisa.'),
('kam', 'HAB', 3, 12, 'Wavĩtĩle nthĩ wĩ mũthilĩku; We nĩwavũie i mbaĩ wĩ mũthatu.'),
('kam', 'HAB', 3, 13, 'We nĩwaumaalile ũndũ wa kũtangĩĩa andũ maku, Nũndũ wa ũtangĩĩo wa mwĩtĩkĩw’a mauta waku; We nĩwokitie mũtongoi wa nyũmba ya ũla mũndũ mwathe, Ũkĩvukũa mwambĩlĩlyo o na kũvika ngingonĩ.'),
('kam', 'HAB', 3, 14, 'Naku nĩwatonyie mũtongoi wa andũ make ma kaũ na mĩsenge yake mwene: Nĩmookie o ta kĩlingi manyaĩĩkye nyie; Kũtana kwoo kwaĩ ta kũya ngya kĩmbithĩ.'),
('kam', 'HAB', 3, 15, 'We nĩwakinyangie ũkanga na mbalasi syaku, Kĩvumbu kya manzĩ maingĩ.'),
('kam', 'HAB', 3, 16, 'Neew’a, na mwĩĩ wakwa watetema, Ilomo syakwa syathĩĩlĩa nũndũ wa ũla wasya; Wou nũkũlika mavĩndĩnĩ makwa, na nĩngũtetemea va nĩĩ; Nĩkwĩthĩwa no mũvaka meteele mũthenya wa ũnyamao nĩuĩtye, Kwambata kwa andũ ala metũvithũkĩa.'),
('kam', 'HAB', 3, 17, 'Nũndũ o na ethĩwa mũkũyũ ndũkalaũka, O na mĩsavivũ ndĩkasyaa; Wĩa wa mũthata ũkethĩwa wa mana; Na mĩũnda ndĩkasyaa lĩu; Ndĩthya sya mbũi na malondu ikavetwa kyengonĩ, Na vaikethĩwa ndĩthya sya ng’ombe itũũnĩ:'),
('kam', 'HAB', 3, 18, 'Ĩndĩ nyie ngatana nthĩnĩ wa Yeova, Ngatanĩa Ngai wa ũtangĩĩo wakwa.'),
('kam', 'HAB', 3, 19, 'Yeova, Mwĩaĩi, nĩ vinya wakwa; Na etw’a maũũ makwa ta maũũ ma ndaatai, Na akatuma nĩendela kũndũ kwakwa kũtũlu. Kwondũ wa Mũingi Ũla Mũnene, syĩndũnĩ syakwa sya kũinga syĩ mĩkunzu.'),
('kam', 'ZEP', 1, 1, 'Ndeto ya Yeova ĩla yamũkĩe Nzevania mwana wa Kusi, mwana wa Ngetalia, mwana wa Amalia, mwana wa Esekia, mĩthenya ya Yosia mwana wa Amoni, mũsumbĩ wa Yuta.'),
('kam', 'ZEP', 1, 2, 'Ngamina syĩndũ syonthe vyũ syume ĩũlũ wa nthĩ, easya ũu Yeova.'),
('kam', 'ZEP', 1, 3, 'Ngamina mũndũ o na nyamũ; ngamina nyũnyi sya yayayanĩ, na makũyũ ma ũkanganĩ, na molulutĩkyo vamwe na ala athũku; na ngaveta mũndũ aume ĩũlũ wa nthĩ, easya ũu Yeova.'),
('kam', 'ZEP', 1, 4, 'Na ngatambũũkya kw’oko kwakwa ĩũlũ wa Yuta, na ĩũlũ wa onthe ala matwĩe Yelusaleme; na ngaveta ũtialo wa Mbaali wume vandũ vaa, o na syĩtwa ya Kemalimu vamwe na athembi;'),
('kam', 'ZEP', 1, 5, 'o na ala mathaithaa nguthu ya ĩtunĩ me nyũmbanĩ ĩũlũ; o na ala mathaithaa, ala mamwĩavĩaa Yeova na kwĩava na Malikamu;'),
('kam', 'ZEP', 1, 6, 'o na ala methyũũĩte na ĩtina maeke kũmũvikĩla Yeova; na ala matamũmanthĩte Yeova, o na kũmũkũlya.'),
('kam', 'ZEP', 1, 7, 'Ĩkilĩlye, Mwĩaĩi Yeova e vo; nũndũ mũthenya wa Yeova nũthengeee: nũndũ Yeova nũseũvĩtye nthembo, nũvathĩte aeni make.'),
('kam', 'ZEP', 1, 8, 'Na kũkeethĩwa mũthenya wa nthembo ya Yeova, ngasilĩla anene me mbee ũsumbĩnĩ, na ana ma mũsumbĩ, na onthe ala mevw’ĩkaa ngũa ngeni.'),
('kam', 'ZEP', 1, 9, 'Na mũthenya ũsu ngasilĩla onthe ala makĩlĩlaa mwalyonĩ wa mũomo, ala mausũasya nyũmba ya vwana woo ũng’endu na ũkengani.'),
('kam', 'ZEP', 1, 10, 'Na mũthenya ũsu, easya ũu Yeova, kũkeethĩwa kĩlonzo kya kũkaya mbingĩlonĩ ya makũyũ, na kĩĩo kuma ũtũinĩ wa kelĩ, na kĩtuu kĩnene kuma iĩmanĩ.'),
('kam', 'ZEP', 1, 11, 'Ĩai, inyw’ĩ mũtwĩe Maketesi; nũndũ andũ onthe ma Kanaani nĩ au vinya; onthe ala makuĩte mĩio ya vetha nĩmavetwa.'),
('kam', 'ZEP', 1, 12, 'Na kũkeethĩwa ĩvinda yĩu, ngamantha nthĩnĩ wa Yelusaleme na mataa; na ngasilĩla andũ ala mekalĩte kĩmongoyonĩ kyoo, ala maasya ngoonĩ syoo, Yeova ndeĩka ũseo, o na ndeĩka ũthũku.'),
('kam', 'ZEP', 1, 13, 'Na ũthwii woo ũkatavwa, na nyũmba syoo ikatiwa syĩ nthei: ĩĩ, makaaka nyũmba, ĩndĩ matikaitũa; na makavanda mĩũnda mĩsavivũ, ĩndĩ matikanyw’a mbinyu yayo.'),
('kam', 'ZEP', 1, 14, 'Mũthenya mũnene wa Yeova wĩ vakuvĩ, wĩ vakuvĩ na nĩwĩkalaatĩte mũno, o wasya wa mũthenya wa Yeova; ngũmbaũ ĩĩĩaa vo kĩĩo kĩ woo.'),
('kam', 'ZEP', 1, 15, 'Mũthenya ũsu nĩ mũthenya wa ũthilĩku, mũthenya wa ũnyamao na thĩna, mũthenya wa wanangĩko na ĩvou, mũthenya wa kĩvindu na mũki mũnene, mũthenya wa matu na kĩvindu kya ngokomi,'),
('kam', 'ZEP', 1, 16, 'mũthenya wa soo na wa wasya wa kũtĩsya, ĩũlũ wa ila ndũa mbiie, na ĩũlũ wa ala maũvai matũlu mũno.'),
('kam', 'ZEP', 1, 17, 'Na ngaete thĩna ĩũlũ wa andũ, nĩ kana maendae ta ililinda, nĩkwĩthĩwa nĩmamũvĩtanĩsye Yeova; na nthakame yoo ĩketwa nthĩ ta kĩtoo, na mĩĩ yoo ta kyaa.'),
('kam', 'ZEP', 1, 18, 'O na vetha woo kana thaavu woo ndũkethĩwa ũtonya kũmavonokya mũthenya wa kũthilĩka kwa Yeova; ĩndĩ nthĩ yonthe ĩkaminwa nĩ mwaki wa kĩwĩu kyake: nũndũ akaminũkĩlya, ĩĩ, mũminũkĩlyo mwai, wa onthe ala matwĩe ĩ nthĩ.'),
('kam', 'ZEP', 2, 1, 'Ĩtũngĩanĩei vamwe, ĩĩ, ĩtũngĩanĩe, we mbaĩ ĩla ĩte na nthoni;'),
('kam', 'ZEP', 2, 2, 'mbee wa ũtw’ĩo ũtanaumĩlya ũsyao, mbee wa mũthenya ũtanavĩta ta wewa, mbee wa ũthatu mwai wa Yeova ũtanoka ĩũlũ wenyu, mbee wa mũthenya wa ũthatu wa Yeova ũtanoka ĩũlũ wenyu.'),
('kam', 'ZEP', 2, 3, 'Mũmanthei Yeova, inyw’onthe ala auu ma nthĩ, ala mũkwatĩte motw’ĩo make; manthai ũlũngalu, manthai ũuu: nokwĩthĩwa mũvithwa mũthenya wa ũthatu wa Yeova.'),
('kam', 'ZEP', 2, 4, 'Nũndũ Ngasa ĩkatiwa, na Asikeloni ĩkeethĩwa ĩanzo; makalũngya Asitoti kwĩ mũthenya katĩ, na Ekiloni ĩkakũanĩw’a na mĩi.'),
('kam', 'ZEP', 2, 5, 'Woo nĩ wa ala matwĩe ũtee wa ũkanga, mbaĩ ya Akelethi! Ndeto ya Yeova yĩ ĩũlũ waku, we Kanaani, nthĩ ya Avilisiti; ngakwananga nĩ kana vatikaaĩthĩwe wa ũtũa kwaku.'),
('kam', 'ZEP', 2, 6, 'Na ũtee wa ũkanga kũkeethĩwa isesi, syĩ na tũsũmba twa aĩthi na syengo sya ndĩthya sya mbũi na malondu.'),
('kam', 'ZEP', 2, 7, 'Na ũtee wa ũkanga ũkatw’ĩka wa ũtialo wa nyũmba ya Yuta; makaĩthasya ndĩthya syoo sya mbũi na malondu kũu; nyũmbanĩ sya Asikeloni nĩkw’o mekomaa wĩoo; nũndũ Yeova Ngaĩ woo akamokĩa, na akamatũnga kuma kũtavwanĩ.'),
('kam', 'ZEP', 2, 8, 'Nĩnĩw’ĩte mbũthĩĩsya ya Moavi, na kũumana kwa ana ma Amimoni, kũla mavũthĩtye andũ makwa, na kwĩnenevya ene ĩũlũ wa mũvaka woo.'),
('kam', 'ZEP', 2, 9, 'Kwondũ wa ũu o tondũ nyie nĩ thayũ, easya ũu Yeova wa nguthu, Ngai wa Isilaeli, Vate ndĩi Moavi ĩkeethĩwa ta Sotomo, na ana ma Amimoni ta Ngomola, wĩkalo wa syĩnyeelya, na maima ma mũnyũ, na ĩanzo tene na tene: na ũtialo wa andũ makwa ũkamatava mũtavo, na ũtialo wa mbaĩ yakwa ũkamatiĩwa.'),
('kam', 'ZEP', 2, 10, 'Ũũ nĩw’o meĩthĩwa nũndũ wa ngathĩĩo syoo, nĩkwĩthĩwa nĩmavũthĩtye na kwĩtũlya ene ĩũlũ wa andũ ma Yeova wa nguthu.'),
('kam', 'ZEP', 2, 11, 'Yeova akeethĩwa ũtĩsyo kwamo; nũndũ akaimosethya ngai syonthe sya nthĩ; na andũ makamũthaitha, kĩla mũndũ vala ũĩ, o ithama syonthe sya i mbaĩ.'),
('kam', 'ZEP', 2, 12, 'O nenyu Aethiovia, mũkooawa na ũvyũ wakwa.'),
('kam', 'ZEP', 2, 13, 'Na akatambũũkĩa ngalĩ ya ĩũlũ na kw’oko kwake, na akyananga Asuli, na akatw’ĩkĩthya Nineva ĩanzo, na nyũmũ ta weũ.'),
('kam', 'ZEP', 2, 14, 'Na ndĩthya ikatindia katĩ wayo, nyamũ syonthe ila syĩ kwa i mbaĩ: ngunĩ na nzee ikekala mĩthyanĩ ya ituĩ syayo; wasya wasyo ũkeew’ĩkĩla mbũthinĩ; wanangĩko ũkeethĩwa myalyonĩ ya mĩomo: nũndũ nũvuĩte mbwaũ sya mĩtĩ ya mĩkũũ.'),
('kam', 'ZEP', 2, 15, 'Ĩno nĩ ndũa ya ũtanu ĩla ĩtwĩe ĩte kĩio, ĩla yaisye ngoonĩ yayo, Ninyie, na vati ũngĩ ate o nyie: A! Ũndũ ĩtw’ĩkĩte ĩanzo, vandũ va kũtindia nyamũ! Kĩla ũmwe ũla ũmĩvĩtĩlaa akamĩtimba, na kwĩkangya kw’oko kwake.'),
('kam', 'ZEP', 3, 1, 'Woo nĩ wayo ng’endi na mbuku! Ndũa nthĩn’ya!'),
('kam', 'ZEP', 3, 2, 'Ndĩaaĩthukĩĩsya ũla wasya; ndĩaakwata ũmanyĩsyo; ndĩaamũĩkĩĩa Yeova; ndĩaathengeea vakuvĩ na Ngai wayo.'),
('kam', 'ZEP', 3, 3, 'Anene mayo me mbee ũsumbĩnĩ ala me nthĩnĩ wayo nĩ mĩnyambũ ĩnĩkũluma; asili mayo nĩ nzũi wĩoo; ititialasya kĩndũ kĩvike ũnĩ.'),
('kam', 'ZEP', 3, 4, 'Athani mayo nĩ andũ mate vata na nĩ nzeleke; athembi mayo nĩmavukĩtye vala vandũ vatheu, nĩmang’endee ĩla mĩao.'),
('kam', 'ZEP', 3, 5, 'Yeova ũla wĩ katĩ wayo nĩ mũlũngalu; ndakeka ũthũku; kĩla kĩoko aetae ũsili wake wa katĩ kyeninĩ, we ndatĩaa kwĩanĩsya; ĩndĩ ũla ũte mũlũngalu ndesĩ nthoni.'),
('kam', 'ZEP', 3, 6, 'Nĩnĩvetete mbaĩ; maũvai moo matũlu nĩ mathei; nĩnĩtw’ĩkĩthĩtye nzĩa syoo nene mbanangĩku, ũndũ itavĩtĩlwa nĩ mũndũ; ndũa syoo nĩ mbanange, ũndũ itethĩwa mũndũ, ũndũ itatũwa.'),
('kam', 'ZEP', 3, 7, 'Naasya, Ndũtĩa ũngĩa; ũketĩkĩla ũmanyĩsyo; kwondũ wa ũu ũtũo wake ndũkavetwa, o kwĩanana na w’onthe ũla natwie ũndũ wake: ĩndĩ mookĩla tene na mathũkya meko moo onthe.'),
('kam', 'ZEP', 3, 8, 'Kwondũ wa ũu mbeteelai kũvika mũthenya ũla nĩũkĩla kũtava, easya ũu Yeova; nũndũ kũtw’a kwakwa nĩ kũmban’ya i mbaĩ, nĩ kana nĩkoman’ye mosumbĩ, nĩmonosye ũthilĩku wakwa, o ũthatu wakwa w’onthe mwai; nũndũ nthĩ yonthe ĩkaminwa nĩ mwaki wa kĩwĩu kyakwa.'),
('kam', 'ZEP', 3, 9, 'Na ĩndĩ nĩvo nĩtũngĩa i ngo sya andũ kĩthyomo kĩtheu, nĩ kana onthe mekaĩle syĩtwa ya Yeova, mamũthũkũmae na ngoo ĩmwe.'),
('kam', 'ZEP', 3, 10, 'Kuma mũingo ũya wa mbũsĩ sya Ethiovia avoyi makwa, o mwĩĩtu wa mũnyaĩĩkw’a wakwa, makandetee nthembo yakwa.'),
('kam', 'ZEP', 3, 11, 'Mũthenya ũsu ndũkasonokw’a nũndũ wa meko maku onthe, ala wambĩtanĩsye; nũndũ nĩvo nĩumya kwaku ala maku metanĩthasya na ngathĩĩo, naku ndũkethĩwa na wĩng’athĩlĩlyo ĩngĩ kĩĩmanĩ kyakwa kĩtheu.'),
('kam', 'ZEP', 3, 12, 'Ĩndĩ ngaeka kwaku ũko wa andũ ũla ũnyamaaw’a o na ngya, na makeevitha syĩtwanĩ ya Yeova.'),
('kam', 'ZEP', 3, 13, 'Ũtialo wa Isilaeli ndũkeka ũthũku, kana kũneena movũngũ; o na ũĩmĩ ũkenganaa ndũkoneka kanyw’anĩ woo; nũndũ makaya na kũkoma nthĩ, na kũtikethĩwa ũkatuma makĩa.'),
('kam', 'ZEP', 3, 14, 'Ina, we mwĩĩtu wa Saioni; ũkĩlya wasya, we Isilaeli; tana na kwĩw’a mũyo na ngoo yonthe, we mwĩĩtu wa Yelusaleme.'),
('kam', 'ZEP', 3, 15, 'Yeova nũvetete mosilĩlo maku, nĩwĩkĩtye mũmaitha waku ũtee: Mũsumbĩ wa Isilaeli, o Yeova, e katĩ waku; ndũkakĩa ũthũku o na ĩndĩĩ.'),
('kam', 'ZEP', 3, 16, 'Mũthenya ũsu Yelũsaleme ĩkatavw’a, Ndũkakĩe we; we Saioni, moko maku matikaleele.'),
('kam', 'ZEP', 3, 17, 'Yeova Ngai waku e katĩ waku, mwene ũtonyi ũla wĩtangĩĩa; akakũtanĩa na mũyo; akathũmũa wendonĩ wake; akakũtanĩa akina.'),
('kam', 'ZEP', 3, 18, 'Ngamomban’ya ala mew’aa woo nũndũ wa ũmbano ũtw’ĩtwe kwaa, ala maĩ maku; ala kũvũthw’a kwayo kwatw’ĩkie mũio kwoo.'),
('kam', 'ZEP', 3, 19, 'Sisya, ĩvinda yĩu ngatwaatwaana na onthe ala makũthĩnasya; na ngatangĩĩa ũla ũthuaa, na ngĩtũnga ũla walũngĩtw’e; na ngamatw’a ngatho na syĩtwa, ala mekalĩte me na nthoni nthĩ yonthe.'),
('kam', 'ZEP', 3, 20, 'Ĩvinda yĩu ngamũete nthĩnĩ, na ĩvinda yĩu ngamũmban’ya; nũndũ ngamũtw’a syĩtwa na ngatho katĩ wa ngo syonthe sya andũ sya nthĩ, yĩla nĩmũtũnga mume kũtavwanĩ kwenyu mũsyaĩtye, easya ũu Yeova.'),
('kam', 'HAG', 1, 1, 'Mwaka wa kelĩ wa kũsumbĩka kwa mũsumbĩ Ndalio, mwei wa thanthatũ, mũthenya wa mbee wa mwei, ndeto ya Yeova yamũkĩa Nzeluvaveli mwana wa Sealitieli, ngavana wa Yuta, na Yosua mwana wa Yeosataki, mũthembi mũnene, na kanyw’a mwathani Akai, ĩkĩmea,'),
('kam', 'HAG', 1, 2, 'Yeova wa nguthu eneena ũũ, akyasya, Andũ aa measya, Ĩvinda yĩtinamba kũvika, ĩvinda ya kwaka nyũmba ya Yeova.'),
('kam', 'HAG', 1, 3, 'Nĩvo ĩndĩ ndeto ya Yeova yookie na kanyw’a wa mwathani Akai, ĩkĩkũlya,'),
('kam', 'HAG', 1, 4, 'Nĩ ĩvinda yenyu ene kwĩkalaa nyũmbanĩ syenyu nzeũvye na mbwaũ nthĩnĩ, yĩla nyũmba ĩno ĩeketwe ĩ mbanangĩku?'),
('kam', 'HAG', 1, 5, 'Na yu kwondũ wa ũu Yeova wa nguthu easya atĩĩ: Sũanĩai mĩendele yenyu.'),
('kam', 'HAG', 1, 6, 'Inyw’ĩ mũvandĩte mbingĩ, na mũkĩketha nini; nĩmũĩsaa, ĩndĩ mũtivũnaa; nĩmũnyusaa, ĩndĩ mũtilaũkaa; nĩmwĩvw’ĩkaa, ĩndĩ vati wĩw’aa muutĩa, na ũla ũthũkũmaa atuvwe, athũkũmaa ĩtuvi na akĩkĩa ngusunĩ mbũthũkangu.'),
('kam', 'HAG', 1, 7, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Sũanĩai mĩendele yenyu.'),
('kam', 'HAG', 1, 8, 'Ambatai kĩĩmanĩ, mũete mĩtĩ, na mũkyaka ĩla nyũmba; na ngendeew’a nĩyo, na ngataĩwa, easya ũu Yeova.'),
('kam', 'HAG', 1, 9, 'Mwaasya mũkoona nyingĩ, na, sisya, ikyoneka nini; na mwaiete mũsyĩ, ngivutũkya. Nĩkĩ? Ekũlya ũu Yeova wa nguthu. Nũndũ wa nyũmba yakwa kũekwa ĩ mbanangĩku, yĩla mũũsemba kĩla mũndũ nyũmbanĩ yake mwene.'),
('kam', 'HAG', 1, 10, 'Kwondũ wa ũu nũndũ wenyu matu nĩmaleaa kũete ĩmwe, na nthĩ nĩleaa kũete ũsyao wayo.'),
('kam', 'HAG', 1, 11, 'Na neeta mũnyao wũke ĩũlũ wa nthĩ, na ĩũlũ wa ĩĩma, na ĩũlũ wa lĩu wa mbaa ngetha, na ĩũlũ wa mbinyu nbĩthĩ, na ĩũlũ wa mauta, na ĩũlũ wa kĩla nthĩ ĩmeasya, na ĩũlũ wa andũ, na ĩũlũ wa indo, na ĩũlũ wa wĩa w’onthe wa moko.'),
('kam', 'HAG', 1, 12, 'Nĩvo ĩndĩ Nzeluvaveli mwana wa Sealitieli, na Yosua mwana wa Yeosataki, mũthembi mũnene, vamwe na ũtialo w’onthe wa andũ, meewie wasya wa Yeova Ngai woo, na ndeto sya mwathani Akai, o tondũ Yeova Ngai woo wamũtũmĩte; na andũ meew’a w’ĩa vala ve Yeova.'),
('kam', 'HAG', 1, 13, 'Nĩvo ĩndĩ Akai, mũtũmwa wa Yeova, waneenie ũtũme wa Yeova kwa andũ, akĩmea, Nĩ vamwe nenyu, easya ũu Yeova.'),
('kam', 'HAG', 1, 14, 'Na Yeova aamũkya veva wa Nzeluvaveli mwana wa Sealitieli, ngavana wa Yuta, na veva wa Yosua mwana wa Yeosataki, mũthembi mũnene, na veva wa ũtialo w’onthe wa andũ; na mooka na matethya wĩa nyũmbanĩ ya Yeova wa nguthu, Ngai woo,'),
('kam', 'HAG', 1, 15, 'mũthenya wa mĩongo ĩlĩ na ĩna, mwei wa thanthatũ, mwaka wa kelĩ wa kũsumbĩka kwa mũsumbĩ Ndalio.'),
('kam', 'HAG', 2, 1, 'Mwei wa mũonza, mũthenya wa mĩongo ĩlĩ na ũmwe wa mwei, ndeto ya Yeova yooka na kanyw’a wa mwathani Akai, ĩkyasya,'),
('kam', 'HAG', 2, 2, 'Neena yu na Nzeluvaveli mwana wa Sealitieli ngavana wa Yuta, na Yosua mwana wa Yeosataki, mũthembi mũnene, na ũtialo wa andũ, ũmakũlye,'),
('kam', 'HAG', 2, 3, 'Nũũ ũtiele katĩ wenyu ũla wonie nyũmba ĩno yĩ na ũtheu wayo wa mbee? Na mwĩmyona ata yu? Ti ta mana methonĩ menyu?'),
('kam', 'HAG', 2, 4, 'Ĩndĩ yu ĩthĩwa na vinya, we Nzeluvaveli, easya ũu Yeova; na ĩthĩwa na vinya, we Yosua, mwana wa Yeosataki, mũthembi mũnene; na ĩthĩwai na vinya, inyw’ĩ andũ onthe ma nthĩ ĩno, na tethyai wĩa, easya ũu Yeova: nũndũ nĩ vamwe nenyu, easya ũu Yeova wa nguthu,'),
('kam', 'HAG', 2, 5, 'o kwĩanana na ndeto ĩla natianĩie nenyu yĩla mwaumie Misili, na Veva wakwa ekalaa katĩ wenyu; mũikakĩe.'),
('kam', 'HAG', 2, 6, 'Nũndũ ũu nĩw’o Yeova wa nguthu ũnũkwasya: No ĩmwe, o kavinda kanini, na ngathingithya matu, na nthĩ, na ũkanga, na nthĩ nyũmũ;'),
('kam', 'HAG', 2, 7, 'na ngathingithya mbaĩ syonthe; na ũla wendetwe nĩ mbaĩ syonthe ũkooka; na ngausũsya nyũmba ĩno ũtheu mũtisu, easya ũu Yeova wa nguthu.'),
('kam', 'HAG', 2, 8, 'Vetha nĩ wakwa, na thaavu nĩ wakwa, easya ũu Yeova wa nguthu.'),
('kam', 'HAG', 2, 9, 'Ũtheu wa ĩtina wa nyũmba ĩno ũkeethĩwa wĩ mũnene kwĩ ũla wa mbee, easya ũu Yeova wa nguthu; na nganenganĩa mũuo vandũ vaa, easya ũu Yeova wa nguthu.'),
('kam', 'HAG', 2, 10, 'Mũthenya wa mĩongo ĩlĩ na ĩna wa mwei wa kenda, mwaka wa kelĩ wa kũsumbĩka kwa Ndalio, ndeto ya Yeova yooka na kanyw’a wa mwathani Akai, ĩkyasya,'),
('kam', 'HAG', 2, 11, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Kũlyai athembi yu ũndũ wa mĩao, mũkyasya,'),
('kam', 'HAG', 2, 12, 'Ethĩwa ũmwe akakua nyama ntheu ovee mũthyanĩ wa ngũa yake, na mũthya wa ngũa yake ũikiita kĩmũtũ, kana ũsũũ, kana mbinyu, kana mauta, kana lĩu o na wĩva, kĩkatw’ĩka kĩtheu? Na athembi masũngĩa na masya, Aiee.'),
('kam', 'HAG', 2, 13, 'Nĩvo ĩndĩ Akai wakũlilye, Ethĩwa ũmwe mũvuku nũndũ wa ũkiita kimba akakiita kĩndũ kĩmwe kya isu, kĩkeethĩwa kĩ kĩvuku? Na athembi masũngĩa na masya, Kĩkeethĩwa kĩ kĩvuku.'),
('kam', 'HAG', 2, 14, 'Nĩvo ĩndĩ Akai wasũngĩie na asya, Andũ aa mailyĩ ũu, na mbaĩ ĩno ĩilyĩ ũu mbee wakwa, easya ũu Yeova; na no ta ũu kĩla wĩa wa moko moo; na o kĩla mathembaa vo no kĩvuku.'),
('kam', 'HAG', 2, 15, 'Na yu, nĩngũmwĩsũva, sũanĩai mũthenya ũũ, na sũanĩai mĩthenya ĩla mĩthelu, mbee wa ĩvia yĩtanailĩĩlwa ĩũlũ wa ĩvia mwakonĩ wa ĩkalũ ya Yeova.'),
('kam', 'HAG', 2, 16, 'Kuma ĩvinda yĩu yonthe, yĩla ũmwe waenda mbumbunĩ yĩ ithimo mĩongo ĩlĩ, veethĩwa o ĩkũmi; yĩla ũmwe waenda ĩvivanĩ ya mbinyu kwosa itethi mĩongo ĩtano, veethĩwa o mĩongo ĩlĩ.'),
('kam', 'HAG', 2, 17, 'Nĩnamũkũnie na wũmanĩlu na mbuka na mbua ya mavia wĩanĩ w’onthe wa moko menyu; ĩndĩ mũtyaaĩnthyũũĩa, easya ũu Yeova.'),
('kam', 'HAG', 2, 18, 'Sũanĩai, nĩngũmwĩsũva, mũthenya ũũ, na sũanĩai mĩthenya ĩla mĩthelu, kuma mũthenya wa mĩongo ĩlĩ na ĩna wa mwei wa kenda, kuma mũthenya ũla mwambĩlĩlyo wa ĩkalũ ya Yeova wakwatiw’e, sũanĩai.'),
('kam', 'HAG', 2, 19, 'Mbeũ syĩ o ĩkũmbĩnĩ? Ĩĩ, mũsavivũ, na mũkũyũ, na mũkũngũmanga, na mũthata ndĩsyaĩte, kuma ũmũnthĩ nĩngũmũathima.'),
('kam', 'HAG', 2, 20, 'Na ndeto ya Yeova yamũkĩa Akai ĩvinda ya kelĩ mũthenya wa mĩongo ĩlĩ na ĩna wa mwei, ĩkĩmwĩa,'),
('kam', 'HAG', 2, 21, 'Neena na Nzeluvaveli, ngavana wa Yuta, ũkĩmwĩa, Ngathingithya matu na nthĩ;'),
('kam', 'HAG', 2, 22, 'na ngang’uthũla kĩvĩla kya ũsumbĩ kya mosumbĩ; na ngaananga vinya wa mosumbĩ ma mbaĩ; na ngang’uthũlanga makasya ma kaũ, na ala makuĩtwe nĩmo; na mbalasi na ala maitũlĩte makavalũkangan’ya nthĩ, nũndũ wa kũtemangana na mbyũ, kĩla mũndũ na mwana‐a‐ĩthe.'),
('kam', 'HAG', 2, 23, 'Mũthenya ũsu, easya Yeova wa nguthu, ngakwosa, we Nzeluvaveli, mũthũkũmi wakwa, mwana wa Sealitieli, easya ũu Yeova, na ngakũtw’a ta ngome ya ũvana ũsilĩlo; nũndũ nĩnakũnyuvie, easya ũu Yeova wa nguthu.'),
('kam', 'ZEC', 1, 1, 'Mwei wa nyanya, mwaka wa kelĩ wa kũsumbĩka kwa Ndalio, ndeto ya Yeova yamũkĩa mwathani Nzekalia mwana wa Mbelekia, mwana wa Ito, ĩkĩmwĩa,'),
('kam', 'ZEC', 1, 2, 'Yeova nĩwew’ĩthĩw’e woo nĩ aaĩthe menyu.'),
('kam', 'ZEC', 1, 3, 'Kwondũ wa ũu matavye, Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Nzyokeai, easya ũu Yeova wa nguthu, nakwa ngamũsyokea, easya ũu Yeova wa nguthu.'),
('kam', 'ZEC', 1, 4, 'Mũtikethĩwe ta aaĩthe menyu, ala manĩĩw’e nĩ athani ma tene, makyasya, Ũũ nĩw’o Yeova wa nguthu ũnũkwasya, Syokai yu kuma mĩendelenĩ yenyu mĩthũku, na kuma mekonĩ menyu mathũku: ĩndĩ matyaaĩw’a, kana kũmbĩthukĩĩsya, easya ũu Yeova.'),
('kam', 'ZEC', 1, 5, 'Maĩva, aaĩthe menyu? Na athani, nĩmekalaa ĩndĩ yonthe?'),
('kam', 'ZEC', 1, 6, 'Ĩndĩ ndeto syakwa na myamũlo yakwa, ila neeaĩe athũkũmi makwa athani, ityaamakwata aaĩthe menyu? Na masyoka na masya, O tondũ Yeova wa nguthu ũsũanĩĩte kũtwĩka, o kwĩanana na mĩendele yaitũ, na kwĩanana na meko maitũ, now’o ũtwĩkĩte.'),
('kam', 'ZEC', 1, 7, 'Mũthenya wa mĩongo ĩlĩ na ĩna wa mwei wa ĩkũmi na ũmwe, nĩw’o mwei wa Sevati, mwaka wa kelĩ wa kũsumbĩka kwa Ndalio, ndeto ya Yeova yamũkĩa mwathani Nzekalia mwana wa Mbelekia, mwana wa Ito, ĩkĩmwĩa,'),
('kam', 'ZEC', 1, 8, 'Ũtukũ nĩnoonie, na, sisya, mũndũ atũlĩte mbalasi ndune, na aũngama katĩ wa mĩtĩ ya mĩandasi ĩla yaĩ kaũlikunĩ; na ĩtina wake kwaĩ mbalasi, ndune, na ĩ mũkũyũ, na nzaũ.'),
('kam', 'ZEC', 1, 9, 'Nĩvo naisye, We mwĩaĩi wakwa, ii nĩ myaũ? Na mũlaĩka ũla waneenaa nakwa ambĩa, Nĩngũkũmanyĩthya syo.'),
('kam', 'ZEC', 1, 10, 'Na ũla mũndũ ũũngeme katĩ wa mĩandasi asũngĩa na asya, Ii nĩsyo Yeova ũtũmĩte syangange nthĩ kũũ na kũũ.'),
('kam', 'ZEC', 1, 11, 'Na syasũngĩa mũlaĩka wa Yeova ũla waũngyĩ katĩ wa mĩandasi, na syasya, Nĩtwangangĩte nthĩ kũũ na kũũ, na, sisya, nthĩ yonthe ĩkalĩte ĩuĩtye, na ĩthũmũĩte.'),
('kam', 'ZEC', 1, 12, 'Nĩvo mũlaĩka wa Yeova wasũngĩie na asya, Ame Yeova wa nguthu, nĩ veana ata ũtakew’ĩa Yelusaleme na ndũa sya Yuta tei, ila waithĩlĩkĩle myaka ĩno mĩongo mũonza?'),
('kam', 'ZEC', 1, 13, 'Na Yeova asũngĩa mũlaĩka ũla waneenaa nakwa ndeto nzeo, o ndeto sya ũkiakisyo.'),
('kam', 'ZEC', 1, 14, 'Na ĩndĩ mũlaĩka ũla waneenaa nakwa ambĩa, Anĩĩsya, ũkyasya, Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Nĩ na kĩwĩu nũndũ wa Yelusaleme na nũndũ wa Saioni o kĩwĩu kĩnene.'),
('kam', 'ZEC', 1, 15, 'Na nĩngwĩw’ĩthw’a woo mũno nĩ mbaĩ ila ithũmũĩte; nũndũ neew’ĩthiw’e woo o vanini, na makalaata thĩna wũke.'),
('kam', 'ZEC', 1, 16, 'Kwondũ wa ũu Yeova easya atĩĩ: Nĩnzyokete Yelusaleme nĩ na matei; nyũmba yakwa ĩkaakwa nthĩnĩ wayo, na ũlii wa kũthima ũkatambũũkw’a ũthime ku Yelusaleme, easya ũu Yeova wa nguthu.'),
('kam', 'ZEC', 1, 17, 'Anĩĩsya ĩngĩ, ũkyasya, Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: O na ndũa syakwa ikausũa ũathimo wĩtĩkange; o na Yeova akakiakisya Saioni, o na akanyuva Yelusaleme.'),
('kam', 'ZEC', 1, 18, 'Na nookĩlya metho makwa, na noona, na, sisya, mbya inya.'),
('kam', 'ZEC', 1, 19, 'Na namwĩa mũlaĩka ũla waneenaa nakwa, Ii nĩ myaũ? Na anzũngĩa, Ii nĩ mbya ila syanyaĩĩkisye Yuta, na Isilaeli, na Yelusaleme.'),
('kam', 'ZEC', 1, 20, 'Na Yeova ambon’ya atwii ana.'),
('kam', 'ZEC', 1, 21, 'Nĩvo naisye, Aa mooka kwĩka ata? Na anzũngĩa, ambĩa, Ii nĩ mbya ila syanyaĩĩkisye Yuta, mũvaka vatyaĩ mũndũ waaũkĩlya mũtwe; ĩndĩ ii nĩsyooka kũmatĩsya, kwĩkya mbya sya i mbaĩ nthĩ, ila syookĩlilye ũvya wasyo ĩũlũ wa nthĩ ya Yuta imĩnyaĩĩkye.'),
('kam', 'ZEC', 2, 1, 'Na nookĩlya metho makwa, na noona, na, sisya, mũndũ e na ũlii wa kũthima kw’okonĩ kwake.'),
('kam', 'ZEC', 2, 2, 'Nĩvo naisye, Ũendete nakũ we? Nake ambĩa, Kũthima Yelusaleme, kũsisya ũthanthau wayo, na ũasa wayo.'),
('kam', 'ZEC', 2, 3, 'Na, sisya, mũlaĩka ũla waneenaa nakwa athi, na mũlaĩka ũngĩ aumĩla akomane nake,'),
('kam', 'ZEC', 2, 4, 'na amwĩa, Semba, neena na mwanake ũũ, ũkĩmwĩa, Yelusaleme ĩkatũwa ta mĩsyĩ ĩte maũvai, nũndũ wa andũ na indo syayo kwingĩva.'),
('kam', 'ZEC', 2, 5, 'Nũndũ nyie, easya ũu Yeova, ngeethĩwa ũvai wayo wa mwaki ũthyũlũlũkĩte, na ngeethĩwa ndaĩa katĩ wayo.'),
('kam', 'ZEC', 2, 6, 'Ae! Ae! Kĩai mume nthĩ ya ngalĩ ya ĩũlũ, easya ũu Yeova; nũndũ nĩnamũnyaĩĩkisye ta iseve inya sya matu, easya ũu Yeova.'),
('kam', 'ZEC', 2, 7, 'Ae! Saioni, vonoka, we ũla ũtwĩe na mwĩĩtu wa Mbaviloni.'),
('kam', 'ZEC', 2, 8, 'Nũndũ ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Nĩwandũmie kwa i mbaĩ ila syakũvutie nĩ kana ndaĩa yumĩle; nũndũ ũla ũkũkiitaa akiitaa kyũma kya itho yake.'),
('kam', 'ZEC', 2, 9, 'Nũndũ, sisya, ngamatukangĩa kw’oko kwakwa, na makatw’ĩka ma kũtavwa nĩ ala mamathũkũmie; na mũkamanya kana Yeova wa nguthu nĩwandũmie.'),
('kam', 'ZEC', 2, 10, 'Ina na tana, we mwĩĩtu wa Saioni; nũndũ, sisya, ngooka, na ngatũa katĩ waku, easya ũu Yeova.'),
('kam', 'ZEC', 2, 11, 'Na mbaĩ mbingĩ ikeelũman’ya na Yeova mũthenya ũsu, na kwĩthĩwa andũ makwa; na ngatũa katĩ waku, na ũkamanya kana Yeova wa nguthu nũndũmĩte kwaku.'),
('kam', 'ZEC', 2, 12, 'Na Yeova akatiĩwa Yuta ta kĩanda kyake nthĩnĩ wa ĩla nthĩ ntheu, na akanyuva Yelusaleme ĩngĩ.'),
('kam', 'ZEC', 2, 13, 'Vindyai, mĩĩ yonthe, mbee wa Yeova; nũndũ nĩwũkĩlĩte kuma ũtũonĩ wake mũtheu.'),
('kam', 'ZEC', 3, 1, 'Na ambon’ya Yosua mũthembi mũnene aũngamĩte mbee wa mũlaĩka wa Yeova, na Satani aũngamĩte ngalĩ ya kw’oko kwake kwa aũme ethĩwe nthũ yake.'),
('kam', 'ZEC', 3, 2, 'Na Yeova amwĩa Satani, Yeova nakũkan’ye, we Satani; ĩĩ, Yeova ũla wanyuvie Yelusaleme nakũkan’ye: kĩĩ tĩ kĩsinga kĩvulĩtw’e mwakinĩ?'),
('kam', 'ZEC', 3, 3, 'Na ĩndĩ Yosua eekĩĩte ngũa mbuku, na aũngamĩte mbee wa mũlaĩka.'),
('kam', 'ZEC', 3, 4, 'Na asũngĩa akĩneena na ala maũngamĩte mbee wake, akyasya, Mumyei ngũa mbuku. Na amwĩa, Sisya, nĩnakũvetea ũthũku waku, na ngakwĩkĩa ngũa ya thooa mũnene.'),
('kam', 'ZEC', 3, 5, 'Na nasya, Nĩmamwĩkĩe ngũtw’a ntheu mũtwe. Na ĩndĩ mamwĩkĩa ngutw’a ntheu mũtwe, na mamwĩkĩa ngũa; na mũlaĩka wa Yeova aũngamĩte ũtee.'),
('kam', 'ZEC', 3, 6, 'Na mũlaĩka wa Yeova amũkũsĩĩa Yosua, akyasya,'),
('kam', 'ZEC', 3, 7, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Ethĩwa ũkakinyaa nzĩanĩ syakwa, na ethĩwa ũkasũvĩaa wĩaĩo wakwa, nĩvo o naku wĩsilĩla nyũmba yakwa, o na ĩngĩ ũkasũvĩaa nza syakwa, na ngakũnenga vandũ va ũlikĩlaa katĩ wa aa maũngamĩte ũtee.'),
('kam', 'ZEC', 3, 8, 'Iw’a yu, we Yosua mũthembi mũnene, we na atindan’ya maku ala mekalaa nthĩ vala ũĩ; nũndũ andũ asu nĩmo wonan’yo: nũndũ, sisya, ngaumĩlya mũthũkũmi wakwa Ũvonge.'),
('kam', 'ZEC', 3, 9, 'Nũndũ, sisya, ĩvia yĩla naia mbee wa Yosua; ĩũlũ wa ĩvia yĩmwe ve metho mũonza: sisya, ngavana movano mayo, na ngaveta ũthũku wa nthĩ ĩsu mũthenya ũmwe, easya ũu Yeova wa nguthu.'),
('kam', 'ZEC', 3, 10, 'Mũthenya ũsu mũkathokanasya kĩla mũndũ na mũtũi wake ĩtina wa mũsavivũ na ĩtina wa mũkũyũ, easya ũu Yeova wa nguthu.'),
('kam', 'ZEC', 4, 1, 'Na mũlaĩka ũla waneenaa nakwa ooka ĩngĩ, na anamũkya, o ta mũndũ ũla ũamũkaw’a toonĩ wake.'),
('kam', 'ZEC', 4, 2, 'Na ambĩa, Wĩona kyaũ? Nakwa nasya, Nĩnoona, na, sisya, kĩndũ kĩla kĩkĩawa mataa kya thaavu mũthei, kĩ na mbakũli yakyo ĩũlũ wakyo, na mataa makyo mũonza ĩũlũ wakyo; ve mĩtote mũonza ĩvikĩte kĩla taanĩ ũla wĩ ĩũlũ wakyo;'),
('kam', 'ZEC', 4, 3, 'na mĩthata ĩlĩ ũtee wakyo, ũmwe ngalĩ ya kw’oko kwa aũme ya mbakũli, na ũla ũngĩ ngalĩ ya kw’oko kwa aka kwayo.'),
('kam', 'ZEC', 4, 4, 'Na nasũngĩa ngĩneena na mũlaĩka ũla waneenaa nakwa, ngĩkũlya, Ii nĩ myaũ, mwĩaĩi wakwa?'),
('kam', 'ZEC', 4, 5, 'Nĩvo mũlaĩka ũla waneenaa nakwa wasũngĩie na ambĩa, Ii ndũsyĩsĩ? Na nasya, Aiee, mwĩaĩi wakwa.'),
('kam', 'ZEC', 4, 6, 'Nĩvo wasũngĩie akĩneena nakwa, akyasya, Ĩno nĩ ndeto ya Yeova kwa Nzeluvaveli, ĩkĩmwĩa, Ti kwondũ wa vinya mwingĩ, kana kwondũ wa ũtonyi, ĩndĩ nĩ kwondũ wa Veva wakwa, easya ũu Yeova wa nguthu.'),
('kam', 'ZEC', 4, 7, 'Nue ũũ, we kĩĩma kĩnene? Mbee wa Nzeluvaveli ũkatw’ĩka ũiĩ; nake akayumĩlya ĩvia ya ĩũlũ mũthya akĩyũkĩlĩlya wasya mũnene, Mumo, mumo.'),
('kam', 'ZEC', 4, 8, 'Na ĩngĩ ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'ZEC', 4, 9, 'Moko ma Nzeluvaveli nĩmakwatisye mwambĩlĩlyo wa nyũmba ĩno; na ĩngĩ moko make makamĩmina; na ũkamanya kana Yeova wa nguthu nũndũmĩte kwenyu.'),
('kam', 'ZEC', 4, 10, 'Nũndũ nũũ ũvũthĩtye mũthenya wa maũndũ manini? Nũndũ asu mũonza makatana, na makoona kavilũ ke kw’okonĩ kwa Nzeluvaveli; asu nĩ metho ma Yeova, ala masembaa kũũ na kũũ nthĩ yonthe.'),
('kam', 'ZEC', 4, 11, 'Nĩvo nasũngĩie, na namũkũlya, Mĩthata ĩsu ĩlĩ ĩ ngalĩ ya kw’oko kwa aũme kwa kĩla kĩndũ kĩkĩawa mataa na ngalĩ ya kw’oko kwa aka nĩ myaũ?'),
('kam', 'ZEC', 4, 12, 'Na nasũngĩa ĩvinda ya kelĩ, na namũkũlya, Mbonge ii ilĩ sya mũthata, ila syĩ ũtee wa mĩtote ĩlĩ ya thaavu, ĩla ĩyumasya mauta ma thaavu, nĩsyo kyaũ?'),
('kam', 'ZEC', 4, 13, 'Na anzũngĩa na asya, Ii ndũsyĩsĩ? Na nasya, Aiee, mwĩaĩi wakwa.'),
('kam', 'ZEC', 4, 14, 'Nĩvo waisye, Ii nĩsyo ala elĩ metĩkĩw’e mauta, ala maũngamaa ũtee wa Mwĩaĩi wa nthĩ yonthe.'),
('kam', 'ZEC', 5, 1, 'Na ĩndĩ nookĩlya metho makwa ĩngĩ, na noona, na, sisya, ĩvuku ĩkũnze yĩũlũkĩte.'),
('kam', 'ZEC', 5, 2, 'Na angũlya, Wĩona kyaũ? Nakwa nasũngĩa, Nĩona ĩvuku ĩkũnze yĩũlũkĩte; ũasa wayo nĩ mĩkono mĩongo ĩlĩ, na ũthanthau wayo mĩkono ĩkũmi.'),
('kam', 'ZEC', 5, 3, 'Nĩvo wambĩie, Kĩĩ nĩ kĩumo kĩla kyumite kĩthi ĩũlũ wa nthĩ yonthe: nũndũ kĩla ũmwe ũla wũyaa akavetwa aume ngalĩ ĩmwe kwĩanana na ũndũ kũandĩkĩtwe; na kĩla ũmwe wĩavaa akavetwa aume ngalĩ ĩla ĩngĩ kwĩanana na ũndũ kũandĩkĩwe.'),
('kam', 'ZEC', 5, 4, 'Ngatuma kyuma kĩthi, na kĩkalika nyũmbanĩ ya kĩng’ei, na nyũmbanĩ ya ũla wĩvĩtaa ũvũngũ na syĩtwa yakwa, easya ũu Yeova wa nguthu; na kĩkekala katĩ wa nyũmba yake, na kĩkamĩmina vamwe na mĩtĩ yayo na mavia mayo.'),
('kam', 'ZEC', 5, 5, 'Nĩvo mũlaĩka ũla waneenaa nakwa waumaalile, na ambĩa, Yu ũkĩlya metho maku, ũsisye kĩĩ nĩ kyaũ kyumĩte kĩthi.'),
('kam', 'ZEC', 5, 6, 'Na nakũlya, Nĩkyo kyaũ? Nake asũngĩa, Ĩno nĩ eva yumĩte ĩthi. Ambĩa ĩngĩ, Ũu nĩw’o mailyĩ ĩ nthĩ yonthe'),
('kam', 'ZEC', 5, 7, '(na, sisya, vookĩlilw’e talendi ya ĩvulũ); na ũũ nĩ mũndũ mũka wĩkalĩte katĩ wa eva.'),
('kam', 'ZEC', 5, 8, 'Na asya, Ũũ nĩ Ũthũku: na amũng’uthanĩa vu nthĩnĩ wa eva; na ekya yĩla ĩvulũ kanyw’anĩ wayo.'),
('kam', 'ZEC', 5, 9, 'Nĩvo nookĩlilye metho makwa, na noona, na, sisya, kwaumĩlile aka elĩ, na kĩseve kyaĩ nthwaunĩ syoo; na ĩndĩ maĩ na nthwau ta nthwau sya ĩsaũ; na mookĩlya eva katĩ wa nthĩ na ĩtu.'),
('kam', 'ZEC', 5, 10, 'Nĩvo neeie mũlaĩka ũla waneenaa nakwa. Aa makua eva meelya nakũ?'),
('kam', 'ZEC', 5, 11, 'Nake anzũngĩa, Methi kũmwakĩa nyũmba nthĩ ya Sinali: na yamina kũseũvw’a, akekalw’a vo vandũ vake mwene.'),
('kam', 'ZEC', 6, 1, 'Na ĩngĩ nookĩlya metho makwa, na noona, na, sisya, kwooka makasya ana ma kaũ kuma katĩ wa iĩma ilĩ; na iĩma isu syaĩ iĩma sya ũthuku.'),
('kam', 'ZEC', 6, 2, 'Ĩkasya ya mbee yaĩ na mbalasi ndune; na ĩkasya ya kelĩ mbalasi nziũ;'),
('kam', 'ZEC', 6, 3, 'na ĩkasya ya katatũ mbalasi nzaũ; na ĩkasya ya kana mbalasi syĩ vinya syĩ iumbĩ.'),
('kam', 'ZEC', 6, 4, 'Nĩvo nasũngĩie na neea mũlaĩka ũla waneenaa nakwa. Ii nĩ myaũ, mwĩaĩi wakwa?'),
('kam', 'ZEC', 6, 5, 'Na mũlaĩka asũngĩa na ambĩa, Ii nĩ iseve inya sya ĩtu, ila iendaa syumĩte vala iũngamaa mbee wa Mwĩaĩi wa nthĩ yonthe.'),
('kam', 'ZEC', 6, 6, 'Ĩkasya yĩla yĩ na mbalasi nziũ yumĩte yĩendete nthĩ ya ngalĩ ya ĩũlũ; na ila nzaũ syauma siatĩĩe; na ila syĩ ĩumbĩ syauma iendete nthĩ ya ngalĩ ya ĩtheo.'),
('kam', 'ZEC', 6, 7, 'Na ila syĩ vinya syaumĩla, na syenda kũthi syangange nthĩ kũũ na kũũ: na asya, Umai vaa, mwangange nthĩ kũũ na kũũ. Na ĩndĩ syanganga nthĩ kũũ na kũũ.'),
('kam', 'ZEC', 6, 8, 'Nĩvo wambanĩĩsye, na aneena nakwa, akyasya, Sisya, ila iendaa kwelekela nthĩ ya ngalĩ ya ĩũlũ nikilĩthĩtye veva wakwa ku nthĩ ya ngalĩ ya ĩũlũ.'),
('kam', 'ZEC', 6, 9, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'ZEC', 6, 10, 'Osa kwa ala mataviwe, o kwa Elitai, na kwa Toviya, na kwa Yetaia; na ũkyũka mũthenya o ũsu, na ũivota nyũmbanĩ ya Yosia mwana wa Nzevania, ĩla malikile mauma Mbaviloni;'),
('kam', 'ZEC', 6, 11, 'ĩĩ, osa kwamo vetha na thaavu, na ũiseũvya ngovia sya ũsumbĩ, na ũisyĩkĩa mũtwenĩ wa Yosua mwana wa Yeosataki, mũthembi mũnene;'),
('kam', 'ZEC', 6, 12, 'na neena nake, ũkĩmwĩa, Ũũ nĩw’o Yeova wa nguthu ũnũũneena, akyasya, Sisya, mũndũ ũla wĩtawa syĩtwa yake Ũvonge: na akeana e o kwake; na akaaka ĩkalũ ya Yeova;'),
('kam', 'ZEC', 6, 13, 'o we akaaka ĩkalũ ya Yeova; na akakua ndaĩa, na akekala kĩvĩlanĩ kyake kya ũsumbĩ na kũsumbĩka; na akeethĩwa mũthembi kĩvĩlanĩ kyake kya ũsumbĩ; na nzama ya mũuo ĩkeethĩwa katĩ woo elĩ.'),
('kam', 'ZEC', 6, 14, 'Na ngovia sya ũsumbĩ ikeethĩwa ũlilikan’yo ĩkalũnĩ ya Yeova ũndũ wa Elemu, na Toviya, na Yetaia, na Eni mwana wa Nzevania.'),
('kam', 'ZEC', 6, 15, 'Na ala me kũasa makooka na makyaka ĩkalũnĩ ya Yeova: na mũkamanya kana Yeova wa nguthu nũndũmĩte kwenyu. Na ũu ũkeethĩwa, ethĩwa mũkeew’aa na kĩthing’ĩĩsyo wasya wa Yeova Ngai wenyu.'),
('kam', 'ZEC', 7, 1, 'Na kweethĩwa mwaka wa kana wa kũsumbĩka kwa mũsumbĩ Ndalio, ndeto ya Yeova yamũkĩa Nzekalia mũthenya wa kana wa mwei wa kenda, wĩtawa Kiselevu.'),
('kam', 'ZEC', 7, 2, 'Na yu ala ma Mbethi‐eli matũma Saleseli na Lekemimeleki, na andũ moo, kũvoya tei kwa Yeova,'),
('kam', 'ZEC', 7, 3, 'na kũneena na athembi ma nyũmba ya Yeova wa nguthu, na athani, akĩkũlya, Nĩnaĩle kũĩa mwei wa katano, ngĩvatha mwene, o tondũ nĩkĩte myaka ĩsu yingĩvĩte ũu?'),
('kam', 'ZEC', 7, 4, 'Nĩvo ndeto ya Yeova wa nguthu yambũkĩe, ĩkĩmbĩa,'),
('kam', 'ZEC', 7, 5, 'Neena na andũ onthe ma ĩ nthĩ, na athembi, ũkĩkũlya, Yĩla mwatĩĩie kũya na mwameta mwei wa katano na wa mũonza, o myaka ĩsu mĩongo mũonza, mwaatĩĩa nongi kũya nũndũ wakwa, nyie?'),
('kam', 'ZEC', 7, 6, 'Na yĩla mũĩsaa, na kũnyw’a, mũtiĩsaa nũndũ wenyu ene, na kũnyw’a nũndũ wenyu ene?'),
('kam', 'ZEC', 7, 7, 'Mũtyaĩle kwĩw’a ndeto ila Yeova waneenie na kanyw’a wa athani ma tene, yĩla Yelusaleme yatwĩwe nĩ andũ na ĩkaĩla, na ndũa syayo imĩthyũlũlũkĩte, na ngalĩ ya ĩtheo na nthĩ ndindimalu syatwĩwe?'),
('kam', 'ZEC', 7, 8, 'Na ndeto ya Yeova yamũkĩa Nzekalia, ĩkĩmwĩa,'),
('kam', 'ZEC', 7, 9, 'Ũũ nĩw’o Yeova wa nguthu ũneenete, akyasya, Silaai sila wa katĩ, na kĩla mũndũ akyon’ya mwanaa‐ĩthe ũseo na ĩnee;'),
('kam', 'ZEC', 7, 10, 'na mũtikathĩn’ye aka ndiwa, o na ala makw’ĩĩwe nĩ aaĩthe, o na mwĩkali wa ũeninĩ, o na ngya; na kũtikethĩwe ũmwe wenyu ũsũanĩĩa mwana‐a‐ĩthe ngoonĩ ũndũ ũthũku.'),
('kam', 'ZEC', 7, 11, 'Ĩndĩ nĩmaleile kwĩw’a, na mambatĩsya ituo, na makunĩka matũ moo, nĩ kana matikew’e.'),
('kam', 'ZEC', 7, 12, 'Ĩĩ, nĩmoomĩsye ngoo syoo ta ĩvia ya ũana, matikese kwĩw’a mĩao, na ndeto ila Yeova wa nguthu watwaie na Veva wake na kanyw’a wa athani tene: kwondũ wa ũu nĩkwaumie ũthilĩku mũnene kwa Yeova wa nguthu.'),
('kam', 'ZEC', 7, 13, 'Na kwĩkĩkĩte atĩĩ, o tondũ wetanie, nao matyaaĩtĩkĩla kwĩw’a, nao makeetana o ta ũu, nakwa ndikew’a, easya ũu Yeova wa nguthu;'),
('kam', 'ZEC', 7, 14, 'ĩndĩ ngamanyaĩĩkya na kĩlingi katĩ wa mbaĩ syonthe ila mataaimanya. O ta ũu ĩ nthĩ yatiiwe yĩ nthei itina woo, ũndũ vataĩ mũndũ waamĩvĩtĩla kana kũsyokela: nũndũ nĩmamĩtw’ĩkĩthĩtye nthĩ ya kwendeesya nthei.'),
('kam', 'ZEC', 8, 1, 'Na ndeto ya Yeova wa nguthu yambũkĩa, ĩkĩmbĩa,'),
('kam', 'ZEC', 8, 2, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Nĩ na kĩwĩu ũndũ wa Saioni o kĩwĩu kĩnene, na nĩ na kĩwĩu nũndũ wayo kĩ ũthilĩku mũnene.'),
('kam', 'ZEC', 8, 3, 'Ũũ nĩw’o Yeova ũnũkwasya: Nĩnasyoka Saioni, na ngatũa Yelusaleme katĩ: na Yelusaleme ĩkeetawa Ndũa ya w’o; na kĩĩma kya Yeova wa nguthu kĩkeetawa Kĩĩma kĩtheu.'),
('kam', 'ZEC', 8, 4, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: O na kũkeethĩwa atumĩa akũũ na iveti ngũũ mekalĩte nzĩanĩ nene sya Yelusaleme, kĩla mũndũ e na ndata yake kw’okonĩ kwake, nũndũ wa kũkũa mũno.'),
('kam', 'ZEC', 8, 5, 'Na nzĩa nene sya ndũa ikausũwa nĩ ivĩsĩ na eĩtu makĩthaũka nzĩanĩ nene syayo.'),
('kam', 'ZEC', 8, 6, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Ethĩwa nĩ ũseng’yo methonĩ ma ũtialo wa andũ aa mĩthenya ĩsu, nĩwaĩle kwĩthĩwa ũseng’yo methonĩ makwa? Ekũlya ũu Yeova wa nguthu.'),
('kam', 'ZEC', 8, 7, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Sisya, ngatangĩĩa andũ makwa kuma nthĩ ya wumĩlonĩ wa syũa, na kuma nthĩ ya ũthũĩlonĩ wa syũa;'),
('kam', 'ZEC', 8, 8, 'na ngamaete, na makatũa nthĩnĩ wa Yelusaleme; na makeethĩwa andũ makwa, na ngeethĩwa Ngai woo, nthĩnĩ wa w’o na nthĩnĩ wa ũlũngalu.'),
('kam', 'ZEC', 8, 9, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Moko menyu nĩmethĩwe na vinya, inyw’ĩ ala mũkwĩw’a mĩthenya ĩno ndeto ii kuma kanyw’anĩ wa athani ala maĩ vo mũthenya ũla mwambĩlĩlyo wa nyũmba ya Yeova wa nguthu wakwatiw’e, nayo nĩ ĩkalũ, nĩ kana yakwe.'),
('kam', 'ZEC', 8, 10, 'Nũndũ mbee wa mĩthenya ĩsu kũtyaĩ ĩtuvĩ ya mũndũ kana ĩtuvi ya nyamũ; o na kũtyaĩ mũuo kwa ũla waumaalile kana ũla walikile, nũndũ wa nthũ: nũndũ nĩngũmaingĩanĩsya andũ onthe kĩla ũmwe na mũtũi wake.'),
('kam', 'ZEC', 8, 11, 'Ĩndĩ yu kwa ũtialo wa andũ aa ndikethĩwa ta mĩthenya ya tene, easya ũu Yeova wa nguthu.'),
('kam', 'ZEC', 8, 12, 'Nũndũ kũkeethĩwa ũsyao wa mũuo; mũsavivũ ũkasyaa ũsyao waw’o, na nthĩ ĩkaingĩvasya ũsyao wayo, na matu makaete ĩmwe yamo; na ngatuma ũtialo wa andũ aa ũtiĩwa maũndũ aa onthe.'),
('kam', 'ZEC', 8, 13, 'Na kũkeethĩwa, o tondũ mwaĩ kĩumo katĩ wa i mbaĩ, inyw’ĩ nyũmba ya Yuta na nyũmba ya Isilaeli, o ta ũu ngamũtangĩĩa, na mũkeethĩwa ũathimo. Mũikakĩe, ĩndĩ moko menyu nĩmethĩwe na vinya.'),
('kam', 'ZEC', 8, 14, 'Nũndũ ũũ nĩw’o Yeova wa nguthu ũnũkwasya: O tondũ nasũanĩĩte kũmwĩka ũthũku, yĩla aaĩthe menyu manthilĩkilye, easya ũu Yeova wa nguthu, na ndyaaĩtũnga;'),
('kam', 'ZEC', 8, 15, 'o ta ũu nĩnzũanĩĩte ĩngĩ mĩthenya ĩno kwĩka Yelusaleme na nyũmba ya Yuta nesa: mũikakĩe.'),
('kam', 'ZEC', 8, 16, 'Aa nĩmo maũndũ ala mwĩĩkaa: Neenaai w’o kĩla mũndũ na mũtũi wake; silĩlaai sila wa katĩ na wa mũuo mbingĩlonĩ syenyu;'),
('kam', 'ZEC', 8, 17, 'na kũtikethĩwe ũmwe wenyu ũsũanĩĩa mũtũi wake ngoonĩ ũndũ ũthũku; na mũikende wĩvĩto wa ũvũngũ: nũndũ aa onthe nĩmo maũndũ ala nĩmenaa, easya ũu Yeova.'),
('kam', 'ZEC', 8, 18, 'Na ndeto ya Yeova wa nguthu yambũkĩa, ĩkĩmbĩa,'),
('kam', 'ZEC', 8, 19, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Kũtĩĩa kũya kwa mwei wa kana na, kũtĩĩa kũya kwa mwei wa katano, na kũtĩĩa kũya kwa mwei wa mũonza, na kũtĩĩa kũya kwa mwei wa ĩkũmi, kũkeethĩwa kwa nyũmba ya Yuta ũtanu na mũyo, na mboka sya ũtanu; kwondũ wa ũu endai w’o na mũuo.'),
('kam', 'ZEC', 8, 20, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: O na ĩngĩ kũkooka ngo sya andũ, o na ala matwĩe ndũanĩ mbingĩ;'),
('kam', 'ZEC', 8, 21, 'na ala matwĩe ndũanĩ ĩmwe makathi ĩla ĩngĩ, makyasya, Tũendei mĩtũkĩ tũkesũve Yeova atwĩke nesa, na kũmantha Yeova wa nguthu: o nakwa nĩngũthi.'),
('kam', 'ZEC', 8, 22, 'Ĩĩ, ngo mbingĩ sya andũ na mbaĩ syĩ vinya ikooka kũmantha Yeova wa nguthu Yelusaleme, na kwĩsũva Yeova asyĩke nesa.'),
('kam', 'ZEC', 8, 23, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Mĩthenya ĩsu kũkeethĩwa, atĩ andũ ĩkũmi, kuma ithyomonĩ syonthe sya i mbaĩ, makakwata, ĩĩ, makakwata mũthya wa ngũa ya mũndũ Mũyuti, makyasya, Nĩtũkũthi nenyu, nũndũ nĩtwĩw’ĩte kana Ngai e vamwe nenyu.'),
('kam', 'ZEC', 9, 1, 'Ũito wa ndeto ya Yeova ĩũlũ wa nthi ya Atilaki, nayo Ndamasiku ikeethĩwa vandũ vayo va kwĩkala (nũndũ itho ya mũndũ na ya mbaĩ syonthe sya Isilaeli yelekele Yeova);'),
('kam', 'ZEC', 9, 2, 'o na Amathi, ĩla ĩvakanĩte nayo; o na Tile na Sitoni, nũndũ nĩ mbũĩ mũno.'),
('kam', 'ZEC', 9, 3, 'Na Tile nĩĩyakĩe ngome yĩ vinya, na kũmban’ya vetha ta kĩtoo, na kũmban’ya thaavu mũtheu ta ndaka nzĩanĩ nene.'),
('kam', 'ZEC', 9, 4, 'Sisya, Mwĩaĩi akamĩvuta, na akakũnĩa ũtonyi wayo ũkanganĩ; na ĩkaanangwa na mwaki.'),
('kam', 'ZEC', 9, 5, 'Asikeloni ĩkoona ũu, na ĩkĩkĩa: na Ngasa o ta ũu, na ĩkeethĩwa na kyalya kĩnene; o na Ekiloni, nũndũ wĩkwatyo wayo ũkasonokw’a; na Ngasa ĩkaaa mũsumbĩ, na Asikeloni ndĩkatũwa.'),
('kam', 'ZEC', 9, 6, 'Na mũndũ wasyaĩwe ũlaalainĩ akatũa Asitoti, na ngaveta ngathiĩo sya Avilisiti.'),
('kam', 'ZEC', 9, 7, 'Na ngaveta kũnyw’a nthakame kanyw’anĩ wake, na mothatyo make maume maeonĩ make; o nake akeethĩwa ũtialo kwa Ngai waitũ; na akeethĩwa ta mũnene nthĩnĩ wa Yuta, na Ekiloni ta Mũyevusĩ.'),
('kam', 'ZEC', 9, 8, 'Na ngamba maeema nĩthyũlũlũkĩtye nyũmba yakwa nĩsiĩĩe nguthu ya kaũ, nĩ kana kũtikethĩwe ũmwe wĩvĩta mũkuthũ kana kũsyoka; na kũtikavĩtĩla mũthĩn’ya katĩ wamo ĩngĩ: nũndũ yu nĩnonete na metho makwa.'),
('kam', 'ZEC', 9, 9, 'Tana mũno, we mwĩĩtu wa Saioni; ũkĩlya wasya, we mwĩĩtu wa Yelusaleme: sisya, mũsumbĩ waku nĩwũkĩte kwaku; nĩ mũlũngalu, na e na ũtangĩĩo; e na wĩnyivyo, na atũlĩte ĩng’oĩ, o ndena, ndena ya ĩng’oi.'),
('kam', 'ZEC', 9, 10, 'Na ngaveta ĩkasya ya kaũ kwa Evalaimu, na mbalasi Yelusaleme; na ũta wa kaũ ũkavetwa; na akaneena mũuo kwa ĩ mbaĩ: na ũsumbĩko wake ũkeethĩwa kuma ũkanga kũvika ũkanga, na kuma ũla Ũsĩ kũvika itulunĩ sya nthĩ.'),
('kam', 'ZEC', 9, 11, 'O na ĩngĩ ũndũ waku, nũndũ wa nthakame ya ũtianĩo waku nĩnĩthaĩtye ovwa maku maume ĩimanĩ yĩla yĩte kĩw’ũ.'),
('kam', 'ZEC', 9, 12, 'Syokai ĩla ngomenĩ yĩ vinya, inyw’ĩ ovwa me wĩkwatyo: o na ũmũnthĩ nĩngũtavan’ya kana nĩngũkũĩva kũndũ kwĩlĩ.'),
('kam', 'ZEC', 9, 13, 'Nũndũ nĩngootete Yuta nũndũ wakwa ta ũta, nĩvakĩĩsye Evalaimu; ngaingĩanĩsya ana maku, we Saioni, na ana maku, we Ngiliki, na ngakũtw’ĩkĩthya ta ũvyũ wa ngũmbaũ.'),
('kam', 'ZEC', 9, 14, 'Na Yeova akooneka ĩũlũ woo; na mũsyĩ wake ũkaumĩla ta ũtisi; na Mwĩaĩi Yeova akavuva soo, na akaendan’ya na ilingi sya ngalĩ ya ĩtheo.'),
('kam', 'ZEC', 9, 15, 'Yeova wa nguthu akamasesea; na makaya, na makakinyangĩa mavia ma kĩkũtha nthĩ; na makanyw’a, na makalonzan’ya ta manyw’ĩte mbinyu; na makausũa ta mbakũli, na kũkola o ta ikoto sya kĩthembeo.'),
('kam', 'ZEC', 9, 16, 'Na Yeova Ngai woo akamatangĩĩa mũthenya ũsu ta ĩĩthya ya andũ make; nũndũ makeethĩwa ta tũvila twa ngovia ya ũsumbĩ, tũkĩlĩtw’e mũno ĩũlũ wa nthĩ yake.'),
('kam', 'ZEC', 9, 17, 'A! Ũndũ ũseo wake ũnenevete, na ũndũ wanakavu wake ũnenevete! Lĩu wa mbaa ngetha ũkatuma anake meana, na mbinyu mbĩthĩ eĩtu atheu.'),
('kam', 'ZEC', 10, 1, 'Ĩtyai Yeova mbua ĩvinda ya mbua ya uũa, o Yeova ũla ũseũvasya motisi; na akamanenga mĩono ya mbua, akanenga kĩla ũmwe nyeki kĩsesinĩ.'),
('kam', 'ZEC', 10, 2, 'Nũndũ telavimu nĩneenete ndeto sya mana, na ala maaũasya nĩmonete ũvũngũ; na nĩmatavanĩtye ndoto ite sya w’o, nĩmakiakiasya mana: kwondũ wa ũu nĩmeyĩendeaa ta malondu, nĩmathĩnaw’a, nĩkwĩthĩwa vati mũĩthi.'),
('kam', 'ZEC', 10, 3, 'Ũthatu wakwa nĩwakanĩe aĩthi, na ngasilĩla i nthenge; nũndũ Yeova wa nguthu nũsyaĩĩtye ĩĩthya yake, nyũmba ya Yuta, na akamatw’a o ta mbalasi yake nzeo kaũnĩ.'),
('kam', 'ZEC', 10, 4, 'Vamwe, kwake kũkauma ĩvia ya kĩkoto, kwake kũkauma mũsumaa, kwake kũkauma ũta wa kaũ, kwake kũkauma kĩla mũsumbĩki.'),
('kam', 'ZEC', 10, 5, 'Na makeethĩwa ta ngũmbaũ, maiangĩa amaitha moo nthĩ ndakanĩ sya nzĩa nene kaũnĩ; na makokita, nĩkwĩthĩwa Yeova e vamwe namo; na ala matũlĩte mbalasi makathokoanw’a.'),
('kam', 'ZEC', 10, 6, 'Na ngeekĩa nyũmba ya Yuta vinya, na ngatangĩĩa nyũmba ya Yosevu, na ngamatũnga; nũndũ nĩ na tei kwoo; na makeethĩwa ta ndaamba kũmaveta: nũndũ ninyie Yeova Ngai woo, na ngamew’a.'),
('kam', 'ZEC', 10, 7, 'Na ala ma Evalaimu makeethĩwa mailyĩ ngũmbaũ, na ngoo syoo ikatana o ta manyw’ĩte mbinyu; ĩĩ, syana syoo ikawona, na kwĩw’a mũyo; ngoo syoo ikatanĩa Yeova.'),
('kam', 'ZEC', 10, 8, 'Ngamauĩsya kĩlũli, na kũmomban’ya; nũndũ nĩnĩmovoetye; na makaingĩva o tondũ maingĩvĩte.'),
('kam', 'ZEC', 10, 9, 'Na ngamavuĩa katĩ wa ngo sya andũ; na makandilikanĩla nthĩ syĩ kũasa; na makekala thayũ na syana syoo, na makasyoka.'),
('kam', 'ZEC', 10, 10, 'Ngamaete o ĩngĩ kuma nthĩ ya Misili, na kũmomban’ya kuma nthĩ ya Asuli; na ngamaete nthĩ ya Ngileati na Levanoni; na vatikoneka vandũ vameanĩe.'),
('kam', 'ZEC', 10, 11, 'Na akavĩtĩla ũkanganĩ wa thĩna, na akakũna itulumo syĩ ũkanganĩ, na syũngũ syonthe sya Naelo ikang’ala; na ngathĩĩo sya Asuli ikatheew’a nthĩ, na ndata ya ũsumbĩ ya Misili ĩkathi.'),
('kam', 'ZEC', 10, 12, 'Na ngamekĩa vinya nthĩnĩ wa Yeova; na makaenda kũũ na kũũ syĩtwanĩ yake, easya ũu Yeova.'),
('kam', 'ZEC', 11, 1, 'Vingũa mĩomo yaku, we Levanoni, nĩ kana mwaki ũvĩvye mĩtĩ yaku ya mĩkũũ.'),
('kam', 'ZEC', 11, 2, 'Kaya, we mũtĩ wa mũsonovali, nũndũ mũkũũ nĩ mũvalũku, nĩkwĩthĩwa ĩla mĩseo nĩ myanangĩku: kayai, inyw’ĩ mĩtĩ ya myaloni yĩ Mbasani, nũndũ mũtitũ wĩ vinya nĩ mũvalũku nthĩ.'),
('kam', 'ZEC', 11, 3, 'A! Wasya wa kũkaya kwa aĩthi! Nũndũ ndaĩa yoo nĩ mbanangĩku: a! Wasya wa kĩlumo kya mĩnyambũ ya mũika! Nũndũ ngathĩĩo sya Yolotani nĩsyanangĩtwe.'),
('kam', 'ZEC', 11, 4, 'Ũũ nĩw’o Yeova Ngai wakwa waisye: Ĩthya ĩĩthya ya kũthĩnzwa;'),
('kam', 'ZEC', 11, 5, 'yĩla ene mayo mayũaaa, na matyĩyonaa ene ta me na ĩvĩtyo; na ala mayĩthooasya maasya, Nataĩwe Yeova, nũndũ nyie nĩ mũthwii; na aĩthi mayo ene matiyĩw’ĩaa ĩnee.'),
('kam', 'ZEC', 11, 6, 'Nũndũ ndikew’ĩa ala matwĩe ĩ nthĩ ĩnee ĩngĩ, easya ũu Yeova; ĩndĩ, sisya, ngamanengane andũ asu kĩla ũmwe kw’okonĩ kwa mũtũi wake, na kw’okonĩ kwa mũsumbĩ wake; na makamĩkũna ĩ nthĩ, na ndikamatangĩĩa kw’okonĩ kwoo.'),
('kam', 'ZEC', 11, 7, 'Na ĩndĩ naĩthya ĩĩthya ya kũthĩnzwa, nĩ w’o, o ila mbonzu sya ĩĩthya. Na neeyosea ndata ilĩ; ĩmwe namĩta Ũseo, na ĩla ĩngĩ namĩta Mawĩw’ano; na naĩthya ĩĩthya.'),
('kam', 'ZEC', 11, 8, 'Na naveta aĩthi atatũ mwei ũmwe; nũndũ ngoo yakwa nĩyanoetw’e nĩmo, na ngoo syoo nasyo nĩsyangolete.'),
('kam', 'ZEC', 11, 9, 'Nĩvo naisye, Ndikamũĩthya: ũla ũnũũkw’a, nakw’e; na ũla ũnũkwaa, nĩae, na ala matiala nĩmaĩsane kĩla ũmwe na ũla ũngĩ.'),
('kam', 'ZEC', 11, 10, 'Na noosa ndata yakwa ĩla ĩtawa Ũseo, na namĩtilan’ya, nĩ kana nanange ũtianĩo ũla natianĩe na ngo syonthe sya andũ.'),
('kam', 'ZEC', 11, 11, 'Na waanangiwe mũthenya ũsu; na o ta ũu asu onzu ĩĩthyanĩ ala mambĩw’aa mamanya kana nĩ ndeto ya Yeova.'),
('kam', 'ZEC', 11, 12, 'Na namea, Ethĩwa nĩmũkwona nĩ ũseo, nengai ĩtuvi yakwa; na ethĩwa ti w’o, ekai. Na ĩndĩ manthimĩa ĩtuvi yakwa ilungu mĩongo ĩtatũ sya vetha.'),
('kam', 'ZEC', 11, 13, 'Na Yeova ambĩa, Mwĩkĩsye mũmbi wa mbisũ, thooa mũseo ũla natw’ĩĩwe nĩmo. Nakwa noosa ilungu isu mĩongo ĩtatũ sya vetha, na nasyĩkĩsya mũmbi, nyũmbanĩ ya Yeova.'),
('kam', 'ZEC', 11, 14, 'Nĩvo natilanilye ndata ĩla ĩngĩ yakwa, o Mawĩw’ano, nĩ kana nanange ũ‐ana‐a‐ĩthe katĩ wa Yuta na Isilaeli.'),
('kam', 'ZEC', 11, 15, 'Na Yeova ambĩa, Ĩyosee o ĩngĩ mĩio ya mũĩthi mũtumanu.'),
('kam', 'ZEC', 11, 16, 'Nũndũ, sisya, ngookĩlya mũĩthi ĩ nthĩ, ũla ũtakaisisya ila mbete, o na ndakamantha ila inyaĩĩkĩtw’e, o na kũvosya ila ndũlĩkangu, o na kũĩthya ila nima; ĩndĩ akaĩsaa nyama sya malondu manou, na akatembũanga mavũngũ mamo tũlungu.'),
('kam', 'ZEC', 11, 17, 'Woo nĩ wa mũĩthĩ ũte vata ũla ũtiaa ĩĩthya! Ũvyũ ũkeethĩwa ĩũlũ wa kw’oko kwake, na ĩũlũ wa itho yake ya ngalĩ ya kw’oko kwa aũme: kw’oko kwake kũkooma vyũ, na itho yake ya ngalĩ ya kw’oko kwa aũme yĩkatulya kĩvĩndu vyu.'),
('kam', 'ZEC', 12, 1, 'Ũito wa ndeto ya Yeova ũndũ wa Isilaeli. Ũũ nĩw’o Yeova ũnũkwasya, ũla ũtambũũkasya matu, na ũkwatasya mwambĩlĩlyo wa nthĩ, na wũmbaa veva wa mũndũ nthĩnĩ wake:'),
('kam', 'ZEC', 12, 2, 'Sisya, nĩngũtw’ĩkĩthya Yelusaleme kĩkombe kya kũlũsya kwa ngo syonthe sya andũ ila imĩthyũlũlũkĩte, na ĩngĩ kĩkeethĩwa ĩũlũ wa Yuta kũtw’ĩkanĩw’anĩ kwa Yelusaleme.'),
('kam', 'ZEC', 12, 3, 'Na kũkeethĩwa mũthenya ũsu, ngatw’ĩkĩthya Yelusaleme ĩvia ĩito kwa ngo syonthe sya andũ; onthe ala meĩyaĩkya yo makokitĩka mũno; na i mbaĩ syonthe sya nthĩ ikamĩlĩlĩĩla.'),
('kam', 'ZEC', 12, 4, 'Mũthenya ũsu, ngakũna kĩla mbalasi na ũtĩsyo, na ũla ũmĩtũlĩte ngamũkũna na ndũũka, easya ũu Yeova; na ngasalukĩlya nyũmba ya Yuta metho makwa, na ngakũna kĩla mbalasi ya ngo sya andũ na mbindu.'),
('kam', 'ZEC', 12, 5, 'Na anene ma Yuta makaasya ngoonĩ syoo, Ala matwĩe Yelusaleme nĩmo vinya wakwa nthĩnĩ wa Yeova wa nguthu Ngai woo.'),
('kam', 'ZEC', 12, 6, 'Mũthenya ũsu ngatw’ĩkĩthya anene ma Yuta ta kĩlĩo kĩ mwaki katĩ wa ngũ, na ta ũmũĩ mwakanu katĩ wa syove sya ngetha; na makamina ngo syonthe sya andũ ila ithyũlũlũkĩte kw’onthe, ngalĩ ya kw’oko kwa aũme na kwa aka; na ala ma Yelusaleme makatũa o ĩngĩ kũndũ kwoo, o Yelusaleme.'),
('kam', 'ZEC', 12, 7, 'Yeova nake akatangĩĩa maeema ma Yuta mbee, nĩ kana ndaĩa ya nyũmba ya Ndaviti na ndaĩa ya ala matwĩe Yelusaleme ndĩkanenevw’e kwĩ ya Yuta.'),
('kam', 'ZEC', 12, 8, 'Mũthenya ũsu Yeova akamasesea ala matwĩe Yelusaleme; na mũthenya ũsu ũla mwonzu katĩ wamo akeethĩwa ta Ndaviti; na nyũmba ya Ndaviti ĩkeethĩwa ta Ngai, o ta mũlaĩka wa Yeova mbee wamo.'),
('kam', 'ZEC', 12, 9, 'Na kũkeethĩwa mũthenya ũsu, ngamantha kwananga mbaĩ syonthe ila syĩũkĩa Yelusaleme.'),
('kam', 'ZEC', 12, 10, 'Na ngatulũĩla nyũmba ya Ndaviti, na ala matwĩe Yelusaleme, veva wa mumo na wa kwĩsũvana; na makanzisya ũla matonyie, na makamũmetea, o tondũ mũndũ ũmeteaa mwana wake e ũmwe, na makeethĩwa na woo nũndũ wake, ta ũmwe wĩthĩwaa na woo nũndũ wa ĩkithathi yake.'),
('kam', 'ZEC', 12, 11, 'Mũthenya ũsu kũkeethĩwa kĩmeto kĩnene Yelusaleme, ta kĩmeto kya Atatilimoni mwandanĩ wa Mekitoni.'),
('kam', 'ZEC', 12, 12, 'Na ĩ nthĩ ĩkameta, kĩla mũvĩa w’oka; mũvĩa wa nyũmba ya Ndaviti w’oka, na iveti syoo syoka; mũvĩa wa nyũmba ya Nathani w’oka, na iveti syoo syoka;'),
('kam', 'ZEC', 12, 13, 'mũvĩa wa nyũmba ya Livai w’oka, na iveti syoo syoka; mũvĩa wa Asimei w’oka, na iveti syoo syoka;'),
('kam', 'ZEC', 12, 14, 'mĩvĩa yonthe ĩla yatialile, kĩla mũvĩa w’oka, na iveti syoo syoka.'),
('kam', 'ZEC', 13, 1, 'Mũthenya ũsu nthongo ĩkeethĩwa yĩ mbingũĩe nyũmba ya Ndaviti na ala matwĩe Yelusaleme, ũndũ wa naĩ na ũndũ wa ũvuku.'),
('kam', 'ZEC', 13, 2, 'Na kũkeethĩwa mũthenya ũsu, easya ũu Yeova wa nguthu, ngaveta masyĩtwa ma mĩvw’anano kuma ĩ nthĩ, na ndĩkalilikanwa ĩngĩ; o na ĩngĩ athani na ũla veva mũvuku ngatuma mauma ĩ nthĩ.'),
('kam', 'ZEC', 13, 3, 'Na kũkeethĩwa, o yĩla ũmwe wĩkwatya kwathana, nĩvo ĩthe na nyinyia ala mamũsyaie makamwĩa, Ndwĩĩkala thayũ we; nũndũ nũkũneena movũngũ syĩtwanĩ ya Yeova; na ĩthe na nyinyia ala mamũsyaie makamũtonya mũkuthũ yĩla wĩĩthĩwa akyathana.'),
('kam', 'ZEC', 13, 4, 'Na kũkeethĩwa mũthenya ũsu, athani makasonoka kĩla ũmwe ũndũ wa woni wake, yĩla wĩathana; o na matikevw’ika ngũa ndasa yĩ w’ĩa makengane:'),
('kam', 'ZEC', 13, 5, 'ĩndĩ akasya, Ndi mwathani nyie, nyie nĩ mũĩmi; nũndũ natw’ĩwe ngombo kuma wana wakwa.'),
('kam', 'ZEC', 13, 6, 'Na ũmwe akamwĩa, Mawũkite aa me itaanĩ syaku nĩ ma kyaũ? Nĩvo wĩsũngĩa, Aa nĩ ala nokitĩwe nyũmbanĩ ya anyanyawa.'),
('kam', 'ZEC', 13, 7, 'Amũka, we ũvyũ, ĩũlũ wa mũĩthi wakwa, na ĩũlũ wa mũndũ ũla mũtindan’ya wakwa, easya ũu Yeova wa nguthu: mũkũne mũĩthi, na malondu makanyaĩĩka; ngathyũũĩa tũla tũnini kw’oko kwakwa.'),
('kam', 'ZEC', 13, 8, 'Na kũkeethĩwa, ĩ nthĩ yonthe, ilungu ilĩ syayo ikavetwa na kũkw’a, easya ũu Yeova; ĩndĩ kya katatũ kĩkatiwa nthĩnĩ wayo.'),
('kam', 'ZEC', 13, 9, 'Na kĩlungu kya katatũ ngakĩete mwakinĩ, na ngamathesya o tondũ vetha ũtheaw’a, na ngamatata o tondũ thaavu ũtatawa. Makeekaĩla syĩtwa yakwa, na ngamew’a: ngasya, Nĩ andũ makwa; namo makasya, Yeova nĩ Ngai wakwa.'),
('kam', 'ZEC', 14, 1, 'Sisya, mũthenya wa Yeova nĩwũkĩte, yĩla mũtavo waku ũkaaanw’a katĩ waku.'),
('kam', 'ZEC', 14, 2, 'Nũndũ ngoomban’ya mbaĩ syonthe ĩũlũ wa Yelusaleme syũkĩte; na ndũa ĩkooswa, na nyũmba ikatavwa mĩio, na aka makakindwa; na nyunzu ya ndũa ĩkatavwa, na ũtialo wa andũ ndũkavetwa ndũanĩ.'),
('kam', 'ZEC', 14, 3, 'Nĩvo Yeova ũkaumĩla, na kũkita na mbaĩ ĩsu, ta yĩla wokitie mũthenya wa kaũ.'),
('kam', 'ZEC', 14, 4, 'Na maũũ make makaũngama mũthenya ũsu ĩũlũ wa kĩla kĩĩma kya Mĩthata, kĩla kyelekele Yelusaleme ngalĩ ya wumĩlonĩ wa syũa: na kĩĩma kya Mĩthata kĩkaatũkanĩla katĩ kyelekele wumĩlonĩ wa syũa na kyelekele ũthũĩlonĩ wa syũa, na vakeethĩwa kyanda kĩnene mũno; na nyunzu ya kĩĩma ĩkathi yelekele ngalĩ ya ĩũlũ na nyunzu yakyo yelekele ngalĩ ya ĩtheo.'),
('kam', 'ZEC', 14, 5, 'Na mũkakĩĩla kyandanĩ kya iĩma syakwa; nũndũ kyanda kya iĩma kĩkavika Aseli; ĩĩ, mũkakĩa, o tondũ mwakĩie kĩtetemo kya nthĩ mĩthenya ya Usia mũsumbĩ wa Yuta; na Yeova Ngai wakwa akooka, na atheu onthe vamwe naku.'),
('kam', 'ZEC', 14, 6, 'Na kũkeethĩwa mũthenya ũsu, kũtikethĩwa kyeni; motisu makaoseea:'),
('kam', 'ZEC', 14, 7, 'ĩndĩ ũkeethĩwa mũthenya ũmwe ũla wĩsĩkĩwe nĩ Yeova; ti mũthenya, na ti ũtukũ; ĩndĩ kũkeethĩwa, atĩ wĩoo kũkeethĩwa kyeni.'),
('kam', 'ZEC', 14, 8, 'Na kũkeethĩwa mũthenya ũsu, atĩ manzĩ ma thayũ makaumĩla Yelusaleme; nyunzu yamo kwelekela ũkanganĩ wa wumĩlonĩ wa syũa, na nyunzu yamo kwelekela ũkanganĩ wa ũthũĩlonĩ wa syũa: kũkeethĩawa ũu ĩvinda ya syũa na ivĩnda ya mbevo.'),
('kam', 'ZEC', 14, 9, 'Na Yeova akethĩwa Mũsumbĩ ĩũlũ wa nthĩ yonthe: mũthenya ũsu Yeova akeethĩwa o ũmwe, na syĩtwa yake o yĩmwe.'),
('kam', 'ZEC', 14, 10, 'Ĩ nthĩ yonthe ĩkatw’ĩkĩthw’a ta Alava, kuma Ngeva kũvika Limoni ngalĩ ya ĩtheo ya Yelusaleme; nayo ĩkookĩlw’a, na kũtũa vandũ vayo, kuma mbingĩlonĩ ya Mbenyamini kũvika vandũ va mbingĩlo ya mbee, o kũvika mbingĩlo ya kĩkotonĩ, na kuma ũla mwako mũtũlu wa mũnyoolo wa Ananeli kũvika iangĩonĩ sya nzavivũ sya mũsumbĩ.'),
('kam', 'ZEC', 14, 11, 'Na andũ makatũa vo, na kũikethĩwa kĩumo ĩngĩ; ĩndĩ Yelusaleme ĩkatũa ĩte mũisyo.'),
('kam', 'ZEC', 14, 12, 'Na ũthĩn’yo ũla Yeova wĩkũna ngo syonthe sya andũ naw’o ila syũkitĩte na Yelusaleme ũkeethĩwa ũũ: mĩĩ yoo ĩkamomonyekaa o maũngyĩ na maũũ moo, na metho moo makaseekeaa me o maimanĩ mamo, na nĩmĩ syoo ikamomeonyekaa syĩ makanyw’anĩ moo.'),
('kam', 'ZEC', 14, 13, 'Na kũkeethĩwa mũthenya ũsu, kĩtuu kĩnene kuma kwa Yeova kĩkeethĩwa katĩ wamo; na makakwatana kĩla ũmwe kw’oko na mũtũi wake, na kw’oko kwake kũkookĩlĩĩla kw’oko kwa mũtũi wake.'),
('kam', 'ZEC', 14, 14, 'O na Yuta akokita ku Yelusaleme; na ũthwii wa mbaĩ syonthe ila ithyũlũlũkĩte kw’onthe ũkoombanw’a vamwe, thaavu, na vetha, na ngũa, mwingĩ mũno.'),
('kam', 'ZEC', 14, 15, 'Na now’o kũkeethĩwa ũthĩn’yo wa mbalasi, na wa nyũmbũ, na wa ngamĩle, na wa ĩng’oi, na wa nyamũ syonthe ĩla ĩkethĩwa myakonĩ ĩsu ya maeema, ũthĩn’yo ta ũsu.'),
('kam', 'ZEC', 14, 16, 'Na kũkeethĩwa, kĩla ũmwe ũtialĩte kwa mbaĩ syonthe ila syokĩlĩĩle Yelusaleme akambataa kĩla mwaka kũthaitha Mũsumbĩ, Yeova wa nguthu, na kũlilikana mboka ya malwanda.'),
('kam', 'ZEC', 14, 17, 'Na kũkeethĩwa, kana o ũla ũtakambataa Yelusaleme wa mĩvĩa yonthe ya nthĩ athaithe Mũsumbĩ, Yeova wa nguthu, kwoo kũtikethĩwa mbua.'),
('kam', 'ZEC', 14, 18, 'Na ethĩwa mũvĩa wa Misili ndũkambata, wũke, o na ndĩkaua kwoo; kũkeethĩwa ũthĩn’yo ũla Yeova wĩkũna i mbaĩ naw’o ila iteambata kũlilikana mboka ya malwanda.'),
('kam', 'ZEC', 14, 19, 'Ũu nĩw’o wĩĩthĩwa ũsilĩlo wa Misili, na ũsilĩlo wa mbaĩ syonthe ila iteambata kũlilikana mboka ya malwanda.'),
('kam', 'ZEC', 14, 20, 'Mũthenya ũsu kũkeethĩwa ndililinĩ sya mbalasi vaandĩkĩtwe, NTHEU KWA YEOVA; na mbisũ ila syĩ nyũmbanĩ ya Yeova ĩkeethĩwa itilyĩ ta mbakũli ila syĩ mbee wa kĩthembeo.'),
('kam', 'ZEC', 14, 21, 'Ĩĩ, kĩla mbisũ nthĩnĩ wa Yelusaleme na nthĩnĩ wa Yuta ĩkeethĩwa ntheu kwa Yeova wa nguthu; na onthe ala mathembaa makooka na makyosa, na kũtheũkĩsya nthĩnĩ wasyo: na mũthenya ũsu kũikethĩwa Mũkanaani nthĩnĩ wa nyũmba ya Yeova wa nguthu.'),
('kam', 'MAL', 1, 1, 'Ũito wa ndeto ya Yeova kwa Isilaeli kwa kanyw’a wa Malaki.'),
('kam', 'MAL', 1, 2, 'Nĩnĩmwendete, easya ũu Yeova. Ĩndĩ inyw’ĩ mwĩkũlya, Ũtwendete ũndũnĩ wĩva? Esau ndaĩ mwana‐a‐inyia wa Yakovo? Ekũlya ũu Yeova: ĩndĩ nĩnamwendie Yakovo;'),
('kam', 'MAL', 1, 3, 'ĩndĩ Esau nĩnamũmenie, na natw’ĩkĩthya iĩma syake nthei, na nĩnanengie mbĩwa sya weũnĩ ũtiĩwa wake.'),
('kam', 'MAL', 1, 4, 'Vala Etomu ũnũkwasya, Twĩ avalũkye nthĩ, ĩndĩ nĩtũũsyoka na tũkyaka maanzonĩ; Yeova wa nguthu easya atĩĩ, Makaaka, ĩndĩ ngang’uthũlanga; na andũ makametaa Mũvaka wa ũthũku, na Andũ ala Yeova ũmathatĩe tene na tene.'),
('kam', 'MAL', 1, 5, 'Na metho menyu makoona, na mũkasya, Yeova nanenevw’e mũkĩlo wa mũvaka wa Isilaeli.'),
('kam', 'MAL', 1, 6, 'Mwana ataĩaa ĩthe, na mũthũkũmi vwana wake: ethĩwa ĩndĩ nyie nĩ ĩthe, kũtaĩwa kwakwa kũĩva? Na ethĩwa nyie nĩ vwana, kũkĩwa kwakwa kũĩva? Ĩnyw’ĩ athembi ala mũvũthasya syĩtwa yakwa, emũkũlya ũu Yeova wa nguthu. Na inyw’ĩ mwĩkũlya, Tũvũthĩtye syĩtwa yaku ũndũnĩ wĩva?'),
('kam', 'MAL', 1, 7, 'Nĩmũthembaa imũtũ mbuku kĩthembeonĩ kyakwa. Na inyw’ĩ mwĩkũlya, Tũkũvukĩtye ũndũnĩ wĩva? Nũndũ mwĩasya, Mesa ya Yeova nĩ mana.'),
('kam', 'MAL', 1, 8, 'Na yĩla mũũthemba ĩla ĩte metho, ti ũthũku! Na yĩla mũkũthemba ĩnĩkũthua na ĩla ndwau, ti ũthũku! Kwamũnenge ngavana waku yu; akendeew’a nue? Kana akakwĩtĩkĩla we? Ekũlya ũu Yeova wa nguthu.'),
('kam', 'MAL', 1, 9, 'Na yu, nĩngũmwĩsũva, mũvoye ũseo kwa Ngai, nĩ kana atonye kũtwĩka nesa: ũũ wĩthĩĩtwe kwondũ wenyu: akamwĩtĩkĩla inyw’ĩ o na ũmwe? Ekũlya ũu Yeova wa nguthu.'),
('kam', 'MAL', 1, 10, 'A! Kethĩwa ve ũmwe katĩ wenyu ũvinga mĩomo, nĩ kana mũikatonye kũvuva mwaki ĩũlũ wa kĩthembeo kyakwa mana! Ndikwendeew’a nĩ inyw’ĩ, o na ndiketĩkĩla nthembo i kw’okonĩ kwenyu, easya ũu Yeova wa nguthu.'),
('kam', 'MAL', 1, 11, 'Nũndũ kuma syũa yauma o na kũvika yathũa syĩtwa yakwa yĩthĩwaa ĩnene katĩ wa Andũ‐ma‐mbaĩ‐ingĩ; na kĩla vandũ ũvani na nthembo ntheu nithembeawa syĩtwa yakwa: nũndũ syĩtwa yakwa yĩthĩwaa ĩnene katĩ wa Andũ‐ma‐mbaĩ‐ingĩ, easya ũu Yeova wa nguthu.'),
('kam', 'MAL', 1, 12, 'Ĩndĩ nĩmũyĩvukasya, nũndũ mwĩasya, Mesa ya Yeova nĩvukĩtw’e, na ũsyao wayo, o na lĩu wayo, nĩ mana.'),
('kam', 'MAL', 1, 13, 'Na ĩngĩ mwĩasya, Sisyai, ũndũ ĩan’ya mĩnoo! Na nĩmũmĩtimbĩte, easya ũu Yeova wa nguthu; na inyw’ĩ mũetete ĩla yoosiwe na ũng’endu, na ĩla ĩnĩkũthua, na ĩla ndwau; o ta ũu nĩmũetae ĩla nthembo: nĩnaĩle kũmyosa mokonĩ menyu? Ekũlya ũu Yeova.'),
('kam', 'MAL', 1, 14, 'Ĩndĩ mũkengani naumanĩwe, ũla wĩavaa, na aithembea Mwĩaĩi ĩmwe yĩ na kĩema, e na nũme ndĩthyanĩ yake ya mbũi na malondu; nũndũ ninyie Mũsumbĩ mũnene, na syĩtwa yakwa nĩ ya ũkĩwa mũno katĩ wa Andũ‐ma‐mbaĩ‐ingĩ, easya ũu Yeova wa nguthu.'),
('kam', 'MAL', 2, 1, 'Na yu, inyw’ĩ athembi, mwĩao ũũ nĩ kwondũ wenyu.'),
('kam', 'MAL', 2, 2, 'Mweethĩwa mũtikwĩw’a, na mweethĩwa mũtikwĩkĩa ũu ngoonĩ, mũnengae syĩtwa yakwa ndaĩa, nĩvo ĩndĩ nĩmũetee kĩumo, na ngamaumanĩa moathimo menyu, easya ũu Yeova wa nguthu; ĩĩ, nĩnĩminĩte kũmaumanĩa, nĩkwĩthĩwa mũtiwĩkĩaa ngoonĩ.'),
('kam', 'MAL', 2, 3, 'Sisyai, ngookan’ya ũsyao wenyu, na ngavakanga mũyoo mothyũnĩ menyu, o mũyoo wa nthembo syenyu; nenyu mũkavetanĩw’a naw’o.'),
('kam', 'MAL', 2, 4, 'Na mũkamanya kana nĩnaetie mwĩao ũũ kwenyu, nĩ kana ũtianĩo wakwa wĩthĩwe na Livai, easya ũu Yeova wa nguthu.'),
('kam', 'MAL', 2, 5, 'Ũtianĩo wakwa waĩ nake wa thayũ na mũuo; na nainenganie kwake nĩ kana akĩe; nake nĩwangĩaa, na kũkĩaa syĩtwa yakwa.'),
('kam', 'MAL', 2, 6, 'Mwĩao wa w’o waĩ kanyw’anĩ wake, na ũla ũte ũlũngalu ndwaaoneka ilomonĩ syake; aendanasya nakwa mũuonĩ na ũlũngalunĩ, na akĩalyũla aingĩ kuma ũthũkunĩ.'),
('kam', 'MAL', 2, 7, 'Nũndũ ilomo sya mũthembi nĩsyaĩle ũsũvĩaa ũmanyi, na andũ nĩmaĩle kũmanthaa mwĩao kanyw’anĩ wake; nũndũ nĩ mũtũmwa wa Yeova wa nguthu.'),
('kam', 'MAL', 2, 8, 'Ĩndĩ nĩmweelelũkile kuma nzĩanĩ; nĩmũtumĩte aingĩ malulutĩka mĩaonĩ; nĩmũthũkĩtye ũtianĩo wa Livai, easya ũu Yeova wa nguthu.'),
('kam', 'MAL', 2, 9, 'Kwondũ wa ũu nyie nakwa namũtwie ma mana na mwĩ ĩtheo mbee wa andũ onthe, o kwĩanana na ũndũ mũtaakwata nzĩa syakwa, ĩndĩ mweethĩwa na wendeesyo wa andũ mĩaonĩ.'),
('kam', 'MAL', 2, 10, 'Tũi ma ĩthe ũmwe ithyonthe? Ti o Ngai ũmwe ũ watũmbie? Twĩĩkana ũseleke nĩkĩ kĩla mũndũ na mwana‐a‐ĩthe, tũkĩvukya ũtianĩo wa aaĩthe maitũ?'),
('kam', 'MAL', 2, 11, 'Yuta nĩwĩkĩte ũseleke, na ũthatyo nĩwĩkĩtwe nthĩnĩ wa Isilaeli na Yelusaleme; nũndũ Yuta nũvukĩtye ũtheu wa Yeova ũla wendaa, na nũtwaĩte mwĩĩtu wa ngai ngeni.'),
('kam', 'MAL', 2, 12, 'Kwa mũndũ ũla wĩkaa ũu, Yeova akaveta kuma maeemanĩ ma Yakovo ũla wĩkalaa asalukĩtye na ũla ũsũngĩaa, na ũla ũthembeaa Yeova wa nguthu nthembo.'),
('kam', 'MAL', 2, 13, 'Na nĩmwĩkaa ũũ ĩngĩ: nĩmũvw’ĩkaa kĩthembeo kya Yeova na methoi, na kũĩa, na kũvevũũka, kwondũ wa ũu ndetĩkĩlaa nthembo nongi, o na ndamyosaa na kwenda kũseo kw’okonĩ kwenyu.'),
('kam', 'MAL', 2, 14, 'Ĩndĩ inyw’ĩ mwĩkũlya. Nĩ ũndũ wa kĩ? Nĩkwĩthĩwa Yeova nĩwĩthĩwaa ngũsĩ katĩ waku na mũka waku wa ũthoo, ũla ũmwĩkĩte ũseleke, o na kau nĩwatindaa nake, na nĩ mũka wa ũtianĩo waku.'),
('kam', 'MAL', 2, 15, 'Na ndaaũmba ũmwe, o na kau aĩ na ũtialo wa Veva? Na nĩ ũmwe nĩkĩ? Amanthaa ũsyao wa ũmũkĩaa Ngai. Kwondũ wa ũu sũvĩa veva waku, na mũndũ o na wĩva ndakeke mũka wake wa ũthoo ũseleke.'),
('kam', 'MAL', 2, 16, 'Nũndũ nĩnĩmenaa ũndũ ũsu wa mũleano, easya ũu Yeova, Ngai wa Isilaeli, o na ũla ũvw’ĩkaa ngũa yake ũng’endu, easya ũu Yeova wa nguthu: kwondũ wa ũu sũvĩai veva wenyu, nĩ kana mũikeke ũseleke.'),
('kam', 'MAL', 2, 17, 'Nĩmũnoetye Yeova na ndeto syenyu. Ĩndĩ mwĩkũlya, Tũmũnoetye ũndũnĩ wĩva? Nũndũ mwĩasya, Kĩla ũmwe wĩkaa ũthũku nĩ mũseo methonĩ ma Yeova, na nĩwendeeaw’a nĩmo; kana aĩva Ngai wĩ ũsili wa katĩ?'),
('kam', 'MAL', 3, 1, 'Sisyai, nĩngũtũma mũtũmwa wakwa, na akaseũvya nzĩa mbee wakwa: na Mwĩaĩi, ũla mũmanthaa, akooka na kĩthũlũmũko ĩkalũnĩ yake; na mũtũmwa wa ũtianĩo, ũla mwendaa, sisyai, nĩwũkĩte, easya ũu Yeova wa nguthu.'),
('kam', 'MAL', 3, 2, 'Ĩndĩ nũũ ũtonya kũmĩĩsya mũthenya wa kũka kwake? Na nũũ wĩũngama yĩla wĩumĩla? Nũndũ ailyĩ mwaki wa mũui wa vetha, na ailyĩ savunĩ wa mũthambya wa ngũa:'),
('kam', 'MAL', 3, 3, 'na akekala nthĩ ta mũui na mũthesya wa vetha, na akathesya ana ma Livai, na kũmathesya ta thaavu na vetha; namo makathembea Yeova nthembo na ũlũngalu.'),
('kam', 'MAL', 3, 4, 'Nĩvo ĩndĩ nthembo ya Yuta na Yelusaleme yĩendeesya Yeova, o ta mĩthenya ya tene, na ta myaka ya tene mũno.'),
('kam', 'MAL', 3, 5, 'Na ngooka vakuvĩ nenyu kũsilĩla; na ngeethĩwa ngũsĩ yĩ mĩtũkĩ kwa aoi, na kwa ilaalai, na kwa ala mevĩtaa ũvũngũ, na kwa ala mavinyĩĩaa mũthũkũmi ũndũ wa ĩtuvi yake, na aka ndiwa, na ala makw’ĩĩwe nĩ aaĩthe, na kwa ala melelũkasya sila wa mwĩkali wa ũeninĩ ndakone kĩla kyake, mateũngĩa, easya ũu Yeova wa nguthu.'),
('kam', 'MAL', 3, 6, 'Nũndũ nyie, Yeova, ndialyũkaa; kwondũ wa ũu inyw’ĩ, inyw’ĩ ana ma Yakovo, mũiminawa.'),
('kam', 'MAL', 3, 7, 'Kuma mĩthenya ya aaĩthe menyu nĩmweelelũkile kuma motw’ĩonĩ makwa, na mũiaamasũvĩa. Nzyokeai, nakwa ngamũsyokea, easya ũu Yeova wa nguthu. Ĩndĩ inyw’ĩ mwĩkũlya, Twĩsyoka ũndũnĩ wĩva?'),
('kam', 'MAL', 3, 8, 'Mũndũ akamũyĩa Ngai? Ĩndĩ nĩmũmbũyaa. Ĩndĩ mwĩkũlya, Tũkũyĩe ũndũnĩ wĩva? Nĩ ilungunĩ sya ĩkũmi na nthembo.'),
('kam', 'MAL', 3, 9, 'Nĩmũumanĩwe; nũndũ nĩmũmbũyaa, o mbaĩ ĩno nima.'),
('kam', 'MAL', 3, 10, 'Etei kĩlungu kya ĩkũmi kyonthe ĩkũmbĩnĩ, nĩ kana vethĩwe lĩu nyũmbanĩ yakwa, na ndatai ũndũnĩ ũũ yu, ethĩwa ndimũvingũĩa mbũthi sya ĩtunĩ, na kũmũtulũĩla ũathimo, mũvaka vae ũthei wa kũwĩanĩa, easya ũu Yeova wa nguthu.'),
('kam', 'MAL', 3, 11, 'Na ngamũkan’ya mwanangi nũndũ wenyu, na ndakananga mosyao ma nthĩ yenyu; o na mĩsavivũ yenyu ndĩketĩkya ũsyao wayo mũũndanĩ ũtanavika, easya ũu Yeova wa nguthu.'),
('kam', 'MAL', 3, 12, 'Na mbaĩ syonthe ikamwĩtaa atanu; nũndũ mũkeethĩwa nthĩ ya kwendeesya, easya ũu Yeova wa nguthu.'),
('kam', 'MAL', 3, 13, 'Ndeto syenyu syĩkalĩte syĩ nyũmũ ĩũlũ wakwa, easya ũu Yeova. Ĩndĩ inyw’ĩ mwĩkũlya, Tũkũneenee ata?'),
('kam', 'MAL', 3, 14, 'Inyw’ĩ mwaĩtye, No mana kũthũkũma Ngai; ũndũ tũlũmĩtye wĩaĩo wake, ũndũ tũendaa twĩ na woo mbee wa Yeova wa nguthu, ũunĩko nĩ mwaũ?'),
('kam', 'MAL', 3, 15, 'Na yu twĩmeta ekathĩĩi atanu; ĩĩ, o ala mekaa ũthũku nĩmakawa; ĩĩ, nĩmatataa Ngai na makĩvonoka.'),
('kam', 'MAL', 3, 16, 'Nĩvo ĩndĩ ala makĩaa Yeova maneenanisye ene kwa ene; na Yeova eethukĩĩsya, na eew’a, na ĩvuku ya ũlilikan’yo yaandĩkwa e vo, nũndũ wa ala makĩaa Yeova, na ala malilikanaa syĩtwa yake.'),
('kam', 'MAL', 3, 17, 'Na makeethĩwa makwa, easya ũu Yeova wa nguthu, o makwa mwene ki, mũthenya ũla nĩtw’a; na ngamew’ĩa tei, o tondũ mũndũ wĩw’ĩaa mwana wake mwene tei ũla ũmũthũkũmaa.'),
('kam', 'MAL', 3, 18, 'Nĩvo ĩndĩ mũkasyoka na kũvathũkan’ya katĩ wa ala alũngalu na ala athũku, ũla ũthũkũmaa Ngai na ũla ũtamũthũkũmaa.'),
('kam', 'MAL', 4, 1, 'Nundũ, sisyai, mũthenya nĩwũkĩte, wakanĩte ta iko ĩnene; na ekathĩĩi onthe, na onthe ala mekaa ũthũku, makeethĩwa ũa; na mũthenya ũla wũkĩte ũkamavĩvya vyũ, mũvaka ndũkamatialya mũi o na ũvonge, easya ũu Yeova wa nguthu.'),
('kam', 'MAL', 4, 2, 'Ĩndĩ kwa inyw’ĩ ala mũkĩaa syĩtwa yakwa syũa ya ũlũngalu yĩkauma yĩ na wovosyo nthwaunĩ syayo; nenyu mũkaumaala, na kũtũva ta tũsaũ twa kĩtũũnĩ.'),
('kam', 'MAL', 4, 3, 'Na mũkakinyangĩa ala athũku nthĩ; nũndũ makeethĩwa mũu ungu wa nyaĩĩ syenyu mũthenya ũla nĩtw’a, easya ũu Yeova wa nguthu.'),
('kam', 'MAL', 4, 4, 'Lilikanai, inyw’ĩ, mĩao ya Mose mũthũkũmi wakwa, ũla namwĩaĩe ku Olevu nũndũ wa Isilaeli onthe, o myamũlo na motw’ĩo.'),
('kam', 'MAL', 4, 5, 'Sisyai, ngatũma mwathani Eliya kwenyu mbee wa mũthenya mũnene na wa ũtĩsya wa Yeova ũtanoka.'),
('kam', 'MAL', 4, 6, 'Na akathyũũa ngoo sya aaĩthe syelekele syana, na ngoo sya syana syelekele aaĩthe masyo; ndikese kũka na kũmĩkũna nthĩ na kĩumo.'),
('kam', 'MAT', 1, 1, 'Ĩvuku ya mosyaanĩo ma Yesũ Klĩsto, mwana wa Ndaviti, mwana wa Avalaamu.'),
('kam', 'MAT', 1, 2, 'Avalaamu asyaie Isaka; na Isaka asyaa Yakovo; na Yakovo asyaa Yuta na ana‐a‐ĩthe make;'),
('kam', 'MAT', 1, 3, 'na Yuta asyaĩwa Velesi na Nzela nĩ Tamalu; na Velesi asyaa Esiloni; na Esiloni asyaa Lamu;'),
('kam', 'MAT', 1, 4, 'na Lamu asyaa Aminatavu; na Aminatavu asyaa Nasoni; na Nasoni asyaa Salumoni;'),
('kam', 'MAT', 1, 5, 'na Salumoni asyaĩwa Mboasi nĩ Laavi; na Mboasi asyaĩwa Oveti nĩ Luthi; na Oveti asyaa Yese;'),
('kam', 'MAT', 1, 6, 'na Yese asyaa mũsumbĩ Ndaviti. Na Ndaviti asyaĩwa Solomoni nĩ mũka ũla waĩ wa Ulia;'),
('kam', 'MAT', 1, 7, 'na Solomoni asyaa Leovoamu; na Leovoamu asyaa Aviya; na Aviya asyaa Asa;'),
('kam', 'MAT', 1, 8, 'na Asa asyaa Yeosavati; na Yeosavati asyaa Yolamu; na Yolamu asyaa Usia;'),
('kam', 'MAT', 1, 9, 'na Usia asyaa Yothamu; na Yothamu asyaa Aasu; na Aasu asyaa Esekia;'),
('kam', 'MAT', 1, 10, 'na Esekia asyaa Manase; na Manase asyaa Amoni; na Amoni asyaa Yosia;'),
('kam', 'MAT', 1, 11, 'na Yosia asyaa Yekonia na ana‐a‐inyia make, ĩvinda ya kũthamĩĩw’a Mbaviloni.'),
('kam', 'MAT', 1, 12, 'Na ĩtina wa kũthamĩĩw’a Mbaviloni, Yekonia asyaa Sealitieli; na Sealitieli asyaa Nzeluvaveli;'),
('kam', 'MAT', 1, 13, 'na Nzeluvaveli asyaa Aviuti; na Aviuti asyaa Eliakimu; na Eliakimu asyaa Asoli;'),
('kam', 'MAT', 1, 14, 'na Asoli asyaa Satoki; na Satoki asyaa Akimu; na Akimu asyaa Eliuti;'),
('kam', 'MAT', 1, 15, 'na Eliuti asyaa Eleasali; na Eleasali asyaa Mathani; na Mathani asyaa Yakovo;'),
('kam', 'MAT', 1, 16, 'na Yakovo asyaa Yosevu mũũme wa Meli ũla wasyaie Yesũ, nake nĩwĩtawa Klĩsto.'),
('kam', 'MAT', 1, 17, 'Na ĩndĩ nzyawa syonthe kuma Avalaamu kũvika Ndaviti nĩ nzyawa ĩkũmi na inya; na kuma Ndaviti kũvika kũla kũthamĩĩw’a Mbaviloni nĩ nzyawa ĩkũmi na inya; na kuma kũthamĩĩw’a Mbaviloni kũvika Klĩsto nĩ nzyawa ĩkũmi na inya.'),
('kam', 'MAT', 1, 18, 'Na kũsyawa kwa Yesũ Klĩsto kwailyĩ ũũ: Yĩla Meli inyia wake wevaĩtw’e nĩ Yosevu, matambĩte kũtwaana, ooneka e na ĩvu ya Veva Mũtheu.'),
('kam', 'MAT', 1, 19, 'Na Yosevu mũũme wake, nĩkwĩthĩwa aĩ mũndũ mũlũngalu, na ndaenda kũmũsonokya mbee wa andũ, enda kũmũeka kĩmbithĩ.'),
('kam', 'MAT', 1, 20, 'Ĩndĩ akĩsũanĩa maũndũ asu, sisya, mũlaĩka wa Mwĩaĩi amumĩlĩla ndotonĩ, akyasya, Yosevu, we mwana wa Ndaviti, ndũkakĩe kũtwaa Meli mũka waku; nũndũ kũitava kwake nĩ kwa Veva Mũtheu.'),
('kam', 'MAT', 1, 21, 'Nake akasyaa kavĩsĩ; naku ũkaketa syĩtwa yako YESŨ; nũndũ nĩwe ũkatangĩĩa andũ make kuma naĩnĩ syoo.'),
('kam', 'MAT', 1, 22, 'Na ũu w’onthe ũtw’ĩkĩte, nĩ kana wĩanĩw’e ũla waneeniwe nĩ Mwĩaĩi na kanyw’a wa mwathani, akyasya,'),
('kam', 'MAT', 1, 23, 'Sisya, mwĩĩtu akethĩwa e ĩvu, na akasyaa kavĩsĩ, Nako syĩtwa yako makaketa Imanueli; na ũalyũlo wayo nĩ, Ngai vamwe naitũ.'),
('kam', 'MAT', 1, 24, 'Na Yosevu ookĩla kuma toonĩ, na eeka o tondũ wĩaĩwe nĩ mũlaĩka wa Mwĩaĩi, na atwaa mũka wake;'),
('kam', 'MAT', 1, 25, 'o na ndaamũmanya mũvaka asyaa kavĩsĩ: nake aketa syĩtwa yako YESŨ.'),
('kam', 'MAT', 2, 1, 'Na Yesũ asaĩwe Mbethelemu nthĩ ya Yutia matukũ ma mũsumbĩ Elote, sisya, andũ oĩ kuma wumĩlonĩ wa syũa mooka Yelusaleme, makyasya,'),
('kam', 'MAT', 2, 2, 'Aĩva ũla wasyaiwe Mũsumbĩ wa Ayuti? Nũndũ nĩtwoonie ndata yake wumĩlonĩ wa syũa, na nĩtwooka kũmũthaitha.'),
('kam', 'MAT', 2, 3, 'Na ũla mũsumbĩ Elote eew’a ũu, aũũya, na Yelusaleme yonthe vamwe nake.'),
('kam', 'MAT', 2, 4, 'Na oomban’ya athembi anene onthe na aandĩki ma andũ, amakũlya vala Klĩsto wĩsyaĩwa.'),
('kam', 'MAT', 2, 5, 'Nao mamwĩa, Nthĩnĩ wa Mbethelemu nthĩ ya Yutia: nũndũ nĩw’o kũandĩkĩtwe nĩ mwathani,'),
('kam', 'MAT', 2, 6, 'Naku Mbethelemu, nthĩ ya Yuta, Ndwĩ mũnini nongi katĩ wa atongoi ma Yuta: Nũndũ kwaku we kũkauma ngavana, Ũla ũkaĩthya andũ makwa Isilaeli.'),
('kam', 'MAT', 2, 7, 'Nĩvo ĩndĩ Elote wametie ala andũ oĩ kĩmbithĩ, na amanyĩthw’a nĩo vyũ ĩvinda yĩla ndata ĩsu yonekie.'),
('kam', 'MAT', 2, 8, 'Na amatũma ku Mbethelemu, na asya, Endai mũkekuũe vyũ ũndũ wa kala kana; na mwakona mũndetee ũvoo, nĩ kana nyie nakwa nĩthi nĩkathaithe.'),
('kam', 'MAT', 2, 9, 'Nao, meew’a ndeto sya mũsumbĩ, makwata nzĩa mathi; na sisya, ndata ĩla moonie wumĩlonĩ wa syũa yamatongoesya, mũvaka yooka yalũma ĩũlũ wa vala ve kala kana.'),
('kam', 'MAT', 2, 10, 'Na moona ĩla ndata, matana ũtanu mũnene mũno.'),
('kam', 'MAT', 2, 11, 'Na malika nyũmba nthĩnĩ na moona kana vamwe na Meli inyia wako, na mavalũka nthĩ na makathaitha; na mathasya mĩio yoo yĩ vata mũno makanenga mĩthĩnzĩo, thaavu na ũvumba na manemane.'),
('kam', 'MAT', 2, 12, 'Nao mooniw’e nĩ Ngai ndotonĩ maikamũalũkĩle Elote, mathi kwoo na nzĩa ĩngĩ.'),
('kam', 'MAT', 2, 13, 'Na asu mathi, sisya, mũlaĩka wa Mwĩaĩi amumĩlĩla Yosevu ndotonĩ, akyasya, Ũkĩla wose kala kana na inyia wako, noikĩa ũthi Misili, ũkekale kw’o mũvaka yĩla ngaũtavya: nũndũ Elote nũkilĩlye kũmantha kala kana akoae.'),
('kam', 'MAT', 2, 14, 'Nake ookĩla oosa kala kana na inyia wako ũtukũ, athi kũvika Misili;'),
('kam', 'MAT', 2, 15, 'na ekala kw’o mũvaka Elote akw’a: nĩ kana kwĩanĩw’e ũla waneeniwe nĩ Mwĩaĩi na kanyw’a wa mwathani, akyasya, Kuma Misili nĩnamwĩtie mwana wakwa.'),
('kam', 'MAT', 2, 16, 'Na ĩndĩ Elote, oona kana nũnavũthiw’e nĩ ala andũ oĩ, athata mũno, na atũma andũ moae tũvĩsĩ tw’onthe tũla twaĩ Mbethelemu, na ndee syonthe syayo, tũla tũvikĩtye myaka ĩlĩ na ĩtina wa vau, kwĩanana na ĩvinda yĩla wamanyĩthiw’e vyũ nĩ ala andũ oĩ.'),
('kam', 'MAT', 2, 17, 'Nĩvo ĩndĩ weanĩiw’e ũla waneeniwe nĩ mwathani Yelemia, akyasya,'),
('kam', 'MAT', 2, 18, 'Wasya nĩweew’ĩkie Lama, Kĩĩo na kĩmeto kĩnene, Lakeli akĩĩĩa syana syake; Na ndetĩkĩla kũkiakiw’a, nĩkwĩthĩwa itivaĩ.'),
('kam', 'MAT', 2, 19, 'Ĩndĩ Elote akw’a, sisya, mũlaĩka wa Mwĩaĩi amumĩlĩla Yosevu ndotonĩ na ku Misili, akyasya,'),
('kam', 'MAT', 2, 20, 'Ũkĩla wose kana na inyia wako, ũthi nthĩ ya Isilaeli: nũndũ nĩ akw’ũ ala mamanthaa thayũ wa kana.'),
('kam', 'MAT', 2, 21, 'Nake ookĩla, oosa kana na inyia wako, na athi nthĩ ya Isilaeli.'),
('kam', 'MAT', 2, 22, 'Ĩndĩ eew’a kana Alikelau nũsumbĩkĩte ĩũlũ wa Yutia vandũ va Elote ĩthe wake, akĩa kũthi kw’o; na oonw’a nĩ Ngai ndotonĩ, eelelũka athi ngalĩ sya Kalilii,'),
('kam', 'MAT', 2, 23, 'na athi atũa ndũanĩ yĩtawa Nasaleti; nĩ kana kwĩanĩw’e ũla waneeniwe nĩ athani, kana we aketwa Mũnasaleti.'),
('kam', 'MAT', 3, 1, 'Na matukũ asu Yoana Mũvatisi aumĩla, akĩtavan’ya weũnĩ wa Yutia, akyasya,'),
('kam', 'MAT', 3, 2, 'Alyũlai ngoo; nũndũ ũsumbĩ wa ĩtu nĩ mũthengeeu.'),
('kam', 'MAT', 3, 3, 'Nĩkwĩthĩwa ũũ nĩwe ũla wawetiwe nĩ mwathani Isaia, akyasya, Wasya wa mũndũ akĩneena mũno weũnĩ, Seũvyai nzĩa ya Mwĩaĩi, Lũngalyai moendelo make.'),
('kam', 'MAT', 3, 4, 'Na Yoana mwene aĩ na ngũa yake ya w’ĩa wa ngamĩle, na mũkwa kĩnyunyunĩ kyake; na kya ũya kyake kyaĩ ngie na ũkĩ wa nzũkĩ wa kĩthekanĩ.'),
('kam', 'MAT', 3, 5, 'Nĩvo Yelusaleme, na Yutia yonthe, na nthĩ yonthe ĩthyũlũlũkĩte Yolotani maendie vala ũĩ;'),
('kam', 'MAT', 3, 6, 'na mavatisĩwa nĩwe ũsĩnĩ wa Yolotani, makyumbũla naĩ syoo.'),
('kam', 'MAT', 3, 7, 'Ĩndĩ oona aingĩ ma Avalisi na Asatukaĩ makyũka ũvatisonĩ wake, amea, Inwy’ĩ ũsyao wa nzoka mbai, nũũ ũmwonetye kũkĩa ũthatu ũla wũkĩte?'),
('kam', 'MAT', 3, 8, 'Syaai ĩndĩ ũsyao ũla waĩle ũalyũlo wa ngoo:'),
('kam', 'MAT', 3, 9, 'na mũikalilikane kwasya nthĩnĩ wenyu, Twĩ na asa waitũ Avalaamu: nũndũ nĩngũmũtavya, kana Ngai nũtonya kũmũkĩlĩlya Avalaamu syana mavianĩ aa.'),
('kam', 'MAT', 3, 10, 'O na yu ĩthoka nĩyiĩtwe matinanĩ ma mĩtĩ: kĩla mũtĩ ĩndĩno ũtasyaaa ũsyao mũseo nũtemawa, na kwĩkw’a mwakinĩ.'),
('kam', 'MAT', 3, 11, 'Nĩ w’o nyie nĩmũvatisaa na manzĩ kũvikĩa ũalyũlo wa ngoo: ĩndĩ ũla wũkĩte ĩtina wakwa e na vinya kwĩ nyie, o na ndyĩanĩwe nĩ ũkua iatũ syake: ũsu akamũvatisaa na Veva Mũtheu na mwaki:'),
('kam', 'MAT', 3, 12, 'na kĩũlũkya kyake kĩ kw’okonĩ kwake, nake akathesya vyũ kĩvũĩo kyake; na akoomban’ya nganũ yake ĩkũmbĩnĩ, ĩndĩ wewa akavĩvya na mwaki ũtavoeka.'),
('kam', 'MAT', 3, 13, 'Nĩvo ĩndĩ Yesũ waumie Kalilii athi Yolotani kwa Yoana, nĩ kana avatiswe nĩwe.'),
('kam', 'MAT', 3, 14, 'Ĩndĩ Yoana enda kũmũsiĩĩa, akyasya, Nyie nĩ na vata wa kũvatiswa nue, naku wĩũka kwakwa?'),
('kam', 'MAT', 3, 15, 'Ĩndĩ Yesũ amũsũngĩa, amwĩa, Ĩtikĩla ũu yu, nũndũ nĩw’o ũtwaĩle kwĩanĩsya ũlũngalu w’onthe. Na ĩndĩ eetĩkĩla.'),
('kam', 'MAT', 3, 16, 'Na Yesũ, avatiswa, ambata oyu kuma manzĩnĩ: na sisya, matu mamũvingũkĩa, na oona Veva wa Ngai aitheea ta ĩvũĩ, na aimũvũĩla;'),
('kam', 'MAT', 3, 17, 'na sisya, wasya wauma matunĩ, ũkyasya, Ũũ nĩwe Mwana wakwa mwendwa, ũla nendeeaw’a nĩwe.'),
('kam', 'MAT', 4, 1, 'Nĩvo Yesũ watongoew’e nĩ Veva weũnĩ nĩ kana atatwe nĩ ndevili.'),
('kam', 'MAT', 4, 2, 'Na atĩĩa ũya mĩthenya mĩongo ĩna na matukũ mĩongo ĩna, ĩtina eew’a nzaa.'),
('kam', 'MAT', 4, 3, 'Na ũla mũtati ooka amwĩa, Ethĩwa nue Mwana wa Ngai, ĩae kana mavia aa matw’ĩke kĩmũtũ.'),
('kam', 'MAT', 4, 4, 'Ĩndĩ asũngĩa, asya, Nĩkũandĩkĩtwe, Mũndũ ndekalaa thayũ kwondũ wa kĩmũtũ kyoka, ĩndĩ kwondũ wa kĩla ndeto yumaa kanyw’anĩ wa Ngai.'),
('kam', 'MAT', 4, 5, 'Na ĩndĩ ndevili amũtwaa nthĩnĩ wa ĩla ndũa ntheu; na amwĩkalya mũthyanĩ wa ĩkalũ,'),
('kam', 'MAT', 4, 6, 'na amwĩa, Ethĩwa nue Mwana wa Ngai, ĩyĩkye nthĩ: nũndũ nĩkũandĩkĩtwe, Akeeaĩa alaĩka make ũndũ waku: na ĩngĩ, Makakũkĩlya mokonĩ moo, Ndũkese kũtulw’a kũũ kwaku nĩ ĩvia.'),
('kam', 'MAT', 4, 7, 'Yesũ amwĩa, Na ĩngĩ nĩkũandĩkitwe, Ndũkamũtate Mwĩaĩi Ngai waku.'),
('kam', 'MAT', 4, 8, 'Na ĩngĩ, ndevili amũtwaa kĩĩmanĩ kĩtũlu mũno, na amwon’ya mosumbĩ onthe ma nthĩ, na ndaĩa syamo;'),
('kam', 'MAT', 4, 9, 'na amwĩa, Syĩndũ ii syonthe nĩngũũnenga, ethĩwa nũũndulĩlya ndu na kũnthaitha.'),
('kam', 'MAT', 4, 10, 'Nĩvo ĩndĩ Yesũ wamwĩie, Thi, Satani: nũndũ nĩkũandĩkĩtwe, Mũthaithae Mwĩaĩi Ngai waku, na mũthũkũmae we, e weka.'),
('kam', 'MAT', 4, 11, 'Na ĩndĩ ndevili amũtia, na sisya, alaĩka mooka mamũthũkũma.'),
('kam', 'MAT', 4, 12, 'Na Yesũ eew’a kana Yoana ekĩĩtwe kolokolonĩ, aenda Kalilii;'),
('kam', 'MAT', 4, 13, 'na auma Nasaleti, athi na atũa Kavelinaumi, ĩla yĩ ũtee wa ũkanga, mĩvakanĩ ya Nzevuluni na Navitali:'),
('kam', 'MAT', 4, 14, 'nĩ kana kwĩanĩw’e ũla waneeniwe nĩ mwathani Isaia, akyasya,'),
('kam', 'MAT', 4, 15, 'Nthĩ ya Nzevuluni na nthĩ ya Navitali, Kwelekela ũkanganĩ, mbee wa Yolotani, Kalilii ya Andũ‐ma‐mbaĩ‐ingĩ,'),
('kam', 'MAT', 4, 16, 'Andũ ala mekalile kĩvindunĩ Nĩmonete kyeni kĩnene, Na kwa ala mekalile nthĩ na kyuunĩ kya kĩkw’ũ, Kyeni nĩkĩmaumĩlĩle.'),
('kam', 'MAT', 4, 17, 'Kuma ĩvinda yĩu Yesũ ambĩlĩlya kũtavan’ya, na kwasya, Alyũlai ngoo; nũndũ ũsumbĩ wa ĩtu ni mũthengeeu.'),
('kam', 'MAT', 4, 18, 'Na Yesũ akĩtambũka ũtee wa ũkanga wa Kalilii, oona andũ elĩ ma inyia ũmwe, Simoni ũla wĩtawa Vetelo, na Andalea mwana‐a‐inyia, makĩkya kĩtei ũkanganĩ; nũndũ maĩ atei ma makũyũ.'),
('kam', 'MAT', 4, 19, 'Na amea, Ngatĩĩai, nakwa ngamũtw’a atei ma andũ.'),
('kam', 'MAT', 4, 20, 'Na oyu matia itei, na mamũatĩĩa.'),
('kam', 'MAT', 4, 21, 'Na akĩenda mbee kuma vau, oona andũ angĩ elĩ ma inyia ũmwe, Yakovo mwana wa Sevetii, na Yoana mwana‐a‐inyia, me ngalawanĩ vamwe na Sevetii ĩthe woo, makĩseũvya itei syoo; na ameta.'),
('kam', 'MAT', 4, 22, 'Na oyu matia ngalawa o na ĩthe woo, na mamũatĩĩa.'),
('kam', 'MAT', 4, 23, 'Na Yesũ anganga Kalilii yonthe, akĩmanyĩsya masinakokenĩ moo, na akĩtavan’ya ũvoo mũseo wa ũsumbĩ, na akĩvosya mowau ma mĩthemba yonthe na mawonzu ma mĩthemba yonthe katĩ wa andũ.'),
('kam', 'MAT', 4, 24, 'Na nguma yake yanyaĩĩka nthĩ yonthe ya Silia: na mamũetee onthe ala maĩ awau, ala makwatĩtwe nĩ mowau na mathĩna ma mĩthemba mingĩ, na ala makwatĩtwe nĩ ndaimoni, na ala maĩ na mũng’uthũko, na ala maaĩte mamutha; na amavosya.'),
('kam', 'MAT', 4, 25, 'Na makomano maingĩ mamũatĩĩa kuma Kalilii na Ndekavoli na Yelusaleme na Yutia na mũingo wa Yolotani.'),
('kam', 'MAT', 5, 1, 'Nake akyona ala makomano, ambata kĩĩmanĩ: na ekala nthĩ, amanyĩw’a make mathi vala ũĩ:'),
('kam', 'MAT', 5, 2, 'na aathamya kanyw’a wake na amamanyĩsya, akyasya,'),
('kam', 'MAT', 5, 3, 'Nĩ aathime ala me na ũkya wa ngoo: nũndũ ũsumbĩ wa ĩtu nĩ woo.'),
('kam', 'MAT', 5, 4, 'Nĩ aathime ala me na kĩmeto: nũndũ nĩo makakiakiw’a.'),
('kam', 'MAT', 5, 5, 'Nĩ aathime ala auu: nũndũ nĩo makatiĩwa nthĩ.'),
('kam', 'MAT', 5, 6, 'Nĩ aathime ala me na nzaa na waũni wa ũlũngalu: nũndũ nĩo makausũw’a.'),
('kam', 'MAT', 5, 7, 'Nĩ aathime ala me na tei: nũndũ nĩo makew’ĩwa tei.'),
('kam', 'MAT', 5, 8, 'Nĩ aathime ala atheu ngoo: nũndũ nĩo makamwona Ngai.'),
('kam', 'MAT', 5, 9, 'Nĩ aathime ala mekaa mũuo: nũndũ nĩo maketwa ana ma Ngai.'),
('kam', 'MAT', 5, 10, 'Nĩ aathime ala mathĩniw’e kwondũ wa ũlũngalu: nũndũ ũsumbĩ wa ĩtu nĩ woo.'),
('kam', 'MAT', 5, 11, 'Mwĩ aathime inyw’ĩ yĩla andũ meũmũkava, na kũmũthĩn’ya na kũmũneenea kĩla ũndũ ũthũku wa ũvũngũ, kwondũ wakwa.'),
('kam', 'MAT', 5, 12, 'Tanai, na ĩthĩwai na mũyo mũnene: nĩkwĩthĩwa ĩtuvi yenyu nĩ ĩnene ĩtunĩ: nũndũ ũu nĩw’o mathĩnisye athani ala maĩ mbee wenyu.'),
('kam', 'MAT', 5, 13, 'Inyw’ĩ mwĩ mũnyũ wa nthĩ: ĩndĩ ũla mũnyũ wathela mũsamo waw’o, ũkasamĩthw’a mũnyũ na kyaũ? Ndwĩ vata ĩngĩ nongi, ate o kwĩkw’a ĩtheka na kũkinyangwa nĩ andũ.'),
('kam', 'MAT', 5, 14, 'Ĩnyw’i mwĩ kyeni kya nthĩ. Ndũa yĩ kĩĩmanĩ ĩũlũ ndĩvithĩka.'),
('kam', 'MAT', 5, 15, 'O na andũ maikwatasya taa, na kũwia ungu wa ĩmisi, ĩndĩ mawiaa vala vatũlu; naw’o nũmamulĩkĩlaa onthe me nyũmba.'),
('kam', 'MAT', 5, 16, 'No ta ũu kyeni kyenyu nĩkĩkenae mbee wa andũ, nĩ kana mone mawĩa menyu maseo, na kũmũtaĩa Ĩthe wenyu ũla wĩ ĩtunĩ.'),
('kam', 'MAT', 5, 17, 'Mũikasũanĩe kana nokie kwananga mĩao kana mavuku ma athani: ndyaaũka kwananga, ĩndĩ nĩ kwĩanĩsya.'),
('kam', 'MAT', 5, 18, 'Nũndũ nĩ w’o nĩngũmwĩa, Mũvaka yĩla ĩtu na nthĩ ikavĩta, kũikavĩta kaũandĩko kamwe kana kaũkenyũsyo kamwe mĩaonĩ, mũvaka onthe meanĩw’e.'),
('kam', 'MAT', 5, 19, 'Na ĩndĩ mũndũ o na wĩva ũla ũkananga mwĩao ũmwe wa ĩno ĩla mĩnini, na kũmanyĩsya andũ ũu, aketwa mũnini mbee ũsumbĩnĩ wa ĩtu: ĩndĩ o ũla ũkamĩka na kũmĩmanyĩsya, aketwa mũnene ũsumbĩnĩ wa ĩtu.'),
('kam', 'MAT', 5, 20, 'Nũndũ nĩngũmwĩa, Ũlũngalu wenyu walea kũvĩtũka ũlũngalu wa aandĩki na Avalisi, mũikalika nongi ũsumbĩnĩ wa ĩtu.'),
('kam', 'MAT', 5, 21, 'Nĩmwĩw’ĩte kana andũ ma tene meeĩwe, Ndũkoae; na o ũla ũkoaa akethĩwa mũndũ wa kũsilĩlwa:'),
('kam', 'MAT', 5, 22, 'ĩndĩ nyie nĩngũmwĩa, o ũla ũkamũthatĩa mwana‐a‐ĩthe vate kĩtumi akethĩwa mũndũ wa kũsilĩlwa; na o ũla ũkamũkava mwana‐a‐ĩthe akethĩwa mũndũ wa kũsilĩlwa ni nzama; na o ũla ũkasya, Wĩ ndia we, akethĩwa ũla waĩlwe nĩ mwaki wa Ngiena.'),
('kam', 'MAT', 5, 23, 'Ethĩwa ĩndĩ nũũnengane mũthĩnzĩo waku kĩthembeonĩ, na ũkĩlilikanĩla vu kana mwana‐a‐au e ũndũ naku,'),
('kam', 'MAT', 5, 24, 'tia mũthĩnzĩo waku vu mbee wa kĩthembeo, noithi, wambe kwĩw’ana na mwana‐a‐au na ĩndĩ ũkyũka ũnengane mũthĩnzĩo waku.'),
('kam', 'MAT', 5, 25, 'Ĩw’ana mĩtũkĩ na mũvinganĩsya waku, yĩla wĩ vamwe nake nzĩanĩ; ũla mũvinganĩsya ndakese ũkũtwaa kwa mũsili na mũsili aikũnengane kwa ĩkanga noyĩkĩwa kolokolonĩ.'),
('kam', 'MAT', 5, 26, 'Nĩ w’o nĩngũkwĩa, Ndũkauma vo nongi, mũvaka waĩva kũvika ĩsendi ya kũminũkĩlya.'),
('kam', 'MAT', 5, 27, 'Nĩmwĩw’ĩte kana nĩkwaneeniwe, Ndũkalaalae:'),
('kam', 'MAT', 5, 28, 'ĩndĩ nyie nĩngũmwĩa, kana kĩla mũndũ ũsyaasya mũndũ mũka na kũmwĩw’ĩa mũmeo nĩweka ũlaalai nake ngoonĩ yake.'),
('kam', 'MAT', 5, 29, 'Na ethĩwa itho yaku ya ngalĩ ya kw’oko kwa aũme nĩyĩũkũlulutĩkya, yumye, ũyĩkye kũasa naku: nũndũ nĩkwaĩle kwaku kwaĩwa nĩ mutha ũmwe waku, kwĩ mwĩĩ waku w’onthe kwĩkw’a Ngienanĩ.'),
('kam', 'MAT', 5, 30, 'Na ethĩwa kw’oko kwaku kwa aũme nĩkũũkũlulutĩkya, kũtile, ũkwĩkye kũasa naku: nũndũ nĩkwaĩle kwaku kwaĩwa nĩ mutha ũmwe, kwĩ mwĩĩ waku w’onthe kwĩkw’a Ngienanĩ.'),
('kam', 'MAT', 5, 31, 'Na ĩngĩ nĩkwaneeniwe, O ũla ũekaa mũka, namũnenge valũa wa kũtaanĩsya:'),
('kam', 'MAT', 5, 32, 'ĩndĩ nyie nĩngumwia, kana kĩla mũndũ ũekaa mũka wake, ate o kwondũ wa ũlaalai, nũnũũmũtw’ikĩthya kĩlaalai: na o ũla wĩmũtwaa ũsu ũeketwe nũnũũlaalaa.'),
('kam', 'MAT', 5, 33, 'Na ĩngĩ, nĩmwĩw’ĩte kana andũ ma tene meeiwe, Ndũkaaĩvĩte wĩvĩto wa ũvũngũ, ĩndĩ wĩkae mawĩvĩto maku kwa Mwĩaĩi:'),
('kam', 'MAT', 5, 34, 'ĩndĩ nyie nĩngũmwĩa, Mũikaaĩvĩte nongi; o na kwa ĩtu, nĩkwĩthĩwa nĩyo kĩvĩla kya ũsumbĩ kya Ngai;'),
('kam', 'MAT', 5, 35, 'o na kwa nthĩ, nĩkwĩthĩwa nĩyo kavĩla ka nyaĩĩ syake; o na kwa Yelusaleme, nĩkwĩthĩwa nĩyo ndũa ya Mũsumbĩ ũla mũnene.'),
('kam', 'MAT', 5, 36, 'O na ndũkaaĩvĩte na mũtwe waku, nĩkwĩthĩwa ndũtonya kũtuma ũsw’ĩĩ ũmwe weũva kana wia.'),
('kam', 'MAT', 5, 37, 'Ĩndĩ kũneena kwenyu kwĩthĩwe, Ĩĩ, ĩĩ; Aiee, aiee; na ũndũ o na wĩva ũla ũthonokete asu, nĩ wa ũla mũthũku.'),
('kam', 'MAT', 5, 38, 'Nĩmwĩw’ĩte kana nĩkwaneeniwe, Itho vandũ va itho, na ĩeo vandũ va ĩeo:'),
('kam', 'MAT', 5, 39, 'ĩndĩ nyie nĩngũmwĩa, Mũikakĩlan’ye vinya na mũndũ mũthũku; ĩndĩ o ũla ũnũũkũkũna ĩtau ya ngalĩ ya kw’oko kwa aũme, mũthyũũĩe yĩngĩ nayo.'),
('kam', 'MAT', 5, 40, 'Na ethĩwa mũndũ o na wĩva nũkwenda ũkũtwaa silanĩ, na kwosa kĩtonyeo kyaku, mũekee ngũa yaku ya ĩũlũ nayo.'),
('kam', 'MAT', 5, 41, 'Na o ũla ũkakũĩngĩĩsya kũthi nake mũendo wa nyunzu ya saa, endan’ya nake saa mũima.'),
('kam', 'MAT', 5, 42, 'Mũnenge ũla ũnũũkwĩtya; na ũla ũnũkwenda kũkova kwaku, ndũkamũvate.'),
('kam', 'MAT', 5, 43, 'Nĩmwĩw’ĩte kana nĩkwaneeniwe, Mwende mũtũi waku, na mũmene mũmaitha waku:'),
('kam', 'MAT', 5, 44, 'ĩndĩ nyie nĩngũmwĩa, Mendei amaitha menyu, na mavoyeaei ala mamũthĩnasya;'),
('kam', 'MAT', 5, 45, 'nĩ kana mwĩthĩwe ana ma Ĩthe wenyu ũla wĩ ĩtunĩ; nĩkwĩthĩwa we nũmaumĩasya syũa yake athũku na aseo, na kũmauĩsya mbua ala mekaa ũlũngalu na ala matekaa ũlũngalu.'),
('kam', 'MAT', 5, 46, 'Nũndũ mũkĩmenda ala mamwendaa, mwĩ na ĩtuvi yaũ? O na aumya ma koti matyĩkaa o ũu?'),
('kam', 'MAT', 5, 47, 'Na ethĩwa mwĩmakethya ana‐a‐ĩthe menyu oka, mũmavĩtũkaa va? O na Andũ‐ma‐mbaĩ‐ingĩ matyĩkaa o ũu?'),
('kam', 'MAT', 5, 48, 'Inyw’ĩ ĩndĩ ĩthĩwai eanĩu, tondũ Ĩthe wenyu wĩ ĩtuni nĩ mwĩanĩu.'),
('kam', 'MAT', 6, 1, 'Ĩsũvĩei mũikekae ũlũngalu wenyu mbee wa andũ, nĩ kana mwoneke nĩo: nĩkwĩthĩwa mweeka ũu, mũi na ĩtuvi kwa Ĩthe wenyu ũla wĩ ĩtunĩ.'),
('kam', 'MAT', 6, 2, 'Yĩla ĩndĩ ũkũnengane motethyo, ndũkavuve soo mbee waku, tondũ angangan’ya mekaa masinakokenĩ na nzĩanĩ nene, nĩ kana makathĩĩwe nĩ andũ. Nĩ w’o nĩngũmwĩa, Nĩmosete ĩtuvi yoo.'),
('kam', 'MAT', 6, 3, 'Ĩndĩ yĩla ũũnengane motethyo, kw’oko kwaku kwa aka kũikamanye ũndũ kw’oko kwaku kwa aũme kũkwĩka:'),
('kam', 'MAT', 6, 4, 'nĩ kana motethyo maku methĩwe ma kĩmbithĩ: na Ĩthe waku ũla wonaa kĩmbithĩnĩ akakũĩva.'),
('kam', 'MAT', 6, 5, 'Na yĩla mũũvoya, mũtikethĩwe ta angangan’ya: nũndũ nĩmendaa kũvoya maũngeme masinakokenĩ na makomanĩonĩ ma nzĩa ila nene, nĩ kana moneke nĩ andũ. Nĩ w’o nĩngũmwĩa, Nĩmosete ĩtuvi yoo.'),
('kam', 'MAT', 6, 6, 'Ĩndĩ we, ũkĩvoya, vota nyũmba yaku ĩla ya nthĩnĩ, na wavinga mũomo, voya Ĩthe waku ũla wĩ kĩmbithĩnĩ, na Ĩthe waku ũla wonaa kĩmbithĩnĩ akakũĩva.'),
('kam', 'MAT', 6, 7, 'Na mũkĩvoya mũikatindĩe ndeto, o tondũ Andũ‐ma‐mbaĩ‐ingĩ mekaa: nũndũ mo matalĩlasya kana makeew’ĩka kwondũ wa ndeto syoo kwĩthĩwa nyingĩ.'),
('kam', 'MAT', 6, 8, 'Mũikethĩwe ĩndĩ mũilyĩ ta asu: nũndũ Ĩthe wenyu nĩwĩsĩ ila mwĩ na vata nasyo, mbee wa inyw’ĩ mũtanamũvoya.'),
('kam', 'MAT', 6, 9, 'Inyw’ĩ ĩndĩ voyaai atĩĩ: Asa waitũ ũla wĩ ĩtunĩ, syĩtwa yaku yĩtaĩwe.'),
('kam', 'MAT', 6, 10, 'Ũsumbĩ waku wũke. Kwenda kwaku kwĩke kũũ nthĩ o ta kũya ĩtunĩ'),
('kam', 'MAT', 6, 11, 'Tũnenge ũmũnthĩ lĩu witũ ũtwĩanĩe'),
('kam', 'MAT', 6, 12, 'Naku ũtũekee mathiĩ maitũ, o tondũ ithyĩ naitũ tũmaekeete ala me na thii naitũ.'),
('kam', 'MAT', 6, 13, 'Na ndũkatũtwaae ũtatwanĩ ĩndĩ ũtũtangĩĩe kwa ũla mũthũku. (Nũndũ ũsumbĩ na vinya na ndaĩa nĩ syaku tene na tene, Ameni.)'),
('kam', 'MAT', 6, 14, 'Nũndũ ethĩwa inyw’ĩ mũkamaekea andũ mavĩtyo moo, Ĩthe wenyu wa ĩtunĩ akamũekea inyw’ĩ.'),
('kam', 'MAT', 6, 15, 'Ĩndĩ mwalea kũmaekea andũ mavĩtyo moo, o na Ĩthe wenyu ndakamũekea inyw’ĩ mavĩtyo menyu.'),
('kam', 'MAT', 6, 16, 'O na ĩngĩ mwatĩĩa ũya, mũikatukye mothyũ menyu ta ala angangan’ya: nũndũ nĩmatukasya mothyũ moo, nĩ kana moneke nĩ andũ atĩ nĩmatĩĩĩte ũya. Nĩ w’o nĩngũmwĩa, Nĩmosete ĩtuvi yoo.'),
('kam', 'MAT', 6, 17, 'Ĩndĩ we watĩĩa ũya, vaka mũtwe waku mauta, noithambya ũthyũ waku;'),
('kam', 'MAT', 6, 18, 'nĩ kana ndũkoneke nĩ andũ kana nũtĩĩĩte ũya, ĩndĩ woneke nĩ Ĩthe waku ũla wĩ kĩmbithĩnĩ: na Ĩthe waku ũla wonaa kĩmbithĩnĩ akakũĩva.'),
('kam', 'MAT', 6, 19, 'Mũikeyiĩe ũthwii kũũ nthĩ vala lungulu na nganga syanangaa, na vala ing’ei ivũthũaa na kũya:'),
('kam', 'MAT', 6, 20, 'ĩndĩ ĩyiĩei ũthwii ĩtunĩ, vala lungulu na nganga itananga, na vala ing’ei itavũthũa kana kũya:'),
('kam', 'MAT', 6, 21, 'nũndũ vala ve ũthwii waku, nĩvo vethĩawa ngoo yaku nayo.'),
('kam', 'MAT', 6, 22, 'Taa wa mwĩĩ nĩ itho: ethĩwa ĩndĩ itho yaku nĩ ĩseo, mwĩĩ waku w’onthe ũkausũa kyeni.'),
('kam', 'MAT', 6, 23, 'Ĩndĩ ethĩwa itho yaku nĩ ĩthũku, mwĩĩ waku w’onthe ũkatulya kĩvindu. Ethĩwa ĩndĩ kyeni kĩ nthĩnĩ waku kyeethĩwa kĩvindu, kĩvindu kyu ko te kĩnene!'),
('kam', 'MAT', 6, 24, 'Kũi mũndũ ũtonya kũthũkũma mavwana elĩ: nũndũ akamũmena ũmwe, na akamwenda ũla ũngĩ; kana akalũman’ya na ũmwe, na akamũvũthya ũla ũngĩ. Mũitonya kũthũkũma Ngai o na ũthwii.'),
('kam', 'MAT', 6, 25, 'Kwondũ wa ũu nĩmwĩa, Mũikemakĩe ũndũ wa mathayũ menyu, kĩla mwĩya kana kĩla mwĩnyw’a; o na mĩĩ yenyu, kĩla mwĩĩvw’ika. Thayũ ndwĩ mbee wa kya ũya, na mwĩĩ mbee wa ngũa?'),
('kam', 'MAT', 6, 26, 'Sisyai nyũnyi sya yayaya, nĩkwĩthĩwa itivandaa, o na itikethaa, o na ityũmbanasya makũmbĩnĩ; na Ĩthe wenyu wa ĩtunĩ nĩwiĩthasya. Inyw’ĩ mũi vata mũno kwĩ syo?'),
('kam', 'MAT', 6, 27, 'Na nũũ kwenyu ũla ũtonya kwondũ wa kwĩmakĩa kwake kwĩyongeleela ũasa wake mũkono ũmwe?'),
('kam', 'MAT', 6, 28, 'Na nĩkĩ mũkwĩmakĩa ũndũ wa ngũa? Sũanĩai ũndũ wa malaa ma lili ma kĩthekanĩ, ũndũ mameaa; maitethasya wĩa, o na maiokothaa:'),
('kam', 'MAT', 6, 29, 'ĩndĩ nĩngũmwĩa, o na Solomoni ndaĩanĩ yake yonthe ndaaĩvw’ĩka ta yĩmwe yamo.'),
('kam', 'MAT', 6, 30, 'Ethĩwa ĩndĩ Ngai nũvw’ĩkaa nyeki ya kĩthekanĩ ta ũu, ĩla ĩnĩkwĩkala ũmũnthi, na ũnĩ ĩkekw’a ikonĩ, ndakamũvw’ĩka inyw’ĩ mbee mũno, inyw’ĩ ma mũĩkĩĩo mũnini?'),
('kam', 'MAT', 6, 31, 'Mũikemakĩe ĩndĩ, mũkyasya, Tũkaya kyaũ? Kana, Tũkanyw’a kyaũ? Kana, Tũkeevw’ĩka kĩ?'),
('kam', 'MAT', 6, 32, 'Nũndũ syĩndũ isu syonthe nimanthawa nĩ Andũ‐ma‐mbaĩ‐ingĩ; nĩkwĩthĩwa Ĩthe wenyu wa ĩtunĩ nĩwĩsĩ mwĩ na vata wa syĩndũ isu syonthe.'),
('kam', 'MAT', 6, 33, 'Ĩndĩ ambai ũmantha ũsumbĩ wake, na ũlũngalu wake; na isu syonthe nĩmũkongeleelwa.'),
('kam', 'MAT', 6, 34, 'Mũikemakĩe ĩndĩ ũndũ wa ũnĩ; nũndũ ũnĩ ũkeemakĩa e w’o. Mũthenya nĩwĩanĩwe nĩ ũthũku waw’o.'),
('kam', 'MAT', 7, 1, 'Mũikasilĩle, nĩ kana mũikasilĩlwe.'),
('kam', 'MAT', 7, 2, 'Nũndũ ũsilĩlo ũla mũsilĩlaa, now’o mũkasilĩlwa: na kĩthimo kĩla mũthimaa, no kyo mũkathimĩwa.'),
('kam', 'MAT', 7, 3, 'Naku nĩkĩ ũũsisya kaũvavathĩ ke ithoni ya mwana‐a‐au, na ndũsũanĩa mũamba ũla wĩ ithonĩ yaku we?'),
('kam', 'MAT', 7, 4, 'Kana ũkamwĩa mwana‐a‐au ata, Ndeka nĩkumye kaũvavathĩ ke ithonĩ yaku; na sisya, mũamba wĩ ithonĩ yaku?'),
('kam', 'MAT', 7, 5, 'Mwangangan’ya we, amba kwĩyumya mũamba ũsu wĩ ithonĩ yaku; na ĩndĩ ũkoona nesa kumya kaũvavathĩ kala ke ithonĩ ya mwana‐a‐au.'),
('kam', 'MAT', 7, 6, 'Mũikanenge ngitĩ kĩla kĩtheu, o na mũikekye malũlũ menyu mbee wa ngũlũe, iikese kũmakinyanga na maũũ masyo, na ĩndĩ ikĩthyũũa na kũmũtembũanga.'),
('kam', 'MAT', 7, 7, 'Voyai, na mũkanengwa; manthai, na mũkoona; vingũsyai, na mũkavingũĩwa:'),
('kam', 'MAT', 7, 8, 'nũndũ ũla ũnũkũvoya nũnũũnengwa; na ũla ũnũũmantha nũnũkwona; na ũla ũnũũvingũsya nũnũũvingũĩwa.'),
('kam', 'MAT', 7, 9, 'Kana nũũ mũndũ wenyu, ũla, mwana wake amwĩtya kĩmũtũ, akamũnenga ĩvia?'),
('kam', 'MAT', 7, 10, 'Kana eetya ĩkũyũ, akamũnenga nzoka?'),
('kam', 'MAT', 7, 11, 'Ethĩwa inyw’ĩ ĩndĩ, ala mwĩ athũku, nĩmwĩsĩ kũnenga syana syenyu mĩthĩnzĩo mĩseo, ti mbee mũno Ĩthe wenyu ũla wĩ ĩtunĩ kũmanenga syĩndũ nzeo ala mamwĩtasya?'),
('kam', 'MAT', 7, 12, 'Maũndũ onthe ĩndĩno o na meva ala mũkwenda andũ mamwĩke inyw’ĩ, nenyu mekei o ta ũu: nũndũ ũu nĩw’o mĩao na athani.'),
('kam', 'MAT', 7, 13, 'Votai inyw’ĩ nthĩnĩ na mbingĩlo ĩla ntheke: nũndũ mbingĩlo nĩ nthanthau, na nzĩa nĩ mbaamu, ĩla ĩelete wanangĩkonĩ, nao nĩ aingĩ ala mavotelaa mbingĩlonĩ ĩsu.'),
('kam', 'MAT', 7, 14, 'Nũndũ mbingĩlo nĩ ntheke, na nzĩa nĩ nziĩĩe, ĩla ĩelete thayũnĩ, nao nĩ avũthũ ala mamyonaa.'),
('kam', 'MAT', 7, 15, 'Ĩsũvĩei athani ma ũvũngũ, ala mokaa kũla mũĩ mevw’ĩkĩte ngũa sya malondu, ĩndĩ nthĩnĩ nĩ nzũi mbai.'),
('kam', 'MAT', 7, 16, 'Mũkamamanya nĩ mosyao moo. Andũ nĩmatusaa nzavivũ mĩw’anĩ, kana makũyũ thangilanĩ?'),
('kam', 'MAT', 7, 17, 'No ta ũu kĩla mũtĩ mũseo nũsyaaa ũsyao mũseo; ĩndĩ mũtĩ mũthũku nũsyaaa ũsyao mũthũku.'),
('kam', 'MAT', 7, 18, 'Mũtĩ mũseo ndũtonya ũsyaa ũsyao mũthũku, o na mũtĩ mũthũku ndũtonya kũsyaa ũsyao mũseo.'),
('kam', 'MAT', 7, 19, 'Kĩla mũtĩ ũtasyaaa ũsyao mũseo nũtemawa, ũkekw’a mwakinĩ.'),
('kam', 'MAT', 7, 20, 'Kwondũ wa ũu nĩmũkamamanya nĩ mosyao moo.'),
('kam', 'MAT', 7, 21, 'Ti kĩla mũndũ ũmbĩtaa, Mwĩaĩi, Mwĩaĩi, ũkavota ũsumbĩnĩ wa ĩtu; ĩndĩ nĩ ũla wĩkaa wende wa Asa wakwa ũla wĩ ĩtunĩ.'),
('kam', 'MAT', 7, 22, 'Mũthenya ũsu nĩ aingĩ makambĩa, Mwĩaĩi, Mwĩaĩi, tũiaathana na syĩtwa yaku, na kumya ndaimoni na syĩtwa yaku, na kwĩka mavinya maingĩ na syĩtwa yaku?'),
('kam', 'MAT', 7, 23, 'Nĩvo ĩndĩ ngamatavya vyũ, Ndyaamũmanya o na ĩndĩĩ: umai vala nĩĩ, inyw’ĩ mwĩkaa mothũku.'),
('kam', 'MAT', 7, 24, 'Kĩla mũndũ ĩndĩ wĩw’aa ndeto ii syakwa, naisyĩkaa, akavw’ananwa na mũndũ mũĩ, ũla wakie nyũmba yake ĩvianĩ:'),
('kam', 'MAT', 7, 25, 'na mbua yaua, na mbũsĩ syooka, na iseve syauutana, syakima nyũmba ĩsu; na ndĩaavalũka: nũndũ wambĩlĩlyo wayo waakĩtwe ĩũlũ wa ĩvia.'),
('kam', 'MAT', 7, 26, 'Na kĩla mũndũ ũla wĩw’aa ndeto ii syakwa, na ndasyĩkaa, akavw’ananwa na mũndũ mũtumanu ũla wakie nyũmba yake kĩthangathĩnĩ;'),
('kam', 'MAT', 7, 27, 'na mbua yaua, na mbũsĩ syooka, na iseve syauutana syakima nyũmba ĩsu; nayo yavalũka: na ũvalũko wayo waĩ mũnene.'),
('kam', 'MAT', 7, 28, 'Na kweethĩwa Yesũ amina ũneena ndeto isu, ala makomano maseng’w’a nĩ ũmanyĩsyo wake:'),
('kam', 'MAT', 7, 29, 'nĩkwĩthĩwa amamanyĩasya ta ũla wĩ na ũkũmũ, na ti ta ala aandĩki moo.'),
('kam', 'MAT', 8, 1, 'Na atheea kuma kĩĩmanĩ, makomano maingĩ mamũatĩĩa.'),
('kam', 'MAT', 8, 2, 'Na sisya, mũndũ ũwaĩte mangũ athi vala ũĩ na amũthaitha, akyasya, Mwĩaĩi, ethĩwa nũkwenda, nũtonya kũnthesya.'),
('kam', 'MAT', 8, 3, 'Nake atambũũkya kw’oko kwake, na amũkiita, akyasya, Nĩngwenda; ĩthĩwa mũtheu. Na oyu athea mangũ make.'),
('kam', 'MAT', 8, 4, 'Na Yesũ amwĩa, Sisya, ndũkatavye mũndũ; ĩndĩ thi, ũkeyonan’ye kwa mũthembi, noiumya mũthĩnzĩo ũla Mose weaie, wĩthĩwe ũkũsĩ kwoo.'),
('kam', 'MAT', 8, 5, 'Na avota Kavelinaumi, mũnene wa asikalĩ ĩana ooka vala ũĩ, aimwĩsũva,'),
('kam', 'MAT', 8, 6, 'akyasya, Mwĩaĩi, mũthũkũmi wakwa nũkomete nyũmba awaĩte ũwau wa kwaa mamutha, na nũnũũthĩna mũno.'),
('kam', 'MAT', 8, 7, 'Na amwĩa, Ngooka na ngĩmũvosya:'),
('kam', 'MAT', 8, 8, 'Na ũla mũnene wa asikalĩ ĩana amũsũngĩa, asya, Mwĩaĩi, ndyĩanĩwe nue kũlika ungu wa kĩala kyakwa; ĩndĩ neena ndeto tũ, na mũthũkũmi wakwa nũnũũvoa.'),
('kam', 'MAT', 8, 9, 'Nũndũ nyie nakwa nĩ mũndũ ũla wĩaĩawa, nĩ na asikalĩ makwa ĩtheo wakwa; na ngĩmwĩa ũmwe, Enda, na akĩthi; na ũngĩ, Ũka na akyũka; na ngombo yakwa, Ĩka ũna, na ĩkĩka.'),
('kam', 'MAT', 8, 10, 'Na Yesũ eew’a ũu, aseng’a, na amea ala mamũvikĩlĩte, Nĩw’onĩngũmwĩa, Ndyaaona mũĩkĩĩo mũnene ta ũu, aiee, o na nthĩnĩ wa Isilaeli.'),
('kam', 'MAT', 8, 11, 'Nakwa nĩngũmwĩa, kana aingĩ makooka kuma wumĩlonĩ wa syũa na ũthũĩlonĩ wa syũa, na makekala nthĩ vamwe na Avalaamu, na Isaka, na Yakovo ũsumbĩnĩ wa ĩtu:'),
('kam', 'MAT', 8, 12, 'ĩndĩ ana ma ũsumbĩ makekw’a kĩvindũnĩ kĩla kĩ nza: vo vakethĩwa kĩĩo na kũvevetan’ya maeo.'),
('kam', 'MAT', 8, 13, 'Na Yesũ amwĩa ũla mũnene wa asikalĩ ĩana Ĩendee; kwĩthĩwe kwaku o tondũ ũĩkĩĩe. Na ũla mũthũkũmi avow’a kavinda o kau.'),
('kam', 'MAT', 8, 14, 'Na Yesũ athi nyũmbanĩ ya Vetelo, oona inyia wa mũka wa Vetelo akomete awaĩte ndetema.'),
('kam', 'MAT', 8, 15, 'Nake amũkiita kw’oko, na ndetema yamũtia; nake ookĩla, amathũkũma.'),
('kam', 'MAT', 8, 16, 'Na kwavika wĩoo, mamũetee aingĩ makwetwe nĩ ndaimoni: na amaumya ndaimoni na ndeto, na avosya onthe ala maĩ awau:'),
('kam', 'MAT', 8, 17, 'nĩ kana kwĩanĩw’e ũla waneeniwe nĩ mwathani Isaia, akyasya, We mwene nĩwosie mawonzu maitũ na akua mowau maitũ.'),
('kam', 'MAT', 8, 18, 'Na Yesũ oona makomano manene mamũthyũlũlũkĩte, eeaa mathi mũingo ũla ũngi.'),
('kam', 'MAT', 8, 19, 'Na kwooka mũandĩki ũmwe, na amwĩa, Mũmanyĩsya, ngakũatĩĩa o kũla wĩthi.'),
('kam', 'MAT', 8, 20, 'Na Yesũ amwĩa, Mbĩwa syĩ na maima, na nyũnyi sya yayaya syĩ na ndala; ĩndĩ Mwana wa mũndũ nde na vandũ va ũkomya mũtwe wake.'),
('kam', 'MAT', 8, 21, 'Na ũngĩ wa amanyĩw’a amwĩa, Mwĩaĩĩ, nenga ũthei nambe ũthi kũmũthika nau.'),
('kam', 'MAT', 8, 22, 'Ĩndĩ Yesũ amwia, Mbikĩla; eka akw’ũ mathike akw’ũ moo.'),
('kam', 'MAT', 8, 23, 'Na alika ngalawanĩ, amanyĩw’a make mamũvikĩla.'),
('kam', 'MAT', 8, 24, 'Na sisya, kwookĩla kĩuutani kĩnene ũkanganĩ, mũvaka ngalawa yavw’ĩkwa nĩ itulumo: ĩndĩ we nĩwakomete.'),
('kam', 'MAT', 8, 25, 'Na mathi vala ũĩ mamũamũkya, makyasya, Mwĩaĩi tũtangĩĩe; nĩtũũkw’a.'),
('kam', 'MAT', 8, 26, 'Na amea, Nĩkĩ mwĩ na w’ĩa inyw’ĩ ma mũĩkĩĩo mũnini? Nĩvo ĩndĩ wokĩlile, akan’ya iseve na ũkanga; na kwaya ũuu mũnene.'),
('kam', 'MAT', 8, 27, 'Na ala andũ maseng’a, makyasya, Ailyĩ ata mũndũ ũũ, nũndũ o na iseve na ũkanga niũmwĩw’a?'),
('kam', 'MAT', 8, 28, 'Na avika mũingo ũla ũngĩ nthĩ ya Akatalene, andũ elĩ makwatĩtwe nĩ ndaimoni makomana nake, maumĩte mbũanĩ me ai mũno, ũndũ mũndũ o na wĩva ndaĩ atonya kũvĩtĩla nzĩanĩ ĩsu.'),
('kam', 'MAT', 8, 29, 'Na sisya makaya, makyasya, Ithyĩ twĩ ũndũ naku wa kĩ, we Mwana wa Ngai? Nĩwooka vaa kũtũthĩn’ya ĩvinda yĩte ĩviku?'),
('kam', 'MAT', 8, 30, 'Na ĩndĩ kwaĩ ĩĩthya ya ngũlũe nyingĩ vaasa nao yĩkĩya.'),
('kam', 'MAT', 8, 31, 'Na ila ndaimoni syamwĩsũva, ikyasya, Ethĩwa nũũtumya, tũeke tũende tũlike ĩĩthyanĩ ya ngũlũe.'),
('kam', 'MAT', 8, 32, 'Na asyĩa, Thii. Nasyo syauma, syalika ngũlũenĩ: na sisya, yĩla ĩĩthya yonthe ya ngũlũe yatheea kĩvaũũkonĩ yĩsembete, yalika ũkanganĩ, yakw’ĩa manzĩnĩ.'),
('kam', 'MAT', 8, 33, 'Na ala maĩthasya, mathi ndũanĩ, na matavan’ya ũvoo w’onthe, na ũndũ ũmakĩtĩkie ala meĩkwatĩtwe nĩ ndaimoni.'),
('kam', 'MAT', 8, 34, 'Na sisya, andũ ma ndũa nima maumaala kũmũthaũa Yesũ: na mamwona, mamwĩsũva aume mĩvakanĩ yoo athi.'),
('kam', 'MAT', 9, 1, 'Na alika ngalawanĩ, ainga, athi ndũanĩ kwoo.'),
('kam', 'MAT', 9, 2, 'Na sisya, mamũetee mũndũ ũla waĩ na ũwau wa kwaa mamutha, akomete ũkomonĩ: na Yesũ oona mũĩkĩĩo woo amwĩa ũla waĩ na ũwau wa kwaa mamutha, Mwana, ĩthĩwa na ũnyĩau; naĩ syaku nĩsyaekwa.'),
('kam', 'MAT', 9, 3, 'Na sisya, amwe ma aandĩki maneena ngoonĩ syoo, Mũndũ ũũ nũkũumana.'),
('kam', 'MAT', 9, 4, 'Na Yesũ amanya malilikano moo, asya, Nĩ ũndũ wa kĩ mũũsũanĩa mothũku ngoonĩ syenyu?'),
('kam', 'MAT', 9, 5, 'Nũndũ ũla ũvũthũ nĩ wĩva, kwasya, Naĩ syaku nĩsyaekwa; kana kwasya, Ũkĩla, ũthi?'),
('kam', 'MAT', 9, 6, 'Ĩndĩ nĩ kana mũmanye atĩ Mwana wa mũndũ e na ũkũmũ kũũ nthĩ wa kũekea naĩ (nĩvo wamwĩie ũla waĩ na ũwau wa kwaa mamutha), Ũkĩla, ũkue ũkomo waku, wĩnũke.'),
('kam', 'MAT', 9, 7, 'Nake ookĩla, enũka.'),
('kam', 'MAT', 9, 8, 'Ĩndĩ makomano moona ũu, makwatwa nĩ w’ĩa, na mamũtaĩa Ngai, ũla ũnengete andũ ũkũmũ ta ũsu.'),
('kam', 'MAT', 9, 9, 'Na Yesũ akĩvĩta kuma vau, oona mũndũ, wetawa Mathayo, ekalĩte vala vaumĩaw’a koti: na amwĩa, Mbikĩla. Nake ookĩla, amũvikĩla.'),
('kam', 'MAT', 9, 10, 'Na kweethĩwa ekalĩte nyũmba akĩya lĩu, sisya, aumya ma koti na andũ athe aingĩ mooka na mekala nthĩ vamwe na Yesũ na amanyĩw’a make.'),
('kam', 'MAT', 9, 11, 'Na Avalisi moona ũu, mamea amanyĩw’a make, Nĩkĩ Mũmanyĩsya wenyu ũnũũya vamwe na aumya ma koti na andũ athe?'),
('kam', 'MAT', 9, 12, 'Nake eew’a ũu, amea, Ala mate awau mati vata wa mũiiti, ĩndĩ no ala awau.'),
('kam', 'MAT', 9, 13, 'Ĩndĩ endai mũkemanyĩsye ũndũ ũtilyĩ ũndũ ũũ, Nyie nendaa tei na ti nthembo: nĩkwĩthĩwa ndyaaũka kũmeta ala alũngalu, ĩndĩ nĩ ala athe.'),
('kam', 'MAT', 9, 14, 'Nĩvo ĩndĩ amanyĩw’a ma Yoana mookie, makyasya, Nĩkĩ ithyĩ na Avalisi tũtĩĩaa ũya mavinda maingĩ, ĩndĩ amanyĩw’a maku matitĩĩaa ũya?'),
('kam', 'MAT', 9, 15, 'Na Yesũ amakũlya, Ala metĩtwe mũtwaanonĩ nĩmatonya kũmeta ĩvinda yĩla mũtwaani wĩ vamwe nao? Ĩndĩ mĩthenya nĩyũkĩte, yĩla mũtwaani ũkaumw’a kwoo, nĩvo ĩndĩ makatĩĩa ũya.'),
('kam', 'MAT', 9, 16, 'Na vai mũndũ ũliaa kĩlio kya ngũa nzaũ ngũanĩ ngũũ; nũndũ kĩla kĩkĩawa vo nĩkyumasya kĩlungu kya ngũa ĩla ngũũ, na ũtembũku ũiendeea ũineneva.'),
('kam', 'MAT', 9, 17, 'O na andũ maiĩ-kĩaa mbinyu mbĩthĩ mathatwanĩ makũũ: nĩkwĩthĩwa mekĩa, ala mathatwa makatembũka, na mbinyu ĩkĩtĩka, na mathatwa makyanangĩka: ĩndĩ mekĩaa mbinyu mbĩthĩ mathatwanĩ meũ, na syelĩ ikĩkala.'),
('kam', 'MAT', 9, 18, 'Akĩneena maũndũ asu nao, sisya, kwooka mũndũ ũmwe mũnene, na amũthaitha, akyasya, Mwĩĩtu wakwa nĩwakw’a oyu: ĩndĩ ũka ũkamwilĩĩle kw’oko na nũnũkwĩthĩwa thayũ.'),
('kam', 'MAT', 9, 19, 'Na Yesũ ookĩla, amũvikĩla, vamwe na amanyĩw’a make.'),
('kam', 'MAT', 9, 20, 'Na sisya, mũndũ mũka, ũla waumawa nĩ nthakame ĩvinda ya myaka ĩkũmi na ĩlĩ ooka ĩtina wake, na akiita ũtiivo wa ngũa yake:'),
('kam', 'MAT', 9, 21, 'nũndũ aisye ngooni yake, Nakiita, o na ethiwa no ngũa yake, nĩngũvoa nĩthĩwe nĩ mũima.'),
('kam', 'MAT', 9, 22, 'Ĩndĩ Yesũ eethyũũa na amwona amwĩa, Mwĩĩtu, ĩthĩwa na ũtanu mũnene; mũĩkĩĩo waku nĩwakũvosya. Na ũla mũndũ mũka avoa, eethĩwa e mũima kuma kavinda o kau.'),
('kam', 'MAT', 9, 23, 'Na Yesũ alika nyũmbanĩ ya ũla mũnene, na oona avuvi ma nzumalĩ, na nguthu ya andũ maĩlonzan’ya,'),
('kam', 'MAT', 9, 24, 'asya, Umai vaa: nũndũ kelĩtu ti kakw’ũ, ĩndĩ nĩkakomete. Na mamũthekeea mũno.'),
('kam', 'MAT', 9, 25, 'Ĩndĩ ĩla nguthu yaumaalw’a nza, avota nthĩnĩ, na akakwata kw’oko; na kala kelitu kookĩla.'),
('kam', 'MAT', 9, 26, 'Na nguma ya ũndũ ũsu yanyaĩĩka nthĩ ĩsu yonthe.'),
('kam', 'MAT', 9, 27, 'Na Yesũ akĩvĩta kuma vo, ililinda ĩlĩ syamũatĩĩa, syaneena na mawasya manene, ikyasya, Twĩw’ĩe tei, we mwana wa Ndaviti.'),
('kam', 'MAT', 9, 28, 'Na avota nyũmba, ila ililinda syooka vala ũĩ: na Yesũ asyĩa, Nĩmũĩkĩĩe kana nĩndonya kwĩka ũndũ ũũ? Syamwĩa, Ĩĩ, Mwĩaĩi.'),
('kam', 'MAT', 9, 29, 'Nĩvo ĩndĩ wakiitie metho masyo, akyasya, O ta kũĩkĩĩa kwenyu nĩkwĩkwe kwenyu.'),
('kam', 'MAT', 9, 30, 'Na metho masyo masalukw’a. Na Yesũ amakindĩlĩla na vinya, akyasya, Sisyai mũndũ o na ũmwe ndakamanye.'),
('kam', 'MAT', 9, 31, 'Ĩndĩ mo mauma vo, na manyaĩĩkya nguma yake nthĩ ĩsu yonthe.'),
('kam', 'MAT', 9, 32, 'Na makyumaala, sisya, aetewe mũndũ ũtaneenaa, ũkwatĩtwe nĩ ndaimoni.'),
('kam', 'MAT', 9, 33, 'Na ndaimoni yaumwa, ũla ũtaneenaa, aneena: na makomano maseng’a, makyasya, Nthĩnĩ wa Isilaeli ũndũ ũsu ndwaamba kwoneka.'),
('kam', 'MAT', 9, 34, 'Ĩndĩ Avalisi masya, Aumasya ndaimoni na vinya wa mũnene wa ndaimoni.'),
('kam', 'MAT', 9, 35, 'Na Yesũ anganga ndũa syonthe na mĩsyĩ, aimanyĩsya masinakokenĩ moo, na aitavan’ya ũvoo mũseo wa ũsumbĩ, na aivosya mowau ma mĩthemba yonthe na kĩla wonzu.'),
('kam', 'MAT', 9, 36, 'Na amona makomano, amew’ĩa tei nĩkwĩthĩwa nĩmanyamaaw’a na kũnyaĩĩkw’a ta malondu mate na mũĩthi.'),
('kam', 'MAT', 9, 37, 'Na ĩndĩ amea amanyĩw’a make, Nĩ w’o ngetha nĩ nyingĩ, ĩndĩ akethi nĩ avũthũ.'),
('kam', 'MAT', 9, 38, 'Voyai ĩndĩ Mwĩaĩi wa ngetha, atũme akethi ngethanĩ yake.'),
('kam', 'MAT', 10, 1, 'Na ameta amanyĩw’a make ĩkũmi na elĩ moke vala ũĩ, na amanenga ũkũmũ ĩũlũ wa maveva mavuku, mamaumye na kũvosya mowau ma mĩthemba yonthe na kĩla wonzu.'),
('kam', 'MAT', 10, 2, 'Na masyĩtwa ma ala atũmwa ĩkũmi na elĩ nĩ aa: Wa mbee nĩ Simoni ũla wĩtawa Vetelo, na Andalea mwana‐a‐inyia; Yakovo mwana wa Sevetii, na Yoana mwana‐a‐inyia;'),
('kam', 'MAT', 10, 3, 'Vilivu, na Valitholomayo; Thoma, na Mathayo ũla mumya wa koti; Yakovo mwana wa Alivaio, na Thatayo;'),
('kam', 'MAT', 10, 4, 'Simoni ũla Mũkanaani, na Yutasi Isikalioti ũla wamũvũnyanĩe'),
('kam', 'MAT', 10, 5, 'Yesũ amatũma asu ĩkũmi na elĩ aimeaĩa, akyasya, Nzĩa ya Andũ‐ma‐mbaĩ‐ingĩ o na yĩva mũikamĩendele, o na mũikavote ndũanĩ ya Asamalia o na yĩva:'),
('kam', 'MAT', 10, 6, 'ĩndĩ kavaa mũthi kwa malondu mau ma nyũmba ya Isilaeli.'),
('kam', 'MAT', 10, 7, 'Na mũendete, tavan’yai, mũkyasya, Ũsumbĩ wa ĩtu nĩ mũthengeeu.'),
('kam', 'MAT', 10, 8, 'Vosyai ala awau, thayũũkyai ala akw’ũ, thesyai ala mawaĩte mangũ, na umyai ndaimoni: nĩmwosete mana, nenganai mana.'),
('kam', 'MAT', 10, 9, 'Mũikakue thaavu, kana vetha, kana ũthuku ngusunĩ syenyu;'),
('kam', 'MAT', 10, 10, 'kana mũvuko wa nzĩanĩ, kana itonyeo ilĩ, kana iatũ, kana ndata: nũndũ mũtethya wa wĩa nĩwaĩlwe nĩ kya ũya kyake.'),
('kam', 'MAT', 10, 11, 'Na ndũa kana mũsyĩ o ũla mwĩvota, manthai vo mũndũ ũla mwaĩlu; na ĩkalai vo mũvaka yĩla mwĩvauma.'),
('kam', 'MAT', 10, 12, 'Na mũkĩlĩka nyũmba, mĩkethyei.'),
('kam', 'MAT', 10, 13, 'Na ethĩwa nyũmba nĩyaĩle, mũuo wenyu nũmĩtheee: ĩndĩ ethĩwa ndĩaĩle, mũuo wenyu nũmũsyokee.'),
('kam', 'MAT', 10, 14, 'Na o ũla ũteũmũthokya, o na kwĩw’a ndeto syenyu, mũkyuma nyũmba ĩsu kana ndũa ĩsu, tuangai kĩtoo kya maũũ menyu.'),
('kam', 'MAT', 10, 15, 'Nĩ w’o nĩngũmwĩa, Kũkethĩwa kavaa nthĩ ya Sotomo na Ngomola mũthenya wa sila, kwĩ ndũa ĩsu.'),
('kam', 'MAT', 10, 16, 'Sisyai, nĩngũmũtũma ta malondu katĩ wa nzũi: ĩthĩwai ĩndĩ mwĩ oĩ ta nzoka, na auu ta mavũĩ.'),
('kam', 'MAT', 10, 17, 'Ĩndĩ ĩsũvĩei na andũ: nũndũ makamũtwaa mbee wa nzama, na makamũvũĩa masinakokenĩ moo;'),
('kam', 'MAT', 10, 18, 'ĩĩ, na mũkatwawa mbee wa makavana na asumbĩ kwondũ wakwa, mwĩthĩwe mwĩ ngũsĩ kwamo na kwa Andũ‐ma‐mbaĩ‐ingĩ.'),
('kam', 'MAT', 10, 19, 'Ĩndĩ yila makamũtwaa kw’o, mũikavũavũane ũndũ mwĩasya kana ndeto ila mwĩneena: nũndũ kavinda kau mũkanengwa ũndũ wa ũneena.'),
('kam', 'MAT', 10, 20, 'Nĩkwĩthĩwa ti inyw’ĩ mwĩneena, ĩndĩ nĩ Veva wa Ĩthe wenyu ũla wĩneena nthĩnĩ wenyu.'),
('kam', 'MAT', 10, 21, 'Na mũndũ akanengane mwana‐a‐inyia oawe, na ĩthe mwana wake: na syana ikamokĩlĩla ala maisyaie, na kũmoaĩthya.'),
('kam', 'MAT', 10, 22, 'Na mũkamenwa nĩ andũ onthe kwondũ wa syĩtwa yakwa: ĩndĩ ũla wĩĩyũmĩĩsya kũvika mũminũkĩlyo, ũsu akatangĩĩwa.'),
('kam', 'MAT', 10, 23, 'Ĩndĩ mamũthĩn’ya ndũanĩ ĩno, kĩai mũthi ndũanĩ ĩngĩ: nũndũ nĩ w’o nĩngũmwĩa, Mũikethĩwa mũnatũngan’ya ndũa sya Isilaeli, Mwana wa mũndũ atanoka.'),
('kam', 'MAT', 10, 24, 'Mũmanyĩw’a ndethĩwa e ĩulũ wa mũmanyĩsya wake kana ngombo ĩũlũ wa vwana wayo.'),
('kam', 'MAT', 10, 25, 'Mũmanyĩw’a nĩwĩanĩwe nĩ kwĩthĩwa ta mũmanyĩsya wake, na ngombo ta vwana wayo. Ethĩwa nĩmamwĩtie mwene wa nyũmba syĩtwa ya Veelisevuli, ti mbee mũno kũmeta ũu ala ma nyũmba yake?'),
('kam', 'MAT', 10, 26, 'Mũikamakĩe ĩndĩ: nũndũ kũti ũndũ ũvw’ike, ũtakavuũwa; kana ũndũ ũvithe ũtakamanyĩka.'),
('kam', 'MAT', 10, 27, 'Ũla ngũmũtavĩsya kĩvindunĩ, neenai kyeninĩ; na ũla mũkwĩw’a na kũtũ, tavanĩsyai nyũmbanĩ ĩũlũ.'),
('kam', 'MAT', 10, 28, 'Mũikamakĩe ala moaa mwĩĩ matatonya kũaa thayũ: ĩndĩ kavaa mũmũkĩe we ũla ũtonya kwanangĩa thayũ na mwĩĩ naw’o Ngienanĩ.'),
('kam', 'MAT', 10, 29, 'Tũsũni twĩlĩ tũitewa ĩsendi yĩmwe? Na vai kamwe katw’o kakavalũka nthĩ Ĩthe wenyu atekwenda:'),
('kam', 'MAT', 10, 30, 'ĩndĩ o na nzw’ĩĩ syonthe sya mĩtwe yenyu nĩ ndale.'),
('kam', 'MAT', 10, 31, 'Mũikakĩe ĩndĩ; inyw’ĩ mwĩ vata kwĩ tũsũni twingĩ.'),
('kam', 'MAT', 10, 32, 'Kĩla mũndũ ĩndĩ ũla wĩmbumbũlaa mbee wa andũ, nakwa ngamumbũlaa mbee wa Asa wakwa ũla wĩ ĩtunĩ.'),
('kam', 'MAT', 10, 33, 'Ĩndĩ o ũla wĩngaĩaa mbee wa andũ nakwa ngamũkaĩaa mbee wa Asa wakwa ũla wĩ ĩtunĩ.'),
('kam', 'MAT', 10, 34, 'Mũikatalĩlye kana nokie kũete mũuo kũũ nthĩ: ndyaaũka kũete mũuo, ĩndĩ nĩ ũvyũ.'),
('kam', 'MAT', 10, 35, 'Nũndũ nokie kũthũan’ya mũndũ na ĩthe, na mwĩĩtu na nyinyia, na mũtwawa na inyia wa mũũme:'),
('kam', 'MAT', 10, 36, 'na amaitha ma mũndũ makethĩwa ala ma nyũmba yake.'),
('kam', 'MAT', 10, 37, 'Ũla ũmwendaa ĩthe kana nyinyia kwĩ nyie, ndambaĩle; na ũla ũmwendaa mwana kana mwĩĩtu wake kwĩ nyie, ndambaĩle.'),
('kam', 'MAT', 10, 38, 'Na ũla ũtosaa ngelan’yo yake na kũngatĩĩa, ndambaĩle.'),
('kam', 'MAT', 10, 39, 'Ũla wonaa thayũ wake akawasya; na ũla waasya thayũ wake kwondũ wakwa akawona.'),
('kam', 'MAT', 10, 40, 'Ũla ũmwosaa inyw’ĩ ambosaa nyie, na ũla ũmbosaa nyie amwosaa ũla wandũmie.'),
('kam', 'MAT', 10, 41, 'Ũla ũmwosaa mwathani syĩtwanĩ ya mwathani akoosa ĩtuvi ya mwathani; na ũla ũmwosaa mũndũ mũlũngalu syĩtwanĩ ya mũndũ mũlũngalu akoosa ĩtuvi ya mũndũ mũlũngalu.'),
('kam', 'MAT', 10, 42, 'Na o ũla ũkanenga ũmwe wa aa anini kĩkombe kya manzĩ mathithu kyoka, syĩtwanĩ ya mũmanyĩw’a, nĩ w’o nĩngũmwĩa, ĩtuvi yake yĩtikaa nongi.'),
('kam', 'MAT', 11, 1, 'Na kweethĩwa Yesũ amina kwĩaĩa amanyĩw’a make ĩkũmi na elĩ, auma vo athi kũmanyĩsya na kũtavan’ya ũvoo mũseo ndũanĩ syoo.'),
('kam', 'MAT', 11, 2, 'Na Yoana, e kolokolonĩ eew’a ũvoo wa meko ma Klĩsto, atũma amanyĩw’a make, makamũkũlye,'),
('kam', 'MAT', 11, 3, 'We nue ũla wĩũka, kana tũmweteele ũngĩ?'),
('kam', 'MAT', 11, 4, 'Na Yesũ asũngĩa, amea, Endai mũkamũtavye Yoana maũndũ ala mwĩw’ĩte na kũmona:'),
('kam', 'MAT', 11, 5, 'ililinda nikwona, na ala mathuaa nĩmeũthi, na ala mawaĩte mangũ nĩmeũthew’a, na ala au matũ nĩmekwĩw’a, na ala akw’ũ nĩmeũthayũũkw’a, na ala ngya nĩmeũtavw’a ũvoo museo.'),
('kam', 'MAT', 11, 6, 'Na nĩ mũathime o ũla ũtakona ũndũ wa ũlulutĩkw’a nthĩnĩ wakwa.'),
('kam', 'MAT', 11, 7, 'Na asu mathi, Yesũ ambĩlĩlya kũneena na makomano ũndũ wa Yoana, Nĩ kyaũ kĩla mwaendaa kũsisya weũnĩ? Nĩ mũangi ũthingithangw’a nĩ kĩseve?'),
('kam', 'MAT', 11, 8, 'Ĩndĩ nĩ kyaũ kĩla mwaendaa kwona? Nĩ mũndũ wĩkĩe ngũa nduũku? Sisyai, ala mekĩaa ngũa nduũku me nyũmbanĩ sya asumbĩ.'),
('kam', 'MAT', 11, 9, 'Ĩndĩ mwaendaa kĩ? Kwona mwathani? Ĩĩ, nĩngũmũtavya, nĩ ũla ũvĩtũkĩte mũno mwathani.'),
('kam', 'MAT', 11, 10, 'Ũsu nĩwe ũla waandĩkĩwe atĩĩ, Sisya, nyie nĩngũtũma mũtũmwa wakwa mbee wa ũthyũ waku, Ũla ũkaseũvya nzĩa yaku mbee waku.'),
('kam', 'MAT', 11, 11, 'Nĩ w’o nĩngũmwĩa, Katĩ wa ala masyaawa nĩ aka kũiaaumĩla mũnene kũvĩta Yoana ũla Mũvatisi: o na kau ũla mũnini ũsumbĩnĩ wa ĩtu nĩ mũnene kwĩ we.'),
('kam', 'MAT', 11, 12, 'Na kuma matukũ ma Yoana ũla Mũvatisi kũvika yu ũsumbĩ wa ĩtu nũlikawa na vinya, na andũ me vinya nĩmawosaa na vinya.'),
('kam', 'MAT', 11, 13, 'Nĩkwĩthĩwa athani onthe na ĩla mĩao nĩmathanie kũvika ĩvinda ya Yoana.'),
('kam', 'MAT', 11, 14, 'Na ethĩwa nĩmũkwenda kwĩtĩkĩla, we nĩwe Eliya ũla wĩũka.'),
('kam', 'MAT', 11, 15, 'Ũla wĩ matũ ma kwĩw’a, nĩew’e.'),
('kam', 'MAT', 11, 16, 'Ĩndĩ nĩũelekan’ya na kyaũ ũsyao ũũ? Ũtilyĩ ta syana syĩkalĩte ing’ang’anĩ, ila syĩtaa syana ingĩ,'),
('kam', 'MAT', 11, 17, 'ikyasya, Twamũvuvĩa mũtũlilũ, na mũinasũnga; twamũmetea, na mũinakũna ithũi.'),
('kam', 'MAT', 11, 18, 'Nũndũ Yoana nĩwokie ateũya na ateũnyw’a, nao measya, E na ndaimoni.'),
('kam', 'MAT', 11, 19, 'Mwana wa mũndũ nĩwokie akĩya na akĩnyw’a, nao measya, Sisyai, mũyi na mũnywi, mũnyanyae wa aumya ma koti na andũ athe! Na ũĩ nũtalĩlawa ũlũngalu nĩ syana syaw’o.'),
('kam', 'MAT', 11, 20, 'Nĩvo wambĩlĩlye kũkan’ya mũno ndũa ila mavinya make maingĩ meekiwe nthĩnĩ wasyo, nĩkwĩthĩwa ityaalyũla ngoo.'),
('kam', 'MAT', 11, 21, 'Woo nĩ waku, Kolasini! Woo nĩ waku, Vethisaita! Nũndũ kethĩwa kweekiwe mavinya Tile na Sitoni ta ala meekiwe nthĩnĩ wenyu, andũ ma kw’o methĩwa maalyũlile ngoo tene makekĩa makunia na kwĩyũmba mũu.'),
('kam', 'MAT', 11, 22, 'Ĩndĩ nyie nĩngũmwĩa, Tile na Sitoni ikethĩwa syĩ kavaa mũthenya wa sila, kwĩ inyw’ĩ.'),
('kam', 'MAT', 11, 23, 'Naku Kavelinaumi, ũkookĩlw’a kũvika ĩtunĩ? Ũkatheew’a kũvika vala maveva ma akw’ũ mekalaa: nũndũ kethĩwa kweekiwe mavinya Sotomo ta ala meekiwe nthĩnĩ waku we, yĩthĩwa vo kũvika mũnthĩ ũũ.'),
('kam', 'MAT', 11, 24, 'Ĩndĩ nĩngũmwĩa, Sotomo ĩkethĩwa ĩ kavaa mũthenya wa sila, kwĩ we.'),
('kam', 'MAT', 11, 25, 'Ĩvinda yĩu Yesũ asũngĩa, asya, Nĩngũũtũngĩa mũvea, we Asa, Mwĩaĩi wa ĩtu na nthĩ, nĩkwĩthĩwa maũndũ asu nĩwamavithie ala me na ũĩ na ũmanyi, na watũvuanisye twana:'),
('kam', 'MAT', 11, 26, 'ĩĩ, Asa, nĩkwĩthĩwa nĩw’o wendeesye kwaku.'),
('kam', 'MAT', 11, 27, 'Nĩnĩnengetwe maũndũ onthe nĩ Asa wakwa: na vai mũndũ wĩsĩ Mwana, ate o Asa; o na vai mũndũ wĩsĩ Asa, ate o Mwana, na mũndũ o na wĩva ũla Mwana ũkwenda kũmũvuanĩsya.'),
('kam', 'MAT', 11, 28, 'Ũkai kwakwa, inyw’onthe ala mũthĩnĩaa wĩa na ala mwĩ na mĩio mĩito, nakwa nga mũthũmũsya.'),
('kam', 'MAT', 11, 29, 'Ĩyĩkĩei ĩsoki yakwa, na mũimanyĩw’a ninyie; nũndũ nyie nĩ mũuu na nĩ na wĩnyivyo ngoonĩ: nenyu mũkasyonea ngoo syenyu ũthũmũo.'),
('kam', 'MAT', 11, 30, 'Nũndũ ĩsoki yakwa yĩti vinya, na mũio wakwa naw’o nĩ mũvũthũ.'),
('kam', 'MAT', 12, 1, 'Ĩvinda yĩu Yesũ nĩwaendie mũthenya wa savato, aivĩtĩla mĩũndanĩ ya nganũ; na amanyĩw’a make maĩ na nzaa na mambĩlĩlya ũtũla iia sya nganũ na kũya.'),
('kam', 'MAT', 12, 2, 'Ĩndĩ Avalisi moona ũu, mamwĩa, Sisya, amanyĩw’a maku nĩmekwĩka ũndũ ũtosana na ĩla mĩao ũkĩkwa mũthenya wa savato.'),
('kam', 'MAT', 12, 3, 'Ĩndĩ amea, Mũtyaasoma ũndũ Ndaviti wekie, yĩla waĩ na nzaa, we na ala maĩ nake;'),
('kam', 'MAT', 12, 4, 'ũndũ wavotie nyũmbanĩ ya Ngai, aya imũtũ ila syaiĩawa Ngai, naw’o ndwosana na ĩla mĩao akĩya we, o na ala maĩ nake, ate o athembi oka?'),
('kam', 'MAT', 12, 5, 'O na mũtyaasoma mĩaonĩ, ũndũ mũthenya wa savato ĩkalũnĩ athembi mavukasya savato, na matitalĩlawa ĩvĩtyo?'),
('kam', 'MAT', 12, 6, 'Ĩndĩ nĩngũmwĩa, kana vaa ve ũmwe mũnene kwĩ ĩkalũ.'),
('kam', 'MAT', 12, 7, 'Ĩndĩ kethĩwa nĩmwamanyie ũndũ ũtilyĩ ũndũ ũũ, Nendaa tei, na ti nthembo, mũiĩthĩwa mwasilĩla ala mate na ĩvĩtyo.'),
('kam', 'MAT', 12, 8, 'Nĩkwĩthĩwa Mwana wa mũndũ nĩ mwĩaĩi wa savato.'),
('kam', 'MAT', 12, 9, 'Na auma vau athi, na alika ĩsinakokenĩ yoo:'),
('kam', 'MAT', 12, 10, 'na sisya, kwaĩ mũndũ vo waĩ na kw’oko kwau. Na mamũkũlya, makyasya, Nĩkwosana na ĩla mĩao kũvosya andũ mũthenya wa savato? Nĩ kana mamũvinganĩsye.'),
('kam', 'MAT', 12, 11, 'Na mea, Nũũ kwenyu, ũla wĩthĩwa na ĩlondu yĩmwe, nayo yavalũka ĩimanĩ mũthenya wa savato, ndeyĩkwata ayumye?'),
('kam', 'MAT', 12, 12, 'Mũndũ ĩndĩ nde vata mũno kwĩ ĩlondu? Kwondũ wa ũu nĩkwosana na ĩla mĩao kwĩka nesa mũthenya wa savato.'),
('kam', 'MAT', 12, 13, 'Nĩvo ĩndĩ wamwĩie ũla mũndũ, Tambũũkya kw’oko kwaku. Nake atambũũkya; nakw’o kwavoa, kweethĩwa kũima ta kũla kũngĩ.'),
('kam', 'MAT', 12, 14, 'Ĩndĩ Avalisi maumaala, na mamũsamĩa ũndũ matonya kũmũaa.'),
('kam', 'MAT', 12, 15, 'Na Yesũ amanya ũu auma vau: na aingĩ mamũatĩĩa; na amavosya onthe,'),
('kam', 'MAT', 12, 16, 'na ameaĩa maikamũtavan’ye:'),
('kam', 'MAT', 12, 17, 'nĩ kana kwĩanĩw’e ũla waneeniwe nĩ mwathani Isaia, akyasya,'),
('kam', 'MAT', 12, 18, 'Sisya, mũthũkũmi wakwa ũla namũnyuvie; Mwendwa wakwa ũla ngoo yakwa yendeew’e nĩwe: Ngamwĩkĩa Veva wakwa, Nake akatavan’ya ũsilĩlo kwa Andũ‐ma‐mbaĩ‐ingĩ.'),
('kam', 'MAT', 12, 19, 'Ndakakananĩa, o na ndakokĩlya wasya; O na vai mũndũ ũkew’a wasya wake nzĩanĩ nene.'),
('kam', 'MAT', 12, 20, 'Mũangi mũkanyange ndakatũla, Na ũtambi ũtoaa syũki ndakavosya, Mũvaka yĩla wĩete ũsilĩlo kũvika ũkĩlyo.'),
('kam', 'MAT', 12, 21, 'Na Andũ‐ma‐mbaĩ‐ingĩ makeekwatya syĩtwa yake.'),
('kam', 'MAT', 12, 22, 'Nĩvo ĩndĩ waetewe mũndũ ũkwatĩtwe nĩ ndaimoni, ũtonaa na ũtaneenaa; na amũvosya, eethĩwa ũla ũtaneenaa aineena na kwona.'),
('kam', 'MAT', 12, 23, 'Na makomano onthe maseng’a, masya, Ũũ ti mwana wa Ndaviti?'),
('kam', 'MAT', 12, 24, 'Ĩndi Avalisi meew’a ũu, masya, Mũndũ ũũ ndaumasya ndaimoni, ate o na vinya wa Veelisevuli mũnene wa ndaimoni.'),
('kam', 'MAT', 12, 25, 'Na amanya mosũanĩo moo, amea, Kĩla ũsumbĩ wĩvathanĩtye nũetawe wanangĩkonĩ; na kĩla ndũa kana nyũmba ĩvathanĩtye ndĩkaũngama:'),
('kam', 'MAT', 12, 26, 'na ethĩwa Satani eumya Satani nĩwĩvathanĩtye; ũsumbĩ wake ĩndĩ ũkaũngama ata?'),
('kam', 'MAT', 12, 27, 'Nakwa ethĩwa numasya ndaimoni na vinya wa Veelisevuli, ana menyu masyumasya na vinya waũ? Kwondũ wa ũu mo makeethĩwa asilĩli menyu.'),
('kam', 'MAT', 12, 28, 'Ĩndĩ nyie ethĩwa numasya ndaimoni na Veva wa Ngai, nĩ w’o ĩndĩ ũsumbĩ wa Ngai nũmũkĩe.'),
('kam', 'MAT', 12, 29, 'Kana mũndũ atonya ata kũlika nyũmbanĩ ya mũndũ wĩ vinya, akamũvuta mĩio yake, atambĩte ũmwova ũla wĩ vinya? Na ĩndĩ aitava ila syĩ nyũmbanĩ yake.'),
('kam', 'MAT', 12, 30, 'Ũla ũte ngalĩ yakwa ũsu e ũndũ nakwa; na ũla ũtombanasya nakwa nũnyaĩĩkasya.'),
('kam', 'MAT', 12, 31, 'Kwondũ wa ũu nĩngũmwĩa, Kĩla naĩ na ũumano ikaekewa andũ; ĩndĩ ũumano wa kũmũuma ũla Veva ndũkaekewa andũ.'),
('kam', 'MAT', 12, 32, 'Na o ũla ũkamũneenea Mwana wa mũndũ ndeto, nũkaekewa; ĩndĩ o ũla ũkamũneenea Veva Mũtheu, ndakaekewa, o na nthĩ ĩno, o na ĩla ĩngĩ yũkĩte.'),
('kam', 'MAT', 12, 33, 'Seũvyai mũtĩ wĩthĩwe mũseo na ũsyao waw’o wĩthĩwe mũseo; kana seũvyai mũtĩ wĩthĩwe mũthũku na ũsyao waw’o wĩthĩwe mũthũku: nũndũ mũtĩ nũmanyĩkaa nĩ ũsyao waw’o.'),
('kam', 'MAT', 12, 34, 'Inyw’ĩ ũsyao wa nzoka mbai, mũtonya ata kũneena maũndũ maseo, mwĩ athũku? Nũndũ ũla wusũĩte ngoo nĩw’o kanyw’a ũneenaa.'),
('kam', 'MAT', 12, 35, 'Mũndũ mũseo nĩwumasya maũndũ maseo kyũmbanĩsyonĩ kyake kĩseo; na mũndũ mũthũku nĩwumasya maũndũ mathũku kyũmbanĩsyonĩ kyake kĩthũku.'),
('kam', 'MAT', 12, 36, 'Nakwa nĩngũmwĩa, kana kĩla ndeto ya mana ĩla andũ maneenaa, mũthenya wa sila makaumya ũtalo wayo.'),
('kam', 'MAT', 12, 37, 'Nũndũ kwa ndeto syaku ũkatalĩlwa ũlũngalu, na kwa ndeto syaku ũkethĩwa wĩ mũsilĩle.'),
('kam', 'MAT', 12, 38, 'Nĩvo amwe ma aandĩki na Avalisi mamũsũngĩie, makyasya, Mũmanyĩsya, nĩtũkwenda kwona kyama kwaku.'),
('kam', 'MAT', 12, 39, 'Ĩndĩ amasũngĩa, amea, Ũsyao mũthũku wa ũlaalai nũũmantha kyama; na ndwĩnengwa kyama ate o kyama kya mwathani Yona:'),
('kam', 'MAT', 12, 40, 'nũndũ o tondũ Yona waĩ nthĩnĩ wa ĩvu ya ĩkũyũ ĩnene mĩthenya ĩtatũ na matukũ atatũ; no ta ũu Mwana wa mũndũ akeethĩwa nthĩnĩ wa ngoo ya nthĩ mĩthenya ĩtatũ na matukũ atatũ.'),
('kam', 'MAT', 12, 41, 'Andũ ma Nineva makaũngama ũsilĩlonĩ vamwe na ũsyao ũũ, nao makoosilĩla: nũndũ nĩmaalyũlile ngoo ũtavan’yonĩ wa Yona; na sisyai, vaa ve ũla mũnene kwĩ Yona.'),
('kam', 'MAT', 12, 42, 'Mũsumbĩ, mũndũ mũka, wa ngalĩ ya ĩtheo nũkokĩla ũsilĩlonĩ vamwe na ũsyao ũũ, na akoosilĩla: nũndũ we nĩwokie kuma itulunĩ sya nthĩ nĩ kana ew’e ũĩ wa Solomoni; na sisyai, vaa ve ũla mũnene kwĩ Solomoni.'),
('kam', 'MAT', 12, 43, 'Ĩndĩ veva mũvuku wauma mũndũnĩ, ũvĩtĩlaa kũndũ kũte manzĩ, ũkĩmantha ũthũmũo, na ndũwonaa.'),
('kam', 'MAT', 12, 44, 'Na ĩndĩ ũkyasya, Nĩngũsyoka nyũmbanĩ yakwa ĩla naumie; naw’o wooka, weethĩa yĩ nthei, yĩ ndute, na yĩ mbanakavye.'),
('kam', 'MAT', 12, 45, 'Nĩvo ĩndĩ ũkĩthi, na ũkyosa vamwe naw’o maveva angĩ mũonza, mathũkũ kwĩ w’o, na mailika na kwĩkala vo: na mwĩkalĩle wa ĩtina wa mũndũ ũsu wĩtw’ĩka mũthũku kwĩ ũla wa mbee. No ta ũu naw’o kũkethĩwa kwa ũsyao ũũ mũthũku.'),
('kam', 'MAT', 12, 46, 'Akĩneena na ala makomano, sisya, inyia wake na ana‐a‐inyia, maũngama nza, makyenda kũneena nake.'),
('kam', 'MAT', 12, 47, 'Na mũndũ ũmwe amwĩa, Sisya, mwenyu na ana‐a‐mwenyu maũngeme nza, makyenda kũneena naku.'),
('kam', 'MAT', 12, 48, 'Asũngĩa, amwĩa ũla wamũtavya ũu, Mwaitũ nũũ? Na ana‐a‐ia naaũ?'),
('kam', 'MAT', 12, 49, 'Na amatambũũkĩsya amanyĩw’a make kw’oko, na asya, Sisyai, mwaitũ na ana‐a‐ia!'),
('kam', 'MAT', 12, 50, 'Nũndũ ũla wĩkaa kwenda kwa Asa wakwa ũla wĩ ĩtunĩ, ũsu nĩwe mwana‐a‐ia, na mwĩĩ‐tu‐a‐ia, na mwaitũ.'),
('kam', 'MAT', 13, 1, 'Mũthenya ũsu Yesũ auma nyũmbanĩ, athi, ekala nthĩ ũtee wa ũkanga.'),
('kam', 'MAT', 13, 2, 'Na makomano manene mamũmbanĩa, kwa ũu avota ngalawanĩ, ekala vo; na yĩla ĩkomano yonthe yaũngama ũtee wa ũkanga.'),
('kam', 'MAT', 13, 3, 'Nake aneena nao maũndũ maingĩ na ngelekan’yo, akyasya, Sisyai, mũvuĩi nĩwaendie kũvuĩa;'),
('kam', 'MAT', 13, 4, 'na akĩvuĩa, mbeke imwe syavalũka ũtee wa nzĩa, na nyũnyi syooka syaiya;'),
('kam', 'MAT', 13, 5, 'na ĩngĩ syavalũka mavianĩ, vala ve mũthanga mũnini: na syamea na mĩtũkĩ, nĩkwĩthĩwa ityaĩ na mũthanga mũliku:'),
('kam', 'MAT', 13, 6, 'na syũa yaaa, syavova; na nĩkwĩthĩwa ityaĩ na mĩi, syooma.'),
('kam', 'MAT', 13, 7, 'Na ingi syavalũka mĩw’anĩ; na mĩw’a yeana na yainyita;'),
('kam', 'MAT', 13, 8, 'na ingĩ syavalũka mũthanganĩ mũseo, na syasyaa ũsyao, imwe ĩana, na imwe mĩongo, thanthatũ, na imwe mĩongo ĩtatũ.'),
('kam', 'MAT', 13, 9, 'Ũla wĩ matũ, nĩew’e.'),
('kam', 'MAT', 13, 10, 'Na amanyĩw’a mooka, mamwĩa, Nĩkĩ ũũneena nao na ngelekan’yo?'),
('kam', 'MAT', 13, 11, 'Nake asũngĩa, amea, Inyw’ĩ mũnengetwe kũmanya nzama sya ũsumbĩ wa ĩtu, ĩndĩ mo maiaanengwa.'),
('kam', 'MAT', 13, 12, 'Nũndũ o ũla wĩ na kĩndũ, akanengwa, nake akaingĩvĩwa: ĩndĩ ũla ũte na kĩndũ, akoosewa o na kĩla wĩ nakyo.'),
('kam', 'MAT', 13, 13, 'Kwondũ wa ũu nĩneenaa nao na ngelekan’yo; nĩkwĩthĩwa makĩsisya matikwona, na makĩw’a matikwĩw’a, o na maiũmanya.'),
('kam', 'MAT', 13, 14, 'Na wathani wa Isaia nĩweanĩiw’e kwoo, ũla waĩtye, Kwĩw’a mũkeew’a, o na mũikamanya nongi; Na kũsisya mũkasisya, o na mũikona nongi:'),
('kam', 'MAT', 13, 15, 'Nũndũ ngoo sya andũ aa nĩ nenevu, Na matũ moo mew’aa na vinya, Na metho moo nĩmalalĩtye; Maikese kwona na metho moo, Na kwĩw’a na matũ moo, Na kũmanya na ngoo syoo, Na kwĩalyũla, Na ngĩmavosya.'),
('kam', 'MAT', 13, 16, 'Ĩndĩ nĩ maathime metho menyu, nĩkwĩthĩwa nĩmekwona; na matũ menyu, nĩkwĩthĩwa nĩmekwĩw’a.'),
('kam', 'MAT', 13, 17, 'Nũndũ nĩ w’o nĩngũmwĩa, kana nĩ athani aingĩ na andũ alũngalu ala mendie kwona maũndũ ala mũkwona, na maiaamona; na kwĩw’a maũndũ ala mũkwĩw’a, na maiaamew’a.'),
('kam', 'MAT', 13, 18, 'Ĩthukĩĩsyei inyw’ĩ ĩndĩ ĩla ngelekan’yo ya mũvuĩi.'),
('kam', 'MAT', 13, 19, 'Mũndũ o na wĩva eew’a ndeto ya ũsumbĩ, na ndeũmĩmanya, nĩvo ĩndĩ wĩũka ũla mũthũku, akavulya kĩla kĩvuĩĩtwe ngoonĩ yake. Ũsu nĩwe ũla ũvuĩĩtwe ũtee wa nzĩa.'),
('kam', 'MAT', 13, 20, 'Na ũsu ũvuĩĩtwe mavianĩ, nĩwe ũla wĩw’aa ndeto, na aiosa oyu na ũtanu;'),
('kam', 'MAT', 13, 21, 'ĩndĩ nde na mĩi nthĩnĩ wake, ĩndĩ ekalanga ĩvinda ĩnini; na yĩla thĩna kana ũnyamao wookĩla kwondũ wa ĩla ndeto, oyu ailulutĩka.'),
('kam', 'MAT', 13, 22, 'Na ũla ũvuĩĩtwe miw’anĩ, ũsu nĩwe ũla wĩw’aa ĩla ndeto; na kwĩmakĩa kwa nthĩ, na ũkengani wa ũthwii, ũinyita ĩla ndeto, nake ailea ũsyaa.'),
('kam', 'MAT', 13, 23, 'Na ũla ũvuĩĩtwe mũthanganĩ mũseo, ũsu nĩwe ũla wĩw’aa ĩla ndeto, na aimĩmanya; ũsu nĩwe ũsyaa ũsyao, ũmwe aisyaa ĩana, na ũngĩ mĩongo thanthatũ, na ũngĩ mĩongo ĩtatũ.'),
('kam', 'MAT', 13, 24, 'Amatavya ngelekan’yo ĩngĩ, akyasya, Ũsumbi wa ĩtu ũilyĩ ta mũndũ ũla wavuĩie mbeũ nzeo mũũndanĩ wake:'),
('kam', 'MAT', 13, 25, 'ĩndĩ andũ makomete, mũmaitha wake ooka na avuĩĩa ĩthaaa nganũnĩ na athi.'),
('kam', 'MAT', 13, 26, 'Ĩndĩ syamea na syamesya mathangũ na syasyaa iia, nĩvo ĩndĩ ĩthaaa yoonekie nayo.'),
('kam', 'MAT', 13, 27, 'Na ngombo sya mwene nyũmba syathi na syamwĩa, Vwana, ndwaavuĩa mbeũ nzeo mũũndanĩ waku? Ĩthaaa ĩndĩ yumĩte va?'),
('kam', 'MAT', 13, 28, 'Na asyĩa, Nĩ mũmaitha wekie ũu. Na ngombo syamwĩa, Nũkwenda tũthi tũkũe?'),
('kam', 'MAT', 13, 29, 'Ĩndĩ asya, Aiee; mũikese ũkũanĩsya nganũ mũikũa ĩthaaa.'),
('kam', 'MAT', 13, 30, 'Iekei syelĩ syĩane kũvika ngethanĩ: na ĩvinda ya ngetha ngatavya akethi, Mbee ũmban’yai ĩthaaa, mwove mĩio nĩ kana mũvĩvye; ĩndĩ nganũ ũmbanĩsyai ikũmbĩnĩ yakwa.'),
('kam', 'MAT', 13, 31, 'Amatavya ngelekan’yo ĩngĩ, akyasya, Ũsumbĩ wa ĩtu ũtilyĩ ta mbeke ya kalatali, ĩla mũndũ wosie na aivanda mũũndanĩ wake:'),
('kam', 'MAT', 13, 32, 'nayo nĩ nini kwĩ mbeũ syonthe; ĩndĩ yeana, yĩthĩawa yĩ nene mbee wa nyũnyi syonthe, na ĩkĩtw’ĩka kĩtĩ, ũndũ nyũnyi sya yayaya syũkaa na kwĩkala mbongenĩ syakyo.'),
('kam', 'MAT', 13, 33, 'Amatavya ngelekan’yo ĩngĩ; Ũsumbĩ wa ĩtu ũilyĩ ta ĩlawa, yĩla mũndũ mũka wosie, na avitha mĩtanĩ ĩtatũ ya mũtu, na w’onthe wakaata.'),
('kam', 'MAT', 13, 34, 'Maũndũ asu onthe Yesu amatavisye makomano na ngelekan’yo; na vate ngelekan’yo ndaaneena nao:'),
('kam', 'MAT', 13, 35, 'nĩ kana kwĩanĩw’e ũla waneeniwe nĩ mwathani, akyasya, Ngaathamya kanyw’a wakwa na ngelekan’yo; Ngaweta maũndũ ala mavithiwe kuma nthĩ yoombwa.'),
('kam', 'MAT', 13, 36, 'Na ĩndĩ atia makomano, athi nyũmba: na amanyĩw’a make mathi vala ũĩ, makyasya, Twon’ye ithyĩ ĩla ngelekan’yo ya ĩthaaa ya mũũndanĩ.'),
('kam', 'MAT', 13, 37, 'Na asũngĩa, asya, Ũsu ũvuĩaa mbeũ ĩla nzeo nĩ Mwana wa mũndũ;'),
('kam', 'MAT', 13, 38, 'na ũla mũũnda nĩ nthĩ; na mbeũ ĩla nzeo nĩ ana ma ũsumbĩ; na ĩthaaa nĩyo ana ma ũla mũthũku;'),
('kam', 'MAT', 13, 39, 'na mũmaitha ũla waivuĩie nĩ ndevili: na ngetha nĩ wĩanĩu wa ĩvinda yĩĩ; na akethi nĩ alaĩka.'),
('kam', 'MAT', 13, 40, 'Na ĩndĩ o ũndũ ĩthaaa yũmbanaw’a na kũvĩvw’a na mwaki; nĩw’o kũkethĩwa wĩanĩu wa ĩvinda yĩĩ.'),
('kam', 'MAT', 13, 41, 'Mwana wa mũndũ akatũma alaĩka make, nao makoomban’ya molulutĩkyo onthe maumw’e ũsumbĩnĩ wake, na ala mekaa mothũku,'),
('kam', 'MAT', 13, 42, 'na makamekya ikonĩ ĩnene yĩ mwaki: vo vakethĩwa kĩĩo na kũvevetan’ya maeo.'),
('kam', 'MAT', 13, 43, 'Nĩvo ĩndĩ ala alũngalu makatisa ta syũa ũsumbĩnĩ wa Ĩthe woo. Ũla wĩ matũ, nĩew’e.'),
('kam', 'MAT', 13, 44, 'Ũsumbĩ wa ĩtu ũilyĩ ta ũthwii mwie ũvithĩtwe mũũndanĩ; ũla mũndũ wonie, na oovithĩĩa; na kwondũ wa ũtanu wake athi na athoosya syĩndũ syonthe ila waĩ nasyo, na athooa mũũnda ũsu.'),
('kam', 'MAT', 13, 45, 'Ĩngĩ, ũsumbĩ wa ĩtu ũilyĩ ta mũndũ mũtandĩthya, aimantha malũlũ maseo:'),
('kam', 'MAT', 13, 46, 'na oona lũlũ ũmwe wa thooa mũnene, athi athoosya syĩndũ syonthe ila waĩ nasyo, oothooa.'),
('kam', 'MAT', 13, 47, 'Ĩngĩ, ũsumbĩ wa ĩtu ũilyĩ ta kĩtei, kĩla kyekiw’e ũkanganĩ, na kyoomban’ya kĩla mũthemba:'),
('kam', 'MAT', 13, 48, 'nakyo kyausũa, makĩkusya ũtee wa ũkanga; na mekala nthĩ, manyuvĩĩa ĩla mĩseo mĩionĩ, ĩndĩ ĩla mĩthũku mekya ũtee.'),
('kam', 'MAT', 13, 49, 'Kũkeethĩwa ta ũu wĩanĩunĩ wa ĩvinda yĩĩ: alaĩka makooka, na makavathan’ya athũku na ala alũngalu,'),
('kam', 'MAT', 13, 50, 'na makamekya ikonĩ ĩnene yĩ mwaki: vo vakethĩwa kĩĩo na kũvevetan’ya maeo.'),
('kam', 'MAT', 13, 51, 'Nĩmwamanya maũndũ asu onthe? Mamwĩa, Ĩĩ.'),
('kam', 'MAT', 13, 52, 'Nake amea, Kwondũ wa ũu kĩla mũandĩki watw’ĩkĩthĩtw’e mũmanyĩw’a wa ũsumbĩ wa ĩtu ailyĩ ta mũndũ mwene wa nyũmba, ũla wumasya kyũmbanĩsyonĩ kyake syĩndũ nzaũ na ila ngũũ.'),
('kam', 'MAT', 13, 53, 'Na kweethĩwa, Yesũ amina ngelekan’yo isu, auma vo athi.'),
('kam', 'MAT', 13, 54, 'Na avika nthĩ ĩla yake amamanyĩsya ĩsinakokenĩ yoo, mũvaka maseng’a, na masya, Mũndũ ũũ aumĩtye va ũĩ ũũ, na mavinya aa?'),
('kam', 'MAT', 13, 55, 'Ũũ ti mwana wa mũseũvya wa mbwaũ? Inyia wake ndetawa Meli? Na ana‐a‐inyia ti Yakovo, na Yosevu, na Simoni, na Yutasi?'),
('kam', 'MAT', 13, 56, 'Na eĩtu‐a‐inyia, mati kwitũ onthe? Ĩndĩ ũũ aumĩtye va maũndũ aa onthe?'),
('kam', 'MAT', 13, 57, 'Na malulutĩkw’a nĩwe. Ĩndĩ Yesũ amea, Mwathani ndalea kwĩthĩwa na ndaĩa, ate o nthĩ yake mwene, na nyũmbanĩ yake mwene.'),
('kam', 'MAT', 13, 58, 'Na ndaaĩka mavinya maingĩ vo nũndũ wa kũlea kwĩtĩkĩla kwoo.'),
('kam', 'MAT', 14, 1, 'Ĩvĩnda yĩu mũsumbĩ Elote eew’a ũvoo wa Yesũ,'),
('kam', 'MAT', 14, 2, 'na amea athũkũmi make, Ũsu nĩwe Yoana ũla Mũvatisi; nũthayũũkĩte kuma akw’ũnĩ; na kwondũ wa ũu mavinya aa metethya wĩa nthĩnĩ wake.'),
('kam', 'MAT', 14, 3, 'Nũndũ Elote aĩ anamũkwata Yoana, akamwova, na akamwĩkĩa kolokolonĩ kwondũ wa Elotia, mũka wa Vilivu mwana‐a‐inyia.'),
('kam', 'MAT', 14, 4, 'Nĩkwĩthĩwa Yoana amũtavisye, Kũtyosana na mĩao we kwĩthĩwa nake.'),
('kam', 'MAT', 14, 5, 'Na akyenda kũmũaa, akĩa nguthu ya andũ, nũndũ mamwonaa e mwathani'),
('kam', 'MAT', 14, 6, 'Ĩndĩ yĩla mũthenya wa kũsyawa kwa Elote wavikie, mwĩĩtu wa Elotia asũngĩa katĩ woo, na amwendeesya Elote.'),
('kam', 'MAT', 14, 7, 'Na ĩndĩ amwatha na wĩvĩto kũmũnenga kĩla wĩmwĩtya o na kĩva.'),
('kam', 'MAT', 14, 8, 'Nake, asilw’a nĩ nyinyia, asya, Nenga mũtwe wa Mũvatisi Yoana vaa ĩsaaninĩ.'),
('kam', 'MAT', 14, 9, 'Na ũla mũsumbĩ eew’a woo; ĩndĩ kwondũ wa mawĩvĩto make, na kwondũ wa ala mailyĩ lĩunĩ vamwe nake, eeaa anengwe;'),
('kam', 'MAT', 14, 10, 'na atũma mũndũ amũtila Yoana mũtwe e kolokolonĩ.'),
('kam', 'MAT', 14, 11, 'Na mũtwe wake waetwe wĩ ĩsaaninĩ, wanengwa ũla mwĩĩtu: nake amũtwaĩa nyinyia.'),
('kam', 'MAT', 14, 12, 'Na amanyĩw’a make mooka, moosa kimba, makĩthika; na mathi mamũtavya Yesũ.'),
('kam', 'MAT', 14, 13, 'Na Yesũ eew’a ũvoo ũsu, auma vau na ngalawa, athi e weka vandũ vate andũ: na makomano meew’a, mamũatĩĩa na nyaĩĩ kuma ndũanĩ syoo.'),
('kam', 'MAT', 14, 14, 'Na aumĩla, na oona ĩkomano ĩnene ya andũ, na amew’ĩa tei, na avosya awau moo.'),
('kam', 'MAT', 14, 15, 'Na kwavika wĩoo, amanyĩw’a mathi vala ũĩ, makyasya, Vaa tũĩ nĩ weũnĩ, na ĩngĩ o na yu ĩvinda nĩ ĩthelu; ĩmbũũkya, makomano mathi mĩsyĩ, makethooee lĩu.'),
('kam', 'MAT', 14, 16, 'Ĩndĩ Yesũ amea, Mati na vata wa kuma kũũ mathi; manengei lĩu e inyw’ĩ.'),
('kam', 'MAT', 14, 17, 'Nao mamwĩa, Vaa tũi na kĩndũ ate o imũtũ itano na makũyũ elĩ.'),
('kam', 'MAT', 14, 18, 'Na amea, Ndeteei isu vaa.'),
('kam', 'MAT', 14, 19, 'Na ameaĩa makomano mekale nthĩ nyekinĩ; na oosa ila imũtũ itano na ala makũyũ elĩ, na ang’elela ĩtunĩ, aiathima, na aĩtilanga, na anenga amanyĩw’a make ila imũtũ, na amanyĩw’a manenga makomano.'),
('kam', 'MAT', 14, 20, 'Na onthe maya, mavũna: na moosa ũtialo wa ilungu isu ndile, ikavũ ĩkũmi na ilĩ syausũa.'),
('kam', 'MAT', 14, 21, 'Na ala maĩe maĩ andũ ta ngili itano, eka aka na syana.'),
('kam', 'MAT', 14, 22, 'Na oyu amathing’ĩĩsya amanyĩw’a make malike ngalawanĩ, mathi mbee wake kũvika mũingo ũngĩ, mũvaka we amombũũkya makomano.'),
('kam', 'MAT', 14, 23, 'Na amombũũkya makomano, ambata kĩĩmanĩ e weka kũvoya: na kwavika wĩoo, e o vo e weka.'),
('kam', 'MAT', 14, 24, 'Ĩvĩnda yĩu ĩla ngalawa yaĩ ũkanganĩ katĩ, ĩkyũkĩlangw’a nĩ itulumo; nũndũ kĩseve nĩkyamathaũĩtye.'),
('kam', 'MAT', 14, 25, 'Na ũsyaĩĩsyo wa kana wa ũtukũ athi vala maĩ akinyĩle ũkanganĩ ĩũlũ.'),
('kam', 'MAT', 14, 26, 'Na amanyĩw’a mamwona akinyĩle ũkanganĩ ĩũlũ, maũũya, makyasya, Nĩ ĩimũ; na makaya nĩ w’ĩa.'),
('kam', 'MAT', 14, 27, 'Ĩndĩ oyu Yesũ aneena nao, akyasya, Ĩthĩwai na ũnyiau; ninyie; mũikakĩe.'),
('kam', 'MAT', 14, 28, 'Na Vetelo amũsũngĩa, asya, Mwĩaĩi, ethĩwa nue, mbĩa nũke vala ũĩ, nginyĩle manzĩnĩ ĩũlũ.'),
('kam', 'MAT', 14, 29, 'Na amwĩa, Ũka. Na Vetelo auma ngalawanĩ, na akinyĩla manzĩnĩ ĩũlũ, nĩ kana aende vala ve Yesũ.'),
('kam', 'MAT', 14, 30, 'Ĩndĩ oona kĩseve kingĩ, aya w’ĩa; na akyambĩlĩlya ũlika manzĩnĩ, akaya, akyasya, Mwĩaĩi, ndangĩĩa.'),
('kam', 'MAT', 14, 31, 'Na kavinda kau Yesũ atambũũkya kw’oko kwake, amũkwata, na amwĩa, We wa mũĩkĩĩo mũnini, nũndũ wa kĩ waya nzika?'),
('kam', 'MAT', 14, 32, 'Na mambata ngalawanĩ, kĩseve kyakilya.'),
('kam', 'MAT', 14, 33, 'Na ala maĩ ngalawanĩ mamũthaitha, makyasya, Nĩ w’o, we wĩ Mwana wa Ngai.'),
('kam', 'MAT', 14, 34, 'Na mainga, mavika nthĩ ya Kenesaleti.'),
('kam', 'MAT', 14, 35, 'Na aũme ma vandũ vau mamũmanya, matũma andũ nthĩ ĩsu yonthe, mamũetee onthe ala maĩ awau;'),
('kam', 'MAT', 14, 36, 'mamwĩsũva makiite o na ethĩwa no ũtiivo wa ngũa yake: na onthe ala makiitie mavow’a vyũ.'),
('kam', 'MAT', 15, 1, 'Nĩvo Avalisi na aandĩki maumie Yelusaleme mathi vala ve Yesũ, makyasya,'),
('kam', 'MAT', 15, 2, 'Nĩ ũndũ wa kĩ amanyĩw’a maku mavĩtasya mokũũ ma atumĩa? Nũndũ makĩya matithambaa nzaa.'),
('kam', 'MAT', 15, 3, 'Nake asũngĩa, amea, Nĩkĩ inyw’ĩ nenyu mũvĩtasya mĩao ya Ngai nũndũ wa mokũũ menyu?'),
('kam', 'MAT', 15, 4, 'Nĩkwĩthĩwa Ngai nĩwaisye, Taĩa au na mwenyu: na, Ũla ũnũkũuma ĩthe kana nyinyia, nakw’e.'),
('kam', 'MAT', 15, 5, 'Ĩndĩ inyw’ĩ mwĩasya, O ũla ũkamwĩa ĩthe kana nyinyia, Kĩndũ o na kĩva kĩla naĩ ndonya ũkũnenga nĩkĩnengetwe Ngai;'),
('kam', 'MAT', 15, 6, 'ũsu ndeũtaĩa ĩthe. Na inyw’ĩ nĩmũmyanangĩte ndeto ya Ngai kwondũ wa mokũũ menyu.'),
('kam', 'MAT', 15, 7, 'Inyw’ĩ angangan’ya, Isaia nĩwathanie nesa ũndũ wenyu, akyasya,'),
('kam', 'MAT', 15, 8, 'Andũ aa nĩmandaĩaa na ilomo syoo; Ĩndĩ ngoo syoo syĩ kũasa nakwa.'),
('kam', 'MAT', 15, 9, 'Nao manthaithaa ũthaithi wa mana, Makĩmanyĩsya momanyĩsyo, nao nĩ mĩao ya andũ.'),
('kam', 'MAT', 15, 10, 'Na ayĩta ĩkomano yũke kwake, na ayĩa, Ĩthuskĩĩsyei, mũmanye:'),
('kam', 'MAT', 15, 11, 'ti kĩla kĩlikaa kanyw’anĩ kĩthũkasya mũndũ; ĩndĩ nĩ kĩla kyumaa kanyw’anĩ, nĩkyo kũthũkasya mũndũ.'),
('kam', 'MAT', 15, 12, 'Nĩvo amanyĩw’a make mookie, na mamwĩa, Nĩwĩsĩ kana Avalisi meew’a ũndũ ũsu nĩmalulutĩkilw’e?'),
('kam', 'MAT', 15, 13, 'Ĩndĩ asũngĩa, na asya, Kĩla kĩtavandĩtwe nĩ Asa wakwa wa ĩtunĩ, kĩkakũwa.'),
('kam', 'MAT', 15, 14, 'Maekei mo: nĩ atongoi mate metho. Na ethĩwa kĩlilinda kĩkatongoesya kĩlilinda kĩngĩ, ikavalũka ĩimanĩ syelĩ.'),
('kam', 'MAT', 15, 15, 'Na Vetelo asũngĩa, amwĩa, Tũmanyithye ngelekan’yo ĩsu.'),
('kam', 'MAT', 15, 16, 'Nake asya, Nenyu o na yu mũi na ũmanyi?'),
('kam', 'MAT', 15, 17, 'Mũtinamba ũmanya, kana kĩndũ o na kĩva kĩlikaa kanyw’anĩ nĩkĩvĩtĩlaa ĩvunĩ, na nĩkĩũmĩwa?'),
('kam', 'MAT', 15, 18, 'Ĩndĩ maũndũ ala maumaa kanyw’anĩ maumaa ngoonĩ; na nĩmo mathũkasya mũndũ.'),
('kam', 'MAT', 15, 19, 'Nũndũ ngoonĩ nĩvo vaumaa malilikano mathũku, maũaani, molaalai, mawathavu, mong’ei, ũkũsĩ wa ũvũngũ, moumano:'),
('kam', 'MAT', 15, 20, 'asu nĩo maũndũ ala mathũkasya mũndũ; ĩndĩ kũya na nzaa itathambĩtwe kũithũkasya mũndũ.'),
('kam', 'MAT', 15, 21, 'Na Yesũ auma vau, athi ngalĩ sya Tile na Sitoni.'),
('kam', 'MAT', 15, 22, 'Na sisya, mũndũ mũka Mũkanaani auma mĩvakanĩ ĩsu, na aneena na wasya mũnene, akyasya, Mbĩw’ĩa tei we, Mwĩaĩi, mwana wa Ndaviti; mwĩĩtu wakwa nũnũũthĩnw’a mũno nĩ ndaimoni.'),
('kam', 'MAT', 15, 23, 'Ĩndĩ we ndaamũsũngĩa ndeto. Na amanyĩw’a make mooka na mamwĩsũva, makyasya, Mũeke athi; nũndũ elonzanĩlya ĩtina waitũ.'),
('kam', 'MAT', 15, 24, 'Ĩndĩ we asũngia, asya, Ndyaatũmwa ate o kwa malondu mau ma nyũmba ya Isilaeli.'),
('kam', 'MAT', 15, 25, 'Ĩndĩ ooka amũthaitha, akyasya, Mwĩaĩi, ndethya.'),
('kam', 'MAT', 15, 26, 'Na asũngĩa, asya, Ti ũseo kwosa lĩu wa syana na kwĩkĩsya ngitĩ.'),
('kam', 'MAT', 15, 27, 'Ĩndĩ we asya, Ĩĩ, Mwĩaĩi: ĩndĩ o na ngitĩ niĩsaa tũlungu tũla tũvalũkaa kuma mesanĩ ya mavwana masyo.'),
('kam', 'MAT', 15, 28, 'Nĩvo Yesũ wasũngĩie, amwĩa, We mũndũ mũka, mũĩkĩĩo waku nĩ mũnene: nĩkwĩkĩke kwaku o ũndũ ũkwenda. Na mwĩĩtu wake avow’a kuma kavinda o kau.'),
('kam', 'MAT', 15, 29, 'Na Yesũ auma vau athi, na athengeea ũkanga wa Kalilii; na ambata kĩĩmanĩ, na ekala nthĩ vo.'),
('kam', 'MAT', 15, 30, 'Na makomano manene mooka vala ũĩ, me na syonze, na ililinda, na ala mataneenaa, na ala au mamutha, na angĩ aingĩ, mamaia maũũnĩ ma Yesũ; na amavosya:'),
('kam', 'MAT', 15, 31, 'mũvaka yĩla ĩkomano yaseng’a, yoona ala mataaneena maineena, na ala au mamutha me aima, na ila syonze iikinya, na ililinda ikyona: na mamũtaĩa Ngai wa Isilaeli.'),
('kam', 'MAT', 15, 32, 'Na Yesũ ameta amanyĩw’a make moke vala ũĩ, na asya, Nĩngũyĩw’ĩa ĩkomano tei, nĩkwĩthĩwa yu nĩ matukũ atatũ mekalĩte nakwa na mati na kĩndũ kya ũya: na ndikwenda kũmombũũkya me na nzaa, maikese ũnyalĩla nzĩanĩ.'),
('kam', 'MAT', 15, 33, 'Na amanyĩw’a mamũkũlya, Twĩumya va kũũ weũnĩ, imũtũ singĩvĩte ũu sya kũvũn’ya ĩkomano yĩnenevete ũu?'),
('kam', 'MAT', 15, 34, 'Na Yesũ amea, Mwĩ na imũtũ syĩana? Na masya, Mũonza, na tũmakũyũ tũvũthũ.'),
('kam', 'MAT', 15, 35, 'Na eeaĩe ĩkomano yĩkale nthĩ;'),
('kam', 'MAT', 15, 36, 'nake oosa ila imũtũ mũonza na tũla tũmakũyũ; na atũnga mũvea, na atilanga, na anenga amanyĩw’a, na amanyĩw’a manenga makomano.'),
('kam', 'MAT', 15, 37, 'Na onthe maya, mavũna: na moosa ũtialo wa ilungu ila ndile, ikavũ mũonza syausũa.'),
('kam', 'MAT', 15, 38, 'Na ala maĩe maĩ aũme ngili inya, eka aka na syana.'),
('kam', 'MAT', 15, 39, 'Na oombũũkya makomano, na alika ngalawanĩ, athi mĩvakanĩ ya Makatani.'),
('kam', 'MAT', 16, 1, 'Na Avalisi na Asatukai mooka mamũvoya amon’ye kyama kyume ĩtunĩ, makĩmũtata.'),
('kam', 'MAT', 16, 2, 'Ĩndĩ asũngĩa na amea, Kũituka, inyw’ĩ mwĩasya, Kũkeethĩwa kwĩ kũseo: nũndũ ĩtu nĩ ĩtune.'),
('kam', 'MAT', 16, 3, 'Na kwĩ kĩoko mwĩasya, Kũkeethĩwa kwĩ kũthũku ũmũnthĩ: nĩkwĩthĩwa ĩtu nĩ ĩtune na nĩ ĩniinũkanu. Inyw’ĩ nĩmwĩsĩ kũmanya ũthyũ wa ĩtu; ĩndĩ syama sya mavinda aa mũitonya kwimanya.'),
('kam', 'MAT', 16, 4, 'Ũsyao mũthũku na wa ũlaalai wĩmantha kyama; ĩndĩ ndũkanengwa kyama, ate o kĩla kyama kya Yona. Na amatia, athi.'),
('kam', 'MAT', 16, 5, 'Na amanyĩw’a mathi mũingo ũla ũngĩ, na moolwa nĩ ũkua imũtũ.'),
('kam', 'MAT', 16, 6, 'Na Yesũ amea, Ĩmanyĩlĩlei na ĩsũvĩei yĩla ĩlawa ya Avalisi na Asatukai.'),
('kam', 'MAT', 16, 7, 'Na masũanĩa ene kwa ene, makyasya, Nĩkwĩthĩwa tũinakua imũtũ.'),
('kam', 'MAT', 16, 8, 'Na Yesũ amanya ũu asya, Ĩnyw’ĩ ma mũĩkĩĩo mũnini, nĩkĩ mũũsũanĩa inyw’ĩ kwa inyw’ĩ, nĩkwĩthĩwa mũi na imũtũ?'),
('kam', 'MAT', 16, 9, 'Mũinamba kũmanya, o na mũiũlilikana ila imũtũ itano sya ala ngili itano, na ũndũ ikavũ syeanaa ila mwoosie?'),
('kam', 'MAT', 16, 10, 'O na ila imũtũ mũonza sya ala ngili inya, na ũndũ ikavũ syeanaa ila mwoosie?'),
('kam', 'MAT', 16, 11, 'Kũilyĩ ata ĩndĩ, ũndũ mũteũmanya kana ndinaneena nenyu ũndũ wa imũtũ? Ĩndĩ ĩsũvĩei ĩlawa ya Avalisi na Asatukai.'),
('kam', 'MAT', 16, 12, 'Na ĩndĩ mamanya kana ndanamatavya mesũvĩe ĩlawa ya imũtũ, ĩndĩ nĩ ĩlawa ya ũmanyĩsyo wa Avalisi na Asatukai.'),
('kam', 'MAT', 16, 13, 'Na Yesũ alika kĩvalonĩ kya Kaisalea ya Vilivu, amakũlya amanyĩw’a make, akyasya, Andũ measya Mwana wa mũndũ nũũ?'),
('kam', 'MAT', 16, 14, 'Na masya, Amwe measya nĩ Mũvatisi Yoana; angĩ, nĩ Eliya; na angĩ, nĩ Yelemia, kana ũmwe wa athani.'),
('kam', 'MAT', 16, 15, 'Amea, Ĩndĩ inyw’ĩ mwĩasya nyie nĩ ũũ?'),
('kam', 'MAT', 16, 16, 'Na Simoni Vetelo asũngĩa na asya, We nue Klĩsto, Mwana wa Ngai ũla wĩ thayũ.'),
('kam', 'MAT', 16, 17, 'Na Yesũ asũngĩa na amwĩa, Wĩ mũathime we, Simoni mwana wa Yona: nĩkwĩthĩwa mwĩĩ na nthakame itikwonetye ũu, ĩndĩ nĩ Asa wakwa ũla wĩ ĩtunĩ.'),
('kam', 'MAT', 16, 18, 'Nakwa nĩngũkwĩa, kana nue Vetelo, na ĩvianĩ yĩĩ ngaaka ĩkanisa yakwa; na mbingĩlo sya vala maveva ma akw’ũ mekaala itikayĩkĩlya vinya.'),
('kam', 'MAT', 16, 19, 'Nakwa ngakũnenga we mbungũo sya ũsumbĩ wa ĩtu: na ũndũ o na wĩva ũla ũkova kũũ nthĩ, ũkethĩwa wĩ wove ĩtunĩ; na ũndũ o na wĩva ũla ũkathasya kũũ nthi, ũkethĩwa wĩ ũthasye ĩtunĩ.'),
('kam', 'MAT', 16, 20, 'Nĩvo wameaĩe amanyĩw’a make maikatavye mũndũ kana we nĩwe Klĩsto.'),
('kam', 'MAT', 16, 21, 'Kuma ĩvinda yĩu Yesũ ambĩlĩlya kũmon’ya amanyĩw’a make, kana ndatĩa ũthi Yelusaleme, na kũthĩnw’a na mathĩna maingĩ nĩ atumĩa na athembi anene na aandĩki, na kũawa, na kũthayũũkw’a mũthenya wa katatũ.'),
('kam', 'MAT', 16, 22, 'Na Vetelo amwosa, na ambĩlĩlya kũmũkan’ya, akyasya, Ũu nĩwĩthĩwe kũasa naku, Mwĩaĩi; ũu ndũkethĩwa kwaku o na ĩndĩĩ.'),
('kam', 'MAT', 16, 23, 'Ĩndĩ eethyũũa, na amwĩa Vetelo, Enda ĩtina wakwa, Satani: we wĩ ũlulutĩkyo kwakwa: nũndũ ndũũlilikana maũndũ ma Ngai, ĩndĩ nĩ ala ma andũ.'),
('kam', 'MAT', 16, 24, 'Nĩvo Yesũ wameie amanyĩw’a make, Ethĩwa mũndũ o na wĩva nũnũkwenda kũmbikĩla, nĩelee mwene, na kwĩyaĩkya ngelan’yo yake, na akĩmbikĩla.'),
('kam', 'MAT', 16, 25, 'Nũndũ o ũla ũnũkwenda kũvĩtya thayũ wake akawasya: na o ũla ũkawasya thayũ wake kwondũ wakwa akawona ĩngĩ.'),
('kam', 'MAT', 16, 26, 'Nũndũ mũndũ aunwa nĩ kyaũ, o na akosa nthĩ nima, na akyasya thayũ wake? Kana mũndũ akakũan’ya thayũ wake na kyaũ?'),
('kam', 'MAT', 16, 27, 'Nũndũ Mwana wa mũndũ akooka ũtheunĩ mũtisu wa Ĩthe wake vamwe na alaĩka make; na ĩvinda yĩu akamũĩva kĩla mũndũ kwĩanana na kwĩka kwake.'),
('kam', 'MAT', 16, 28, 'Nĩ w’o nĩngũmwĩa, Ve andũ amwe ma aa maũngeme vaa, ala matakasama kĩkw’ũ nongi, matanamba kwona Mwana wa mũndũ akyũka ũsumbĩnĩ wake.'),
('kam', 'MAT', 17, 1, 'Na ĩtina wa matukũ thanthatũ Yesũ oosa Vetelo, na Yakovo, na Yoana mwana‐a‐inyia, ambata nao me oka kĩĩmanĩ kĩtũlu:'),
('kam', 'MAT', 17, 2, 'na mũvw’ano wake waalyũka mene; na ũthyũ wake watisa ta syũa, na ngũa syake syeeũva ta kyeni.'),
('kam', 'MAT', 17, 3, 'Na sisya, Mose na Eliya mamaumĩlĩla makĩneenan’ya nake.'),
('kam', 'MAT', 17, 4, 'Na Vetelo asũngĩa na amwĩa Yesũ, Mwĩaĩi, nĩ ũseo kwitũ kwĩthĩwa vaa: ethĩwa nũkwenda, nĩngwaka vaa malwanda atatũ; yĩmwe yaku, na yĩngĩ ya Mose, na yĩngĩ ya Eliya.'),
('kam', 'MAT', 17, 5, 'Akĩneena, sisya, ĩthweo ĩtisũku yamekĩa muunyĩ: na sisya, wasya wauma ĩthweonĩ, ũkyasya, Ũũ nĩwe Mwana wakwa mwendwa, ũla nendeew’e nĩwe; mwĩw’ei we.'),
('kam', 'MAT', 17, 6, 'Na amanyĩw’a mawĩw’a, mavalũka na mothyũ moo, na makĩa mũno.'),
('kam', 'MAT', 17, 7, 'Na Yesũ ooka amakiita, na asya, Ũkĩlai, mũikakĩe.'),
('kam', 'MAT', 17, 8, 'Na makyũkĩlya metho moo, maiaaona mũndũ ate o Yesũ weka.'),
('kam', 'MAT', 17, 9, 'Na makĩtheea kuma kĩĩmanĩ, Yesũ ameaĩa, akyasya, Mũikatavye mũndũ ũvoo wa woni ũsu, mũvaka Mwana wa mũndũ athayũũka kuma kwa akw’ũ.'),
('kam', 'MAT', 17, 10, 'Na amanyĩw’a make mamũkũlya, makyasya, Nĩkĩ ĩndĩ aandĩki mekwasya mũvaka Eliya ambe kũka?'),
('kam', 'MAT', 17, 11, 'Nake asũngĩa, amea, Nĩ w’o Eliya nĩwũkĩte, na kũtũnga maũndũ onthe kwĩthĩwa meũ:'),
('kam', 'MAT', 17, 12, 'ĩndĩ nĩngũmwĩa, kana Eliya nĩwokie, na maiaamũmanya, ĩndĩ mamwĩkie o ũndũ mendie. No ta ũu Mwana wa mũndũ nake akathĩnw’a nĩo.'),
('kam', 'MAT', 17, 13, 'Nĩvo ala amanyĩw’a mamanyie kana aneena nao ũndũ wa Yoana Mũvatisi.'),
('kam', 'MAT', 17, 14, 'Na mavika vala ve yĩla ĩkomano, mũndũ ooka amũtulĩlya ndu, akyasya,'),
('kam', 'MAT', 17, 15, 'Mwĩaĩi, mwĩw’ĩe mwana wakwa tei: nũndũ e na ũwau wa mũng’uthũko, nake enyamaw’a mũno; nũndũ mavinda maingĩ avalũkaa mwakinĩ, na mavinda maingĩ manzĩnĩ.'),
('kam', 'MAT', 17, 16, 'Nakwa namũete kwa amanyĩw’a maku, na mainatonya kũmũvosya.'),
('kam', 'MAT', 17, 17, 'Na Yesũ asũngĩa, asya, Ũsyao ũũ ũte na mũĩkĩĩo na mũemu, ngeethĩwa vamwe nenyu ĩvinda yĩana ata? Nĩmũmĩĩsya ĩvinda yĩana ata? Mũetei vaa nĩĩ.'),
('kam', 'MAT', 17, 18, 'Na Yesũ amĩkan’ya; na ĩla ndaimoni yauma: na kĩmwana kyavoa kuma ĩvinda yĩu.'),
('kam', 'MAT', 17, 19, 'Nĩvo ĩndĩ ala amanyĩw’a maendie vala ve Yesũ kasama, masya, Nĩkĩ ithyĩ tũinatonya kũmyumya?'),
('kam', 'MAT', 17, 20, 'Na amea, Nũndũ wa kũnyivĩwa nĩ mũĩkĩĩo: nũndũ nĩ w’o nĩngũmwĩa, Ethĩwa mwĩ na mũĩkĩĩo: wĩana kaveke ka kalatali, mũkatavya kĩĩma kĩĩ, Uma vau ũĩ ũthi vaya; nakyo kĩkathi; o na vai ũndũ ũtakatonyeka kwenyu.'),
('kam', 'MAT', 17, 21, 'Ĩndĩ mũthemba ũũ ndumaa ate ũndũ wa kũvoya na kũtĩĩa ũya.'),
('kam', 'MAT', 17, 22, 'Na yĩla mekalĩte Kalilii, Yesũ amea, Mwana wa mũndũ ethi kũnenganwe mokonĩ ma andũ;'),
('kam', 'MAT', 17, 23, 'nao makamũaa, na mũthenya wa katatũ akathayũũkw’a. Nao meew’a woo mũno.'),
('kam', 'MAT', 17, 24, 'Na mavika Kavelinaumi, ala maumasya koti wa nyunzu sekeli mathi kwa Vetelo, masya, Mũmanyĩsya wenyu ndaumasya ĩla nyunzu ya sekeli?'),
('kam', 'MAT', 17, 25, 'Asya, Ĩĩ. Na alika nyũmba, Yesũ amba ũmũkũlya, akyasya, Wĩona ata, Simoni? Asumbĩ ma nthĩ maumasya koti kana ũelo kwa aaũ? Kwa ana moo, kana kwa aenĩ?'),
('kam', 'MAT', 17, 26, 'Na asya, Kwa aeni. Yesũ amwĩa, Na ĩndĩ ana moo nĩ athasye.'),
('kam', 'MAT', 17, 27, 'Ĩndĩ, nĩ kana tuĩkese ũmalulutĩkya, enda ũkanganĩ, noyĩkya ndoano, na ĩkũyũ yĩla yĩamba ũkwatw’a yose; na wayathamũkan’ya kanyw’a, ũkoona sekeli: wose ũkamanenge kwondũ wakwa na kwondũ waku.'),
('kam', 'MAT', 18, 1, 'Saa ũsu amanyĩw’a mooka vala ve Yesũ, makyasya, Nũũ ĩndĩ ũla mũnene ũsumbĩnĩ wa ĩtu?'),
('kam', 'MAT', 18, 2, 'Na eeta kana kanini, akaũngamya katĩ woo,'),
('kam', 'MAT', 18, 3, 'na asya, Nĩ w’o nĩngũmwĩa, Mwalea kũalyũka mwĩthĩwe ta syana nini, mũikalika nongi ũsumbĩnĩ wa ĩtu.'),
('kam', 'MAT', 18, 4, 'O ũla ĩndĩ ũkenyivya ta kana kaa kanini, ũsu nĩ mũnene ũsumbĩnĩ wa ĩtu.'),
('kam', 'MAT', 18, 5, 'Na o ũla ũkosa kana kamwe kanini kailyĩ kaa syĩtwanĩ yakwa embosa nyie:'),
('kam', 'MAT', 18, 6, 'ĩndĩ ũla ũkalulutĩkya kamwe ka tũũ tũnini tũla tũmbĩtĩkĩlaa, nĩwaĩle kwoveewa ngingo ĩvia ĩnene ya ũthia, na akĩkw’a kyũngũnĩ kya ũkanga.'),
('kam', 'MAT', 18, 7, 'Woo nĩ wa nthĩ kwondũ wa molulutĩkyo! Nũndũ molulutĩkyo maitĩa kũka; ĩndĩ woo nĩ wa mũndũ ũla ũtumaa ũlulutĩkyo wũka!'),
('kam', 'MAT', 18, 8, 'Na ethĩwa kw’oko kwaku kana kũũ kwaku nĩkũũkũlulutĩkya, kũtile, wĩkye kũasa naku: nĩ ũseo kwaku ũlike thayũnĩ na kĩthu kya kw’oko kana kya kũũ, kwĩ ũkĩkw’a wĩ na moko elĩ kana maũũ elĩ mwakinĩ wa tene na tene.'),
('kam', 'MAT', 18, 9, 'Na ethĩwa itho yaku nĩyĩũkũlulutĩkya, yumye, wĩkye kũasa naku: nĩ ũseo kwaku ũlike thayũnĩ wĩ nthongo, kwĩ ũkĩkw’a wĩ na metho elĩ nthĩnĩ wa Ngiena ya mwaki.'),
('kam', 'MAT', 18, 10, 'Sisyai mũikavũthye kamwe ka tũũ tũnini: nũndũ nĩngũmwĩa, kana alaĩka matw’o ĩtunĩ mavinda onthe monaa ũthyũ wa Asa wakwa ũla wĩ ĩtunĩ.'),
('kam', 'MAT', 18, 11, 'Nũndũ Mwana wa mũndũ nĩwokie kũtangĩĩa kĩla kyaĩte.'),
('kam', 'MAT', 18, 12, 'Mwĩona ata? Ethĩwa mũndũ o na wĩva e na malondu ĩana, na yĩmwe yamo yĩkyaa, ndeũtia ala mĩongo kenda na kenda, na akĩthi iĩmanĩ kũmantha yĩla yau?'),
('kam', 'MAT', 18, 13, 'Na ethĩwa nũnũũyona, nĩ w’o nĩngũmwĩa, nũnũũyĩtanĩa yĩu mbee wa ala mĩongo kenda na kenda mate mau.'),
('kam', 'MAT', 18, 14, 'No ta ũu ti kwenda kwa Ĩthe wenyu ũla wĩ ĩtunĩ, kamwe ka tũũ tũnini kae.'),
('kam', 'MAT', 18, 15, 'Na mwana‐a‐au akwĩka naĩ, thi, ũmwon’ye ĩvĩtyo yake wĩ nake mwĩ inyw’oka: akwĩw’a, nĩwamwona mwana‐a‐au.'),
('kam', 'MAT', 18, 16, 'Ĩndĩ alea ũkwĩw’a, osa ũngĩ ũmwe kana elĩ vamwe naku, nĩ kana kwa makanyw’a ma ngũsĩ ilĩ kana itatũ kĩla ndeto ĩlũme.'),
('kam', 'MAT', 18, 17, 'Na alea ũmew’a mo, yĩtavye ĩkanisa: na alea kwĩw’a ĩkanisa nayo, kwaku nĩethĩwe ta Mũndũ‐wambaĩ‐ingĩ na ta mumya wa koti.'),
('kam', 'MAT', 18, 18, 'Nĩ w’o nĩngũmwĩa, Maũndũ o na meva ala mũkova kũũ nthĩ makethĩwa me move ĩtunĩ; na maũndũ o na meva ala mũkathasya kũũ nthĩ makethĩwa me mathasye ĩtunĩ.'),
('kam', 'MAT', 18, 19, 'Ĩngĩ nĩngũmwĩa, ethĩwa elĩ ma inyw’ĩ makeew’ana kũũ nthĩ ũndũnĩ o na wĩva ũla makavoya, makeekwa ũndũ ũsu nĩ Asa wakwa ũla wĩ ĩtunĩ.'),
('kam', 'MAT', 18, 20, 'Nĩkwĩthĩwa vala ve elĩ kana atatũ mombene syĩtwanĩ yakwa, nyie nĩ vo katĩ woo.'),
('kam', 'MAT', 18, 21, 'Na ĩndĩ Vetelo athi, amwĩa, Mwĩaĩi, nĩ mavinda meana ata mwana‐a‐asa aimbĩka naĩ nĩmũekee? Kũvika ya mũonza?'),
('kam', 'MAT', 18, 22, 'Yesũ amwĩa, Ndiũkũtavya kũvika ya mũonza; ĩndĩ kũvika mũonza kũndũ mĩongo mũonza.'),
('kam', 'MAT', 18, 23, 'Kwondũ wa ũu ũsumbĩ wa ĩtu ũilyĩ ta mũsumbĩ ũmwe, ũla wendie ũtalo kwa ngombo syake.'),
('kam', 'MAT', 18, 24, 'Na ambĩlĩlya ũtala, aetewe ĩmwe ĩla yaĩ na thiĩ nake wa mbesa sya talendi ngili ĩkũmi.'),
('kam', 'MAT', 18, 25, 'Ĩndĩ nĩkwĩthĩwa ĩtyaĩ na kĩndũ kya ũĩva, vwana wayo eeaa ĩtewe, yo na kĩveti kyayo, na syana, na syonthe ila yaĩ nasyo, kũĩva ũla thiĩ.'),
('kam', 'MAT', 18, 26, 'Na ĩndĩ ĩla ngombo yavalũka nthĩ na yamũthaitha, ĩkyasya, Vwana, nandũa kavola, nakwa ngakũĩva syonthe.'),
('kam', 'MAT', 18, 27, 'Na vwana wa ngombo ĩsu amĩw’ĩa tei, na amĩthasya, na amĩekea ũla thiĩ.'),
('kam', 'MAT', 18, 28, 'Ĩndĩ ngombo ĩsu yaumaala, yoona ũmwe wa athũkũmi ala angĩ, ũla waĩ na thiĩ nayo wa silingi ĩana yĩmwe: amũkwata, na amũkwata mĩmeo, ĩkyasya, Ndĩva kĩla ngũũandũa.'),
('kam', 'MAT', 18, 29, 'Na ĩndĩ mũthũkũmi ũsu avalũka nthĩ na amwĩsũva, akyasya, Nandũa kavola, nakwa ngakũĩva.'),
('kam', 'MAT', 18, 30, 'Nayo ndĩaaĩtĩkĩla: ĩndĩ yathi yamwĩkĩa kolokolonĩ, mũvaka yĩla ũkaĩva ũla thiĩ.'),
('kam', 'MAT', 18, 31, 'Na ĩndĩ athũkũmi ala angĩ moona ũndũ weekwa, meew’a woo mũno, na mathi mamũtavya vwana woo w’onthe ũndũ kweekwa.'),
('kam', 'MAT', 18, 32, 'Na ĩndĩ vwana wayo amĩta kwake, na amĩtavya, We ngombo nthũku, ngũekeie thiĩ ũsu w’onthe, nũndũ nũmbĩsũvie:'),
('kam', 'MAT', 18, 33, 'naku ndwaĩlwe nĩ kũmwĩw’ĩa tei mũthũkũmi ũngĩ, tondũ nyie ngwĩw’ĩie tei?'),
('kam', 'MAT', 18, 34, 'Na vwana wayo athata, na amĩnengane kwa athĩn’ya, mũvaka yĩla ĩkaĩva thiĩ ũsu w’onthe.'),
('kam', 'MAT', 18, 35, 'Asa wakwa wa ĩtunĩ akamwĩka inyw’ĩ o ta ũu, mwalea kũekanĩa kĩla mũndũ na mwana‐a‐ĩthe kuma ngoonĩ syenyu.'),
('kam', 'MAT', 19, 1, 'Na kweethĩwa Yesũ amina ndeto isu, auma Kalilii athi mĩvakanĩ ya Yutia, mũingo wa Yolotani;'),
('kam', 'MAT', 19, 2, 'na makomano manene mamũatĩĩa; na amavoesya ku.'),
('kam', 'MAT', 19, 3, 'Na Avalisi mooka vala ũĩ, makĩmũtata, makyasya, Nĩkwosana na ĩla mĩao mũndũ kũmũeka mũka kwondũ wa kĩla ũndũ?'),
('kam', 'MAT', 19, 4, 'Na asũngĩa, amakũlya, Mũtyaasoma kana we ũla wamombie mbee, amombie mũndũ mũũme na mũndũ mũka,'),
('kam', 'MAT', 19, 5, 'na asya, Kwondũ wa ũu mũndũ akatia ĩthe na nyinyia, na akalũman’ya na mũka wake; na me elĩ makeethĩwa mwĩĩ ũmwe?'),
('kam', 'MAT', 19, 6, 'O na matw’ĩkĩte ti elĩ ĩngĩ, ĩndĩ nĩ mwĩĩ ũmwe. Ala Ngai ũlũmanĩtye ĩndĩ, mũndũ ndakaamataan’ye.'),
('kam', 'MAT', 19, 7, 'Mamwĩa, Nĩkĩ ĩndĩ Mose weaie kũnengane valũa wa kũtaanĩsya, na kũmũeka?'),
('kam', 'MAT', 19, 8, 'Amea, Mose kwondũ wa wũmũ wa ngoo syenyu nĩwetĩkĩlile mũeke aka menyu: ĩndĩ kuma mwambĩlĩlyonĩ kũiailyĩ ũu.'),
('kam', 'MAT', 19, 9, 'Nakwa nĩngũmwĩa, O ũla ũkamũeka mũka wake, ate o kwondũ wa ũlaalai, na aitwaa ũngĩ, nũnũũlaalaa: na ũla wĩmũtwaa ũsu ũeketwe nũnũũlaalaa.'),
('kam', 'MAT', 19, 10, 'Amanyĩw’a make mamwĩa, Ethĩwa ũndũ wa mũndũ na mũka wake ũtilyĩ ũu, kũtwaana kũi vata.'),
('kam', 'MAT', 19, 11, 'Ĩndĩ we amea, Tĩ andũ onthe matonya kwosa ndeto ĩno, ĩndĩ no asu ala manengetwe.'),
('kam', 'MAT', 19, 12, 'Nũndũ kwĩ avakũe ala masyaiwe ũu kuma mavunĩ ma aanyinyia moo: na kwĩ avakũe ala mavakũiwe nĩ andũ: na kwĩ avakũe ala meevakũie kwondũ wa ũsumbĩ wa ĩtu. Ũla ũtonya kũmyosa, namyose.'),
('kam', 'MAT', 19, 13, 'Na ĩndĩ aetewe syana nini nĩ kana asilĩĩle moko, na kwivoyea: na amanyĩw’a mamakan’ya.'),
('kam', 'MAT', 19, 14, 'Ĩndĩ Yesũ asya, Iekei syana nini, na mũikaivate kũka kwakwa: nũndũ ũsumbĩ wa ĩtu nĩ wa ala mailyi ta isu.'),
('kam', 'MAT', 19, 15, 'Na asilĩĩla moko, na auma vau athi.'),
('kam', 'MAT', 19, 16, 'Na sisya, ũmwe ooka vala ũĩ amũkũlya, Mũmanyĩsya mũseo, nĩĩka ũndũ ũseo wiva nĩ kana nĩthĩwe na thayũ ũtathela?'),
('kam', 'MAT', 19, 17, 'Na amwĩa, Nĩkĩ ũũmbĩta mũseo? Ũla mũseo no Ũmwe: ĩndĩ ethĩwa nũkwenda kũvota thayũnĩ, kwata mĩao.'),
('kam', 'MAT', 19, 18, 'Nake amũkũlya, Yĩva? Na Yesũ amwĩa, Ndũkoae, Ndũkalaalae, Ndũkoye, Ndũkaneene ũkũsĩ wa ũvũngũ,'),
('kam', 'MAT', 19, 19, 'Taĩa au na mwenyu; na, Mwende mũtũi waku tondũ wĩyendete.'),
('kam', 'MAT', 19, 20, 'Ũla mwanake amwĩa, Maũndũ asu onthe nĩnĩmakwatie: nĩ ũndũ wĩva ũla ndielye?'),
('kam', 'MAT', 19, 21, 'Yesũ amwĩa, Ethĩwa nũkwenda kwĩthĩwa mwĩanĩu, thi, ũkathoosye ila wĩ nasyo, ũnenge ngya, naku ũkethĩwa na ũthwii ĩtunĩ: na ĩndĩ ũkyũka ũngatĩĩe.'),
('kam', 'MAT', 19, 22, 'Ĩndĩ ũla mwanake eew’a ndeto isu, athi na woo; nĩkwĩthĩwa aĩ na ũthwii mwingĩ.'),
('kam', 'MAT', 19, 23, 'Na Yesũ amea amanyĩw’a make, Nĩ w’o nĩngũmwĩa, Kũkeethĩwa ũndũ wĩ vinya mũndũ mũthwii kũlika ũsumbĩnĩ wa ĩtu.'),
('kam', 'MAT', 19, 24, 'Na ĩngĩ nĩngũmwĩa, Nĩ ũvũthũ ngamĩle kũvotela kalimanĩ ka singano, kwĩ mũndũ mũthwii kũvota ũsumbĩnĩ wa Ngai.'),
('kam', 'MAT', 19, 25, 'Na amanyĩw’a meew’a ũu maseng’a mũno, makyasya, Nũũ ĩndĩ ũtonya kũtangĩĩwa?'),
('kam', 'MAT', 19, 26, 'Na Yesũ amasisya, amea, Kwa andũ ũndũ ũũ ndũtonyeka; ĩndĩ kwa Ngai maũndũ onthe nĩmatonyeka.'),
('kam', 'MAT', 19, 27, 'Na ĩndĩ Vetelo asũngĩa, amwĩa, Sisya, ithyĩ nĩtũtiĩte syonthe na twakũatĩĩa; tũkosa kyaũ ĩndĩ?'),
('kam', 'MAT', 19, 28, 'Na Yesũ amea, Nĩ w’o nĩngũmwĩa, kana inyw’ĩ mũmbikĩlĩte, yĩla Mwana wa mũndũ ũkekalĩla kĩvĩla kya ũsumbĩ kya ũtheu wake mũtisu kũalyũkwanĩ kweũ, inyw’ĩ nenyu nĩmũkekalĩla ivĩla sya ũsumbĩ ĩkũmi na ilĩ, mũkĩsilĩla mbai ĩkũmi na ilĩ sya Isilaeli.'),
('kam', 'MAT', 19, 29, 'Na kĩla mũndũ ũla ũtiĩte nyũmba, kana ana‐a‐inyia, kana eĩtu‐a‐inyia, kana ĩthe, kana nyinyia, kana syana, kana mĩũnda, kwondũ wa syĩtwa yakwa, akoosaa vandũ va kĩmwe, ĩana, na akatiĩwa thayũ ũtathela.'),
('kam', 'MAT', 19, 30, 'Ĩndĩ aingĩ me mbee makethĩwa me ĩtina; na ala me ĩtina makethĩwa me mbee.'),
('kam', 'MAT', 20, 1, 'Nũndũ ũsumbĩ wa ĩtu ũilyĩ ta mũndũ mwene wa nyũmba, ũla waumaalile kĩoko tene kũandĩka atethya ma wĩa ma mũũnda wake wa mũsavivũ.'),
('kam', 'MAT', 20, 2, 'Na eeaanĩa na atethya ma wĩa kũmanenga mũthenya silingi ĩmwe, amatũma mũũndanĩ wake wa mĩsavivũ.'),
('kam', 'MAT', 20, 3, 'Na aumaala ta saa itatũ, na oona angĩ maũngeme kĩng’ang’anĩ mate na wĩa;'),
('kam', 'MAT', 20, 4, 'na asu amea, Nenyu endai mũũndani wa mĩsavivũ, na ngamũnenga kĩla kĩmwĩanĩe. Nao mathi.'),
('kam', 'MAT', 20, 5, 'Aumaala ĩngĩ ta syũa yaũngama na saa kenda, eeka o ta ũu.'),
('kam', 'MAT', 20, 6, 'Na ta saa ĩkũmi na ũmwe aumaala, na oona angĩ maũngeme; na amakũlya, Nĩkĩ mũũngamie vaa mũthenya mũima mũte na wĩa?'),
('kam', 'MAT', 20, 7, 'Mamwĩa, Nĩkwĩthĩwa vai mũndũ ũnatũandĩka. Amea, Endai nenyu mũũndanĩ wa mĩsavivũ.'),
('kam', 'MAT', 20, 8, 'Na kwavika wĩoo, ũla mwene wa mũũnda wa mĩsavivũ amwĩa mũũngamĩi wa kwake, Mete atethya ma wĩa, ũmanenge ĩtuvi yoo, wambĩlĩlye kuma ũla wa ĩtina kũvivika ũla wa mbee.'),
('kam', 'MAT', 20, 9, 'Na mooka ala maandĩkiwe ta saa ĩkũmi na ũmwe, manengwa kĩla mũndũ silingi ĩmwe.'),
('kam', 'MAT', 20, 10, 'Na ala ma mbee mooka, matalĩthya kana makoosa mbee; nao manengwa kĩla mũndũ silingi ĩmwe.'),
('kam', 'MAT', 20, 11, 'Na moosa, mamũnyungunyĩĩsya ũla mwene wa nyũmba,'),
('kam', 'MAT', 20, 12, 'makyasya, Aa ma ĩtina matethya wĩa saa o ũmwe, naku wameanan’ya naitũ ala tũmĩĩsye thĩna na ũvyũvu wa mũthenya mũima.'),
('kam', 'MAT', 20, 13, 'Ĩndĩ asũngĩa ũmwe woo, amwĩa, Mũnyanyawa ndinakwĩka naĩ: ndũneaanĩa nakwa silingi ĩmwe?'),
('kam', 'MAT', 20, 14, 'Osa kĩla kyaku, noithi; nĩ kwenda kwakwa kũmũnenga ũũ wa ĩtina o taku.'),
('kam', 'MAT', 20, 15, 'Kũiosana na mĩao nyie kwĩka ũndũ ngwenda na syĩndũ syakwa mwene? Kana itho yaku nĩ ĩthũku nĩkwĩthĩwa nyie nĩ mũseo?'),
('kam', 'MAT', 20, 16, 'No ta ũu ala me ĩtina makethĩwa me mbee, na ala me mbee makethĩwa me ĩtina.'),
('kam', 'MAT', 20, 17, 'Na Yesũ akyambata Yelusaleme, oosa ala amanyĩw’a ĩkũmi na elĩ nzama, na me nzĩanĩ amea,'),
('kam', 'MAT', 20, 18, 'Sisyai, nĩtũkwambata Yelusaleme; na Mwana wa mũndũ akanenganwe mokonĩ ma athembi anene na aandĩki; nao makamũsilĩla oawe,'),
('kam', 'MAT', 20, 19, 'na makamũnengane mokonĩ ma Andũ‐ma‐mbaĩ‐ingĩ mamũthekee na kĩvũthya, na kũmũvũa, na kũmwamba ngelan’yonĩ: na mũthenya wa katatũ akathayũũkw’a.'),
('kam', 'MAT', 20, 20, 'Nĩvo ĩndĩ inyia wa ana ma Sevetii wokie vala ũĩ vamwe na ana make, akĩmũthaitha, na akĩmũvoya ũndũ.'),
('kam', 'MAT', 20, 21, 'Na amũkũlya, Wĩenda kyaũ? Amwĩa, Ĩae kana ana aa elĩ makwa mekale, ũmwe ngalĩ ya kw’oko kwaku kwa aũme, na ũmwe ngalĩ ya kw’oko kwaku kwa aka, ũsumbĩnĩ waku.'),
('kam', 'MAT', 20, 22, 'Ĩndĩ Yesũ asũngĩa na asya, Mũiĩsĩ ũndũ mũũvoya. Nĩmũtonya kũnyw’a kĩkombe kĩla ngilĩlye ũnyw’a? Mamwĩa, Nĩtũtonya.'),
('kam', 'MAT', 20, 23, 'Amea, Kĩkombe kyakwa nĩ w’o mũkakĩnyw’a: ĩndĩ kwĩkala ngalĩ ya kw’oko kwakwa kwa aũme, na ngalĩ ya kw’oko kwakwa kwa aka, ti ũndũ wakwa kũnengane, ĩndĩ nĩmakanengwa ala maseũvĩw’e nĩ Asa wakwa.'),
('kam', 'MAT', 20, 24, 'Na ala ĩkũmi meew’a ũu, mamathatĩa asu elĩ ma inyia ũmwe.'),
('kam', 'MAT', 20, 25, 'Ĩndĩ Yesũ ameta moke vala ũĩ, na asya, Nĩmwĩsĩ kana asumbĩ ma Andũ‐ma‐mbaĩ‐ingĩ masumbĩkaa ĩũlũ woo, na anene moo nĩmameaĩaa.'),
('kam', 'MAT', 20, 26, 'Kũikethĩwe ũu katĩ wenyu: ĩndĩ o ũla ũkwenda kwĩthĩwa mũnene katĩ wenyu akeethĩwa e mũthũkũmi wenyu;'),
('kam', 'MAT', 20, 27, 'na o ũla ũkwenda kwĩthĩwa wa mbee katĩ wenyu akeethĩwa ngombo yenyu:'),
('kam', 'MAT', 20, 28, 'o tondũ Mwana wa mũndũ ndaaũka kũthũkũmwa, ĩndĩ nĩ kũthũkũma, na kũnengane thayũ wake wĩthĩwe wovosyo kwondũ wa aingĩ.'),
('kam', 'MAT', 20, 29, 'Na makyuma Yeliko ĩkomano ĩnene yamũatĩĩa.'),
('kam', 'MAT', 20, 30, 'Na sisya, andu elĩ ililinda mekalĩte ũtee wa nzĩa, nao meew’a kana Yesũ nũvĩtĩte, maneena na mawasya manene, makyasya, Mwĩaĩi, twĩw’ĩe tei, we mwana wa Ndaviti.'),
('kam', 'MAT', 20, 31, 'Na ĩkomano yamakan’ya nĩ kana mavindye: ĩndĩ maneena mũno mbee, makyasya, Mwĩaĩi, twĩw’ĩe tei, we mwana wa Ndaviti.'),
('kam', 'MAT', 20, 32, 'Na Yesũ aũngama, ameta, na asya, Mwĩenda nĩmwĩke ata?'),
('kam', 'MAT', 20, 33, 'Mamwĩa, Mwĩaĩi, twĩenda metho maitũ masalukw’e.'),
('kam', 'MAT', 20, 34, 'Na Yesũ, nũndũ wa kũmew’ĩa tei, amakiita metho; na oyu manengwa kwona, na mamũatĩĩa.'),
('kam', 'MAT', 21, 1, 'Na yĩla mathengeeie Yelusaleme, na mavika Vethivake, kĩĩmanĩ kya Mĩthata, nĩvo Yesũ watũmie amanyĩw’a elĩ,'),
('kam', 'MAT', 21, 2, 'aimea, Endai mũsyĩ ũla ũmwelekele, na kavinda o kau nĩmũkwona ĩng’oi yovetwe, na ndena nayo: thasyai, mũndetee.'),
('kam', 'MAT', 21, 3, 'Na ethĩwa mũndũ o na wĩva akamwĩa ũndũ, asyai, Mwĩaĩi e vata nayo; na oyu nũnũũmũnenga yo.'),
('kam', 'MAT', 21, 4, 'Na ũu weethĩĩwe, nĩ kana kwĩanĩw’e ũla waneeniwe nĩ mwathani, akyasya,'),
('kam', 'MAT', 21, 5, 'Mũtavyei mwĩĩtu wa Saioni, Sisya Mũsumbĩ waku nĩwũkĩte kwaku, Nĩ mũuu, atũlĩte ĩng’oi, O ndena, ndena ya ĩng’oi.'),
('kam', 'MAT', 21, 6, 'Na ala amanyĩw’a mathi, meeka o tondũ Yesũ ũmeaĩe,'),
('kam', 'MAT', 21, 7, 'na maete ĩng’oi, na ndena, na mamailĩĩla ngũa syoo; na asyĩkalĩla.'),
('kam', 'MAT', 21, 8, 'Na ala aingĩ ma ĩkomano yĩu malan’ya ngũa syoo nzĩanĩ; na angĩ matema tũũvonge twa mĩtĩ, malan’ya nzĩanĩ.'),
('kam', 'MAT', 21, 9, 'Na makomano ala maendie mbee wake, na ala mamũatĩĩe, mookĩlya wasya mũnene, makyasya, Hosana, mwana wa Ndaviti: nĩ mũathime ũla wũkĩte syĩtwanĩ ya Mwĩaĩi; Hosana, ku ĩũlũ mũno.'),
('kam', 'MAT', 21, 10, 'Na alika Yelusaleme, ndũa yonthe yavũavũana, ĩkyasya, Ũũ nũũ?'),
('kam', 'MAT', 21, 11, 'Na ala makomano masya, Ũũ nĩwe Yesũ, ũla mwathani wa Nasaleti ya Kalilii.'),
('kam', 'MAT', 21, 12, 'Na Yesũ avota ĩkalũnĩ ya Ngai, amakuthũa onthe ala mathooasya na kũthooa ĩkalũnĩ, na ang’uthũlanga mesa sya ala meũvunzya mbesa, na ivĩla sya ala meũthoosya mavũĩ;'),
('kam', 'MAT', 21, 13, 'na amea, Nĩkũandĩkĩtwe, Nyũmba yakwa ĩkeetwa nyũmba ya kũvoyea: ĩndĩ inyw’ĩ mwĩmĩtw’a ngunga ya avutani.'),
('kam', 'MAT', 21, 14, 'Na ililinda na ala mathuaa mooka vala ũĩ ĩkalũnĩ; na amavosya.'),
('kam', 'MAT', 21, 15, 'Ĩndĩ athembi anene na aandĩki moona moseng’yo ala weka, na syana iineena na wasya mũnene ĩkalũnĩ, ikyasya, Hosana, mwana wa Ndaviti; mathata,'),
('kam', 'MAT', 21, 16, 'na mamwĩa, Nũkwĩw’a ũndũ aa mekwasya? Na Yesũ amea, Ĩĩ: mũtyaamba ũsoma, Kuma makanyw’anĩ ma syana na tũũkenge ndaĩa nĩyeanĩie?'),
('kam', 'MAT', 21, 17, 'Na amatia, na auma ndũanĩ ĩsu athi Vethania, na akoma kw’o.'),
('kam', 'MAT', 21, 18, 'Na kĩoko asyokete ĩla ndũanĩ, eew’a nzaa.'),
('kam', 'MAT', 21, 19, 'Na oona mũkũyũ ũtee wa nzĩa, athi vo, na eethĩa ndwĩ kĩndũ ate o matũ mathei; na awĩa, Kũikethĩwe ũsyao kwaku kuma yu o na tene na tene. Na oyu ũla mũkũyũ wooma.'),
('kam', 'MAT', 21, 20, 'Na ala amanyĩw’a moona ũu, maseng’a, makyasya, Mũkũyũ ũũ wooma ata oyuyu?'),
('kam', 'MAT', 21, 21, 'Na Yesũ asũngĩa, amea, Nĩ w’o nĩngũmwĩa, Ethĩwa mwĩ na mũĩkĩĩo, na mũikethĩwa na nzika, mũikeka ũndũ ũũ wa mũkũyũ w’oka, ĩndĩ o na ethĩwa mũkatavya kĩĩma kĩĩ, Kuwa nokĩkw’a ũkanganĩ, ũkeekwa.'),
('kam', 'MAT', 21, 22, 'Na maũndũ onthe, o ala mũketya mũkĩvoya, mũkĩtĩkĩla, mũkoosa.'),
('kam', 'MAT', 21, 23, 'Na avota ĩkalũnĩ, athembi anene na atumĩa ma andũ mooka vala ũĩ akĩmanyĩsya, na masya, Wĩkaa maũndũ aa na ũkũmũ wĩva? Na nũũ ũla ũkũnengete ũkũmũ ũũ?'),
('kam', 'MAT', 21, 24, 'Na Yesũ asũngĩa na amea, Nakwa nĩngũmũkũlya ũkũlyo ũmwe, na mwandavya, nakwa nĩngũmũtavya ũkũmũ ũla ũtumaa nĩka maũndũ aa.'),
('kam', 'MAT', 21, 25, 'Ũvatisi wa Yoana waumie va? Waumie ĩtunĩ kana waumie andũnĩ? Na masũanĩa ene kwa ene, makyasya, Ethĩwa nĩtũkwasya, Waumie ĩtunĩ; etwĩa, Nĩkĩ ĩndi mũtaamwĩtĩkĩla?'),
('kam', 'MAT', 21, 26, 'Ĩndĩ ethĩwa nĩtũkwasya, Waumie andũnĩ; nĩtũũkĩa ĩkomano; nũndũ andũ onthe nĩmeesĩ Yoana nĩ mwathani.'),
('kam', 'MAT', 21, 27, 'Na mamũsũngĩa Yesũ, masya, Tũtyĩsĩ. Nake amea, O nakwa ndimũtavya ũkũmũ ũla ũtumaa nĩka maũndũ aa.'),
('kam', 'MAT', 21, 28, 'Ĩndĩ mwĩona ata? Mũndũ ũmwe aĩ na ana elĩ; na athi vala ve ũla wa mbee, na asya, Mwana wakwa, thi ũmũnthĩ ũkatethye wĩa mũũndanĩ wa mĩsavivũ.'),
('kam', 'MAT', 21, 29, 'Na asũngĩa, asya, Ndithi: ĩndĩ ĩtina eelila, na athi.'),
('kam', 'MAT', 21, 30, 'Na athi vala ve ũla wa kelĩ, na asya o ta ũu. Nake asũngĩa, asya, Nĩngũthi vwana: na ndaathi.'),
('kam', 'MAT', 21, 31, 'Nĩ wĩva wa asu elĩ ũla wekie kwenda kwa ĩthe wake? Masya, Nĩ ũla wa mbee. Yesũ amea, Nĩ w’o nĩngũmwĩa, kana aumya ma koti na malwaya nĩmavotaa ũsumbĩnĩ wa Ngai mbee wenyu.'),
('kam', 'MAT', 21, 32, 'Nũndũ Yoana nĩwokie kwenyu na nzĩa ya ũlũngalu, na mũtyaamwĩtĩkĩla; ĩndĩ aumya ma koti na malwaya nĩmamwĩtĩkĩlile: nenyu mwoona ũu, o na ĩtina mũtyaaĩlila, nĩ kana mũmwĩtĩkĩle.'),
('kam', 'MAT', 21, 33, 'Ĩthukĩĩsyei ngelekan’yo ĩngĩ: Kwaĩ mũndũ mwene wa nyũmba, nake avandie mũũnda wa mĩsavivũ, na oothyũlũlũkya wiio, enza katĩ waw’o ĩima ya ũangĩa nzavivũ, na aaka mwako mũtũlu wa mũnyoolo, na oonenga aĩmi mamũĩmĩe, nake athi ũeni nthĩ ĩngĩ.'),
('kam', 'MAT', 21, 34, 'Na ĩvinda ya ũsyao, yathengeea, atũma ngombo syake kwa ala aĩmi, inengwe mosyao maw’o.'),
('kam', 'MAT', 21, 35, 'Na ala aĩmi makwata ngombo syake, na ĩmwe mamĩkũna, na ĩngĩ mamyũaa, na ĩngĩ mamĩkimanga na mavia.'),
('kam', 'MAT', 21, 36, 'Na atũma ĩngĩ ngombo ingĩ mbingĩ kwĩ ila sya mbee; na masyĩka o ta ũu.'),
('kam', 'MAT', 21, 37, 'Ĩndĩ ĩtina atũma mwana wake kwoo, akyasya, Makamũtaĩa mwana wakwa.'),
('kam', 'MAT', 21, 38, 'Ĩndĩ aĩmi moona ũla mwana, masya ene kwa ene, Ũũ nĩwe mũtiĩwa; ũkai tũmũae, twose ũtiĩwa wake.'),
('kam', 'MAT', 21, 39, 'Na mamũkwata, mamwĩkya ũtee wa mũũnda wa mĩsavivũ, na mamũaa.'),
('kam', 'MAT', 21, 40, 'Yĩla ĩndĩ mwene wa mũũnda wa mĩsavivũ ũkoka, akameka ata aĩmi asu?'),
('kam', 'MAT', 21, 41, 'Mamwĩa, Akamananga naĩ andũ asu athũku, na akanenga aĩmi angĩ mũũnda ũsu wa mĩsavivũ, ala makamũnenga mosyao ĩvindanĩ yamo.'),
('kam', 'MAT', 21, 42, 'Yesũ amea, Mũtyaamba ũsoma maandĩkonĩ, Ĩvia yĩla yaleilwe nĩ aki, Yĩu yatw’ĩkie yĩla ĩnene ya kĩkotonĩ; Ũu nĩwaumie kwa Mwĩaĩi, Naw’o nĩ ũseng’yo methonĩ maitũ?'),
('kam', 'MAT', 21, 43, 'Kwondũ wa ũu nĩngũmwĩa, Ũsumbĩ wa Ngai ũkaumw’a kwenyu, na ũkanengwa mbaĩ ĩsyaaa mosyao maw’o.'),
('kam', 'MAT', 21, 44, 'Na ũla wĩvalũka ĩũlũ wa ĩvia yĩĩ akavevenzeka: ĩndĩ o ũla yĩmũvalũkĩla, akatumbatumbĩka anyaĩĩke ta kĩtoo.'),
('kam', 'MAT', 21, 45, 'Na athembi anene na Avalisi meew’a ngelekan’yo syake, mamanya kana nĩmo meũwetwa.'),
('kam', 'MAT', 21, 46, 'Na makĩmantha kũmũkwata, makĩa makomano, nĩkwĩthĩwa mamwonaa e mwathani.'),
('kam', 'MAT', 22, 1, 'Na Yesũ asũngĩa na aneena nao ĩngĩ na ngelekan’yo, akyasya,'),
('kam', 'MAT', 22, 2, 'Ũsumbĩ wa ĩtu ũilyĩ ta mũsumbĩ ũmwe, ũla wamũvokee mwana wake mboka ya mũtwaano,'),
('kam', 'MAT', 22, 3, 'na atũma ngombo syake kũmeta ala metĩtwe mbokanĩ ya mũtwaano moke: nao malea kũka.'),
('kam', 'MAT', 22, 4, 'Atũma ĩngĩ ngombo ingĩ, akyasya, Matavyei ala metĩtwe, Sisyai, nĩnzeũvisye mboka yakwa: ndewa syakwa na indo syakwa nou nĩsyũaiwe, na syĩndũ syonthe nĩsyũmbanĩtw’e: ũkai mbokanĩ ya mũtwaano.'),
('kam', 'MAT', 22, 5, 'Ĩndĩ malea kwona ta ũndũ, na meeendea, ũmwe mũũndanĩ wake, ũngĩ ũtandĩthyonĩ wake;'),
('kam', 'MAT', 22, 6, 'na ala matialile makwata ngombo syake, masyĩka naĩ, na masyũaa.'),
('kam', 'MAT', 22, 7, 'Ĩndĩ ũla mũsumbĩ athata; atũma ita syake, na aananga oaani asu, na avĩvya ndũa yoo.'),
('kam', 'MAT', 22, 8, 'Na ĩndĩ aitavya ngombo syake, Mboka ya mũtwaano nĩ nzeũvye, ĩndĩ ala meĩtĩtwe mainaĩla.'),
('kam', 'MAT', 22, 9, 'Endai ĩndĩ mataanĩsyonĩ ma malelũ, na onthe ala mũkwona, metei moke mũtwaanonĩ.'),
('kam', 'MAT', 22, 10, 'Na ngombo isu syaumaala syathi malelũnĩ, na syoomban’ya onthe ala syoonie, ala athũku o na ala aseo: na mũtwaano wausũa aeni.'),
('kam', 'MAT', 22, 11, 'Ĩndĩ ũla mũsumbĩ avota nthĩnĩ kũsisya aeni, oonie mũndũ vo ũtekĩĩte ngũa ya mũtwaano:'),
('kam', 'MAT', 22, 12, 'na amũkũlya, Mũnyanyawa, ũlikile vaa ata, naku ndwĩ na ngũa ya mũtwaano? Nake avindya ki.'),
('kam', 'MAT', 22, 13, 'Nĩvo ĩndĩ mũsumbĩ wameie athũkũmi, Mwovei moko na maũũ, mũmwĩkye kĩvindunĩ nza; vo vakethĩwa kĩĩo na kũvevetan’ya maeo.'),
('kam', 'MAT', 22, 14, 'Nĩkwĩthĩwa nĩ aingĩ ala metawa, ĩndĩ ala anyuve nĩ avũthũ.'),
('kam', 'MAT', 22, 15, 'Nĩvo ĩndĩ Avalisi maendie masũanĩa ũndũ matonya kũmũtea ndetonĩ syake.'),
('kam', 'MAT', 22, 16, 'Na matũma amanyĩw’a moo kwake, vamwe na ala ma Elote, makyasya, Mũmanyĩsya, nĩtwĩsĩ kana wĩ wa w’o, na nzĩa ya Ngai nũmanyĩasya w’o, na ndũkĩaa mũndũ o na wĩva: nũndũ ndũsiasya ũthyũ wa mũndũ.'),
('kam', 'MAT', 22, 17, 'Tũtavye ĩndĩ, Wĩona ata? Nĩkwosana na ĩla mĩao kũnenga Kaisali koti, kana ti w’o?'),
('kam', 'MAT', 22, 18, 'Ĩndĩ Yesũ amanya ũthũku woo, na asya, Nĩkĩ mũũndata, inyw’ĩ angangan’ya?'),
('kam', 'MAT', 22, 19, 'Mbon’yai mbesa ya koti. Na mamũetee silingi.'),
('kam', 'MAT', 22, 20, 'Na amea, Mũvw’ano ũũ na ũandĩko ũũ nĩ waũ?'),
('kam', 'MAT', 22, 21, 'Mamwĩa, Nĩ wa Kaisali. Na ĩndĩ amea, Mũnengei Kaisali syĩndũ sya Kaisali; na Ngai syĩndũ sya Ngai.'),
('kam', 'MAT', 22, 22, 'Na meew’a ũu, maseng’a, na mamũeka, mathi.'),
('kam', 'MAT', 22, 23, 'Mũthenya ũsu Asatukai mooka vala ũĩ, ala maasya kana kũi ũthayũũkyo; na mamũkũlya,'),
('kam', 'MAT', 22, 24, 'makyasya, Mũmanyĩsya, Mose nĩwaisye, Mũndũ akw’a ate na syana, mwana‐a‐inyia wake namwose mũka wake, amũũngamĩsye mwana‐a‐inyia mbeũ.'),
('kam', 'MAT', 22, 25, 'Yu ĩndĩ kwitũ kwaĩ aũme mũonza ma inyia ũmwe: na ũla wa mbee atwaa mũka na akw’a, na nĩkwĩthĩwa ndaĩ na mbeũ amũtiĩa mwana‐a‐inyia mũka wake;'),
('kam', 'MAT', 22, 26, 'no ta ũu ũla wa kelĩ nake, na wa katatũ, kũvika onthe me mũonza.'),
('kam', 'MAT', 22, 27, 'Na ĩtina wa onthe ũla mũndũ mũka akw’a.'),
('kam', 'MAT', 22, 28, 'Ũthayũũkyonĩ ĩndĩ akethĩwa e mũka wa wiva wa asu mũonza? Nũndũ onthe maĩ nake.'),
('kam', 'MAT', 22, 29, 'Ĩndĩ Yesũ asũngĩa na amea, Nĩmũkũvĩtya, nĩkwĩthĩwa mũtyĩsĩ maandĩko, o na vinya wa Ngai.'),
('kam', 'MAT', 22, 30, 'Nũndũ ũthayũũkyonĩ maitwaanaa, o na maitwaawa, ĩndĩ mailyĩ ta alaĩka ala me ĩtunĩ.'),
('kam', 'MAT', 22, 31, 'Ĩndĩ ũndũ wa ũthayũũkyo wa akw’ũ, mũtyaasoma ũndũ mwataviwe. Nĩ Ngai, akyasya,'),
('kam', 'MAT', 22, 32, 'Nyie nĩ Ngai wa Avalaamu, na Ngai wa Isaka, na Ngai wa Yakovo? Ngai ti Ngai wa ala akw’ũ, ĩndĩ nĩ wa ala me thayũ.'),
('kam', 'MAT', 22, 33, 'Na makomano meew’a ũu, maseng’w’a nĩ ũmanyĩsyo wake.'),
('kam', 'MAT', 22, 34, 'Ĩndĩ Avalisi meew’a kana nĩwakilĩthya Asatukai, meeyũmban’ya vamwe.'),
('kam', 'MAT', 22, 35, 'Na ũmwe woo, mũmanyĩsya wa mĩao, amũkũlya aimũtata:'),
('kam', 'MAT', 22, 36, 'Mũmanyĩsya, mĩaonĩ, mwĩao ũla mũnene nĩ wĩva?'),
('kam', 'MAT', 22, 37, 'Na amwĩa Mwende Mwĩaĩi Ngai waku na ngoo yaku yonthe, na thayũ waku w’onthe, na kĩlĩko kyaku kyonthe.'),
('kam', 'MAT', 22, 38, 'Ũu nĩw’o mwĩao ũla mũnene na wa mbee.'),
('kam', 'MAT', 22, 39, 'Na wa kelĩ ũvw’anene naw’o, nĩw’o ũũ, Mwende mũtũi waku o tondũ wĩyendete.'),
('kam', 'MAT', 22, 40, 'Mĩao ĩsu ĩlĩ nĩyũmbanĩtye ĩla mĩao yonthe na athani.'),
('kam', 'MAT', 22, 41, 'Na Avalisi mombene, Yesũ amakũlya,'),
('kam', 'MAT', 22, 42, 'asya, Mwĩona ata inyw’ĩ ũndũ wa Klĩsto? Nĩ mwana waũ? Mamwĩa, Nĩ wa Ndaviti.'),
('kam', 'MAT', 22, 43, 'Amea, Kũilyĩ ata ĩndĩ, Ndaviti e Vevanĩ kũmwĩta Mwĩaĩi, akyasya,'),
('kam', 'MAT', 22, 44, 'Mwĩaĩi amwĩie Mwĩaĩi wakwa, Ĩkala nthĩ ngalĩ ya kw’oko kwakwa kwa aũme, Mũvaka nie amaitha maku ungu wa nyaĩĩ syaku?'),
('kam', 'MAT', 22, 45, 'Ethĩwa ĩndĩ Ndaviti emwĩta Mwĩaĩi, nĩ mwana wake ata?'),
('kam', 'MAT', 22, 46, 'Na vai ũmwe waatonya kũmũsũngĩa ndeto, o na kuma mũthenya ũsu vai mũndũ waatata kũmũkũlya ũndũ ĩngĩ.'),
('kam', 'MAT', 23, 1, 'Na ĩndĩ Yesũ aneena na ala makomano na amanyĩw’a make,'),
('kam', 'MAT', 23, 2, 'akyasya, Aandĩki na Avalisi nĩmekalĩte kĩvĩlanĩ kya Mose:'),
('kam', 'MAT', 23, 3, 'maũndũ onthe ĩndĩ o na meva ala mamwĩaĩaa, kwatai na kũmeka: ĩndĩ mĩkĩle yoo mũikamĩke; nũndũ nĩmaneenaa na matyĩkaa.'),
('kam', 'MAT', 23, 4, 'Ĩĩ, nĩmovaa mĩio mĩito ĩtakuĩka, na makĩmaĩkya andũ ituonĩ; ĩndĩ mo ene matyĩtĩkĩla kũmyũkĩlya na kyaa kyoo.'),
('kam', 'MAT', 23, 5, 'Ĩndĩ mawĩa moo onthe mekaa nĩ kana moneke nĩ andũ: nũndũ mathanthaasya iawa syoo, na manenevasya ndiivo sya ngũa syoo,'),
('kam', 'MAT', 23, 6, 'na nĩmendaa vandũ va mbee mbokanĩ, na ivĩla sya mbee masinakokenĩ,'),
('kam', 'MAT', 23, 7, 'na kũkethw’a ing’ang’anĩ, na kwĩtwa Lavai nĩ andũ.'),
('kam', 'MAT', 23, 8, 'Ĩndĩ inyw’ĩ mũiketwe Lavai: nũndũ mũmanyĩsya wenyu nĩ ũmwe, na inyw’onthe mwĩ ana ma ĩthe ũmwe.'),
('kam', 'MAT', 23, 9, 'Na mũikamwĩte mũndũ o na wĩva ĩthe wenyu kũũ nthĩ: nũndũ Ĩthe wenyu nĩ ũmwe, ũla wĩ ĩtunĩ.'),
('kam', 'MAT', 23, 10, 'O na mũiketwe eaĩi: nũndũ mwĩaĩi wenyu nĩ ũmwe, nĩwe Klisto.'),
('kam', 'MAT', 23, 11, 'Ĩndĩ ũla mũnene mbee katĩ wenyu akeethĩwa e mũthũkũmi wenyu.'),
('kam', 'MAT', 23, 12, 'Na o ũla ũkenenevya akanyiaw’a; na o ũla ũkenyivya akanenevw’a.'),
('kam', 'MAT', 23, 13, 'Ĩndĩ woo nĩ wenyu, aandĩki na Avalisi, angangan’ya! Nĩkwĩthĩwa nĩmũmavingĩaa andũ ũsumbĩ wa ĩtu: nũndũ inyw’ĩ ene mũtĩũvota, o na mũtiũmaeka ala meũvota, mavote.'),
('kam', 'MAT', 23, 14, 'Woo nĩ wenyu, aandĩki na Avalisi, angangan’ya! Nĩkwĩthĩwa nĩmũĩsaa nyũmba sya aka ndiwa, na nũndũ wa ũkengani nĩmũasavasya mboya: kwondũ wa ũu mũkona ũsilĩlo mũnene mbee.'),
('kam', 'MAT', 23, 15, 'Woo nĩ wenyu, aandĩki na Avalisi, angangan’ya! Nĩkwĩthĩwa mũthyũlũlũkaa ũkanga na nthĩ nĩ kana mwone mũvikĩli ũmwe; na ooneka, nĩmũũmũtw’ĩkĩthya mwana wa Ngiena kũthonoka inyw’ĩ ene kũndũ kwĩlĩ.'),
('kam', 'MAT', 23, 16, 'Woo nĩ wenyu, inyw’ĩ atongoi mũte metho, ala mwaasya, O ũla ũkevĩta na ĩkalũ, ti kĩndũ; ĩndĩ o ũla ũkevĩta na thaavu wa ĩkalũ, nĩwe wĩ na thiĩ.'),
('kam', 'MAT', 23, 17, 'Inyw’ĩ ndia na ililinda: nũndũ kĩla kĩnene nĩ kĩva, thaavu kana ĩkalũ yĩla yĩtheasya thaavu?'),
('kam', 'MAT', 23, 18, 'Na, O ũla ũkevĩta na kĩthembeo, ti kĩndũ; ĩndĩ o ũla ũkevĩta na nthembo ĩla yĩ ĩũlũ wakyo, nĩwe wĩ na thiĩ.'),
('kam', 'MAT', 23, 19, 'Inyw’ĩ ililinda: nũndũ kĩla kĩnene nĩ kĩva, nthembo, kana kĩthembeo kĩla kĩtheasya nthembo?'),
('kam', 'MAT', 23, 20, 'We ĩndĩ ũla wĩvĩtaa na kĩthembeo, nĩwĩvĩtaa nakyo, na syĩndũ syonthe ila syĩ ĩũlũ wakyo.'),
('kam', 'MAT', 23, 21, 'Na ũla wĩvĩtaa na ĩkalũ, nĩwĩvĩtaa nayo, na kwa ũla wĩkalaa nthĩnĩ wayo.'),
('kam', 'MAT', 23, 22, 'Na ũla wĩvĩtaa na ĩtu nĩwĩvĩtaa na kĩvĩla kya ũsumbĩ kya Ngai na kwa ũla ũkĩkalĩlaa.'),
('kam', 'MAT', 23, 23, 'Woo nĩ wenyu, aandĩki na Avalisi, angangan’ya! Nĩkwĩthĩwa nĩmumasya kĩlungu kya ĩkũmi kya mindi na anisi na kumini, na mũitia mũtekĩte maũndũ ala manene ma ĩla mĩao, ũsili wa katĩ, na tei, na mũĩkĩĩo: ĩndĩ asu nĩmwaĩlwe nĩ kũmeka, na ti kũtia asu angĩ mũtamekĩte.'),
('kam', 'MAT', 23, 24, 'Inyw’ĩ atongoi mũte metho, ala mũkelaa ũmuu, na mũimelya ngamĩle!'),
('kam', 'MAT', 23, 25, 'Woo nĩ wenyu, aandĩki na Avalisi, angangan’ya! Nĩkwĩthĩwa mũtheasya kĩkombe na ĩsaani ĩũlũ, ĩndĩ nthĩnĩ syusĩe ũvutani na wendi mũthonoku.'),
('kam', 'MAT', 23, 26, 'We Mũvalisi ũte metho, amba ũthesya nthĩnĩ wa kĩkombe na wa ĩsaani, nĩ kana yĩthĩwe yĩ ĩtheu ngalĩ ya ĩũlũ nayo.'),
('kam', 'MAT', 23, 27, 'Woo nĩ wenyu, aandĩki na Avalisi, angangan’ya! Nĩkwĩthĩwa mũilyĩ ta mbũa ivakĩtwe sokaa, ila syonekaa syĩ nzeo kũũ ĩũlũ, ĩndĩ nthĩnĩ syusĩe mavĩndĩ ma akw’ũ, na ũvuku w’onthe.'),
('kam', 'MAT', 23, 28, 'No ta ũu inyw’ĩ nenyu kũũ ĩũlũ mwonekaa nĩ andũ mwĩ alũngalu, ĩndĩ nthĩnĩ musũĩte wangangan’yo na ũthũku.'),
('kam', 'MAT', 23, 29, 'Woo nĩ wenyu, aandĩki na Avalisi, angangan’ya! Nĩkwĩthĩwa nĩmwakaa mbũa sya athani, na kwanakavya mbũa sya ala alũngalu,'),
('kam', 'MAT', 23, 30, 'na mũkyasya, Kethĩwa ithyĩ twaĩ kw’o ĩvinda ya aasa maitũ, tũiĩthĩwa twaĩ na mũamba nao nthakamenĩ ya athani.'),
('kam', 'MAT', 23, 31, 'Kwondũ wa ũu nĩmwĩkũsĩĩĩte, kana inyw’ĩ mwĩ ana ma ala mooaie athani.'),
('kam', 'MAT', 23, 32, 'Usũsyai ĩndĩ kĩthimi kya aaĩthe menyu.'),
('kam', 'MAT', 23, 33, 'Inyw’ĩ nzoka, ũsyao wa syĩko, mũkakĩa ata ũsilĩlo wa Ngiena?'),
('kam', 'MAT', 23, 34, 'Kwondũ wa ũu, sisyai, nyie nĩngũtũma kwenyu athani na andũ oĩ, na aandĩki: amwe moo mũkamoaa na kũmamba ngelan’yonĩ; na amwe moo mũkamavũĩa masinakokenĩ menyu, na kũmalũngya ndũa na ndũa:'),
('kam', 'MAT', 23, 35, 'nĩ kana yũke ĩũlũ wenyu nthakame yonthe ya alũngalu ĩla yetĩkie kũũ nthĩ, kuma nthakame ya Aveli ũla mũlũngalu kũvika nthakame ya Nzakalia mwana wa Valakia, ũla mwooaĩe katĩ wa vala vandũ vatheu na kĩthembeo.'),
('kam', 'MAT', 23, 36, 'Nĩ w’o nĩngũmwĩa, Maũndũ aa onthe makavikĩa ũsyao ũũ.'),
('kam', 'MAT', 23, 37, 'We Yelusaleme, Yelusaleme ũla wũaa athani, na kũmakimanga na mavia ala matũmiwe kwaku! Nĩ mavinda meana nendie kũmban’ya vamwe syana syaku, o ũndũ ngũkũ yũmbanasya tũswii twayo vamwe nthwaunĩ syayo, nenyu mũtyaaĩtĩkĩla!'),
('kam', 'MAT', 23, 38, 'Sisyai, nyũmba yenyu nĩtiĩtwe yĩ nthei.'),
('kam', 'MAT', 23, 39, 'Nũndũ nĩngũmwĩa, Mũikambona ĩngĩ nongi, mũvaka yĩla mũkasya, Nĩ mũathime ũla wũkĩte syĩtwanĩ ya Mwĩaĩi.'),
('kam', 'MAT', 24, 1, 'Na Yesũ auma ĩkalũnĩ, na e nzĩanĩ aendete; na amanyĩw’a make mooka vala ũĩ nĩ kana mamwon’ye myako ya ĩkalũ.'),
('kam', 'MAT', 24, 2, 'Ĩndĩ asũngĩa, amea, Mũtikwona syĩndũ ii syonthe? Nĩ w’o nĩngũmwĩa, Vaa vaikatiwa ĩvia ĩũlũ wa yĩngĩ, yĩla yĩtakaombowa.'),
('kam', 'MAT', 24, 3, 'Na ekalĩte kĩĩmanĩ kya Mĩthata, amanyĩw’a mooka vala ũĩ nzama, makyasya, Tũtavye, maũndũ asu makethĩwa indĩĩ? Na wonan’yo nĩ wĩva wa kũka kwaku, na wa wĩanĩu wa ĩvinda yĩĩ?'),
('kam', 'MAT', 24, 4, 'Na Yesũ asũngĩa, amea, Ĩsũvĩei mũndũ ndakamwasye'),
('kam', 'MAT', 24, 5, 'Nũndũ aingĩ makooka na syĩtwa yakwa, makyasya, Ninyie Klĩsto; na makamasya aingĩ.'),
('kam', 'MAT', 24, 6, 'Na mũkeew’a ũvoo wa makaũ na mawetango ma makaũ; sisyai mũikaũũye: nũndũ maũndũ asu mati ndĩi ya ũlea kwĩkĩka; ĩndĩ mũminũkĩlyo ndũnamba ũvika.'),
('kam', 'MAT', 24, 7, 'Nũndũ mbaĩ ĩkookĩlĩla mbaĩ, na ũsumbĩ ũkookĩlĩla ũsumbĩ; na kũkeethĩwa mayũa na itetemo sya nthĩ kũũ na kũũ.'),
('kam', 'MAT', 24, 8, 'Ĩndĩ maũndũ asu onthe nĩ wambĩlĩlyo wa woo.'),
('kam', 'MAT', 24, 9, 'Nĩvo makamũnengane thĩnanĩ, na makamũaa; na mũkeethĩwa mũmenetwe nĩ mbaĩ syonthe kwondũ wa syĩtwa yakwa.'),
('kam', 'MAT', 24, 10, 'Nĩvo aingĩ makalulutĩka, na makenengane ene kwa ene amaithanĩ, na makamenana.'),
('kam', 'MAT', 24, 11, 'Na athani aingĩ ma ũvũngũ makookĩla, na makamasya aingĩ.'),
('kam', 'MAT', 24, 12, 'Na kwondũ wa ũthũku kwingĩva, wendo wa aingĩ ũkavoa.'),
('kam', 'MAT', 24, 13, 'Ĩndĩ ũla ũkomĩĩsya kũvika mũminũkĩlyo, ũsu akatangĩĩwa.'),
('kam', 'MAT', 24, 14, 'Na ũvoo ũũ mũseo wa ũsumbĩ ũkatavanw’a nthĩ yonthe wĩthĩwe ũkũsĩ kwa mbaĩ syonthe; na ĩndĩ mũminũkĩlyo ũkyũka.'),
('kam', 'MAT', 24, 15, 'Yĩla ĩndĩ mwĩona ũthatyo ũla wanangaa, ũla wawetiwe nĩ mwathani Ndanieli, ũũngeme vala vandũ vatheu (ũla ũsomaa namanye),'),
('kam', 'MAT', 24, 16, 'nĩvo ala me Yutia makĩe mathi iĩmanĩ:'),
('kam', 'MAT', 24, 17, 'na ũla wĩ ĩũlũ wa nyũmba ndakatheee aumye syĩndũ ila syĩ nyũmbanĩ kwake:'),
('kam', 'MAT', 24, 18, 'na ũla wĩ mũũndanĩ ndakasyoke ose ngũa yake ya ĩũlũ.'),
('kam', 'MAT', 24, 19, 'Ĩndĩ woo nĩ wa ala aito na ala mekwongya mĩthenya ĩsu!'),
('kam', 'MAT', 24, 20, 'Na voyai kũkĩa kwenyu kũikethĩwe ĩvinda ya mbevo, kana mũthenya wa savato:'),
('kam', 'MAT', 24, 21, 'nũndũ ĩvinda yĩu kũkethĩwa thĩna mũnene, ũndũ ũtaaĩthĩwa kuma mwambĩlĩlyo wa nthĩ kũvika yu, o na kũikethĩwa ũngĩ nongi.'),
('kam', 'MAT', 24, 22, 'Na kethĩwa matukũ asu matyaakuvĩvw’a, kũivĩta mwĩĩ o na wĩva: ĩndĩ kwondũ wa ala anyuve matukũ asu makakuvĩvw’a.'),
('kam', 'MAT', 24, 23, 'Na ĩvinda yĩu ethĩwa mũndũ o na wĩva akakwĩa, Sisya, Klĩsto e vaa, kana, e vaya; mũtiketĩkĩle.'),
('kam', 'MAT', 24, 24, 'Nũndũ makookĩla Maklĩsto ma ũvũngũ, na athani ma ũvũngũ, na makoonan’ya syama nene na moseng’yo; nĩ kana masye, o na anyuve, ethĩwa ũu nũtonyeka.'),
('kam', 'MAT', 24, 25, 'Sisyai, nĩnamũtavya inyw’ĩ mbee.'),
('kam', 'MAT', 24, 26, 'Ethĩwa ĩndĩ makamwĩa, Sisyai, e weũnĩ; mũikaumaale: Sisyai, e nyũmbanĩ sya nthĩnĩ; mũiketĩkĩle.'),
('kam', 'MAT', 24, 27, 'Nũndũ o ũndũ ũtisi ũtisaa wumĩlonĩ wa syũa, nokyoneka kũvika ũthũĩlonĩ; o ta ũu kũkeethĩwa kũka kwa Mwana wa mũndũ.'),
('kam', 'MAT', 24, 28, 'O vala vethĩawa kimba, nĩvo ndei syũmbanĩaa.'),
('kam', 'MAT', 24, 29, 'Ĩndĩ ĩtina wa thĩna wa matukũ asu, kavinda o kau, syũa yĩkĩya kĩvindu, na mwei ũilea kumya kyeni kyaw’o, na ndata ikĩvalũka kuma ĩtunĩ, na mavinya na matu makĩthingithangw’a:'),
('kam', 'MAT', 24, 30, 'na ĩndĩ kũkyoneka wonan’yo wa Mwana wa mũndũ ĩtunĩ: na ĩndĩ mbaĩ syonthe sya nthĩ ikameta, na makoona Mwana wa mũndũ okĩte ĩũlũ wa mathweo ma ĩtu na vinya na ũtheu mũnene mũtisu.'),
('kam', 'MAT', 24, 31, 'Nake akatũma alaĩka make na wasya mũnene wa soo, nao makoomban’ya ala anyuve make kuma ngalĩ inya sya iseve, kuma itulunĩ sya matu kũvika itulunĩ ila ingĩ syamo.'),
('kam', 'MAT', 24, 32, 'Na ĩndĩ ĩmanyĩsyei ngelekan’yo ya mũkũyũ: mbonge syololoa, na syathongoosya wenze, nĩmwĩsĩ kana mũniino nũthengeee;'),
('kam', 'MAT', 24, 33, 'no ta ũu nenyu, mũkyona maũndũ asu onthe, manyai kana e vakuvĩ, o ta mĩomonĩ.'),
('kam', 'MAT', 24, 34, 'Nĩ w’o nĩngũmwĩa, Ũsyao ũũ ndũkavĩta maũndũ asu onthe mateanĩw’e.'),
('kam', 'MAT', 24, 35, 'Ĩtu na nthĩ nikavĩta, ĩndĩ ndeto syakwa itikavĩta.'),
('kam', 'MAT', 24, 36, 'Ĩndĩ mũthenya ũsu na saa ũsu vai ũmwe wĩsĩ, o na alaĩka ma ĩtunĩ, o na Mwana, ĩndĩ no Asa weka.'),
('kam', 'MAT', 24, 37, 'Ĩndĩ o ũndũ kwailyĩ matukũ ma Noa, now’o kũkethĩwa kũilyĩ Mwana wa mũndũ akyũka.'),
('kam', 'MAT', 24, 38, 'Nũndũ o tondũ matukũnĩ asu ala maĩ mbee wa kĩla kĩw’ũ kingĩ, andũ meethĩiwe makĩya na makĩnyw’a, makĩtwaana na makĩtwawa, kũvika mũthenya ũla Noa walikile ngalawanĩ,'),
('kam', 'MAT', 24, 39, 'na matyeesĩ mũvaka kĩla kĩw’ũ kingĩ kyooka, kyamatwaa onthe; now’o kũkethĩwa kũilyĩ Mwana wa mũndũ akyũka.'),
('kam', 'MAT', 24, 40, 'Ĩvinda yĩu aũme elĩ makeethĩwa mũũndanĩ; ũmwe nũkwoswa, na ũla ũngĩ nũkatiwa:'),
('kam', 'MAT', 24, 41, 'aka elĩ makethĩwa maithianĩa ĩvianĩ yĩmwe; ũmwe nũkoswa, na ũla ũngĩ nũkatiwa.'),
('kam', 'MAT', 24, 42, 'Syaĩĩsyai ĩndĩ; nũndũ mũtyĩsĩ mũthenya ũla Mwĩaĩi wenyu wĩũka.')
